async function keysByProperty(env, url) {
  const propId = url.searchParams.get('property_id');
  if (!propId) return json({ error: 'Missing property_id' }, 400);
  const keys = await fetchTab(env, 'Keys');
  return json(keys.filter(k => k.Property_ID === propId && k.Active !== 'FALSE'));
}

async function keysByUnit(env, url) {
  const unitId = url.searchParams.get('unit_id');
  const propId = url.searchParams.get('property_id') || '';
  if (!unitId) return json({ error: 'Missing unit_id' }, 400);
  const keys = await fetchTab(env, 'Keys');
  return json(keys.filter(k => {
    if (k.Active === 'FALSE') return false;
    if (k.Unit_ID === unitId) return true;
    if (propId && k.Property_ID === propId && !k.Unit_ID && k.Shared !== 'FALSE') return true;
    return false;
  }));
}

function getWOLockboxes(keys, woPropertyId, woUnitId, woUnitLabel, masterKeyInfo) {
  const result = keys
    .filter(k => {
      if (k.Active === 'FALSE') return false;
      if (!k.Property_ID || String(k.Property_ID) !== String(woPropertyId)) return false;
      const kUnit = (k.Unit_ID || k.Unit_Label || '').toString().trim();
      const isPropertyLevel = kUnit === '' || kUnit === '0';
      const unitMatches = woUnitId && (String(kUnit) === String(woUnitId) || (woUnitLabel && kUnit.toLowerCase() === woUnitLabel.toLowerCase()));
      if (isPropertyLevel && k.Shared !== 'FALSE') return true;
      if (unitMatches) return true;
      if (!woUnitId && isPropertyLevel) return true;
      return false;
    })
    .map(k => {
      const kUnit = (k.Unit_ID || k.Unit_Label || '').toString().trim();
      const isBuilding = kUnit === '' || kUnit === '0';
      // Canonical type vocabulary. Three different tools have written Key_Type over time —
      // the original flat legacy strings (Lockbox, Door Code, Electronic, ...), keys.html's
      // own flat set (Front Door, Gate Code, Garage Code, Mailbox, Utility, Rear Access,
      // Other), and the current Building-*/Unit-* hyphenated scheme used by index.html's
      // "Add Access Item" modal and the CSV importer's inferKeyType. TYPE_MAP is kept in
      // sync with index.html's renderKeysView TYPE_LABEL map (same key set) so a code never
      // silently falls through to a raw/garbled label — every scheme currently written
      // anywhere in the app resolves to a real, human label here.
      const TYPE_MAP = {
        // Current hyphenated scheme
        'Building-FrontDoorKey':'Front Door Key','Building-FrontDoorCode':'Electronic Code (Front Door)',
        'Building-Lockbox':'Lockbox','Building-Padlock':'Padlock','Building-GateCode':'Gate Code',
        'Building-CustomKey':'Key','Building-CustomLockbox':'Lockbox','Building-CustomCode':'Access Code',
        'Unit-Key':'Unit Key','Unit-DoorCode':'Electronic Code','Unit-Lockbox':'Lockbox',
        'Unit-MailboxKey':'Mailbox Key','Unit-Padlock':'Padlock',
        // Legacy / keys.html flat vocabulary
        'Lockbox':'Lockbox','lockbox':'Lockbox','Door Code':'Electronic Code','Door_Code':'Electronic Code',
        'Electronic':'Electronic Code','electronic':'Electronic Code',
        'Front Door':'Front Door Key','front door':'Front Door Key',
        'Unit Key':'Unit Key','unit key':'Unit Key','Key':'Key',
        'Gate Code':'Gate Code','Gate_Code':'Gate Code','Garage Code':'Garage Code',
        'Building Code':'Building Code','Building_Code':'Building Code',
        'Mailbox':'Mailbox Key','Utility':'Utility Key','Rear Access':'Rear Access',
        'Other':'Access',
      };
      const typeLabel = TYPE_MAP[k.Key_Type] || (k.Key_Type || 'Key');
      const unitDisplay = kUnit || woUnitLabel || '';
      // Contents (Aug 24, 2026): what a Lockbox key ACTUALLY holds — a lockbox that "applies
      // to" a multi-unit building may only carry a front-door key, or be a one-off setup for
      // a single job, not every key someone might assume. Appended onto the label itself
      // (not just a side field) so it can't be missed by whoever's reading the dispatch text.
      const contents = (k.Contents || '').trim();
      const label = (isBuilding ? `Building — ${typeLabel}` : `${unitDisplay ? 'Unit '+unitDisplay+' — ' : ''}${typeLabel}`) + (contents ? ` [${contents}]` : '');
      const code = k.Key_Code || k.Lockbox_Code || k.Code || k.code || '';
      const location = k.Lockbox_Location || k.Location || k.Notes || '';
      // Visibility (Keys.Visibility): '' / 'Auto' = this code follows the normal trade/WO
      // sharing toggle like every other code (unchanged behavior); 'Brett Only' = never hand
      // THIS ONE code to a vendor, no matter the trade default or per-WO toggle — the ONLY
      // way it still reaches a vendor-facing view is if the vendor actually assigned to that
      // WO IS Brett himself (Vendors.In_House), handled in enrichWO. This is what makes
      // sharing controllable per CODE, independent of its type (lock code, lockbox code,
      // electronic door code, gate code, ...) instead of one all-or-nothing WO-level switch.
      const visibility = (k.Visibility || '').trim();
      // Key_Identifier (Aug 24, 2026): the number stamped on the physical key/lock itself —
      // what a locksmith needs to cut a duplicate or order a replacement, and what lets a
      // FOUND key be looked up ("key #123 — whose is that?"). Deliberately separate from
      // `code` (the access code/combination someone dials or types) — conflating the two was
      // the exact ambiguity Brett flagged.
      return { id: k.ID||'', label, code, location, notes: k.Notes||'', type: k.Key_Type||'', scope: isBuilding ? 'building' : 'unit', visibility, contents, identifier: k.Key_Identifier||'' };
    })
    .filter(k => k.code || k.location)
    .sort((a, b) => a.scope === 'building' && b.scope !== 'building' ? -1 : 1);
  // Master Key (Aug 24, 2026, reworked same day per Brett's correction): a property being on
  // a master key system is a DIFFERENT fact from a vendor having a copy of it, and a building
  // can be on a master key AND have a lockbox AND have a per-unit tenant key all at once —
  // none of those cancel each other out, so this is additive to whatever the map() above
  // already found, never a replacement for it. The caller (enrichWO/assignVendor) resolves
  // `masterKeyInfo` ONLY when the person looking is the vendor actually assigned to this WO —
  // never for a tenant, never for an owner, never for some other vendor — and never hands us
  // the master key's admin Code (that's a locksmith-ordering reference, not something dispatched
  // over SMS/portal; a physical key doesn't have a "code" to give someone, they either have a
  // copy or they don't). `masterKeyInfo.hasIt` reflects THIS vendor's own Master_Key_Holders
  // status, so "you have a copy" vs. "you do not have a copy yet — check with Brett" is
  // accurate per-vendor, matching Brett's own example (told Eddy the building's on a master
  // key, but Eddy doesn't have his copy yet).
  if (masterKeyInfo) {
    result.unshift({
      id: 'mk',
      label: 'Master Key — ' + (masterKeyInfo.name || 'Unnamed'),
      code: masterKeyInfo.hasIt ? 'You have a copy of this key.' : 'You do NOT currently have a copy — check with Brett.',
      location: masterKeyInfo.note || '',
      notes: masterKeyInfo.note || '',
      type: 'Master Key',
      scope: 'building',
      visibility: '',
      contents: '',
      identifier: '',
    });
  }
  return result;
}

async function updateKeyWithHistory(env, body) {
  const keys = await fetchTab(env, 'Keys');
  const existing = keys.find(k => k.ID === String(body.id));
  if (!existing) return json({ error: 'Key not found' }, 404);
  const now = new Date().toISOString().split('T')[0];
  const codeChanged = (body.fields.Key_Code !== undefined && body.fields.Key_Code !== existing.Key_Code) || (body.fields.Lockbox_Code !== undefined && body.fields.Lockbox_Code !== existing.Lockbox_Code);
  if (codeChanged) {
    const histData = await sheetsRequest(env, 'GET', `/values/Keys_History`);
    const histRows = histData.values || [];
    if (histRows.length) {
      const hh = histRows[0];
      const newRow = hh.map(h => ({ ID: String(nextSafeId(histRows)), Key_ID: String(body.id), Property_ID: existing.Property_ID||'', Unit_ID: existing.Unit_ID||'', Key_Type: existing.Key_Type||'', Old_Code: existing.Key_Code || existing.Lockbox_Code||'', New_Code: body.fields.Key_Code || body.fields.Lockbox_Code||'', Changed_Date: now, Changed_By: body.changed_by||'admin', Reason: body.reason||'', Notes: body.notes||'' }[h] ?? ''));
      await sheetsRequest(env, 'POST', `/values/Keys_History:append?valueInputOption=RAW`, { values: [newRow] });
    }
  }
  // Keys was never given an ensureColumns call anywhere — updateRow maps strictly by
  // existing header name, so writing Visibility (new, per-code sharing control) or
  // Last_Changed on a sheet that's never had them silently drops the write with no error.
  // Grow the header row first; no-ops instantly once the columns exist.
  await ensureColumns(env, 'Keys', ['Visibility', 'Last_Changed', 'Contents', 'Key_Identifier']);
  return await updateRow(env, 'Keys', body.id, { ...body.fields, Last_Changed: now });
}

// ── ATTACHMENTS ──────────────────────────────────────────────

// GET /attachments?wo_id= | ?invoice_id= — per-record scope (Oct 14 2026, queue #150).
// Before this, ANY signed-in tenant/owner/vendor session token could list ANY job's attachments
// (cross-account leak of photos, Drive links and receipt file names). Now:
//   - Admin secret / internal tokens (callerRole null): unchanged, full access.
//   - A role session may only see attachments on a WO it could already see in its own portal list
//     (attachmentScopeAllows below mirrors vendorWorkorders / tenantWorkorders / ownerWorkorders).
//   - Tenants never receive receipt/bill/invoice rows (vendor cost docs) even on their own jobs.
//   - Asking for a WO the session may not see is a generic 404 (same for "missing" and "not yours",
//     like /owner-file/view) and is logged to Ops_Telemetry as a failure so a probe or a real
//     regression is visible. A telemetry failure propagates (loud 500) instead of being swallowed.
//   - Unknown roles fail closed.
const ATTACHMENT_COST_DOC_TYPES = ['receipt', 'bill', 'invoice'];

// Shared with tenantWorkorders so "what a tenant can see" has ONE definition. Status/include_closed
// filtering stays in the list endpoint (a tenant may view photos on a closed job they can see).
function tenantCanSeeWO(tenant, w) {
  if (!tenant || !w) return false;
  if (w.Voided === 'TRUE') return false;
  if (w.Tenant_Visible === 'FALSE') return false;
  if (w.Property_ID !== tenant.Property_ID) return false;
  if (isBackgroundWO(tenant, w)) return false;
  if (tenant.Unit_ID) return w.Unit_ID === tenant.Unit_ID || w.Tenant_ID === tenant.ID;
  return true;
}

function attachmentScopeAllows(role, sessionId, wo, tenants, properties) {
  if (!wo || !role || !sessionId) return false;
  const sid = String(sessionId);
  if (role === 'vendor') {
    // Assigned vendor only. A voided WO is still theirs: additional-work drafts are stored as voided
    // children and the vendor attaches photos to them before submitting.
    return String(wo.Vendor_ID || '') !== '' && String(wo.Vendor_ID) === sid;
  }
  if (role === 'tenant') {
    const tenant = (tenants || []).find(t => t.ID === sid && t.Active !== 'FALSE');
    return tenantCanSeeWO(tenant, wo);
  }
  if (role === 'owner') {
    const prop = (properties || []).find(p => p.ID === wo.Property_ID);
    if (!prop || String(prop.Owner_ID || '') !== sid) return false;
    return wo.Voided !== 'TRUE' && String(wo.Type || '') !== 'addon' && !isHiddenBidCopy(wo);
  }
  return false;
}

// ── SESSION IDENTITY BINDING (Oct 14 2026, Brett: "fix them") ──────────────────────────────────
// Before this, every tenant/owner/vendor endpoint trusted the id the PAGE sent (?tenant_id=,
// ?owner_id=, ?vendor_id=, body.vendor_id ...) instead of the id baked into the signed session
// token, so any signed-in account could read another account's job list, bills, receipts or
// notification settings by changing one number in the URL. One central rule, enforced in the
// router for every role session (admin secret and internal tokens never reach it):
//   - The id param for the caller's role (vendor_id / owner_id / tenant_id), when supplied in the
//     query string OR the POST body, must equal the verified session id. A mismatch is a 403 and a
//     failed Ops_Telemetry row (`session_identity_mismatch`) - never silently "corrected".
//   - On GET the session id is then FORCED into the query, so a request that simply omits the param
//     (e.g. /vendor-bills?status=submitted, which used to return every vendor's bills) is scoped to
//     the caller instead of falling through to "everything".
//   - GETs that name a work order (wo_id) must be for a job this session may see (the same
//     attachmentScopeAllows used by /attachments - one definition). Generic 404 otherwise.
// POST bodies are validated when the id is present; per-record write checks (e.g. /status on a WO id)
// are a separate layer and are listed in BACKLOG.
const SESSION_IDENTITY_PARAM = { vendor: 'vendor_id', owner: 'owner_id', tenant: 'tenant_id' };
const WO_KEYED_READ_PATHS = ['/estimates', '/time-entries', '/receipts', '/vendor-bills', '/nearby-wos', '/wo-audit'];

function sessionIdentityMismatch(role, sessionId, url, body) {
  if (!role) return null;                                   // admin secret / internal token
  const param = SESSION_IDENTITY_PARAM[role];
  if (!param) return { param: '(role)', supplied: String(role) };   // unknown role fails closed
  const sid = String(sessionId || '');
  const supplied = [];
  if (url && url.searchParams) supplied.push(url.searchParams.get(param));
  if (body && typeof body === 'object') supplied.push(body[param]);
  for (const v of supplied) {
    if (v === null || v === undefined || v === '') continue;
    if (!sid || String(v) !== sid) return { param, supplied: String(v).slice(0, 60) };
  }
  return null;
}

async function denySessionIdentity(env, path, role, sessionId, mm) {
  await logTelemetry(env, { Source: 'worker', Job_Type: 'session_identity_mismatch', Skill_Or_Endpoint: path, Success: 'FALSE', Notes: `role=${role} session=${sessionId} sent ${mm.param}=${mm.supplied}` });
  return json({ error: 'Forbidden' }, 403);
}

// Returns a Response when the session may NOT read this wo_id, otherwise null.
async function woKeyedReadDenied(env, path, url, role, sessionId) {
  const woId = url.searchParams.get('wo_id') || '';
  if (!woId) return null;                                   // handlers that need a wo_id 400 on their own
  const [workorders, tenants, properties] = await fetchTabs(env, ['Work_Orders', 'Tenants', 'Properties']);
  if (attachmentScopeAllows(role, sessionId, findWO(workorders, woId), tenants, properties)) return null;
  await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_scope_denied', Skill_Or_Endpoint: path, Success: 'FALSE', Notes: `role=${role} session=${sessionId} wo=${woId}` });
  return json({ error: 'Not found' }, 404);
}

async function getAttachments(env, url, callerRole, callerSessionId) {
  const woId = url.searchParams.get('wo_id') || '';
  const invoiceId = url.searchParams.get('invoice_id') || '';
  if (!woId && !invoiceId) return json({ error: 'Missing wo_id or invoice_id' }, 400);
  const attachments = await fetchTab(env, 'Attachments');
  const rows = attachments.filter(a => { if (a.Active === 'FALSE') return false; if (woId && a.WO_ID === woId) return true; if (invoiceId && a.Invoice_ID === invoiceId) return true; return false; });
  if (!callerRole) return json(rows);   // admin secret / internal token: full access, as before
  const [workorders, tenants, properties] = await fetchTabs(env, ['Work_Orders', 'Tenants', 'Properties']);
  const allowedWO = new Map();
  const woAllowed = (id) => {
    if (!id) return false;
    if (!allowedWO.has(id)) allowedWO.set(id, attachmentScopeAllows(callerRole, callerSessionId, findWO(workorders, id), tenants, properties));
    return allowedWO.get(id);
  };
  if (woId && !woAllowed(woId)) {
    await logTelemetry(env, { Source: 'worker', Job_Type: 'attachments_scope_denied', Skill_Or_Endpoint: '/attachments', Success: 'FALSE', Notes: `role=${callerRole} session=${callerSessionId} wo=${woId}` });
    return json({ error: 'Not found' }, 404);
  }
  let visible = rows.filter(a => woAllowed(a.WO_ID));
  if (callerRole === 'tenant') visible = visible.filter(a => !ATTACHMENT_COST_DOC_TYPES.includes(String(a.File_Type || '').toLowerCase()));
  return json(visible);
}

// Stream the bytes of a receipt/bill/invoice file (the INTERNAL_TYPES that are deliberately
// NEVER made anyone-with-link shareable — FEATURE_LOG rule 13, to keep vendor cost data out of
// customer-facing links) back through the Worker's own Drive access, so the vendor who uploaded
// it can actually view it. Root cause of "blank/black page when a vendor taps their receipt":
// the portal's photo gallery/lightbox (vendor.html rcRenderLightbox / the plain <a> fallback for
// PDFs) was pointing straight at drive.google.com — which 404s/blanks for a file that is
// correctly kept private. This does NOT change the sharing policy (the file is still never
// public); it only lets an already-authenticated vendor session read the bytes of a file that's
// logged against a WO_ID they have legitimate access to, same trust boundary as GET /attachments.
async function viewInternalFile(env, url, callerRole, callerSessionId) {
  const woId = url.searchParams.get('wo_id') || '';
  const fileId = url.searchParams.get('file_id') || '';
  if (!woId || !fileId) return json({ error: 'wo_id and file_id required' }, 400);
  try {
    const attachments = await fetchTab(env, 'Attachments');
    const row = attachments.find(a => a.Active !== 'FALSE' && a.WO_ID === woId && a.Drive_File_ID === fileId);
    if (!row) return json({ error: 'File not found for this work order' }, 404);
    // Oct 14 2026: any signed-in session could stream any job's receipt/bill/invoice bytes by
    // guessing wo_id + file_id. A role session now needs the same access to the WO as /attachments
    // (the assigned vendor; a tenant/owner can never reach cost documents through this route since
    // it is not in their scope list, and attachmentScopeAllows fails closed on anything else).
    // Admin secret / internal token (callerRole null) is unchanged. Same generic 404 as "no such file".
    if (callerRole) {
      const [wos, tenants, properties] = await fetchTabs(env, ['Work_Orders', 'Tenants', 'Properties']);
      if (!attachmentScopeAllows(callerRole, callerSessionId, findWO(wos, woId), tenants, properties)) {
        await logTelemetry(env, { Source: 'worker', Job_Type: 'vendor_file_scope_denied', Skill_Or_Endpoint: '/vendor-file/view', Success: 'FALSE', Notes: `role=${callerRole} session=${callerSessionId} wo=${woId} file=${fileId}` });
        return json({ error: 'File not found for this work order' }, 404);
      }
    }
    const token = await getAccessToken(env);
    const driveRes = await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!driveRes.ok || !driveRes.body) return json({ error: 'Could not load file from Drive' }, 502);
    const mime = row.Mime_Type || driveRes.headers.get('content-type') || 'application/octet-stream';
    const safeName = (row.File_Name || 'file').replace(/[^\w.\- ]/g, '_');
    return new Response(driveRes.body, {
      status: 200,
      headers: { ...CORS, 'Content-Type': mime, 'Cache-Control': 'private, no-store', 'Content-Disposition': `inline; filename="${safeName}"` },
    });
  } catch (e) {
    return await fileViewError(env, '/vendor-file/view', e, callerRole, callerSessionId);
  }
}

// Shared by the two file streamers (Oct 14 2026): a role session never sees raw Drive/Sheets error
// text, but the failure is always logged with a ref (a telemetry failure propagates to the router's
// own 500 handler, so it is never swallowed). Admin/internal callers (callerRole null) keep the detail.
async function fileViewError(env, path, e, callerRole, callerSessionId) {
  const ref = crypto.randomUUID().slice(0, 8);
  await logTelemetry(env, { Source: 'worker', Job_Type: 'file_view_error', Skill_Or_Endpoint: path, Success: 'FALSE', Notes: `ref=${ref} role=${callerRole || 'none'} session=${callerSessionId || ''} ${String((e && e.message) || e)}`.slice(0, 480) });
  return json({ error: callerRole ? 'Could not load this file. Please try again; if it keeps happening, tell Ridge Co and quote ref ' + ref + '.' : ((e && e.message) || String(e)), ref }, 500);
}

// GET /owner-file/view?wo_id=&file_id=&t= — owner-scoped receipt viewer (rule 177, Sep 16 2026).
// Brett: receipts (materials proof-of-purchase photos) should be visible to the property owner;
// vendor invoices/bills should not — the second half was already true (never Drive-shared, no
// owner UI slot even renders them), but receipts were stuck in the same never-shared bucket, so
// owner.html could show a receipt's filename with a link that always blanked out. This is the
// owner-facing twin of viewInternalFile above, with two checks that function does not need
// because an owner session is a different trust level than an admin/vendor one:
//   1. Hard content-type gate — refuses anything whose Attachments.File_Type isn't exactly
//      'receipt', so a bill/invoice can never be served through this path no matter what
//      file_id is guessed.
//   2. Ownership check — an 'owner' session (callerRole/callerSessionId, from the verified PIN
//      session token) may only view a receipt on a WO whose property actually belongs to them
//      (Work_Orders.Property_ID -> Properties.Owner_ID). The admin secret (callerRole stays
//      null at the auth gate) skips this, same as every other endpoint's "admin = full access."
// Every rejection path returns the same generic 404 — missing file, wrong type, and wrong owner
// all look identical from the outside, so a snooping session can't use the response shape to
// tell those cases apart or fish for what exists.
async function viewOwnerReceiptFile(env, url, callerRole, callerSessionId) {
  const woId = url.searchParams.get('wo_id') || '';
  const fileId = url.searchParams.get('file_id') || '';
  if (!woId || !fileId) return json({ error: 'wo_id and file_id required' }, 400);
  try {
    const attachments = await fetchTab(env, 'Attachments');
    const row = attachments.find(a => a.Active !== 'FALSE' && a.WO_ID === woId && a.Drive_File_ID === fileId);
    if (!row || (row.File_Type || '').toLowerCase() !== 'receipt') return json({ error: 'File not found for this work order' }, 404);
    if (callerRole === 'owner') {
      const [wos, properties] = await fetchTabs(env, ['Work_Orders', 'Properties']);
      const wo = findWO(wos, woId);
      const prop = wo ? properties.find(p => p.ID === wo.Property_ID) : null;
      if (!prop || String(prop.Owner_ID || '') !== String(callerSessionId || '')) return json({ error: 'File not found for this work order' }, 404);
    }
    const token = await getAccessToken(env);
    const driveRes = await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!driveRes.ok || !driveRes.body) return json({ error: 'Could not load file from Drive' }, 502);
    const mime = row.Mime_Type || driveRes.headers.get('content-type') || 'application/octet-stream';
    const safeName = (row.File_Name || 'file').replace(/[^\w.\- ]/g, '_');
    return new Response(driveRes.body, {
      status: 200,
      headers: { ...CORS, 'Content-Type': mime, 'Cache-Control': 'private, no-store', 'Content-Disposition': `inline; filename="${safeName}"` },
    });
  } catch (e) {
    return await fileViewError(env, '/owner-file/view', e, callerRole, callerSessionId);
  }
}

// GET /selftest/vendor-file-view — live canary for the vendor-file-view proxy (rule 142
// follow-up, Sept 2 2026). viewInternalFile's real auth path is a vendor's PIN-issued session
// token as ?t=, which CI/a script can't obtain without live vendor credentials — this calls
// the exact same function (same Attachments-row lookup, same Drive alt=media fetch, same
// trust boundary as GET /attachments) so a pass here is proof the actual byte-stream works
// end to end against a real logged Attachment row, not a guess. Reports JSON instead of
// streaming bytes so scripts/selftest-vendor-file-view.mjs can assert on it directly.
// Gated by its own SELFTEST_TOKEN, never WORKER_SECRET — same discipline as
// selfTestInvoiceExtract; CLAUDE.md's standing note is not to widen that shared key.
// Read-only, no writes, no PII beyond a file name already visible to whoever holds WO_ID +
// file_id (same as viewInternalFile itself).
async function selfTestVendorFileView(env, url) {
  const want = env.SELFTEST_TOKEN;
  if (!want) return json({ error: 'SELFTEST_TOKEN not configured on this Worker', configured: false }, 503);
  const got = url.searchParams.get('token') || '';
  let diff = got.length ^ want.length;
  for (let i = 0; i < got.length && i < want.length; i++) diff |= got.charCodeAt(i) ^ want.charCodeAt(i);
  if (diff !== 0) return json({ error: 'Unauthorized' }, 401);
  const t0 = Date.now();
  const res = await viewInternalFile(env, url);
  const buf = await res.arrayBuffer();
  const bytes = new Uint8Array(buf);
  const head = Array.from(bytes.slice(0, 8)).map(b => b.toString(16).padStart(2, '0')).join('');
  let errMsg = null;
  if (!res.ok) { try { errMsg = JSON.parse(new TextDecoder().decode(bytes)).error; } catch (e) { errMsg = 'non-JSON error body'; } }
  return json({
    success: res.ok && bytes.length > 0,
    status: res.status,
    content_type: res.headers.get('Content-Type') || '',
    byte_length: bytes.length,
    first_bytes_hex: head,
    error: errMsg,
    ms: Date.now() - t0,
  });
}

async function listAttachments(env, url) {
  const woId = url.searchParams.get('wo_id') || '';
  const rows = await fetchTab(env, 'Attachments');
  let items = rows.filter(r => r.Active !== 'FALSE');
  if (woId) items = items.filter(r => r.WO_ID === woId);
  return json(items);
}

// ── PHOTO UPLOAD ─────────────────────────────────────────────

async function handlePhotoUploadClean(env, request) {
  const step = { current: 'init' };
  try {
    step.current = 'parse_form';
    const formData = await request.formData();
    const file     = formData.get('file');
    const woId     = (formData.get('wo_id')    || '').trim();
    const propAddr = (formData.get('property') || 'Unknown Property').trim() || 'Unknown Property';
    const fileType = (formData.get('file_type')|| 'photo').trim();
    if (!file) return json({ error: 'No file provided' }, 400);
    const filename = file.name || `${fileType}_${Date.now()}`;
    const mimeType = file.type || 'application/octet-stream';
    step.current = 'get_token';
    const propsRoot = env.DRIVE_PROPERTIES_ROOT;
    if (!propsRoot) return json({ error: 'DRIVE_PROPERTIES_ROOT env var not set' }, 500);
    const token = await getAccessToken(env);
    if (!token) return json({ error: 'Failed to get Google access token' }, 500);
    step.current = 'find_prop_folder';
    const propFolder = await findOrCreateFolder(token, propAddr, propsRoot, propsRoot);
    if (!propFolder || !propFolder.id) return json({ error: `Could not find/create property folder "${propAddr}"`, step: step.current }, 500);
    step.current = 'find_wo_folder';
    const woLabel  = woId || `upload_${Date.now()}`;
    // Vendor cost docs (receipts/bills/invoices) go to a NON-shared internal folder — never the
    // customer-facing WO folder that gets shared on the invoice. Job photos stay in the WO folder.
    const INTERNAL_TYPES = ['receipt','bill','invoice'];
    const isInternal = INTERNAL_TYPES.includes(fileType.toLowerCase());
    let woFolder;
    if (isInternal) {
      const internalRoot = await findOrCreateFolder(token, '_Internal — Vendor Bills', propFolder.id);
      if (!internalRoot || !internalRoot.id) return json({ error: 'Could not find/create internal vendor-bills folder', step: step.current }, 500);
      woFolder = await findOrCreateFolder(token, woLabel, internalRoot.id);
    } else {
      woFolder = await findOrCreateFolder(token, woLabel, propFolder.id);
    }
    if (!woFolder || !woFolder.id) return json({ error: `Could not find/create WO folder "${woLabel}"`, step: step.current }, 500);
    step.current = 'upload_file';
    const arrayBuffer = await file.arrayBuffer();
    const uploaded = await uploadFileToDrive(token, arrayBuffer, filename, mimeType, woFolder.id, propsRoot);
    if (!uploaded || !uploaded.id) return json({ error: 'Drive upload failed', step: step.current }, 500);
    // Make customer/job-facing media (before/after/report/photo/video) anyone-with-link readable so
    // vendors/tenants/owners can open it in the portal without a Google login. Internal cost docs
    // (receipt/bill/invoice → _Internal — Vendor Bills) are NEVER shared (FEATURE_LOG rule 13).
    if (!isInternal) {
      try {
        const shared = await driveShareAnyone(token, uploaded.id);
        if (!shared) { try { await logTelemetry(env, { Source: 'worker', Job_Type: 'drive_share_failed', Skill_Or_Endpoint: 'upload-photo', Success: 'FALSE', Notes: `wo=${woId} file=${filename} id=${uploaded.id}` }); } catch (_) {} }
      } catch (_) { /* still non-fatal to the upload itself */ }
    }
    step.current = 'log_attachments';
    try {
      await addRow(env, 'Attachments', { WO_ID: woId, File_Name: filename, File_Type: fileType, Drive_File_ID: uploaded.id, Drive_URL: uploaded.webViewLink || uploaded.id, Mime_Type: mimeType, Created_Date: new Date().toISOString().split('T')[0], Active: 'TRUE' });
    } catch(sheetErr) { /* non-fatal */ }
    step.current = 'update_wo_fields';
    try {
      // Only the customer-facing WO folder becomes the WO's shared Drive_Folder (photo link).
      if (!isInternal && woFolder.webViewLink) {
        await updateWOField(env, woId, 'Drive_Folder_URL', woFolder.webViewLink);
        await updateWOField(env, woId, 'Drive_Folder_ID',  woFolder.id);
      }
    } catch(woErr) { /* non-fatal */ }
    return json({ success: true, fileId: uploaded.id, url: uploaded.webViewLink || `https://drive.google.com/file/d/${uploaded.id}/view`, name: filename, woFolderUrl: woFolder.webViewLink || '' });
  } catch(e) {
    return json({ error: e.message || 'Upload failed', step: step.current, stack: e.stack?.substring(0,300) }, 500);
  }
}

// ── WO HELPERS ───────────────────────────────────────────────

// Is this tenant still living there? Used by every path that decides whether to hand a
// tenant's contact details to anyone. One predicate on purpose — three near-copies of this
// check in three files is how one of them ends up not being applied.
function isTenantCurrent(t) {
  if (!t || !t.ID) return false;
  if (String(t.Active || '').toUpperCase() === 'FALSE') return false;
  if (t.Move_Out_Date) {
    // Oct 14 2026 (owner tenant roster): a plain YYYY-MM-DD move-out date means "lives there through the END of
    // that day, Eastern". The old check read 23:59:59 in the Worker's own clock (UTC), so a tenant leaving on the
    // 14th counted as gone from 7:59pm ET on the 14th. Anything that is not a plain date keeps the old reading.
    const mo = String(t.Move_Out_Date).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(mo)) {
      if (new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' }) > mo) return false;
    } else {
      const out = new Date(t.Move_Out_Date + 'T23:59:59');
      if (!isNaN(out) && out < new Date()) return false;
    }
  }
  return true;
}

// Unit_Label formatting (Sep 23 2026): real Unit_Label data is a genuine mix — most read like
// full labels already ("Apt 3R", "Apt B") but a real subset (931 Saint Paul St, 1305 N Calvert
// St) are bare identifiers ("3R", "1F", "2nd") with no "Apt"/"Unit"/word prefix at all. Blindly
// prepending "Unit " onto every label double-prefixed the already-full ones ("...St Unit Apt
// 3R"); blindly stripping it would have read badly on the bare ones ("...St 3R" reads fine
// actually, but a bare ordinal like "2nd" reads oddly with no word at all — "Unit 2nd" is the
// clearer text). This keeps a bare label prefixed with "Unit " and leaves an already-worded
// label (Apt/Unit/Suite/#) exactly as-is. Use this everywhere a unit label is appended onto an
// address instead of raw string concatenation.
function formatUnitLabel(label) {
  const l = String(label || '').trim();
  if (!l) return '';
  return (/^(apt|unit|suite|ste)\b/i.test(l) || l[0] === '#') ? l : `Unit ${l}`;
}

// The tenant to hand a VENDOR. Deliberately stricter than "whoever the work order names":
// a vendor going to an address today needs the person living there today. A moved-out
// tenant's name and phone must not travel out to a third party — they no longer live
// there, and it's their personal contact detail being passed to a stranger.
// Whole-property (no-Unit) work orders never get a Tenant_ID filled in at creation — there's
// no unit to carry one. Mirrors the same fallback enrichWO already uses for the WO-detail
// display: an active tenant at this property with no Unit_ID of their own IS that property's
// tenant. Found live (Sep 2026): this fallback was missing here, so tenant SMS silently never
// fired for any whole-property WO — Tenant_SMS_Sent stayed FALSE even on a successful assign.
function currentTenantForDispatch(tenants, unit, wo) {
  const id = (unit && unit.Tenant_ID) || (wo && wo.Tenant_ID) || '';
  let t = id ? (tenants || []).find(x => String(x.ID) === String(id)) : null;
  if (!t && wo && wo.Property_ID && !wo.Unit_ID) {
    t = (tenants || []).find(x => x.Property_ID === wo.Property_ID && !x.Unit_ID && x.Active !== 'FALSE');
  }
  return isTenantCurrent(t) ? t : null;
}

// CAP-036 #21 fix (Sep 24 2026) — real case: 115 W 29th St Apt 2 (Julie Feldman + Alanna
// McLaughlin) and Apt 3 (Lance Serafica + Emily Marquez) each have TWO active tenants sharing
// one unit, and only one of them was ever getting work-order SMS (reassignment/completion/
// scheduled/etc). Root cause was NOT a bad tenant/unit link — both tenants' own Tenants rows
// correctly carry the same Unit_ID/Property_ID. The bug was that every tenant-notification call
// site resolved "the" tenant via currentTenantForDispatch, which follows Units.Tenant_ID — a
// single FK column that can only ever name one occupant — instead of asking the Tenants table
// for every active tenant actually linked to that unit. Confirmed systemic: at least 8 other
// live multi-tenant units show the same one-tenant-only pointer (153 W Lanvale Apt 1, 1214 N
// Calvert Apt 2 & Apt 3, 3014 N Calvert Apt B, 928 N Calvert Apt 2F, 151 W Lanvale Apt 2, plus
// the Apt 3/20 E Eager test row) — none of those needed a data fix either.
//
// tenantsForDispatch returns EVERY currently-active tenant tied to this WO's unit (or, for a
// whole-property WO with no Unit_ID, every active no-Unit tenant at that property — same
// fallback currentTenantForDispatch already used). This is deliberately still scoped to ONE
// unit/property's own tenants, never a building-wide broadcast — that's a separate, already-
// decided default-off case. Callers that need to actually SEND something still run each
// returned tenant through isTenantNotifiable (phone present, not background-WO) individually,
// exactly as they did for the single tenant before this fix.
function tenantsForDispatch(tenants, unit, wo) {
  const list = tenants || [];
  let matches = [];
  if (wo && wo.Unit_ID) {
    matches = list.filter(t => t.Unit_ID === wo.Unit_ID && t.Active !== 'FALSE');
  } else if (wo && wo.Property_ID && !wo.Unit_ID) {
    matches = list.filter(t => t.Property_ID === wo.Property_ID && !t.Unit_ID && t.Active !== 'FALSE');
  } else if (wo && wo.Tenant_ID) {
    const t = list.find(x => String(x.ID) === String(wo.Tenant_ID));
    if (t) matches = [t];
  }
  return matches.filter(isTenantCurrent);
}

// A WO opened before the tenant's Move_In_Date is "background" to them — work tied to
// whoever lived there before (e.g. a turnover-cleaning WO opened while the unit was being
// prepped for their move-in). Shared by isTenantNotifiable (SMS) and tenantWorkorders (portal
// list) so a tenant is neither texted about nor shown a WO that predates them. B-fix Aug 17:
// this check previously lived only in isTenantNotifiable, so a tenant wouldn't be TEXTED about
// a pre-move-in WO but could still SEE it by opening the tenant portal — the SMS gate and the
// portal-visibility gate had quietly drifted apart. Real case: tenant "Matt" at 151 W Lanvale
// St Apt 2 could see a turnover-cleaning WO opened right around his move-in date.
function isBackgroundWO(tenant, wo) {
  if (!tenant || !tenant.Move_In_Date || !wo || !wo.Created_Date) return false;
  // Oct 14 2026 (owner tenant roster): compare Eastern CALENDAR DAYS. A plain date parses as midnight UTC, which is
  // 8pm ET the evening before, so a work order created at 9pm ET on Sep 30 (01:00 UTC Oct 1) used to count as
  // created AFTER an Oct 1 move-in and was shown / texted to the new tenant. Rule: a WO created on or after the
  // move-in day (ET) belongs to the tenant; anything created on an earlier ET day is background.
  const mi = String(tenant.Move_In_Date).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(mi)) {
    const cr = String(wo.Created_Date).trim();
    const crDay = /^\d{4}-\d{2}-\d{2}$/.test(cr) ? cr : (isNaN(new Date(cr)) ? '' : new Date(cr).toLocaleDateString('en-CA', { timeZone: 'America/New_York' }));
    if (crDay) return crDay < mi;
  }
  return new Date(tenant.Move_In_Date) > new Date(wo.Created_Date);
}

function isTenantNotifiable(tenant, wo) {
  if (!tenant || !tenant.Phone) return false;
  // Delegates the "do they still live there" question rather than restating it. Three
  // near-copies of this check is why one of them ended up not being applied.
  if (!isTenantCurrent(tenant)) return false;
  if (isBackgroundWO(tenant, wo)) return false;
  return true;
}

function roundUpTo15(minutes) { if (minutes <= 0) return 15; return Math.ceil(minutes / 15) * 15; }

// Ids arrive as an array from the Hub and as a comma string from anything hand-rolled.
// Accept both rather than silently doing nothing to one of them.
function parseIdList(v) {
  const arr = Array.isArray(v) ? v : String(v == null ? '' : v).split(',');
  const out = [];
  arr.map(x => String(x == null ? '' : x).trim()).forEach(x => { if (x && out.indexOf(x) < 0) out.push(x); });
  return out;
}

// Stamp the bill onto the hours it was built from. Bill_ID is not an original Time_Entries
// column and addRow/updateRow map by header — writing it without this reports success and
// stores nothing (rule 37).
async function linkTimeEntriesToBill(env, entryIds, billId, woId) {
  const ids = parseIdList(entryIds);
  if (!ids.length || !billId) return 0;
  await ensureColumns(env, 'Time_Entries', ['Bill_ID']);
  const rows = await fetchTab(env, 'Time_Entries');
  let linked = 0;
  for (const id of ids) {
    const row = rows.find(r => String(r.ID) === String(id));
    // Only hours on THIS job, and never re-point an entry that is already inside a bill —
    // that would move money from one invoice to another without either one changing.
    if (!row) continue;
    if (woId && String(row.WO_ID) !== String(woId)) continue;
    if (String(row.Bill_ID || '').trim()) continue;
    await updateRow(env, 'Time_Entries', id, { Bill_ID: String(billId) });
    linked++;
  }
  return linked;
}

async function listTimeEntries(env, url) {
  const woId = url.searchParams.get('wo_id') || '', vendorId = url.searchParams.get('vendor_id') || '';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  try {
    const rows = await fetchTab(env, 'Time_Entries');
    let results = rows.filter(r => r.WO_ID === woId && r.Active !== 'FALSE');
    if (vendorId) results = results.filter(r => r.Role === 'vendor' && r.Entered_By_ID === vendorId);

    // Hours rolled into a vendor bill are already being charged as that bill's labour.
    // Say so, so the billing panel doesn't add them a second time on top. A VOIDED bill
    // releases them again — otherwise voiding a mistake would strand the time forever.
    let live = null;
    try {
      const bills = await fetchTab(env, 'Vendor_Bills');
      live = new Set(bills.filter(b => b.Active !== 'FALSE').map(b => String(b.ID)));
    } catch (e) { live = null; }
    results = results.map(r => {
      const billId = String(r.Bill_ID || '').trim();
      return Object.assign({}, r, {
        // null (couldn't read the bills) is deliberately different from '' (read them, not
        // billed) — the panel must not treat "don't know" as "safe to charge again".
        Billed_Bill_ID: live === null ? null : (billId && live.has(billId) ? billId : ''),
      });
    });

    return json(results.sort((a, b) => new Date(a.Created_Date) - new Date(b.Created_Date)));
  } catch(e) { return json([]); }
}

// GET /receipts-billed?wo_id=  — receipt ids already committed to an approved invoice on
// this job. A receipt can be charged to the owner exactly once, and two vendors' bills on
// one job means two invoices that would otherwise each pick up the same materials. Panel
// heuristics only work while both panels happen to be open; this survives reloads.
async function listBilledReceipts(env, url) {
  const woId = url.searchParams.get('wo_id') || '';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  try {
    const irs = await fetchTab(env, 'Invoice_Review');
    const billed = {};
    irs.filter(r => r.Active !== 'FALSE' && String(r.WO_ID) === String(woId)).forEach(r => {
      String(r.Own_Material_IDs || '').split(',').map(x => x.trim()).filter(Boolean)
        .forEach(id => { billed[id] = String(r.ID); });
    });
    // Signed scope proposal WITH Ridge Co materials priced in (Sep 22 2026): the owner already
    // pays for those materials through the proposal's payment milestones — so every receipt on
    // this job counts as billed. index.html's invoice picker already renders any id in
    // `billed` as disabled + "already invoiced", so no picker change is needed. A read failure
    // here throws into the catch below → ok:false → the picker ticks nothing by default.
    const covered = await scopeCoveringSignatureForWO(env, woId);
    if (covered) {
      const rcs = await fetchTab(env, 'Receipts');
      rcs.filter(rc => String(rc.WO_ID) === String(woId) && rc.Active !== 'FALSE').forEach(rc => {
        const id = String(rc.ID);
        if (!billed[id]) billed[id] = 'signed proposal (Scope #' + covered.scope_id + ')';
      });
    }
    return json({ ok: true, wo_id: woId, billed, scope_covered: covered || null });
  } catch (e) { return json({ ok: false, error: e.message, billed: {} }); }
}

async function listReceipts(env, url) {
  const woId = url.searchParams.get('wo_id') || '', vendorId = url.searchParams.get('vendor_id') || '';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  try {
    const rows = await fetchTab(env, 'Receipts');
    let results = rows.filter(r => r.WO_ID === woId && r.Active !== 'FALSE');
    if (vendorId) results = results.filter(r => r.Role === 'vendor' && r.Added_By_ID === vendorId);
    return json(results.sort((a,b) => new Date(a.Created_Date)-new Date(b.Created_Date)));
  } catch(e) { return json([]); }
}

// Brett, Sep 2026: a receipt no longer has to be tied to a work order. A Ridge Co business
// expense (no customer, sometimes no property either — e.g. office supplies) or a receipt
// against one of Brett's own properties (e.g. Milam Ridge / 1864 Kerns School Rd, which has
// no owner to bill) both need to be recorded somewhere. wo_id stays the common case and is
// still validated by the caller (receiptReconConfirm) when present, but this function itself
// only truly requires an amount — everything else is optional context.
// Brett, Sep 2026: "default all to my cards" — every receipt (Hub or vendor-submitted) is
// assumed to be a Ridge Co card purchase unless the person entering it explicitly says
// otherwise. payment_source is 'company_card' (default) or 'vendor_reimburse' (the vendor
// paid out of pocket and needs it added to what they're owed) — never silently inferred from
// role, since Brett himself sometimes logs an entry on a vendor's behalf.
async function addReceipt(env, body) {
  const { wo_id, property_id, amount, description, store, date, added_by, added_by_id, role, category, source_file_id, source_file_url, payment_source, allow_negative } = body;
  if (!amount && amount !== 0) return json({ error: 'amount required' }, 400);
  const amt = parseFloat(amount);
  if (isNaN(amt) || amt === 0) return json({ error: 'amount must be non-zero' }, 400);
  // Part 3 (Sep 22 2026 brief): a refund posts as a genuine NEGATIVE amount — money coming back,
  // not a charge (never a positive number silently standing in for it). Every other caller of
  // addReceipt (vendor portal, manual entry, ordinary WO receipts) still gets the original
  // positive-only guard; allow_negative is only ever passed by the refund expense path
  // (receiptReconConfirm's no_wo refund case) and the refund-reversal write
  // (receiptReconRefundReverse) — both Rung-3/Brett's-tap gated, never automatic.
  if (amt < 0 && !allow_negative) return json({ error: 'amount must be a positive number' }, 400);
  const paymentSource = (payment_source === 'vendor_reimburse') ? 'vendor_reimburse' : 'company_card';

  // Same receipt, same job/property, same store, seconds apart = a double-tap, not two
  // purchases. Added_By_ID and Date are in the signature and the window is short, because two
  // small identical purchases on one job (two of the same fitting from the same run) is a
  // real thing and must not be swallowed.
  const dupe = await findRecentDuplicate(env, 'Receipts', {
    WO_ID: wo_id || '', Property_ID: property_id || '', Amount: amt.toFixed(2), Store: store || '', Description: description || '',
    Added_By_ID: String(added_by_id || ''), Date: date || new Date().toISOString().split('T')[0],
  }, 30);
  if (dupe) return json({ success: true, duplicate: true, amount: amt.toFixed(2) });

  // The core fields below still land even if this fails; only the new ones are at risk on a
  // very first run. Rule 174: ensureColumns itself now logs a Telemetry row on any failure
  // (see its own comment) — this used to swallow that same failure with zero trace anywhere,
  // which is exactly how Payment_Source went unnoticed for weeks. No swallow needed here
  // anymore; the shared function's own logging covers it.
  try { await ensureColumns(env, 'Receipts', ['Property_ID', 'Category', 'Source_File_ID', 'Source_File_URL', 'QB_Email_Sent', 'QB_Email_Sent_Date', 'Payment_Source']); }
  catch (e) { /* logged centrally by ensureColumns; the write below still proceeds with whatever columns exist */ }

  const addResp = await addRow(env, 'Receipts', {
    WO_ID: wo_id || '', Property_ID: property_id || '', Amount: amt.toFixed(2), Description: description||'', Store: store||'',
    Date: date||new Date().toISOString().split('T')[0], Added_By: added_by||'', Added_By_ID: String(added_by_id||''),
    Role: role||'hub', Category: category || (wo_id ? 'billable' : 'company'), Payment_Source: paymentSource,
    Source_File_ID: source_file_id || '', Source_File_URL: source_file_url || '',
    QB_Email_Sent: 'FALSE', QB_Email_Sent_Date: '',
    Created_Date: new Date().toISOString(), Active: 'TRUE',
  });
  let newId = ''; try { const j = await addResp.clone().json(); newId = j && j.id || ''; } catch (e) {}

  // Sep 28 2026 fix (Brett — WO-1229/Amanda's garbage disposal): a receipt confirmed through the
  // Receipt Reconciler correctly writes Source_File_ID/Source_File_URL onto this new Receipts
  // row, and that's what the invoice line and Invoice_Review pull from — so the AMOUNT always
  // made it onto the customer invoice. But the WO detail page's unified "Attachments" gallery
  // (index.html's loadPortalAttachments, owner.html's matching photo/receipt view) never reads
  // Receipts at all — it reads the separate Attachments tab, which until now only ever got a row
  // from a direct photo/file upload (POST /attachment/add), never from a receipt confirm/attach/
  // reassign/refund-reverse flow. So the receipt's own image silently never showed up in
  // Attachments even though it was fully on file and fully billed. Every addReceipt() caller that
  // has both a WO and an actual scanned file (receiptReconConfirm, receiptAttachOnly, reassign,
  // refund-reverse, the vendor-submitted path) is fixed here in one place: write a matching
  // Attachments row, File_Type 'receipt', linked back to this Receipts row via Receipt_ID (new
  // column, additive) so a backfill or a retry can never create a duplicate. Deliberately skipped
  // when there's no wo_id (a no-WO company/1864-Kerns expense has nowhere to gallery it) or no
  // file (a manual receipt entry with no image). This never touches Receipts/Invoice_Review/
  // billing — additive-only, Attachments write failure never fails the receipt add itself.
  if (wo_id && newId && (source_file_id || source_file_url)) {
    try {
      await ensureColumns(env, 'Attachments', ['Receipt_ID']);
      await addRow(env, 'Attachments', {
        WO_ID: wo_id, File_Name: ((store || 'Receipt') + (date ? ' ' + date : '')).trim(),
        File_Type: 'receipt', Drive_File_ID: source_file_id || '', Drive_URL: source_file_url || '',
        Mime_Type: '', Receipt_ID: String(newId),
        Created_Date: new Date().toISOString().split('T')[0], Active: 'TRUE',
      });
    } catch (e) { try { await logTelemetry(env, { Source: 'worker', Job_Type: 'receipt_attachment_gallery_write', Skill_Or_Endpoint: '/receipt/add', Success: 'FALSE', Notes: `receipt_id=${newId} wo_id=${wo_id} err=${String(e && e.message || e)}` }); } catch (_) {} }
  }

  return json({ success: true, amount: amt.toFixed(2), id: newId, payment_source: paymentSource });
}

// ── RECEIPT RECONCILER (CAP-002) — deterministic matching engine, ZERO AI ──────────────────────
// The token-saving core of the receipt pipeline. Given a receipt's already-extracted fields (PO,
// total, date, store, items), it decides — with pure code, no model call — where the receipt
// belongs and whether it's safe to bill: exclude company/customer-paid, resolve the property from
// the PO, rank that property's OPEN work orders by keyword overlap, and raise duplicate /
// already-invoiced guards. READ-ONLY; suggests, never writes. The only AI in the whole pipeline is
// the one cheap per-image OCR (receiptExtract) that produces this input.
// Strip apostrophes to NOTHING before the general non-alnum-to-space pass, not just fold them
// into a space — "Lowe's" and "Lowes" must normalize identically. Sep 28 2026 fix: an apostrophe
// falling into the generic [^a-z0-9] class turned "Lowe's" into "lowe s" (two tokens), which
// then no longer contained "lowes" as a substring — "lowes" and "lowe's" returned different
// receipt-recon search results for the same store. See matching fix in receipt-reconciler.html's
// _clientNorm (same bug, client-side queue filter).
function _rcNorm(s){ return String(s==null?'':s).toLowerCase().replace(/['‘’ʼ`´]/g, '').replace(/[^a-z0-9]/g,' ').replace(/\s+/g,' ').trim(); }

// PURE — resolve the property a receipt's PO/handwritten note points to, by token overlap on the
// street address. A matched house-number is weighted double (it disambiguates same-street units).
// Returns null below a confidence floor so an unmatched receipt is flagged, never mis-filed.
function matchReceiptProperty(po, properties) {
  const n = _rcNorm(po); if (!n) return null;
  const nt = n.split(' ');
  let best = null, bestScore = 0;
  for (const p of (properties || [])) {
    const a = _rcNorm(p.Address); if (!a) continue;
    const at = new Set(a.split(' '));
    let sc = 0; for (const t of nt) { if (t.length > 1 && at.has(t)) sc += /^\d+$/.test(t) ? 2 : 1; }
    if (sc > bestScore) { bestScore = sc; best = p; }
  }
  return bestScore >= 2 ? { property: best, score: bestScore } : null;
}

const RECEIPT_OPEN_STATUSES = WOStatus.sets.ACTIVE;
const RECEIPT_STOP = new Set(['the','and','for','with','apt','ste','unit','street','saint','st','ave','rd','ln','pl','n','s','e','w','2x','x']);

// PURE — rank a property's work orders by keyword overlap between the receipt (items + PO) and each
// WO's description/trade. Only OPEN work orders are returned (a receipt can only be billed onto work
// that hasn't been invoiced yet); each carries its status so the caller can flag Invoiced/Paid.
function rankReceiptWOs(receipt, wos) {
  // Rank on the ITEM keywords only — NOT the PO/address. The property is already resolved, so
  // letting address tokens ("3014","calvert") score would wrongly favor whichever WO's description
  // repeats the address over the WO that actually matches the materials (caught in live testing).
  const blob = _rcNorm(Array.isArray(receipt.items) ? receipt.items.join(' ') : (receipt.items||''));
  const kw = Array.from(new Set(blob.split(' ').filter(w => w.length >= 3 && !RECEIPT_STOP.has(w))));
  return (wos || []).map(w => {
    const desc = _rcNorm((w.Description||'') + ' ' + (w.Trade||''));
    let score = 0; for (const k of kw) if (desc.indexOf(k) >= 0) score++;
    return { id: String(w.ID), status: w.Status, trade: w.Trade||'', unit: String(w.Unit_ID||''),
             desc: String(w.Description||'').replace(/\s+/g,' ').slice(0, 70), score,
             open: RECEIPT_OPEN_STATUSES.includes(w.Status) };
  }).filter(w => w.open).sort((a,b) => b.score - a.score || String(a.id).localeCompare(String(b.id)));
}

// PURE — a receipt is a DUPLICATE if the same WO already carries an active receipt with the same
// amount, date, and store. This is the exact class of double-post we hit twice by hand today.
function receiptIsDuplicate(receipts, woId, amount, date, store) {
  const amt = (Number(amount)||0).toFixed(2), st = _rcNorm(store);
  return (receipts || []).some(r => r.Active !== 'FALSE' && String(r.WO_ID) === String(woId) &&
    (Number(r.Amount)||0).toFixed(2) === amt && String(r.Date||'') === String(date||'') && _rcNorm(r.Store) === st);
}

// PURE — Part 3 matching step: given a refund (store/amount/date/items), find candidate ORIGINAL
// purchase receipts it might be reversing. Same-store required; a candidate purchase must date
// on-or-before the refund and within `windowDays` (default 120 — returns commonly lag weeks to a
// couple months); a candidate must be a real positive purchase (never another refund) whose
// amount is at least the refund amount (a receipt for less than what's being refunded can't be
// the source of a full or partial return of it). Scored, not decided — this only ever SUGGESTS;
// Brett's own tap on the returned receipt_id is what actually reverses anything (see
// receiptReconRefundReverse). No I/O — everything is passed in, so this is fully unit-testable.
function receiptRefundFindMatches(refund, existingReceipts, opts) {
  opts = opts || {};
  const windowDays = opts.windowDays || 120;
  const refundAmt = Math.abs(Number(refund && refund.amount) || 0);
  const refundStore = _rcNorm(refund && refund.store);
  const refundDate = String((refund && refund.date) || '').trim();
  const refundDateMs = refundDate ? Date.parse(refundDate + 'T00:00:00Z') : NaN;
  const refundItemsBlob = _rcNorm(Array.isArray(refund && refund.items) ? refund.items.join(' ') : ((refund && refund.items) || ''));
  const refundKw = new Set(refundItemsBlob.split(' ').filter(w => w.length >= 3 && !RECEIPT_STOP.has(w)));
  if (!refundStore || !refundAmt) return [];

  const candidates = [];
  for (const r of (existingReceipts || [])) {
    if (!r || r.Active === 'FALSE') continue;
    const amt = Number(r.Amount) || 0;
    if (amt <= 0) continue; // only match against real purchases, never another refund/negative row
    if (_rcNorm(r.Store) !== refundStore) continue;
    if (amt + 0.01 < refundAmt) continue; // a smaller purchase can't be the source of this refund
    const purchaseDateMs = r.Date ? Date.parse(String(r.Date) + 'T00:00:00Z') : NaN;
    let hasDateRelation = false;
    if (!isNaN(refundDateMs) && !isNaN(purchaseDateMs)) {
      const diffDays = (refundDateMs - purchaseDateMs) / 86400000;
      if (diffDays < 0 || diffDays > windowDays) continue; // must precede the refund, within the window
      hasDateRelation = true;
    }
    let score = 0;
    const amountDiff = Math.abs(amt - refundAmt);
    const exactAmount = amountDiff < 0.02;
    score += exactAmount ? 3 : 1;
    if (hasDateRelation) score += 1;
    const descBlob = _rcNorm(String(r.Description || ''));
    let itemOverlap = 0;
    for (const k of refundKw) if (descBlob.indexOf(k) >= 0) itemOverlap++;
    score += itemOverlap;
    candidates.push({
      receipt_id: r.ID, wo_id: r.WO_ID || '', property_id: r.Property_ID || '',
      amount: amt, date: r.Date || '', store: r.Store || '', description: r.Description || '',
      exact_amount: exactAmount, item_overlap: itemOverlap, score,
    });
  }
  candidates.sort((a, b) => b.score - a.score || Math.abs(a.amount - refundAmt) - Math.abs(b.amount - refundAmt));
  return candidates.slice(0, 5);
}

// ── Receipt duplicate CHECKER (Sep 2 2026 design, built Sep 16 2026) ────────────────────────
// PURE — property-wide duplicate check, deliberately WIDER than receiptIsDuplicate above (which
// only ever compares against the ONE work order a receipt is being posted to). Brett re-scanning
// a batch of old receipts: "I think some of these receipts are actual duplicates... check
// against duplicates in QuickBooks and/or existing work orders." A receipt entered against the
// wrong WO at the same property (a real, recurring mistake — several jobs often run at once on
// one property) would never be caught by the same-WO check; this compares against every OTHER
// Receipts row logged at the same property, regardless of which WO it landed on.
// `workorders` resolves a candidate's property when it only carries a WO_ID (older rows may
// predate Receipts.Property_ID existing at all) — never trusted over an explicit Property_ID.
function receiptDuplicatesAtProperty(receipt, allReceipts, workorders) {
  const amt = (Number(receipt.total ?? receipt.amount) || 0).toFixed(2);
  const st = _rcNorm(receipt.store);
  const date = String(receipt.date || '');
  const propId = String(receipt.property_id || '');
  if (!propId || !date) return []; // can't safely scope a property-wide check without both
  const excludeId = receipt.id != null ? String(receipt.id) : null;
  const woPropMap = {}; (workorders || []).forEach(w => { woPropMap[String(w.ID)] = String(w.Property_ID || ''); });
  return (allReceipts || [])
    .filter(r => {
      if (r.Active === 'FALSE') return false;
      if (excludeId && String(r.ID) === excludeId) return false;
      const rProp = String(r.Property_ID || woPropMap[String(r.WO_ID)] || '');
      if (rProp !== propId) return false;
      if ((Number(r.Amount) || 0).toFixed(2) !== amt) return false;
      if (String(r.Date || '') !== date) return false;
      if (_rcNorm(r.Store) !== st) return false;
      return true;
    })
    .map(r => ({ id: r.ID, wo_id: r.WO_ID || '', amount: r.Amount, date: r.Date, store: r.Store, added_by: r.Added_By || '' }));
}

// PURE — narrows a broad QuickBooks Invoice list (Id/DocNumber/TxnDate only — no Line items,
// see qbInvoiceLineDuplicates below for why) down to candidates within `windowDays` of a
// receipt's date. Kept separate from the QB fetch itself so the date-window logic is
// unit-testable with no live Sheets/QuickBooks.
function qbInvoiceCandidatesByDate(invoices, date, windowDays) {
  if (!date) return [];
  const target = new Date(date + 'T00:00:00Z').getTime();
  if (isNaN(target)) return [];
  return (invoices || []).filter(inv => {
    const txn = inv.TxnDate ? new Date(inv.TxnDate + 'T00:00:00Z').getTime() : null;
    return txn != null && !isNaN(txn) && Math.abs(txn - target) <= windowDays * 86400000;
  });
}

// PURE — the whole reconciliation decision, no I/O. Given an already-extracted receipt and
// already-fetched tabs, decides category/action. Factored out of receiptSuggest() so the SAME
// logic drives both the interactive POST /receipt/suggest endpoint and the bulk cron scan
// (receiptReconScan) below — one source of truth, and fully unit-testable with no live Sheets.
function receiptSuggestCore(input, properties, workorders, receipts, custCards) {
  const po = String(input.po || '').trim();
  let total = Number(input.total) || 0;
  const date = String(input.date || '').trim();
  const store = String(input.store || '').trim();
  const items = Array.isArray(input.items) ? input.items : (input.items ? [String(input.items)] : []);
  const card = String(input.card || '').replace(/\D/g,'').slice(-4);
  const cc = custCards || [];

  // Exclusions first — never propose a WO for spend that isn't customer-billable.
  // Part 3 (Sep 22 2026 brief): a refund is NEVER skip-only anymore — it has two real actions
  // (match-and-reverse the original purchase, or post as a negative expense), both offered by
  // the Reconciler UI off this category. Defense-in-depth on the sign: whether the negative
  // total came from receiptExtract's own refund detection or from input.refund being passed
  // explicitly (e.g. by a caller that didn't go through receiptExtract), the total returned
  // here is always forced negative — never a positive refund amount reaching addReceipt.
  if (total < 0 || input.refund === true) {
    total = total ? -Math.abs(total) : total;
    return {
      ok: true, category: 'refund', action: 'refund_review',
      reason: 'Return/refund receipt — confirm a matching original purchase to reverse the bill, or post as a negative expense.',
      po, total, store, date, items,
    };
  }
  if (/\bbmore\b/i.test(po) || /\bbmore\b/i.test(String(input.customer_name||''))) return { ok: true, category: 'company', action: 'exclude', reason: 'PO "bmore" = company expense, not customer-billable.', po, total };
  if (card && cc.includes(card)) return { ok: true, category: 'customer_paid', action: 'exclude', reason: `Paid on a customer card (…${card}).`, po, total };

  const m = matchReceiptProperty(po, properties);
  if (!m) return { ok: true, category: 'billable', action: 'need_property', reason: 'Could not resolve a property from the PO — assign manually.', po, total, store, date };
  const pid = String(m.property.ID);
  const propWos = (workorders || []).filter(w => String(w.Property_ID) === pid);
  const ranked = rankReceiptWOs({ items, po }, propWos);
  const top = ranked[0] || null;
  const flags = [];
  if (top && receiptIsDuplicate(receipts, top.id, total, date, store)) flags.push('duplicate_on_wo');
  if (top && WOStatus.sets.INVOICED_OR_PAYMENT.includes(top.status)) flags.push('wo_already_invoiced');
  if (!ranked.length) flags.push('no_open_wo');
  return {
    ok: true, category: 'billable',
    action: flags.includes('duplicate_on_wo') ? 'skip_duplicate' : (top ? 'suggest' : 'need_wo'),
    po, total, store, date,
    property: { id: pid, address: m.property.Address, match_score: m.score },
    suggested_wo: top ? { id: top.id, status: top.status, trade: top.trade, desc: top.desc, keyword_score: top.score } : null,
    alternates: ranked.slice(1, 4),
    flags,
  };
}

// Customer-card list can live in the Cloudflare secret (RECEIPT_CUSTOMER_CARDS) OR, so Brett
// never has to touch the Cloudflare dashboard, a Config sheet row 'receipt_customer_cards' —
// either works, comma-separated last-4s.
async function receiptCustomerCards(env) {
  const cfg = await fetchConfig(env).catch(() => ({}));
  return String(env.RECEIPT_CUSTOMER_CARDS || cfg.receipt_customer_cards || '').split(',').map(s => s.replace(/\D/g,'').slice(-4)).filter(Boolean);
}

// POST /receipt/suggest { po, total, date, store, items, card } — READ-ONLY. Returns the
// deterministic reconciliation for one already-extracted receipt. Admin-gated; writes nothing.
async function receiptSuggest(env, body) {
  body = body || {};
  try {
    const custCards = await receiptCustomerCards(env);
    const [properties, workorders, receipts] = await fetchTabs(env, ['Properties', 'Work_Orders', 'Receipts']);
    const result = receiptSuggestCore({
      po: body.po || body.po_or_property || '', total: body.total, date: body.date,
      store: body.store || body.vendor || '', items: body.items,
      card: body.card || body.payment_card_last4 || '', customer_name: body.customer_name,
    }, properties, workorders, receipts, custCards);
    return json(result);
  } catch (e) { return json({ ok: false, error: String(e && e.message || e) }, 500); }
}

// ── RECEIPT RECONCILER — PHASE 2 (CAP-002) — daily automation wrapper ──────────────────────
// Polls the real "Receipts and Invoices" Drive folder (under PAYABLES Inbox — the folder Brett
// already drops scans into) once a day via the existing digest cron, OCRs each new file with the
// one cheap vision call (receiptExtract), runs it through the zero-AI engine above, and drops the
// verdict in a confirm-first queue. NOTHING bills itself — every row sits until Brett taps
// Confirm (POST /receipt-recon/confirm, which calls the same addReceipt() the vendor portal and
// every manual entry this session used) or Skip. A pending row costs one OCR call and zero other
// AI tokens; the daily sweep of an empty folder costs nothing at all.
const RECEIPT_RECON_QUEUE_HEADERS = ['ID','Source_File_ID','Source_File_URL','File_Name','Received_Date','Vendor','Receipt_Date','Total','PO_Reference','Items','Items_Summary','Card_Last4','Invoice_Number','Suggestion','Status','Confirmed_WO_ID','Confirmed_Amount','Confirmed_Description','Notes','Active','Duplicate_Confirmed_Date','Duplicate_Evidence_JSON','Duplicate_Checked_Date','Gmail_Message_ID','Entry_Source','Rescan_Match_JSON','Confirmed_Receipt_ID','Manual_Refund'];
// "Receipts and Invoices" under PAYABLES Inbox (Drive) — the folder Brett has been dropping
// scans into all session. Overridable without a redeploy via Config key 'receipt_recon_folder_id'.
const RECEIPT_RECON_FOLDER_ID_DEFAULT = '1-sf6pQN2DD3qj5cPZavy1k0DOfH4U20n';

// ── Part 0 (Sep 22 2026 incident) — intake-time rescan guard ───────────────────────────────
// Brett caught a $56.04 Home Depot receipt he'd already processed reappearing as a fresh
// Pending row with no indication it had already been handled. Root cause: receiptReconScan only
// ever deduped on Source_File_ID (the Drive file), so a receipt processed by hand, or confirmed
// before a mailbox scan ever ran, could get pulled back in through a NEW Drive file (a re-forward,
// a second manual drop, an email backfill re-run) and look indistinguishable from brand-new. The
// functions below cross-check a receipt BEFORE it's queued and, on a match, flag it — never
// silently drop it (a false match could hide a real second purchase at the same store).

// PURE — the Apps Script (ReceiptMailToHub.gs, saveMessage_) already writes a Gmail link into
// every emailed receipt's Drive file description, e.g. "...| https://mail.google.com/mail/u/?
// authuser=...#all/19abcdef0123456". This reads that existing metadata — no Apps Script redeploy
// needed. Returns '' when the file wasn't produced by the email pipeline (a manual Drive drop).
function receiptReconGmailIdFromDescription(desc) {
  const m = String(desc || '').match(/#all\/([A-Za-z0-9_-]+)/);
  return m ? m[1] : '';
}

// PURE — same description text (see receiptReconGmailIdFromDescription) distinguishes a file the
// email pipeline saved from one Brett dropped into the Drive folder by hand. Used only to show
// Brett a fast "how did this get here" cue on every Pending row, per his Sep 22 ask — never
// changes any routing/matching decision.
function receiptReconEntrySource(desc) {
  return /From email .* Hub/.test(String(desc || '')) ? 'email_scan' : 'manual_drop';
}

// PURE — cross-checks one about-to-be-queued receipt against (a) an exact re-add of the same
// source email (Gmail message ID, cheapest/highest-confidence, layer 1), (b) already-confirmed
// Receipts rows with the same store+amount+date, and (c) Receipt_Recon_Queue rows Brett already
// dispositioned (skipped / confirmed / duplicate_confirmed — NOT still pending) with the same
// store+amount+date. Returns a flat array of match objects, each with a ready-to-show `reason`
// string (same shape as receiptCheckDuplicatesOne's evidence array below). Never decides
// anything — the caller always still queues the row as 'pending'; this only adds the flag.
function receiptReconFindRescanMatches(candidate, existingReceipts, existingQueueRows) {
  const amt = (Number(candidate.total) || 0).toFixed(2);
  const st = _rcNorm(candidate.store);
  const date = String(candidate.date || '').trim();
  const matches = [];

  if (candidate.gmailMessageId) {
    for (const r of (existingQueueRows || [])) {
      if (r.Gmail_Message_ID && r.Gmail_Message_ID === candidate.gmailMessageId) {
        const status = r.Status || 'pending';
        matches.push({
          type: 'gmail_exact', queue_id: r.ID, status, received_date: r.Received_Date || '',
          reason: `This exact email was already processed on ${String(r.Received_Date || '').slice(0, 10)} (queue #${r.ID}, status: ${status}).`,
        });
      }
    }
  }

  if (date && st && Number(amt) > 0) {
    for (const r of (existingReceipts || [])) {
      if (r.Active === 'FALSE') continue;
      if ((Number(r.Amount) || 0).toFixed(2) !== amt) continue;
      if (String(r.Date || '') !== date) continue;
      if (_rcNorm(r.Store) !== st) continue;
      matches.push({
        type: 'receipts', receipt_id: r.ID, wo_id: r.WO_ID || '', date: r.Date, amount: r.Amount, store: r.Store,
        reason: `Possible re-scan — matches an already-processed receipt from ${r.Date} ($${(Number(r.Amount) || 0).toFixed(2)} at ${r.Store || 'that store'}${r.WO_ID ? ', WO ' + r.WO_ID : ''}).`,
      });
    }
    for (const r of (existingQueueRows || [])) {
      const status = r.Status || 'pending';
      if (status === 'pending') continue;
      if (String(r.Active || '').toUpperCase() === 'FALSE') continue;
      if ((Number(r.Total) || 0).toFixed(2) !== amt) continue;
      if (String(r.Receipt_Date || '') !== date) continue;
      if (_rcNorm(r.Vendor) !== st) continue;
      matches.push({
        type: 'queue_dispositioned', queue_id: r.ID, status, date: r.Receipt_Date, amount: r.Total, store: r.Vendor,
        reason: `Possible re-scan — matches a previously ${status.replace(/_/g, ' ')} queue entry from ${r.Receipt_Date} ($${(Number(r.Total) || 0).toFixed(2)} at ${r.Vendor || 'that store'}).`,
      });
    }
  }
  return matches;
}

// ── Statement importer (Sep 24 2026) — STATEMENT_RECEIPT_RECONCILIATION_BUILD_BRIEF_v1.0 Phase 1
// ─────────────────────────────────────────────────────────────────────────────────────────────
// PURE — checks ONE normalized statement line (from a bulk vendor statement — Home Depot, Lowe's,
// a credit card, etc.) against already-captured Receipts and Receipt_Recon_Queue rows. Deliberately
// reuses the SAME comparison primitives as receiptReconFindRescanMatches above (_rcNorm,
// .toFixed(2) string equality for money, same Active/Status filters) rather than inventing a
// second dedup/matching algorithm — the brief's explicit, load-bearing instruction. Never image
// matching (a statement line never looks like a receipt photo).
// Returns { confidence: 'confirmed'|'possible'|null, ...matchDetails }:
//   1. 'confirmed' — exact amount (to the cent) AND exact date AND normalized vendor match,
//      against a live Receipts row (Active !== 'FALSE') or a non-pending Receipt_Recon_Queue row.
//   2. 'confirmed' — line.ref (PO/invoice number) exact-matches PO_Reference or Invoice_Number on
//      an existing Receipt_Recon_Queue row, at the same amount, even if the date differs by a day
//      or two (a reference match is a stronger signal than date proximity). Receipts itself has no
//      PO/invoice-number column (confirmed live, addReceipt above) — checked against Description
//      there as a best-effort fallback only.
//   3. 'possible' — same amount (exact) AND date within ±3 calendar days (same day-window math as
//      qbDuplicateBillsNear) AND normalized vendor roughly matches (substring either direction) —
//      weaker signal, still surfaced, never silently suppressed.
//   4. null — no match.
function statementLineMatch(line, existingReceipts, existingQueueRows) {
  const amt = (Number(line && line.amount) || 0).toFixed(2);
  const st = _rcNorm(line && (line.vendor || line.store));
  const date = String((line && line.date) || '').trim();
  const ref = String((line && line.ref) || '').trim();
  const roughMatch = (a, b) => !!a && !!b && (a.indexOf(b) >= 0 || b.indexOf(a) >= 0);

  // 1) Exact match — amount + date + normalized vendor.
  if (date && st && Number(amt) > 0) {
    for (const r of (existingReceipts || [])) {
      if (r.Active === 'FALSE') continue;
      if ((Number(r.Amount) || 0).toFixed(2) !== amt) continue;
      if (String(r.Date || '') !== date) continue;
      if (_rcNorm(r.Store) !== st) continue;
      return { confidence: 'confirmed', type: 'exact_receipt', receipt_id: r.ID, wo_id: r.WO_ID || '' };
    }
    for (const r of (existingQueueRows || [])) {
      const status = r.Status || 'pending';
      if (status === 'pending') continue;
      if (String(r.Active || '').toUpperCase() === 'FALSE') continue;
      if ((Number(r.Total) || 0).toFixed(2) !== amt) continue;
      if (String(r.Receipt_Date || '') !== date) continue;
      if (_rcNorm(r.Vendor) !== st) continue;
      return { confidence: 'confirmed', type: 'exact_queue', queue_id: r.ID, status };
    }
  }

  // 2) Reference match — same amount, exact PO/invoice number, date can differ.
  if (ref && Number(amt) > 0) {
    for (const r of (existingQueueRows || [])) {
      if (String(r.Active || '').toUpperCase() === 'FALSE') continue;
      if ((Number(r.Total) || 0).toFixed(2) !== amt) continue;
      if (ref === String(r.PO_Reference || '').trim() || ref === String(r.Invoice_Number || '').trim()) {
        return { confidence: 'confirmed', type: 'ref_queue', queue_id: r.ID, status: r.Status || 'pending' };
      }
    }
    for (const r of (existingReceipts || [])) {
      if (r.Active === 'FALSE') continue;
      if ((Number(r.Amount) || 0).toFixed(2) !== amt) continue;
      if (ref === String(r.Description || '').trim()) {
        return { confidence: 'confirmed', type: 'ref_receipt', receipt_id: r.ID, wo_id: r.WO_ID || '' };
      }
    }
  }

  // 3) Possible — same amount, date within ±3 days, vendor roughly matches.
  if (date && Number(amt) > 0) {
    const d = new Date(date + 'T00:00:00Z');
    if (!isNaN(d)) {
      const from = d.getTime() - 3 * 86400000, to = d.getTime() + 3 * 86400000;
      for (const r of (existingReceipts || [])) {
        if (r.Active === 'FALSE') continue;
        if ((Number(r.Amount) || 0).toFixed(2) !== amt) continue;
        const rd = new Date(String(r.Date || '') + 'T00:00:00Z'); if (isNaN(rd)) continue;
        if (rd.getTime() < from || rd.getTime() > to) continue;
        if (st && !roughMatch(_rcNorm(r.Store), st)) continue;
        return { confidence: 'possible', type: 'window_receipt', receipt_id: r.ID, wo_id: r.WO_ID || '' };
      }
      for (const r of (existingQueueRows || [])) {
        const status = r.Status || 'pending';
        if (status === 'pending') continue;
        if (String(r.Active || '').toUpperCase() === 'FALSE') continue;
        if ((Number(r.Total) || 0).toFixed(2) !== amt) continue;
        const rd = new Date(String(r.Receipt_Date || '') + 'T00:00:00Z'); if (isNaN(rd)) continue;
        if (rd.getTime() < from || rd.getTime() > to) continue;
        if (st && !roughMatch(_rcNorm(r.Vendor), st)) continue;
        return { confidence: 'possible', type: 'window_queue', queue_id: r.ID, status };
      }
    }
  }

  return { confidence: null };
}

// POST /receipt-recon/scan (also called by the daily cron) — pull new files from the inbox
// folder, OCR + reconcile each one, append to the confirm-first queue. Never writes a Receipt.
async function receiptReconScan(env, body) {
  // Oct 16 2026: AI credit paused -> touch nothing (no Drive listing, no OCR call, no attempt counted); files wait in the folder.
  { const st = await aiCreditCheck(env); if (st.paused) return aiCreditPausedJson({ message: AI_SCAN_PAUSED_MSG, scanned: 0, remaining: 0, paused_since: st.at || null, reason: 'paused: AI credit - receipts stay in the Drive folder and are scanned automatically after AI resumes' }); }
  const cfg = await fetchConfig(env).catch(() => ({}));
  // Per-call cap on NEW files (Sep 22 2026). Each file costs ~4 subrequests (Drive download, OCR,
  // Sheets append); uncapped, a big drop (e.g. an email backfill) blew Cloudflare's per-invocation
  // subrequest limit partway through — same failure rule 155a hit at 25 for QB email forwarding.
  // Files past the cap simply wait for the next scan (dedup is by Source_File_ID), and the
  // response's `remaining` tells the Hub button to say "tap Scan again".
  const want = [body && body.max, cfg.receipt_recon_scan_batch].map(Number).find(n => Number.isFinite(n) && n >= 1);
  const cap = Math.min(10, Math.floor(want || 8));
  const folder = cfg.receipt_recon_folder_id || env.RECEIPT_RECON_FOLDER_ID || RECEIPT_RECON_FOLDER_ID_DEFAULT;
  const tok = await getAccessToken(env);
  await ensureTab(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);
  // The tab already existed with live rows before Duplicate_Confirmed_Date was added (Aug 23) —
  // ensureTab only writes headers on a brand-new/empty tab, so an existing tab needs the
  // explicit widen-and-append-header path or the new column silently never appears (rule 37/78).
  await ensureColumns(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);
  const params = new URLSearchParams({ q: `'${folder}' in parents and trashed=false`, fields: 'files(id,name,mimeType,webViewLink,description)', supportsAllDrives: 'true', includeItemsFromAllDrives: 'true', pageSize: '100' });
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?${params}`, { headers: { Authorization: `Bearer ${tok}` } });
  const data = await res.json();
  if (data.error) return json({ ok: false, error: 'Drive list failed: ' + (data.error.message || JSON.stringify(data.error)) }, 500);
  const files = (data.files || []).filter(f => /image|pdf/i.test(f.mimeType || ''));

  let existing = []; try { existing = await fetchTab(env, 'Receipt_Recon_Queue'); } catch (e) {}
  const seen = new Set(existing.map(r => r.Source_File_ID).filter(Boolean));
  // A file the OCR can't read (Sep 22 2026: recon_smoke_test.png, "Could not process image")
  // was never written to the queue, so every scan retried it forever — one wasted AI call per
  // scan, and a permanent error line. Same fix receiptScan got for its folder: 3 attempts,
  // tracked in Config (no schema change), then skipped and reported under `stuck`.
  let failures = {}; try { failures = JSON.parse(cfg.receipt_recon_failures || '{}'); } catch (e) { failures = {}; }
  // Sep 29 2026: a missing/rotated API key ("ANTHROPIC_API_KEY not configured") is a Worker
  // config problem, NOT a bad file — it must never burn a file's 3 attempts. Self-heal: drop any
  // tracker entry whose recorded error was a config error, so files stranded by an earlier key
  // outage are retried automatically the next scan.
  let healed = false;
  for (const id of Object.keys(failures)) {
    if (receiptReconIsConfigError(failures[id] && failures[id].error) || aiCreditErrorTextIsOutage(failures[id] && failures[id].error)) { delete failures[id]; healed = true; }   // + Oct 16 2026: attempts burned by the credit outage
  }
  if (healed) { try { await setConfigKey(env, { key: 'receipt_recon_failures', value: JSON.stringify(failures) }); } catch (e) { console.error('receiptReconScan: could not save the healed tracker:', schedErrText(e)); await logTelemetry(env, { Source: 'worker', Job_Type: 'receipt_recon_tracker_write_failed', Skill_Or_Endpoint: 'receiptReconScan', Success: 'FALSE', Notes: schedErrText(e).slice(0, 300) }).catch(te => console.error('telemetry failed:', schedErrText(te))); } }
  const allNew = files.filter(f => !seen.has(f.id) && !(failures[f.id] && failures[f.id].attempts >= 3));
  const stuck = Object.values(failures).filter(x => x.attempts >= 3).map(x => x.name);
  if (!allNew.length) return json({ ok: true, folder_id: folder, scanned: 0, remaining: 0, already_queued: files.length, stuck });
  const newFiles = allNew.slice(0, cap);

  const custCards = await receiptCustomerCards(env);
  const [properties, workorders, receipts] = await fetchTabs(env, ['Properties', 'Work_Orders', 'Receipts']);
  let n = 0; const errs = []; let failuresChanged = false; let skippedOld = 0; let flaggedRescan = 0; let configError = ''; let pausedMid = false;
  const cutoff = receiptReconCutoff(cfg);
  for (const f of newFiles) {
    try {
      const dl = await driveDownload(tok, f.id);
      const ex = await receiptExtract(env, dl.bytes, dl.mime);
      const po = ex.po_reference || ex.handwritten_note || '';
      const items = Array.isArray(ex.items) ? ex.items : [];
      const itemsSummary = Array.isArray(ex.items_summary) ? ex.items_summary : [];
      const suggestion = receiptSuggestCore({ po, total: ex.total, date: ex.date, store: ex.vendor, items, card: ex.card_last4 || '', refund: ex.refund === true }, properties, workorders, receipts, custCards);
      const tooOld = receiptBeforeCutoff(ex.date, cutoff);
      if (tooOld) skippedOld++;
      // Part 0 (Sep 22 2026 incident) — cross-check BEFORE this lands as a fresh Pending row.
      // Never auto-skips on a match (a false positive could hide a real second purchase) — only
      // flags the row so Brett sees it the instant he looks at the card, not by memory.
      const gmailId = receiptReconGmailIdFromDescription(f.description);
      const entrySource = receiptReconEntrySource(f.description);
      const rescanMatches = receiptReconFindRescanMatches({ total: ex.total, store: ex.vendor, date: ex.date, gmailMessageId: gmailId }, receipts, existing);
      if (rescanMatches.length) flaggedRescan++;
      // Part 3 (Sep 22 2026 brief) — surface the refund detection in Notes too, not just the
      // Suggestion JSON the card's badge reads, so it's visible even before the UI renders.
      const refundNote = (!tooOld && ex.refund) ? ('🔄 Refund/return detected — ' + (ex.refund_reason || 'review the suggested match or post as a negative expense.')) : '';
      const notes = tooOld ? receiptCutoffNote(ex.date, cutoff) : [rescanMatches.length ? rescanMatches.map(m => '⚠️ ' + m.reason).join(' ') : '', refundNote].filter(Boolean).join(' ');
      await addRow(env, 'Receipt_Recon_Queue', {
        Source_File_ID: f.id, Source_File_URL: f.webViewLink || '', File_Name: f.name || '',
        Received_Date: new Date().toISOString(), Vendor: ex.vendor || '', Receipt_Date: ex.date || '',
        Total: (ex.total === null || ex.total === undefined) ? '' : String(ex.total),
        PO_Reference: po, Items: JSON.stringify(items), Items_Summary: JSON.stringify(itemsSummary), Card_Last4: ex.card_last4 || '', Invoice_Number: ex.invoice_number || '',
        Suggestion: JSON.stringify(suggestion).slice(0, 4000), Status: tooOld ? 'skipped' : 'pending',
        Confirmed_WO_ID: '', Confirmed_Amount: '', Confirmed_Description: '', Notes: notes, Active: 'TRUE',
        Gmail_Message_ID: gmailId, Entry_Source: entrySource, Rescan_Match_JSON: JSON.stringify(rescanMatches).slice(0, 4000),
      });
      n++;
      if (failures[f.id]) { delete failures[f.id]; failuresChanged = true; }
    } catch (e) {
      if (aiCreditIsPausedError(e)) { pausedMid = true; break; }   // credit ran out mid-scan: stop, no attempt counted, nothing retried
      errs.push((f.name || f.id) + ': ' + (e.message || 'err'));
      if (receiptReconIsConfigError(e && e.message)) { configError = String(e.message).slice(0, 200); break; }
      const prior = failures[f.id];
      failures[f.id] = { name: f.name || f.id, error: String(e && e.message || 'err').slice(0, 200), attempts: (prior ? prior.attempts : 0) + 1, last_tried: new Date().toISOString() };
      failuresChanged = true;
    }
  }
  if (failuresChanged) { try { await setConfigKey(env, { key: 'receipt_recon_failures', value: JSON.stringify(failures) }); } catch (e) { errs.push('could not save the attempt tracker: ' + schedErrText(e)); console.error('receiptReconScan: tracker write failed:', schedErrText(e)); } }
  const stuckNow = Object.values(failures).filter(x => x.attempts >= 3).map(x => x.name);
  if (pausedMid) return aiCreditPausedJson({ message: AI_SCAN_PAUSED_MSG, scanned: n, remaining: allNew.length - n, errors: errs, stuck: stuckNow, reason: 'paused: AI credit - the scan stopped when Anthropic credit ran out; remaining receipts wait in Drive' });
  return json({ ok: true, folder_id: folder, scanned: n, skipped_before_cutoff: skippedOld, flagged_rescan: flaggedRescan, cutoff, remaining: allNew.length - newFiles.length, errors: errs, stuck: stuckNow, config_error: configError || undefined });
}

// A Worker-side configuration problem (missing/rotated API key), as opposed to a problem with one
// specific file. Used so a key outage never counts against a file's 3-attempt limit.
function receiptReconIsConfigError(msg) {
  return /not configured|api[_ ]?key|missing .*(key|secret|token)|unauthori[sz]ed|invalid x-api-key|authentication_error/i.test(String(msg == null ? '' : msg));
}

// POST /receipt-recon/import-statement { vendor, rows:[{date,amount,description,ref}], source_file_id?,
// source_file_name?, source_file_url? } OR { vendor, file_id, mime_type, source_file_name? } —
// Statement importer Phase 1 (Sep 24 2026, STATEMENT_RECEIPT_RECONCILIATION_BUILD_BRIEF_v1.0).
// Lands EVERY unmatched/possibly-matched line from a bulk vendor statement into the SAME
// Receipt_Recon_Queue Brett already works daily — not a new screen — tagged Entry_Source:'statement'
// so he can tell a statement line apart from a normally scanned receipt. Confirmed matches are
// never inserted (no action needed); this never writes a Receipt directly, same non-billing
// discipline as receiptReconScan above. CSV rows are parsed CLIENT-SIDE (index.html) per this
// codebase's hubBulkImport convention — confirmed live, no server-side CSV parser exists — so the
// `rows` shape here is already-parsed objects, never raw CSV text.
async function receiptReconImportStatement(env, body) {
  body = body || {};
  const vendor = String(body.vendor || '').trim();
  if (!vendor) return json({ error: 'vendor required' }, 400);
  const hasRows = Array.isArray(body.rows) && body.rows.length;
  const hasFile = !!(body.file_id && body.mime_type);
  if (!hasRows && !hasFile) return json({ error: 'rows (array) or file_id+mime_type required' }, 400);
  if (hasRows && body.rows.length > 500) return json({ error: 'Too many rows in one call — split into batches of 500 or fewer.' }, 400);

  let workingRows = [];
  let detectedVendor = '';
  let sourceFileId = body.source_file_id || '';
  const sourceFileName = body.source_file_name || '';
  const sourceFileUrl = body.source_file_url || '';

  if (hasFile) {
    sourceFileId = body.file_id;
    let dl;
    try {
      const tok = await getAccessToken(env);
      dl = await driveDownload(tok, body.file_id);
    } catch (e) {
      return json({ error: 'Could not download the file: ' + (e && e.message || e) }, 500);
    }
    const ex = await statementExtract(env, dl.bytes, dl.mime);
    if (ex && ex._paused) return aiCreditPausedJson({ message: 'Automatic statement reading is paused - enter the statement lines by hand (or paste the CSV).' });
    detectedVendor = ex.vendor_detected || '';
    // statementExtract's own lines already use `amount`; documented here in case an older/altered
    // extractor response ever returns `total` instead — mapped defensively, never silently dropped.
    workingRows = (ex.lines || []).map(l => ({
      date: l.date || '', amount: (l.amount !== undefined && l.amount !== null) ? l.amount : l.total,
      description: l.description || '', ref: l.ref || '',
    }));
  } else {
    workingRows = body.rows;
  }

  await ensureTab(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);
  await ensureColumns(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);
  const [receipts, queueRows] = await fetchTabs(env, ['Receipts', 'Receipt_Recon_Queue']);

  // Cloudflare-subrequest-safety cap, same pattern as receiptReconScan's `cap`/`remaining` above —
  // a big statement (hundreds of lines) must never blow the per-invocation subrequest limit
  // partway through. FIXED (Sep 24 2026 review): rows past the cap used to always be re-taken from
  // the START of workingRows on the next call — since a just-inserted row is Status:'pending' and
  // statementLineMatch correctly treats 'pending' as NOT yet dispositioned (never counts as a prior
  // match), that meant the first 100 lines got duplicate-inserted every subsequent call instead of
  // dedupe-skipping. Fix: the CALLER now tracks and sends `offset` (default 0) so each call
  // processes a genuinely different slice — `next_offset` tells it exactly where to resume, so
  // nothing is ever reprocessed and nothing is silently skipped.
  const IMPORT_STATEMENT_MAX_WRITES = 100;
  const offset = Math.max(0, parseInt(body.offset, 10) || 0);
  const toProcess = workingRows.slice(offset, offset + IMPORT_STATEMENT_MAX_WRITES);
  const nextOffset = offset + toProcess.length;
  const remaining = Math.max(0, workingRows.length - nextOffset);

  let matched_confirmed = 0, flagged_possible = 0, inserted = 0, skipped_invalid = 0;
  const errors = [];
  const today = new Date().toISOString().split('T')[0];

  for (const line of toProcess) {
    const amt = Number(line && line.amount);
    const date = String((line && line.date) || '').trim();
    if (!isFinite(amt) || amt <= 0 || !date) { skipped_invalid++; continue; }
    const lineVendor = (line && line.vendor) || vendor;
    const normLine = { amount: amt, date, ref: (line && line.ref) || '', vendor: lineVendor };
    let match;
    try { match = statementLineMatch(normLine, receipts, queueRows); }
    catch (e) { errors.push('match failed: ' + (e && e.message || e)); match = { confidence: null }; }

    if (match.confidence === 'confirmed') { matched_confirmed++; continue; }
    if (match.confidence === 'possible') flagged_possible++;

    const noteBase = `From ${vendor} statement upload (${sourceFileName || 'uploaded ' + today}).`;
    const notes = noteBase + (match.confidence === 'possible' ? ' ⚠️ Possibly matches an existing entry within 3 days — check before billing.' : '');
    try {
      await addRow(env, 'Receipt_Recon_Queue', {
        Source_File_ID: sourceFileId || '', Source_File_URL: sourceFileUrl || '', File_Name: sourceFileName || '',
        Received_Date: new Date().toISOString(), Vendor: lineVendor, Receipt_Date: date,
        Total: String(amt), PO_Reference: (line && line.ref) || '', Items: '[]',
        Items_Summary: JSON.stringify([(line && line.description) || '']).slice(0, 4000),
        Card_Last4: '', Invoice_Number: '', Suggestion: '', Status: 'pending',
        Confirmed_WO_ID: '', Confirmed_Amount: '', Confirmed_Description: '', Notes: notes, Active: 'TRUE',
        Gmail_Message_ID: '', Entry_Source: 'statement', Rescan_Match_JSON: '[]',
      });
      inserted++;
    } catch (e) { errors.push('insert failed: ' + (e && e.message || e)); }
  }

  return json({
    success: true, vendor, vendor_detected: detectedVendor || undefined, total_lines: workingRows.length,
    matched_confirmed, flagged_possible, inserted, skipped_invalid, remaining, next_offset: nextOffset, errors,
  });
}

// GET /receipt-recon/queue?status=pending|confirmed|skipped|all — the confirm-first review list.
async function listReceiptReconQueue(env, url) {
  let rows = []; try { rows = await fetchTab(env, 'Receipt_Recon_Queue'); } catch (e) { return json([]); }
  const status = url.searchParams.get('status') || 'pending';
  return json(rows.filter(r => String(r.Active || '').toUpperCase() !== 'FALSE' && (status === 'all' || (r.Status || 'pending') === status))
    .map(r => {
      let suggestion = null; try { suggestion = JSON.parse(r.Suggestion || 'null'); } catch (e) {}
      let items = []; try { items = JSON.parse(r.Items || '[]'); } catch (e) {}
      let items_summary = []; try { items_summary = JSON.parse(r.Items_Summary || '[]'); } catch (e) {}
      let duplicate_evidence = []; try { duplicate_evidence = JSON.parse(r.Duplicate_Evidence_JSON || '[]'); } catch (e) {}
      let rescan_matches = []; try { rescan_matches = JSON.parse(r.Rescan_Match_JSON || '[]'); } catch (e) {}
      // Sep 23 2026 build: Brett's manual "mark as refund" override for a row the automatic
      // refund detection (receiptExtract's refund_signal_text / negative-total check) missed.
      // Only ever flips the category the frontend reads to decide which card to render — never
      // touches the original OCR'd Suggestion JSON itself, so un-marking it restores exactly
      // what the scanner originally decided.
      if (String(r.Manual_Refund || '').toUpperCase() === 'TRUE') {
        suggestion = Object.assign({}, suggestion || {}, { category: 'refund', manual_refund: true });
      }
      return { ...r, suggestion, items, items_summary, duplicate_evidence, rescan_matches };
    }));
}

// POST /receipt-recon/confirm { id, wo_id, amount, description, store, date } — the ONLY write
// path in this pipeline. Brett (or the UI, pre-filled from the suggestion) picks the WO; this
// calls the exact same addReceipt() every other entry path uses, so its duplicate guard and
// Receipts-tab shape are identical no matter how the receipt got there.
// Brett, Sep 2026: when a newly-confirmed receipt lands on a WO that already has an
// Invoice_Review row, fold it into that SAME row instead of leaving it to be picked up (or
// silently missed) whenever Brett next approves invoicing for the job. Never creates a
// second Invoice_Review row. If that invoice was already sent to QuickBooks, this does not
// touch QuickBooks at all — it just flags the row so the existing qb/repairable →
// qb/repair-invoice path (which already refuses to touch a paid invoice — see qbRepairInvoice)
// picks it up and Brett can push the update himself.
async function appendReceiptToInvoiceReview(env, { wo_id, receipt_id, amount }) {
  if (!wo_id || !receipt_id) return { linked: false };
  try {
    await ensureColumns(env, 'Invoice_Review', ['Repair_Flagged', 'Repair_Reason']);
    const irs = await fetchTab(env, 'Invoice_Review');
    const candidates = irs.filter(r => r.Active !== 'FALSE' && String(r.WO_ID) === String(wo_id));
    if (!candidates.length) return { linked: false, reason: 'no_invoice_review_yet' };
    // Most recently approved row for this WO, mirroring approveInvoiceReview's own
    // "hand back the existing row" precedent rather than guessing among several.
    candidates.sort((a, b) => new Date(b.Approved_Date || 0) - new Date(a.Approved_Date || 0));
    const ir = candidates[0];
    const amt = +(Number(amount) || 0).toFixed(2);
    // Part 3 (Sep 22 2026 brief): a refund reversal calls this with a NEGATIVE amt to credit
    // the pending invoice back down — the only real change from the original (always-positive)
    // shape. Still reject a literal zero; a negative amt is otherwise handled the same as a
    // positive one below, with an added floor so a reversal can never push the invoice negative.
    if (!amt) return { linked: false, reason: 'no_amount' };
    const ids = String(ir.Own_Material_IDs || '').split(',').map(x => x.trim()).filter(Boolean);
    if (ids.includes(String(receipt_id))) return { linked: true, ir_id: ir.ID, already: true };
    ids.push(String(receipt_id));
    const newOwnMaterials = +((Number(ir.Own_Materials) || 0) + amt).toFixed(2);
    const newCustomerTotal = +((Number(ir.Customer_Total) || 0) + amt).toFixed(2);
    if (newOwnMaterials < 0 || newCustomerTotal < 0) {
      // A refund larger than what's still pending on this invoice — the Receipts row itself
      // (the source of truth) is still written by the caller; this just can't safely fold the
      // credit into Invoice_Review without taking it below $0. Surfaced so the UI can tell Brett
      // to check the invoice by hand rather than silently under-crediting it.
      return { linked: false, reason: 'would_go_negative', attempted_delta: amt };
    }
    const alreadySent = !!(ir.QB_Invoice_ID || '').trim();
    const fields = { Own_Material_IDs: ids.join(','), Own_Materials: String(newOwnMaterials), Customer_Total: String(newCustomerTotal) };
    if (alreadySent) {
      fields.Repair_Flagged = 'TRUE';
      fields.Repair_Reason = `Receipt #${receipt_id} ($${amt.toFixed(2)}) added ${new Date().toISOString().split('T')[0]} after invoice was sent — run Repairable Invoices to push it to QuickBooks.`;
    }
    await updateRow(env, 'Invoice_Review', ir.ID, fields);
    return { linked: true, ir_id: ir.ID, already_sent: alreadySent, new_customer_total: newCustomerTotal };
  } catch (e) {
    return { linked: false, error: String(e && e.message || e) };
  }
}

// POST /receipt-recon/confirm { id, wo_id? | no_wo:true, property_id?, amount, description,
// store, date }. wo_id is still the ordinary case and is validated as before. Brett, Sep
// 2026: a "company"/business-expense receipt (excluded from the normal WO flow, see
// receiptSuggestCore's category logic) has no work order at all — pass no_wo:true for that
// path; property_id is then optional too (Ridge Co overhead has no property; a receipt for
// Milam Ridge, which has no owner to bill, would carry property_id but still no wo_id).
async function receiptReconConfirm(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (row.Status === 'confirmed') return json({ error: 'already confirmed', id }, 409);
  const noWo = body.no_wo === true || String(body.no_wo).toUpperCase() === 'TRUE';
  const wo_id = body.wo_id || '';
  const property_id = body.property_id || '';
  if (!noWo && !wo_id) return json({ error: 'wo_id required (or pass no_wo:true for a business expense)' }, 400);
  // Validate the WO actually exists BEFORE writing anything. The manual "type a WO number to
  // override" field on the reconciler UI has no way to know if what was typed is real — a typo
  // (1054 vs 1045) would otherwise post a real Receipts row against a nonexistent or wrong job
  // with no error and no way to notice at the time. This is the actual defense; the frontend's
  // own live validation against the already-loaded WO list is just fast-fail UX on top of it.
  if (!noWo) {
    const workorders = await fetchTab(env, 'Work_Orders');
    if (!workorders.some(w => String(w.ID) === String(wo_id))) {
      return json({ error: `No work order with ID "${wo_id}" exists — check the number and try again.` }, 400);
    }
  }
  const amount = (body.amount !== undefined && body.amount !== null && body.amount !== '') ? body.amount : row.Total;
  const description = body.description || row.PO_Reference || row.Vendor || '';
  const store = body.store || row.Vendor || '';
  const date = body.date || row.Receipt_Date || '';
  let suggestion = null; try { suggestion = JSON.parse(row.Suggestion || 'null'); } catch (e) {}
  // Brett, Sep 22 2026: "attach receipts to Ridge Co and 1864 Kerns School Rd as an expense
  // rather than selecting a work order". A no-WO confirm is ALWAYS an expense record, even when
  // the scanner suggested 'billable' (a Home Depot receipt with a job address on it) — otherwise
  // it would sit in Receipts marked billable with nothing to bill it to.
  // Part 3 (Sep 22 2026 brief): a refund row (category 'refund' from receiptSuggestCore, or a
  // negative Total that predates this build) posted through the no-WO expense path is money
  // coming BACK — it stays category 'refund' (never folded into generic 'company') and the
  // amount is force-negated no matter what was typed/pre-filled, so a refund can never reach
  // addReceipt as a positive charge from this path.
  const isRefundRow = (suggestion && suggestion.category === 'refund') || Number(row.Total) < 0;
  const category = noWo ? (isRefundRow ? 'refund' : 'company') : ((suggestion && suggestion.category) || 'billable');
  const finalAmount = (noWo && isRefundRow) ? -Math.abs(Number(amount) || 0) : amount;
  const addResp = await addReceipt(env, {
    wo_id: wo_id || '', property_id, amount: finalAmount, description, store, date,
    added_by: 'Receipt Reconciler', added_by_id: 'receipt-recon', role: 'hub', category,
    source_file_id: row.Source_File_ID || '', source_file_url: row.Source_File_URL || '',
    payment_source: body.payment_source, allow_negative: (noWo && isRefundRow),
  });
  const addJson = await addResp.json().catch(() => ({}));
  let invoiceLink = null;
  if (addJson && addJson.success && !addJson.duplicate && wo_id && addJson.id) {
    // A signed scope proposal's WO is billed through its payment milestones — folding this
    // receipt into a pending Invoice_Review row would charge the customer for it a second time.
    // It still lands on the WO (counted in Signed Proposals' materials budget vs actual).
    let covered = null, coverErr = null;
    try { covered = await scopeCoveringSignatureForWO(env, wo_id); } catch (e) { coverErr = e; }
    if (covered) invoiceLink = { linked: false, reason: 'covered_by_signed_proposal', scope_id: covered.scope_id };
    else if (coverErr) invoiceLink = { linked: false, reason: 'scope_check_failed', error: String(coverErr && coverErr.message || coverErr) };
    else invoiceLink = await appendReceiptToInvoiceReview(env, { wo_id, receipt_id: addJson.id, amount });
  }
  if (addJson && addJson.success) {
    // Confirmed_Receipt_ID (Sep 23 2026 build): the actual Receipts row this confirmation wrote,
    // so a later Reassign / Mark-as-refund on this queue row can find and void the exact right
    // row instead of guessing from amount/store/date. Blank on a duplicate skip — nothing new
    // was written in that case.
    await updateRow(env, 'Receipt_Recon_Queue', id, {
      Status: addJson.duplicate ? 'skipped' : 'confirmed',
      Confirmed_WO_ID: wo_id, Confirmed_Amount: String(amount), Confirmed_Description: description,
      Confirmed_Receipt_ID: addJson.duplicate ? '' : String(addJson.id || ''),
      Notes: addJson.duplicate ? 'Auto-skipped — an identical receipt already exists on that WO.' : '',
    });
  }
  // Expense receipts go to QuickBooks' receipts inbox right away rather than waiting for the
  // 7am sweep (which only takes 8 a day) — Brett is clearing a backlog and wants each one done
  // when he taps it. Work-order receipts keep going through the normal daily sweep.
  let qbEmail = null;
  if (noWo && addJson && addJson.success && !addJson.duplicate && addJson.id) {
    try {
      const r = await sendReceiptsToQBEmail(env, { ids: [String(addJson.id)], limit: 1 });
      const j = await r.json().catch(() => ({}));
      qbEmail = { sent: (j.sent || 0) > 0, error: j.error || (j.failed && j.failed[0] && j.failed[0].error) || null };
    } catch (e) { qbEmail = { sent: false, error: String(e && e.message || e) }; }
  }
  return json({ ok: true, wo_id, property_id, ...addJson, invoice_link: invoiceLink, qb_email: qbEmail });
}

// POST /receipt/attach-only { id, wo_id, property_id?, amount?, description?, store?, date? } —
// Part 2 of the Sep 22 2026 dup/refund/bulk brief. The alternative Brett needs when a receipt is
// flagged as a possible duplicate (Part 1's "image attached?" indicator, right below) but the
// image itself was never actually filed anywhere: attach it to the matched WO WITHOUT billing it
// a second time. Reuses ONLY the file-attach half of the normal confirm flow — addReceipt(),
// which writes Source_File_ID/Source_File_URL onto the new Receipts row (confirmed live as the
// REAL column names on Receipts, not the brief's guessed File_Url/Drive_File_Id — PAT-024; see
// addReceipt above). Deliberately does NOT call appendReceiptToInvoiceReview (the billing half
// receiptReconConfirm uses to fold a receipt into a pending customer invoice) and does NOT call
// sendReceiptsToQBEmail — addReceipt itself never touches Vendor_Bills or Invoice_Review, and
// this function adds nothing that would. Verified by test/receipt-attach-only.test.mjs, not just
// by this comment (Brett's standing rule: don't just assert a no-billing-side-effect claim).
//
// Category 'attached_only' is a NEW Receipts.Category value (checked the existing enum first —
// 'billable'/'company'/'customer_paid'/'refund' — none of them mean "image on file, deliberately
// never billed", so a new value is the right call here, not a misuse of an existing one). Marks
// the row so it's never re-suggested for billing and shows up in the Reconciler's own history —
// the Receipt_Recon_Queue row gets the matching Status 'attached_only' (excluded from the default
// ?status=pending view, same as 'confirmed'/'skipped', and browsable via its own tab/status=all).
async function receiptAttachOnly(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const wo_id = body.wo_id; if (!wo_id) return json({ error: 'wo_id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (['confirmed', 'attached_only'].includes(row.Status)) return json({ error: `already ${row.Status}`, id }, 409);
  // Same pre-write existence check receiptReconConfirm uses — a typo'd WO number must never
  // silently post a real Receipts row against a nonexistent job.
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = workorders.find(w => String(w.ID) === String(wo_id));
  if (!wo) return json({ error: `No work order with ID "${wo_id}" exists — check the number and try again.` }, 400);
  if (!row.Source_File_ID && !row.Source_File_URL) {
    return json({ error: 'This queue row has no scanned image on file — nothing to attach.' }, 400);
  }
  const property_id = body.property_id || wo.Property_ID || '';
  const amount = (body.amount !== undefined && body.amount !== null && body.amount !== '') ? body.amount : row.Total;
  const description = body.description || row.PO_Reference || row.Vendor || '';
  const store = body.store || row.Vendor || '';
  const date = body.date || row.Receipt_Date || '';
  const addResp = await addReceipt(env, {
    wo_id, property_id, amount, description, store, date,
    added_by: 'Receipt Reconciler (attach only)', added_by_id: 'receipt-recon-attach-only', role: 'hub',
    category: 'attached_only',
    source_file_id: row.Source_File_ID || '', source_file_url: row.Source_File_URL || '',
    payment_source: body.payment_source,
  });
  const addJson = await addResp.json().catch(() => ({}));
  if (addJson && addJson.success) {
    await updateRow(env, 'Receipt_Recon_Queue', id, {
      Status: 'attached_only', Confirmed_WO_ID: wo_id, Confirmed_Amount: String(amount), Confirmed_Description: description,
      Notes: addJson.duplicate ? 'Image already attached to that WO — not re-attached.' : 'Image attached only — not billed, no invoice line added.',
    });
  }
  return json({ ok: true, wo_id, property_id, attached_only: true, ...addJson });
}

// Receipt-date cutoff (Brett, Sep 22 2026: "exclude items that go back to 2025 and 2023").
// Old receipts reach the queue when paper receipts get scanned into the folder (e.g. a Jun 2025
// Surplus City receipt scanned Aug 26 2026) — the email pull never goes before Jul 1. Anything
// dated before the cutoff is queued as SKIPPED with a plain note instead of landing in Pending,
// and is one tap from coming back (↩ Move back to Pending). Config key receipt_recon_min_date
// (yyyy-mm-dd); blank/missing = 2026-07-01, matching the email backfill start.
const RECEIPT_RECON_MIN_DATE_DEFAULT = '2026-07-01';
function receiptReconCutoff(cfg) {
  const v = String((cfg && cfg.receipt_recon_min_date) || '').trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : RECEIPT_RECON_MIN_DATE_DEFAULT;
}
function receiptBeforeCutoff(receiptDate, cutoff) {
  const d = String(receiptDate || '').trim();
  return /^\d{4}-\d{2}-\d{2}/.test(d) && d.slice(0, 10) < cutoff;   // no/garbled date = keep it in Pending, never hide it
}
function receiptCutoffNote(receiptDate, cutoff) {
  return `Receipt dated ${String(receiptDate).slice(0, 10)} is before the ${cutoff} cutoff — skipped automatically. Tap "Move back to Pending" if you need it.`;
}

// POST /receipt-recon/skip-before-cutoff { dry_run? } — one-time cleanup of pending rows that
// predate the cutoff (they were queued before the cutoff existed). Skips only; writes nothing
// else, and every row it touches can be moved back with /receipt-recon/unskip.
async function receiptReconSkipBeforeCutoff(env, body) {
  const cfg = await fetchConfig(env).catch(() => ({}));
  const cutoff = receiptReconCutoff(cfg);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const hits = rows.filter(r => String(r.Active || '').toUpperCase() !== 'FALSE' && (r.Status || 'pending') === 'pending' && receiptBeforeCutoff(r.Receipt_Date, cutoff));
  const list = hits.map(r => ({ id: r.ID, date: r.Receipt_Date, total: r.Total, vendor: r.Vendor }));
  if (body && body.dry_run) return json({ ok: true, dry_run: true, cutoff, would_skip: list.length, rows: list });
  for (const r of hits) await updateRow(env, 'Receipt_Recon_Queue', r.ID, { Status: 'skipped', Notes: receiptCutoffNote(r.Receipt_Date, cutoff) });
  return json({ ok: true, cutoff, skipped: list.length, rows: list });
}

// POST /receipt-recon/unskip { id } — undo a Skip (Sep 22 2026; before this a skipped receipt
// could never come back). Only moves skipped → pending; confirmed/duplicate rows are untouched.
async function receiptReconUnskip(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (row.Status !== 'skipped') return json({ error: `Only a skipped receipt can be moved back (this one is "${row.Status || 'pending'}").` }, 409);
  await updateRow(env, 'Receipt_Recon_Queue', id, { Status: 'pending', Notes: '' });
  return json({ ok: true, id });
}

// POST /receipt-recon/skip { id, reason? } — dismiss without billing anything.
async function receiptReconSkip(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  await updateRow(env, 'Receipt_Recon_Queue', id, { Status: 'skipped', Notes: body.reason || '' });
  return json({ ok: true, id });
}

// POST /receipt-recon/confirm-duplicate { id } — a DISTINCT resolution from generic Skip
// (Brett, Aug 23): confirming "yes, this really is a duplicate" is a different judgment than
// "skip for some other reason" (no match, bad data, needs research), and lumping both into one
// undifferentiated 'skipped' status meant a real duplicate could never be told apart from
// something that still needed a human decision. Writes NOTHING to Receipts — this only marks the
// judgment as made. Stamps Duplicate_Confirmed_Date so the 180-day retention sweep
// (purgeConfirmedDuplicateReceipts, below) knows when the clock started.
async function receiptReconConfirmDuplicate(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (row.Status === 'duplicate_confirmed') return json({ ok: true, id, already: true });
  // A specific reason from a matched evidence signal (see receiptCheckDuplicatesOne) is far
  // more useful on later reference than the generic note — Brett's own "there may be reason to
  // reference it later" ask. Falls back to the original generic wording when confirmed the old
  // way (from the same-WO-only flag, with no cross-source evidence attached).
  const reason = String(body.reason || '').trim();
  await updateRow(env, 'Receipt_Recon_Queue', id, {
    Status: 'duplicate_confirmed', Duplicate_Confirmed_Date: new Date().toISOString(),
    Notes: (reason ? reason + ' ' : '') + 'Confirmed duplicate by Brett — not billed. Auto-purges from the queue after 180 days.',
  });
  return json({ ok: true, id, status: 'duplicate_confirmed' });
}

// POST /receipt-recon/bulk-action { ids:[...], action, property_id?, reason? } — Part 4 of the
// Sep 22 2026 dup/refund/bulk brief (bulk checkboxes on the Reconciler). One dispatch endpoint,
// matching the /wo/combine-style batched-write convention already used in this file, rather than
// a separate endpoint per action. Deliberately does NOT reimplement any of the four actions —
// it fans each id out to the SAME single-row handler the Reconciler's own row buttons already
// call, so a bulk action behaves byte-for-byte like N taps of the existing button, with the same
// guardrails (e.g. only a 'skipped' row can move back to pending; a no-WO confirm is always an
// expense; a confirm-duplicate on an already-duplicate row is a harmless no-op):
//   mark_duplicate   -> receiptReconConfirmDuplicate (same status the single "Confirm duplicate"
//                        button writes: 'duplicate_confirmed')
//   expense          -> receiptReconConfirm({ no_wo:true, property_id }) — PR #23's one-tap
//                        expense flow, applied to the whole batch against ONE property choice
//                        (Ridge Co: property_id ''; 1864 Kerns School Rd: its real property id,
//                        resolved client-side by kernsProperty() exactly like the single-tap
//                        buttons already do — no new property lookup here).
//   move_to_pending  -> receiptReconUnskip — PR #24's single-row ↩ undo; only ever moves a
//                        'skipped' row back to 'pending', so an id that isn't currently skipped
//                        lands in `failed` with that handler's own real error, same as tapping
//                        the single-row button on it would.
//   skip             -> receiptReconSkip
// Respects the Cloudflare subrequest cap the same way /admin/share-attachments' limit/offset
// does: only the first RECEIPT_BULK_ACTION_MAX ids are processed per call; the rest come back as
// remaining_ids for the client to call again with (same "click again to continue" shape as the
// Reconciler's own runFullAudit loop), rather than looping unbounded server-side in one request.
const RECEIPT_BULK_ACTIONS = ['mark_duplicate', 'expense', 'move_to_pending', 'skip'];
const RECEIPT_BULK_ACTION_MAX = 20;
async function receiptReconBulkAction(env, body) {
  body = body || {};
  const action = String(body.action || '');
  if (!RECEIPT_BULK_ACTIONS.includes(action)) {
    return json({ error: `action must be one of: ${RECEIPT_BULK_ACTIONS.join(', ')}` }, 400);
  }
  const allIds = [...new Set((Array.isArray(body.ids) ? body.ids : []).map(x => String(x || '')).filter(Boolean))];
  if (!allIds.length) return json({ error: 'ids required (array)' }, 400);
  // property_id may legitimately be '' (Ridge Co overhead, no property) — only reject when the
  // key is missing entirely, same as receiptReconConfirm's own no_wo validation shape.
  if (action === 'expense' && body.property_id === undefined) {
    return json({ error: "property_id required for expense (pass '' for Ridge Co / general overhead)" }, 400);
  }
  const batch = allIds.slice(0, RECEIPT_BULK_ACTION_MAX);
  const remaining = allIds.slice(RECEIPT_BULK_ACTION_MAX);

  const succeeded = [], failed = [];
  for (const id of batch) {
    try {
      let res;
      if (action === 'mark_duplicate') res = await receiptReconConfirmDuplicate(env, { id, reason: body.reason || '' });
      else if (action === 'expense') res = await receiptReconConfirm(env, { id, no_wo: true, property_id: body.property_id || '' });
      else if (action === 'move_to_pending') res = await receiptReconUnskip(env, { id });
      else res = await receiptReconSkip(env, { id, reason: body.reason || 'bulk skip from Receipt Reconciler' });
      const resJson = await res.json().catch(() => ({}));
      if (resJson && resJson.error) failed.push({ id, error: resJson.error });
      else succeeded.push({ id, result: resJson });
    } catch (e) {
      failed.push({ id, error: String(e && e.message || e) });
    }
  }
  return json({
    ok: true, action, processed: batch.length,
    succeeded, failed,
    remaining_ids: remaining, remaining: remaining.length,
  });
}

// POST /receipt-recon/refund-candidates { id } — READ-ONLY. Part 3 of the Sep 22 2026 brief.
// Given a refund row in Receipt_Recon_Queue, searches the Receipts tab for candidate ORIGINAL
// purchases it might be reversing (receiptRefundFindMatches, pure/unit-tested above) and returns
// them for Brett to eyeball — store/date/amount/description, ranked, never a verdict. Writes
// nothing. The UI calls this on demand (same on-demand convention as checkDuplicatesOne), not
// embedded in every queue-list render, to keep GET /receipt-recon/queue cheap.
async function receiptReconRefundCandidates(env, body) {
  body = body || {};
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  let suggestion = null; try { suggestion = JSON.parse(row.Suggestion || 'null'); } catch (e) {}
  let items = []; try { items = JSON.parse(row.Items || '[]'); } catch (e) {}
  const receipts = await fetchTab(env, 'Receipts');
  const candidates = receiptRefundFindMatches({ store: row.Vendor, amount: row.Total, date: row.Receipt_Date, items }, receipts);
  return json({ ok: true, id, refund: { store: row.Vendor || '', amount: row.Total || '', date: row.Receipt_Date || '', items }, candidates });
}

// POST /receipt-recon/refund-reverse { id, receipt_id, reason, preview_only? } — Rung-3 money
// write (AUTONOMY_GUARDRAILS): reverses the billed amount of an earlier purchase to credit a
// refund against it. Same admin-gated / Brett-taps-Confirm shape as every other QuickBooks/
// customer-invoice write in this file (see scopeProposalAdjustBill) — this path is NOT in
// PUBLIC_PATHS or any ROLE_SCOPES entry, so it requires the admin secret exactly like every
// other write here, and it is never called from receiptExtract/receiptSuggestCore/receiptReconScan
// detection or matching — only from the Reconciler UI's own explicit "This matches — reverse the
// billed amount" button tap, after Brett has reviewed receiptReconRefundCandidates' suggestions.
//
// What "reverse" means concretely: writes a NEW negative Receipts row on the SAME WO as the
// original purchase (reusing addReceipt with allow_negative:true — the exact mechanism every
// other Receipts write in this file uses, not a bespoke QuickBooks call), then folds it into the
// same pending Invoice_Review row the original purchase's receipt was folded into via
// appendReceiptToInvoiceReview (now negative-delta aware — see its own comment), crediting the
// customer's pending invoice back down by the refunded amount. If that invoice was already sent
// to QuickBooks, appendReceiptToInvoiceReview's existing Repair_Flagged convention picks it up
// exactly like a receipt added after the fact does — Brett pushes the correction himself via the
// existing Repairable Invoices path, same as every other post-send correction in this app. The
// Receipts row itself is always written regardless of whether the Invoice_Review fold succeeds —
// it's the audit-trail source of truth even if the pending invoice couldn't safely absorb the
// full credit (see 'would_go_negative').
async function receiptReconRefundReverse(env, body) {
  body = body || {};
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const receiptId = body.receipt_id; if (!receiptId) return json({ error: 'receipt_id required — pick the original purchase this refund matches' }, 400);
  const reason = String(body.reason || '').trim();
  if (!reason) return json({ error: 'A reason is required — it goes on the reversing Receipts row, not just in the Hub.' }, 400);

  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (['confirmed', 'attached_only', 'refund_reversed'].includes(row.Status)) return json({ error: `already ${row.Status}`, id }, 409);
  let suggestion = null; try { suggestion = JSON.parse(row.Suggestion || 'null'); } catch (e) {}
  const isRefundRow = (suggestion && suggestion.category === 'refund') || Number(row.Total) < 0;
  if (!isRefundRow) return json({ error: 'This queue row is not flagged as a refund.' }, 400);

  const receipts = await fetchTab(env, 'Receipts');
  const original = receipts.find(r => String(r.ID) === String(receiptId) && r.Active !== 'FALSE');
  if (!original) return json({ error: `No active Receipts row with ID "${receiptId}" found.` }, 404);
  if (!original.WO_ID) return json({ error: 'That original receipt has no WO_ID — nothing to reverse a bill against.' }, 400);

  const reverseAmount = -Math.abs(Number(row.Total) || 0);
  if (!reverseAmount) return json({ error: 'This refund has no usable amount — fix the Total on the queue row first.' }, 400);

  const preview = {
    queue_id: id, original_receipt_id: original.ID, wo_id: original.WO_ID, property_id: original.Property_ID || '',
    original_amount: Number(original.Amount) || 0, reverse_amount: reverseAmount,
    store: row.Vendor || original.Store || '', date: row.Receipt_Date || '', reason,
  };
  if (body.preview_only) return json({ ok: true, preview });

  const addResp = await addReceipt(env, {
    wo_id: original.WO_ID, property_id: original.Property_ID || '', amount: reverseAmount,
    description: `REFUND — reverses receipt #${original.ID} (${reason})`.slice(0, 500),
    store: row.Vendor || original.Store || '', date: row.Receipt_Date || new Date().toISOString().split('T')[0],
    added_by: 'Receipt Reconciler (refund reverse)', added_by_id: 'receipt-recon-refund-reverse', role: 'hub',
    category: 'refund', source_file_id: row.Source_File_ID || '', source_file_url: row.Source_File_URL || '',
    payment_source: body.payment_source, allow_negative: true,
  });
  const addJson = await addResp.json().catch(() => ({}));
  let invoiceLink = null;
  if (addJson && addJson.success && !addJson.duplicate && addJson.id) {
    // Same signed-scope-proposal carve-out receiptReconConfirm uses: a job billed through
    // proposal milestones is never folded into Invoice_Review (it would double-count against
    // the milestone billing instead of the ordinary per-receipt invoice).
    let covered = null, coverErr = null;
    try { covered = await scopeCoveringSignatureForWO(env, original.WO_ID); } catch (e) { coverErr = e; }
    if (covered) invoiceLink = { linked: false, reason: 'covered_by_signed_proposal', scope_id: covered.scope_id };
    else if (coverErr) invoiceLink = { linked: false, reason: 'scope_check_failed', error: String(coverErr && coverErr.message || coverErr) };
    else invoiceLink = await appendReceiptToInvoiceReview(env, { wo_id: original.WO_ID, receipt_id: addJson.id, amount: reverseAmount });
  }
  if (addJson && addJson.success) {
    await updateRow(env, 'Receipt_Recon_Queue', id, {
      Status: 'refund_reversed', Confirmed_WO_ID: original.WO_ID, Confirmed_Amount: String(reverseAmount),
      Confirmed_Description: `Reverses receipt #${original.ID}`,
      Notes: `Confirmed match by Brett — reversed $${Math.abs(reverseAmount).toFixed(2)} against receipt #${original.ID} on WO ${original.WO_ID}. ${reason}`,
    });
  }
  return json({ ok: true, wo_id: original.WO_ID, original_receipt_id: original.ID, ...addJson, invoice_link: invoiceLink });
}

// ── Sep 23 2026 build: reassign a confirmed BMore/Ridge Co expense + manual refund marking ────
// Brett's three asks this session: (1) un-flip a receipt that was confirmed as a BMore/Ridge Co
// business expense (no work order) and rebill it to a property + work order instead, without
// losing the ability to flag receipts as BMore/Ridge Co in the first place; (2) a search over
// every processed receipt, so "did I already process this $101.28 receipt" can be checked
// directly instead of eyeballing tabs; (3) a way to manually mark a receipt as a refund when the
// automatic OCR-based detection (receiptExtract's refund_signal_text / negative-total check)
// misses one, including undoing a receipt that was already confirmed/expensed by mistake.
//
// Brett's own scoping answers (Sep 23 2026): reassigning/un-confirming only works while the
// original Receipts row hasn't been emailed to QuickBooks yet (QB_Email_Sent) — once QuickBooks
// has it, these refuse and tell him to fix it there directly rather than silently trying to
// unwind an already-sent expense. Reassign is an inline action on the confirmed card itself
// (not a "move back to Pending" reset). Converting an already-confirmed receipt to a refund
// reuses the existing Pending refund flow (find-match / negative-expense) rather than building a
// second, parallel refund-posting path — it voids the original (if eligible) and drops the row
// back into Pending with Manual_Refund set, which is exactly what the pending "Mark as refund"
// toggle also sets.

// Finds the real Receipts row a confirmed Receipt_Recon_Queue row actually wrote. Prefers the
// stored Confirmed_Receipt_ID (every confirm/reassign from this build forward sets it); falls
// back to signature matching (amount/store/date) for rows confirmed before that column existed.
async function findReceiptForQueueRow(env, row) {
  const receipts = await fetchTab(env, 'Receipts');
  if (row.Confirmed_Receipt_ID) {
    const hit = receipts.find(rc => String(rc.ID) === String(row.Confirmed_Receipt_ID));
    if (hit) return hit;
  }
  const amt = Number(row.Confirmed_Amount || row.Total || 0).toFixed(2);
  return receipts.find(rc => String(rc.Active || '').toUpperCase() !== 'FALSE'
    && Number(rc.Amount).toFixed(2) === amt
    && _rcNorm(rc.Store) === _rcNorm(row.Vendor)
    && String(rc.Date || '').slice(0, 10) === String(row.Receipt_Date || '').slice(0, 10)) || null;
}

// Symmetric with appendReceiptToInvoiceReview (which folds a receipt's dollar amount INTO the
// most-recent pending Invoice_Review row at confirm time) — this pulls it back OUT, wherever it
// actually landed. Sep 28 2026, Brett: "need to be able to reverse the amount added to the
// invoice/work order." Searches every Invoice_Review row for the one that actually holds this
// receipt_id (not just the most-recent-for-this-WO row appendReceiptToInvoiceReview would pick
// today — a later receipt or invoice cycle may have moved on since this one was confirmed), and
// strips the ID out of Own_Material_IDs rather than just subtracting the dollar amount: that
// function's own `ids.includes(receipt_id)` dedupe guard would otherwise treat a later correct
// re-confirm of the same receipt_id as "already: true" and silently skip re-adding it. Mirrors
// appendReceiptToInvoiceReview's own already-sent-to-QuickBooks handling (flag + note rather than
// blocking) rather than reinventing it.
async function removeReceiptFromInvoiceReview(env, { receipt_id, amount }) {
  if (!receipt_id) return { unlinked: false };
  try {
    await ensureColumns(env, 'Invoice_Review', ['Repair_Flagged', 'Repair_Reason']);
    const irs = await fetchTab(env, 'Invoice_Review');
    const ir = irs.find(r => String(r.Own_Material_IDs || '').split(',').map(x => x.trim()).includes(String(receipt_id)));
    if (!ir) return { unlinked: false, reason: 'not_found_in_invoice_review' };
    const ids = String(ir.Own_Material_IDs || '').split(',').map(x => x.trim()).filter(Boolean).filter(x => x !== String(receipt_id));
    const amt = +(Number(amount) || 0).toFixed(2);
    const newOwnMaterials = Math.max(0, +((Number(ir.Own_Materials) || 0) - amt).toFixed(2));
    const newCustomerTotal = Math.max(0, +((Number(ir.Customer_Total) || 0) - amt).toFixed(2));
    const alreadySent = !!(ir.QB_Invoice_ID || '').trim();
    const fields = { Own_Material_IDs: ids.join(','), Own_Materials: String(newOwnMaterials), Customer_Total: String(newCustomerTotal) };
    if (alreadySent) {
      fields.Repair_Flagged = 'TRUE';
      fields.Repair_Reason = `Receipt #${receipt_id} ($${amt.toFixed(2)}) removed ${new Date().toISOString().split('T')[0]} (reconciler undo) after the invoice was already sent — run Repairable Invoices to reconcile the QuickBooks total.`;
    }
    await updateRow(env, 'Invoice_Review', ir.ID, fields);
    return { unlinked: true, ir_id: ir.ID, already_sent: alreadySent, new_customer_total: newCustomerTotal };
  } catch (e) {
    return { unlinked: false, error: String(e && e.message || e) };
  }
}

// Voids the WO-gallery Attachments row Fix #2's addReceipt() wrote for a given Receipts row (via
// the Receipt_ID link column), so an undone/reversed receipt's image also disappears from the WO
// Attachments view (index.html + owner.html) — not just the invoice amount. Soft-delete, same
// Active:'FALSE' convention as everywhere else. A receipt with no gallery row (no WO, no scanned
// file, or confirmed before Fix #2 shipped) is a harmless no-op.
async function voidAttachmentForReceipt(env, receipt_id) {
  if (!receipt_id) return { voided: false };
  try {
    await ensureColumns(env, 'Attachments', ['Receipt_ID']);
    const atts = await fetchTab(env, 'Attachments');
    const hit = atts.find(a => String(a.Receipt_ID || '') === String(receipt_id) && String(a.Active || '').toUpperCase() !== 'FALSE');
    if (!hit) return { voided: false, reason: 'not_found' };
    await updateRow(env, 'Attachments', hit.ID, { Active: 'FALSE' });
    return { voided: true, attachment_id: hit.ID };
  } catch (e) {
    return { voided: false, error: String(e && e.message || e) };
  }
}

// Shared reversal core for /receipt-recon/mark-refund-confirmed AND the new /receipt-recon/undo
// below — voids the original Receipts row (same not-yet-emailed-to-QuickBooks guard Reassign
// uses), reverses its dollar contribution out of Invoice_Review, and voids the matching
// Attachments gallery row. Works unchanged for an 'attached_only' row too: removeReceiptFromInvoiceReview
// simply finds nothing to unlink (attach-only never calls appendReceiptToInvoiceReview in the
// first place), so it's a safe no-op rather than a special case.
async function voidConfirmedReceiptForQueueRow(env, row, noteTag) {
  await ensureColumns(env, 'Receipt_Recon_Queue', ['Confirmed_Receipt_ID', 'Manual_Refund']);
  const original = await findReceiptForQueueRow(env, row);
  if (!original) return { error: 'Could not find the original Receipts row for this confirmation — nothing was changed. Check the Receipts tab directly.', status: 404 };
  if (String(original.QB_Email_Sent || '').toUpperCase() === 'TRUE') {
    return { error: `This receipt was already emailed to QuickBooks on ${String(original.QB_Email_Sent_Date || '').slice(0, 10)} — fix it in QuickBooks directly rather than here (${noteTag === 'undone' ? 'undoing' : 'reversing'} it here would leave QuickBooks out of sync).`, status: 409 };
  }
  await updateRow(env, 'Receipts', original.ID, {
    Active: 'FALSE',
    Description: (original.Description || '') + ` [${noteTag} ${new Date().toISOString().slice(0, 10)} — pulled back into Receipt Reconciler for reversal]`,
  });
  const invoiceUnlink = await removeReceiptFromInvoiceReview(env, { receipt_id: original.ID, amount: Number(original.Amount || row.Confirmed_Amount || 0) });
  const attachmentVoid = await voidAttachmentForReceipt(env, original.ID);
  return { voidedId: original.ID, invoiceUnlink, attachmentVoid };
}

// POST /receipt-recon/reassign { id, wo_id?, property_id, amount?, description?, store?, date? }
// property_id is always required (even a "no work order, just fix the property" reassign needs
// one — that's still an expense, just a corrected one). wo_id is optional — omit it to leave this
// as an expense but move it off general Ridge Co overhead onto a specific property (or vice
// versa); include it to bill it to that work order like any other receipt.
async function receiptReconReassign(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const property_id = body.property_id || '';
  if (!property_id) return json({ error: 'property_id required' }, 400);
  const wo_id = body.wo_id || '';
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (row.Status !== 'confirmed') return json({ error: `only a confirmed row can be reassigned (this one is ${row.Status || 'pending'})` }, 409);

  if (wo_id) {
    const workorders = await fetchTab(env, 'Work_Orders');
    const wo = workorders.find(w => String(w.ID) === String(wo_id));
    if (!wo) {
      return json({ error: `No work order with ID "${wo_id}" exists — check the number and try again.` }, 400);
    }
    if (String(wo.Property_ID) !== String(property_id)) {
      return json({ error: `Work order ${wo_id} belongs to a different property than the one you're reassigning to (Property ${wo.Property_ID}, not ${property_id}) — check the property/WO pairing.` }, 400);
    }
  }

  await ensureColumns(env, 'Receipt_Recon_Queue', ['Confirmed_Receipt_ID', 'Manual_Refund']);
  const original = await findReceiptForQueueRow(env, row);
  if (!original) return json({ error: 'Could not find the original Receipts row for this confirmation — nothing was changed. Check the Receipts tab directly.' }, 404);
  if (String(original.QB_Email_Sent || '').toUpperCase() === 'TRUE') {
    return json({ error: `This receipt was already emailed to QuickBooks on ${String(original.QB_Email_Sent_Date || '').slice(0, 10)} — fix it in QuickBooks directly rather than here (reassigning would double it up).` }, 409);
  }

  const amount = (body.amount !== undefined && body.amount !== null && body.amount !== '') ? body.amount : (row.Confirmed_Amount || row.Total);
  const description = body.description || row.Confirmed_Description || row.PO_Reference || row.Vendor || '';
  const store = body.store || row.Vendor || '';
  const date = body.date || row.Receipt_Date || '';

  // Void the original expense row — same soft-delete pattern used everywhere else (Active:
  // 'FALSE'), never a hard delete, so it stays visible/auditable on the Receipts tab.
  await updateRow(env, 'Receipts', original.ID, {
    Active: 'FALSE',
    Description: (original.Description || '') + ` [reassigned ${new Date().toISOString().slice(0, 10)} — replaced by a new Receipts row on ` + (wo_id ? `WO ${wo_id}` : `Property ${property_id}`) + ']',
  });

  const category = wo_id ? 'billable' : 'company';
  const addResp = await addReceipt(env, {
    wo_id, property_id, amount, description, store, date,
    added_by: 'Receipt Reconciler (reassign)', added_by_id: 'receipt-recon-reassign', role: 'hub', category,
    source_file_id: row.Source_File_ID || '', source_file_url: row.Source_File_URL || '',
    payment_source: original.Payment_Source,
  });
  const addJson = await addResp.json().catch(() => ({}));

  let invoiceLink = null;
  if (addJson && addJson.success && !addJson.duplicate && wo_id && addJson.id) {
    let covered = null, coverErr = null;
    try { covered = await scopeCoveringSignatureForWO(env, wo_id); } catch (e) { coverErr = e; }
    if (covered) invoiceLink = { linked: false, reason: 'covered_by_signed_proposal', scope_id: covered.scope_id };
    else if (coverErr) invoiceLink = { linked: false, reason: 'scope_check_failed', error: String(coverErr && coverErr.message || coverErr) };
    else invoiceLink = await appendReceiptToInvoiceReview(env, { wo_id, receipt_id: addJson.id, amount });
  }

  // Same "expense goes to QuickBooks right away" behavior receiptReconConfirm already uses for a
  // no-WO receipt (Sep 22 2026) — a WO-bound reassign follows the normal daily sweep instead.
  let qbEmail = null;
  if (!wo_id && addJson && addJson.success && !addJson.duplicate && addJson.id) {
    try {
      const r = await sendReceiptsToQBEmail(env, { ids: [String(addJson.id)], limit: 1 });
      const j = await r.json().catch(() => ({}));
      qbEmail = { sent: (j.sent || 0) > 0, error: j.error || (j.failed && j.failed[0] && j.failed[0].error) || null };
    } catch (e) { qbEmail = { sent: false, error: String(e && e.message || e) }; }
  }

  if (addJson && addJson.success) {
    await updateRow(env, 'Receipt_Recon_Queue', id, {
      Confirmed_WO_ID: wo_id, Confirmed_Amount: String(amount), Confirmed_Description: description,
      Confirmed_Receipt_ID: String(addJson.id || row.Confirmed_Receipt_ID || ''),
      Notes: `Reassigned ${new Date().toISOString().slice(0, 10)} from a BMore/Ridge Co expense to ` + (wo_id ? `WO ${wo_id}` : `Property ${property_id}`) + '.',
    });
  }

  return json({ ok: true, wo_id, property_id, voided_receipt_id: original.ID, ...addJson, invoice_link: invoiceLink, qb_email: qbEmail });
}

// POST /receipt-recon/mark-refund { id, refund } — manual override for a PENDING receipt the
// automatic refund detection missed or got wrong. Never touches Receipts — a pending row hasn't
// billed anything yet — just flips the flag GET /receipt-recon/queue reads to decide which card
// (normal vs refund) to render. refund:false undoes it and restores the scanner's own original
// category, since the underlying Suggestion JSON is never modified.
async function receiptReconMarkRefund(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if ((row.Status || 'pending') !== 'pending') return json({ error: `only a pending row can be toggled this way (this one is ${row.Status})` }, 409);
  const refund = body.refund !== false;
  await ensureColumns(env, 'Receipt_Recon_Queue', ['Manual_Refund']);
  await updateRow(env, 'Receipt_Recon_Queue', id, { Manual_Refund: refund ? 'TRUE' : 'FALSE' });
  return json({ ok: true, id, manual_refund: refund });
}

// POST /receipt-recon/mark-refund-confirmed { id } — undo a receipt that was wrongly confirmed
// or expensed and route it into the refund flow instead. Reuses the exact Pending refund UI
// (find matching purchase / post as a negative expense) rather than a second parallel posting
// path: if it was actually billed (Status 'confirmed'), the original Receipts row is voided
// (same not-yet-sent-to-QuickBooks guard as reassign above), its dollar amount is pulled back OUT
// of whatever Invoice_Review row it was folded into, and its WO-gallery Attachments row is voided
// too (Sep 28 2026 fix — voidConfirmedReceiptForQueueRow — this used to only void the Receipts
// row itself and silently leave the amount sitting on the customer invoice and the image sitting
// in the gallery). The queue row drops back to Pending with Manual_Refund set. An 'attached_only'
// row never billed anything in the first place (see receiptAttachOnly) — voidConfirmedReceiptForQueueRow
// still runs for it (harmless no-op on the Invoice_Review side) so its gallery attachment is voided too.
async function receiptReconMarkRefundConfirmed(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (!['confirmed', 'attached_only'].includes(row.Status)) return json({ error: `only a confirmed or attached-only receipt can be marked as a refund this way (this one is ${row.Status || 'pending'})` }, 409);

  const result = await voidConfirmedReceiptForQueueRow(env, row, 'marked refund');
  if (result.error) return json({ error: result.error }, result.status);

  await updateRow(env, 'Receipt_Recon_Queue', id, {
    Status: 'pending', Manual_Refund: 'TRUE',
    Confirmed_WO_ID: '', Confirmed_Amount: '', Confirmed_Description: '', Confirmed_Receipt_ID: '',
    Notes: `Marked as a refund ${new Date().toISOString().slice(0, 10)} — was ${row.Status}.`,
  });
  return json({ ok: true, id, voided_receipt_id: result.voidedId, invoice_unlink: result.invoiceUnlink, attachment_void: result.attachmentVoid });
}

// POST /receipt-recon/undo { id } — Sep 28 2026, Brett: "need to make it reversible... need to be
// able to reverse the amount added to the invoice/work order plus reverse the attachment of the
// image/pdf/file. this can live in the receipts reconciler." Two named use cases: a mistaken
// confirm, or a duplicate that slipped through unnoticed. Deliberately distinct from Mark-as-
// refund above — that one assumes money is genuinely coming back and routes the row into the
// refund-posting flow (Manual_Refund: TRUE). Undo makes no assumption about why: it cleanly
// unwinds everything the confirm/attach-only wrote (voids the Receipts row, pulls its amount back
// out of Invoice_Review, voids its Attachments gallery row) and drops the queue row back to a
// plain, unflagged Pending — ready to be re-confirmed correctly, or marked a duplicate via the
// existing /receipt-recon/confirm-duplicate flow. Same not-yet-emailed-to-QuickBooks guard as
// Reassign/Mark-refund-confirmed — once QuickBooks already has it, this refuses and points at
// QuickBooks directly rather than silently leaving it out of sync.
async function receiptReconUndo(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  const rows = await fetchTab(env, 'Receipt_Recon_Queue');
  const row = rows.find(r => String(r.ID) === String(id));
  if (!row) return json({ error: 'queue row not found' }, 404);
  if (!['confirmed', 'attached_only'].includes(row.Status)) return json({ error: `only a confirmed or attached-only receipt can be undone (this one is ${row.Status || 'pending'})` }, 409);

  const result = await voidConfirmedReceiptForQueueRow(env, row, 'undone');
  if (result.error) return json({ error: result.error }, result.status);

  await ensureColumns(env, 'Receipt_Recon_Queue', ['Manual_Refund']);
  await updateRow(env, 'Receipt_Recon_Queue', id, {
    Status: 'pending', Manual_Refund: 'FALSE',
    Confirmed_WO_ID: '', Confirmed_Amount: '', Confirmed_Description: '', Confirmed_Receipt_ID: '',
    Notes: `Undone ${new Date().toISOString().slice(0, 10)} — was ${row.Status}. Re-confirm it correctly, or use "Confirm duplicate" if it turns out to be one.`,
  });
  return json({ ok: true, id, voided_receipt_id: result.voidedId, invoice_unlink: result.invoiceUnlink, attachment_void: result.attachmentVoid });
}

// GET /receipt-recon/search?q=<amount|store|description text>&date=<yyyy-mm-dd> — Brett, Sep 23
// 2026: "let me manually check whether I already processed this receipt" (he keeps hitting cases
// where no duplicate flag comes back but he's fairly sure he already handled one). Searches the
// canonical Receipts ledger, not just this session's own queue — that's the real record of what
// actually got billed/expensed/refunded/attached, including anything entered outside the
// Reconciler (vendor-submitted, manually keyed, older pre-Reconciler receipts). Read-only.
async function receiptReconSearch(env, url) {
  const qRaw = (url.searchParams.get('q') || '').trim();
  const dateParam = (url.searchParams.get('date') || '').trim();
  if (!qRaw && !dateParam) return json({ error: 'q or date required' }, 400);
  let rows = []; try { rows = await fetchTab(env, 'Receipts'); } catch (e) { return json({ error: String(e && e.message || e) }, 500); }
  const qNorm = _rcNorm(qRaw);
  // A bare number is very likely an amount search ("$101.28" / "101.28") — match it against
  // Amount with cent-level tolerance, in addition to the normal text match, so Brett doesn't have
  // to strip the $ or guess how it's formatted.
  const qAmount = parseFloat(qRaw.replace(/[^0-9.\-]/g, ''));
  const hasAmount = qRaw.replace(/[^0-9.]/g, '').length > 0 && !isNaN(qAmount);

  let properties = [], workorders = [];
  try { properties = await fetchTab(env, 'Properties'); } catch (e) {}
  try { workorders = await fetchTab(env, 'Work_Orders'); } catch (e) {}
  const propById = new Map(properties.map(p => [String(p.ID), p]));
  const woById = new Map(workorders.map(w => [String(w.ID), w]));

  const results = rows.filter(r => {
    if (dateParam && String(r.Date || '').slice(0, 10) !== dateParam) return false;
    if (!qRaw) return true;
    if (hasAmount && Math.abs(Number(r.Amount) - qAmount) < 0.01) return true;
    const blob = _rcNorm([r.Store, r.Description, r.WO_ID, r.Property_ID].filter(Boolean).join(' '));
    return !!(qNorm && blob.indexOf(qNorm) >= 0);
  }).map(r => {
    const prop = r.Property_ID ? propById.get(String(r.Property_ID)) : null;
    const wo = r.WO_ID ? woById.get(String(r.WO_ID)) : null;
    return {
      id: r.ID, amount: r.Amount, store: r.Store, description: r.Description, date: r.Date,
      category: r.Category, active: String(r.Active || '').toUpperCase() !== 'FALSE',
      wo_id: r.WO_ID || '', wo_description: wo ? (wo.Description || '') : '',
      property_id: r.Property_ID || '', property_address: prop ? (prop.Address || '') : '',
      qb_email_sent: String(r.QB_Email_Sent || '').toUpperCase() === 'TRUE',
      qb_email_sent_date: r.QB_Email_Sent_Date || '', created_date: r.Created_Date || '',
      added_by: r.Added_By || '', source_file_url: r.Source_File_URL || '',
    };
  }).sort((a, b) => new Date(b.date || b.created_date || 0) - new Date(a.date || a.created_date || 0));

  return json({ ok: true, count: results.length, results: results.slice(0, 200) });
}

// POST /admin/seed-test-receipt { wo_id?, total?, vendor?, receipt_date? } — Sep 23 2026, test-
// infra fix. A real Receipt_Recon_Queue row only ever arrives via receiptReconScan() pulling a
// file out of Drive — there was no way to get a testable PENDING row onto staging for
// hub_test_post smoke tests of confirm/reassign/mark-refund. This creates one directly,
// self-scoped to TEST-PROPERTY-001 (no TEST_MARKER_FIELD entry exists for Receipt_Recon_Queue
// itself, same limitation noted on receiptAttachOnly's guard above, so scoping happens here at
// creation time instead of being checked afterward). If wo_id is given it must already belong to
// TEST-PROPERTY-001 — this never creates a Work_Orders row of its own, only reuses one. Staging-
// only by construction, same as seedTestFixtures.
async function seedTestReceipt(env, url, body) {
  if (!isStaging(env, url)) return json({ error: 'seed-test-receipt only runs on staging' }, 403);
  const properties = await fetchTab(env, 'Properties');
  const testProp = properties.find(p => String(p.Access_Notes || '') === 'TEST-PROPERTY-001');
  if (!testProp) return json({ error: 'TEST-PROPERTY-001 not seeded — call /admin/seed-test-fixtures first' }, 400);

  let woId = '';
  if (body && body.wo_id) {
    const wos = await fetchTab(env, 'Work_Orders');
    const wo = wos.find(w => String(w.ID) === String(body.wo_id));
    if (!wo || String(wo.Property_ID) !== String(testProp.ID)) {
      return json({ error: 'wo_id, if given, must already belong to TEST-PROPERTY-001' }, 400);
    }
    woId = wo.ID;
  }

  await ensureTab(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);
  await ensureColumns(env, 'Receipt_Recon_Queue', RECEIPT_RECON_QUEUE_HEADERS);

  const total = (body && body.total !== undefined && body.total !== null && body.total !== '') ? String(body.total) : '12.34';
  const vendor = (body && body.vendor) ? String(body.vendor) : 'TEST-VENDOR-001';
  const receiptDate = (body && body.receipt_date) ? String(body.receipt_date) : new Date().toISOString().slice(0, 10);
  const suggestion = { property_id: testProp.ID, wo_id: woId || undefined, confidence: 'test' };

  const addRes = await (await addRow(env, 'Receipt_Recon_Queue', {
    Source_File_ID: 'TEST-SEEDED-' + Date.now(), Source_File_URL: '', File_Name: 'test-seed-receipt.png',
    Received_Date: new Date().toISOString(), Vendor: vendor, Receipt_Date: receiptDate,
    Total: total, PO_Reference: woId || '', Items: '[]', Items_Summary: '[]', Card_Last4: '', Invoice_Number: '',
    Suggestion: JSON.stringify(suggestion), Status: 'pending',
    Confirmed_WO_ID: '', Confirmed_Amount: '', Confirmed_Description: '', Notes: 'Seeded by /admin/seed-test-receipt for HUB_TEST_TOKEN smoke tests — safe to ignore/delete.',
    Active: 'TRUE', Duplicate_Confirmed_Date: '', Duplicate_Evidence_JSON: '', Duplicate_Checked_Date: '',
    Gmail_Message_ID: '', Entry_Source: 'test_seed', Rescan_Match_JSON: '', Confirmed_Receipt_ID: '', Manual_Refund: 'FALSE',
  })).json();

  return json({
    ok: true, id: addRes.id, property_id: testProp.ID, wo_id: woId || null,
    total, vendor, receipt_date: receiptDate,
    note: 'Call again anytime — each call creates a fresh pending row (not idempotent like seed-test-fixtures, since a receipt queue is naturally many rows).',
  });
}

const DUPLICATE_RETENTION_DAYS = 180;

// PURE — is this queue row due for the 180-day retention purge right now? Factored out of
// purgeConfirmedDuplicateReceipts so the date-math edge cases (missing/invalid stamp, exactly-at-
// cutoff, already-purged) are unit-testable without mocking Sheets I/O.
function receiptDuplicatePurgeDue(row, nowMs, retentionDays) {
  if (!row || row.Status !== 'duplicate_confirmed') return false;
  if (String(row.Active || '').toUpperCase() === 'FALSE') return false;
  const stamped = Date.parse(row.Duplicate_Confirmed_Date || '');
  if (!stamped || isNaN(stamped)) return false;
  const cutoff = nowMs - retentionDays * 24 * 60 * 60 * 1000;
  return stamped <= cutoff;
}

// POST /receipt-recon/purge-duplicates (also called by the daily cron) — soft-deletes any
// confirmed-duplicate row older than DUPLICATE_RETENTION_DAYS. Soft-delete only (Active:'FALSE'),
// never a hard delete — matches the house rule (CAP-020's Contacts-sync blanking is the same
// pattern): the row stays for audit trail, it just drops out of every 'pending'/'all' view that
// filters on Active. Read-then-write, best-effort per row so one bad date doesn't kill the sweep.
async function purgeConfirmedDuplicateReceipts(env) {
  let rows = []; try { rows = await fetchTab(env, 'Receipt_Recon_Queue'); } catch (e) { return json({ ok: false, error: String(e && e.message || e) }, 500); }
  const now = Date.now();
  let purged = 0; const errs = [];
  for (const r of rows) {
    if (!receiptDuplicatePurgeDue(r, now, DUPLICATE_RETENTION_DAYS)) continue;
    try { await updateRow(env, 'Receipt_Recon_Queue', r.ID, { Active: 'FALSE' }); purged++; }
    catch (e) { errs.push(String(r.ID) + ': ' + (e.message || 'err')); }
  }
  return json({ ok: true, purged, checked: rows.length, errors: errs });
}

// ══════════════════════════════════════════════════════════════════════════
// SCOPE CREATOR (B-030/031/076) — the workflow: raw notes → organized Scope of
// Work → WO (request for estimate, unassigned) → capture the vendor's estimate
// onto the scope → generate the CUSTOMER proposal from scope+estimate. Inputs
// are typed / voiced text, an uploaded handwriting photo (OCR), or a file picked
// from Brett's handwriting-scan Drive folder. Editable at every stage — both
// direct edits AND natural-language commands ("remove the plumbing section").
// Splittable into per-vendor scopes. Reuses the Receipt-Reconciler Claude-vision
// OCR pattern, the New-WO flow (createWorkOrder), the photo pipeline, and
// calcTieredEstimate for the proposal. HARD RULE: markup is applied SERVER-SIDE
// only and only FINAL customer prices ever leave scopeProposal — never cost,
// markupPct, or the derivation. (Brett's #1 non-negotiable.)
// ══════════════════════════════════════════════════════════════════════════
const SCOPES_HEADERS = ['ID','Property_ID','Unit_ID','Room','Title','Status','Raw_Input','Line_Items','Source_Refs','Parent_Scope_ID','WO_ID','Vendor_ID','Estimate_Number','Estimate_Amount','Estimate_Notes','Proposal_Text','Created_By','Created_Date','Updated_Date','Notes','Active'];
// Brett's handwriting scan Drive folder (scan-intake/processed.json). Overridable via
// Config key `scope_scan_folder_id` or env SCOPE_SCAN_FOLDER_ID. NOTE: the Worker runtime
// service account must be shared (Editor) on this folder or the Drive list returns 0 rows.
const SCOPE_SCAN_FOLDER_DEFAULT = '1iXjjwsnPKF_GtlR8gesxS9uJppO4xntZ';

async function scopesTab(env) { await ensureTab(env, 'Scopes', SCOPES_HEADERS); }
function scopeParseItems(s) { try { const a = JSON.parse((s && s.Line_Items) || '[]'); return Array.isArray(a) ? a : []; } catch (_) { return []; } }
// Normalizes an item's pricing into a `variants` array — 1 entry = single fixed vendor cost,
// 2+ entries = a customer CHOICE (e.g. "Repair Roof" vs "Replace Roof"; Brett, Aug 19 2026:
// "options within scope such as repair or replace roof... may be options where other items
// only have 1 option"). Backward compatible with pre-variant items that only ever carried a
// bare description (no price yet) — those normalize to one blank-label variant at $0, priced
// later on the item editor.
function scopeCleanVariants(it) {
  const raw = Array.isArray(it && it.variants) ? it.variants : null;
  // price_override (Sep 2 2026, Brett): lets an admin set the FINAL customer price directly on a
  // variant, bypassing calcTieredEstimate's cost+markup formula entirely for that variant. Stored
  // alongside vendor_cost (never replacing it) so vendor-bill proration at signing — which is
  // always vendor_cost × deposit/subtotal, see scopeSigVendorBillAmount — is completely unaffected
  // by a manual price override. null/blank/non-positive means "no override, auto-calc as before".
  let variants = (raw && raw.length)
    ? raw.map((v, i) => {
        const po = v && v.price_override;
        const poNum = (po === '' || po === null || po === undefined) ? null : parseFloat(po);
        const out = {
          key: (v && v.key) || ('v' + (i + 1)), label: (v && v.label) || '',
          vendor_cost: Math.max(0, parseFloat(v && v.vendor_cost) || 0),
          price_override: (poNum != null && isFinite(poNum) && poNum >= 0) ? +poNum.toFixed(2) : null,
        };
        // Ridge Co–supplied materials (Sep 22 2026, Brett: "no way to account for materials
        // included in the estimate but to be paid for by ridge co rather than vendor"). Ridge Co's
        // OWN cost for materials it buys itself — priced to the customer per the scope's
        // Materials_Pricing_JSON mode (see scopeItemsPricing), shown to the customer as a separate
        // "Includes materials" line, and NEVER part of vendor_cost, so it never reaches the vendor
        // bill or a milestone's Vendor_Amount. Only attached when actually used, so every pre-existing
        // variant keeps its exact old shape.
        const mat = Math.max(0, parseFloat(v && v.rc_materials_cost) || 0);
        const matDesc = String((v && v.rc_materials_desc) || '').trim().slice(0, 200);
        if (mat > 0 || matDesc) { out.rc_materials_cost = +mat.toFixed(2); out.rc_materials_desc = matDesc; }
        return out;
      })
    : [{ key: 'v1', label: '', vendor_cost: Math.max(0, parseFloat(it && (it.cost != null ? it.cost : it.vendor_cost)) || 0), price_override: null }];
  if (!variants.length) variants = [{ key: 'v1', label: '', vendor_cost: 0 }];
  let selected = (it && it.selected_key) || variants[0].key;
  if (!variants.some(v => v.key === selected)) selected = variants[0].key;
  return { variants, selected_key: selected };
}
function scopeCleanItems(arr) {
  return (Array.isArray(arr) ? arr : []).map((it, i) => {
    const { variants, selected_key } = scopeCleanVariants(it);
    return {
      id: (it && it.id) || ('li' + (i + 1)), area: (it && it.area) || '', trade: (it && it.trade) || '',
      description: (it && it.description) || '', qty: (it && it.qty) || '', note: (it && it.note) || '',
      variants, selected_key,
      // vendor's own wording when `description` is the English rendering of it (Sep 28 2026) — kept, never shown to the owner
      ...((it && it.description_orig) ? { description_orig: String(it.description_orig) } : {}),
      // Optional add-on (Oct 13 2026, Brett): true = NOT part of the base job — the customer ticks it
      // on or off on the proposal. Absent/false = included in the job (an item with 2+ variants is
      // still a pick-one choice). Only written when true, so every existing item keeps its exact shape.
      ...((it && (it.optional === true || it.optional === 'true')) ? { optional: true } : {}),
    };
  }).filter(it => it.description);
}
async function scopeFind(env, id) { const rows = await fetchTab(env, 'Scopes'); return rows.find(r => r.ID === String(id)) || null; }

// ── WO → Scope conversion (Sep 18 2026, POST /wo/push-to-scope) ─────────────────────────────
// Maps a vendor's actual submitted Estimate (Estimates tab: flat {desc, amount} line items — a
// vendor's own numbers, one Subtotal, no options) into Scope line items (the richer
// {id, area, trade, description, qty, note, variants:[{key,label,vendor_cost,price_override}],
// selected_key} shape scopeCleanItems already normalizes everything else into). This is the
// FORWARD direction of the existing scopeToWO (scope → WO); nothing here reuses or replaces that.
// Each estimate line becomes a single-variant item (variants.length === 1, same "no options yet"
// shape scopeCleanVariants already gives a bare-cost item) so it prices through calcTieredEstimate
// exactly like any hand-typed scope item — Brett can still add Repair/Replace-style variants
// afterward in scope-creator.html, this just gets the vendor's numbers in the door.
// `existingItems` (the target scope's CURRENT Line_Items, [] for a brand-new scope) is passed so
// fresh item ids never collide with ones already on the scope — this function only ever APPENDS.
function scopeItemsFromEstimate(lineItems, existingItems) {
  const existing = Array.isArray(existingItems) ? existingItems : [];
  const usedIds = new Set(existing.map(it => it && it.id).filter(Boolean));
  let n = existing.length;
  const out = [];
  // Sep 28 2026: everything the OWNER reads is English — desc_en (or the English half of an [ES]/[EN]
  // tag) when the vendor wrote Spanish; the vendor's own wording rides along as description_orig.
  for (const li of estimateLinesEnglish(lineItems)) {
    const description = String((li && li.desc) || '').trim();
    if (!description) continue; // mirrors scopeCleanItems: an item with no description is dropped
    const amount = Math.max(0, parseFloat(li && li.amount) || 0);
    n++;
    let id = 'li' + n;
    while (usedIds.has(id)) { n++; id = 'li' + n; }
    usedIds.add(id);
    out.push({
      id, area: '', trade: '', description, qty: '', note: '',
      variants: [{ key: 'v1', label: '', vendor_cost: +amount.toFixed(2), price_override: null }],
      selected_key: 'v1',
      ...(li.desc_orig ? { description_orig: String(li.desc_orig) } : {}),
    });
  }
  return out;
}
// Claude text helper (mirrors generateEstimateText). media = optional image/document content block.
async function scopeClaude(env, prompt, media, maxTokens) {
  if (!env.ANTHROPIC_API_KEY) throw new Error('ANTHROPIC_API_KEY not configured');
  const content = media ? [media, { type: 'text', text: prompt }] : prompt;
  const { data } = await anthropicMessages(env, { model: 'claude-sonnet-4-6', max_tokens: maxTokens || 1200, messages: [{ role: 'user', content }] }, { source: 'scopeClaude' });   // Oct 16 2026: guarded call (credit pause); throws AiCreditPausedError
  return (data.content && data.content[0] && data.content[0].text || '').trim();
}
function scopeParseJSON(txt) { try { return JSON.parse(String(txt).replace(/^```json?/i, '').replace(/```$/, '').trim()); } catch (_) { return null; } }

// OCR an uploaded/drive image or PDF of hand-written notes → verbatim transcription text.
async function scopeOcr(env, bytes, mime) {
  const b64 = bytesToB64(bytes), isPdf = /pdf/i.test(mime);
  const media = isPdf
    ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
    : { type: 'image', source: { type: 'base64', media_type: (String(mime).split(';')[0] || 'image/jpeg'), data: b64 } };
  const prompt = `You are transcribing a property-maintenance contractor's HAND-WRITTEN job notes (a scope of work). Transcribe EVERYTHING you can read, verbatim, preserving line breaks and any list/indent structure. Expand shorthand only where unambiguous. Do NOT invent items, do NOT add prices, do NOT summarize. If a word is unreadable, write [?]. Return ONLY the transcription text, no preamble.`;
  return await scopeClaude(env, prompt, media, 1500);
}

async function scopeCreate(env, body) {
  await scopesTab(env);
  if (!body.property_id) return json({ error: 'property_id required' }, 400);
  const now = new Date().toISOString();
  return await addRow(env, 'Scopes', {
    Property_ID: body.property_id || '', Unit_ID: body.unit_id || '', Room: body.room || '',
    Title: body.title || 'Untitled scope', Status: 'draft', Raw_Input: body.raw_input || '',
    Line_Items: '[]', Source_Refs: '[]', Parent_Scope_ID: body.parent_scope_id || '', WO_ID: '',
    Vendor_ID: '', Estimate_Number: '', Estimate_Amount: '', Estimate_Notes: '', Proposal_Text: '',
    Created_By: body.created_by || 'admin', Created_Date: now, Updated_Date: now, Notes: '', Active: 'TRUE',
  });
}

// WO statuses meaning the crew is still actively working the job (before 'Complete'). Anything
// NOT in this set — Complete, Pending Invoice, Invoiced, Paid, or anything else — means the job
// itself is done from a work-execution standpoint, per the existing OPEN_WO_STATUSES ordering.
const WO_STILL_ACTIVE_STATUSES = WOStatus.sets.FIELD_OPEN;

// GET /scopes — Brett (Sep 8 2026): "link status on proposal to the work order since that's how
// we are billing it... 'complete' is not just the proposal being complete but the job, and thus
// ready for billing steps... advise me on how to make the status more clear so we don't end up
// with unbilled jobs in the 'complete' pile." A scope's own Status only ever reflects its OWN
// booking history (invoiced = deposit booked, fully-invoiced = final balance booked) — it has no
// idea whether the underlying job is actually finished. Rather than persist a third status value
// that could go stale the moment the WO moves on, this computes a READ-TIME-ONLY 'ready-to-bill'
// label whenever a deposit-booked scope's linked WO shows the job physically done but the final
// balance hasn't been booked yet — nothing is ever written back to the Scopes sheet for this.
// scope-creator.html surfaces 'ready-to-bill' as its own always-visible, never-collapsed section
// (unlike the collapsed 'in-progress'/'completed' buckets) specifically so a job that's done but
// not yet billed can never get lost — 'completed' (collapsed, safe to ignore) is reserved for
// Status === 'fully-invoiced' ONLY, i.e. genuinely, already fully billed.
async function scopeList(env, url) {
  await scopesTab(env);
  let rows = []; try { rows = await fetchTab(env, 'Scopes'); } catch (_) { return json([]); }
  rows = rows.filter(r => String(r.Active || '').toUpperCase() !== 'FALSE');
  const status = url && url.searchParams.get('status');
  if (status && status !== 'all') rows = rows.filter(r => (r.Status || 'draft') === status);
  rows.sort((a, b) => (parseInt(b.ID) || 0) - (parseInt(a.ID) || 0));

  // Only bother reading Work_Orders at all when at least one row could actually need it.
  let woStatusById = null;
  if (rows.some(r => r.Status === 'invoiced' && r.WO_ID)) {
    try {
      const wos = await fetchTab(env, 'Work_Orders');
      woStatusById = new Map(wos.map(w => [w.ID, w.Status]));
    } catch (_) { woStatusById = new Map(); }
  }
  function displayStatus(r) {
    if (r.Status === 'invoiced' && r.WO_ID && woStatusById) {
      const woStatus = woStatusById.get(r.WO_ID);
      if (woStatus && !WO_STILL_ACTIVE_STATUSES.includes(woStatus)) return 'ready-to-bill';
    }
    return r.Status;
  }

  return json(rows.map(r => ({ id: r.ID, property_id: r.Property_ID, unit_id: r.Unit_ID, room: r.Room, title: r.Title, status: displayStatus(r), wo_id: r.WO_ID, approval_stage: r.Approval_Stage || '', parent_scope_id: r.Parent_Scope_ID, item_count: scopeParseItems(r).length, estimate_amount: r.Estimate_Amount, has_proposal: !!(r.Proposal_Text || '').trim(), created_date: r.Created_Date, updated_date: r.Updated_Date })));
}

// Builds a customer-facing "<Address> Unit <Label>" string for a scope — looks up the real
// Unit_Label (e.g. "2F") from the Units tab instead of printing the internal Unit_ID (e.g. "45").
// Aug 22 2026: fixes a bug caught live on the 931 St. Paul proposal, where the public link header
// read "931 Saint Paul St Unit 45" instead of "...Unit 2F" — s.Unit_ID is the Units-tab row ID,
// never the label a customer should see. Falls back to the raw Unit_ID only if no matching unit
// row is found, so an address never silently goes blank.
async function scopeAddr(env, s) {
  let addr = '';
  try {
    const props = await fetchTab(env, 'Properties');
    const p = props.find(x => x.ID === s.Property_ID);
    if (p) {
      addr = p.Address || '';
      if (s.Unit_ID) {
        let label = s.Unit_ID;
        try {
          const units = await fetchTab(env, 'Units');
          const u = units.find(x => x.ID === s.Unit_ID);
          if (u && u.Unit_Label) label = u.Unit_Label;
        } catch (_) {}
        addr += ' Unit ' + label;
      }
    }
  } catch (_) {}
  return addr;
}

async function scopeGet(env, url) {
  const id = url.searchParams.get('id'); if (!id) return json({ error: 'id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  let srcs = []; try { srcs = JSON.parse(s.Source_Refs || '[]'); } catch (_) {}
  return json(Object.assign({}, s, { line_items: scopeParseItems(s), source_refs: srcs }));
}

// GET /scope/drive-list?folder= — list image/pdf files in the handwriting scan folder to pick from.
async function scopeDriveList(env, url) {
  const cfg = await fetchConfig(env).catch(() => ({}));
  const folder = (url && url.searchParams.get('folder')) || cfg.scope_scan_folder_id || env.SCOPE_SCAN_FOLDER_ID || SCOPE_SCAN_FOLDER_DEFAULT;
  try {
    const tok = await getAccessToken(env);
    const params = new URLSearchParams({ q: `'${folder}' in parents and trashed=false`, fields: 'files(id,name,mimeType,webViewLink,modifiedTime)', supportsAllDrives: 'true', includeItemsFromAllDrives: 'true', pageSize: '100', orderBy: 'modifiedTime desc' });
    const res = await fetch(`https://www.googleapis.com/drive/v3/files?${params}`, { headers: { Authorization: `Bearer ${tok}` } });
    const data = await res.json();
    if (data.error) return json({ ok: false, folder_id: folder, error: 'Drive list failed: ' + (data.error.message || ''), files: [] });
    const files = (data.files || []).filter(f => /image|pdf/i.test(f.mimeType || ''));
    return json({ ok: true, folder_id: folder, files });
  } catch (e) { return json({ ok: false, error: e.message, files: [] }); }
}

// POST /scope/ingest — {scope_id, text | drive_file_id | image_b64(+mime), source_label?} → append to Raw_Input.
async function scopeIngest(env, body) {
  const id = body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  let added = '', label = body.source_label || '', type = 'text';
  try {
    if (body.text && String(body.text).trim()) { added = String(body.text).trim(); type = 'text'; label = label || 'typed/voice'; }
    else if (body.drive_file_id) { const tok = await getAccessToken(env); const dl = await driveDownload(tok, body.drive_file_id); added = await scopeOcr(env, dl.bytes, dl.mime); type = 'drive'; label = label || ('drive:' + body.drive_file_id); }
    else if (body.image_b64) { const raw = String(body.image_b64).replace(/^data:[^,]+,/, ''); const bin = Uint8Array.from(atob(raw), c => c.charCodeAt(0)); added = await scopeOcr(env, bin.buffer, body.mime || 'image/jpeg'); type = 'upload'; label = label || 'upload'; }
    else return json({ error: 'text, drive_file_id, or image_b64 required' }, 400);
  } catch (e) {
    if (aiCreditIsPausedError(e)) return aiCreditPausedJson({ message: 'Automatic reading of the photo is paused - type the notes in by hand.' });
    return json({ error: 'ingest failed: ' + (e.message || e) }, 500);
  }
  const raw = s.Raw_Input ? (s.Raw_Input + '\n\n' + added) : added;
  let srcs = []; try { srcs = JSON.parse(s.Source_Refs || '[]'); } catch (_) {}
  srcs.push({ type, label, ts: new Date().toISOString(), chars: added.length });
  await updateRow(env, 'Scopes', id, { Raw_Input: raw, Source_Refs: JSON.stringify(srcs).slice(0, 8000), Updated_Date: new Date().toISOString() });
  return json({ success: true, extracted: added, raw_input: raw });
}

// POST /scope/generate — organize Raw_Input into structured line items (no prices).
async function scopeGenerate(env, body) {
  const id = body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const raw = (s.Raw_Input || '').trim();
  if (!raw) return json({ error: 'No notes to organize yet — add typed/voice/OCR input first' }, 400);
  const prompt = `You are a property-maintenance scope-of-work organizer. Turn the contractor's raw, messy job notes below into a clean, itemized scope of work — the list of work a VENDOR will estimate. Fix typos/slang/grammar. Split compound notes into separate concrete work items. Group by area (room/location) and trade where clear. Do NOT invent work that isn't implied. Do NOT include ANY prices, costs, or dollar amounts.\n\nRaw notes:\n"""\n${raw}\n"""\n\nReturn ONLY strict minified JSON: an array of items, each {"id":"li1","area":"","trade":"","description":"","qty":"","note":""}. Number ids li1, li2, li3… in order. area = room/location (e.g. "Kitchen", "Exterior"); trade = one of Plumbing, Electrical, HVAC, Carpentry, Drywall, Paint, Flooring, Appliance, Cleaning, General, or "" if unclear; description = the work, imperative and specific; qty = a count/measure if stated else ""; note = any caveat/detail. JSON array only, no prose.`;
  const txt = await scopeClaude(env, prompt, null, 2000);
  const items = scopeParseJSON(txt);
  if (!Array.isArray(items)) return json({ error: 'Could not organize notes — model returned unparseable output', raw: String(txt).slice(0, 300) }, 502);
  const clean = scopeCleanItems(items);
  await updateRow(env, 'Scopes', id, { Line_Items: JSON.stringify(clean), Updated_Date: new Date().toISOString() });
  return json({ success: true, line_items: clean });
}

// POST /scope/command — natural-language edit of the current line items ("remove the plumbing section").
async function scopeCommand(env, body) {
  const id = body.scope_id, command = body.command;
  if (!id || !command) return json({ error: 'scope_id and command required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const items = scopeParseItems(s);
  const prompt = `You are editing a property-maintenance scope of work. Current line items as JSON:\n${JSON.stringify(items)}\n\nApply this instruction from the contractor:\n"""${command}"""\n\nReturn ONLY strict minified JSON: {"items":[...],"summary":"<one short sentence describing exactly what changed>"}. Each item keeps the shape {"id","area","trade","description","qty","note"}. Preserve the id of any item you keep; assign a fresh id (continue the li# numbering) to any new item. Remove items the instruction says to remove. Never add prices. JSON only.`;
  const txt = await scopeClaude(env, prompt, null, 2000);
  const parsed = scopeParseJSON(txt);
  if (!parsed || !Array.isArray(parsed.items)) return json({ error: 'Could not apply command — model returned unparseable output', raw: String(txt).slice(0, 300) }, 502);
  // The model is told to return only the text fields ("never add prices"), so a kept item comes
  // back with no `variants` — which scopeCleanItems would reset to a single $0 option, silently
  // wiping every vendor cost, override, and Ridge Co materials amount on items the command didn't
  // even touch. Carry the saved priced variants back over by id for every kept item.
  const prevById = {}; for (const it of items) if (it && it.id) prevById[it.id] = it;
  const merged = parsed.items.map(it => {
    // Kept item → ALWAYS its saved pricing (the model is told never to touch prices, so any
    // variants it echoes back are at best a copy and at worst a mangled one).
    const prev = it && it.id && prevById[it.id];
    if (prev && Array.isArray(prev.variants) && prev.variants.length) {
      return Object.assign({}, it, { variants: prev.variants, selected_key: prev.selected_key });
    }
    return it;
  });
  const clean = scopeCleanItems(merged);
  await updateRow(env, 'Scopes', id, { Line_Items: JSON.stringify(clean), Updated_Date: new Date().toISOString() });
  return json({ success: true, line_items: clean, summary: parsed.summary || 'Updated.' });
}

// Guard for anything a human types directly into a field that can end up on a customer-facing
// surface with no AI rewrite / server-side markup step in between (Aug 24 2026, same incident
// as the scopeProposalView `note` leak — that one was a structured field with no internal/
// customer split; this is the same failure MODE applied to raw hand-typed text). Deliberately
// narrow and high-precision: matches vendor-pricing-specific language that has ~zero legitimate
// reason to appear in a customer proposal, WITHOUT matching the customer's own already-standard
// boilerplate (e.g. "Total Estimated Cost: $925.00" / "Required 50% Deposit" — those are the
// customer's final price, which Brett's rule explicitly allows). Bare "cost" or a dollar amount
// alone is NOT enough to trip this — it has to look like vendor-side pricing/derivation language.
// Returns the matched phrase (for a useful error message) or null if clean.
// NOTE: this is a keyword/phrase NET, not a semantic filter — it catches the incident phrasing
// and realistic close variants, not every possible paraphrase of "here's what the vendor
// charged." A note with two dollar amounts and no trigger word at all (e.g. "our cost is $400,
// customer price is $650") can still slip through. Treat this as a backstop on top of the
// admin-only gate on this endpoint, not a guarantee — see FEATURE_LOG for the incident writeup.
function findVendorPricingLeak(text) {
  const t = String(text || '');
  const patterns = [
    /\b(?:vendor|contractor|sub(?:contractor)?)'?s?[\s_-]*(?:cost|quote|quoted|price|priced|charg\w*)/i,
    /\bsub\s+charg\w*/i,
    /\b(?:we|i)\s+were\s+quoted\b/i,
    /\bquoted\s+(?:us|me)\b/i,
    /mark[\s-]?up/i,
    /\bmarked[\s-]?up\b/i,
    // "margin" alone is too common in trade language (door/cabinet fit) to gate on bare-word —
    // only trip on the money-margin sense: "profit margin", "our/my margin", or "margin is/of ~N".
    /\bprofit\s*margin\b/i,
    /\b(?:my|our)\s*margin\b/i,
    /\bmargin\s*(?:is|of|on|at)\s*(?:about\s*)?\$?\d/i,
    /\b(my|our|ridge\s*co'?s?)\s+(cut|profit|fee\s+on\s+(this|top))\b/i,
    /\bwe(?:'re| are)\s+(?:making|clearing)\b/i,
  ];
  for (const re of patterns) { const m = t.match(re); if (m) return m[0]; }
  return null;
}
// POST /scope/update — direct manual edits.
async function scopeUpdate(env, body) {
  const id = body.scope_id || body.id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const fields = { Updated_Date: new Date().toISOString() };
  if (Array.isArray(body.line_items)) fields.Line_Items = JSON.stringify(scopeCleanItems(body.line_items));
  // How Ridge Co–supplied materials are priced to the customer on this proposal (Sep 22 2026):
  // chosen per proposal on scope-creator.html step 7. Validated here, the one place it's written.
  if (body.materials_pricing !== undefined) {
    const mp = scopeCleanMaterialsPricing(body.materials_pricing);
    if (mp.error) return json({ error: mp.error }, 400);
    await ensureColumns(env, 'Scopes', ['Materials_Pricing_JSON']);
    fields.Materials_Pricing_JSON = JSON.stringify(mp.value);
  }
  if (body.title !== undefined) fields.Title = body.title;
  if (body.notes !== undefined) fields.Notes = body.notes;
  if (body.room !== undefined) fields.Room = body.room;
  if (body.raw_input !== undefined) fields.Raw_Input = body.raw_input;
  if (body.status !== undefined) fields.Status = body.status;
  // Aug 21 2026: allow a hand-edited Proposal_Text to be saved directly (e.g. a Cowork-drafted
  // customer proposal), bypassing the AI regeneration in scopeProposal(). Admin-gated same as every
  // other field on this endpoint (POST /scope/update is not in PUBLIC_PATHS). Setting this also
  // flips Status to 'proposed' when it isn't already, matching what scopeProposal() itself does,
  // so the existing shareable link (scope-proposal.html) immediately serves the new text verbatim —
  // no new link/token needed unless Link_Rev is bumped separately via /scope/proposal/revoke.
  // SECURITY FIX (Aug 24 2026): this hand-edited text is never AI-rewritten and never passes
  // through scopeProposalView's field-level stripping (there's nothing to strip — it's a single
  // opaque blob), so it's the same "unfiltered free text reaching a customer" risk class as the
  // note-field leak fixed the same day, just via a different admin action. Gate it here, at the
  // one place it's ever written, instead of trying to sanitize it wherever it's later served.
  if (body.proposal_text !== undefined) {
    const leak = findVendorPricingLeak(body.proposal_text);
    if (leak) return json({ error: `Proposal text contains vendor-pricing language ("${leak}") that can never reach the customer — remove it and save again. Only the job description and the final price/deposit belong here.` }, 400);
    fields.Proposal_Text = body.proposal_text;
    if (body.status === undefined) fields.Status = 'proposed';
  }
  await updateRow(env, 'Scopes', id, fields);
  return json({ success: true });
}

// POST /scope/split — carve selected items into a new child scope (for a different vendor).
async function scopeSplit(env, body) {
  const id = body.scope_id; const ids = Array.isArray(body.line_item_ids) ? body.line_item_ids : [];
  if (!id || !ids.length) return json({ error: 'scope_id and line_item_ids required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const items = scopeParseItems(s);
  const picked = items.filter(it => ids.includes(it.id));
  if (!picked.length) return json({ error: 'None of the selected items were found' }, 400);
  const now = new Date().toISOString();
  const child = await addRow(env, 'Scopes', {
    Property_ID: s.Property_ID, Unit_ID: s.Unit_ID, Room: s.Room,
    Title: body.new_title || ((s.Title || 'Scope') + ' — split'), Status: 'draft', Raw_Input: '',
    Line_Items: JSON.stringify(picked), Source_Refs: '[]', Parent_Scope_ID: s.ID, WO_ID: '',
    Vendor_ID: '', Estimate_Number: '', Estimate_Amount: '', Estimate_Notes: '', Proposal_Text: '',
    Created_By: body.created_by || 'admin', Created_Date: now, Updated_Date: now, Notes: 'Split from Scope #' + s.ID, Active: 'TRUE',
  });
  const cj = await child.json().catch(() => ({}));
  if (body.remove_from_parent) {
    const remain = items.filter(it => !ids.includes(it.id));
    await updateRow(env, 'Scopes', s.ID, { Line_Items: JSON.stringify(remain), Updated_Date: now });
  }
  return json({ success: true, id: cj.id, moved: picked.length });
}

// POST /scope/approve — the review gate before a scope can become a WO.
async function scopeApprove(env, body) {
  const id = body.scope_id || body.id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  if (!scopeParseItems(s).length) return json({ error: 'Scope has no line items to approve' }, 400);
  await updateRow(env, 'Scopes', id, { Status: 'approved', Updated_Date: new Date().toISOString() });
  return json({ success: true });
}

// POST /scope/to-wo — convert an approved scope into a WORK ORDER tagged "Estimate Requested"
// (unassigned), with the line items rendered into the description + checklist, and any photos
// staged on the scope re-keyed onto the new WO as before-photos.
async function scopeToWO(env, body) {
  const id = body.scope_id || body.id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const items = scopeParseItems(s); if (!items.length) return json({ error: 'Scope has no line items' }, 400);
  if (s.WO_ID) return json({ error: 'Scope already has a work order: ' + s.WO_ID, wo_id: s.WO_ID }, 409);
  const trades = [...new Set(items.map(it => (it.trade || '').trim()).filter(Boolean))];
  const trade = trades.length === 1 ? trades[0] : '';
  const byArea = {}; for (const it of items) { const a = it.area || 'General'; (byArea[a] = byArea[a] || []).push(it); }
  let desc = 'REQUEST FOR ESTIMATE — Scope of Work (Scope #' + s.ID + ')\n';
  for (const a of Object.keys(byArea)) { desc += '\n' + a + ':\n'; for (const it of byArea[a]) desc += '  • ' + (it.description || '') + (it.qty ? (' (qty ' + it.qty + ')') : '') + (it.trade ? (' [' + it.trade + ']') : '') + (it.note ? (' — ' + it.note) : '') + '\n'; }
  const checklist = JSON.stringify(items.map(it => ({ t: (it.area ? (it.area + ': ') : '') + (it.description || ''), done: false, code: '', why: '' })));
  const woResp = await createWorkOrder(env, { property_id: s.Property_ID, unit_id: s.Unit_ID, room: s.Room, trade, type: 'estimate', priority: body.priority || 'normal', description: desc.trim(), notes: 'Request for estimate created from Scope #' + s.ID, checklist, created_by: body.created_by || 'scope-creator', vendor_needs_access: body.vendor_needs_access || 'auto' });
  const wj = await woResp.json().catch(() => ({}));
  const woId = wj.id; if (!woId) return json({ error: 'WO creation failed', detail: wj }, 500);
  try { await ensureColumns(env, 'Work_Orders', ['Scope_ID']); } catch (_) {}
  await updateWOFields(env, woId, { Status: 'Estimate Requested', Scope_ID: s.ID });
  let moved = 0;
  try {
    const atts = await fetchTab(env, 'Attachments'); const key = 'SCOPE-' + s.ID;
    for (const a of atts) { if (a.WO_ID === key && String(a.Active || '').toUpperCase() !== 'FALSE') { await updateRow(env, 'Attachments', a.ID, { WO_ID: woId }); moved++; } }
  } catch (_) {}
  await updateRow(env, 'Scopes', id, { Status: 'wo-created', WO_ID: woId, Updated_Date: new Date().toISOString() });
  return json({ success: true, wo_id: woId, photos_moved: moved });
}

// POST /wo/push-to-scope (Sep 18 2026) — ADMIN-ONLY: zero ROLE_SCOPES entries, reachable only via
// WORKER_SECRET / the Hub's own admin session. {wo_id, estimate_id?, apply?}
// The FORWARD direction of scopeToWO, above (scope → WO): takes a regular Work Order's own
// APPROVED vendor Estimate (Estimates tab — a vendor's real submitted numbers, structurally
// different from a Scope's {area,trade,description,qty,note,variants} items) and converts it into
// a Scope, so the job can go through the full e-signed / materials-markup / multi-milestone Scope
// Proposal billing path instead of a single-shot WO invoice. Brett's locked decisions (do not
// re-litigate — see context/WO_TO_SCOPE_CONVERSION_BUILD_BRIEF_v1.0.md):
//   • Gate: exactly one Estimates row for this WO must already be Status:'Approved' (via the
//     existing POST /estimate/approve) before this does anything — 0 or 2+ approved is a 400,
//     never a guess at which one.
//   • Reuse, never duplicate: Work_Orders.Scope_ID is checked FIRST. Set (e.g. WO-1186 → Scope 7,
//     created earlier via /scope/to-wo) → the mapped items are APPENDED onto that scope's existing
//     Line_Items, never clobbering anything Brett already added by hand. Unset → a new Scopes row
//     is created (Property_ID/Unit_ID/Vendor_ID copied from the WO) and Work_Orders.Scope_ID is
//     set to it.
//   • Idempotent per estimate: the converted estimate's own id+version is recorded in the target
//     scope's existing Source_Refs array (type:'estimate') and the Estimates row itself flips to
//     Status:'Converted' — a second push of the SAME already-converted estimate_id is a no-op
//     (returns the existing scope, appends nothing twice), never a duplicate append or an error.
//   • Cleanup: once converted, Estimates gets Converted_Scope_ID/Converted_Date so it stops
//     sitting in the UI as a phantom pending item.
// Same preview-first (apply defaults false) / best-effort-cleanup-on-partial-failure shape as
// moveVendorBillToNewWO, above — a failure after the new-Scope-creation step hands back its id for
// a human to finish or clean up by hand, same documented gap as that precedent.
async function woPushToScope(env, body) {
  const woId = body && body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const apply = !!body && (body.apply === true || String(body.apply).toUpperCase() === 'TRUE');

  await scopesTab(env);
  try { await ensureColumns(env, 'Work_Orders', ['Scope_ID']); } catch (_) {}
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, woId);
  if (!wo) return json({ error: `No work order ${woId} found` }, 404);
  if (String(wo.Type || '') === 'addon' && String(wo.Parent_WO_ID || '').trim() &&
      (String(wo.Voided || '').toUpperCase() === 'TRUE' || ['Withdrawn', 'Draft'].includes(String(wo.Addon_Status || '')))) {
    return json({ error: `Additional work ${woId} is ${String(wo.Addon_Status || '') === 'Draft' ? 'still a draft' : 'withdrawn or voided'} — it cannot be sent to a Scope Proposal.` }, 400);
  }
  if (String(wo.Voided || '').toUpperCase() === 'TRUE') return json({ error: `WO ${woId} is voided — restore it first (POST /wo/unvoid) before pushing it to a Scope Proposal.` }, 409);

  const allEstimates = await fetchTab(env, 'Estimates');
  const woEstimates = allEstimates.filter(e => e.WO_ID === woId && String(e.Active || '').toUpperCase() !== 'FALSE');
  if (!woEstimates.length) return json({ error: `WO ${woId} has no estimates yet — submit/add one first (POST /estimate).` }, 400);

  // An explicit estimate_id that's already Converted is a no-op success, not an error — calling
  // this a second time on the same already-converted estimate must never look like a failure.
  const reqEstimateId = body && body.estimate_id ? String(body.estimate_id) : '';
  if (reqEstimateId) {
    const already = woEstimates.find(e => e.ID === reqEstimateId && String(e.Status || '') === 'Converted');
    if (already) {
      return json({
        success: true, applied: true, already_converted: true, wo_id: woId, estimate_id: already.ID,
        scope_id: already.Converted_Scope_ID || '',
        message: `Estimate ${already.ID} (v${already.Version}) was already converted to Scope ${already.Converted_Scope_ID || '?'} on ${already.Converted_Date || 'an earlier date'} — nothing more to do.`,
      });
    }
  }

  let approved = woEstimates.filter(e => String(e.Status || '') === 'Approved');
  // approve_first (Sep 30 2026): the "Approve & send to proposal" button. When no estimate is Approved
  // yet, approve the chosen/latest open one SILENTLY as part of this push — no vendor text (the
  // vendor hears nothing until the owner signs the proposal), no 'Approved' stage flash (the WO goes
  // straight to Proposed below). The plain /estimate/approve button is unchanged and still texts the
  // vendor — that is the "approve, no proposal" path.
  const approveFirst = !!body && (body.approve_first === true || String(body.approve_first).toUpperCase() === 'TRUE');
  let silentApprove = null;
  if (approveFirst && approved.length === 0) {
    const open = woEstimates.filter(e => !['Approved', 'Converted', 'Declined', 'Withdrawn'].includes(String(e.Status || '')));
    if (!open.length) return json({ error: `WO ${woId} has no open estimate to approve (every version is Declined or already Converted).` }, 400);
    silentApprove = reqEstimateId
      ? open.find(e => e.ID === reqEstimateId)
      : open.reduce((a, b) => (parseInt(a.Version) || 0) > (parseInt(b.Version) || 0) ? a : b);
    if (!silentApprove) return json({ error: `Estimate ${reqEstimateId} is not an open estimate on WO ${woId}` }, 404);
    approved = [silentApprove];
  }
  if (approved.length !== 1) {
    return json({
      error: approved.length === 0
        ? `WO ${woId} has no APPROVED estimate yet — approve one first (POST /estimate/approve), then push it to a Scope Proposal.`
        : `WO ${woId} has ${approved.length} estimate versions marked Approved (ids ${approved.map(e => e.ID).join(', ')}) — resolve to exactly one (POST /estimate/unapprove the extras) before pushing to a Scope Proposal.`,
    }, 400);
  }
  const estimate = reqEstimateId ? woEstimates.find(e => e.ID === reqEstimateId) : approved[0];
  if (!estimate) return json({ error: `Estimate ${reqEstimateId} not found on WO ${woId}` }, 404);
  if (estimate.ID !== approved[0].ID) {
    return json({ error: `Estimate ${estimate.ID} (v${estimate.Version}) is not the approved estimate on this WO — the approved one is ${approved[0].ID} (v${approved[0].Version}).` }, 400);
  }

  let lineItems = []; try { lineItems = JSON.parse(estimate.Line_Items || '[]'); } catch (_) {}
  if (!Array.isArray(lineItems) || !lineItems.length) return json({ error: `Estimate ${estimate.ID} has no line items to convert.` }, 400);
  // Older estimates (pre desc_en) written in Spanish: translate the lines that lack an English copy
  // in memory only, so the proposal is English regardless. A translation miss keeps the original.
  if (lineItems.some(li => li && li.desc && !li.desc_en && plausiblyNonEnglish(li.desc))) {
    try {
      const need = lineItems.map((li, i) => (li && li.desc && !li.desc_en && plausiblyNonEnglish(li.desc)) ? i : -1).filter(i => i >= 0);
      const tr = await translateBatchToEnglish(env, need.map(i => lineItems[i].desc));
      if (tr.ok) need.forEach((i, k) => { if (String(tr.out[k]).trim().toLowerCase() !== String(lineItems[i].desc).trim().toLowerCase()) lineItems[i] = Object.assign({}, lineItems[i], { desc_en: tr.out[k] }); });
    } catch (_) {}
  }

  // ---- Resolve target scope: reuse Work_Orders.Scope_ID if already set, else preview a new one.
  const scopes = await fetchTab(env, 'Scopes');
  let targetScope = null, willCreate = false;
  if (wo.Scope_ID) {
    targetScope = scopes.find(x => x.ID === String(wo.Scope_ID));
    if (!targetScope) return json({ error: `WO ${woId}'s Scope_ID (${wo.Scope_ID}) does not match any real Scope — fix the link by hand before pushing.` }, 409);
  } else {
    willCreate = true;
  }

  const existingItems = targetScope ? scopeParseItems(targetScope) : [];
  const mappedItems = scopeItemsFromEstimate(lineItems, existingItems);
  if (!mappedItems.length) return json({ error: `Estimate ${estimate.ID}'s line items all have blank descriptions — nothing to convert.` }, 400);

  const preview = {
    success: true, applied: false, wo_id: woId, estimate_id: estimate.ID, estimate_version: estimate.Version,
    target: willCreate
      ? { will_create: true, property_id: wo.Property_ID, unit_id: wo.Unit_ID || '' }
      : { will_create: false, scope_id: targetScope.ID, title: targetScope.Title || '', existing_item_count: existingItems.length },
    mapped_items: mappedItems,
    estimate_subtotal: +(+estimate.Subtotal || 0).toFixed(2),
    will_approve_silently: !!silentApprove,
  };
  if (!apply) return json(preview);

  // ---- APPLY ----
  if (silentApprove) {
    // Estimate row only: Status + who/when/why. Deliberately NO vendor text and NO
    // 'Approved' stage — see approve_first note above. A failure here stops before any
    // Scope is created, so nothing is left half-done.
    const ar = await updateRow(env, 'Estimates', silentApprove.ID, {
      Status: 'Approved', Approved_By: (body && body.approved_by) || 'admin', Approved_Date: new Date().toISOString(),
      Approval_Note: 'Approved for proposal — vendor not texted until the owner signs',
    });
    if (ar && typeof ar.status === 'number' && ar.status >= 400) return ar;
  }
  let scopeId = targetScope ? targetScope.ID : '';
  if (willCreate) {
    const now = new Date().toISOString();
    const createResp = await addRow(env, 'Scopes', {
      Property_ID: wo.Property_ID || '', Unit_ID: wo.Unit_ID || '', Room: wo.Room || '',
      Title: ('WO ' + woId + ' — ' + (wo.Description || wo.Trade || 'Scope of work')).slice(0, 120),
      Status: 'draft', Raw_Input: '', Line_Items: '[]', Source_Refs: '[]', Parent_Scope_ID: '',
      WO_ID: woId, Vendor_ID: wo.Vendor_ID || '', Estimate_Number: '', Estimate_Amount: '', Estimate_Notes: '',
      Proposal_Text: '', Created_By: (body && body.created_by) || 'admin', Created_Date: now, Updated_Date: now, Notes: '', Active: 'TRUE',
    });
    const createJson = await createResp.clone().json().catch(() => ({}));
    scopeId = createJson.id;
    if (!scopeId) return json({ error: 'Failed to create the new Scope for this WO', detail: createJson }, 500);
    try { await updateWOFields(env, woId, { Scope_ID: scopeId }); }
    catch (e) {
      return json({
        success: false, applied: true, partial: true, scope_id: scopeId, estimate_id: estimate.ID,
        error: `Scope ${scopeId} was created, but linking it back onto WO ${woId} (Scope_ID) failed (${e.message || e}). Set Work_Orders.Scope_ID to ${scopeId} by hand, then retry — retrying this action now would create ANOTHER new scope, it would not resume this one.`,
      }, 500);
    }
  }

  const finalItems = existingItems.concat(mappedItems);
  let srcs = []; try { srcs = JSON.parse((targetScope && targetScope.Source_Refs) || '[]'); } catch (_) {}
  srcs.push({ type: 'estimate', estimate_id: estimate.ID, version: estimate.Version, wo_id: woId, ts: new Date().toISOString() });
  try {
    await updateRow(env, 'Scopes', scopeId, {
      Line_Items: JSON.stringify(finalItems), Source_Refs: JSON.stringify(srcs).slice(0, 8000),
      Vendor_ID: (targetScope && targetScope.Vendor_ID) || wo.Vendor_ID || '',
      Updated_Date: new Date().toISOString(),
    });
  } catch (e) {
    return json({
      success: false, applied: true, partial: true, scope_id: scopeId, estimate_id: estimate.ID,
      error: `Scope ${scopeId} exists (${willCreate ? 'newly created' : 'reused'}), but writing the converted items onto it failed (${e.message || e}). Check Scope ${scopeId} in scope-creator.html and add the items by hand — the estimate has NOT been marked Converted, so retrying this call is safe.`,
    }, 500);
  }

  // Cleanup (point 2): mark the estimate resolved so it stops sitting as a phantom pending item.
  // Best-effort — the scope write above already succeeded, so a failure here must not be reported
  // as if nothing worked; it's surfaced as a warning instead.
  let convertedMarked = false;
  try {
    await ensureColumns(env, 'Estimates', ['Converted_Scope_ID', 'Converted_Date']);
    await updateRow(env, 'Estimates', estimate.ID, { Status: 'Converted', Converted_Scope_ID: scopeId, Converted_Date: new Date().toISOString() });
    convertedMarked = true;
  } catch (e) {}

  await setApprovalStage(env, { woId, scopeId, stage: 'Proposed' });
  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_push_to_scope', Skill_Or_Endpoint: '/wo/push-to-scope', Success: 'TRUE', Notes: `wo=${woId} estimate=${estimate.ID} scope=${scopeId} created=${willCreate}` }); } catch (_) {}

  return json({
    success: true, applied: true, wo_id: woId, scope_id: scopeId, created_new_scope: willCreate,
    estimate_id: estimate.ID, items_added: mappedItems.length, converted_marked: convertedMarked,
    approved_silently: !!silentApprove, vendor_texted: false,
    warning: convertedMarked ? '' : `Scope ${scopeId} was updated, but marking Estimate ${estimate.ID} Converted failed — set it by hand (Status=Converted, Converted_Scope_ID=${scopeId}) so it stops showing as pending.`,
  });
}

// POST /scope/estimate — record the vendor's estimate number(s) + amount onto the scope
// (editable afterward, since a vendor may propose a different solution or drop an item).
async function scopeEstimate(env, body) {
  const id = body.scope_id || body.id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const fields = { Updated_Date: new Date().toISOString() };
  if (body.vendor_id !== undefined) fields.Vendor_ID = body.vendor_id;
  if (body.estimate_number !== undefined) fields.Estimate_Number = body.estimate_number;
  if (body.estimate_amount !== undefined) fields.Estimate_Amount = String(body.estimate_amount);
  if (body.estimate_notes !== undefined) {
    // Sep 28 2026: notes copied from a Spanish vendor estimate are stored in English (what the owner
    // proposal side reads); the original is kept in Estimate_Notes_Orig. Fails open to the original.
    fields.Estimate_Notes = body.estimate_notes;
    const _n = String(body.estimate_notes || '');
    if (_n.trim() && plausiblyNonEnglish(_n)) {
      try {
        const tr = await translateBatchToEnglish(env, [_n]);
        if (tr.ok && tr.out[0] && tr.out[0].trim().toLowerCase() !== _n.trim().toLowerCase()) {
          try { await ensureColumns(env, 'Scopes', ['Estimate_Notes_Orig']); fields.Estimate_Notes_Orig = _n; fields.Estimate_Notes = tr.out[0]; } catch (_) {}
        }
      } catch (_) {}
    } else if (s.Estimate_Notes_Orig !== undefined) { fields.Estimate_Notes_Orig = ''; }
  }
  if (['draft', 'approved', 'wo-created'].includes(s.Status)) fields.Status = 'estimated';
  await updateRow(env, 'Scopes', id, fields);
  // Approval stage: a vendor estimate recorded on a scope that has no stage yet → Estimated.
  if (body.estimate_amount !== undefined && String(body.estimate_amount) !== '' && !String(s.Approval_Stage || '')) await setApprovalStage(env, { scopeId: id, stage: 'Estimated' });
  // Keep the linked Work Order's own Vendor_ID in sync (Sep 22 2026 fix). A WO created via
  // /scope/to-wo starts fully unassigned (createWorkOrder is called with no vendor_id), and
  // nothing else in the Scope Proposal pipeline — /scope/proposal/sign, scopeProposalBook,
  // scopeProposalBillMilestones — ever writes Work_Orders.Vendor_ID; this endpoint (the one
  // place Scopes.Vendor_ID is ever set) was the only candidate. Left unfixed, a WO that
  // originated from a Scope Proposal stays permanently invisible to that vendor's own portal
  // (GET /vendor-workorders filters on Work_Orders.Vendor_ID) and to the admin Work Orders
  // vendor filter, no matter who is actually doing the job or how far the job has progressed
  // (estimate → signed → booked → invoiced) — confirmed live root cause of Cesar Diaz showing
  // zero jobs in both places despite having signed, in-progress proposal work. Only fires when
  // this call is actually changing the vendor and the scope has a real linked WO; never writes
  // a blank Vendor_ID onto a WO.
  if (body.vendor_id !== undefined && body.vendor_id && s.WO_ID) {
    try { await updateWOFields(env, s.WO_ID, { Vendor_ID: body.vendor_id }); } catch (_) {}
  }
  return json({ success: true });
}

// Pure: should this Scope's Vendor_ID be backfilled onto its linked Work Order? Factored out so
// the rule is unit-testable on its own (the surrounding function is pure Sheets I/O
// orchestration, same as every other qbApi/Sheets-calling function in this file) and so nothing
// else can accidentally drift from it. Requires a real linked WO and a real vendor on the scope,
// and -- the part that matters most -- the WO's own Vendor_ID must still be blank; this must
// never overwrite a WO that already has a vendor on file.
function scopeBackfillEligible(scope, wo) {
  return !!(scope && wo && scope.WO_ID && scope.Vendor_ID && !wo.Vendor_ID);
}

// POST /admin/backfill-scope-wo-vendor — one-time (idempotent, safe to re-run) backfill for the
// gap fixed above: every Work Order that was ever created from a Scope Proposal before this fix
// has Work_Orders.Vendor_ID permanently blank even though its Scope row (and the vendor who
// actually did the job) is known. Read-mostly: only ever writes Work_Orders.Vendor_ID, and only
// when it's currently blank on a WO whose linked Scope has a Vendor_ID on file — never overwrites
// an existing value, never touches anything else on the WO or the Scope.
// POST /admin/gemini-context-update — writes the daily-refreshed Brett-context snapshot that
// GET /gemini-context serves. Gated by HUB_PROD_WRITE_TOKEN (see HUB_PROD_WRITE_PATHS above),
// same narrow-token cascade as the other prod-write admin routes. Body: { content: "<markdown>" }.
// Stored in Config (not a dedicated tab) since it's a single blob, same pattern as other
// singleton settings — see fetchConfig/setConfigKey.
async function adminGeminiContextUpdate(env, body) {
  const content = body && body.content;
  if (!content || typeof content !== 'string') return json({ error: 'content (string) required' }, 400);
  await setConfigKey(env, { key: 'Gemini_Context_Snapshot', value: content });
  return json({ success: true, bytes: content.length });
}

async function backfillScopeWOVendor(env) {
  const [scopes, workorders] = await Promise.all([
    fetchTab(env, 'Scopes').catch(() => []),
    fetchTab(env, 'Work_Orders').catch(() => []),
  ]);
  const woById = new Map(workorders.map(w => [String(w.ID), w]));
  let scopesChecked = 0, updated = 0; const details = [];
  for (const s of scopes) {
    if (!s.WO_ID || !s.Vendor_ID) continue;
    scopesChecked++;
    const wo = woById.get(String(s.WO_ID));
    if (!scopeBackfillEligible(s, wo)) continue;
    await updateWOFields(env, wo.ID, { Vendor_ID: s.Vendor_ID });
    updated++;
    details.push({ wo_id: wo.ID, scope_id: s.ID, vendor_id: s.Vendor_ID });
  }
  return json({ success: true, scopes_checked: scopesChecked, wo_vendor_backfilled: updated, details });
}

// POST /admin/backfill-receipt-attachments { apply?: true } — one-time (idempotent, safe to
// re-run) backfill for the Sep 28 2026 fix in addReceipt() above: every past Receipts row that
// has a WO_ID and a scanned image (Source_File_ID/Source_File_URL) but was written before that
// fix never got a matching Attachments row, so its image is invisible on the WO detail gallery
// and the owner portal even though it's fully billed and fully on file (Brett — WO-1229/Amanda's
// garbage disposal was the case that surfaced this; this sweeps every WO, not just that one, per
// his "past, future" instruction). Read-mostly by default: with no body or apply:false/omitted it
// only PREVIEWS what it would create (counts + a details list), so the actual write is a second,
// explicit call — matches Brett's verify-before-build habit for anything touching ~90+ rows at
// once. Idempotent via the same Receipt_ID link the live fix writes: a Receipts row already
// linked to an Attachments row (by ID, not by guessing from WO_ID/date/store) is never touched
// again, so re-running this after new receipts come in only picks up the new ones.
async function backfillReceiptAttachments(env, body) {
  const apply = !!(body && body.apply === true);
  const [receipts, attachments] = await Promise.all([
    fetchTab(env, 'Receipts').catch(() => []),
    fetchTab(env, 'Attachments').catch(() => []),
  ]);
  const alreadyLinked = new Set(
    attachments.filter(a => String(a.File_Type || '').toLowerCase() === 'receipt' && a.Receipt_ID)
      .map(a => String(a.Receipt_ID))
  );
  let scanned = 0, eligible = 0, created = 0; const details = [];
  for (const r of receipts) {
    if (String(r.Active || '').toUpperCase() === 'FALSE') continue;
    scanned++;
    if (!r.WO_ID) continue;
    const hasFile = r.Source_File_ID || r.Source_File_URL;
    if (!hasFile) continue;
    if (alreadyLinked.has(String(r.ID))) continue;
    eligible++;
    details.push({ receipt_id: r.ID, wo_id: r.WO_ID, store: r.Store || '', date: r.Date || '', amount: r.Amount || '' });
    if (apply) {
      try {
        await ensureColumns(env, 'Attachments', ['Receipt_ID']);
        await addRow(env, 'Attachments', {
          WO_ID: r.WO_ID, File_Name: ((r.Store || 'Receipt') + (r.Date ? ' ' + r.Date : '')).trim(),
          File_Type: 'receipt', Drive_File_ID: r.Source_File_ID || '', Drive_URL: r.Source_File_URL || '',
          Mime_Type: '', Receipt_ID: String(r.ID),
          Created_Date: new Date().toISOString().split('T')[0], Active: 'TRUE',
        });
        created++;
      } catch (e) {
        try { await logTelemetry(env, { Source: 'worker', Job_Type: 'receipt_attachment_gallery_backfill', Skill_Or_Endpoint: '/admin/backfill-receipt-attachments', Success: 'FALSE', Notes: `receipt_id=${r.ID} wo_id=${r.WO_ID} err=${String(e && e.message || e)}` }); } catch (_) {}
      }
    }
  }
  return json({
    success: true, applied: apply, receipts_scanned: scanned,
    eligible_missing_gallery_attachment: eligible, attachments_created: apply ? created : 0,
    details: details.slice(0, 500),
  });
}

// Marks up every item's variant(s) SERVER-SIDE (calcTieredEstimate, per item — each option is
// priced on its own merits, e.g. a small item doesn't inherit a big job's tier) and picks the
// default-selected variant per item to compute a subtotal/deposit. Returns vendor_cost alongside
// price for the ADMIN-only caller (scopeProposal) — the customer-facing boundary functions
// (scopeProposalView, scopeProposalSign) are what strip it before anything leaves the server.
//
// Ridge Co–supplied materials (Sep 22 2026): a variant may also carry rc_materials_cost — what
// Ridge Co itself pays for materials (never the vendor). `mp` = the scope's materials pricing
// choice {mode, pct}, picked per proposal on scope-creator.html:
//   'markup'   — same tiered markup as vendor cost: the variant is priced as ONE job of
//                (vendor_cost + materials) through calcTieredEstimate (so a small add-on never
//                gets its own minimum-markup/admin fee), and the materials share of that price is
//                split out proportionally for the customer's "Includes materials" line.
//   'at_cost'  — pass-through: materials × cardFeeMult only, no markup.
//   'flat_pct' — materials × (1 + pct/100) × cardFeeMult.
// A price_override always covers the vendor/labor part only; materials are priced per mode on top.
// Variant.price stays the TOTAL for the option (labor + materials) so every existing consumer
// (scopeProposalView subtotal, scopeProposalSign) keeps working unchanged. vendorCostTotal never
// includes materials — that is the whole point: the vendor is never billed for them.
// Self-contained on purpose (only calcTieredEstimate) — test files extract this function alone.
function scopeItemsPricing(items, pc, mp) {
  const mode = (mp && ['markup', 'at_cost', 'flat_pct'].includes(mp.mode)) ? mp.mode : 'markup';
  const pct = (mp && isFinite(+mp.pct) && +mp.pct >= 0) ? +mp.pct : 0;
  const fee = (pc && pc.cardFeeMult != null) ? pc.cardFeeMult : 1;
  const r2 = n => Math.round((+n || 0) * 100) / 100;
  let subtotal = 0, vendorCostTotal = 0, rcMaterialsCostTotal = 0, rcMaterialsPriceTotal = 0;
  const priced = items.map(it => {
    const rawVariants = (it.variants && it.variants.length) ? it.variants : [{ key: 'v1', label: '', vendor_cost: 0 }];
    const variants = rawVariants.map(v => {
      // Manual price override (Sep 2 2026) wins outright — skips calcTieredEstimate for this
      // variant entirely. vendor_cost is still carried through unchanged for the later vendor-bill
      // proration at signing, so overriding the customer price never touches what the vendor is owed.
      const hasOverride = v.price_override != null && isFinite(v.price_override) && v.price_override >= 0;
      const vc = +(v.vendor_cost || 0);
      const mat = Math.max(0, +(v.rc_materials_cost || 0) || 0);
      if (!(mat > 0)) {
        // No Ridge Co materials — byte-for-byte the pre-Sep-22 behavior.
        const calc = hasOverride ? null : calcTieredEstimate(vc, pc);
        const price = hasOverride ? +(+v.price_override).toFixed(2) : (calc ? calc.finalPrice : 0);
        return { key: v.key, label: v.label, price, vendor_cost: +vc.toFixed(2), price_override: hasOverride ? price : null };
      }
      let labor, matPrice;
      if (mode === 'markup') {
        const combo = calcTieredEstimate(vc + mat, pc);
        const comboPrice = combo ? combo.finalPrice : 0;
        matPrice = r2(comboPrice * mat / (vc + mat));
        labor = hasOverride ? r2(v.price_override) : r2(comboPrice - matPrice);
      } else {
        matPrice = mode === 'at_cost' ? r2(mat * fee) : r2(mat * (1 + pct / 100) * fee);
        const calc = (hasOverride || !(vc > 0)) ? null : calcTieredEstimate(vc, pc);
        labor = hasOverride ? r2(v.price_override) : (calc ? calc.finalPrice : 0);
      }
      const price = r2(labor + matPrice);
      return {
        key: v.key, label: v.label, price, vendor_cost: +vc.toFixed(2), price_override: hasOverride ? r2(v.price_override) : null,
        rc_materials_cost: r2(mat), materials_price: matPrice, materials_desc: String(v.rc_materials_desc || '').trim() || 'Materials',
      };
    });
    let selKey = it.selected_key || variants[0].key;
    if (!variants.some(v => v.key === selKey)) selKey = variants[0].key;
    const sel = variants.find(v => v.key === selKey) || variants[0];
    // An optional add-on is NOT part of the base job: it never counts toward the base subtotal /
    // vendor cost / materials totals. It only enters them at signing, if the customer ticks it.
    if (!it.optional) {
      subtotal += sel.price; vendorCostTotal += sel.vendor_cost;
      rcMaterialsCostTotal += (sel.rc_materials_cost || 0); rcMaterialsPriceTotal += (sel.materials_price || 0);
    }
    return { id: it.id, area: it.area, trade: it.trade, description: it.description, qty: it.qty, note: it.note, variants, selected_key: selKey, ...(it.optional ? { optional: true } : {}) };
  });
  // Add-on pricing (Oct 13 2026, Brett: "price the whole job, show the difference"): an add-on's
  // customer price is price(base job + add-on) − price(base job), so a small add-on is never hit
  // with its own small-job minimum markup/admin fee and "base + add-on" always lands on the price
  // the whole job would have had. Never below the add-on's own vendor cost (falls back to its
  // stand-alone price if the difference would be). Variants with a manual price_override or Ridge Co
  // materials keep the stand-alone price computed above.
  const baseVendor = vendorCostTotal;
  if (baseVendor > 0) {
    const baseCalc = calcTieredEstimate(baseVendor, pc);
    if (baseCalc) for (const it of priced) {
      if (!it.optional) continue;
      for (const v of it.variants) {
        if (v.price_override != null || v.rc_materials_cost > 0) continue;
        const whole = calcTieredEstimate(baseVendor + v.vendor_cost, pc);
        if (!whole) continue;
        const diff = r2(whole.finalPrice - baseCalc.finalPrice);
        if (diff >= v.vendor_cost && diff > 0) v.price = diff;
      }
    }
  }
  subtotal = +subtotal.toFixed(2);
  return {
    items: priced, subtotal, deposit: +(subtotal / 2).toFixed(2), vendorCostTotal: +vendorCostTotal.toFixed(2),
    rcMaterialsCostTotal: +rcMaterialsCostTotal.toFixed(2), rcMaterialsPriceTotal: +rcMaterialsPriceTotal.toFixed(2),
  };
}

// Materials pricing choice for a scope (Sep 22 2026). Validates what scope-creator.html sends.
const SCOPE_MATERIALS_MODES = ['markup', 'at_cost', 'flat_pct'];
function scopeCleanMaterialsPricing(mp) {
  const mode = mp && mp.mode;
  if (!SCOPE_MATERIALS_MODES.includes(mode)) return { error: 'materials_pricing.mode must be one of: ' + SCOPE_MATERIALS_MODES.join(', ') };
  if (mode !== 'flat_pct') return { value: { mode } };
  const pct = parseFloat(mp.pct);
  if (!isFinite(pct) || pct < 0 || pct > 500) return { error: 'Flat materials % must be a number from 0 to 500.' };
  return { value: { mode, pct: Math.round(pct * 100) / 100 } };
}
function scopeParseMaterialsPricing(s) {
  try {
    const v = JSON.parse((s && s.Materials_Pricing_JSON) || 'null');
    const c = scopeCleanMaterialsPricing(v);
    if (c.value) return c.value;
  } catch (_) {}
  return { mode: 'markup' };
}

// POST /scope/proposal — build the CUSTOMER proposal from scope + per-item vendor pricing.
// calcTieredEstimate applies the markup SERVER-SIDE, per item; ONLY the final customer prices +
// subtotal + deposit are ever returned to a customer-facing caller — never cost, markupPct, or
// the derivation (Brett's #1 non-negotiable). Items with 2+ variants are a customer CHOICE
// (e.g. "Repair Roof" vs "Replace Roof"); items with exactly 1 variant are fixed/included.
async function scopeProposal(env, body) {
  const id = body.scope_id || body.id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const items = scopeParseItems(s); if (!items.length) return json({ error: 'Scope has no line items' }, 400);
  // An item is priced once ANY option carries a vendor cost OR a Ridge Co materials cost — a
  // materials-only item (Ridge Co buys it, no vendor labor) is legitimately $0 vendor cost
  // (Sep 22 2026; before this, Brett had to type a fake $1 vendor cost, which then got paid to
  // the vendor on the milestone bill).
  if (!items.some(it => !it.optional)) return json({ error: 'Every line item is marked as an optional add-on — a proposal needs at least one included item (the base job). Un-mark one add-on, or add the main job.' }, 400);
  const unpriced = items.filter(it => !(it.variants || []).some(v => (parseFloat(v.vendor_cost) || 0) > 0 || (parseFloat(v.rc_materials_cost) || 0) > 0));
  if (unpriced.length) return json({ error: `Add vendor cost (or Ridge Co materials) to every item first (missing on ${unpriced.length} item(s), e.g. "${unpriced[0].description}") — price each option (Repair/Replace, etc.) on the item editor.` }, 400);
  // The materials description is hand-typed and shown to the customer verbatim — same leak class
  // as Proposal_Text (see findVendorPricingLeak). Gate it here, where it becomes customer-facing.
  for (const it of items) for (const v of (it.variants || [])) {
    if (!((parseFloat(v.rc_materials_cost) || 0) > 0)) continue;
    const leak = findVendorPricingLeak(v.rc_materials_desc || '');
    if (leak) return json({ error: `The materials description on "${it.description}" contains pricing language ("${leak}") that can never reach the customer — describe the materials only (e.g. "LVP flooring + underlayment").` }, 400);
  }
  let addr = await scopeAddr(env, s);
  addr = addr || ('Property ' + s.Property_ID);
  const _pc = await getPricingConfig(env);
  if (!_pc) return json({ error: 'Pricing not configured — set PRICING_CONFIG (Cloudflare secret) or the Config sheet `pricing_config` row.' }, 400);
  const materialsPricing = scopeParseMaterialsPricing(s);
  const priced = scopeItemsPricing(items, _pc, materialsPricing); // markup applied here, server-side, per item
  const maxUpfront = await scopeMaxUpfrontPct(env);
  const rawSchedule = scopeParsePaymentSchedule(s);
  const scheduleCheck = scopeValidatePaymentSchedule(rawSchedule, maxUpfront);
  // rawSchedule was already validated when it was saved (scopeSetPaymentSchedule) or is the
  // built-in default, so scheduleCheck.error should never fire here — but if a schedule was
  // somehow left in a bad state, fall back to the default rather than 500ing proposal generation.
  const schedule = scheduleCheck.schedule || scopeDefaultPaymentSchedule();
  const milestones = scopeComputeMilestoneAmounts(schedule, priced.subtotal, priced.vendorCostTotal);
  if (priced.items.some(it => it.optional)) {
    // Smallest total a customer could sign = cheapest option on every base item, no add-ons.
    const smallest = priced.items.filter(it => !it.optional).reduce((sum, it) => { const ps = (it.variants || []).map(v => +v.price || 0); return sum + (ps.length ? Math.min(...ps) : 0); }, 0);
    const addonProblem = scopeScheduleAddonProblem(schedule, smallest);
    if (addonProblem) return json({ error: 'This proposal has optional add-ons, but its payment schedule can\'t take them: ' + addonProblem }, 400);
  }

  const bulletsPrompt = `You are a property maintenance estimate writer. Rewrite each of the following scope-of-work item descriptions into a short, polished, customer-facing sentence. Correct typos/slang/grammar, imperative and specific. Do NOT include ANY dollar amounts, costs, or pricing of any kind. Items (JSON array):\n${JSON.stringify(items.map(it => ({ id: it.id, area: it.area, description: it.description, note: it.note })))}\n\nReturn ONLY strict minified JSON: an array of {"id":"<same id>","text":"<rewritten sentence>"}, same order, no preamble.`;
  const rewritten = {};
  try {
    const txt = await scopeClaude(env, bulletsPrompt, null, 1500);
    const arr = scopeParseJSON(txt);
    if (Array.isArray(arr)) for (const r of arr) if (r && r.id) rewritten[r.id] = r.text;
  } catch (_) {}
  for (const it of priced.items) if (rewritten[it.id]) it.description = rewritten[it.id];

  // Flat-text fallback doc (clipboard "Copy proposal" + legacy clients) — grand total + deposit
  // only, same no-leak shape as before; the interactive per-item/variant view is Proposal_Items_JSON.
  // Ridge Co–supplied materials get their own customer line (Brett, Sep 22 2026: "owner gets NO
  // transparency on markup info. just sees description and price to them") — description + the
  // customer's materials price only, never Ridge Co's cost or the mode/markup used.
  // Oct 13 2026 (Brett): the text now shows EVERY option the customer will be offered — pick-one
  // alternatives with their prices, and optional add-ons as a separate "+$X" block that is NOT in
  // the Total — so what Brett reads/copies matches what the customer page presents. Customer prices
  // only; never vendor cost.
  const money = n => '$' + (+n || 0).toFixed(2);
  const itemLine = it => {
    const vs = it.variants || [];
    const multi = vs.length > 1;
    let line = '- ' + (it.area ? it.area + ': ' : '') + it.description;
    if (it.optional && !multi && vs[0]) line += ' (+' + money(vs[0].price) + ')';
    if (multi) {
      line += '\n    Choose one:';
      for (const v of vs) line += '\n      * ' + (v.label || 'Option') + ' - ' + (it.optional ? '+' : '') + money(v.price);
    }
    for (const v of vs) {
      if (!(v.materials_price > 0)) continue;
      line += '\n    Includes materials' + (multi && v.label ? ' (' + v.label + ' option)' : '') + ': ' + v.materials_desc + ' — ' + money(v.materials_price);
    }
    return line;
  };
  const baseItems = priced.items.filter(it => !it.optional), addonItems = priced.items.filter(it => it.optional);
  let scopeText = baseItems.map(itemLine).join('\n');
  if (addonItems.length) {
    scopeText += '\n\nOptional add-ons (NOT included in the total below - you choose whether to add them when you approve):\n' + addonItems.map(itemLine).join('\n');
    for (const it of addonItems) {
      const vs = it.variants || [];
      if (vs.length === 1) scopeText += '\n  Total with this add-on: ' + money(priced.subtotal + vs[0].price);
    }
  }
  // Standing policy (Aug 21 2026, Brett): if only PART of a scope is approved/completed instead of
  // the full project, itemized pricing for those pieces is a best-efforts estimate, not a fixed
  // quote — the combined price is built to absorb small unknowns across a mixed batch of larger and
  // smaller tasks, and a piece done alone loses that cushion. Applies universally (not just when a
  // standalone-vs-combined comparison is shown), so it's standard boilerplate on every proposal.
  const scheduleLines = milestones.map(m => {
    const when = m.trigger === 'upfront' ? ' — due to approve this proposal and schedule the work'
      : m.trigger === 'completion' ? ' — due at job completion'
      : ' — billed once this milestone is reached';
    return `  - ${m.label}${m.calc_mode === 'flat' ? '' : ` (${m.percent}%)`}: $${m.customer_amount.toFixed(2)}${when}`; // a flat-$ payment shows no % (it isn't one)
  }).join('\n');
  const doc = `${addr}\n\nScope of Work:\n\n${scopeText}\n\nFinancial Terms:\n\nTotal Estimated Cost${addonItems.length ? ' (base job, before any optional add-ons)' : ''}: $${priced.subtotal.toFixed(2)}\nPayment Schedule:\n${scheduleLines}\n\nPayment & Project Terms:\n\n- Payment is due per the schedule above; the first payment is required to approve this proposal and schedule the work.\n- All scheduled payments must be paid electronically. Physical checks are not accepted.\n- Where an item offers more than one option, the price shown reflects the option selected at signing; the invoice matches that selection.${addonItems.length ? '\n- Optional add-ons are included only if you select them when you approve; the payment schedule above then applies to the new total.' : ''}\n- If only part of this scope is approved or completed instead of the full project, pricing for those individual items is a best-efforts estimate, not a fixed quote: the combined price is built to absorb the small unknowns of doing larger and smaller tasks together in one visit, and a standalone item doesn't get that same cushion — its actual final cost may run higher than estimated once that work is underway on its own.`;

  await ensureColumns(env, 'Scopes', ['Proposal_Items_JSON']);
  await updateRow(env, 'Scopes', id, {
    Proposal_Text: doc, Proposal_Items_JSON: JSON.stringify(priced.items),
    Estimate_Amount: String(priced.vendorCostTotal), Status: 'proposed', Updated_Date: new Date().toISOString(),
  });
  return json({ success: true, proposal_text: doc, final_price: priced.subtotal, deposit: priced.deposit, schedule: milestones, schedule_warnings: [...(scheduleCheck.warnings || []), ...(addonItems.length && schedule.some(m => m.calc_mode === 'flat') ? [`This proposal has optional add-ons AND a flat-dollar payment. Flat payments stay at the exact amount you typed when a customer adds an add-on; the last "% of total" payment ("${scopeAbsorberLabel(schedule)}") takes the whole difference.`] : [])], items: priced.items,
    // Admin-only caller (scope-creator.html) — lets Brett see the materials split he just priced.
    materials: { mode: materialsPricing.mode, pct: materialsPricing.pct, cost_total: priced.rcMaterialsCostTotal, price_total: priced.rcMaterialsPriceTotal, vendor_cost_total: priced.vendorCostTotal } });
}

// ── Scope proposal customer link (Aug 18 2026, rule 113) ───────────────────
// Brett: "I need the proposal generator to actually generate a proposal" — scopeProposal()
// above only ever produced text saved on the Scope record with no way to hand it to a
// customer. Same signed-link pattern already proven twice today (Shareable Work Order B-117,
// AR Report link) — HMAC-off-WORKER_SECRET token, revoke-by-bumping-a-rev-column, no separate
// token-storage table. No e-sign yet (Brett flagged Documenso as a possible future path for
// that) — this just gets a real, working, sendable link live for today.
const SCOPE_PROPOSAL_LINK_TTL = 60 * 60 * 24 * 90; // 90 days — revoke any time via the rev bump
async function scopeProposalLinkToken(env, scopeId) {
  try { await ensureColumns(env, 'Scopes', ['Link_Rev']); } catch (e) {}
  const s = await scopeFind(env, scopeId);
  if (!s) return null;
  const rev = String(s.Link_Rev || '0');
  return await makeSessionToken({ scope: 'scope-proposal', id: String(scopeId), rev }, env.WORKER_SECRET, SCOPE_PROPOSAL_LINK_TTL);
}
async function scopeProposalLinkAuth(env, tok) {
  const payload = await verifySessionToken(String(tok || ''), env.WORKER_SECRET);
  if (!payload || payload.scope !== 'scope-proposal') return null;
  const s = await scopeFind(env, payload.id);
  if (!s) return null;
  if (String(s.Link_Rev || '0') !== String(payload.rev)) return null;
  return { scopeId: payload.id, s };
}
// POST /scope/proposal/link {scope_id} — admin-gated. Requires Proposal_Text already set
// (generate it first via /scope/proposal) so a customer never lands on an empty page. Minting
// again before a revoke returns the SAME link (same rev) — safe to call repeatedly.
async function scopeProposalLink(env, body) {
  const id = body && body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  if (!(s.Proposal_Text || '').trim()) return json({ error: 'Generate the proposal text first (Generate proposal), then create the link.' }, 400);
  const token = await scopeProposalLinkToken(env, id);
  return json({ success: true, url: `${PORTAL_BASE}/scope-proposal.html?t=${encodeURIComponent(token)}` });
}
// ADMIN: revoke every outstanding link for one scope's proposal by bumping its rev — same
// one-tap revoke UX as the WO share link and the AR report link.
async function scopeProposalLinkRevoke(env, body) {
  const id = body && body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const next = String((parseInt(s.Link_Rev || '0', 10) || 0) + 1);
  await updateRow(env, 'Scopes', id, { Link_Rev: next });
  return json({ success: true, rev: next });
}

const PROPOSAL_SEND_LOG_TAB = 'Proposal_Send_Log';
const PROPOSAL_SEND_LOG_COLS = ['ID', 'Timestamp', 'Scope_ID', 'Owner_ID', 'Owner_Name', 'Email', 'Address', 'Link', 'Result', 'SMS_Result'];

// ── Proposal read status + owner heads-up text (Hub Improvements, Oct 14 2026; FEATURE_LOG rule 209) ──
// Two read signals, both written onto the Scopes row:
//   * Page_*  = the owner opened scope-proposal.html (reliable; a real click-through).
//   * Email_* = the 1x1 tracking pixel in the proposal email loaded (the owner's mail app showed images). Gmail and
//     Apple Mail prefetch images through proxies, so a hit within PROPOSAL_OPEN_AUTO_WINDOW_MS of the send is counted
//     as Email_Auto_Opens (a machine, not a person) and does NOT mark the email "opened". Treat Email_* as "probably".
// Either signal counts as "seen" - that is what cancels a held owner text (processQuietHoursQueue) .
const PROPOSAL_TRACK_COLS = ['Email_First_Opened', 'Email_Last_Opened', 'Email_Open_Count', 'Email_Auto_Opens', 'Page_First_Viewed', 'Page_Last_Viewed', 'Page_View_Count', 'Owner_SMS_Status', 'Owner_SMS_Time'];
const PROPOSAL_OPEN_AUTO_WINDOW_MS = 120000;
const PROPOSAL_RESEND_GUARD_MS = 60000;
const PROPOSAL_BOT_UA = /bot|crawl|spider|slurp|facebookexternalhit|whatsapp|slackbot|twitterbot|curl\/|python-requests|headless|linkpreview|link preview/i;
const SCOPE_SMS_QUIET_WINDOW = { start: 20, end: 8 };   // owner proposal text: fine until 8pm ET, held until 8am ET
const PROPOSAL_PIXEL_GIF_B64 = 'R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
// Pure: how to treat one hit. 'ignore' = obvious bot; 'auto' = email image fetched right after send (prefetch); 'real' = count it.
function classifyProposalHit({ kind, ua, sentDate, now }) {
  if (PROPOSAL_BOT_UA.test(String(ua || ''))) return 'ignore';
  if (kind === 'email') { const sent = Date.parse(sentDate || ''); if (sent && (now - sent) < PROPOSAL_OPEN_AUTO_WINDOW_MS) return 'auto'; }
  return 'real';
}
// Pure: has the owner (probably) seen this proposal?
// `sinceIso` (the send that queued the text = the scope's Sent_Date): only a view AT OR AFTER it counts, so an
// open from an earlier send/preview cannot cancel the text for a later resend. Compares the LAST view stamps
// (they move on every hit). With no usable sinceIso it falls back to "any view ever" (legacy rows).
function proposalSeenByOwner(s, sinceIso) {
  if (!s) return false;
  const since = Date.parse(sinceIso || '');
  if (!since) return !!(String(s.Page_First_Viewed || '').trim() || String(s.Email_First_Opened || '').trim());
  const at = (v) => { const t = Date.parse(String(v || '').trim()); return t ? t : 0; };
  return at(s.Page_Last_Viewed || s.Page_First_Viewed) >= since || at(s.Email_Last_Opened || s.Email_First_Opened) >= since;
}
// Never silent: a failed log lands in Ops_Telemetry; the public page/pixel still works.
async function proposalRecordHit(env, s, kind, ua) {
  try {
    const verdict = classifyProposalHit({ kind, ua, sentDate: s.Sent_Date, now: Date.now() });
    if (verdict === 'ignore') return;
    await ensureColumns(env, 'Scopes', PROPOSAL_TRACK_COLS);
    const nowIso = new Date().toISOString();
    let f;
    if (kind === 'email' && verdict === 'auto') f = { Email_Auto_Opens: String((parseInt(s.Email_Auto_Opens || '0', 10) || 0) + 1) };
    else if (kind === 'email') f = { Email_First_Opened: s.Email_First_Opened || nowIso, Email_Last_Opened: nowIso, Email_Open_Count: String((parseInt(s.Email_Open_Count || '0', 10) || 0) + 1) };
    else f = { Page_First_Viewed: s.Page_First_Viewed || nowIso, Page_Last_Viewed: nowIso, Page_View_Count: String((parseInt(s.Page_View_Count || '0', 10) || 0) + 1) };
    const r = await updateRow(env, 'Scopes', s.ID, f);
    if (r && r.status >= 400) throw new Error('Scopes update HTTP ' + r.status);
  } catch (e) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'proposal_hit_log_failed', Skill_Or_Endpoint: '/scope-proposal/' + kind, Success: 'FALSE', Notes: 'scope=' + (s && s.ID) + ' err=' + String((e && e.message) || e).slice(0, 200) }); } catch (_) {}
  }
}
// PUBLIC GET /scope-proposal/px?t=<proposal link token> - the tracking pixel. ALWAYS answers with the gif (a broken
// image in the owner's email would look worse than a missed open); only a valid, current token is recorded.
async function scopeProposalPixel(env, url, ua, ctx) {
  try {
    const auth = await scopeProposalLinkAuth(env, url.searchParams.get('t'));
    if (auth) await proposalRecordHit(env, auth.s, 'email', ua);
  } catch (e) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'proposal_hit_log_failed', Skill_Or_Endpoint: '/scope-proposal/px', Success: 'FALSE', Notes: String((e && e.message) || e).slice(0, 200) }); } catch (_) {}
  }
  const bin = Uint8Array.from(atob(PROPOSAL_PIXEL_GIF_B64), c => c.charCodeAt(0));
  return new Response(bin, { status: 200, headers: { 'Content-Type': 'image/gif', 'Cache-Control': 'no-store, no-cache, must-revalidate, private', 'Pragma': 'no-cache', 'Access-Control-Allow-Origin': '*' } });
}
// Stamp the owner-text outcome on the Scope so the Scope Creator can show it. Best-effort + telemetry, never throws.
async function proposalStampSms(env, scopeId, status) {
  try {
    await ensureColumns(env, 'Scopes', PROPOSAL_TRACK_COLS);
    const r = await updateRow(env, 'Scopes', scopeId, { Owner_SMS_Status: status, Owner_SMS_Time: new Date().toISOString() });
    if (r && r.status >= 400) throw new Error('Scopes update HTTP ' + r.status);
  } catch (e) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'proposal_sms_stamp_failed', Skill_Or_Endpoint: 'proposalStampSms', Success: 'FALSE', Notes: 'scope=' + scopeId + ' status=' + status + ' err=' + String((e && e.message) || e).slice(0, 160) }); } catch (_) {}
  }
}
// Text the owner "your estimate was emailed". Gated like every owner SMS (global / property / owner toggles, test mode).
// Quiet window 8pm-8am ET (not the global 7pm-9am); `override` (Brett's per-send choice) sends right now. When held, the
// Message_Queue row carries Skip_If_Seen so the release sweep drops it if the owner has already opened the proposal.
// Returns { status, ... } - every outcome (including blocked / failed / no phone) is reported, none swallowed.
async function proposalOwnerSms(env, { scopeId, prop, owner, addr, ownerName, override }) {
  let out;
  try {
    const cfg = await fetchConfig(env);
    const first = ((owner && (owner.First_Name || '')) || (ownerName && ownerName !== 'there' ? String(ownerName).split(' ')[0] : '') || 'there');
    if (!owner || !normalizePhone(owner.Phone)) out = { status: 'no_phone', note: 'Owner has no phone on file - email sent, no text.' };
    else {
      const r = await sendTemplatedSms(env, { type: 'owner_proposal_ready', kind: 'owner', owner, property: prop,
        tokens: { FirstName: first, Address: addr, AssistantName: cfg.ASSISTANT_NAME || 'Riley' },
        bypassQuietHours: !!override, quietWindow: SCOPE_SMS_QUIET_WINDOW, skip_if_seen: 'scope:' + scopeId });
      if (r && r.error) out = { status: 'failed', note: String(r.error).slice(0, 200) };
      else if (r && r.held_for_quiet_hours) out = { status: 'held', send_after: r.send_after, note: 'Held for quiet hours; sends at 8:00am ET unless the owner opens the estimate first.' };
      else if (r && r.sent) out = { status: 'sent', test_mode: !!r.test_mode, delivered_to: r.delivered_to, note: r.test_mode ? 'TEST MODE: delivered to the test number, not the owner.' : 'Texted the owner.' };
      else if (r && r.send_ok === false) out = { status: 'blocked', note: 'SMS gates blocked it: ' + String(r.gate_snapshot || '').slice(0, 200) };
      else if (r && r.reason) out = { status: 'failed', note: String(r.reason).slice(0, 200) };
      else out = { status: 'failed', note: 'Twilio did not confirm the send.' };
    }
  } catch (e) { out = { status: 'failed', note: String((e && e.message) || e).slice(0, 200) }; }
  await proposalStampSms(env, scopeId, out.status);
  if (out.status !== 'sent' && out.status !== 'held') {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'proposal_owner_sms', Skill_Or_Endpoint: '/scope/proposal/send', Success: 'FALSE', Notes: 'scope=' + scopeId + ' ' + out.status + ': ' + (out.note || '') }); } catch (_) {}
  }
  return out;
}

// Pure: resolves the CONFIRMED PAYOR for a scope's property — never the Realtor/PM referral
// source (that's a separate Properties.Source_* field, kept deliberately apart — see
// renderOwnerGate's "Realtor ≠ payor" label). Mirrors the exact rule scope-creator.html's own
// client-side ownerBillingStatus() already enforces (property -> Owner_ID -> Owners row -> Email),
// as its own pure function so it's unit-testable without mocking Sheets/Gmail.
function scopeProposalResolveRecipient(prop, owners) {
  const owner = (prop && prop.Owner_ID) ? (owners || []).find(o => o.ID === String(prop.Owner_ID)) : null;
  const email = (owner && (owner.Email || '').trim()) || '';
  return { owner: owner || null, email };
}

// B-210 follow-on: POST /scope/proposal/send {scope_id} — admin-gated, mirrors arReportSend's
// shape. Emails the shareable proposal link (same idempotent-per-Link_Rev token as
// /scope/proposal/link — no duplicate link is ever minted) straight to the CONFIRMED PAYOR —
// the owner resolved via Property.Owner_ID, exactly what Section 6 "Confirm the payor" gate
// already enforces client-side. Deliberately never the Realtor/PM referral source (Source_Email
// on Properties) — that field exists specifically to keep the two separate (see renderOwnerGate's
// own "Realtor ≠ payor" label). Re-checks both server-side gates (proposal text generated, owner
// email on file) rather than trusting client state, same defensive posture as every other
// money/customer-facing send in this file.
async function scopeProposalSend(env, body) {
  const id = body && body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  if (!(s.Proposal_Text || '').trim()) return json({ error: 'Generate the proposal first (Generate proposal), then send.' }, 400);
  // Double-send guard (Oct 14 2026): a double tap / retry within PROPOSAL_RESEND_GUARD_MS of the last send is refused
  // BEFORE any email or text goes out (409, nothing sent). A deliberate resend after that still works.
  const lastSent = Date.parse(s.Sent_Date || '');
  if (lastSent && (Date.now() - lastSent) < PROPOSAL_RESEND_GUARD_MS && (Date.now() - lastSent) >= 0) {
    return json({ error: 'This estimate was just sent ' + Math.max(1, Math.round((Date.now() - lastSent) / 1000)) + 's ago - nothing was sent again. Wait a minute if you really want to resend.', code: 'just_sent' }, 409);
  }

  const [props, owners] = await fetchTabs(env, ['Properties', 'Owners']);
  const prop = props.find(p => p.ID === String(s.Property_ID)) || null;
  const { owner, email } = scopeProposalResolveRecipient(prop, owners);
  if (!email) return json({ error: 'No billing-ready owner email on file — confirm the payor (step 6) first.' }, 400);

  const addr = qbPropertyDisplayName(prop) || ('Property ' + s.Property_ID);
  const ownerName = qbOwnerDisplayName(owner) || 'there';

  const token = await scopeProposalLinkToken(env, id);
  if (!token) return json({ error: 'Could not create the proposal link.' }, 500);
  const url = `${PORTAL_BASE}/scope-proposal.html?t=${encodeURIComponent(token)}`;
  const pixelUrl = `${String(env.WORKER_BASE_URL || 'https://maintenance-hub.brett-2f8.workers.dev').replace(/\/+$/, '')}/scope-proposal/px?t=${encodeURIComponent(token)}`;
  const html = buildScopeProposalEmailHtml({ ownerName, addr, url, pixelUrl });
  const subject = `Ridge Co — your estimate for ${addr}`;

  try {
    await gmailSendEmail(env, { to: email, subject, html });
  } catch (e) {
    try {
      await ensureTab(env, PROPOSAL_SEND_LOG_TAB, PROPOSAL_SEND_LOG_COLS);
      await addRow(env, PROPOSAL_SEND_LOG_TAB, { Timestamp: new Date().toISOString(), Scope_ID: String(id), Owner_ID: owner.ID, Owner_Name: ownerName, Email: email, Address: addr, Link: url, Result: 'FAILED: ' + String((e && e.message) || e).slice(0, 200) });
    } catch (_) { /* audit log best-effort */ }
    return json({ error: 'Send failed: ' + e.message }, 500);
  }

  try {
    await ensureColumns(env, 'Scopes', ['Sent_Date', 'Sent_To', 'Send_Count']);
    const nextCount = String((parseInt(s.Send_Count || '0', 10) || 0) + 1);
    await updateRow(env, 'Scopes', id, { Sent_Date: new Date().toISOString(), Sent_To: email, Send_Count: nextCount });
  } catch (_) { /* the email already sent successfully; a failure to stamp the Scopes row shouldn't be reported as a send failure */ }

  // Owner heads-up text (Oct 14 2026): on the FIRST send only (a resend would just nag), unless sms_again:true.
  // Email already went; the text is held/skipped/blocked on its own rules and its outcome is always reported.
  let sms;
  if ((parseInt(s.Send_Count || '0', 10) || 0) === 0 || body.sms_again === true) {
    sms = await proposalOwnerSms(env, { scopeId: String(id), prop, owner, addr, ownerName, override: body.override_quiet_hours === true });
  } else sms = { status: 'not_attempted', note: 'Resend: the owner was already texted on the first send.' };

  try {
    await ensureTab(env, PROPOSAL_SEND_LOG_TAB, PROPOSAL_SEND_LOG_COLS);
    await ensureColumns(env, PROPOSAL_SEND_LOG_TAB, PROPOSAL_SEND_LOG_COLS);
    await addRow(env, PROPOSAL_SEND_LOG_TAB, { Timestamp: new Date().toISOString(), Scope_ID: String(id), Owner_ID: owner.ID, Owner_Name: ownerName, Email: email, Address: addr, Link: url, Result: 'sent', SMS_Result: sms.status + (sms.note ? ' - ' + sms.note : '') });
  } catch (_) { /* audit log best-effort; the send already happened */ }

  return json({ success: true, sent_to: email, sent_at: new Date().toISOString(), url, sms });
}

// PUBLIC (link-token gated): the customer-safe payload scope-proposal.html renders. Serves the
// Job photos attached to this scope's work order (or staged under SCOPE-<id> before a WO exists —
// same key scope-creator.html's own "Before photos" upload already uses, and the same key
// scopeToWO() re-keys onto the real WO_ID at conversion time, so this always finds the right set
// regardless of when in the lifecycle it's called). Customer-safe subset only: 'before'/'photo'/
// 'other' — never 'receipt'/'bill'/'invoice' (private vendor-cost docs, already never Drive-shared
// per NON_SHARE_FILE_TYPES, but filtered here too as defense-in-depth) and never 'after'/'report'
// (not relevant on a pre-signature estimate, admin-internal). Only returns files that are actually
// viewable as an image/video (mirrors the isImage/isVideo check index.html's own gallery uses) —
// a stray PDF wouldn't render in a photo strip anyway. These files are already made
// anyone-with-link shareable at upload time (logAttachment → driveShareAnyone), so returning the
// Drive file id here is safe on this public boundary — same trust level as any other photo URL
// already handed to vendors/tenants elsewhere in the Hub, and never any pricing data.
const SCOPE_PROPOSAL_PHOTO_TYPES = ['before', 'photo', 'other'];
async function scopeProposalPhotos(env, s) {
  try {
    const key = s.WO_ID || ('SCOPE-' + s.ID);
    const rows = await fetchTab(env, 'Attachments');
    return rows
      .filter(a => a.Active !== 'FALSE' && a.WO_ID === key)
      .filter(a => SCOPE_PROPOSAL_PHOTO_TYPES.includes((a.File_Type || 'other').toLowerCase()))
      .map(a => {
        const mime = (a.Mime_Type || '').toLowerCase();
        const isVideo = mime.indexOf('video/') === 0;
        const isImage = mime.indexOf('image/') === 0 || (!mime && !!a.Drive_File_ID);
        return { fileId: a.Drive_File_ID || '', url: a.Drive_URL || '', name: a.File_Name || 'photo', isVideo, isViewable: isVideo || isImage };
      })
      .filter(p => p.isViewable && p.fileId);
  } catch (_) { return []; }
}

// structured per-item/variant view built by scopeProposal() (Proposal_Items_JSON) — HARD RULE:
// strips `vendor_cost` from every variant right here, at the public boundary, so it can never
// reach a customer even though it is stored (privately, Sheets-only) alongside price for later
// use by scopeProposalSign. Also reports the LOCKED signed state (if any) so a revisited link
// shows what was actually signed, never a re-editable form.
// SECURITY FIX (Aug 24 2026): `note` is ALSO stripped here now. It's a free-text field Brett
// types into scope-creator.html's item editor with no internal/customer split — same class of
// field as `vendor_cost`, just never added to this boundary's strip list until a live proposal
// shipped a vendor's raw quote ("Vendor quote $650 for this full punch list...") straight to a
// customer via this exact field. Per Brett's hard rule: nothing about vendor pricing, how a
// price was derived, or any vendor-facing commentary may ever reach a customer-facing surface —
// only the job description and the final price. If a genuinely customer-safe note is ever
// needed, it must be a SEPARATE, explicitly-labeled field — never this one.
async function scopeProposalView(env, url, ua, ctx) {
  const auth = await scopeProposalLinkAuth(env, url.searchParams.get('t'));
  if (!auth) return json({ error: 'invalid_link', message: 'This link is invalid or has expired. Please contact Ridge Co for a current proposal.' }, 401);
  const s = auth.s;
  // Read status (Oct 14 2026): the owner opening the proposal page is the reliable "they looked" signal.
  // Awaited (short) so a failed log is never lost; append &preview=1 to the link to look without counting.
  if (url.searchParams.get('preview') !== '1') await proposalRecordHit(env, s, 'page', ua);
  let addr = await scopeAddr(env, s);
  let rawItems = []; try { rawItems = JSON.parse(s.Proposal_Items_JSON || '[]'); } catch (_) {}
  const items = rawItems.map(it => ({
    id: it.id, area: it.area, trade: it.trade, description: it.description,
    // no vendor_cost, no rc_materials_cost (Ridge Co's own materials cost) — only the customer's
    // materials PRICE + description, and only when the option actually includes materials.
    variants: (it.variants || []).map(v => (+v.materials_price > 0)
      ? { key: v.key, label: v.label, price: v.price, materials_price: +v.materials_price, materials_desc: String(v.materials_desc || 'Materials') }
      : { key: v.key, label: v.label, price: v.price }),
    selected_key: it.selected_key,
    ...(it.optional ? { optional: true } : {}), // optional add-on: unticked by default, price = what it ADDS to the total
  })); // no `note` — free-text field with no internal/customer split; never safe to echo back
  const photos = await scopeProposalPhotos(env, s);
  const subtotal = +(items.reduce((sum, it) => { if (it.optional) return sum; const sel = (it.variants || []).find(v => v.key === it.selected_key) || it.variants[0]; return sum + (sel ? sel.price : 0); }, 0)).toFixed(2);
  const deposit = +(subtotal / 2).toFixed(2);
  const rawSchedule = scopeParsePaymentSchedule(s);
  const scheduleValidation = scopeValidatePaymentSchedule(rawSchedule, await scopeMaxUpfrontPct(env));
  const schedule = scopeComputeMilestoneAmounts(scheduleValidation.schedule || scopeDefaultPaymentSchedule(), subtotal, 0)
    .map(m => ({ label: m.label, percent: m.percent, trigger: m.trigger, customer_amount: m.customer_amount, calc_mode: m.calc_mode, flat_customer_amount: m.flat_customer_amount })); // never vendor_amount — customer-facing boundary
  let signed = null;
  try {
    await scopeSigTab(env);
    const sigs = await fetchTab(env, 'Scope_Signatures');
    const row = sigs.find(r => r.Scope_ID === String(s.ID) && String(r.Active || '').toUpperCase() !== 'FALSE');
    if (row) {
      let sel = {}; try { sel = JSON.parse(row.Selections_JSON || '{}'); } catch (_) {}
      let signedSchedule = schedule; // fallback: unsigned live schedule, shown against the locked subtotal below
      try {
        await paymentMilestonesTab(env);
        const ms = (await fetchTab(env, 'Payment_Milestones')).filter(m => m.Signature_ID === String(row.ID) && String(m.Active || '').toUpperCase() !== 'FALSE');
        if (ms.length) signedSchedule = ms.map(m => ({ label: m.Label, percent: +m.Percent || 0, trigger: m.Trigger, customer_amount: +m.Customer_Amount || 0, calc_mode: m.Calc_Mode === 'flat' ? 'flat' : 'percent', status: m.Status || 'pending' }));
      } catch (_) {}
      signed = { signer_name: row.Signer_Name, signed_date: row.Signed_Date, subtotal: +row.Subtotal || subtotal, deposit: +row.Deposit_Amount || deposit, selections: sel, schedule: signedSchedule };
    }
  } catch (_) {}
  return json({ ok: true, address: addr || ('Property ' + s.Property_ID), title: s.Title || '', status: s.Status || '', items, subtotal, deposit, schedule, proposal_text: s.Proposal_Text || '', signed, photos });
}

// ── Scope proposal e-sign (Aug 19 2026) ─────────────────────────────────────
// Click-to-sign inside the existing Worker+Sheets stack (Brett's explicit choice — no
// Documenso/external e-sign service): typed name + a drawn signature (canvas PNG) + timestamp +
// IP + device, logged to a dedicated Scope_Signatures tab. A valid ESIGN-Act e-signature for a
// contractor proposal, not a notarized legal document. Auth reuses the SAME scope-proposal link
// token as scopeProposalView — no separate PROPOSAL_SIGN_TOKEN needed, since the token already
// scopes access to exactly one scope's proposal.
const SCOPE_SIG_HEADERS = ['ID','Scope_ID','Signer_Name','Signature_PNG','Selections_JSON','Subtotal','Deposit_Amount','Vendor_Cost_Total','Signed_Date','Signed_TS','IP','User_Agent','Status','QB_Invoice_ID','QB_Invoice_Number','QB_Bill_ID','QB_Bill_Number','QB_Final_Invoice_ID','QB_Final_Invoice_Number','QB_Final_Bill_ID','QB_Final_Bill_Number','Bill_Skip_Reason','Final_Bill_Skip_Reason','Created_Date','Active'];
async function scopeSigTab(env) { await ensureTab(env, 'Scope_Signatures', SCOPE_SIG_HEADERS); }

// ── Payment Schedule / Milestones (Sep 14 2026) ─────────────────────────────
// Generalizes the old fixed 50% deposit / 50% final split (scopeProposalBook/BookFinal, above)
// into an arbitrary N-way milestone schedule — Brett: presets 1/3, 1/4, custom (e.g. 50% upfront
// + 25% at a progress milestone + 25% final). Additive/backward-compatible by design: a
// Scope_Signatures row signed BEFORE this shipped has no Payment_Milestones rows and keeps using
// the original 2-stage book/book-final path unchanged — signed-proposals.html branches on
// whether a row has milestones. Every NEW signature gets its schedule expanded into individual
// Payment_Milestones rows at signing time (scopeProposalSign), billed via
// scopeProposalBillMilestones (one or several milestones grouped into a single QB invoice/bill,
// per Brett's "combine in one bill" requirement).
//
// MD Home Improvement Law caveat (Brett confirmed Sep 14 2026, not legal advice): a deposit
// collected before/at signing is capped at 1/3 of the contract price (Md. Bus. Reg. §8-617(b)).
// MAX_UPFRONT_DEPOSIT_PCT_DEFAULT enforces this as a WARNING only (Brett's explicit call — not a
// hard block) on any milestone tagged trigger:'upfront'. A Config key 'MAX_UPFRONT_DEPOSIT_PCT'
// overrides the default if Brett sets one.
const MAX_UPFRONT_DEPOSIT_PCT_DEFAULT = 33.34;
async function scopeMaxUpfrontPct(env) {
  try { const cfg = await fetchConfig(env); const v = parseFloat(cfg.MAX_UPFRONT_DEPOSIT_PCT); return (isFinite(v) && v > 0 && v <= 100) ? v : MAX_UPFRONT_DEPOSIT_PCT_DEFAULT; }
  catch (_) { return MAX_UPFRONT_DEPOSIT_PCT_DEFAULT; }
}
function scopeDefaultPaymentSchedule() {
  return [
    { label: 'Deposit', percent: 33.34, trigger: 'upfront' },
    { label: 'Final', percent: 66.66, trigger: 'completion' },
  ];
}
// Validates + normalizes a milestone array. Percentages must sum to 100 within a small rounding
// tolerance (0.1) — the last entry absorbs drift under that; anything further off is REJECTED
// rather than silently renormalized, since that would change what a customer is agreeing to pay
// without them seeing it. Upfront total over the MD cap is a warning, never a rejection — Brett's
// explicit "warn, don't block" call.
function scopeValidatePaymentSchedule(milestones, maxUpfrontPct) {
  if (!Array.isArray(milestones) || !milestones.length) return { error: 'At least one milestone is required.' };
  const clean = [];
  for (const m of milestones) {
    const label = String((m && m.label) || '').trim().slice(0, 80) || 'Payment';
    const percent = +(+(m && m.percent)).toFixed(2);
    const trigger = ['upfront', 'manual', 'completion'].includes(m && m.trigger) ? m.trigger : 'manual';
    if (!isFinite(percent) || percent <= 0) return { error: `"${label}" needs a percent greater than 0.` };
    // Vendor-pay-per-milestone (Sep 18 2026): defaults TRUE — matches today's implicit
    // always-pay-vendor-every-milestone behavior, so no proposal already signed under the old
    // behavior changes. See scopeVendorPayableSchedule for what FALSE actually does at bill time
    // (rolls this milestone's vendor share forward, never drops it).
    const vendorPaid = !(m && m.vendor_paid === false);
    // Calc mode (Sep 18 2026): 'percent' (default — today's exact behavior, unchanged) or 'flat'
    // — a typed CUSTOMER-facing override for this one milestone. Modeled the same way
    // price_override already sits alongside vendor_cost on a scope item (scopeCleanVariants,
    // above): an overlay field that never replaces the underlying percent/vendor-cost math, which
    // is exactly why vendor-side proration stays percent-based regardless of this flag.
    const calcMode = (m && m.calc_mode === 'flat') ? 'flat' : 'percent';
    let flatCustomerAmount = null;
    if (calcMode === 'flat') {
      const fa = +(+(m && m.flat_customer_amount)).toFixed(2);
      if (!isFinite(fa) || fa < 0) return { error: `"${label}" is set to a flat customer amount, but flat_customer_amount is missing or invalid.` };
      flatCustomerAmount = fa;
    }
    clean.push({ label, percent, trigger, vendor_paid: vendorPaid, calc_mode: calcMode, flat_customer_amount: flatCustomerAmount });
  }
  const total = +clean.reduce((sum, m) => sum + m.percent, 0).toFixed(2);
  if (Math.abs(total - 100) > 0.1) return { error: `Milestone percentages must add up to 100% (currently ${total}%).` };
  if (Math.abs(total - 100) > 0.001) clean[clean.length - 1].percent = +(clean[clean.length - 1].percent + (100 - total)).toFixed(2);
  const warnings = [];
  const upfrontPct = +clean.filter(m => m.trigger === 'upfront').reduce((sum, m) => sum + m.percent, 0).toFixed(2);
  if (upfrontPct > maxUpfrontPct) warnings.push(`Upfront milestones total ${upfrontPct}%, above the ${maxUpfrontPct}% Maryland places on a deposit collected before work begins (Md. Bus. Reg. §8-617). Not blocked — confirm this job is clear before sending.`);
  return { schedule: clean, warnings };
}
// Splits subtotal/vendorCostTotal across a validated schedule. The LAST milestone absorbs any
// rounding remainder so milestones always foot exactly to the signed totals — never drift a cent
// short or over from percent rounding, same discipline as scopeSigVendorBillAmount below.
function scopeComputeMilestoneAmounts(schedule, subtotal, vendorCostTotal) {
  subtotal = +subtotal || 0; vendorCostTotal = +vendorCostTotal || 0;
  // Oct 13 2026: 'flat' rows are fixed customer amounts, exactly as typed. The customer-side
  // ABSORBER (the row that takes rounding and any add-on difference so milestones always foot to
  // the signed total) is the LAST NON-FLAT row — not simply the last row, which may be flat. With
  // no non-flat row there is no absorber (legacy all-flat schedules keep their typed amounts).
  const isFlatRow = (m) => m.calc_mode === 'flat' && m.flat_customer_amount != null;
  let absorber = -1;
  for (let k = schedule.length - 1; k >= 0; k--) { if (!isFlatRow(schedule[k])) { absorber = k; break; } }
  const custAmts = schedule.map((m, i) => isFlatRow(m) ? +(+m.flat_customer_amount).toFixed(2) : +((m.percent / 100) * subtotal).toFixed(2));
  if (absorber >= 0) custAmts[absorber] = +(subtotal - custAmts.reduce((sum, a, i) => i === absorber ? sum : sum + a, 0)).toFixed(2);
  let vendRunning = 0;
  return schedule.map((m, i) => {
    const isLast = i === schedule.length - 1;
    // 'flat' overrides the CUSTOMER amount only, exactly as typed — never the vendor side (see
    // scopeValidatePaymentSchedule's comment on why); vendor proration stays percent-based.
    const custAmt = custAmts[i];
    const vendAmt = isLast ? +(vendorCostTotal - vendRunning).toFixed(2) : +((m.percent / 100) * vendorCostTotal).toFixed(2);
    vendRunning = +(vendRunning + vendAmt).toFixed(2);
    return {
      label: m.label, percent: m.percent, trigger: m.trigger, customer_amount: custAmt, vendor_amount: vendAmt,
      vendor_paid: m.vendor_paid !== false, calc_mode: m.calc_mode === 'flat' ? 'flat' : 'percent',
      flat_customer_amount: (m.flat_customer_amount != null ? m.flat_customer_amount : null),
    };
  });
}
function scopeAbsorberLabel(schedule) { for (let k = schedule.length - 1; k >= 0; k--) { if (!(schedule[k].calc_mode === 'flat' && schedule[k].flat_customer_amount != null)) return schedule[k].label; } return ''; }
// Oct 13 2026: can this schedule take an optional add-on at all? Returns '' when fine, else a plain
// explanation. Flat rows stay fixed; the last non-flat row absorbs the difference, so it must exist
// and must not go negative at the SMALLEST total the customer could sign (percent rows only grow with
// the total, so if it is >= 0 there it is >= 0 at every larger total).
function scopeScheduleAddonProblem(schedule, smallestTotal) {
  const isFlatRow = (m) => m.calc_mode === 'flat' && m.flat_customer_amount != null;
  let absorber = -1;
  for (let k = schedule.length - 1; k >= 0; k--) { if (!isFlatRow(schedule[k])) { absorber = k; break; } }
  if (absorber < 0) return 'Every payment on this schedule is a fixed $ amount, so an optional add-on would leave the payments not adding up to the new total. Make at least one payment (usually the Final) a "% of total" row.';
  const amts = scopeComputeMilestoneAmounts(schedule, smallestTotal, 0);
  if (amts[absorber].customer_amount < 0) return `The fixed-$ payments on this schedule leave "${schedule[absorber].label}" at $${amts[absorber].customer_amount.toFixed(2)} on a $${(+smallestTotal).toFixed(2)} job — lower a fixed amount or raise the % rows so the last % payment is not negative.`;
  return '';
}
// Given a signature's FULL milestone schedule (any order; sorted here by `sequence`), returns the
// ACTUAL vendor-payable amount per milestone once a Vendor_Paid_At_This_Milestone:false milestone's
// share has rolled forward — the vendor's total across the whole schedule is always the sum of
// every milestone's own `vendor_amount` (computed once at signing time by
// scopeComputeMilestoneAmounts and never touched again), just concentrated into fewer/larger draws
// per Brett's explicit requirement (rollover, not a discount). Purely structural: it depends only
// on each milestone's fixed sequence/vendor_amount/vendor_paid, never on what has or hasn't
// actually been billed yet — so it's safe to recompute on every call and safe even if milestones
// end up billed out of sequence order.
//   • vendor_paid:true  → payable = its own vendor_amount + anything carried forward from
//     immediately-preceding vendor_paid:false milestone(s); carry resets to 0 after.
//   • vendor_paid:false → payable = 0 (nothing billed to the vendor for this milestone THIS round);
//     its vendor_amount is added to the carry for the next vendor_paid:true milestone to absorb.
//   • A trailing run of vendor_paid:false milestones with no later TRUE milestone to catch it (a
//     degenerate schedule — e.g. the FINAL milestone itself is flagged false) would otherwise
//     strand that money forever; instead it's force-attached to the LAST milestone in the
//     schedule regardless of that milestone's own flag, since "the vendor is never underpaid in
//     total" (Brett's explicit requirement) outranks a strict last-TRUE-wins read. Flagged in the
//     build brief as worth a real UI warning if it's ever actually configured this way.
function scopeVendorPayableSchedule(milestones) {
  const ordered = (Array.isArray(milestones) ? milestones : []).slice().sort((a, b) => (+a.sequence || 0) - (+b.sequence || 0));
  let carry = 0;
  const out = ordered.map(m => {
    const own = +m.vendor_amount || 0;
    const paid = m.vendor_paid !== false;
    if (paid) {
      const eff = +(own + carry).toFixed(2);
      carry = 0;
      return { id: m.id, sequence: m.sequence, vendor_payable: eff };
    }
    carry = +(carry + own).toFixed(2);
    return { id: m.id, sequence: m.sequence, vendor_payable: 0 };
  });
  if (carry > 0 && out.length) out[out.length - 1].vendor_payable = +(out[out.length - 1].vendor_payable + carry).toFixed(2);
  return out;
}
function scopeParsePaymentSchedule(s) {
  try { const arr = JSON.parse((s && s.Payment_Schedule_JSON) || 'null'); if (Array.isArray(arr) && arr.length) return arr; } catch (_) {}
  return scopeDefaultPaymentSchedule();
}

// POST /scope/payment-schedule (admin) { scope_id, milestones:[{label,percent,trigger}] }
// Saved onto Scopes.Payment_Schedule_JSON — read by scopeProposal (proposal text/amounts) and
// scopeProposalSign (which expands it into Payment_Milestones rows at signing time). Does not
// retroactively touch any scope that's already been signed.
async function scopeSetPaymentSchedule(env, body) {
  const id = body && body.scope_id; if (!id) return json({ error: 'scope_id required' }, 400);
  await scopesTab(env);
  const s = await scopeFind(env, id); if (!s) return json({ error: 'Scope not found' }, 404);
  const maxUpfront = await scopeMaxUpfrontPct(env);
  const { schedule, error, warnings } = scopeValidatePaymentSchedule(body && body.milestones, maxUpfront);
  if (error) return json({ error }, 400);
  await ensureColumns(env, 'Scopes', ['Payment_Schedule_JSON']);
  await updateRow(env, 'Scopes', id, { Payment_Schedule_JSON: JSON.stringify(schedule), Updated_Date: new Date().toISOString() });
  return json({ success: true, schedule, warnings: warnings || [] });
}

const PAYMENT_MILESTONES_HEADERS = ['ID','Scope_ID','Signature_ID','Label','Percent','Trigger','Sequence','Customer_Amount','Vendor_Amount','Status','QB_Invoice_ID','QB_Invoice_Number','QB_Bill_ID','QB_Bill_Number','Billed_Date','Created_Date','Active','Vendor_Paid_At_This_Milestone','Calc_Mode','Flat_Customer_Amount'];
async function paymentMilestonesTab(env) { await ensureTab(env, 'Payment_Milestones', PAYMENT_MILESTONES_HEADERS); }

// POST /scope-proposal/sign — PUBLIC (link-token gated, body.t). {t, signer_name, signature_png,
// selections:{itemId:variantKey}}. MONEY IS SERVER-AUTHORITATIVE: the client sends WHICH variant
// per item, never a dollar amount — price comes from the already-computed Proposal_Items_JSON,
// vendor cost (for the later prorated vendor bill, Phase 3) comes from the private Line_Items,
// and neither is ever echoed back to the client. Idempotent — re-submitting an already-signed
// scope returns the existing signature rather than creating a second one.
async function scopeProposalSign(env, body, ip, ua) {
  const auth = await scopeProposalLinkAuth(env, body && body.t);
  if (!auth) return json({ error: 'invalid_link', message: 'This link is invalid or has expired. Please contact Ridge Co for a current proposal.' }, 401);
  const s = auth.s;
  const signer = String((body && body.signer_name) || '').trim().slice(0, 120);
  if (signer.length < 2) return json({ error: 'signer_name required' }, 400);
  const sigPng = String((body && body.signature_png) || '');
  if (!sigPng || sigPng.length < 100) return json({ error: 'A drawn signature is required' }, 400);

  await scopeSigTab(env);
  const existing = await fetchTab(env, 'Scope_Signatures');
  const dup = existing.find(r => r.Scope_ID === String(s.ID) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (dup) return json({ ok: true, id: dup.ID, duplicate: true, subtotal: +dup.Subtotal || 0, deposit: +dup.Deposit_Amount || 0 });

  let items = []; try { items = JSON.parse(s.Proposal_Items_JSON || '[]'); } catch (_) {}
  if (!items.length) return json({ error: 'Proposal not ready to sign yet.' }, 400);
  const selections = (body && body.selections && typeof body.selections === 'object') ? body.selections : {};
  let subtotal = 0;
  const finalSelections = {};
  for (const it of items) {
    const variants = it.variants || [];
    let key = selections[it.id];
    // Optional add-on: only included if the customer's selection names one of its options; anything
    // else (absent, '__none__', a bad key) means DECLINED — never silently added to what they owe.
    if (it.optional && !variants.some(v => v.key === key)) continue;
    if (!variants.some(v => v.key === key)) key = it.selected_key || (variants[0] && variants[0].key);
    const sel = variants.find(v => v.key === key) || variants[0];
    if (!sel) continue;
    subtotal += (+sel.price || 0);
    finalSelections[it.id] = key;
  }
  // Vendor cost is looked up from Line_Items (the private source of truth), never from the
  // customer-facing Proposal_Items_JSON/selections payload, and never returned to the client.
  let vendorCostTotal = 0;
  for (const it of scopeParseItems(s)) {
    const key = finalSelections[it.id];
    if (key === undefined) continue; // declined optional add-on — not signed, so no vendor cost
    const v = (it.variants || []).find(x => x.key === key) || (it.variants || [])[0];
    if (v) vendorCostTotal += (+v.vendor_cost || 0);
  }
  // Ridge Co–supplied materials on the SIGNED options (Sep 22 2026) — never part of
  // vendorCostTotal (so never on a vendor bill); recorded as the budget Signed Proposals tracks
  // matched receipts against. Cost from private Line_Items, customer price from Proposal_Items_JSON.
  let rcMaterialsCost = 0, rcMaterialsPrice = 0;
  for (const it of scopeParseItems(s)) {
    const key = finalSelections[it.id];
    if (key === undefined) continue; // declined optional add-on
    const v = (it.variants || []).find(x => x.key === key) || (it.variants || [])[0];
    if (v) rcMaterialsCost += (+v.rc_materials_cost || 0);
  }
  for (const it of items) {
    const key = finalSelections[it.id];
    if (key === undefined) continue; // declined optional add-on
    const v = (it.variants || []).find(x => x.key === key) || (it.variants || [])[0];
    if (v) rcMaterialsPrice += (+v.materials_price || 0);
  }
  rcMaterialsCost = +rcMaterialsCost.toFixed(2); rcMaterialsPrice = +rcMaterialsPrice.toFixed(2);
  subtotal = +subtotal.toFixed(2); vendorCostTotal = +vendorCostTotal.toFixed(2);
  const deposit = +(subtotal / 2).toFixed(2); // legacy column, kept for any old dashboard summing it — not used for new billing
  if (items.some(it => it.optional)) {
    // A schedule that can't absorb the signed total (all rows flat, or fixed $ exceed the total) must
    // never be signed — refuse BEFORE any write, tell Brett (telemetry), show the customer a plain message.
    const sv = scopeValidatePaymentSchedule(scopeParsePaymentSchedule(s), await scopeMaxUpfrontPct(env));
    const addonProblem = scopeScheduleAddonProblem(sv.schedule || scopeDefaultPaymentSchedule(), subtotal);
    if (addonProblem) {
      let telemetryError = '';
      try { await logTelemetry(env, { Source: 'worker', Job_Type: 'scope_sign_schedule_mismatch', Skill_Or_Endpoint: '/scope-proposal/sign', Success: 'FALSE', Notes: `scope=${s.ID} subtotal=${subtotal} problem=${addonProblem}`.slice(0, 480) }); } catch (e) { telemetryError = String(e && e.message || e); }
      return json({ error: 'schedule_unavailable', message: 'This proposal can\'t be signed online right now. Please contact Ridge Co and we\'ll send you a corrected copy.', ...(telemetryError ? { telemetry_error: telemetryError } : {}) }, 409);
    }
  }
  const now = new Date();
  if (rcMaterialsCost > 0 || rcMaterialsPrice > 0) {
    try { await ensureColumns(env, 'Scope_Signatures', ['RC_Materials_Cost', 'RC_Materials_Price']); } catch (_) { /* logged centrally by ensureColumns */ }
  }
  const sigResp = await addRow(env, 'Scope_Signatures', {
    RC_Materials_Cost: rcMaterialsCost ? String(rcMaterialsCost) : '', RC_Materials_Price: rcMaterialsPrice ? String(rcMaterialsPrice) : '',
    Scope_ID: String(s.ID), Signer_Name: signer,
    Signature_PNG: sigPng.length <= 45000 ? sigPng : '', // Sheets cell cap ~50k chars; skip if oversized
    Selections_JSON: JSON.stringify(finalSelections),
    Subtotal: String(subtotal), Deposit_Amount: String(deposit), Vendor_Cost_Total: String(vendorCostTotal),
    Signed_Date: now.toISOString().slice(0, 10), Signed_TS: now.toISOString(),
    IP: String(ip || '').slice(0, 60), User_Agent: String(ua || '').slice(0, 300),
    Status: 'Signed', Created_Date: now.toISOString(), Active: 'TRUE',
  });
  const sigJson = await sigResp.json().catch(() => ({}));
  const signatureId = sigJson.id;

  // Expand the scope's payment schedule (whatever Brett configured on scope-creator.html, or the
  // built-in default if he never touched it) into individual Payment_Milestones rows tied to
  // this signature — one row per milestone, billed independently later via
  // scopeProposalBillMilestones. This is what actually replaces the old fixed deposit/final
  // split going forward; the Deposit_Amount/Subtotal columns above are kept only for backward
  // compatibility with anything still reading the old 2-stage shape.
  let milestones = [];
  if (signatureId) {
    try {
      const maxUpfront = await scopeMaxUpfrontPct(env);
      const rawSchedule = scopeParsePaymentSchedule(s);
      const { schedule } = scopeValidatePaymentSchedule(rawSchedule, maxUpfront);
      const clean = schedule || scopeDefaultPaymentSchedule();
      const amounts = scopeComputeMilestoneAmounts(clean, subtotal, vendorCostTotal);
      await paymentMilestonesTab(env);
      try { await ensureColumns(env, 'Payment_Milestones', ['Vendor_Paid_At_This_Milestone', 'Calc_Mode', 'Flat_Customer_Amount']); } catch (_) {}
      for (let i = 0; i < amounts.length; i++) {
        const m = amounts[i];
        const mResp = await addRow(env, 'Payment_Milestones', {
          Scope_ID: String(s.ID), Signature_ID: String(signatureId), Label: m.label, Percent: String(m.percent),
          Trigger: m.trigger, Sequence: String(i + 1), Customer_Amount: String(m.customer_amount), Vendor_Amount: String(m.vendor_amount),
          Status: 'pending', Created_Date: now.toISOString(), Active: 'TRUE',
          Vendor_Paid_At_This_Milestone: m.vendor_paid !== false ? 'TRUE' : 'FALSE',
          Calc_Mode: m.calc_mode === 'flat' ? 'flat' : 'percent',
          Flat_Customer_Amount: (m.flat_customer_amount != null ? String(m.flat_customer_amount) : ''),
        });
        const mJson = await mResp.json().catch(() => ({}));
        milestones.push(Object.assign({ id: mJson.id }, m));
      }
    } catch (e) {
      // A milestone-row failure must never undo the signature that already succeeded — the
      // Hub can still bill off Scope_Signatures' own Subtotal/Deposit_Amount via the legacy
      // book/book-final path as a fallback if this ever happens; not silently swallowed either,
      // since the empty `milestones` array itself is the visible signal (no schedule shown yet).
    }
  }

  await updateRow(env, 'Scopes', s.ID, { Status: 'signed', Updated_Date: now.toISOString() });
  await setApprovalStage(env, { woId: s.WO_ID || '', scopeId: s.ID, stage: 'Pre-approved' });
  // Texts (rule 201): Brett + the vendor learn the owner signed and the deposit is pending. Best-effort.
  try {
    const c = await estimateSmsContext(env, s.WO_ID || '', s.Vendor_ID);
    const job = s.WO_ID ? ('work order ' + s.WO_ID) : ('proposal #' + s.ID);
    await sendTemplatedSms(env, { type: 'admin_proposal_signed', kind: 'admin', wo_id: s.WO_ID || '', unit_id: s.Unit_ID || '', property: c.property, tokens: { Signer: signer, Job: job, Address: c.address } });
    if (c.vendor && c.vendor.Phone) await sendTemplatedSms(env, { type: 'vendor_proposal_signed', kind: 'vendor', vendor: c.vendor, wo_id: s.WO_ID || '', unit_id: s.Unit_ID || '', property: c.property, tokens: { FirstName: vendorFirstName(c.vendor), Job: job } });
  } catch (_) {}
  return json({ ok: true, subtotal, deposit, schedule: milestones });
}

// ── Vendor-bill gap tracking (Aug 24 2026) ──────────────────────────────────
// A signed proposal books TWO things: the customer's deposit invoice and the vendor's prorated
// bill. The invoice half is persisted immediately (so a bill failure can't duplicate it), which
// means a booking whose bill silently failed still flips to Status: Booked and, before this,
// rendered as a plain green "✓ Booked" forever — Ridge Co invoiced the customer and never
// created the payable, with nothing left behind to notice it by. Bill_Skip_Reason records WHY a
// bill didn't happen, persistently, and is cleared the moment a bill exists.
//
// Exactly one skip is legitimate: in-house work. Ridge Co never creates a payable to itself for
// Brett's own hours, so that case must read as a calm note, not an alarm — otherwise the alarm
// gets ignored and the real gaps ride along with it.
const SCOPE_BILL_SKIP_INHOUSE = 'In-house vendor — no vendor bill is created for Ridge Co\'s own work.';
function scopeSigSkipIsInHouse(reason) { return /in-house/i.test(String(reason || '')); }

// Classify a signed proposal's vendor-bill state for the Hub. `inHouseFallback` re-derives the
// in-house case for rows booked BEFORE Bill_Skip_Reason existed (from the scope's vendor on the
// Vendors tab) — without it every legitimate old in-house booking would false-flag as a missing
// bill, which is the fastest way to teach Brett to ignore the banner.
//   'not_booked' — nothing booked yet, the normal pre-billing state.
//   'billed'     — a QB bill exists. Nothing to say.
//   'in_house'   — no bill, and that is expected. Calm note.
//   'missing'    — no bill and there should be one. Hard-stop banner + retry.
function scopeSigBillGap(row, inHouseFallback) {
  row = row || {};
  const booked = String(row.Status || '') === 'Booked' || !!row.QB_Invoice_ID;
  if (!booked) return { kind: 'not_booked', reason: '' };
  if (row.QB_Bill_ID) return { kind: 'billed', reason: '' };
  const reason = String(row.Bill_Skip_Reason || '').trim();
  if (reason) return { kind: scopeSigSkipIsInHouse(reason) ? 'in_house' : 'missing', reason };
  if (inHouseFallback) return { kind: 'in_house', reason: SCOPE_BILL_SKIP_INHOUSE };
  return { kind: 'missing', reason: 'The customer was invoiced but no vendor bill was created, and no reason was recorded (booked before skip-reason tracking).' };
}

// Same classification as scopeSigBillGap, above, for the FINAL-balance half
// (scopeProposalBookFinal) — added Sep 18 2026 after a real gap: 1305 N Calvert St's final
// vendor bill existed in QuickBooks but was invisible everywhere Brett actually looks (this
// page had no banner for it, and Who To Pay never knew Signed-Proposal bills exist at all — see
// the qbPayables changes below). The final phase had every other protection rule 145 added to
// the deposit phase except this one.
function scopeSigFinalBillGap(row, inHouseFallback) {
  row = row || {};
  const booked = !!row.QB_Final_Invoice_ID;
  if (!booked) return { kind: 'not_booked', reason: '' };
  if (row.QB_Final_Bill_ID) return { kind: 'billed', reason: '' };
  const reason = String(row.Final_Bill_Skip_Reason || '').trim();
  if (reason) return { kind: scopeSigSkipIsInHouse(reason) ? 'in_house' : 'missing', reason };
  if (inHouseFallback) return { kind: 'in_house', reason: SCOPE_BILL_SKIP_INHOUSE };
  return { kind: 'missing', reason: 'The customer was invoiced the final balance but no vendor bill was created, and no reason was recorded (booked before skip-reason tracking).' };
}

// GET /scope-proposal/signed (admin) — signed scope proposals, for the Hub to review before
// booking them into QuickBooks via POST /scope-proposal/book (below).
async function scopeProposalSignedList(env, url) {
  await scopeSigTab(env);
  const rows = await fetchTab(env, 'Scope_Signatures');
  const scopes = await fetchTab(env, 'Scopes').catch(() => []);
  const props = await fetchTab(env, 'Properties').catch(() => []);
  // Vendors is read only to re-derive the in-house case for legacy rows (see scopeSigBillGap).
  const vendors = await fetchTab(env, 'Vendors').catch(() => []);
  // Payment_Milestones (Sep 14 2026): rows signed under the new milestone system carry these;
  // rows signed before it shipped have none and keep rendering the old deposit/final UI
  // (signed-proposals.html branches on milestones.length).
  let allMilestones = [];
  try { await paymentMilestonesTab(env); allMilestones = await fetchTab(env, 'Payment_Milestones'); } catch (_) {}
  // Receipts on each signed scope's work order = the ACTUAL side of Ridge Co materials budget
  // vs actual (Sep 22 2026). null (not []) on a read failure so the page says "couldn't check"
  // instead of a confident $0.
  let allReceipts = null;
  try { allReceipts = await fetchTab(env, 'Receipts'); } catch (_) {}
  const out = rows.filter(r => String(r.Active || '').toUpperCase() !== 'FALSE').map(r => {
    const sc = scopes.find(x => x.ID === r.Scope_ID) || {};
    const p = props.find(x => x.ID === sc.Property_ID) || {};
    let sel = {}; try { sel = JSON.parse(r.Selections_JSON || '{}'); } catch (_) {}
    const subtotal = +r.Subtotal || 0, deposit = +r.Deposit_Amount || 0, vendorCostTotal = +r.Vendor_Cost_Total || 0;
    // The Hub's "Bill vendor (deposit share)" figure must be the amount book() will ACTUALLY
    // bill — Vendor_Cost_Total × deposit/subtotal — not the vendor's full job cost. Showing the
    // full cost under a "deposit share" label is how a $650 job read as a $650 deposit bill when
    // the real one was $325.
    const { amount: vendorBillAmount } = scopeSigVendorBillAmount(vendorCostTotal, deposit, subtotal);
    const vend = (sc.Vendor_ID && vendors.find(v => v.ID === String(sc.Vendor_ID))) || null;
    const vendInHouse = !!vend && String(vend.In_House || '').toUpperCase() === 'TRUE';
    const gap = scopeSigBillGap(r, vendInHouse);
    const finalGap = scopeSigFinalBillGap(r, vendInHouse);
    const milestones = allMilestones
      .filter(m => m.Signature_ID === String(r.ID) && String(m.Active || '').toUpperCase() !== 'FALSE')
      .sort((a, b) => (+a.Sequence || 0) - (+b.Sequence || 0))
      .map(m => ({
        id: m.ID, label: m.Label, percent: +m.Percent || 0, trigger: m.Trigger,
        customer_amount: +m.Customer_Amount || 0, vendor_amount: +m.Vendor_Amount || 0, status: m.Status || 'pending',
        qb_invoice_id: m.QB_Invoice_ID || '', qb_invoice_number: m.QB_Invoice_Number || '',
        qb_bill_id: m.QB_Bill_ID || '', qb_bill_number: m.QB_Bill_Number || '', billed_date: m.Billed_Date || '',
        // CAP-036 #14 — "Invoiced — Pending Info" flag, layered on top of Status (see
        // setMilestonePendingInfo / scopeProposalBillMilestones).
        pending_info: String(m.Pending_Info || '').toUpperCase() === 'TRUE',
        pending_info_note: m.Pending_Info_Note || '',
      }));
    return {
      id: r.ID, scope_id: r.Scope_ID, wo_id: sc.WO_ID || '', property: p.Address || ('Property ' + sc.Property_ID),
      title: sc.Title || '', signer: r.Signer_Name, signed_date: r.Signed_Date, signed_ts: r.Signed_TS,
      subtotal: subtotal, deposit: deposit, vendor_cost_total: vendorCostTotal, vendor_bill_amount: vendorBillAmount, selections: sel,
      status: r.Status || 'Signed', qb_invoice_id: r.QB_Invoice_ID || '', qb_invoice_number: r.QB_Invoice_Number || '',
      qb_bill_id: r.QB_Bill_ID || '', qb_bill_number: r.QB_Bill_Number || '',
      qb_final_invoice_id: r.QB_Final_Invoice_ID || '', qb_final_invoice_number: r.QB_Final_Invoice_Number || '',
      qb_final_bill_id: r.QB_Final_Bill_ID || '', qb_final_bill_number: r.QB_Final_Bill_Number || '',
      bill_gap: gap.kind, bill_skip_reason: gap.reason,
      final_bill_gap: finalGap.kind, final_bill_skip_reason: finalGap.reason, milestones,
      materials: scopeMaterialsBudgetSummary(+r.RC_Materials_Cost || 0, +r.RC_Materials_Price || 0, sc.WO_ID || '', allReceipts),
    };
  });
  out.sort((a, b) => String(b.signed_ts).localeCompare(String(a.signed_ts)));
  return json(out);
}

// Pure: Ridge Co materials budget (what the signed proposal priced in) vs actual receipts matched
// to the scope's work order (Sep 22 2026). Every receipt on a signed scope's WO counts — those are
// blocked from being invoiced again via Review Bills (scopeCoveringSignature), so this is the one
// place they stay visible. receipts === null means the Receipts read failed.
function scopeMaterialsBudgetSummary(budgetCost, budgetPrice, woId, receipts) {
  budgetCost = +(+budgetCost || 0).toFixed(2); budgetPrice = +(+budgetPrice || 0).toFixed(2);
  if (receipts === null) return { budget_cost: budgetCost, budget_price: budgetPrice, actual: null, receipt_count: null, variance: null, state: 'unknown' };
  // Vendor-logged receipts (Role 'vendor') are the vendor's own purchases, inside their cost — not
  // Ridge Co spending — so they never count toward "actual" here.
  const mine = woId ? (receipts || []).filter(rc => String(rc.WO_ID) === String(woId) && String(rc.Active || '').toUpperCase() !== 'FALSE' && (parseFloat(rc.Amount) || 0) > 0 && String(rc.Role || '').toLowerCase() !== 'vendor') : [];
  const actual = +mine.reduce((sum, rc) => sum + (parseFloat(rc.Amount) || 0), 0).toFixed(2);
  const variance = +(budgetCost - actual).toFixed(2); // + = under budget, - = over
  // No materials budget → 'none': those receipts aren't part of the proposal and keep billing
  // through Review Bills as always (scopeCoveringSignature doesn't cover the WO), so nothing to show.
  let state = 'none';
  if (budgetCost > 0) state = actual === 0 ? 'not_bought' : (variance < 0 ? 'over' : 'within');
  return { budget_cost: budgetCost, budget_price: budgetPrice, actual, receipt_count: mine.length, variance, state };
}

// Pure: the active signed Scope_Signatures row (if any) whose scope owns this work order AND
// priced Ridge Co materials into the proposal (RC_Materials_Cost > 0) — i.e. the owner already
// pays for Ridge Co's materials through the proposal's payment milestones, so receipts on it must
// never be invoiced a second time through Review Bills (Sep 22 2026, Brett: "track vs budget +
// block double-billing"). A signed proposal with NO materials budget (every proposal signed before
// this shipped) is deliberately NOT covered: its receipts were never priced in, so they keep
// billing through Review Bills exactly as before — blocking them would lose the money instead.
// Matches Scopes.WO_ID first, then Work_Orders.Scope_ID if given.
function scopeCoveringSignature(scopes, sigs, woId, wo) {
  if (!woId) return null;
  const woScopeId = wo && wo.Scope_ID ? String(wo.Scope_ID) : '';
  const scopeIds = (scopes || []).filter(s => String(s.WO_ID || '') === String(woId) || (woScopeId && String(s.ID) === woScopeId)).map(s => String(s.ID));
  if (!scopeIds.length) return null;
  const sig = (sigs || []).find(r => scopeIds.includes(String(r.Scope_ID)) && String(r.Active || '').toUpperCase() !== 'FALSE' && (parseFloat(r.RC_Materials_Cost) || 0) > 0);
  return sig ? { scope_id: String(sig.Scope_ID), signature_id: String(sig.ID), materials_budget: +(parseFloat(sig.RC_Materials_Cost) || 0).toFixed(2) } : null;
}
async function scopeCoveringSignatureForWO(env, woId) {
  if (!woId) return null;
  // A tab that doesn't exist yet means "no signed scopes" — any OTHER read failure throws, so a
  // caller never mistakes "couldn't check" for "not covered" (that would re-open double-billing).
  const orEmpty = e => { if (isMissingTabError(e)) return []; throw e; };
  const [scopes, sigs] = await Promise.all([fetchTab(env, 'Scopes').catch(orEmpty), fetchTab(env, 'Scope_Signatures').catch(orEmpty)]);
  return scopeCoveringSignature(scopes, sigs, woId, null);
}

// Which trade to book the deposit/bill lines under. A Scope has no single Trade field of its
// own (it can mix trades across items), so this takes a majority vote across the SIGNED items
// (by item count — simple and predictable) and falls back to General on a tie or a miss. Good
// enough for the invoice/bill line + account routing; it is never shown to the customer.
function scopeSigTrade(items, selections) {
  const counts = {};
  for (const it of items) {
    if (!selections || selections[it.id] === undefined) continue; // only items actually selected/signed
    const t = (it.trade || 'General').trim() || 'General';
    counts[t] = (counts[t] || 0) + 1;
  }
  let best = 'General', bestN = 0;
  for (const t in counts) if (counts[t] > bestN) { best = t; bestN = counts[t]; }
  return QB_TRADE_MAP[best] ? best : 'General';
}

// The vendor bill is prorated to the SAME share of vendor cost as the deposit is of the
// signed subtotal (deposit/subtotal ratio — normally 0.5 since deposit = subtotal/2, but
// computed rather than hardcoded so a future non-50% deposit policy prorates correctly too).
// Falls back to a straight 50% only if subtotal is somehow 0 (never divide by zero).
function scopeSigVendorBillAmount(vendorCostTotal, deposit, subtotal) {
  const ratio = subtotal > 0 ? (deposit / subtotal) : 0.5;
  return { ratio, amount: +((vendorCostTotal || 0) * ratio).toFixed(2) };
}

// POST /scope-proposal/book (admin) { id, preview_only }
// Books the QuickBooks side of a signed scope proposal (the NEW generic Scope_Signatures
// e-sign system — Phase 2, following the per-item e-sign work of Aug 19/rule 123): a customer
// invoice for the DEPOSIT (row.Deposit_Amount — half of the signed subtotal) + a vendor bill
// for the SAME proportion of the vendor's cost (Vendor_Cost_Total × deposit/subtotal), so what
// Ridge Co pays the vendor up front tracks what actually came in from the customer rather than
// fronting the vendor's full cost before the customer pays the balance. This is a separate,
// parallel system from the older proposalBook() (B-076, PROPOSAL_CONFIG-registry-based, full
// vendor cost billed immediately) — proposalBook is untouched; this mirrors its preview-first /
// admin-gated / idempotent safety pattern for the new Scopes/Scope_Signatures data model:
//   • preview_only returns the computed invoice/bill lines + warnings, commits nothing.
//   • the invoice id is persisted immediately after creation, before the bill is attempted, so
//     a later failure (bill error, dropped connection) can never cause a duplicate invoice.
//   • the bill is wrapped in try/catch so its failure can never hide or roll back the invoice.
//   • re-calling after either half already exists skips that half rather than double-booking.
// Shared party/trade resolution for booking a scope proposal's QuickBooks side — used by BOTH
// the deposit booking (scopeProposalBook) and the final-balance booking (scopeProposalBookFinal,
// Sep 2 2026) so the two halves of a job can never resolve to a different customer/vendor/trade
// due to duplicated logic drifting apart.
// ── Vendor Standalone Billing + Self-Serve Work Orders (Sep 24 2026 build brief) ───────────
// PURE helpers — no I/O, unit-tested by test/vendor-standalone-billing-selfserve.test.mjs.

// §4a/4b: a One-Off Job (self-serve WO) can never be created with no stated reason. 'other'
// requires a real note; 'owner'/'brett' accept one but don't require it.
function validateApprovalSource(source, note) {
  const s = String(source || '').trim().toLowerCase();
  if (!['owner', 'brett', 'other'].includes(s)) {
    return { ok: false, error: 'Approval_Source must be owner, brett, or other' };
  }
  if (s === 'other' && !String(note || '').trim()) {
    return { ok: false, error: 'Approval_Note is required when Approval_Source is "other"' };
  }
  return { ok: true, source: s, note: String(note || '').trim() };
}

// §3c: never trust the client — a standalone bill may only target a property the vendor's
// own Billing_Property_Access allow-list already carries (or that an approved access-request
// has since appended to it — see vendorAccessRequestApprove).
function vendorHasBillingPropertyAccess(vendor, propertyId) {
  const list = String((vendor && vendor.Billing_Property_Access) || '').split(',').map(s => s.trim()).filter(Boolean);
  return list.includes(String(propertyId || '').trim());
}

// §3c: same Total/Receipts_Total/Receipts_Reimburse_Total shape addVendorBill's normal
// hourly/flat + receipts flow already produces (and Review Bills' irCalc() already reads) —
// Total is what's actually owed TO THE VENDOR (excludes items paid on Ridge Co's own card),
// Receipts_Total is the full billable amount (both pay modes) that reaches the customer
// invoice via buildInvoiceLines. Keeping this identical to the existing formula means no
// downstream code (irCalc, buildInvoiceLines) needs to know a bill is standalone at all.
function computeStandaloneBillTotals(lineItems) {
  const items = Array.isArray(lineItems) ? lineItems : [];
  let receiptsTotal = 0, reimburseTotal = 0;
  for (const it of items) {
    const amt = +(Number(it && it.amount) || 0);
    if (amt <= 0) continue;
    receiptsTotal += amt;
    if (!it || it.pay !== 'account') reimburseTotal += amt;
  }
  return {
    receipts_total: +receiptsTotal.toFixed(2),
    receipts_reimburse_total: +reimburseTotal.toFixed(2),
    total: +reimburseTotal.toFixed(2),
  };
}

async function scopeSigResolveParties(env, s, row) {
  let selections = {}; try { selections = JSON.parse(row.Selections_JSON || '{}'); } catch (_) {}
  const items = scopeParseItems(s);
  const tradeName = scopeSigTrade(items, selections);
  const trade = QB_TRADE_MAP[tradeName] || QB_TRADE_MAP.General;

  const [props, units, owners, vendors] = await fetchTabs(env, ['Properties', 'Units', 'Owners', 'Vendors']);
  const prop  = props.find(p => p.ID === s.Property_ID) || null;
  const unit  = (s.Unit_ID && units.find(u => u.ID === s.Unit_ID)) || null;
  const owner = prop ? (owners.find(o => o.ID === prop.Owner_ID) || null) : null;
  const vendor = (s.Vendor_ID && vendors.find(v => v.ID === String(s.Vendor_ID))) || null;
  const billTo = qbResolveBillTo(owner, prop, unit);
  const custDisplay = billTo.display || (owner && qbOwnerDisplayName(owner)) || 'Customer';
  const vendDisplay = vendor ? (vendor.Company || vendor.Name || [vendor.First_Name, vendor.Last_Name].filter(Boolean).join(' ') || ('Vendor ' + s.Vendor_ID)).trim() : '';
  const vendorInHouse = !!vendor && String(vendor.In_House || '').toUpperCase() === 'TRUE';
  const unitLabel = unit ? qbUnitLabel(unit) : '';
  const addr = qbPropertyDisplayName(prop) ? (qbPropertyDisplayName(prop) + (unitLabel ? (' ' + unitLabel) : '')) : ('Property ' + s.Property_ID);

  return { tradeName, trade, prop, unit, owner, vendor, billTo, custDisplay, vendDisplay, vendorInHouse, addr };
}

// POST /scope-proposal/bill-milestones (admin) { signature_id, milestone_ids:[...], preview_only }
// Generalized replacement for scopeProposalBook/BookFinal's fixed 2-stage booking, for any
// signature that has Payment_Milestones rows (i.e. signed after Sep 14 2026's schedule system
// shipped — older rows keep using book/book-final untouched, see the section header above).
// Bills one or MORE milestones together as a single grouped QB invoice + single grouped QB
// vendor bill (Brett: "ability to combine in one bill if I need to" — jobs sometimes move faster
// than he can check in on). Same safety shape as scopeProposalBook: preview_only computes and
// returns without writing; the invoice is persisted before the bill is attempted so a bill
// failure can never duplicate the invoice on retry; a bill failure never hides or rolls back an
// already-created invoice. Every milestone in the request must belong to the same signature and
// still be 'pending' — mixing signatures or re-billing an already-billed milestone is rejected
// outright rather than silently partial-processed.
// POST /scope-proposal/milestone/set-pending-info { signature_id, milestone_id, pending_info, note?, set_by? }
// CAP-036 #14's confirmed scope also covers Scope Proposal / milestone billing, not just plain
// vendor invoices (Brett, answering the open question directly: "applies to Scope Proposal /
// milestone billing too"). Payment_Milestones only ever has Status 'pending' → 'billed'
// (scopeProposalBillMilestones is the only thing that flips it) — same flag-on-top pattern as
// Vendor_Bills: a 'pending' milestone can ALSO be flagged Pending_Info, blocking it from being
// billed (soft block, overridable — see scopeProposalBillMilestones below) until Brett clears it.
async function setMilestonePendingInfo(env, body) {
  const msId = String(body.milestone_id || '').trim();
  const sigId = String(body.signature_id || '').trim();
  if (!msId || !sigId) return json({ error: 'signature_id and milestone_id required' }, 400);
  const pending = body.pending_info === true || String(body.pending_info).toUpperCase() === 'TRUE';
  const note = String(body.note || '').trim();
  if (pending && !note) return json({ error: 'A note is required when flagging Pending Info — say what\'s missing.' }, 400);

  try {
    await paymentMilestonesTab(env);
    await ensureColumns(env, 'Payment_Milestones', ['Pending_Info', 'Pending_Info_Note', 'Pending_Info_Set_By', 'Pending_Info_Set_Date']);
  } catch (e) { return json({ error: 'Could not prepare Payment_Milestones columns: ' + String(e && e.message || e) }, 500); }

  const milestones = await fetchTab(env, 'Payment_Milestones');
  const m = milestones.find(x => x.ID === msId && x.Signature_ID === sigId && String(x.Active || '').toUpperCase() !== 'FALSE');
  if (!m) return json({ error: `Milestone ${msId} not found on signature ${sigId}` }, 404);

  await updateRow(env, 'Payment_Milestones', msId, {
    Pending_Info: pending ? 'TRUE' : 'FALSE',
    Pending_Info_Note: pending ? note : '',
    Pending_Info_Set_By: pending ? (body.set_by || 'Brett') : '',
    Pending_Info_Set_Date: pending ? new Date().toISOString() : '',
  });
  return json({ success: true, id: msId, signature_id: sigId, pending_info: pending, note: pending ? note : '' });
}

async function scopeProposalBillMilestones(env, body) {
  const sigId = body && body.signature_id;
  const milestoneIds = Array.isArray(body && body.milestone_ids) ? body.milestone_ids.map(String) : [];
  if (!sigId || !milestoneIds.length) return json({ error: 'signature_id and milestone_ids required' }, 400);

  await scopeSigTab(env); await paymentMilestonesTab(env);
  const [sigs, allMilestones, scopes] = await Promise.all([fetchTab(env, 'Scope_Signatures'), fetchTab(env, 'Payment_Milestones'), fetchTab(env, 'Scopes')]);
  const row = sigs.find(r => r.ID === String(sigId) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (!row) return json({ error: 'signature not found' }, 404);
  const s = scopes.find(x => x.ID === row.Scope_ID);
  if (!s) return json({ error: 'Scope not found for this signature (Scope_ID ' + row.Scope_ID + ')' }, 404);

  const picked = milestoneIds.map(id => allMilestones.find(m => m.ID === id && m.Signature_ID === String(sigId) && String(m.Active || '').toUpperCase() !== 'FALSE')).filter(Boolean);
  if (picked.length !== milestoneIds.length) return json({ error: 'One or more milestone_ids were not found on this signature.' }, 404);
  const notPending = picked.filter(m => (m.Status || 'pending') !== 'pending');
  if (notPending.length) return json({ error: 'Milestone(s) already billed: ' + notPending.map(m => m.Label).join(', ') }, 400);

  // CAP-036 #14: soft block, not a hard one — a flagged milestone can still be billed with
  // explicit override_pending_info:true (Brett's own words: "I can be blocked by me"), but never
  // silently. previewOnly is allowed through either way so the checkbox/preview can show the
  // flag; only the real write (below) is gated.
  const flaggedPending = picked.filter(m => String(m.Pending_Info || '').toUpperCase() === 'TRUE');
  if (flaggedPending.length && !body.preview_only && !body.override_pending_info) {
    return json({
      error: `${flaggedPending.length} selected milestone(s) are flagged "Invoiced — Pending Info": ` +
        flaggedPending.map(m => `${m.Label}${m.Pending_Info_Note ? ' (' + m.Pending_Info_Note + ')' : ''}`).join(', ') +
        '. Resolve them, or resend with override_pending_info to bill anyway.',
      pending_info: true,
    }, 409);
  }

  const { tradeName, trade, prop, unit, owner, vendor, billTo, custDisplay, vendDisplay, vendorInHouse, addr } = await scopeSigResolveParties(env, s, row);

  const custTotal = +picked.reduce((sum, m) => sum + (+m.Customer_Amount || 0), 0).toFixed(2);

  // Vendor-pay-per-milestone rollover (Sep 18 2026): a milestone's own Vendor_Amount is fixed at
  // signing time and never recomputed — what actually gets BILLED to the vendor this round is the
  // structural payable from scopeVendorPayableSchedule (the FULL schedule, not just what's picked
  // here), so a skipped milestone's share correctly rolls into whichever later TRUE milestone
  // absorbs it, however these get grouped/ordered across separate bill-milestones calls.
  const sigMilestones = allMilestones.filter(m => m.Signature_ID === String(sigId) && String(m.Active || '').toUpperCase() !== 'FALSE');
  const payableSchedule = scopeVendorPayableSchedule(sigMilestones.map(m => ({
    id: m.ID, sequence: +m.Sequence || 0, vendor_amount: +m.Vendor_Amount || 0,
    vendor_paid: String(m.Vendor_Paid_At_This_Milestone || 'TRUE').toUpperCase() !== 'FALSE',
  })));
  const payableById = {}; payableSchedule.forEach(p => { payableById[p.id] = p.vendor_payable; });
  const vendTotal = +picked.reduce((sum, m) => sum + (payableById[m.ID] || 0), 0).toFixed(2);
  const pickedOwnVendorTotal = +picked.reduce((sum, m) => sum + (+m.Vendor_Amount || 0), 0).toFixed(2);

  let billSkipReason = '';
  if (!vendor) billSkipReason = s.Vendor_ID ? ('Vendor ' + s.Vendor_ID + ' was not found on the Vendors tab — no vendor bill will be created.') : 'No vendor is set on this scope — no vendor bill will be created.';
  else if (vendorInHouse) billSkipReason = SCOPE_BILL_SKIP_INHOUSE;
  else if (!(vendTotal > 0)) {
    billSkipReason = pickedOwnVendorTotal > 0
      ? 'Vendor payment for the selected milestone(s) is deferred (Vendor_Paid_At_This_Milestone is off) — their share rolls forward onto a later paid milestone; nothing billed to the vendor this round.'
      : 'The selected milestone(s) carry $0 of vendor cost — there is nothing to bill.';
  }

  const labelList = picked.map(m => m.Label).join(' + ');
  const invoiceDesc = (tradeName + ' — ' + (s.Title || 'scope of work') + ' — ' + labelList + ' (' + addr + ')').slice(0, 4000);
  const warnings = [];
  if (!owner) warnings.push('Owner not resolved from the property — the invoice would create/land on a fallback QB customer.');
  if (billSkipReason) warnings.push(billSkipReason);
  if (billTo.level === 'owner') { const n = qbBillToNote(billTo, prop, unit); if (n) warnings.push(n); }

  // Instant-pay fee for THIS payment (Oct 19 2026): its own visible negative line on the vendor bill,
  // only for vendors paid instantly (Vendors.Instant_Pay, or Config instant_pay_default_vendor_ids).
  const cfgAll = await fetchConfig(env);
  const feeCfg = instantFeeConfig(cfgAll);
  feeCfg.warnings.forEach(w => warnings.push(w));
  const feeDefaultOn = !!vendor && instantPayEnabled(vendor, cfgAll, undefined);
  const feeOn = !!vendor && !vendorInHouse && vendTotal > 0 && instantPayEnabled(vendor, cfgAll, body.instant_pay);
  const mkAdj = (force) => vendorBillAdjustments({ payable: vendTotal, lang: (vendor && String(vendor.Language || '').toLowerCase() === 'es') ? 'es' : 'en', feeOn: force === true || feeOn, cfg: feeCfg, credits: [] });
  const adj = mkAdj(false);
  adj.notes.forEach(n => warnings.push(n));

  const preview = {
    signature_id: row.ID, scope_id: row.Scope_ID, property: addr, signer: row.Signer_Name,
    milestones: picked.map(m => ({
      id: m.ID, label: m.Label, percent: +m.Percent || 0, customer_amount: +m.Customer_Amount || 0,
      vendor_amount: +m.Vendor_Amount || 0, vendor_payable_now: payableById[m.ID] || 0,
      vendor_paid_this_milestone: String(m.Vendor_Paid_At_This_Milestone || 'TRUE').toUpperCase() !== 'FALSE',
      pending_info: String(m.Pending_Info || '').toUpperCase() === 'TRUE', pending_info_note: m.Pending_Info_Note || '',
    })),
    invoice: { customer: custDisplay, level: billTo.level, amount: custTotal, item: tradeName, desc: invoiceDesc },
    bill: (vendor && !vendorInHouse && vendTotal > 0) ? { vendor: vendDisplay, amount: vendTotal, trade: tradeName, fee: adj.fee, send_amount: adj.bill_total,
      fee_on: feeOn, fee_default_on: feeDefaultOn, fee_if_on: mkAdj(true).fee } : null,
    warnings,
  };
  if (body.preview_only) return json({ ok: true, preview });

  // ---- COMMIT ----
  if (!owner && !(billTo.qb_id || '')) return json({ ok: false, error: 'Owner not resolved for ' + addr + ' — refusing to create a QuickBooks invoice on a fallback customer. Fix the property/owner link first.', warnings });
  const token = await qbAccessToken(env);
  const txnDate = new Date().toISOString().slice(0, 10);
  let invoiceId = '', invoiceNumber = '', billId = '', billNumber = '';

  // 1) Customer invoice — one line per milestone, so the itemization stays visible even when
  // several are billed together in one shot.
  if (custTotal > 0) {
    let customerId = (billTo.level !== 'owner' && billTo.qb_id) ? billTo.qb_id : '';
    if (!customerId) {
      try { customerId = await qbFindOrCreateCustomer(env, owner || {}, custDisplay, token); }
      catch (e) { return json({ ok: false, error: 'Customer: ' + e.message, warnings }); }
    }
    const invoicePayload = {
      Line: picked.map(m => ({ DetailType: 'SalesItemLineDetail', Amount: +(+m.Customer_Amount || 0).toFixed(2),
        Description: (tradeName + ' — ' + (s.Title || 'scope of work') + ' — ' + m.Label + ' (' + addr + ')').slice(0, 4000),
        SalesItemLineDetail: { ItemRef: { value: trade.item }, Qty: 1, UnitPrice: +(+m.Customer_Amount || 0).toFixed(2) } })),
      CustomerRef: { value: customerId }, TxnDate: txnDate,
      CustomerMemo: { value: ('Scope proposal ' + row.Scope_ID + ' — ' + labelList + ' — accepted ' + (row.Signed_Date || '') + ' by ' + row.Signer_Name).slice(0, 1000) },
    };
    const billEmail = (owner && (owner.Billing_Email || owner.Email) || '').trim();
    if (billEmail && billEmail.length <= 100 && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(billEmail)) invoicePayload.BillEmail = { Address: billEmail };
    let r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token);
    invoiceId = (r && r.Invoice && r.Invoice.Id) || '';
    if (!invoiceId && invoicePayload.BillEmail) { delete invoicePayload.BillEmail; r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token); invoiceId = (r && r.Invoice && r.Invoice.Id) || ''; }
    if (!invoiceId) return json({ ok: false, error: 'QB invoice failed: ' + (qbFault(r) || 'unknown error'), warnings });
    invoiceNumber = (r.Invoice && r.Invoice.DocNumber) || '';
  }

  // 2) Vendor bill — one line per milestone, wrapped so a failure can never hide/roll back the
  // invoice already created above. Same skip-reason discipline as scopeProposalBook.
  if (invoiceId && !billSkipReason) {
    try {
      const vendorQbId = await qbFindOrCreateVendor(env, vendor, vendDisplay, token);
      if (vendorQbId) {
        // Only milestones with an actual payable THIS round get a line — a milestone whose
        // vendor pay was deferred (rolled forward per scopeVendorPayableSchedule) gets no $0 line.
        const payableLines = picked.filter(m => (payableById[m.ID] || 0) > 0);
        const billPayload = {
          Line: payableLines.map(m => ({ DetailType: 'AccountBasedExpenseLineDetail', Amount: +(payableById[m.ID] || 0).toFixed(2),
            Description: (vendDisplay + ' — ' + tradeName + ' — ' + (s.Title || '') + ' — ' + m.Label +
              ((payableById[m.ID] || 0) !== (+m.Vendor_Amount || 0) ? ' (includes a rolled-forward share from an earlier deferred milestone)' : '') + ' — ' + addr).slice(0, 4000),
            AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } })),
          VendorRef: { value: vendorQbId }, TxnDate: txnDate,
          PrivateNote: ('Scope proposal ' + row.Scope_ID + ' — ' + labelList + ' — ' + vendDisplay).slice(0, 1000),
        };
        for (const l of adj.lines) billPayload.Line.push({ DetailType: 'AccountBasedExpenseLineDetail', Amount: l.amount, Description: String(l.desc).slice(0, 4000), AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } });
        const rb = await qbApi(env, 'bill?minorversion=73', 'POST', billPayload, token);
        billId = (rb && rb.Bill && rb.Bill.Id) || '';
        billNumber = (rb && rb.Bill && rb.Bill.DocNumber) || '';
        if (!billId) billSkipReason = 'QB bill failed: ' + (qbFault(rb) || 'unknown error');
      } else { billSkipReason = 'The vendor\'s QuickBooks id could not be resolved — no vendor bill was created.'; }
    } catch (e) { billSkipReason = 'Vendor bill error: ' + e.message; }
    if (billSkipReason) warnings.push(billSkipReason);
  }

  // 3) Persist — every included milestone gets the SAME invoice/bill id (they were billed
  // together) and flips to 'billed'. Nothing here is undo-able yet (no bill-milestones equivalent
  // of unbook/unbook-final) — flagged as a known gap, not silently missing.
  const now = new Date().toISOString();
  for (const m of picked) {
    await updateRow(env, 'Payment_Milestones', m.ID, {
      Status: 'billed', QB_Invoice_ID: invoiceId, QB_Invoice_Number: invoiceNumber,
      QB_Bill_ID: billId, QB_Bill_Number: billNumber, Billed_Date: now,
    });
  }

  // 4) WO writeback (Sep 18 2026) — after a successful customer invoice, roll the running billed
  // total and a timestamped note onto the linked Work_Orders row (Scopes.WO_ID is the link; a
  // scope pushed here via /wo/push-to-scope, or created the old way via /scope/to-wo, both set
  // it). Best-effort: the invoice/bill above are already committed, so a failure here is reported,
  // never allowed to look like the whole bill failed.
  if (invoiceId && s.WO_ID) {
    try {
      const wosNow = await fetchTab(env, 'Work_Orders');
      const woRow = findWO(wosNow, s.WO_ID);
      if (woRow) {
        await ensureColumns(env, 'Work_Orders', ['Customer_Charge']);
        // The FINAL milestone is "whichever bill leaves nothing else pending" — not necessarily
        // the one tagged trigger:'completion' by label, since Brett can bill out of the label
        // order. Mirrors scopeProposalBookFinal's own reasoning (rule 143): once nothing is left
        // to bill, the job is already done by definition, so this must not guess/overwrite a more
        // specific WO status the job has already moved past — extended here, not duplicated. Any
        // INTERIM bill (something still pending afterward) keeps this function's existing
        // behavior from before this build: mark the WO Invoiced, same as scopeProposalBook's
        // deposit stage does.
        const pickedIds = new Set(picked.map(m => m.ID));
        const stillPending = sigMilestones.some(m => !pickedIds.has(m.ID) && (m.Status || 'pending') === 'pending');
        const priorCharge = parseFloat(woRow.Customer_Charge) || 0;
        const newCharge = +(priorCharge + custTotal).toFixed(2);
        const ts = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
        const vendorNote = vendTotal > 0
          ? ('vendor paid $' + vendTotal.toFixed(2) + ' this round' + (adj.fee > 0 ? ' (send $' + adj.bill_total.toFixed(2) + ' after the $' + adj.fee.toFixed(2) + ' instant-pay fee)' : ''))
          : ('vendor not paid this round' + (billSkipReason ? (' — ' + billSkipReason) : ''));
        const noteLine = '[' + ts + '] Scope Proposal billed — ' + labelList + ' — $' + custTotal.toFixed(2) + ' invoiced (' + (invoiceNumber || invoiceId) + '); ' + vendorNote + '.';
        const fields = { Customer_Charge: String(newCharge), Notes: woRow.Notes ? (woRow.Notes + '\n' + noteLine) : noteLine };
        if (stillPending) fields.Status = 'Invoiced';
        await updateWOFields(env, s.WO_ID, fields);
      }
    } catch (e) { warnings.push('Invoice/bill succeeded, but updating the linked Work Order (' + s.WO_ID + ') failed: ' + (e.message || e)); }
  }

  return json({ ok: true, invoice_id: invoiceId, invoice_number: invoiceNumber, bill_id: billId, bill_number: billNumber, milestone_ids: picked.map(m => m.ID), vendor_billed: vendTotal, vendor_fee: adj.fee, vendor_send_amount: adj.bill_total, warnings });
}

async function scopeProposalBook(env, body) {
  if (!body || !body.id) return json({ error: 'id required' }, 400);
  await scopeSigTab(env);
  const rows = await fetchTab(env, 'Scope_Signatures');
  const row = rows.find(r => r.ID === String(body.id) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (!row) return json({ error: 'signature not found' }, 404);

  await scopesTab(env);
  const scopes = await fetchTab(env, 'Scopes');
  const s = scopes.find(x => x.ID === row.Scope_ID);
  if (!s) return json({ error: 'Scope not found for this signature (Scope_ID ' + row.Scope_ID + ')' }, 404);

  const subtotal = +row.Subtotal || 0;
  const deposit = +row.Deposit_Amount || 0;
  const vendorCostTotal = +row.Vendor_Cost_Total || 0;
  const { ratio, amount: vendorBillAmount } = scopeSigVendorBillAmount(vendorCostTotal, deposit, subtotal);

  const { tradeName, trade, prop, unit, owner, vendor, billTo, custDisplay, vendDisplay, vendorInHouse, addr } =
    await scopeSigResolveParties(env, s, row);


  // Why this booking would create no vendor bill — decided ONCE, here, and used by both the
  // preview warnings and the persisted Bill_Skip_Reason, so what the Hub shows and what the
  // sheet remembers can never drift apart.
  let billSkipReason = '';
  if (!vendor) {
    billSkipReason = s.Vendor_ID
      ? ('Vendor ' + s.Vendor_ID + ' was not found on the Vendors tab — no vendor bill will be created.')
      : 'No vendor is set on this scope — no vendor bill will be created.';
  } else if (vendorInHouse) {
    billSkipReason = SCOPE_BILL_SKIP_INHOUSE;
  } else if (!(vendorBillAmount > 0)) {
    billSkipReason = 'The signed selections carry $0 of vendor cost — there is nothing to bill. Check the scope\'s vendor pricing.';
  }

  const warnings = [];
  if (!owner) warnings.push('Owner not resolved from the property — the invoice would create/land on a fallback QB customer.');
  if (billSkipReason) warnings.push(billSkipReason);
  if (billTo.level === 'owner') { const n = qbBillToNote(billTo, prop, unit); if (n) warnings.push(n); }
  if (ratio !== 0.5) warnings.push('Deposit is ' + Math.round(ratio * 100) + '% of the signed subtotal (not the usual 50%) — the vendor bill is prorated to match.');
  warnings.push('Invoice is the DEPOSIT only ($' + deposit.toFixed(2) + ' of $' + subtotal.toFixed(2) + '); the vendor bill is the same ' + Math.round(ratio * 100) + '% of the vendor cost ($' + vendorBillAmount.toFixed(2) + ' of $' + vendorCostTotal.toFixed(2) + ').');

  const invoiceDesc = (tradeName + ' — ' + (s.Title || 'scope of work') + ' — deposit (' + addr + ')').slice(0, 4000);
  // Instant-pay fee (Oct 19 2026) — its own visible negative line, only for instant-pay vendors.
  const cfgAll = await fetchConfig(env);
  const feeCfg = instantFeeConfig(cfgAll);
  feeCfg.warnings.forEach(w => warnings.push(w));
  const adj = vendorBillAdjustments({ payable: vendorBillAmount, lang: (vendor && String(vendor.Language || '').toLowerCase() === 'es') ? 'es' : 'en',
    feeOn: !!vendor && !vendorInHouse && vendorBillAmount > 0 && instantPayEnabled(vendor, cfgAll, body.instant_pay), cfg: feeCfg, credits: [] });
  adj.notes.forEach(n => warnings.push(n));
  const preview = {
    signature_id: row.ID, scope_id: row.Scope_ID, property: addr, signer: row.Signer_Name,
    invoice: { customer: custDisplay, level: billTo.level, amount: deposit, item: tradeName, desc: invoiceDesc, of_total: subtotal },
    bill: (vendor && !vendorInHouse && vendorBillAmount > 0) ? { vendor: vendDisplay, amount: vendorBillAmount, trade: tradeName, of_total: vendorCostTotal, fee: adj.fee, send_amount: adj.bill_total } : null,
    already: { invoice: row.QB_Invoice_ID || '', bill: row.QB_Bill_ID || '' }, warnings,
  };
  if (body.preview_only) return json({ ok: true, preview });

  // ---- COMMIT ----
  if (!owner && !(billTo.qb_id || '')) return json({ ok: false, error: 'Owner not resolved for ' + addr + ' — refusing to create a QuickBooks invoice on a fallback customer. Fix the property/owner link first.', warnings });
  // Backfill Bill_Skip_Reason before anything is written. ensureTab only writes a header to an
  // EMPTY tab (FEATURE_LOG rule 37) and updateRow silently DROPS any field whose header is
  // missing — so without this, the live Scope_Signatures sheet would swallow every skip reason
  // and the gap would stay exactly as invisible as it was. Runs on the commit path only, never
  // on preview or on the customer's signing path.
  await ensureColumns(env, 'Scope_Signatures', SCOPE_SIG_HEADERS);
  const token = await qbAccessToken(env);
  const txnDate = new Date().toISOString().slice(0, 10);
  let invoiceId = row.QB_Invoice_ID || '', invoiceNumber = row.QB_Invoice_Number || '';
  let billId = row.QB_Bill_ID || '', billNumber = row.QB_Bill_Number || '';

  // 1) Customer invoice (deposit) — idempotent.
  if (!invoiceId && deposit > 0) {
    let customerId = (billTo.level !== 'owner' && billTo.qb_id) ? billTo.qb_id : '';
    if (!customerId) {
      try { customerId = await qbFindOrCreateCustomer(env, owner || {}, custDisplay, token); }
      catch (e) { return json({ ok: false, error: 'Customer: ' + e.message, warnings }); }
    }
    const invoicePayload = {
      Line: [{ DetailType: 'SalesItemLineDetail', Amount: +deposit.toFixed(2), Description: invoiceDesc,
        SalesItemLineDetail: { ItemRef: { value: trade.item }, Qty: 1, UnitPrice: +deposit.toFixed(2) } }],
      CustomerRef: { value: customerId }, TxnDate: txnDate,
      CustomerMemo: { value: ('Scope proposal ' + row.Scope_ID + ' — accepted ' + (row.Signed_Date || '') + ' by ' + row.Signer_Name).slice(0, 1000) },
    };
    const billEmail = (owner && (owner.Billing_Email || owner.Email) || '').trim();
    if (billEmail && billEmail.length <= 100 && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(billEmail)) invoicePayload.BillEmail = { Address: billEmail };
    let r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token);
    invoiceId = (r && r.Invoice && r.Invoice.Id) || '';
    if (!invoiceId && invoicePayload.BillEmail) { delete invoicePayload.BillEmail; r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token); invoiceId = (r && r.Invoice && r.Invoice.Id) || ''; }
    if (!invoiceId) return json({ ok: false, error: 'QB invoice failed: ' + (qbFault(r) || 'unknown error'), warnings });
    invoiceNumber = (r.Invoice && r.Invoice.DocNumber) || '';
    // Persist the invoice id NOW, before touching the bill, so a later failure (bill error or a
    // dropped connection) can never cause a duplicate invoice on retry.
    try { await updateRow(env, 'Scope_Signatures', row.ID, { Status: 'Booked', QB_Invoice_ID: invoiceId, QB_Invoice_Number: invoiceNumber }); } catch (e) {}
  }

  // 2) Vendor bill (prorated cost) — idempotent; skipped if vendor missing/in-house/zero.
  // Wrapped so a bill failure can never roll back or hide the already-created (and persisted) invoice.
  // Every path that ends WITHOUT a bill records why in billSkipReason, which is persisted in step 3.
  // Before this, a skipped or failed bill left only an ephemeral warning in this one response: the
  // row flipped to Booked, the Hub showed a plain green checkmark, and the missing payable was
  // invisible from then on. The reason string is the durable trace.
  if (!billId && !billSkipReason) {
    try {
      const vendorQbId = await qbFindOrCreateVendor(env, vendor, vendDisplay, token);
      if (vendorQbId) {
        const billPayload = {
          Line: [{ DetailType: 'AccountBasedExpenseLineDetail', Amount: +vendorBillAmount.toFixed(2),
            Description: (vendDisplay + ' — ' + tradeName + ' — ' + (s.Title || '') + ' — deposit share — ' + addr).slice(0, 4000),
            AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } }],
          VendorRef: { value: vendorQbId }, TxnDate: txnDate,
          PrivateNote: ('Scope proposal ' + row.Scope_ID + ' — ' + vendDisplay).slice(0, 1000),
        };
        for (const l of adj.lines) billPayload.Line.push({ DetailType: 'AccountBasedExpenseLineDetail', Amount: l.amount, Description: String(l.desc).slice(0, 4000), AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } });
        const rb = await qbApi(env, 'bill?minorversion=73', 'POST', billPayload, token);
        billId = (rb && rb.Bill && rb.Bill.Id) || '';
        billNumber = (rb && rb.Bill && rb.Bill.DocNumber) || '';
        if (!billId) billSkipReason = 'QB bill failed: ' + (qbFault(rb) || 'unknown error');
      } else { billSkipReason = 'The vendor\'s QuickBooks id could not be resolved — no vendor bill was created.'; }
    } catch (e) { billSkipReason = 'Vendor bill error: ' + e.message; }
    // Only the failures discovered HERE are new information; the preflight reasons above are
    // already in warnings.
    if (billSkipReason) warnings.push(billSkipReason);
  }

  // 3) Persist QB ids + the bill-gap reason + tie back to the scope/work order. The reason is
  // written on EVERY commit, so a retry that succeeds clears a previously recorded gap.
  await updateRow(env, 'Scope_Signatures', row.ID, {
    Status: 'Booked', QB_Invoice_ID: invoiceId, QB_Invoice_Number: invoiceNumber, QB_Bill_ID: billId, QB_Bill_Number: billNumber,
    Bill_Skip_Reason: billId ? '' : billSkipReason,
  });
  try { await updateRow(env, 'Scopes', s.ID, { Status: 'invoiced', Updated_Date: new Date().toISOString() }); } catch (e) {}
  try { if (s.WO_ID) await updateWOFields(env, s.WO_ID, { Status: 'Invoiced' }); } catch (e) {}

  return json({ ok: true, invoice_id: invoiceId, invoice_number: invoiceNumber, bill_id: billId, bill_number: billNumber, warnings });
}

// POST /scope-proposal/unbook (admin) { id }
// Reverses a mistaken DEPOSIT booking from scopeProposalBook, above (Brett, Sep 7 2026: the
// post-confirm modal's only button read "Cancel" even after the invoice+bill had already been
// created — confusing, since nothing left to cancel — so this pairs a genuine Undo with it).
// Deletes the QB invoice and bill (via qbDeleteInvoiceSafe/qbDeleteBillSafe — refuses either one
// that already has a payment applied) and clears their ids back off the row, returning it to
// exactly the pre-booking state ("Signed — needs billing"). No preview_only path: the person is
// explicitly asking to reverse something already done, not previewing a new action — the Hub's
// own confirm() dialog ("are you sure you want to undo these bills and invoices?") is the gate,
// same as Confirm's preview step is the gate on the way in.
async function scopeProposalUnbook(env, body) {
  if (!body || !body.id) return json({ error: 'id required' }, 400);
  await scopeSigTab(env);
  const rows = await fetchTab(env, 'Scope_Signatures');
  const row = rows.find(r => r.ID === String(body.id) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (!row) return json({ error: 'signature not found' }, 404);
  if (!row.QB_Invoice_ID && !row.QB_Bill_ID) return json({ ok: false, error: 'Nothing booked yet — there is no deposit invoice or bill to undo.' }, 400);
  if (row.QB_Final_Invoice_ID || row.QB_Final_Bill_ID)
    return json({ ok: false, error: 'The final balance has already been invoiced on top of this deposit — undo that first (its own Undo, on the "Final balance" line), then come back to undo the deposit.' }, 409);

  const token = await qbAccessToken(env);
  const invRes = await qbDeleteInvoiceSafe(env, row.QB_Invoice_ID, token);
  if (!invRes.ok) return json({ ok: false, error: invRes.error });
  const billRes = await qbDeleteBillSafe(env, row.QB_Bill_ID, token);
  if (!billRes.ok) return json({ ok: false, error: 'The invoice was undone, but the bill was NOT (' + billRes.error + ') — QuickBooks and the Hub now disagree on the bill; fix it in QuickBooks directly, or retry.' });

  await updateRow(env, 'Scope_Signatures', row.ID, {
    Status: 'Signed', QB_Invoice_ID: '', QB_Invoice_Number: '', QB_Bill_ID: '', QB_Bill_Number: '', Bill_Skip_Reason: '',
  });
  try {
    await scopesTab(env);
    const scopes = await fetchTab(env, 'Scopes');
    const s = scopes.find(x => x.ID === row.Scope_ID);
    if (s) {
      await updateRow(env, 'Scopes', s.ID, { Status: 'signed', Updated_Date: new Date().toISOString() });
      // 'Pending Invoice' is the standing WO status for "ready to bill, not yet invoiced" (see
      // OPEN_WO_STATUSES) — the correct inverse of the 'Invoiced' this same booking set.
      if (s.WO_ID) await updateWOFields(env, s.WO_ID, { Status: 'Pending Invoice' });
    }
  } catch (e) {}

  return json({ ok: true, undone_invoice: row.QB_Invoice_ID || '', undone_bill: row.QB_Bill_ID || '' });
}

// POST /scope-proposal/book-final (admin) { id, preview_only }
// Books the REMAINING balance of a signed scope proposal — Brett (Sep 2 2026): "the vendor was
// paid the deposit, finished the job, and now i need to invoice for the final." Only the deposit
// half (scopeProposalBook, above) existed until now; this is its counterpart for after the job is
// actually done. Same idempotent / preview-first / admin-gated / persist-invoice-before-bill shape,
// same shared party resolution (scopeSigResolveParties) so the final half can never resolve to a
// different customer/vendor/trade than the deposit half did.
//   • Requires the deposit to already be booked (QB_Invoice_ID present) — a final invoice with no
//     deposit on record would double-bill the customer for the full amount with no visibility that
//     half was already collected.
//   • remaining invoice = subtotal − deposit (computed, not assumed 50/50, matching
//     scopeSigVendorBillAmount's own no-hardcoded-ratio convention).
//   • remaining vendor bill = vendor_cost_total − (the SAME deposit-share amount already billed on
//     the deposit half) — i.e. the other 1−ratio share, never a re-derivation that could drift from
//     what was actually billed the first time.
//   • re-calling after either half already exists (QB_Final_Invoice_ID / QB_Final_Bill_ID) skips
//     that half rather than double-booking, same convention as the deposit function.
async function scopeProposalBookFinal(env, body) {
  if (!body || !body.id) return json({ error: 'id required' }, 400);
  await scopeSigTab(env);
  await ensureColumns(env, 'Scope_Signatures', ['QB_Final_Invoice_ID', 'QB_Final_Invoice_Number', 'QB_Final_Bill_ID', 'QB_Final_Bill_Number', 'Final_Bill_Skip_Reason']);
  const rows = await fetchTab(env, 'Scope_Signatures');
  const row = rows.find(r => r.ID === String(body.id) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (!row) return json({ error: 'signature not found' }, 404);
  if (!row.QB_Invoice_ID) return json({ error: 'The deposit hasn\'t been booked yet — book the deposit invoice first (Preview & create invoice + bill), then come back to invoice the final balance.' }, 400);

  await scopesTab(env);
  const scopes = await fetchTab(env, 'Scopes');
  const s = scopes.find(x => x.ID === row.Scope_ID);
  if (!s) return json({ error: 'Scope not found for this signature (Scope_ID ' + row.Scope_ID + ')' }, 404);

  const subtotal = +row.Subtotal || 0;
  const deposit = +row.Deposit_Amount || 0;
  const vendorCostTotal = +row.Vendor_Cost_Total || 0;
  const { ratio, amount: vendorBillAmount } = scopeSigVendorBillAmount(vendorCostTotal, deposit, subtotal);
  const finalAmount = +(subtotal - deposit).toFixed(2);
  const finalVendorAmount = +(vendorCostTotal - vendorBillAmount).toFixed(2);

  const { tradeName, trade, prop, unit, owner, vendor, billTo, custDisplay, vendDisplay, vendorInHouse, addr } =
    await scopeSigResolveParties(env, s, row);

  // Same skip-reason discipline as the deposit half (scopeProposalBook) — decided ONCE, used by
  // both the preview warnings and the persisted Final_Bill_Skip_Reason, so the Hub and the sheet
  // can never drift apart. Added Sep 18 2026: the final phase had every other protection the
  // deposit phase got in rule 145 except this one — a final vendor bill that silently failed to
  // create had nothing recording it, the exact blind spot rule 145 fixed on the deposit side.
  let billSkipReason = '';
  if (!vendor) {
    billSkipReason = s.Vendor_ID
      ? ('Vendor ' + s.Vendor_ID + ' was not found on the Vendors tab — no vendor bill will be created.')
      : 'No vendor is set on this scope — no vendor bill will be created.';
  } else if (vendorInHouse) {
    billSkipReason = SCOPE_BILL_SKIP_INHOUSE;
  } else if (!(finalVendorAmount > 0)) {
    billSkipReason = 'The remaining vendor balance is $0 or less — there is nothing to bill.';
  }

  const warnings = [];
  if (!owner) warnings.push('Owner not resolved from the property — the invoice would create/land on a fallback QB customer.');
  if (billSkipReason) warnings.push(billSkipReason);
  if (billTo.level === 'owner') { const n = qbBillToNote(billTo, prop, unit); if (n) warnings.push(n); }
  if (ratio !== 0.5) warnings.push('Deposit was ' + Math.round(ratio * 100) + '% of the signed subtotal (not the usual 50%) — the final balance is prorated to match what remains.');
  if (finalAmount <= 0) warnings.push('Nothing appears to remain — subtotal ($' + subtotal.toFixed(2) + ') is not greater than the deposit already invoiced ($' + deposit.toFixed(2) + ').');
  warnings.push('Invoice is the FINAL BALANCE ($' + finalAmount.toFixed(2) + ' of $' + subtotal.toFixed(2) + ', deposit of $' + deposit.toFixed(2) + ' already invoiced separately); the vendor bill is the remaining ' + Math.round((1 - ratio) * 100) + '% of the vendor cost ($' + finalVendorAmount.toFixed(2) + ' of $' + vendorCostTotal.toFixed(2) + ').');

  const invoiceDesc = (tradeName + ' — ' + (s.Title || 'scope of work') + ' — final balance (' + addr + ')').slice(0, 4000);
  const cfgAll = await fetchConfig(env);
  const feeCfg = instantFeeConfig(cfgAll);
  feeCfg.warnings.forEach(w => warnings.push(w));
  const adj = vendorBillAdjustments({ payable: finalVendorAmount, lang: (vendor && String(vendor.Language || '').toLowerCase() === 'es') ? 'es' : 'en',
    feeOn: !!vendor && !vendorInHouse && finalVendorAmount > 0 && instantPayEnabled(vendor, cfgAll, body.instant_pay), cfg: feeCfg, credits: [] });
  adj.notes.forEach(n => warnings.push(n));
  const preview = {
    signature_id: row.ID, scope_id: row.Scope_ID, property: addr, signer: row.Signer_Name,
    invoice: { customer: custDisplay, level: billTo.level, amount: finalAmount, item: tradeName, desc: invoiceDesc, of_total: subtotal, deposit_already_invoiced: deposit },
    bill: (vendor && !vendorInHouse && finalVendorAmount > 0) ? { vendor: vendDisplay, amount: finalVendorAmount, trade: tradeName, of_total: vendorCostTotal, fee: adj.fee, send_amount: adj.bill_total } : null,
    already: { invoice: row.QB_Final_Invoice_ID || '', bill: row.QB_Final_Bill_ID || '' }, warnings,
  };
  if (body.preview_only) return json({ ok: true, preview });

  // ---- COMMIT ----
  if (!owner && !(billTo.qb_id || '')) return json({ ok: false, error: 'Owner not resolved for ' + addr + ' — refusing to create a QuickBooks invoice on a fallback customer. Fix the property/owner link first.', warnings });
  if (finalAmount <= 0) return json({ ok: false, error: 'Nothing to invoice — the final balance is $0 or less.', warnings });
  const token = await qbAccessToken(env);
  const txnDate = new Date().toISOString().slice(0, 10);
  let invoiceId = row.QB_Final_Invoice_ID || '', invoiceNumber = row.QB_Final_Invoice_Number || '';
  let billId = row.QB_Final_Bill_ID || '', billNumber = row.QB_Final_Bill_Number || '';

  // 1) Customer invoice (final balance) — idempotent.
  if (!invoiceId && finalAmount > 0) {
    let customerId = (billTo.level !== 'owner' && billTo.qb_id) ? billTo.qb_id : '';
    if (!customerId) {
      try { customerId = await qbFindOrCreateCustomer(env, owner || {}, custDisplay, token); }
      catch (e) { return json({ ok: false, error: 'Customer: ' + e.message, warnings }); }
    }
    const invoicePayload = {
      Line: [{ DetailType: 'SalesItemLineDetail', Amount: +finalAmount.toFixed(2), Description: invoiceDesc,
        SalesItemLineDetail: { ItemRef: { value: trade.item }, Qty: 1, UnitPrice: +finalAmount.toFixed(2) } }],
      CustomerRef: { value: customerId }, TxnDate: txnDate,
      CustomerMemo: { value: ('Scope proposal ' + row.Scope_ID + ' — final balance (deposit invoice #' + (row.QB_Invoice_Number || row.QB_Invoice_ID) + ' already sent)').slice(0, 1000) },
    };
    const billEmail = (owner && (owner.Billing_Email || owner.Email) || '').trim();
    if (billEmail && billEmail.length <= 100 && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(billEmail)) invoicePayload.BillEmail = { Address: billEmail };
    let r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token);
    invoiceId = (r && r.Invoice && r.Invoice.Id) || '';
    if (!invoiceId && invoicePayload.BillEmail) { delete invoicePayload.BillEmail; r = await qbApi(env, 'invoice?minorversion=73', 'POST', invoicePayload, token); invoiceId = (r && r.Invoice && r.Invoice.Id) || ''; }
    if (!invoiceId) return json({ ok: false, error: 'QB invoice failed: ' + (qbFault(r) || 'unknown error'), warnings });
    invoiceNumber = (r.Invoice && r.Invoice.DocNumber) || '';
    // Persist the invoice id NOW, before touching the bill, so a later failure (bill error or a
    // dropped connection) can never cause a duplicate invoice on retry.
    try { await updateRow(env, 'Scope_Signatures', row.ID, { QB_Final_Invoice_ID: invoiceId, QB_Final_Invoice_Number: invoiceNumber }); } catch (e) {}
  }

  // 2) Vendor bill (remaining cost) — idempotent; skipped if vendor missing/in-house/zero. Same
  // !billId && !billSkipReason gate as the deposit half, so a bill is only ever attempted when
  // nothing already disqualified it — and every path that ends without a bill has already set
  // billSkipReason, persisted in step 3 below (mirrors rule 145's Bill_Skip_Reason exactly).
  if (!billId && !billSkipReason) {
    try {
      const vendorQbId = await qbFindOrCreateVendor(env, vendor, vendDisplay, token);
      if (vendorQbId) {
        const billPayload = {
          Line: [{ DetailType: 'AccountBasedExpenseLineDetail', Amount: +finalVendorAmount.toFixed(2),
            Description: (vendDisplay + ' — ' + tradeName + ' — ' + (s.Title || '') + ' — final balance share — ' + addr).slice(0, 4000),
            AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } }],
          VendorRef: { value: vendorQbId }, TxnDate: txnDate,
          PrivateNote: ('Scope proposal ' + row.Scope_ID + ' — ' + vendDisplay + ' — final balance').slice(0, 1000),
        };
        for (const l of adj.lines) billPayload.Line.push({ DetailType: 'AccountBasedExpenseLineDetail', Amount: l.amount, Description: String(l.desc).slice(0, 4000), AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } });
        const rb = await qbApi(env, 'bill?minorversion=73', 'POST', billPayload, token);
        billId = (rb && rb.Bill && rb.Bill.Id) || '';
        billNumber = (rb && rb.Bill && rb.Bill.DocNumber) || '';
        if (!billId) billSkipReason = 'QB bill failed: ' + (qbFault(rb) || 'unknown error');
      } else { billSkipReason = 'The vendor\'s QuickBooks id could not be resolved — no vendor bill was created.'; }
    } catch (e) { billSkipReason = 'Vendor bill error: ' + e.message; }
    if (billSkipReason) warnings.push(billSkipReason);
  }

  // 3) Persist QB ids + the bill-gap reason + tie back to the scope/work order. The reason is
  // written on EVERY commit, so a retry that succeeds clears a previously recorded gap — same
  // convention as the deposit half's Bill_Skip_Reason.
  await updateRow(env, 'Scope_Signatures', row.ID, {
    QB_Final_Invoice_ID: invoiceId, QB_Final_Invoice_Number: invoiceNumber, QB_Final_Bill_ID: billId, QB_Final_Bill_Number: billNumber,
    Final_Bill_Skip_Reason: billId ? '' : billSkipReason,
  });
  try { await updateRow(env, 'Scopes', s.ID, { Status: 'fully-invoiced', Updated_Date: new Date().toISOString() }); } catch (e) {}
  // WO_Status intentionally left untouched here — unlike the deposit half, the job is already
  // done by the time a final invoice is booked (that's the whole trigger for this call), so its
  // Status should already reflect real-world completion; this function shouldn't guess and
  // overwrite whatever more specific state the WO is actually in.

  return json({ ok: true, invoice_id: invoiceId, invoice_number: invoiceNumber, bill_id: billId, bill_number: billNumber, warnings });
}

// POST /scope-proposal/adjust-bill (admin) { id, phase: 'deposit'|'final', amount, reason, preview_only }
// One-off correction to an ALREADY-BOOKED Signed-Proposal vendor bill (Sep 18 2026). Built for
// the case that surfaced 1305 N Calvert St's missing-final-bill gap: Cesar found unforeseen
// complexity mid-job and asked for more than the original prorated share; Brett chose to eat the
// increase himself (never re-bills the customer — this only ever touches the vendor's own Bill)
// and had no way to adjust a bill the Hub had already created without going around it by hand.
//
// Adds ONE new line to the existing Bill for `amount` (positive to raise what's owed, negative
// to reduce it) and keeps every existing line untouched — QuickBooks' sparse Bill update
// replaces the WHOLE Line array, not just the lines you mention, so this always sends
// [...existing lines, new line], never just the new line alone (that would silently wipe the
// original charge). A partial payment already applied against the bill keeps applying exactly as
// it did before; QuickBooks recomputes Balance = new Total − whatever's already been applied —
// e.g. a $3,400 bill with $500 already applied ($2,900 balance), adjusted by +$500, becomes a
// $3,900 bill with the same $500 applied ($3,400 balance now owed).
//
// Same preview-first / admin-gated / Brett-taps-Confirm shape as every other QuickBooks write in
// this file — AUTONOMY_GUARDRAILS Rung 3 (money writes are never fired without Brett's own tap).
async function scopeProposalAdjustBill(env, body) {
  try {
    const id = body && body.id, phase = String((body && body.phase) || '').trim();
    const amount = Number(body && body.amount);
    const reason = String((body && body.reason) || '').trim();
    if (!id || (phase !== 'deposit' && phase !== 'final')) return json({ ok: false, error: 'id and phase (deposit|final) are required' }, 400);
    if (!amount || isNaN(amount)) return json({ ok: false, error: 'A non-zero amount is required.' }, 400);
    if (!reason) return json({ ok: false, error: 'A reason is required — it goes on the new bill line in QuickBooks, not just in the Hub.' }, 400);

    await scopeSigTab(env);
    const rows = await fetchTab(env, 'Scope_Signatures');
    const row = rows.find(r => r.ID === String(id) && String(r.Active || '').toUpperCase() !== 'FALSE');
    if (!row) return json({ ok: false, error: 'signature not found' }, 404);
    const billId = phase === 'final' ? row.QB_Final_Bill_ID : row.QB_Bill_ID;
    if (!billId) return json({ ok: false, error: 'No ' + phase + ' vendor bill exists yet on this signature to adjust — book it first.' }, 400);

    const token = await qbAccessToken(env);
    const got = await qbApi(env, `bill/${encodeURIComponent(billId)}?minorversion=73`, 'GET', null, token);
    const bill = got && got.Bill;
    if (!bill) return json({ ok: false, error: qbFault(got) || 'Could not read that bill from QuickBooks.' }, 404);

    const curTotal = Number(bill.TotalAmt) || 0;
    const curBalance = bill.Balance != null ? Number(bill.Balance) : curTotal;
    const newTotal = +(curTotal + amount).toFixed(2);
    const newBalance = +(curBalance + amount).toFixed(2);
    if (newTotal < 0) return json({ ok: false, error: 'That would make the bill total negative ($' + newTotal.toFixed(2) + ') — reduce by less.' }, 400);
    if (newBalance < -0.005) return json({ ok: false, error: 'That would take the balance below $0 ($' + newBalance.toFixed(2) + ') — this bill already has more applied against it than that.' }, 400);

    const expenseLine = (bill.Line || []).find(l => l.DetailType === 'AccountBasedExpenseLineDetail');
    const acctRef = expenseLine && expenseLine.AccountBasedExpenseLineDetail && expenseLine.AccountBasedExpenseLineDetail.AccountRef;
    if (!acctRef) return json({ ok: false, error: 'Could not find an expense account on the existing bill line to match.' }, 500);

    const preview = { signature_id: row.ID, phase, bill_id: billId, current_total: curTotal, current_balance: curBalance,
      adjustment: amount, new_total: newTotal, new_balance: newBalance, reason };
    if (body.preview_only) return json({ ok: true, preview });

    // Reuse the SAME expense account as the bill's existing line(s) — an adjustment belongs on
    // the same account the original charge was coded to, never a fresh guess.
    const newLine = { DetailType: 'AccountBasedExpenseLineDetail', Amount: +amount.toFixed(2),
      Description: reason.slice(0, 4000), AccountBasedExpenseLineDetail: { AccountRef: acctRef } };
    const patch = { Id: billId, SyncToken: bill.SyncToken, sparse: true, VendorRef: bill.VendorRef, Line: [...(bill.Line || []), newLine] };
    const upd = await qbApi(env, 'bill?minorversion=73', 'POST', patch, token);
    const updated = upd && upd.Bill;
    if (!updated) return json({ ok: false, error: 'Update failed: ' + (qbFault(upd) || 'unknown error') }, 502);
    return json({ ok: true, signature_id: row.ID, phase, bill_id: billId,
      new_total: Number(updated.TotalAmt), new_balance: updated.Balance != null ? Number(updated.Balance) : null });
  } catch (e) { return json({ ok: false, error: e.message }, 500); }
}

// POST /scope-proposal/unbook-final (admin) { id }
// Reverses a mistaken FINAL-BALANCE booking from scopeProposalBookFinal, above — same Undo
// pairing as scopeProposalUnbook, for the second (final-balance) invoicing step instead of the
// first (deposit) one. Deletes the QB final invoice + final bill and clears their ids, dropping
// Scopes.Status back to 'invoiced' (its state between the deposit being booked and the final
// balance being booked) — the deposit invoice/bill themselves are untouched. WO status is left
// alone here too, mirroring scopeProposalBookFinal's own choice not to guess at it.
async function scopeProposalUnbookFinal(env, body) {
  if (!body || !body.id) return json({ error: 'id required' }, 400);
  await scopeSigTab(env);
  const rows = await fetchTab(env, 'Scope_Signatures');
  const row = rows.find(r => r.ID === String(body.id) && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (!row) return json({ error: 'signature not found' }, 404);
  if (!row.QB_Final_Invoice_ID && !row.QB_Final_Bill_ID) return json({ ok: false, error: 'Nothing booked yet — there is no final-balance invoice or bill to undo.' }, 400);

  const token = await qbAccessToken(env);
  const invRes = await qbDeleteInvoiceSafe(env, row.QB_Final_Invoice_ID, token);
  if (!invRes.ok) return json({ ok: false, error: invRes.error });
  const billRes = await qbDeleteBillSafe(env, row.QB_Final_Bill_ID, token);
  if (!billRes.ok) return json({ ok: false, error: 'The final invoice was undone, but the final bill was NOT (' + billRes.error + ') — QuickBooks and the Hub now disagree; fix it in QuickBooks directly, or retry.' });

  await updateRow(env, 'Scope_Signatures', row.ID, {
    QB_Final_Invoice_ID: '', QB_Final_Invoice_Number: '', QB_Final_Bill_ID: '', QB_Final_Bill_Number: '',
  });
  try {
    await scopesTab(env);
    const scopes = await fetchTab(env, 'Scopes');
    const s = scopes.find(x => x.ID === row.Scope_ID);
    if (s) await updateRow(env, 'Scopes', s.ID, { Status: 'invoiced', Updated_Date: new Date().toISOString() });
  } catch (e) {}

  return json({ ok: true, undone_invoice: row.QB_Final_Invoice_ID || '', undone_bill: row.QB_Final_Bill_ID || '' });
}

// the Owners tab. Per-customer overrides live in Owners.Hourly_Rate (blank = this default).
const DEFAULT_HUB_RATE = 85;

// Resolve the hourly rate for Brett's own time on a job: the owner's Owners.Hourly_Rate if
// they have one set, otherwise DEFAULT_HUB_RATE. Follows WO → Property → Owner, the same
// chain the invoice path uses. Falls back to the default on any read miss rather than
// billing $0 (a missing rate must never silently zero out the time).
async function resolveHubHourlyRate(env, woId) {
  try {
    const [wos, props, owners] = await fetchTabs(env, ['Work_Orders', 'Properties', 'Owners']);
    const wo = findWO(wos, woId);
    if (!wo) return DEFAULT_HUB_RATE;
    const prop = props.find(p => p.ID === wo.Property_ID);
    const owner = prop ? owners.find(o => o.ID === prop.Owner_ID) : null;
    const r = owner ? parseFloat(owner.Hourly_Rate || 0) : 0;
    return r > 0 ? r : DEFAULT_HUB_RATE;
  } catch (e) {
    return DEFAULT_HUB_RATE;
  }
}

async function addTimeEntry(env, body) {
  const { wo_id, entered_by, entered_by_id, role, entry_type, start_datetime, end_datetime, duration_minutes_raw, notes, invoice_description, billable, hourly_rate } = body;
  if (!wo_id) return json({ error: 'wo_id required' }, 400);
  if (!role)  return json({ error: 'role required (hub or vendor)' }, 400);
  { const _blk = await bidGroupWriteBlock(env, wo_id, 'time entries', 'horas', '/time-entry/add'); if (_blk) return json({ error: _blk.message, code: 'bid_group_cancelled', refusal_logged: _blk.logged }, 409); }
  let durationMinutes = 0;
  if (start_datetime && end_datetime) { durationMinutes = roundUpTo15((new Date(end_datetime) - new Date(start_datetime)) / 60000); }
  else if (duration_minutes_raw) { durationMinutes = roundUpTo15(parseFloat(duration_minutes_raw) || 0); }
  if (durationMinutes <= 0) return json({ error: 'Could not calculate duration' }, 400);
  let rate = parseFloat(hourly_rate || 0);
  // Brett's own (hub) time bills at a per-customer rate. When the Hub sends no explicit rate,
  // resolve it from the job's owner (Owners.Hourly_Rate, else the default). Vendor entries
  // always carry their own rate and are left untouched.
  if (role === 'hub' && !(rate > 0)) {
    rate = await resolveHubHourlyRate(env, wo_id);
  }
  const billableAmt = (billable === 'TRUE' || billable === true) ? (durationMinutes / 60) * rate : 0;

  // Same worker, same job, same block of time, seconds apart = a double-tap on Log Time.
  // Notes and Entry_Type are part of the signature on purpose: on the quick-duration path
  // there are no start/end times, so without them the signature collapses to
  // job + person + minutes — and logging two genuine 30-minute blocks back to back is
  // exactly what those quick buttons are for. The window is deliberately short for the
  // same reason: catching up on a day's entries in one sitting must not eat any of them.
  const dupe = await findRecentDuplicate(env, 'Time_Entries', {
    WO_ID: wo_id, Entered_By_ID: String(entered_by_id||''), Duration_Minutes: String(durationMinutes),
    Start_DateTime: start_datetime || '', End_DateTime: end_datetime || '',
    Notes: notes || '', Entry_Type: entry_type || (role === 'hub' ? 'Admin' : 'Labor'),
    Invoice_Description: invoice_description || '',
  }, 30);
  if (dupe) return json({ success: true, duplicate: true, duration_minutes: durationMinutes });

  // Invoice_Description is what the customer actually reads on the invoice line, kept
  // separate from Notes (private — never leaves the Hub). Same lazy ensureColumns pattern as
  // every other additive field in this file: a write to a column the sheet doesn't have yet
  // reports success and stores nothing (rule 37), so this has to run before the write.
  if (invoice_description) { try { await ensureColumns(env, 'Time_Entries', ['Invoice_Description']); } catch (e) {} }

  await addRow(env, 'Time_Entries', { WO_ID: wo_id, Entered_By: entered_by||'', Entered_By_ID: String(entered_by_id||''), Role: role, Entry_Type: entry_type || (role === 'hub' ? 'Admin' : 'Labor'), Start_DateTime: start_datetime||'', End_DateTime: end_datetime||'', Duration_Minutes: String(durationMinutes), Notes: notes||'', Invoice_Description: invoice_description||'', Billable: role === 'hub' ? String(billable === 'TRUE' || billable === true) : 'TRUE', Hourly_Rate: String(rate), Billable_Amount: String(billableAmt.toFixed(2)), Created_Date: new Date().toISOString(), Active: 'TRUE' });
  return json({ success: true, duration_minutes: durationMinutes, hourly_rate: rate });
}

async function listWOTenants(env, url) {
  const woId = url.searchParams.get('wo_id') || '';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  try { const rows = await fetchTab(env, 'WO_Tenants'); return json(rows.filter(r => r.WO_ID === woId && r.Active !== 'FALSE')); }
  catch(e) { return json([]); }
}

async function addTenantToWO(env, body) {
  const { wo_id, tenant_id, added_by } = body;
  if (!wo_id || !tenant_id) return json({ error: 'wo_id and tenant_id required' }, 400);
  const tenants = await fetchTab(env, 'Tenants');
  const tenant = tenants.find(t => t.ID === tenant_id);
  if (!tenant) return json({ error: 'Tenant not found' }, 404);
  // Oct 14 2026 (Brett): a tenant is only ever linked to work created on/after their move-in day. No override.
  const _wo = findWO(await fetchTab(env, 'Work_Orders'), String(wo_id));
  if (_wo && isBackgroundWO(tenant, _wo)) return json({ error: 'Not linked: ' + wo_id + ' was created before this tenant moved in (' + tenant.Move_In_Date + ').', code: 'wo_predates_move_in' }, 409);
  try { const existing = await fetchTab(env, 'WO_Tenants'); const already = existing.find(r => r.WO_ID === wo_id && r.Tenant_ID === tenant_id && r.Active !== 'FALSE'); if (already) return json({ success: true, id: already.ID, already_linked: true }); }
  catch (e) { return json({ error: 'Could not check existing links (' + String((e && e.message) || e).slice(0, 160) + ') - nothing was linked.' }, 500); }
  await addRow(env, 'WO_Tenants', { WO_ID: wo_id, Tenant_ID: tenant_id, Tenant_Name: ((tenant.First_Name||'')+' '+(tenant.Last_Name||'')).trim(), Tenant_Phone: tenant.Phone||'', Added_By: added_by||'system', Added_Date: new Date().toISOString(), Active: 'TRUE' });
  return json({ success: true });
}

async function removeTenantFromWO(env, body) {
  const { wo_id, tenant_id } = body;
  if (!wo_id || !tenant_id) return json({ error: 'wo_id and tenant_id required' }, 400);
  try { const rows = await fetchTab(env, 'WO_Tenants'); const row = rows.find(r => r.WO_ID === wo_id && r.Tenant_ID === tenant_id && r.Active !== 'FALSE'); if (!row) return json({ success: true, not_found: true }); await updateRow(env, 'WO_Tenants', row.ID, { Active: 'FALSE' }); return json({ success: true }); }
  catch(e) { return json({ error: e.message }, 500); }
}

// Oct 14 2026: the ONE implementation of "this tenant has moved out", shared by the admin Move Out button
// (processMoveOut), the owner tenant roster tool and the daily scheduled flip. Returns { errors, ... }: every step that
// can fail is reported back to the caller and logged to Ops_Telemetry, never swallowed. The caller decides how loud to be.
async function respErrText(res) {
  try { const j = await res.json(); return String((j && (j.error || j.message)) || ('HTTP ' + res.status)); }
  catch (e) { return 'HTTP ' + res.status + ' (unreadable body: ' + ((e && e.message) || e) + ')'; }
}
async function tenantMarkMovedOut(env, tenantId, moveOutDate) {
  const out = { errors: [], units_cleared: [], retro_wos_cleaned: 0, verified: false };
  const fail = (step, msg) => { out.errors.push({ step, error: String(msg).slice(0, 240) }); };
  try {
    await ensureColumns(env, 'Tenants', ['SMS_Enabled', 'Roster_Pending_Flip']);
    // The tenant's own row is left intact on purpose - same ID, same Unit_ID and Property_ID, now carrying a
    // move-out date. That row IS the history: their work orders, their contact record, everything logged while they
    // lived there stays attached to it. A new tenant gets a new row and a new ID; nothing is reused.
    // SMS_Enabled goes FALSE (Oct 14 2026) so a moved-out tenant is also switched off at the tenant toggle, not only
    // by the moved-out check in the SMS gate. SMS_OptOut is NOT touched: that is the tenant's own STOP record.
    const res = await updateRow(env, 'Tenants', tenantId, { Active: 'FALSE', Move_Out_Date: moveOutDate, PIN: '', SMS_Enabled: 'FALSE', Roster_Pending_Flip: '' });
    if (!res.ok) fail('tenant_row', await respErrText(res));
    else {
      // Verified write: re-read and confirm the row really changed (success:true with an unchanged cell is a failure).
      const back = (await fetchTab(env, 'Tenants')).find(t => String(t.ID) === String(tenantId));
      if (!back || String(back.Active).toUpperCase() !== 'FALSE' || back.Move_Out_Date !== moveOutDate) fail('tenant_row_verify', 'read-back does not show the move-out');
      else out.verified = true;
    }
  } catch (e) { fail('tenant_row', (e && e.message) || e); }

  // What DOES have to change is the unit's pointer to its CURRENT tenant. Move-out never cleared it, so the unit went
  // on naming someone who had left - and vendors were being texted a former tenant's name and phone number.
  try {
    const units = await fetchTab(env, 'Units');
    for (const u of units.filter(x => String(x.Tenant_ID || '') === String(tenantId))) {
      const r = await updateRow(env, 'Units', u.ID, { Tenant_ID: '' });
      if (!r.ok) fail('unit_pointer', 'unit ' + (u.Unit_Label || u.ID) + ': ' + await respErrText(r));
      else out.units_cleared.push(u.Unit_Label || u.ID);
    }
  } catch (e) { fail('unit_pointer', (e && e.message) || e); }

  // Links to work orders created AFTER the move-out date do not belong to this tenant.
  try {
    const [wos, woTenants] = await fetchTabs(env, ['Work_Orders', 'WO_Tenants']);
    for (const link of woTenants.filter(r => String(r.Tenant_ID) === String(tenantId) && r.Active !== 'FALSE')) {
      const wo = wos.find(w => w.ID === link.WO_ID);
      if (!wo || !wo.Created_Date) continue;
      const cr = String(wo.Created_Date).trim();
      const crDay = /^\d{4}-\d{2}-\d{2}$/.test(cr) ? cr : (isNaN(new Date(cr)) ? '' : new Date(cr).toLocaleDateString('en-CA', { timeZone: 'America/New_York' }));
      if (crDay && crDay > moveOutDate) {
        const r = await updateRow(env, 'WO_Tenants', link.ID, { Active: 'FALSE' });
        if (!r.ok) fail('wo_link', 'link ' + link.ID + ': ' + await respErrText(r));
        else out.retro_wos_cleaned++;
      }
    }
  } catch (e) { fail('wo_links', (e && e.message) || e); }

  if (out.errors.length) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'tenant_move_out_incomplete', Skill_Or_Endpoint: 'tenantMarkMovedOut', Success: 'FALSE', Notes: ('tenant=' + tenantId + ' ' + JSON.stringify(out.errors)).slice(0, 480) }); }
    catch (e) { out.errors.push({ step: 'telemetry', error: String((e && e.message) || e).slice(0, 160) }); }
  }
  return out;
}

async function processMoveOut(env, body) {
  const { tenant_id, move_out_date } = body;
  if (!tenant_id) return json({ error: 'tenant_id required' }, 400);
  const moveOutDate = move_out_date || new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
  const r = await tenantMarkMovedOut(env, tenant_id, moveOutDate);
  const unitsFailed = r.errors.some(e => e.step === 'unit_pointer');
  const rowFailed = r.errors.some(e => e.step === 'tenant_row' || e.step === 'tenant_row_verify');
  if (rowFailed) return json({ error: 'Move-out did NOT save: ' + r.errors.map(e => e.error).join('; '), errors: r.errors }, 500);
  return json({ success: true, move_out_date: moveOutDate, retro_wos_cleaned: r.retro_wos_cleaned,
                units_unlinked: r.units_cleared.length, units: r.units_cleared,
                // Say so loudly. A half-cleared pointer means a former tenant's number is
                // still reachable, which is the whole thing this is meant to prevent.
                units_incomplete: unitsFailed, errors: r.errors,
                warning: r.errors.length ? ('Move-out saved but some follow-up steps failed (' + r.errors.map(e => e.step).join(', ') + ') - run "Check units naming moved-out tenants" in Dev tools.') : '' });
}

// ══ OWNER TENANT ROSTER - importer / updater (Oct 14 2026, Brett) ═══════════════════════════════════════════════════
// Why: tenants kept entering the Hub with a BLANK Move_In_Date (bulk importer, owner onboarding, admin Add Tenant), and a
// blank date switches off the only protection a new tenant has from the previous tenant's work orders (isBackgroundWO
// hides + never texts a WO created before Move_In_Date). Amanda Ireland's Oct 2026 list was the trigger. This tool makes
// the dates impossible to skip, on a screen the owner can use herself:
//   GET  /owner/tenant-roster          the owner's properties/units/current tenants (for the manual form + the CSV check)
//   POST /owner/tenant-roster/preview  {rows, consent?}  validates EVERYTHING, writes NOTHING
//   POST /owner/tenant-roster/apply    {rows, consent?}  same validation; refuses the whole file if any row is bad
// Owner sessions are bound to their own id (callerSessionId, never a client-sent owner_id). Admin (Brett) may pass owner_id.
// DEFAULTS BAKED IN, NO SWITCHES (Brett's explicit call): a departing tenant is deactivated, PIN cleared, SMS_Enabled FALSE;
// an arriving tenant is linked to NO work order (so only work created on/after the move-in day, Eastern, ever reaches them
// - isBackgroundWO); nobody is texted or emailed by this tool, tenant OR owner. The owner is never shown these rules.
// A future move-out date only records the date + flags the row for the daily scheduler flip (daily_turnover job, no cron);
// NO turnover work orders are created - Brett is alerted and approves those himself.
const ROSTER_MAX_ROWS = 200;
// Cloudflare allows ~50 outbound calls per request on this plan. A big roster file therefore applies in SLICES: each call does as
// many rows as fit in the budget, then answers { partial:true, remaining:N }; the page re-sends the same file until remaining is 0.
// Safe to repeat because the plan is recomputed every call and finished rows then plan as unchanged / already_done.
const ROSTER_SUBREQ_LIMIT = 44, ROSTER_TAIL_RESERVE = 10;
const ROSTER_COST = { move_out: 13, move_out_future: 5, update: 5, insert: 10 };
const ROSTER_LOG_TAB = 'Roster_Imports';
const ROSTER_LOG_COLS = ['ID', 'Timestamp', 'Batch', 'Owner_ID', 'Actor', 'Rows', 'Moved_In', 'Moved_Out', 'Future_Move_Outs', 'Name_Fixes', 'Consent_Attested', 'Result', 'Details_JSON', 'Active'];
// Tenants columns this tool relies on. SMS_Consent: 'attested' (upload box ticked) | 'pending' (not ticked) | 'welcome_sent'.
// Welcome_Sent stays blank until Brett sends the welcome, which is what puts the person on his "not yet welcomed" list.
const ROSTER_TENANT_COLS = ['SMS_Enabled', 'SMS_Consent', 'Roster_Source', 'Roster_Batch', 'Roster_Pending_Flip', 'Welcome_Sent', 'Welcome_Sent_Date', 'Onboarding_Source'];

// '' = blank, null = not a real date, otherwise YYYY-MM-DD. Accepts YYYY-MM-DD, M/D/YYYY, M/D/YY, M-D-YYYY.
function rosterNormDate(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return '';
  let y, m, d, mt;
  if ((mt = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s))) { y = +mt[1]; m = +mt[2]; d = +mt[3]; }
  else if ((mt = /^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2}|\d{4})$/.exec(s))) { m = +mt[1]; d = +mt[2]; y = +mt[3]; if (mt[3].length === 2) y += 2000; }
  else return null;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
function rosterUnitKey(label) {
  return String(label || '').trim().toLowerCase().replace(/^(apartment|apt|unit|suite|ste|#)\s*\.?\s*/, '').replace(/\s+/g, '');
}
// Only the name parts the row actually supplies AND that really differ (trimmed, case-sensitive so a capitalisation fix counts).
// A blank part never blanks what is on file - this tool amends names, it never overwrites them with nothing.
function rosterNameFields(first, last, t) {
  const f = {};
  if (first && first !== String(t.First_Name || '').trim()) f.First_Name = first;
  if (last && last !== String(t.Last_Name || '').trim()) f.Last_Name = last;
  return f;
}
function rosterNameKey(first, last) {
  return (String(first || '') + ' ' + String(last || '')).trim().toLowerCase().replace(/\s+/g, ' ');
}
function rosterSplitName(name) {
  const s = String(name || '').trim().replace(/\s+/g, ' ');
  if (!s) return { first: '', last: '' };
  const m = /^(\S+)\s+(.*)$/.exec(s);
  return m ? { first: m[1], last: m[2] } : { first: s, last: '' };
}
// Match a typed/CSV address to one of the OWNER'S properties only. Exact normalized match first; then the same address
// without a ", City" tail; then a UNIQUE whole-word prefix ("1599 Ingleside" -> "1599 Ingleside Ave"), which is flagged as a
// warning so the person sees what it matched. Anything else is an error that names close candidates.
function rosterFindProperty(ownerProps, row) {
  const pid = String(row.property_id || '').trim();
  const addr = String(row.property || row.address || '').trim();
  if (pid) { const p = ownerProps.find(x => String(x.ID) === pid); return p ? { prop: p } : { error: 'Property id ' + pid + ' is not one of your properties.' }; }
  if (!addr) return { error: 'Property is required.' };
  const k = qbNormAddress(addr);
  const k0 = qbNormAddress(addr.split(',')[0]);
  const street = x => qbNormAddress(String(x.Address || '').split(',')[0]);
  let hit = ownerProps.filter(p => qbNormAddress(p.Address) === k);
  if (!hit.length) hit = ownerProps.filter(p => street(p) === k0);
  if (hit.length === 1) return { prop: hit[0] };
  if (hit.length > 1) return { error: '"' + addr + '" matches more than one of your properties - add the city or use the property picker.' };
  const pre = ownerProps.filter(p => { const s = street(p); return k0 && (s.startsWith(k0 + ' ') || k0.startsWith(s + ' ')); });
  if (pre.length === 1) return { prop: pre[0], warning: 'Matched "' + addr + '" to ' + pre[0].Address + '.' };
  const near = ownerProps.filter(p => { const s = street(p); const num = k0.split(' ')[0]; return num && s.split(' ')[0] === num; }).slice(0, 3).map(p => p.Address);
  return { error: 'Property "' + addr + '" is not one of your properties.' + (near.length ? ' Did you mean: ' + near.join(' / ') + '?' : '') };
}

// PURE. Everything the apply step does is decided here, from data passed in, so it is unit-testable and the preview and
// the apply can never disagree. inp: { ownerId, today:'YYYY-MM-DD'(ET), rows, properties, units, tenants, consent, batch }
// Returns { ok, rows:[{n,label,status,errors,warnings,property_id,unit_id,tenant_id,write}], counts, errors }.
//   status: move_in | move_out | name_fix | backfill | unchanged | already_done | error
function rosterPlan(inp) {
  const today = String(inp.today || '');
  const tenants = inp.tenants || [], units = inp.units || [];
  const ownerProps = (inp.properties || []).filter(p => String(p.Owner_ID || '') === String(inp.ownerId) && p.Active !== 'FALSE');
  const consent = inp.consent === true;
  const rowsIn = Array.isArray(inp.rows) ? inp.rows : [];
  const out = { ok: false, rows: [], counts: { move_in: 0, move_out: 0, future_move_out: 0, name_fix: 0, backfill: 0, unchanged: 0, already_done: 0, error: 0 }, errors: [] };
  if (!rowsIn.length) { out.errors.push('No rows to import.'); return out; }
  if (rowsIn.length > ROSTER_MAX_ROWS) { out.errors.push('Too many rows (' + rowsIn.length + '). Maximum ' + ROSTER_MAX_ROWS + ' per upload - split the file.'); return out; }
  const maxDate = String(+today.slice(0, 4) + 1) + today.slice(4);   // a year ahead: catches 2062-style typos
  const MIN_DATE = '2000-01-01';
  const departingIds = new Set();
  const claimed = new Map();   // tenant id -> row n that already targets it

  // ---- pass 1: resolve + classify each row on its own ----
  rowsIn.forEach((r, i) => {
    r = r || {};
    const res = { n: i + 1, label: '', status: 'error', errors: [], warnings: [], property_id: '', unit_id: '', tenant_id: '', phone: '', write: null, _prop: null, _unit: null, _match: null, _former: null, _mi: '', _mo: '' };
    const err = m => res.errors.push(m);
    let first = String(r.first_name || '').trim(), last = String(r.last_name || '').trim();
    if (!first && !last && r.name) { const sp = rosterSplitName(r.name); first = sp.first; last = sp.last; }
    const email = String(r.email || '').trim();
    const rawPhone = String(r.phone || '').trim();
    const phone = rawPhone ? normalizePhone(firstPhone(rawPhone)) : '';
    res.phone = phone;
    if (rawPhone && !/^\+1\d{10}$/.test(phone)) err('Phone "' + rawPhone + '" is not a valid 10-digit US number.');
    if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) res.warnings.push('Email "' + email + '" does not look valid - it will be ignored.');
    const mi = rosterNormDate(r.move_in_date), mo = rosterNormDate(r.move_out_date);
    if (mi === null) err('Move-in date "' + r.move_in_date + '" is not a real date (use YYYY-MM-DD or M/D/YYYY).');
    if (mo === null) err('Move-out date "' + r.move_out_date + '" is not a real date (use YYYY-MM-DD or M/D/YYYY).');
    if (mi && (mi < MIN_DATE || mi > maxDate)) err('Move-in date ' + mi + ' is out of range - check the year.');
    if (mo && (mo < MIN_DATE || mo > maxDate)) err('Move-out date ' + mo + ' is out of range - check the year.');
    res._mi = mi || ''; res._mo = mo || '';

    const pf = rosterFindProperty(ownerProps, r);
    if (pf.error) err(pf.error);
    const prop = pf.prop || null;
    if (pf.warning) res.warnings.push(pf.warning);
    res.label = ((prop && prop.Address) || String(r.property || r.address || r.property_id || '?')) + ' - ' + ((first + ' ' + last).trim() || '(no name)');
    if (!prop) { out.rows.push(res); return; }
    res.property_id = String(prop.ID); res._prop = prop;

    const propUnits = units.filter(u => String(u.Property_ID) === String(prop.ID) && u.Active !== 'FALSE');
    let unit = null;
    if (propUnits.length) {
      const uid = String(r.unit_id || '').trim(), ul = String(r.unit || '').trim();
      if (uid) unit = propUnits.find(u => String(u.ID) === uid) || null;
      else if (ul) { const k = rosterUnitKey(ul); unit = propUnits.find(u => rosterUnitKey(u.Unit_Label) === k) || null; }
      if (!uid && !ul) err('This property has units - enter the unit for this tenant.');
      else if (!unit) err('Unit "' + (ul || uid) + '" was not found at ' + prop.Address + ' (units: ' + propUnits.map(u => u.Unit_Label).slice(0, 8).join(', ') + ').');
    } else if (String(r.unit || r.unit_id || '').trim()) {
      res.warnings.push('This property has no units, so the unit was ignored.');
    }
    if (unit) { res.unit_id = String(unit.ID); res._unit = unit; res.label += ' (' + unit.Unit_Label + ')'; }

    // ---- match an existing tenant at THIS property: by phone, else (no phone given) by exact name ----
    const atProp = tenants.filter(t => String(t.Property_ID) === String(prop.ID));
    let cands = [];
    if (phone) cands = atProp.filter(t => normalizePhone(t.Phone) === phone);
    else if (first || last) { const nk = rosterNameKey(first, last); cands = atProp.filter(t => rosterNameKey(t.First_Name, t.Last_Name) === nk && (!unit || String(t.Unit_ID || '') === String(unit.ID))); }
    const live = cands.filter(t => !tenantMovedOut(t));
    let match = null;
    if (live.length > 1) err('More than one current tenant at this address has that ' + (phone ? 'phone number' : 'name') + ' - fix the duplicate in the Hub first.');
    else if (live.length === 1) match = live[0];
    const former = !match && cands.length ? cands[0] : null;
    res._match = match; res._former = former;
    if (match && unit && String(match.Unit_ID || '') !== String(unit.ID)) err('This person is already on file at this address under a different unit.');
    if (match) { res.tenant_id = String(match.ID); if (claimed.has(String(match.ID))) err('Row ' + claimed.get(String(match.ID)) + ' already covers the same tenant.'); else claimed.set(String(match.ID), res.n); }
    if (res.errors.length) { out.rows.push(res); return; }

    const nameFix = match ? rosterNameFields(first, last, match) : {};
    const nameDiffers = Object.keys(nameFix).length > 0;

    if (match) {
      const mMi = String(match.Move_In_Date || '').trim();
      if (mo) {
        if (mMi && /^\d{4}-\d{2}-\d{2}$/.test(mMi) && mo < mMi) { err('Move-out ' + mo + ' is before this tenant\'s move-in ' + mMi + '.'); }
        else if (mi && mMi && mi !== mMi) res.warnings.push('Move-in date ignored: this tenant is already on file with move-in ' + mMi + '.');
        if (!res.errors.length) {
          if (String(match.Move_Out_Date || '').trim() === mo && String(match.Roster_Pending_Flip || '').toUpperCase() === 'TRUE') res.status = 'already_done';
          else { res.status = 'move_out'; res.write = { type: 'move_out', tenant_id: String(match.ID), move_out_date: mo, future: mo > today }; departingIds.add(String(match.ID)); }
        }
        if (nameDiffers) res.warnings.push('Name on the row differs from the tenant on file; it was not changed because this row is a move-out.');
      } else if (mi) {
        if (mMi && mMi !== mi) err('This tenant is already on file with move-in ' + mMi + '. Move-in dates are not rewritten from here - leave the date blank to keep it, or add a move-out row.');
        else {
          const fields = {};
          if (!mMi) fields.Move_In_Date = mi;
          Object.assign(fields, nameFix);
          if (email && !String(match.Email || '').trim() && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) fields.Email = email;
          if (Object.keys(fields).length) { res.status = fields.Move_In_Date ? 'backfill' : 'name_fix'; res.write = { type: 'update', tenant_id: String(match.ID), fields }; }
          else res.status = 'unchanged';
        }
      } else {
        const fields = {};
        Object.assign(fields, nameFix);
        if (email && !String(match.Email || '').trim() && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) fields.Email = email;
        if (Object.keys(fields).length) { res.status = 'name_fix'; res.write = { type: 'update', tenant_id: String(match.ID), fields }; }
        else res.status = 'unchanged';
        if (!String(match.Move_In_Date || '').trim()) res.warnings.push('This tenant has no move-in date on file. Add one to protect them from the previous tenant\'s work orders.');
      }
    } else {
      // ---- no current tenant matched: this must be an ARRIVAL ----
      if (former && mo && !mi) {
        // Re-running a file that was already applied: the tenant is gone, on the date asked for = nothing to do.
        if (String(former.Move_Out_Date || '').trim() === mo) res.status = 'already_done';
        else err('This tenant already moved out' + (former.Move_Out_Date ? ' on ' + former.Move_Out_Date : '') + ' - the move-out date on the row (' + mo + ') does not match.');
      }
      else if (former) { err('This ' + (phone ? 'phone number' : 'name') + ' belongs to a former tenant at this address (record ' + former.ID + '). The Hub keeps one record per phone number, so this cannot be added as new - contact support.'); }
      else if (mo && !mi) err('No tenant at this address matches this row, so there is nobody to move out. Check the phone number or name.');
      else if (!mi) err('Move-in date is required for a new tenant.');
      else if (mo) err('A new tenant gets a move-in date only. Add the move-out later, when it is known.');
      else if (!first && !last) err('Tenant name is required.');
      else if (!phone) err('Phone number is required for a new tenant.');
      if (!res.errors.length && res.status !== 'already_done') {
        res.status = 'move_in';
        res.write = { type: 'insert', fields: {
          First_Name: first, Last_Name: last, Phone: phone, Email: /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) ? email : '',
          Property_ID: String(prop.ID), Unit_ID: unit ? String(unit.ID) : '', Active: 'TRUE',
          Move_In_Date: mi, Move_Out_Date: '',
          // SMS stays OFF until the upload box says the tenants agreed (or Brett sends the welcome himself). Either way the row
          // is flagged (SMS_Consent + blank Welcome_Sent) so it shows up for Brett. SMS_OptOut is the tenant's own STOP record - never set here.
          SMS_Enabled: consent ? 'TRUE' : 'FALSE', SMS_Consent: consent ? 'attested' : 'pending',
          Roster_Source: 'owner_roster', Roster_Batch: String(inp.batch || ''), Roster_Pending_Flip: '', Welcome_Sent: '', Welcome_Sent_Date: '',
        } };
      }
    }
    out.rows.push(res);
  });

  // ---- pass 2: checks that need the whole file ----
  const seenArrival = new Set();
  const livePhoneOwner = t => { const p = (inp.properties || []).find(x => String(x.ID) === String(t.Property_ID)); return p ? String(p.Owner_ID || '') : ''; };
  for (const res of out.rows) {
    if (res.status !== 'move_in') continue;
    const err = m => { res.errors.push(m); res.status = 'error'; res.write = null; };
    const prop = res._prop, unit = res._unit, phone = res.phone;
    const key = prop.ID + '|' + (unit ? unit.ID : '') + '|' + phone;
    if (seenArrival.has(key)) { err('This phone number appears twice for the same address in this file.'); continue; }
    seenArrival.add(key);
    // the number must not already be a CURRENT tenant somewhere else (unless that tenant is leaving in this same file)
    const elsewhere = tenants.filter(t => normalizePhone(t.Phone) === phone && String(t.Property_ID) !== String(prop.ID) && !tenantMovedOut(t) && !departingIds.has(String(t.ID)));
    if (elsewhere.length) {
      const t = elsewhere[0];
      const mine = livePhoneOwner(t) === String(inp.ownerId);
      const where = mine ? ((inp.properties || []).find(x => String(x.ID) === String(t.Property_ID)) || {}).Address : '';
      err('This phone number is already a current tenant' + (where ? ' at ' + where : ' at another address') + '. Add a move-out row for that tenant first (same file), or check the number.');
      continue;
    }
    const formerElsewhere = tenants.filter(t => normalizePhone(t.Phone) === phone && String(t.Property_ID) !== String(prop.ID) && tenantMovedOut(t));
    if (formerElsewhere.length) res.warnings.push('This number is also on a former tenant record elsewhere.');
    // a new tenant cannot start before the previous tenant left (backdating would link them to the old tenant's work orders)
    const scope = tenants.filter(t => String(t.Property_ID) === String(prop.ID) && (unit ? String(t.Unit_ID || '') === String(unit.ID) : true));
    let blocker = '', blockerWho = '';
    for (const t of scope) {
      const leaving = out.rows.find(x => x.status === 'move_out' && x.tenant_id === String(t.ID));
      const d = leaving ? leaving._mo : String(t.Move_Out_Date || '').trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(d) && d > blocker) { blocker = d; blockerWho = ((t.First_Name || '') + ' ' + (t.Last_Name || '')).trim(); }
    }
    if (blocker && res._mi < blocker) { err('Move-in ' + res._mi + ' is before the previous tenant' + (blockerWho ? ' (' + blockerWho + ')' : '') + ' left on ' + blocker + '. A new tenant cannot start before the old one leaves.'); continue; }
    const stay = scope.filter(t => !tenantMovedOut(t) && !departingIds.has(String(t.ID)));
    if (stay.length) res.warnings.push(stay.length + ' other current tenant' + (stay.length > 1 ? 's' : '') + ' stay' + (stay.length > 1 ? '' : 's') + ' on file at this address (' + stay.slice(0, 3).map(t => ((t.First_Name || '') + ' ' + (t.Last_Name || '')).trim()).join(', ') + '). If someone has left, add a move-out row.');
  }

  for (const res of out.rows) {
    out.counts[res.status === 'error' ? 'error' : res.status]++;
    if (res.status === 'move_out' && res.write.future) out.counts.future_move_out++;
    delete res._prop; delete res._unit; delete res._match; delete res._former; delete res._mi; delete res._mo;
  }
  out.ok = out.counts.error === 0;
  return out;
}

// Verified-write helpers ------------------------------------------------------------------------------------------
async function rosterWriteTenant(env, tenantId, fields) {
  const r = await updateRow(env, 'Tenants', tenantId, fields);
  if (!r.ok) throw new Error(await respErrText(r));
  const back = (await fetchTab(env, 'Tenants')).find(t => String(t.ID) === String(tenantId));
  if (!back) throw new Error('tenant ' + tenantId + ' not found after the write');
  for (const [k, v] of Object.entries(fields)) {
    if (String(back[k] == null ? '' : back[k]) !== String(v)) throw new Error('read-back mismatch on ' + k + ' (wanted "' + v + '", sheet has "' + (back[k] || '') + '")');
  }
  return back;
}

// owner_id for the roster routes: an owner session is bound to its own id; admin must name one.
function rosterOwnerId(callerRole, callerSessionId, body, url) {
  if (callerRole === 'owner') return String(callerSessionId || '');
  return String((body && body.owner_id) || (url && url.searchParams && url.searchParams.get('owner_id')) || '');
}

// GET /owner/tenant-roster - what the manual form and the CSV check need. No PINs, no SMS/consent state (owners are not shown those rules).
async function ownerRosterList(env, callerRole, callerSessionId, url) {
  const ownerId = rosterOwnerId(callerRole, callerSessionId, null, url);
  if (!ownerId) return json({ error: 'owner_id required' }, 400);
  const [properties, units, tenants] = await fetchTabs(env, ['Properties', 'Units', 'Tenants']);
  const props = properties.filter(p => String(p.Owner_ID || '') === ownerId && p.Active !== 'FALSE');
  const ids = new Set(props.map(p => String(p.ID)));
  return json({
    owner_id: ownerId,
    max_rows: ROSTER_MAX_ROWS,
    properties: props.map(p => ({ id: String(p.ID), address: p.Address || '', units: units.filter(u => String(u.Property_ID) === String(p.ID) && u.Active !== 'FALSE').map(u => ({ id: String(u.ID), label: u.Unit_Label || '' })) })),
    tenants: tenants.filter(t => ids.has(String(t.Property_ID))).map(t => ({
      id: String(t.ID), property_id: String(t.Property_ID), unit_id: String(t.Unit_ID || ''),
      name: ((t.First_Name || '') + ' ' + (t.Last_Name || '')).trim(), phone: t.Phone || '', email: t.Email || '',
      move_in_date: t.Move_In_Date || '', move_out_date: t.Move_Out_Date || '', current: !tenantMovedOut(t),
    })),
  });
}

async function rosterLoadPlan(env, ownerId, body, batch) {
  const [owners, properties, units, tenants] = await fetchTabs(env, ['Owners', 'Properties', 'Units', 'Tenants']);
  const owner = owners.find(o => String(o.ID) === String(ownerId) && o.Active !== 'FALSE');
  if (!owner) return { error: 'Owner not found', status: 404 };
  const rows = body && Array.isArray(body.rows) ? body.rows : null;
  if (!rows) return { error: 'rows (array) required', status: 400 };
  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
  // ONLY rows + the consent box are read from the client. No other option exists (no SMS switch, no notify, no override).
  const plan = rosterPlan({ ownerId, today, rows, properties, units, tenants, consent: !!(body && body.consent === true), batch });
  return { owner, plan, units, tenants, today };
}

// POST /owner/tenant-roster/preview - validate only. Writes NOTHING.
async function ownerRosterPreview(env, callerRole, callerSessionId, body) {
  const ownerId = rosterOwnerId(callerRole, callerSessionId, body);
  if (!ownerId) return json({ error: 'owner_id required' }, 400);
  const L = await rosterLoadPlan(env, ownerId, body, '');
  if (L.error) return json({ error: L.error }, L.status);
  return json({ ok: L.plan.ok, mode: 'preview', plan: L.plan, writes: false });
}

// POST /owner/tenant-roster/apply - all-or-nothing validation, then ordered writes (move-outs, fixes, arrivals), each verified.
async function ownerRosterApply(env, callerRole, callerSessionId, body) {
  const ownerId = rosterOwnerId(callerRole, callerSessionId, body);
  if (!ownerId) return json({ error: 'owner_id required' }, 400);
  const actor = callerRole === 'owner' ? 'owner:' + ownerId : 'admin';
  const startCalls = __sheetsFetchCount;
  const used = () => __sheetsFetchCount - startCalls;
  // A continuation call (the page re-sends the same file until nothing remains) carries the batch id from the first call.
  const batch = /^RB-\d{8}-[A-Z0-9]{4}$/.test(String((body && body.batch) || '')) ? String(body.batch)
    : 'RB-' + new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' }).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
  const L = await rosterLoadPlan(env, ownerId, body, batch);
  if (L.error) return json({ error: L.error }, L.status);
  const plan = L.plan;
  if (!plan.ok) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'tenant_roster_refused', Skill_Or_Endpoint: '/owner/tenant-roster/apply', Success: 'FALSE', Notes: ('owner=' + ownerId + ' actor=' + actor + ' rows=' + plan.rows.length + ' errors=' + plan.counts.error + ' ' + plan.errors.join('; ')).slice(0, 480) }); }
    catch (e) { plan.errors.push('Could not record the refusal in telemetry: ' + String((e && e.message) || e).slice(0, 120)); }
    return json({ ok: false, applied: false, refused: true, plan, error: 'Nothing was imported. Fix the rows marked in red and try again.' }, 422);
  }
  const results = [], warnings = [];
  const today = L.today;
  try { await ensureColumns(env, 'Tenants', ROSTER_TENANT_COLS); await ensureTab(env, ROSTER_LOG_TAB, ROSTER_LOG_COLS); }
  catch (e) { return json({ ok: false, applied: false, error: 'Could not prepare the Tenants sheet columns - nothing was imported: ' + String((e && e.message) || e).slice(0, 200) }, 500); }
  const done = (row, extra) => results.push(Object.assign({ n: row.n, label: row.label, status: row.status, applied: true }, extra || {}));
  const failed = (row, e) => results.push({ n: row.n, label: row.label, status: row.status, applied: false, error: String((e && e.message) || e).slice(0, 240) });
  // Budget: always attempt the first row (so every call makes progress); after that only start a row if it fits.
  const deferred = [];
  const fits = est => results.length === 0 || used() + est + ROSTER_TAIL_RESERVE <= ROSTER_SUBREQ_LIMIT;

  // 1. departures
  for (const row of plan.rows.filter(r => r.status === 'move_out')) {
    const w = row.write;
    if (!fits(w.future ? ROSTER_COST.move_out_future : ROSTER_COST.move_out)) { deferred.push(row); continue; }
    try {
      if (w.future) { await rosterWriteTenant(env, w.tenant_id, { Move_Out_Date: w.move_out_date, Roster_Pending_Flip: 'TRUE' }); done(row, { future: true, move_out_date: w.move_out_date }); }
      else {
        const r = await tenantMarkMovedOut(env, w.tenant_id, w.move_out_date);
        if (r.errors.length) failed(row, new Error(r.errors.map(e => e.step + ': ' + e.error).join('; '))); else done(row, { move_out_date: w.move_out_date });
      }
    } catch (e) { failed(row, e); }
  }
  // 2. name fixes / move-in backfills (amend only - the update carries just the changed fields)
  for (const row of plan.rows.filter(r => r.status === 'name_fix' || r.status === 'backfill')) {
    if (!fits(ROSTER_COST.update)) { deferred.push(row); continue; }
    try { await rosterWriteTenant(env, row.write.tenant_id, row.write.fields); done(row); } catch (e) { failed(row, e); }
  }
  // 3. arrivals
  for (const row of plan.rows.filter(r => r.status === 'move_in')) {
    if (!fits(ROSTER_COST.insert)) { deferred.push(row); continue; }
    try {
      const add = await addRow(env, 'Tenants', Object.assign({}, row.write.fields));
      const addJ = await add.json();
      if (!add.ok || !addJ.id) throw new Error(addJ.error || ('HTTP ' + add.status));
      const back = (await fetchTab(env, 'Tenants')).find(t => String(t.ID) === String(addJ.id));
      if (!back || back.Move_In_Date !== row.write.fields.Move_In_Date || String(back.Active).toUpperCase() !== 'TRUE' || normalizePhone(back.Phone) !== row.write.fields.Phone) throw new Error('new tenant row did not read back correctly (id ' + addJ.id + ')');
      let unitLinked = '';
      if (row.unit_id) {
        const u = (await fetchTab(env, 'Units')).find(x => String(x.ID) === String(row.unit_id));
        if (u && !String(u.Tenant_ID || '').trim()) {
          const ur = await updateRow(env, 'Units', u.ID, { Tenant_ID: String(addJ.id) });
          if (!ur.ok) warnings.push(row.label + ': tenant added but the unit pointer could not be set (' + await respErrText(ur) + ').'); else unitLinked = u.Unit_Label || u.ID;
        }
      }
      done(row, { tenant_id: String(addJ.id), unit_linked: unitLinked });
    } catch (e) { failed(row, e); }
  }

  const bad = results.filter(r => !r.applied);
  const counts = { move_in: results.filter(r => r.applied && r.status === 'move_in').length, move_out: results.filter(r => r.applied && r.status === 'move_out').length,
    future_move_out: results.filter(r => r.applied && r.future).length, name_fix: results.filter(r => r.applied && (r.status === 'name_fix' || r.status === 'backfill')).length,
    unchanged: plan.counts.unchanged + plan.counts.already_done, failed: bad.length };
  const ok = bad.length === 0;
  const partial = deferred.length > 0;   // more rows still to do: the page re-sends the same file (same batch) until this is false
  const owner = L.owner;
  const ownerLabel = (owner.Company || ((owner.First_Name || '') + ' ' + (owner.Last_Name || '')).trim() || 'owner ' + ownerId);

  // audit row + telemetry (failures here are reported, never swallowed)
  const auditTs = new Date().toISOString();
  try {
    const lr = await addRow(env, ROSTER_LOG_TAB, { Timestamp: auditTs, Batch: batch, Owner_ID: ownerId, Actor: actor, Rows: String(plan.rows.length), Moved_In: String(counts.move_in), Moved_Out: String(counts.move_out),
      Future_Move_Outs: String(counts.future_move_out), Name_Fixes: String(counts.name_fix), Consent_Attested: body.consent === true ? 'TRUE' : 'FALSE', Result: !ok ? 'partial_failure' : (partial ? 'in_progress' : 'ok'),
      Details_JSON: JSON.stringify(results.map(r => ({ n: r.n, s: r.status, ok: r.applied, id: r.tenant_id || '', e: r.error || '' }))).slice(0, 40000), Active: 'TRUE' });
    if (!lr.ok) warnings.push('The audit log row could not be written (' + await respErrText(lr) + ').');
  } catch (e) { warnings.push('The audit log row could not be written: ' + String((e && e.message) || e).slice(0, 160)); }
  try {
    await logTelemetry(env, { Source: 'worker', Job_Type: 'tenant_roster_apply', Skill_Or_Endpoint: '/owner/tenant-roster/apply', Success: ok ? 'TRUE' : 'FALSE',
      Notes: ('batch=' + batch + ' owner=' + ownerId + ' actor=' + actor + ' in=' + counts.move_in + ' out=' + counts.move_out + ' future=' + counts.future_move_out + ' fixes=' + counts.name_fix + ' failed=' + counts.failed + ' deferred=' + deferred.length + ' calls=' + used() + (bad.length ? ' ' + bad.map(b => 'row' + b.n + ':' + b.error).join('; ') : '')).slice(0, 480) });
  } catch (e) { warnings.push('Telemetry could not be written: ' + String((e && e.message) || e).slice(0, 160)); }

  // ONE heads-up to Brett (admin phone) per batch, sent by the LAST slice only - never to the owner or any tenant. The totals add up the
  // earlier slices from the Roster_Imports audit rows. A failure to alert (or to read them) is reported, not hidden.
  if (!partial || bad.length) {
    try {
      const tot = { in: counts.move_in, out: counts.move_out, future: counts.future_move_out, fix: counts.name_fix };
      if (body && body.batch === batch) {
        try {
          for (const x of (await fetchTab(env, ROSTER_LOG_TAB)).filter(x => x.Batch === batch && x.Timestamp !== auditTs)) {
            tot.in += +x.Moved_In || 0; tot.out += +x.Moved_Out || 0; tot.future += +x.Future_Move_Outs || 0; tot.fix += +x.Name_Fixes || 0;
          }
        } catch (e) { warnings.push('Could not add up the earlier parts of this import for the heads-up text: ' + String((e && e.message) || e).slice(0, 120)); }
      }
      const txt = 'Roster import (' + ownerLabel + '): ' + tot.in + ' in, ' + tot.out + ' out' + (tot.future ? ' (' + tot.future + ' future)' : '') + ', ' + tot.fix + ' name fixes'
        + (counts.failed ? ', ' + counts.failed + ' FAILED' : '') + '. ' + (tot.in ? tot.in + ' new tenants flagged for consent/welcome. ' : '')
        + (tot.future ? tot.future + ' future move-out(s) booked - no turnover WOs created; approve when ready. ' : '') + 'Batch ' + batch + '.';
      const an = await adminNotify(env, { text: txt, source: 'tenant_roster' });
      if (!an.ok) warnings.push('Heads-up text to Brett was not sent: ' + await respErrText(an));
    } catch (e) { warnings.push('Heads-up text to Brett was not sent: ' + String((e && e.message) || e).slice(0, 160)); }
  }

  return json({ ok, applied: true, partial, remaining: deferred.length, subrequests_used: used(), batch, counts, results, warnings, plan: { counts: plan.counts, rows: plan.rows.map(r => ({ n: r.n, label: r.label, status: r.status, warnings: r.warnings })) } }, ok ? 200 : 207);
}

// Daily scheduler step (rides the existing daily_turnover job - NO new cron, NO new Apps Script row): flips the tenants the
// roster tool booked a FUTURE move-out for, once that date has passed (Eastern). Scoped by Roster_Pending_Flip so it can never
// touch a tenant it did not book. Reports failures loudly (throws after trying all) so /cron/status and the alert path see them.
async function rosterFlipDueMoveOuts(env) {
  const tenants = await fetchTab(env, 'Tenants');
  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
  const due = tenants.filter(t => String(t.Roster_Pending_Flip || '').toUpperCase() === 'TRUE' && String(t.Active).toUpperCase() !== 'FALSE' && /^\d{4}-\d{2}-\d{2}$/.test(String(t.Move_Out_Date || '').trim()) && today > String(t.Move_Out_Date).trim());
  const flipped = [], problems = [], deferred = [];
  const startCalls = __sheetsFetchCount;
  for (const t of due) {
    // Same ~50-call request cap as the roster apply: flip what fits, leave the rest for tomorrow's run (counted in the telemetry row).
    if (flipped.length + problems.length > 0 && (__sheetsFetchCount - startCalls) + ROSTER_COST.move_out + ROSTER_TAIL_RESERVE > ROSTER_SUBREQ_LIMIT) { deferred.push(String(t.ID)); continue; }
    try {
      const r = await tenantMarkMovedOut(env, t.ID, String(t.Move_Out_Date).trim());
      if (r.errors.length) problems.push('tenant ' + t.ID + ': ' + r.errors.map(e => e.step + ' ' + e.error).join('; '));
      else flipped.push(String(t.ID));
    } catch (e) { problems.push('tenant ' + t.ID + ': ' + String((e && e.message) || e)); }
  }
  if (due.length) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'tenant_roster_flip', Skill_Or_Endpoint: 'daily_turnover', Success: problems.length ? 'FALSE' : 'TRUE', Notes: ('flipped=' + flipped.join(',') + (deferred.length ? ' deferred_to_next_run=' + deferred.join(',') : '') + (problems.length ? ' problems=' + problems.join(' | ') : '')).slice(0, 480) }); }
    catch (e) { problems.push('telemetry: ' + String((e && e.message) || e)); }
  }
  if (problems.length) throw new Error('roster move-out flip had problems: ' + problems.join(' | ').slice(0, 400));
  return { due: due.length, flipped, deferred };
}

// Oct 14 2026 (Brett: "yes to all refusing without move-in/move-out dates"): the dates are what keep a new tenant away from the
// previous tenant's work orders, so NO path may create a tenant without them. One rule, used by /tenant/add (admin Hub, every
// importer page), the bulk importer and owner onboarding: a tenant needs a real Move_In_Date; a tenant created as already gone
// (Active FALSE) also needs a Move_Out_Date that is not before the move-in. Returns '' when fine, otherwise the plain-English reason.
function tenantDatesError(f) {
  f = f || {};
  const mi = rosterNormDate(f.Move_In_Date);
  if (mi === null) return 'Move-in date "' + f.Move_In_Date + '" is not a real date (use YYYY-MM-DD).';
  if (!mi) return 'Move-in date is required. Without it the tenant would see - and be texted about - the previous tenant\'s work orders.';
  if (String(f.Active == null ? '' : f.Active).toUpperCase() === 'FALSE') {
    const mo = rosterNormDate(f.Move_Out_Date);
    if (mo === null) return 'Move-out date "' + f.Move_Out_Date + '" is not a real date (use YYYY-MM-DD).';
    if (!mo) return 'Move-out date is required for a tenant who has already left.';
    if (mo < mi) return 'Move-out date is before the move-in date.';
  } else if (String(f.Move_Out_Date || '').trim()) {
    const mo = rosterNormDate(f.Move_Out_Date);
    if (mo === null) return 'Move-out date "' + f.Move_Out_Date + '" is not a real date (use YYYY-MM-DD).';
    if (mo < mi) return 'Move-out date is before the move-in date.';
  }
  return '';
}
async function tenantAddGuarded(env, body) {
  body = body || {};
  const why = tenantDatesError(body);
  if (why) {
    const out = { error: why, code: 'tenant_dates_required' };
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'tenant_add_refused', Skill_Or_Endpoint: '/tenant/add', Success: 'FALSE', Notes: ('property=' + (body.Property_ID || '') + ' unit=' + (body.Unit_ID || '') + ' ' + why).slice(0, 480) }); }
    catch (e) { out.telemetry_error = String((e && e.message) || e).slice(0, 160); }
    return json(out, 400);
  }
  body.Move_In_Date = rosterNormDate(body.Move_In_Date);
  if (String(body.Move_Out_Date || '').trim()) body.Move_Out_Date = rosterNormDate(body.Move_Out_Date);
  return await addRow(env, 'Tenants', body);
}
// /tenant/update must not be a back door: it can change a date but never blank the move-in of a tenant.
async function tenantUpdateGuarded(env, body) {
  const f = body && body.fields;
  if (f && Object.prototype.hasOwnProperty.call(f, 'Move_In_Date')) {
    const mi = rosterNormDate(f.Move_In_Date);
    if (mi === null) return json({ error: 'Move-in date "' + f.Move_In_Date + '" is not a real date (use YYYY-MM-DD).', code: 'tenant_dates_required' }, 400);
    if (!mi) return json({ error: 'The move-in date cannot be cleared. Without it the tenant would see the previous tenant\'s work orders.', code: 'tenant_dates_required' }, 400);
    f.Move_In_Date = mi;
  }
  return await updateRow(env, 'Tenants', body && body.id, f);
}

// ── Tenant work-order-submission toggle (Aug 20, 2026) ──────────────────────
// Brett's ask: turn tenants' ability to submit their own work orders on/off, settable at the
// OWNER level (which can scope itself to specific properties) and the PROPERTY level (which
// can scope itself to specific units). Owner-level, when it applies to this property, ALWAYS
// wins over whatever the property has set — "if I set it at the owner level, that's what
// takes place." Nothing set anywhere → OFF (Brett's explicit call — safer than silently
// defaulting every tenant to "can submit" until someone remembers to flip a switch).
//
// Data model (self-provisioning via ensureColumns, so this is a no-op deploy until first use):
//   Owners.Tenant_WO_Toggle        ''|'ON'|'OFF'  — the owner-level override, if any
//   Owners.Tenant_WO_Property_IDs  comma-separated Property IDs the override applies to;
//                                  blank = ALL of this owner's properties
//   Properties.Tenant_WO_Toggle       ''|'ON'|'OFF'  — the property-level default, if any
//   Properties.Tenant_WO_Unit_IDs     comma-separated Unit IDs it applies to; blank = ALL units
//
// resolveTenantWOAccess is a pure function (no I/O) so it's cheap to unit-test and reused by
// both the single-lookup gate (resolveTenantSubmitAccess) and the settings-page summary
// (tenantWOSettingsSummary) without re-fetching Sheets data for every row.
function resolveTenantWOAccess(property, owner, unitId) {
  if (!property) return false;
  if (owner && (owner.Tenant_WO_Toggle === 'ON' || owner.Tenant_WO_Toggle === 'OFF')) {
    const scoped = String(owner.Tenant_WO_Property_IDs || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!scoped.length || scoped.includes(property.ID)) return owner.Tenant_WO_Toggle === 'ON';
  }
  if (property.Tenant_WO_Toggle === 'ON' || property.Tenant_WO_Toggle === 'OFF') {
    const scoped = String(property.Tenant_WO_Unit_IDs || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!scoped.length || (unitId && scoped.includes(unitId))) return property.Tenant_WO_Toggle === 'ON';
  }
  return false;
}

async function resolveTenantSubmitAccess(env, propertyId, unitId) {
  if (!propertyId) return false;
  const [properties, owners] = await fetchTabs(env, ['Properties', 'Owners']);
  const property = properties.find(p => p.ID === propertyId);
  if (!property) return false;
  const owner = property.Owner_ID ? owners.find(o => o.ID === property.Owner_ID) : null;
  return resolveTenantWOAccess(property, owner, unitId || '');
}

async function setOwnerTenantWOToggle(env, body) {
  if (!body.owner_id) return json({ error: 'Missing owner_id' }, 400);
  await ensureColumns(env, 'Owners', ['Tenant_WO_Toggle', 'Tenant_WO_Property_IDs']);
  const toggle = body.toggle === 'ON' ? 'ON' : body.toggle === 'OFF' ? 'OFF' : '';
  const ids = Array.isArray(body.property_ids) ? body.property_ids.filter(Boolean).join(',') : String(body.property_ids || '');
  return await updateRow(env, 'Owners', body.owner_id, { Tenant_WO_Toggle: toggle, Tenant_WO_Property_IDs: ids });
}

async function setPropertyTenantWOToggle(env, body) {
  if (!body.property_id) return json({ error: 'Missing property_id' }, 400);
  await ensureColumns(env, 'Properties', ['Tenant_WO_Toggle', 'Tenant_WO_Unit_IDs']);
  const toggle = body.toggle === 'ON' ? 'ON' : body.toggle === 'OFF' ? 'OFF' : '';
  const ids = Array.isArray(body.unit_ids) ? body.unit_ids.filter(Boolean).join(',') : String(body.unit_ids || '');
  return await updateRow(env, 'Properties', body.property_id, { Tenant_WO_Toggle: toggle, Tenant_WO_Unit_IDs: ids });
}

// Sep 16 2026 (Brett): free text shown to a tenant on any WO the owner has claimed as their
// own (Managed_By='Owner'), directing them to the owner instead of Ridge Co — e.g. "Check
// your Buildium portal for updates" for an owner who runs their own tenant system, or just a
// phone number for one who doesn't. Set once per owner, added lazily (only once a reassignment
// actually happens for that owner), not pre-populated for every owner up front. Same
// ensureColumns-then-updateRow shape as setOwnerTenantWOToggle right above, since the generic
// POST /owner/update endpoint won't auto-create a brand-new column on its own.
async function setOwnerHeldContactNote(env, body) {
  if (!body.owner_id) return json({ error: 'Missing owner_id' }, 400);
  await ensureColumns(env, 'Owners', ['Held_Contact_Note']);
  return await updateRow(env, 'Owners', body.owner_id, { Held_Contact_Note: body.note || '' });
}

// One-shot read for the settings page: every active owner (with its toggle + scoped
// properties) and every active property (with its own toggle + a per-unit resolved
// "enabled" so the page can render the live effective state without re-implementing the
// hierarchy logic client-side).
async function tenantWOSettingsSummary(env) {
  const [properties, owners, units] = await fetchTabs(env, ['Properties', 'Owners', 'Units']);
  const ownerById = {}; owners.forEach(o => { ownerById[o.ID] = o; });
  const activeProps = properties.filter(p => p.Active !== 'FALSE');
  const propRows = activeProps.map(p => {
    const owner = p.Owner_ID ? ownerById[p.Owner_ID] : null;
    const propUnits = units.filter(u => u.Property_ID === p.ID && u.Active !== 'FALSE');
    return {
      property_id: p.ID,
      address: p.Address || '',
      owner_id: p.Owner_ID || '',
      owner_toggle: owner ? (owner.Tenant_WO_Toggle || '') : '',
      owner_property_ids: owner ? (owner.Tenant_WO_Property_IDs || '') : '',
      property_toggle: p.Tenant_WO_Toggle || '',
      property_unit_ids: p.Tenant_WO_Unit_IDs || '',
      whole_property_enabled: resolveTenantWOAccess(p, owner, ''),
      units: propUnits.map(u => ({ unit_id: u.ID, unit_label: u.Unit_Label || '', enabled: resolveTenantWOAccess(p, owner, u.ID) })),
    };
  });
  const ownerRows = owners.filter(o => o.Active !== 'FALSE').map(o => ({
    owner_id: o.ID,
    name: (`${o.First_Name || ''} ${o.Last_Name || ''}`.trim()) || o.Company || `Owner ${o.ID}`,
    toggle: o.Tenant_WO_Toggle || '',
    property_ids: o.Tenant_WO_Property_IDs || '',
    property_count: activeProps.filter(p => p.Owner_ID === o.ID).length,
  }));
  return json({ owners: ownerRows, properties: propRows });
}

// Same-isolate, synchronous claim against the WO-create duplicate race — see the long comment
// in createWorkOrder for why this exists alongside findRecentDuplicate rather than instead of
// it. Keyed on the exact same signature fields findRecentDuplicate matches on, so it can never
// be stricter than that check (a genuinely different description/property/unit never collides).
// TTL is a little longer than the Work_Orders findRecentDuplicate window (60s) so a slow first
// request can't have its claim expire out from under it while still mid-flight.
const __woClaimCache = new Map(); // signatureKey -> expiry (ms epoch)
const WO_CLAIM_TTL_MS = 75000;
function claimWOSignature(sig) {
  const key = ['Property_ID', 'Unit_ID', 'Tenant_ID', 'Trade', 'Description', 'Type', 'Parent_WO_ID']
    .map(k => String(sig[k] || '')).join('\u0001');
  const now = Date.now();
  for (const [k, exp] of __woClaimCache) if (exp <= now) __woClaimCache.delete(k); // opportunistic sweep, keeps the Map from growing forever
  const existing = __woClaimCache.get(key);
  if (existing && existing > now) return false; // already claimed and still live
  __woClaimCache.set(key, now + WO_CLAIM_TTL_MS);
  return true;
}

async function createWorkOrder(env, body) {
  const _t0 = Date.now();
  // Same property/unit/tenant, same trade/description, seconds apart = a double-tap on
  // Create Work Order, not two real jobs. Before this guard, a double-tap always produced
  // two rows sharing the SAME auto-incremented WO number — both requests read the sheet's
  // current max ID before either had appended, so both computed the identical "next" number.
  // Every WO lookup elsewhere (findWO, updateWOFields' rowIndex, updateRow) resolves by
  // ID with a plain first-match .find()/.findIndex(), so the second of those two rows became
  // permanently unreachable by any endpoint in the app — no button could ever touch it again
  // (WO-1192, 2026-09-14). Same pattern/window as Receipts and Time_Entries: short window,
  // full signature match, hand back the row that already exists instead of appending a twin.
  //
  // Root cause of WO-1213/WO-1214 (2026-09-23, Lance Serafica, identical description, 30s
  // apart) — a pure TOCTOU race between this Sheets-backed check and the append it guards.
  // findRecentDuplicate's "is there already a matching row?" read and this function's own
  // append are two separate round trips with nothing in between stopping a second request from
  // reading the sheet before the first request's write has landed — exactly the class of bug
  // rule 179's cronSweep claim exists for, just never applied here. The tenant `/workorder`
  // path makes it worse: session→tenant resolution and the tenant-WO-toggle access check both
  // run first and are themselves awaited Sheets reads, so a second submission arriving ~30s
  // later (a tenant who saw no confirmation and tried again) does its OWN duplicate check even
  // later than that, right at or past the edge of the 30s window rule 162 set. Live-reproduced
  // against staging pre-fix: two identical /workorder submissions 30s apart both created a
  // fresh WO (WO-1094 -> WO-1095), confirming this analysis before writing the fix below.
  //
  // Fix has two parts:
  //  1. A synchronous, same-isolate claim below. Cloudflare Workers are single-threaded within
  //     an isolate — a plain Map check-and-set with no `await` between them cannot race with
  //     itself, unlike the Sheets read/append pair. This is a REAL lock for the common case
  //     (a tenant's own two taps land on the same isolate) and is checked before any network
  //     call at all, so it can't be starved by upstream latency the way the sheet-based check
  //     can. It is not cross-isolate durable — see claimWOSignature's own comment — so it's a
  //     fast first line of defense layered on top of findRecentDuplicate below, not a
  //     replacement for it.
  //  2. The window itself: widened 30s -> 60s for Work_Orders specifically (findRecentDuplicate
  //     also got its own latency fix — see its comment — but the tenant path's pre-check
  //     latency happens before findRecentDuplicate is even called, so a wider nominal window is
  //     the only way to keep real margin here). Still a full-signature match (property + unit +
  //     tenant + trade + description + type), so two genuinely different tenant requests close
  //     in time are never blocked by this — only an exact repeat of the same complaint is.
  const _woSig = {
    Property_ID: body.property_id || '', Unit_ID: body.unit_id || '', Tenant_ID: body.tenant_id || '',
    Trade: body.trade || '', Description: body.description || '', Type: body.type || 'manual',
    ...(body.parent_wo_id ? { Parent_WO_ID: String(body.parent_wo_id) } : {}),   // additional-work child: type + parent are part of the signature
  };
  const _gotClaim = claimWOSignature(_woSig);
  if (!_gotClaim) {
    // Another request in this isolate already claimed this exact signature and may still be
    // mid-flight (not necessarily finished writing yet), so a single check right now could
    // still miss it. Poll briefly for it to land instead of racing ahead to append a twin.
    for (let i = 0; i < 6; i++) {
      await new Promise(r => setTimeout(r, 350));
      const found = await findRecentDuplicate(env, 'Work_Orders', _woSig, 60);
      if (found) return json({ success: true, duplicate: true, id: found.ID });
    }
    // Gave up waiting (the "owner" of the claim errored out, or this really is a stale claim
    // slot getting reused) — fall through to the normal single-source-of-truth check below
    // rather than blocking a legitimate write forever.
  }
  const dupe = await findRecentDuplicate(env, 'Work_Orders', _woSig, 60);
  if (dupe) return json({ success: true, duplicate: true, id: dupe.ID });

  // If a checklist was defined at creation, make sure the column exists BEFORE we read the
  // header row — otherwise the field maps to a non-existent header and is silently dropped.
  if (body.checklist) { try { await ensureColumns(env, 'Work_Orders', ['Checklist']); } catch(_){} }
  const data = await sheetsRequest(env, 'GET', `/values/Work_Orders`);
  const rows = data.values || [];
  if (!rows.length) throw new Error('Work_Orders tab has no headers');
  const headers = rows[0];
  // The WO number lives in the "ID" column, which is NOT column 0 — column 0 is
  // Vendor_Needs_Access (blank/"auto"). Reading r[0] found no numbers at all, so
  // every new WO restarted at WO-1001 and collided with itself. Resolve by header.
  const idCol = headers.indexOf('ID');
  if (idCol === -1) throw new Error('Work_Orders tab has no ID column');
  let nextWONum = 1001;
  if (rows.length > 1) {
    const existingNums = rows.slice(1).map(r => parseInt(String(r[idCol]||'').replace(/\D/g,'')) || 0).filter(n => Number.isFinite(n) && n > 0);
    if (existingNums.length > 0) nextWONum = Math.max(...existingNums) + 1;
  }
  let woId = `WO-${nextWONum}`; const now = new Date().toISOString();
  const newRow = headers.map(h => ({ ID: woId, Property_ID: body.property_id||'', Unit_ID: body.unit_id||'', Tenant_ID: body.tenant_id||'', Vendor_ID: '', Type: body.type||'manual', Trade: body.trade||'', Description: body.description||'', Priority: body.priority||'normal', Status: 'New', Scheduled_Date: '', Scheduled_Window: '', Completed_Date: '', Invoice_ID: '', Owner_WO_Ref: body.owner_wo_ref||'', WO_Contact_Name: body.wo_contact_name||'', WO_Contact_Phone: body.wo_contact_phone||'', Tenant_Visible: body.tenant_visible !== false && body.tenant_visible !== 'FALSE' ? 'TRUE' : 'FALSE', Tenant_Notify_Created: body.tenant_notify_created !== false && body.tenant_notify_created !== 'FALSE' ? 'TRUE' : 'FALSE', Tenant_Notify_Updates: body.tenant_notify_updates !== false && body.tenant_notify_updates !== 'FALSE' ? 'TRUE' : 'FALSE', Vendor_SMS_Sent: 'FALSE', Tenant_SMS_Sent: 'FALSE', Owner_Notified: 'FALSE', Created_By: body.created_by||'admin', Created_Date: now, Notes: body.notes||'', Room: body.room||'', Vendor_Needs_Access: body.vendor_needs_access||'auto', Checklist: body.checklist||'',
    // Self-Serve Work Orders ("One-Off Job", Sep 24 2026 build brief §4b) — blank/no-op for
    // every other caller (tenant submit.html, the Hub's New WO modal, etc.); only
    // workorderSelfServe ever sends these three, and only after ensureColumns has already
    // added them to Work_Orders.
    Created_By_Vendor: body.created_by_vendor||'', Approval_Source: body.approval_source||'', Approval_Note: body.approval_note||'',
    // Recurring WOs (Sep 28 2026) — only processRecurringWorkOrders/recurPostWO send these, after ensureColumns.
    Recurring_Template_ID: body.recurring_template_id||'', Recurring_Due: body.recurring_due||'', Owner_Notify_Override: body.owner_notify_override||'',
    // Vendor Additional Work (Sep 30 2026) — only /wo/additional-work/start sends this, after ensureColumns.
    Parent_WO_ID: body.parent_wo_id||''
  }[h] ?? ''));
  const _woAppend = await sheetsRequest(env, 'POST', `/values/Work_Orders:append?valueInputOption=RAW`, { values: [newRow] });
  // Oct 16 2026: if another request took the same WO number in the gap, give THIS row the next free number (and say so in telemetry).
  woId = (await guardAppendedIds(env, 'Work_Orders', _woAppend, rows.length, idCol, [woId], (v, c) => 'WO-' + mintNextNumericId(v, c))).ids[0];
  try {
    const tenants = await fetchTab(env, 'Tenants');
    const activeTenants = tenants.filter(t => { if (t.Active === 'FALSE') return false; if (body.unit_id) return t.Unit_ID === body.unit_id; if (body.property_id) return !t.Unit_ID && String(t.Property_ID) === String(body.property_id); return false; });
    const allTenantIds = new Set([...activeTenants.map(t => t.ID), ...(Array.isArray(body.tenant_ids) ? body.tenant_ids : [])]);
    for (const tid of allTenantIds) {
      const t = tenants.find(x => x.ID === tid); if (!t) continue;
      await addRow(env, 'WO_Tenants', { WO_ID: woId, Tenant_ID: tid, Tenant_Name: ((t.First_Name||'')+' '+(t.Last_Name||'')).trim(), Tenant_Phone: t.Phone||'', Added_By: 'system-auto', Added_Date: now, Active: 'TRUE' });
    }
  } catch(e) {}
  // Owner Received + Tenant Received (Sep 14 2026, Brett) — fire only on WO creation, not on
  // later status changes (Scheduled/Complete/On_Hold already fire from updateStatus). Own
  // try/catch, non-fatal — WO creation itself already succeeded above regardless of this.
  try {
    const [units, properties, owners, tenants] = await fetchTabs(env, ['Units','Properties','Owners','Tenants']);
    const unit = units.find(u => u.ID === body.unit_id);
    const property = properties.find(p => p.ID === body.property_id);
    const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
    const woLike = { ID: woId, Unit_ID: body.unit_id||'', Property_ID: body.property_id||'', Tenant_ID: body.tenant_id||'', Trade: body.trade||'', Description: body.description||'', Created_Date: now };
    // Owner Received: ONLY for tenant-portal-submitted WOs (Type='tenant') — Brett was
    // explicit an admin-created manual WO should NOT trigger this (the admin creating it
    // already knows about it; a tenant-submitted request is the one case the owner genuinely
    // wasn't already aware of). Fires immediately — unlike the tenant-side message below,
    // there's no "might get bumped by Assigned soon" concern on the owner side.
    if ((body.type || '') === 'tenant' && owner?.Phone && property) {
      const notify = await shouldNotifyOwner(env, woLike, 'Received');
      if (notify) {
        const msg = `Hi ${owner.First_Name}, we've received a new ${woLike.Trade || 'General'} request from your tenant at ${propUnitText(property, unit)}: ${woLike.Description || '(no description)'}. We'll follow up once it's scheduled. Ref: ${woId}.`;
        const r = await smsGatedSend(env, { wo_id: woId, message_type: 'owner_job_received', recipient_type: 'owner', owner, property, message_body: msg });
        if (r.sent) await updateWOFields(env, woId, { Owner_Notified: 'TRUE' });
      }
    }
    // Tenant Received: separate from tenant_job_assigned — tells the tenant only that the
    // request landed and is pending assignment/scheduling. Not scoped to Type='tenant' (unlike
    // Owner Received above) — applies to any new WO with a notifiable tenant, same scope the
    // existing Tenant_Notify_Created toggle already covers. Delayed 1h so a fast assignment can
    // supersede/bump it (see the tenant_job_received check in processPendingNotifications)
    // instead of the tenant getting "we got it" immediately followed by "you're assigned".
    // CAP-036 #21: every active tenant in the unit, not just one.
    const tenantNotifyCreated = body.tenant_notify_created !== false && body.tenant_notify_created !== 'FALSE';
    if (tenantNotifyCreated) for (const tenant of tenantsForDispatch(tenants, unit, woLike)) {
      if (!isTenantNotifiable(tenant, woLike)) continue;
      const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'your unit';
      const msg = `Hi ${tenant.First_Name}, we've received your ${woLike.Trade || 'General'} request at ${address} and it's pending assignment and scheduling. We'll be in touch. Ref: ${woId}. ${TENANT_STOP_NOTE}`;
      const sendAfter = new Date(Date.now() + 1*3600000).toISOString();
      await queueNotification(env, woId, 'tenant_received', tenant.Phone, msg, sendAfter, { message_type: 'tenant_job_received', recipient_type: 'tenant', recipient_id: tenant.ID, property_id: property ? property.ID : '' });
    }
  } catch (e) { /* non-fatal */ }
  try { await logTelemetry(env, { Source:'worker', Job_Type:'wo_create', Skill_Or_Endpoint:'/workorder', Success:'TRUE', Latency_ms: Date.now()-_t0, Notes:`trade=${body.trade||''} type=${body.type||'manual'}` }); } catch(_){}
  return json({ success: true, id: woId });
}

// ── Buildium email → Work Order intake (B-103, Oct 12 2026) ──────────────────────────────────
// Phoenix Estate Rentals (and any future customer on Buildium) posts a work order to Brett as a
// vendor; Buildium emails brett@ from donotreply@managebuilding.com. Two emails arrive per post:
//   1. "New work order: <address>"  — link-only notice. IGNORED (the Apps Script never sends it).
//   2. "<Org>: Work order <n>"      — the DETAILED email (title, address, description, tenant
//                                     contact, entry notes). This is the one we turn into a WO.
// The Apps Script poller (apps-script/buildium-intake/) forwards (1-minute trigger) each detailed email
// here: POST /intake/email {subject, body, from, message_id, received_at}. Auth: narrow INTAKE_TOKEN,
// accepted ONLY for that one path. Behavior (Brett, Oct 12 2026):
//   - create the WO automatically; admin SMS immediately (bypassQuietHours - no waiting until 9am)
//   - one WO per Buildium ref, ever (dedupe on Work_Orders.Owner_WO_Ref + Intake_Queue.Ref_Key)
//   - unit optional (SFH), but multi-unit buildings are supported: a multi-unit property with no
//     / unknown unit in the email is PARKED, never guessed
//   - anything we can't place with certainty (no/ambiguous property, unit problem, parse failure)
//     is PARKED in Intake_Queue + SMS, never turned into a junk WO and never dropped silently
//   - no tenant SMS is sent for intake WOs (tenant_notify_* FALSE); Brett switches them on per WO
// NOTHING FAILS SILENTLY: every outcome writes Ops_Telemetry + an Intake_Queue row, an error returns
// 500 (the poller keeps retrying + emails Brett), and an SMS that did not go out is recorded and
// returned as sms_sent:false (the poller emails Brett on that too).
const INTAKE_TAB = 'Intake_Queue';
const INTAKE_COLS = ['ID','Received_At','Source','Ref_Key','Message_ID','Subject','Status','Reason','WO_ID','Property_ID','Unit_ID','Address_Raw','Title','SMS_Status','Parsed_JSON','Raw_Body','Processed_At'];
let _intakeTabReady = false;
const INTAKE_MAX_BODY = 60000;   // a real Buildium email is ~3-8KB; anything bigger is parked, never run through the parsers

// Plain-body / HTML / markdown-table renderings of the same email all flatten to one line of
// single-spaced text so the field regexes below don't care how Gmail laid it out.
function intakeFlatten(s) {
  return String(s == null ? '' : s).slice(0, INTAKE_MAX_BODY)
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]{0,500}>/g, ' ')
    .replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ')
    .replace(/&lt;|&gt;/g, ' ').replace(/&amp;/g, '&')   // never turn entities back into < > (would re-create tags)
    .replace(/\[\]\([^)]{0,500}\)/g, ' ')
    .replace(/[| ]/g, ' ')
    .replace(/-{3,}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function intakeBetween(t, startRe, endRe) {
  const s = startRe.exec(t);
  if (!s) return null;
  const rest = t.slice(s.index + s[0].length);
  // pad with a leading space so an end marker that sits right at the start of `rest` (an empty
  // field, e.g. "Entry notes" immediately followed by "Entry contacts") still terminates it
  const e = endRe ? endRe.exec(' ' + rest) : null;
  return (e ? rest.slice(0, Math.max(0, e.index - 1)) : rest).trim();
}

// "Renita Howell, Tenant * (410) 556-7166 * (443) 810-0081 * a@b.com" -> [{name, role, phones[], emails[]}]
// A second contact follows the first one's last email/phone with only a space, so a '*' is inserted there.
function intakeParseContacts(raw) {
  let s = String(raw || '').trim();
  if (!s || /^--+$/.test(s)) return [];
  s = s.slice(0, 3000);
  s = s.replace(/([A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]{1,63}(?:\.[A-Za-z0-9-]{1,63}){1,4}|\d{4})\s+(?=[A-Z][a-z])/g, '$1 * ');
  // Plain-text (getPlainBody) layout has no '*' separators: split after a role word, and between back-to-back phones / phone→email.
  s = s.replace(/(,\s*(?:Tenant|Owner|Resident|Occupant|Other|Manager))\s+(?=\S)/g, '$1 * ');
  s = s.replace(/(\d{4})\s+(?=\(?\d{3}\)?[\s.-]{0,3}\d{3}[\s.-]{0,3}\d{4}|[A-Za-z0-9._%+-]{1,64}@)/g, '$1 * ');
  const ROLE = /^(.+?),\s*(Tenant|Owner|Resident|Occupant|Other|Manager)$/;
  const out = []; let cur = null;
  const start = (name, role) => { cur = { name, role, phones: [], emails: [] }; out.push(cur); };
  for (const tok0 of s.split('*')) {
    const tok = tok0.trim(); if (!tok) continue;
    const rm = ROLE.exec(tok);
    if (rm) { start(rm[1].trim(), rm[2]); continue; }
    const emails = tok.match(/[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]{1,63}(?:\.[A-Za-z0-9-]{1,63}){1,4}/g) || [];
    const phones = (tok.match(/\(?\d{3}\)?[\s.-]{0,3}\d{3}[\s.-]{0,3}\d{4}/g) || []).map(x => x.trim());
    if (emails.length || phones.length) { if (!cur) start('', ''); cur.emails.push(...emails); cur.phones.push(...phones); continue; }
    start(tok, '');
  }
  return out.filter(c => c.name || c.phones.length || c.emails.length).slice(0, 5).map(c => ({ ...c, name: c.name.slice(0, 80), phones: c.phones.slice(0, 4), emails: c.emails.slice(0, 4) }));
}

function parseBuildiumEmail(subject, rawText) {
  const t = intakeFlatten(rawText);
  const out = { ok: false, errors: [] };
  const subjM = /Work order\s+#?(\d+)/i.exec(String(subject || ''));
  const refM = /Work order\s+#(\d+)(?:-(\d+))?\s*:\s*/i.exec(t);
  if (!refM) { out.errors.push('no "Work order #<n>:" header found in body'); return out; }
  out.ref = refM[1]; out.seq = refM[2] || '1';
  if (subjM && subjM[1] !== out.ref) out.errors.push('subject WO number ' + subjM[1] + ' != body WO number ' + out.ref);
  out.ref_key = out.ref + '-' + out.seq;
  const afterRef = t.slice(refM.index + refM[0].length);
  const jdIdx = afterRef.search(/\sJob description\s/i);
  const secIdx = afterRef.search(/\s(?:Contact and scheduling information|Entry details|Parts and labor details|Vendor information)\s/i);
  const headEnd = jdIdx >= 0 ? jdIdx : (secIdx >= 0 ? secIdx : afterRef.length);
  const head = afterRef.slice(0, headEnd);
  const locIdx = head.lastIndexOf(' Location ');
  if (locIdx < 0) { out.errors.push('no "Location" found'); out.title = head.trim(); return out; }
  out.title = head.slice(0, locIdx).trim().slice(0, 200);
  out.address_raw = head.slice(locIdx + ' Location '.length).trim().slice(0, 200);
  out.description = jdIdx >= 0
    ? (intakeBetween(afterRef.slice(jdIdx), /^\sJob description\s+/i, /\s(?:Contact and scheduling information|Entry details|Parts and labor details|Vendor information)\s/i) || '')
    : '';
  out.description = out.description.slice(0, 1500);
  out.entry_details = (intakeBetween(t, /Entry details\s+/i, /\s+Entry notes\b/i) || '').slice(0, 300);
  out.entry_notes = (intakeBetween(t, /Entry notes\s*/i, /\s+Entry contacts\b/i) || '').slice(0, 1000);
  out.contacts = intakeParseContacts(intakeBetween(t, /Entry contacts\s*/i, /\s+(?:Parts and labor details|Vendor information)\b/i) || '');
  const orgM = /Work order from\s+(.+?)\s+\d{1,2}\/\d{1,2}\/\d{4}/i.exec(t) || /^(.*?):\s*Work order/i.exec(String(subject || ''));
  out.org = orgM ? orgM[1].trim() : '';
  if (!out.title) out.errors.push('empty title');
  if (!out.address_raw) out.errors.push('empty location');
  out.ok = out.errors.length === 0;
  return out;
}

// Buildium location -> {norm, tokens}. Strips ", MD 21206" so what is left is
// "<street address> [- <unit>] [<city>]" in qbNormAddress's folded form (Avenue->ave, North->n ...).
function intakeNormLocation(addrRaw) {
  let s = String(addrRaw || '').slice(0, 200).replace(/\s+/g, ' ').trim();
  s = s.replace(/#\s*([A-Za-z0-9]+)/g, ' apt $1 ');   // "#2F" => "apt 2f"
  s = s.replace(/[,\s]+[A-Za-z]{2}\s*\d{5}(?:-\d{4})?\s*$/, '').replace(/[,\s]+\d{5}(?:-\d{4})?\s*$/, '').replace(/,\s*[A-Za-z]{2}\s*$/, '');
  return qbNormAddress(s);
}

// Active properties whose address is a prefix of the Buildium location and whose leftover is only
// an optional unit marker ("- 1", "apt 3", bare "-") and/or a city. Returns {matches:[{property, unit_raw}]}.
function intakeMatchProperty(addrRaw, properties) {
  const E = intakeNormLocation(addrRaw);
  const matches = [];
  if (!E) return { matches, norm: E };
  for (const p of properties) {
    if (String(p.Active || '').toUpperCase() === 'FALSE') continue;
    const P = qbNormAddress(p.Address);
    if (!P) continue;
    if (E !== P && !E.startsWith(P + ' ')) continue;
    let rest = E.slice(P.length).trim();
    // Only THIS property's own city (or Baltimore when none is on file) may trail the street address.
    const cityBase = qbNormAddress(p.City).split(' ').filter(Boolean);
    const cityWords = new Set(cityBase.concat(['md', 'maryland'], cityBase.length ? [] : ['baltimore']));
    let unit = '';
    const um = /^(?:-|apt|ste|bldg|fl)(?:\s+([a-z0-9]+))?(?=\s|$)/.exec(rest);
    if (um) {
      if (um[1] && !cityWords.has(um[1])) { unit = um[1]; rest = rest.slice(um[0].length).trim(); }
      else { rest = rest.slice(um[0].length).trim(); }
    }
    if (rest && !rest.split(' ').every(w => cityWords.has(w))) continue;   // leftover must be ONLY this property's city/state words ("Rear", "Annex", another city => park)
    matches.push({ property: p, unit_raw: unit });
  }
  return { matches, norm: E };
}

// Pick the Unit row. SFH / single-unit property: the sole unit, whatever the email says (Buildium
// appends "- 1" to houses). Multi-unit: the email's unit must match exactly one Unit_Label.
function intakeResolveUnit(property, unitRaw, units) {
  const pu = (units || []).filter(u => String(u.Property_ID) === String(property.ID) && String(u.Active || '').toUpperCase() !== 'FALSE');
  const multi = pu.length > 1 || (String(property.Type || '').toLowerCase() === 'multi' && parseInt(property.Unit_Count || '1', 10) > 1);
  if (!multi) {
    // Buildium tags houses "- 1". Anything else (apt 2, rear...) on a single-unit property is a mismatch: park, don't guess.
    const w = String(unitRaw || '') ? qbNormAddress(unitRaw).replace(/^(?:apt|unit) /, '') : '';
    const sole = pu.length === 1 ? qbNormAddress(pu[0].Unit_Label).replace(/^(?:apt|unit) /, '') : '';
    if (w && w !== '1' && w !== sole) return { ok: false, reason: 'unit_no_match', detail: 'email unit "' + unitRaw + '" but this is a single-unit property' + (sole ? ' (unit "' + pu[0].Unit_Label + '")' : '') };
    return { ok: true, unit_id: pu.length === 1 ? String(pu[0].ID) : '', unit_label: pu.length === 1 ? String(pu[0].Unit_Label || '') : '' };
  }
  const labels = pu.map(u => u.Unit_Label).join(', ');
  if (!pu.length) return { ok: false, reason: 'no_unit_records', detail: 'multi-unit property has no Units rows' };
  if (!unitRaw) return { ok: false, reason: 'unit_required', detail: 'multi-unit property (' + labels + ') but the email names no unit' };
  const want = qbNormAddress(unitRaw).replace(/^(?:apt|unit) /, '');
  const m = pu.filter(u => qbNormAddress(u.Unit_Label).replace(/^(?:apt|unit) /, '') === want);
  if (m.length === 1) return { ok: true, unit_id: String(m[0].ID), unit_label: String(m[0].Unit_Label || '') };
  return { ok: false, reason: m.length ? 'unit_ambiguous' : 'unit_no_match', detail: 'email unit "' + unitRaw + '" vs ' + labels };
}

// Existing active tenant of that unit (or of the property when unit-less) whose phone or email
// matches a Buildium contact. Exactly one match -> its ID; otherwise '' (contact stays on the WO).
function intakeMatchTenant(contacts, tenants, propertyId, unitId) {
  const last10 = s => String(s || '').replace(/\D/g, '').slice(-10);
  const phones = new Set(), emails = new Set();
  for (const c of contacts || []) { c.phones.forEach(p => phones.add(last10(p))); c.emails.forEach(e => emails.add(e.toLowerCase())); }
  const pool = (tenants || []).filter(t => String(t.Active || '').toUpperCase() !== 'FALSE' &&
    (unitId ? String(t.Unit_ID) === String(unitId) : String(t.Property_ID) === String(propertyId)));
  const hit = pool.filter(t => (last10(t.Phone) && phones.has(last10(t.Phone))) || (t.Email && emails.has(String(t.Email).trim().toLowerCase())));
  return hit.length === 1 ? String(hit[0].ID) : '';
}

// Reads only. Shared by the real handler, dry_run and the HUB_TEST_TOKEN guard.
async function intakeAnalyze(env, subject, text, override) {
  const parsed = parseBuildiumEmail(subject, text);
  const res = { parsed, status: 'parked', reason: '', detail: '' };
  if (!parsed.ok) { res.reason = 'parse_failed'; res.detail = parsed.errors.join('; '); return res; }
  const [properties, units, tenants] = await fetchTabs(env, ['Properties', 'Units', 'Tenants']);
  let property, unitRaw = '';
  if (override && override.property_id) {
    property = properties.find(p => String(p.ID) === String(override.property_id));
    if (!property) { res.reason = 'override_property_not_found'; res.detail = 'property_id ' + override.property_id; return res; }
    unitRaw = '';
  } else {
    const m = intakeMatchProperty(parsed.address_raw, properties);
    if (m.matches.length === 0) { res.reason = 'no_property_match'; res.detail = 'no active property matches "' + parsed.address_raw + '" (normalized: ' + m.norm + ')'; return res; }
    if (m.matches.length > 1) { res.reason = 'ambiguous_property'; res.detail = m.matches.map(x => x.property.ID + ' ' + x.property.Address).join(' | '); return res; }
    property = m.matches[0].property; unitRaw = m.matches[0].unit_raw;
  }
  res.property = property;
  if (override && override.unit_id) {
    const u = units.find(x => String(x.ID) === String(override.unit_id) && String(x.Property_ID) === String(property.ID));
    if (!u) { res.reason = 'override_unit_not_found'; res.detail = 'unit_id ' + override.unit_id + ' is not on property ' + property.ID; return res; }
    res.unit_id = String(u.ID); res.unit_label = String(u.Unit_Label || '');
  } else {
    const ur = intakeResolveUnit(property, unitRaw, units);
    if (!ur.ok) { res.reason = ur.reason; res.detail = ur.detail; return res; }
    res.unit_id = ur.unit_id; res.unit_label = ur.unit_label;
  }
  res.tenant_id = intakeMatchTenant(parsed.contacts, tenants, property.ID, res.unit_id);
  res.status = 'ok';
  return res;
}

const INTAKE_REASON_TEXT = {
  parse_failed: "couldn't read the email", no_property_match: 'no matching property', ambiguous_property: 'more than one matching property',
  unit_required: 'multi-unit building, no unit in email', unit_no_match: "unit doesn't match", unit_ambiguous: 'unit matches more than one',
  no_unit_records: 'multi-unit property has no units on file', override_property_not_found: 'property not found', override_unit_not_found: 'unit not found',
};

async function intakeEnsureTab(env) {
  if (!_intakeTabReady) { await ensureTab(env, INTAKE_TAB, INTAKE_COLS); _intakeTabReady = true; }
  await ensureColumns(env, INTAKE_TAB, INTAKE_COLS);
}

async function intakeAppendRow(env, row) {
  await intakeEnsureTab(env);
  const res = await addRow(env, INTAKE_TAB, row);
  let j = null; try { j = await res.clone().json(); } catch (_) {}
  if (!res || res.status !== 200 || !j || j.success !== true || !j.id) throw new Error('Intake_Queue row did not land: ' + (j && j.error ? j.error : (res && res.status)));
  const back = (await fetchTab(env, INTAKE_TAB)).find(q => String(q.ID) === String(j.id));
  if (!back || String(back.Message_ID || '') !== String(row.Message_ID || '')) throw new Error('Intake_Queue row ' + j.id + ' did not read back after write');
  return String(j.id);
}

async function intakeSmsAdmin(env, message, woId, property) {
  try {
    const cfg = await fetchConfig(env);
    if (!cfg.admin_phone) return 'FAILED: Config admin_phone not set';
    const r = await smsGatedSend(env, { wo_id: woId || '', message_type: 'admin_intake_alert', recipient_type: 'admin', admin: { Name: 'Admin', Phone: cfg.admin_phone }, property: property || null, message_body: message, bypassQuietHours: true });
    if (r && r.sent) return 'sent';
    if (r && r.send_ok === false) return 'BLOCKED: ' + r.gate_snapshot;
    return 'FAILED: not sent (' + ((r && r.gate_snapshot) || 'unknown') + ')';
  } catch (e) { return 'FAILED: ' + String((e && e.message) || e).slice(0, 150); }
}

async function intakeTelemetry(env, t0, ok, notes) {
  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'intake_email', Skill_Or_Endpoint: '/intake/email', Success: ok ? 'TRUE' : 'FALSE', Latency_ms: Date.now() - t0, Notes: String(notes).slice(0, 480) }); return true; }
  catch (_) { return false; }
}

// The sender must be the ACTUAL address (bare, or the last <...> of "Name <addr>") on managebuilding.com.
// A display name like "donotreply@managebuilding.com" <x@evil.io> must not pass.
function intakeSenderOk(from) {
  return /(?:^|<)\s*[^<>\s@]{1,64}@(?:[a-z0-9-]{1,63}\.){0,4}managebuilding\.com\s*>?\s*$/.test(String(from || '').toLowerCase().slice(0, 300));
}

// POST /intake/email  (INTAKE_TOKEN / WORKER_SECRET)  and  retryRow (POST /intake/retry) share this.
async function intakeEmail(env, body, retryRow) {
  const t0 = Date.now();
  const subject = String(body.subject || ''), text = String(body.body || body.text || ''), msgId = String(body.message_id || '').trim();
  const from = String(body.from || '').toLowerCase(), dry = body.dry_run === true;
  if (!msgId) return json({ error: 'message_id required' }, 400);
  if (!retryRow && !intakeSenderOk(from)) return json({ error: 'sender must be managebuilding.com' }, 400);
  if (!/Work order\s+#?\d+/i.test(subject) || /^\s*New work order/i.test(subject)) return json({ success: true, ignored: true, reason: 'not a detailed work-order email' });
  let stage = 'analyze';
  try {
    const a = text.length > INTAKE_MAX_BODY
      ? { parsed: { ok: false, errors: ['email body too large (' + text.length + ' chars, max ' + INTAKE_MAX_BODY + ')'] }, status: 'parked', reason: 'parse_failed', detail: 'email body too large (' + text.length + ' chars)' }
      : await intakeAnalyze(env, subject, text, retryRow ? { property_id: body.property_id, unit_id: body.unit_id } : null);
    const p = a.parsed || {};
    const refKey = p.ref_key || '';
    if (dry) return json({ success: true, dry_run: true, status: a.status, reason: a.reason, detail: a.detail, parsed: p, property_id: a.property ? a.property.ID : '', property_address: a.property ? a.property.Address : '', unit_id: a.unit_id || '', unit_label: a.unit_label || '', tenant_id: a.tenant_id || '' });

    // ── dedupe: one outcome per Buildium ref ──
    stage = 'dedupe';
    await intakeEnsureTab(env);
    const refTag = 'Buildium #' + refKey;
    const queue = await fetchTab(env, INTAKE_TAB);
    if (!retryRow) {
      const prior = queue.find(q => (q.Status === 'Created' || q.Status === 'Parked') && ((refKey && q.Ref_Key === refKey) || q.Message_ID === msgId));
      if (prior) return json({ success: true, duplicate: true, ref_key: refKey, status: prior.Status, wo_id: prior.WO_ID || '' });
    }
    let existingWO = null;
    if (refKey && a.status === 'ok') {
      const wos = await fetchTab(env, 'Work_Orders');
      existingWO = wos.find(w => String(w.Owner_WO_Ref || '').trim() === refTag) || null;
    }
    const receivedAt = String(body.received_at || new Date().toISOString());
    const baseRow = { Received_At: receivedAt, Source: 'Buildium', Ref_Key: refKey, Message_ID: msgId, Subject: subject.slice(0, 200), Address_Raw: p.address_raw || '', Title: (p.title || '').slice(0, 200), Parsed_JSON: JSON.stringify(p).slice(0, 45000), Raw_Body: text.slice(0, 45000), Processed_At: new Date().toISOString() };

    // ── parked ──
    if (a.status !== 'ok') {
      stage = 'park';
      const reasonTxt = INTAKE_REASON_TEXT[a.reason] || a.reason;
      let rowId;
      if (retryRow) { rowId = String(retryRow.ID); }
      else { rowId = await intakeAppendRow(env, { ...baseRow, Status: 'Parked', Reason: a.reason + ': ' + a.detail.slice(0, 300), SMS_Status: 'pending' }); }
      const sms = await intakeSmsAdmin(env, `⚠️ Buildium WO ${refKey ? '#' + refKey : '(unreadable)'} from ${p.org || 'Buildium'} NOT created (${reasonTxt}): ${p.title || subject} @ ${p.address_raw || '?'}. Parked in Intake_Queue row ${rowId}.`.slice(0, 480), '', null);
      const upd = await updateRow(env, INTAKE_TAB, rowId, { SMS_Status: sms, Processed_At: new Date().toISOString() });
      const telemetryOk = await intakeTelemetry(env, t0, false, `parked ${refKey} ${a.reason}; sms=${sms}`);
      return json({ success: true, parked: true, reason: a.reason, detail: a.detail, queue_id: rowId, sms_sent: sms === 'sent', sms_status: sms, telemetry_ok: telemetryOk, queue_updated: upd.status === 200 });
    }

    // ── create (or repair a WO that exists without its queue row) ──
    stage = 'create';
    let woId, repaired = false;
    if (existingWO) { woId = existingWO.ID; repaired = true; }
    else {
      await ensureColumns(env, 'Work_Orders', ['Source', 'Intake_Message_ID']);
      const c0 = p.contacts[0] || {};
      const contactLine = p.contacts.map(c => [c.name && (c.name + (c.role ? ' (' + c.role + ')' : '')), c.phones.join(', '), c.emails.join(', ')].filter(Boolean).join(' ')).join(' | ');
      const notes = [
        `Source: Buildium email - ${p.org || 'Buildium'} - WO #${refKey}`,
        p.entry_details || p.entry_notes ? `Entry: ${[p.entry_details, p.entry_notes].filter(Boolean).join(' | ')}` : '',
        contactLine ? `Contact (from Buildium): ${contactLine}` : '',
        `Buildium location: ${p.address_raw}`,
      ].filter(Boolean).join('\n');
      const woBody = {
        property_id: a.property.ID, unit_id: a.unit_id || '', tenant_id: a.tenant_id || '', type: 'manual', trade: '', priority: 'normal',
        description: (p.title + (p.description ? ' - ' + p.description : '')).slice(0, 1500),
        owner_wo_ref: refTag, wo_contact_name: c0.name || '', wo_contact_phone: c0.phones && c0.phones[0] ? normalizePhone(c0.phones[0]) : '',
        tenant_notify_created: false, tenant_notify_updates: false, created_by: 'buildium-email', notes,
      };
      const cr = await createWorkOrder(env, woBody);
      const cj = await cr.json();
      if (cr.status !== 200 || !cj || cj.success !== true || !cj.id) throw new Error('createWorkOrder failed: ' + JSON.stringify(cj).slice(0, 200));
      woId = cj.id;
      if (cj.duplicate) throw new Error(`createWorkOrder returned duplicate ${woId} for ${refKey} - a different WO with an identical signature was created within 60s`);
      await updateWOFields(env, woId, { Source: 'Buildium email', Intake_Message_ID: msgId });
    }
    // read-back: the WO must really be there with our ref, and our provenance columns must have landed
    stage = 'verify';
    const wosAfter = (await sheetsRequest(env, 'GET', '/values/Work_Orders')).values || [];
    const hdr = wosAfter[0] || [], hc = n => hdr.indexOf(n);
    const iId = hc('ID'), iRef = hc('Owner_WO_Ref'), iSrc = hc('Source'), iMid = hc('Intake_Message_ID');
    if (iId < 0 || iRef < 0) throw new Error('verify failed: Work_Orders is missing its ID or Owner_WO_Ref column');
    const row = wosAfter.slice(1).find(r => String(r[iId]) === String(woId));
    if (!row || String(row[iRef] || '').trim() !== refTag) throw new Error(`verify failed: ${woId} not found with Owner_WO_Ref "${refTag}" after create`);
    if (!repaired && (iSrc < 0 || iMid < 0 || String(row[iSrc] || '') !== 'Buildium email' || String(row[iMid] || '') !== msgId)) throw new Error(`verify failed: ${woId} Source / Intake_Message_ID columns did not save`);

    stage = 'notify';
    const addr = a.property.Address + (a.unit_label ? ' ' + formatUnitLabel(a.unit_label) : '');
    const who = (p.contacts[0] && p.contacts[0].name) ? ` Contact: ${p.contacts[0].name}${p.contacts[0].phones[0] ? ' ' + p.contacts[0].phones[0] : ''}.` : '';
    const sms = await intakeSmsAdmin(env, `📥 New WO ${woId} from ${p.org || 'Buildium'} (#${refKey}): ${p.title} @ ${addr}.${who}${repaired ? ' (recovered after an interrupted run)' : ''}`.slice(0, 480), woId, a.property);
    stage = 'queue-row';
    let rowId;
    if (retryRow) {
      rowId = String(retryRow.ID);
      const u = await updateRow(env, INTAKE_TAB, rowId, { Status: 'Created', Reason: '', WO_ID: woId, Property_ID: a.property.ID, Unit_ID: a.unit_id || '', SMS_Status: sms, Processed_At: new Date().toISOString() });
      if (u.status !== 200) throw new Error('Intake_Queue retry row update failed');
    } else {
      rowId = await intakeAppendRow(env, { ...baseRow, Status: 'Created', Reason: repaired ? 'recovered existing WO' : '', WO_ID: woId, Property_ID: a.property.ID, Unit_ID: a.unit_id || '', SMS_Status: sms });
    }
    const telemetryOk = await intakeTelemetry(env, t0, sms === 'sent', `created ${woId} from ${refKey}; sms=${sms}${repaired ? '; repaired' : ''}`);
    return json({ success: true, created: true, wo_id: woId, ref_key: refKey, property_id: a.property.ID, unit_id: a.unit_id || '', tenant_id: a.tenant_id || '', queue_id: rowId, sms_sent: sms === 'sent', sms_status: sms, repaired, telemetry_ok: telemetryOk });
  } catch (e) {
    const msg = String((e && e.message) || e);
    const telOk = await intakeTelemetry(env, t0, false, `error at ${stage}: ${msg}`);
    let alertFailed = telOk ? '' : 'telemetry row not written';
    // One alert SMS + one Error row per message (the poller retries every minute; don't spam).
    try {
      await intakeEnsureTab(env);
      const prior = (await fetchTab(env, INTAKE_TAB)).filter(q => q.Message_ID === msgId && q.Status === 'Error');
      if (!prior.length && !dry) {
        const sms = await intakeSmsAdmin(env, `🔴 Buildium email intake error (${stage}): ${msg}`.slice(0, 300), '', null);
        await intakeAppendRow(env, { Received_At: String(body.received_at || ''), Source: 'Buildium', Message_ID: msgId, Subject: subject.slice(0, 200), Status: 'Error', Reason: `${stage}: ${msg}`.slice(0, 400), SMS_Status: sms, Raw_Body: text.slice(0, 45000), Processed_At: new Date().toISOString() });
      }
    } catch (e2) { alertFailed = (alertFailed ? alertFailed + '; ' : '') + 'could not write Error row / alert SMS: ' + String((e2 && e2.message) || e2).slice(0, 200); }
    return json({ success: false, error: msg, stage, alert_failed: alertFailed }, 500);
  }
}

// POST /intake/retry {id, property_id?, unit_id?}  (admin) - re-run a Parked / Error row from its stored
// raw email, optionally forcing the property/unit (Brett's manual "it's this one").
async function intakeRetry(env, body) {
  await intakeEnsureTab(env);
  const row = (await fetchTab(env, INTAKE_TAB)).find(q => String(q.ID) === String(body && body.id));
  if (!row) return json({ error: 'Intake_Queue row not found: ' + (body && body.id) }, 404);
  if (row.Status === 'Created') return json({ error: 'row ' + row.ID + ' already Created as ' + row.WO_ID }, 409);
  if (!row.Raw_Body) return json({ error: 'row has no stored email body' }, 422);
  return await intakeEmail(env, { subject: row.Subject, body: row.Raw_Body, message_id: row.Message_ID, received_at: row.Received_At, property_id: body.property_id, unit_id: body.unit_id }, row);
}

// GET /intake-queue - newest first, without the (large) raw bodies.
async function intakeQueueList(env) {
  let all;
  try { all = await fetchTab(env, INTAKE_TAB); }
  catch (e) { if (isMissingTabError(e)) return json([]); throw e; }   // GET never creates the tab
  return json(all.map(({ Raw_Body, Parsed_JSON, ...rest }) => rest).reverse());
}

// POST /workorder/self-serve { vendor_id, property_id, trade?, description, approval_source,
//   approval_note? }
// "Log a One-Off Job" (Sep 24 2026 build brief §4b) — a thin wrapper around createWorkOrder
// for a vendor with Vendors.Can_Create_Own_WO='TRUE'. Deliberately NOT property-restricted
// (§4a: "it's going to be a one-off system") — any active property is fair game, unlike the
// billing flow's Billing_Property_Access allow-list. The one hard requirement is the
// Approval_Source attestation: this is the ONLY substitute for Brett originating the WO
// himself, so it is validated server-side and never trusted from the client alone.
async function workorderSelfServe(env, body) {
  const vendorId = String(body.vendor_id || '').trim();
  const propertyId = String(body.property_id || '').trim();
  const description = String(body.description || '').trim();
  if (!vendorId) return json({ error: 'vendor_id required' }, 400);
  if (!propertyId) return json({ error: 'property_id required' }, 400);
  if (!description) return json({ error: 'description required' }, 400);

  const approval = validateApprovalSource(body.approval_source, body.approval_note);
  if (!approval.ok) return json({ error: approval.error }, 400);

  const [vendors, properties] = await fetchTabs(env, ['Vendors', 'Properties']);
  const vendor = vendors.find(v => String(v.ID) === vendorId);
  if (!vendor) return json({ error: 'Vendor not found' }, 404);
  if (String(vendor.Can_Create_Own_WO || '').toUpperCase() !== 'TRUE') {
    return json({ error: 'This vendor is not enabled for self-serve work orders' }, 403);
  }
  const prop = properties.find(p => String(p.ID) === propertyId && p.Active !== 'FALSE');
  if (!prop) return json({ error: 'Property not found or inactive' }, 404);

  await ensureColumns(env, 'Work_Orders', ['Created_By_Vendor', 'Approval_Source', 'Approval_Note']);

  // createWorkOrder itself always sets Vendor_ID to blank on create (assignment is a separate
  // step everywhere in this app) — the vendor is assigned to themselves via the normal
  // assignVendor() chokepoint right after, exactly like any other WO, so this never bypasses
  // that pipeline's own SMS/notification/audit side effects.
  const createRes = await createWorkOrder(env, {
    property_id: propertyId, trade: vendor.Trade || '', description,
    priority: 'normal', type: 'vendor_self_serve', created_by: 'vendor:' + vendorId,
    created_by_vendor: 'TRUE', approval_source: approval.source, approval_note: approval.note,
  });
  let created = null;
  try { created = await createRes.clone().json(); } catch (e) { return createRes; }
  if (!created || created.error) return createRes;
  if (created.duplicate) return json(created);

  // Server-side, never a client-supplied vendor id (same class of hardening as the Sep 16
  // 2026 tenant-submission fix) — the vendor is ALWAYS assigned to themselves, never anyone else.
  try { await assignVendor(env, { wo_id: created.id, vendor_id: vendorId, notify: false }); }
  catch (e) { /* WO exists even if the self-assign step fails; Brett can assign it manually */ }

  return json({ success: true, id: created.id });
}

// ══════════════════════════════════════════════════════════════
//  VENDOR ADDITIONAL WORK (Sep 30 2026) — context/VENDOR_ADDITIONAL_WORK_BUILD_BRIEF_v1.0.md
// ══════════════════════════════════════════════════════════════
// A vendor on an open, NON-estimate job finds something else. It becomes a CHILD work order
// (Type 'addon', Parent_WO_ID = the job) carrying ONE normal Estimates row, kept separate from the
// parent's own estimate. Two phases so photos can be required server-side:
//   1. POST /wo/additional-work/start   -> creates a DRAFT child (hidden: Voided=TRUE + Addon_Status='Draft')
//   2. vendor uploads photos against child_wo_id (/create-upload-session + /log-attachment, addon_item=<index>)
//   3. POST /wo/additional-work/submit  -> every item needs >=1 photo, then estimate v1 + un-hide the child
// plus /withdraw (vendor), GET /wo/additional-work (list), POST /wo/additional-work/owner-notice (admin,
// information-only, preview-first). Approve / Needs Info / Decline / push-to-scope are the EXISTING
// child-keyed /estimate/* and /wo/push-to-scope routes. The parent's own Estimates / Current_Estimate /
// Approval_Stage are never touched.
const ADDON_WO_COLUMNS = ['Parent_WO_ID', 'Addon_Status', 'Addon_Tenant_Mentioned', 'Addon_Items_JSON', 'Addon_Amount', 'Addon_Owner_Notified_Date'];
const ADDON_MAX_ITEMS = 20;
const ADDON_PHOTO_TYPES = ['before', 'photo'];
const ADDON_PARENT_BLOCKED_STATUSES = WOStatus.sets.ADDON_PARENT_BLOCKED;

// Draft children are hidden everywhere a normal WO list reads (see getWorkOrdersList / hubBootstrap /
// vendorWorkorders / ownerWorkorders). Belt and braces: a draft is ALSO Voided=TRUE, which every other
// list, the vendor nudges and nearby-WOs already skip.
function addonIsDraft(w) { return String((w && w.Addon_Status) || '') === 'Draft'; }
function addonIsChild(w) { return !!(w && String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim()); }

// Which vendor is acting. A vendor SESSION is always its own id (body.vendor_id is never trusted);
// admin / staging test token callers act as the WO's assigned vendor.
function addonActingVendor(callerRole, callerSessionId, wo) {
  return callerRole === 'vendor' ? String(callerSessionId || '') : String((wo && wo.Vendor_ID) || '');
}

// PURE — validates the start body. Returns { ok, error, items, amount }.
function addonValidateStart(body) {
  const rawItems = body && body.items;
  if (!Array.isArray(rawItems) || rawItems.length < 1) return { ok: false, error: 'items required (1-' + ADDON_MAX_ITEMS + ')' };
  if (rawItems.length > ADDON_MAX_ITEMS) return { ok: false, error: 'At most ' + ADDON_MAX_ITEMS + ' items per submission' };
  const items = [];
  for (let i = 0; i < rawItems.length; i++) {
    const d = String((rawItems[i] && rawItems[i].desc) == null ? '' : rawItems[i].desc).trim();
    if (!d) return { ok: false, error: 'Item ' + (i + 1) + ' needs a description' };
    items.push({ index: i, desc: d.slice(0, 500) });
  }
  const amount = Number(body && body.amount);
  if (!Number.isFinite(amount) || amount <= 0) return { ok: false, error: 'amount must be a number greater than 0' };
  if (amount > 1000000) return { ok: false, error: 'amount looks too large' };
  return { ok: true, items, amount: +amount.toFixed(2) };
}

// PURE — which item indexes still lack a photo. photoRows = this child's Attachments rows.
function addonMissingPhotoItems(items, photoRows) {
  const have = new Set();
  (Array.isArray(photoRows) ? photoRows : []).forEach(a => {
    if (!a || a.Active === 'FALSE') return;
    if (!ADDON_PHOTO_TYPES.includes(String(a.File_Type || '').toLowerCase())) return;
    const ix = String(a.Addon_Item == null ? '' : a.Addon_Item).trim();
    if (ix !== '') have.add(ix);
  });
  return (Array.isArray(items) ? items : []).map(it => it.index).filter(ix => !have.has(String(ix)));
}

function addonParseItems(child) { try { const a = JSON.parse(child.Addon_Items_JSON || '[]'); return Array.isArray(a) ? a : []; } catch (_) { return []; } }
function addonLatestEstimate(estimates, woId) {
  const v = (estimates || []).filter(e => e.WO_ID === woId && e.Active !== 'FALSE');
  return v.length ? v.reduce((a, b) => (parseInt(a.Version) || 0) > (parseInt(b.Version) || 0) ? a : b) : null;
}

// POST /wo/additional-work/start { parent_wo_id, items:[{desc}], amount, tenant_mentioned? }
async function addonStart(env, body, callerRole, callerSessionId) {
  const parentId = String((body && body.parent_wo_id) || '').trim();
  if (!parentId) return json({ error: 'parent_wo_id required' }, 400);
  const v = addonValidateStart(body);
  if (!v.ok) return json({ error: v.error }, 400);
  const workorders = await fetchTab(env, 'Work_Orders');
  const parent = findWO(workorders, parentId);
  if (!parent) return json({ error: 'Work order not found' }, 404);
  const vendorId = addonActingVendor(callerRole, callerSessionId, parent);
  if (!vendorId || String(parent.Vendor_ID || '') !== vendorId) return json({ error: 'This work order is not assigned to you' }, 403);
  if (parent.Voided === 'TRUE') return json({ error: 'This work order is voided' }, 400);
  if (ADDON_PARENT_BLOCKED_STATUSES.includes(String(parent.Status || ''))) return json({ error: 'This work order is ' + parent.Status + ' — additional work cannot be added' }, 400);
  if (String(parent.Type || '') === 'estimate') return json({ error: 'This job is a request for an estimate — add the items to its existing estimate instead', use_estimate_editor: true }, 400);
  if (String(parent.Type || '') === 'addon' || String(parent.Parent_WO_ID || '').trim()) return json({ error: 'Additional work cannot be added to additional work' }, 400);

  await ensureColumns(env, 'Work_Orders', ADDON_WO_COLUMNS.concat(WO_VOID_COLUMNS));
  const description = ('Additional work for ' + parentId + ': ' + v.items.map((it, i) => (i + 1) + ') ' + it.desc).join('; ')).slice(0, 1500);
  // Never notifies anyone: no tenant texts/visibility, no owner texts, vendor assigned with notify:false.
  const createRes = await createWorkOrder(env, {
    property_id: parent.Property_ID || '', unit_id: parent.Unit_ID || '', trade: parent.Trade || '',
    description, priority: parent.Priority || 'normal', type: 'addon', created_by: 'vendor:' + vendorId,
    parent_wo_id: parentId, tenant_visible: false, tenant_notify_created: false, tenant_notify_updates: false,
    owner_notify_override: 'off',
  });
  let created = null;
  try { created = await createRes.clone().json(); } catch (e) { return createRes; }
  if (!created || created.error) return createRes;
  const childId = created.id;
  if (created.duplicate) {
    // double-tap: hand back the child that already exists
    const existing = findWO(await fetchTab(env, 'Work_Orders'), childId);
    const stored = existing ? addonParseItems(existing) : [];
    return json({ success: true, duplicate: true, child_wo_id: childId, items: (stored.length ? stored : v.items).map(it => ({ index: it.index, desc: it.desc })) });
  }
  try { await assignVendor(env, { wo_id: childId, vendor_id: vendorId, notify: false }); } catch (e) { /* surfaced by the field check below */ }
  await updateWOFields(env, childId, {
    Voided: 'TRUE', Void_Reason: 'Other', Void_Reason_Detail: 'Additional-work draft (not submitted yet)',
    Parent_WO_ID: parentId, Addon_Status: 'Draft',
    Addon_Tenant_Mentioned: (body.tenant_mentioned === true || body.tenant_mentioned === 'TRUE') ? 'TRUE' : 'FALSE',
    Addon_Items_JSON: JSON.stringify(v.items), Addon_Amount: v.amount.toFixed(2),
  });
  return json({ success: true, child_wo_id: childId, items: v.items.map(it => ({ index: it.index, desc: it.desc })) });
}

// POST /wo/additional-work/submit { child_wo_id }
// The amount captured at /start (Work_Orders.Addon_Amount) is the source of truth.
async function addonSubmit(env, body, callerRole, callerSessionId) {
  const childId = String((body && body.child_wo_id) || '').trim();
  if (!childId) return json({ error: 'child_wo_id required' }, 400);
  const [workorders, estimates, attachments] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Estimates'), fetchTab(env, 'Attachments')]);
  const child = findWO(workorders, childId);
  if (!child || !addonIsChild(child)) return json({ error: 'Additional-work job not found' }, 404);
  const vendorId = addonActingVendor(callerRole, callerSessionId, child);
  if (!vendorId || String(child.Vendor_ID || '') !== vendorId) return json({ error: 'This work order is not assigned to you' }, 403);
  const status = String(child.Addon_Status || '');
  const existingEst = addonLatestEstimate(estimates, childId);
  if (status === 'Submitted' && existingEst) {
    return json({ success: true, already_submitted: true, child_wo_id: childId, version: parseInt(existingEst.Version) || 1, subtotal: existingEst.Subtotal || '' });
  }
  if (status === 'Withdrawn') return json({ error: 'This additional work was withdrawn' }, 400);
  if (status !== 'Draft' && status !== 'Submitted') return json({ error: 'This job is not an additional-work draft' }, 400);

  const items = addonParseItems(child);
  if (!items.length) return json({ error: 'Draft has no items' }, 400);
  const missing = addonMissingPhotoItems(items, attachments.filter(a => a.WO_ID === childId));
  if (missing.length) return json({ error: 'Every item needs at least one photo', missing_items: missing }, 400);

  // Amount: the one captured at /start (never re-taken from the submit body).
  let amount = Number(child.Addon_Amount);
  if (!Number.isFinite(amount) || amount <= 0) return json({ error: 'amount missing on this draft' }, 400);
  amount = +amount.toFixed(2);

  if (!existingEst) {
    // addEstimateVersion accepts $0 lines and sums amounts, so the lump sum sits on line 1 and the rest
    // are $0 — Subtotal === amount exactly, every item stays individually readable (and translatable).
    const line_items = items.map((it, i) => ({ desc: it.desc, amount: i === 0 ? amount : 0, addon_item: it.index }));
    const estRes = await addEstimateVersion(env, { wo_id: childId, vendor_id: vendorId, line_items, created_by: 'vendor', sms_kind: 'Additional work' });
    let est = null; try { est = await estRes.clone().json(); } catch (_) {}
    if (!est || est.error || !est.success) return estRes;
  }
  // Un-hide the child: it is now a normal job awaiting approval.
  await updateWOFields(env, childId, { Voided: 'FALSE', Void_Reason: '', Void_Reason_Detail: '', Addon_Status: 'Submitted' });
  const est2 = addonLatestEstimate(await fetchTab(env, 'Estimates'), childId);
  return json({ success: true, child_wo_id: childId, version: est2 ? (parseInt(est2.Version) || 1) : 1, subtotal: est2 ? est2.Subtotal : amount.toFixed(2) });
}

// POST /wo/additional-work/withdraw { child_wo_id } — vendor, while the estimate is Pending / Needs Info.
async function addonWithdraw(env, body, callerRole, callerSessionId) {
  const childId = String((body && body.child_wo_id) || '').trim();
  if (!childId) return json({ error: 'child_wo_id required' }, 400);
  const [workorders, estimates] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Estimates')]);
  const child = findWO(workorders, childId);
  if (!child || !addonIsChild(child)) return json({ error: 'Additional-work job not found' }, 404);
  const vendorId = addonActingVendor(callerRole, callerSessionId, child);
  if (!vendorId || String(child.Vendor_ID || '') !== vendorId) return json({ error: 'This work order is not assigned to you' }, 403);
  const status = String(child.Addon_Status || '');
  if (status === 'Withdrawn') return json({ success: true, already_withdrawn: true, child_wo_id: childId });
  const est = addonLatestEstimate(estimates, childId);
  if (status === 'Submitted') {
    const es = String((est && est.Status) || 'Pending');
    if (!['Pending', 'Needs Info', ''].includes(es)) return json({ error: 'Too late to withdraw — this was already ' + es }, 400);
  } else if (status !== 'Draft') return json({ error: 'This job is not additional work' }, 400);
  try { await ensureColumns(env, 'Work_Orders', WO_VOID_COLUMNS); } catch (_) {}
  const now = new Date().toISOString();
  await updateWOFields(env, childId, {
    Voided: 'TRUE', Void_Reason: 'Other', Void_Reason_Detail: 'Additional work withdrawn by vendor', Voided_By: 'vendor:' + vendorId, Voided_Date: now,
    Addon_Status: 'Withdrawn',
  });
  if (est && est.ID) { try { await updateRow(env, 'Estimates', est.ID, { Status: 'Withdrawn' }); } catch (_) {} }
  try { await logWOAudit(env, childId, 'vendor:' + vendorId, callerRole === 'vendor' ? 'vendor' : 'admin', 'Addon_Status', status, 'Withdrawn', 'Additional work withdrawn'); } catch (_) {}
  return json({ success: true, child_wo_id: childId });
}

// Photo rows (customer-safe types only) grouped by item index.
function addonPhotosByItem(attachments, childId) {
  const out = {};
  (attachments || []).forEach(a => {
    if (a.WO_ID !== childId || a.Active === 'FALSE') return;
    if (!ADDON_PHOTO_TYPES.includes(String(a.File_Type || '').toLowerCase())) return;
    const ix = String(a.Addon_Item == null ? '' : a.Addon_Item).trim(); if (ix === '') return;
    (out[ix] = out[ix] || []).push({ url: a.Drive_URL || '', file_name: a.File_Name || '', mime_type: a.Mime_Type || '' });
  });
  return out;
}

// GET /wo/additional-work?parent_wo_id= — admin, or the vendor assigned to the parent.
// Without parent_wo_id a VENDOR session gets ALL of its own submitted (non-draft, non-withdrawn) add-ons across every
// parent in ONE call (the portal used to call this once per job card and burned the Sheets read quota). The vendor is
// always the session vendor; nothing from the body/query is trusted. Admin still must name a parent.
async function addonList(env, url, callerRole, callerSessionId) {
  const parentId = String(url.searchParams.get('parent_wo_id') || '').trim();
  const allForVendor = !parentId && callerRole === 'vendor';
  if (!parentId && !allForVendor) return json({ error: 'parent_wo_id required' }, 400);
  const [workorders, estimates, attachments] = await fetchTabs(env, ['Work_Orders', 'Estimates', 'Attachments']);
  let children;
  if (allForVendor) {
    const me = String(callerSessionId || '');
    if (!me) return json({ error: 'Unauthorized' }, 401);
    children = workorders.filter(w => String(w.Vendor_ID || '') === me && String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() && !addonIsDraft(w) && String(w.Addon_Status || '') !== 'Withdrawn');
  } else {
    const parent = findWO(workorders, parentId);
    if (!parent) return json({ error: 'Work order not found' }, 404);
    if (callerRole === 'vendor' && String(parent.Vendor_ID || '') !== String(callerSessionId || '')) return json({ error: 'This work order is not assigned to you' }, 403);
    children = workorders.filter(w => String(w.Parent_WO_ID || '') === parentId && String(w.Type || '') === 'addon' && !addonIsDraft(w));
  }
  const isAdmin = callerRole !== 'vendor';
  const out = children.map(c => {
    const est = addonLatestEstimate(estimates, c.ID);
    const photos = addonPhotosByItem(attachments, c.ID);
    let lines = []; try { lines = JSON.parse((est && est.Line_Items) || '[]'); } catch (_) {}
    const items = addonParseItems(c).map(it => {
      const line = lines.find(l => l && Number(l.addon_item) === it.index) || {};
      const ph = photos[String(it.index)] || [];
      return { index: it.index, desc: it.desc, desc_en: line.desc_en || '', photo_count: ph.length, photos: ph };
    });
    const row = {
      child_wo_id: c.ID, parent_wo_id: String(c.Parent_WO_ID || ''), addon_status: c.Addon_Status || '', status: c.Status || '', approval_stage: c.Approval_Stage || '',
      withdrawn: String(c.Addon_Status || '') === 'Withdrawn', created_date: c.Created_Date || '',
      items, amount: est ? (est.Subtotal || '') : (c.Current_Estimate || ''),
      tenant_mentioned: String(c.Addon_Tenant_Mentioned || '') === 'TRUE',
      estimate: est ? { id: est.ID, version: parseInt(est.Version) || 1, status: est.Status || 'Pending' } : null,
      estimate_status: est ? (est.Status || 'Pending') : 'Pending',
    };
    if (isAdmin) { row.owner_notified = !!String(c.Addon_Owner_Notified_Date || '').trim(); row.owner_notified_date = c.Addon_Owner_Notified_Date || ''; }
    return row;
  }).sort((a, b) => String(a.created_date).localeCompare(String(b.created_date)));
  // success + items + per-row estimate_status are the contract vendor.html / index.html read (withdrawn rows are not listed in `items`).
  return json({ success: true, parent_wo_id: parentId || null, additional_work: out, items: out.filter(r => !r.withdrawn), pending_count: out.filter(r => !r.withdrawn && r.estimate && ['Pending', ''].includes(r.estimate.status)).length });
}

// PURE — the INFORMATION-ONLY owner message. No price, no vendor bill/receipt anywhere. Photo links are
// the per-file Drive URLs of the item photos only (types before/photo, which logAttachment shares
// anyone-with-link) — never a WO folder, because the WO folder also holds the After + Receipts subfolder.
function addonBuildOwnerNotice({ ownerFirst, address, parentId, itemTexts, photoUrls }) {
  const first = String(ownerFirst || '').trim() || 'there';
  const list = (itemTexts || []).filter(Boolean);
  const urls = (photoUrls || []).filter(Boolean);
  const smsUrls = urls.slice(0, 3);
  const more = urls.length - smsUrls.length;
  const sms = 'Hi ' + first + ', while working at ' + address + ' our vendor found something you should know about: ' + list.join('; ') + '.'
    + (smsUrls.length ? ' Photos: ' + smsUrls.join(' ') + (more > 0 ? ' (+' + more + ' more by email)' : '') : '')
    + ' We will follow up on next steps. Ref: ' + parentId + '.';
  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const html = '<p>Hi ' + esc(first) + ',</p><p>While working at <b>' + esc(address) + '</b>, our vendor found the following, which we wanted you to know about:</p><ul>'
    + list.map(t => '<li>' + esc(t) + '</li>').join('') + '</ul>'
    + (urls.length ? '<p>Photos:</p><ul>' + urls.map((u, i) => '<li><a href="' + esc(u) + '">Photo ' + (i + 1) + '</a></li>').join('') + '</ul>' : '')
    + '<p>This is for your information. We will follow up on next steps. Reference: ' + esc(parentId) + '.</p>';
  return { sms, subject: 'Something found at ' + address + ' (Ref ' + parentId + ')', html };
}

// PURE — may the owner EMAIL go out? Same gates as the SMS chokepoint (smsGateDecision kind 'owner': Global + Property + Customer
// toggles) plus the owner's Notify_Method and Test Mode: in Test Mode SMS is redirected to Brett, but an email has no redirect, so a
// real owner is never emailed while Test Mode is on. Returns { ok, reason }.
function addonEmailGate({ cfg, property, owner }) {
  const global = String((cfg && cfg.TWILIO_ENABLED) || '').toUpperCase() === 'TRUE';
  const testMode = String((cfg && cfg.TWILIO_TEST_MODE) || '').toUpperCase() !== 'FALSE';
  const on = v => String(v == null ? '' : v).toUpperCase() !== 'FALSE';
  if (String((owner && owner.Notify_Method) || 'sms') === 'none') return { ok: false, reason: 'owner notification method is none' };
  const g = smsGateDecision({ global, propertyOn: on(property && property.SMS_Enabled), ownerOn: on(owner && owner.SMS_Enabled), kind: 'owner' });
  if (!g.sendOk) return { ok: false, reason: g.gateSnapshot };
  if (testMode) return { ok: false, reason: 'Test Mode is on — no email to a real owner' };
  return { ok: true, reason: '' };
}

// POST /wo/additional-work/owner-notice { child_wo_id, preview?:true, resend? } — ADMIN-ONLY (no ROLE_SCOPES entry).
async function addonOwnerNotice(env, body) {
  const childId = String((body && body.child_wo_id) || '').trim();
  if (!childId) return json({ error: 'child_wo_id required' }, 400);
  const preview = !(body && body.preview === false);
  const [workorders, estimates, attachments, properties, owners, unitsAll] = await fetchTabs(env, ['Work_Orders', 'Estimates', 'Attachments', 'Properties', 'Owners', 'Units']);
  const child = findWO(workorders, childId);
  if (!child || !addonIsChild(child)) return json({ error: 'Additional-work job not found' }, 404);
  const status = String(child.Addon_Status || '');
  if (status !== 'Submitted') return json({ error: 'Only a submitted additional-work item can be shared with the owner' }, 400);
  if (String(child.Voided || '').toUpperCase() === 'TRUE') return json({ error: 'This additional work is voided' }, 400);
  const est = addonLatestEstimate(estimates, childId);
  if (est && String(est.Status || '') === 'Declined') return json({ error: 'This additional work was declined — it is never shown to the owner' }, 400);
  const parent = findWO(workorders, child.Parent_WO_ID) || child;
  const property = properties.find(p => String(p.ID) === String(child.Property_ID)) || null;
  const owner = property ? owners.find(o => String(o.ID) === String(property.Owner_ID)) : null;
  if (!owner) return json({ error: 'No owner found for this property' }, 400);
  let lines = []; try { lines = JSON.parse((est && est.Line_Items) || '[]'); } catch (_) {}
  const photos = addonPhotosByItem(attachments, childId);
  const items = addonParseItems(child);
  const itemTexts = items.map(it => {
    const line = lines.find(l => l && Number(l.addon_item) === it.index) || {};
    return englishOnly(line.desc_en || it.desc);
  });
  const photoUrls = []; items.forEach(it => (photos[String(it.index)] || []).forEach(p => { if (p.url) photoUrls.push(p.url); }));
  const address = propUnitText(property, unitsAll.find(u => String(u.ID) === String(child.Unit_ID || (parent && parent.Unit_ID) || ''))) || 'your property';
  const msg = addonBuildOwnerNotice({ ownerFirst: owner.First_Name, address, parentId: parent.ID, itemTexts, photoUrls });
  const ownerEmail = String(owner.Email || owner.Billing_Email || '').trim();
  const warnings = [];
  if (!photoUrls.length) warnings.push('No photo links found for this item.');
  if (!owner.Phone) warnings.push('Owner has no phone on file — no text will be sent.');
  if (!ownerEmail) warnings.push('Owner has no email on file — no email will be sent.');
  if (String(owner.Notify_Method || 'sms') === 'none') warnings.push('Owner notification method is set to none.');
  if (String(parent.Managed_By || '') === 'Owner') warnings.push('This job is marked owner-managed.');
  let _cfg = {}; try { _cfg = await fetchConfig(env); } catch (_) {}
  const emailGate = addonEmailGate({ cfg: _cfg, property, owner });
  if (!emailGate.ok) warnings.push('Email will NOT be sent: ' + emailGate.reason + '.');
  const already = String(child.Addon_Owner_Notified_Date || '').trim();
  if (already) warnings.push('Owner was already notified on ' + already + '.');
  const recipient = { owner_id: owner.ID, name: ((owner.First_Name || '') + ' ' + (owner.Last_Name || '')).trim() || owner.Company || '', phone: owner.Phone || '', email: ownerEmail };
  if (preview) return json({ preview: true, child_wo_id: childId, parent_wo_id: parent.ID, recipient, sms: { body: msg.sms }, email: { to: ownerEmail, subject: msg.subject, html: msg.html }, photo_links: photoUrls, warnings, already_notified: !!already });
  if (already && !body.resend) return json({ error: 'Owner was already notified on ' + already + ' — pass resend:true to send again', already_notified: true }, 409);

  let smsResult = { sent: false, reason: 'no owner phone' };
  if (owner.Phone) {
    try { smsResult = await smsGatedSend(env, { wo_id: parent.ID, message_type: 'owner_addon_notice', recipient_type: 'owner', owner, property, message_body: msg.sms }); }
    catch (e) { smsResult = { sent: false, reason: String((e && e.message) || e) }; }
  }
  let emailResult = { sent: false, reason: 'no owner email' };
  if (ownerEmail && !emailGate.ok) emailResult = { sent: false, reason: emailGate.reason };
  else if (ownerEmail) {
    try { const _er = await gmailSendEmail(env, { to: ownerEmail, subject: msg.subject, html: msg.html }); emailResult = (_er && _er.sent === false) ? { sent: false, staged: !!_er.staged, reason: _er.note || 'not sent' } : { sent: true }; }
    catch (e) { emailResult = { sent: false, reason: String((e && e.message) || e) }; }
  }
  const anyOut = !!(smsResult && (smsResult.sent || smsResult.held_for_quiet_hours)) || emailResult.sent;
  if (anyOut) { try { await updateWOFields(env, childId, { Addon_Owner_Notified_Date: new Date().toISOString() }); } catch (_) {} }
  try { await logWOAudit(env, childId, 'admin', 'admin', 'Addon_Owner_Notified', '', anyOut ? 'sent' : 'not sent', 'Owner information notice'); } catch (_) {}
  return json({ success: true, sms: { sent: !!(smsResult && smsResult.sent), held_for_quiet_hours: !!(smsResult && smsResult.held_for_quiet_hours), gate_snapshot: (smsResult && (smsResult.gate_snapshot || smsResult.reason)) || '' }, email: emailResult, warnings });
}

async function appendWONotes(env, body) {
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, body.wo_id);
  if (!wo) return json({ error: 'WO not found' }, 404);
  const ts = new Date().toLocaleString('en-US', { timeZone:'America/New_York', month:'short', day:'numeric', hour:'numeric', minute:'2-digit' });
  const prefix = body.author ? `[${ts} — ${body.author}] ` : `[${ts}] `;
  await updateWOFields(env, body.wo_id, { Notes: wo.Notes ? `${wo.Notes}\n${prefix}${body.note}` : `${prefix}${body.note}` });
  return json({ success: true });
}

const WO_VOID_REASONS = ['Duplicate', 'Combined', 'Other'];
const WO_VOID_COLUMNS = ['Voided', 'Void_Reason', 'Void_Reason_Detail', 'Void_Combined_Into_WO_ID', 'Voided_By', 'Voided_Date'];

// Void/Hide — separate from Status. A voided WO keeps whatever Status it had; this only
// controls whether it shows up anywhere. Distinct from Cancelled on purpose (Brett,
// 2026-09-14): Cancelled is a real job that was issued and then called off; Voided is for a
// work order that should never have existed at all (a duplicate create, or one job folded
// into another) — the record stays, it's just gone from every list/search by default.
//
// Does NOT help a same-ID collision (two rows sharing one WO number) — findWO/updateWOFields
// resolve by ID first-match same as everywhere else, so voiding still only ever reaches the
// first of two colliding rows. That class of problem is what the duplicate-submission guard
// in createWorkOrder now prevents at the source; a pre-existing collision needs a manual
// sheet fix, same as WO-1192.
// PURE — Submitted add-on children of parentId that are still alive (estimate Pending / Needs Info / Approved, child not voided).
// Voiding or cancelling the parent while any exist would strand them, so those paths refuse until Brett declines/withdraws them.
function addonLiveChildren(workorders, estimates, parentId) {
  return (workorders || []).filter(w => String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() === String(parentId) &&
    String(w.Addon_Status || '') === 'Submitted' && String(w.Voided || '').toUpperCase() !== 'TRUE').filter(c => {
    const v = (estimates || []).filter(e => String(e.WO_ID) === String(c.ID) && e.Active !== 'FALSE');
    if (!v.length) return false;
    const latest = v.reduce((a, b) => (parseInt(a.Version) || 0) > (parseInt(b.Version) || 0) ? a : b);
    return ['Pending', 'Needs Info', 'Approved', ''].includes(String(latest.Status || ''));
  }).map(c => c.ID);
}
function addonLiveChildrenMessage(ids, parentId, verb) {
  return `${parentId} has additional work still open (${ids.join(', ')}). Decline or withdraw ${ids.length > 1 ? 'those' : 'that'} first, then ${verb} this work order.`;
}
async function woVoid(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const reason = body.reason;
  if (!WO_VOID_REASONS.includes(reason)) return json({ error: `reason must be one of: ${WO_VOID_REASONS.join(', ')}` }, 400);
  const combinedInto = reason === 'Combined' ? (body.combined_into_wo_id || '') : '';
  if (reason === 'Combined' && !combinedInto) return json({ error: 'combined_into_wo_id required when reason is Combined' }, 400);

  try { await ensureColumns(env, 'Work_Orders', WO_VOID_COLUMNS); } catch (_) {}
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, woId);
  if (!wo) return json({ error: 'WO not found' }, 404);
  // Orphan guard (additional work): not for 'Combined' (combine/split keep their own behaviour — known gap).
  if (reason !== 'Combined' && workorders.some(w => String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() === String(woId))) {
    const _live = addonLiveChildren(workorders, await fetchTab(env, 'Estimates'), woId);
    if (_live.length) return json({ error: addonLiveChildrenMessage(_live, woId, 'void'), open_additional_work: _live }, 409);
  }
  if (combinedInto) {
    if (combinedInto === woId) return json({ error: 'Cannot combine a work order into itself' }, 400);
    if (!findWO(workorders, combinedInto)) return json({ error: `Target work order ${combinedInto} not found` }, 404);
  }

  const changedBy = body.updated_by || 'admin', changedByRole = body.updated_by_role || 'admin';
  const now = new Date().toISOString();
  await updateWOFields(env, woId, {
    Voided: 'TRUE', Void_Reason: reason, Void_Reason_Detail: body.detail || '',
    Void_Combined_Into_WO_ID: combinedInto, Voided_By: changedBy, Voided_Date: now,
  });
  await logWOAudit(env, woId, changedBy, changedByRole, 'Voided', 'FALSE', 'TRUE', `${reason}${body.detail ? ': ' + body.detail : ''}${combinedInto ? ' -> ' + combinedInto : ''}`);

  // Combined: copy this WO's Notes onto the surviving WO, same timestamped-prefix convention
  // appendWONotes already uses, so the merge is visible on the record that's actually kept —
  // no data about the voided job's notes is lost, and nothing else (vendor bills, receipts,
  // time entries) moves; those stay attached to their original WO_ID.
  if (combinedInto && wo.Notes) {
    const target = findWO(workorders, combinedInto);
    if (target) {
      const ts = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
      const prefix = `[${ts} — combined from ${woId}] `;
      const merged = target.Notes ? `${target.Notes}\n${prefix}${wo.Notes}` : `${prefix}${wo.Notes}`;
      try { await updateWOFields(env, combinedInto, { Notes: merged }); } catch (e) {}
    }
  }
  return json({ success: true });
}

async function woUnvoid(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, woId);
  if (!wo) return json({ error: 'WO not found' }, 404);
  // Void_Reason/Detail/Combined_Into/Voided_By/Voided_Date are left in place as history
  // (this WO was voided on X for reason Y, then restored on Z) — only the Voided flag itself
  // flips, which is the only thing that actually controls visibility.
  await updateWOFields(env, woId, { Voided: 'FALSE' });
  const changedBy = body.updated_by || 'admin', changedByRole = body.updated_by_role || 'admin';
  await logWOAudit(env, woId, changedBy, changedByRole, 'Voided', 'TRUE', 'FALSE', 'Restored');
  return json({ success: true });
}

// Bulk Void (Sep 23 2026 build — index.html WO bulk-select toolbar, "Void Selected…"). Brett's
// main use case: clearing out old test/junk work orders (duplicate-guard artifacts, manual
// test rows) a handful at a time, without hand-opening each one's own Void modal. This is a
// thin per-WO loop over the real woVoid() (same shape woCombine already uses to fold N WOs
// into one) — it does not reimplement the void/audit-log logic, so a bulk void is byte-for-byte
// identical, per WO, to a manual single Void.
//
// Money-attached guard (Brett, explicit): a WO that already has money on it must be SKIPPED,
// never silently voided — voiding it would hide it from `/workorders` and every WO picker
// while it's still owed money or already billed. "Money attached" is any of:
//   1. a non-blank Work_Orders.Customer_Charge
//   2. a non-blank Work_Orders.QBO_Invoice_Number (already invoiced in QuickBooks)
//   3. a linked, active Vendor_Bills row (Active !== 'FALSE', WO_ID matches) — reviewed or not;
//      even an unreviewed bill means a vendor already submitted charges against this WO.
// Every skip is reported back with its specific reason so Brett can see which WO IDs were
// skipped and why — never a silent drop. WOs that pass the check still go through in the same
// batch as the ones that are skipped.
function woBulkVoidMoneyBlockReason(wo, linkedBill) {
  if (String(wo.Customer_Charge || '').trim()) return `Customer charge on file ($${String(wo.Customer_Charge).trim()})`;
  if (String(wo.QBO_Invoice_Number || '').trim()) return `Already invoiced in QuickBooks (${String(wo.QBO_Invoice_Number).trim()})`;
  if (linkedBill) return `Has a linked vendor bill (${linkedBill.ID}${linkedBill.Status === 'reviewed' ? ', reviewed' : ''})`;
  return null;
}

// POST /wo/bulk-void {ids:[...], reason, detail?, combined_into_wo_id?, updated_by?,
// updated_by_role?} — admin-gated same as /wo/void (not in PUBLIC_PATHS, no ROLE_SCOPES entry).
// `reason` is the same WO_VOID_REASONS enum as the single-WO Void modal, applied to the whole
// batch — not per-WO. If reason is 'Combined', `combined_into_wo_id` is required and is the
// SAME target for every WO in the batch (voiding several stray duplicates into one real WO);
// for combining different WOs into different survivors, use the existing /wo/combine picker
// instead. Returns {success, voided:[ids], skipped:[{id, reason}]} — never throws for an
// individual bad WO, only for a malformed request as a whole.
async function woBulkVoid(env, body) {
  const ids = [...new Set((Array.isArray(body.ids) ? body.ids : []).map(x => String(x || '')).filter(Boolean))];
  if (!ids.length) return json({ error: 'ids required (at least one)' }, 400);
  const reason = body.reason;
  if (!WO_VOID_REASONS.includes(reason)) return json({ error: `reason must be one of: ${WO_VOID_REASONS.join(', ')}` }, 400);
  const combinedInto = reason === 'Combined' ? String(body.combined_into_wo_id || '') : '';
  if (reason === 'Combined' && !combinedInto) return json({ error: 'combined_into_wo_id required when reason is Combined' }, 400);

  try { await ensureColumns(env, 'Work_Orders', WO_VOID_COLUMNS); } catch (_) {}
  const workorders = await fetchTab(env, 'Work_Orders');
  if (combinedInto && !findWO(workorders, combinedInto)) return json({ error: `Target work order ${combinedInto} not found` }, 404);

  // Best-effort — a Vendor_Bills read failure must never block voiding WOs that have no money
  // issue at all; it just means the vendor-bill leg of the money check can't run (Customer_Charge
  // / QBO_Invoice_Number still do), same fail-open posture findRecentDuplicate uses.
  let vendorBills = [];
  try { vendorBills = await fetchTab(env, 'Vendor_Bills'); } catch (e) {}

  const changedBy = body.updated_by || 'admin', changedByRole = body.updated_by_role || 'admin';
  const voided = [], skipped = [];

  for (const id of ids) {
    const wo = findWO(workorders, id);
    if (!wo) { skipped.push({ id, reason: 'Work order not found' }); continue; }
    if (String(wo.Voided || '').toUpperCase() === 'TRUE') { skipped.push({ id, reason: 'Already voided' }); continue; }
    if (combinedInto && id === combinedInto) { skipped.push({ id, reason: 'Cannot combine a work order into itself' }); continue; }
    const linkedBill = vendorBills.find(b => b.Active !== 'FALSE' && String(b.WO_ID) === String(id));
    const moneyReason = woBulkVoidMoneyBlockReason(wo, linkedBill);
    if (moneyReason) { skipped.push({ id, reason: moneyReason }); continue; }
    try {
      const res = await woVoid(env, { wo_id: id, reason, detail: body.detail || '', combined_into_wo_id: combinedInto, updated_by: changedBy, updated_by_role: changedByRole });
      const resBody = await res.json();
      if (resBody && resBody.success) voided.push(id);
      else skipped.push({ id, reason: (resBody && resBody.error) || 'Void failed' });
    } catch (e) { skipped.push({ id, reason: e.message || 'Void failed' }); }
  }

  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_bulk_void', Skill_Or_Endpoint: '/wo/bulk-void', Success: 'TRUE', Notes: `voided=${voided.length} skipped=${skipped.length}` }); } catch (_) {}

  return json({ success: true, voided, skipped, voided_count: voided.length, skipped_count: skipped.length });
}

// Combine (bulk void-into-one, Sep 22 2026 build — index.html bulk-select toolbar; field
// audit Sep 23 2026 after Brett hit two real bugs — see PR description). Only these fields
// are ever compared/reconciled across the selected work orders — each one requires either
// unanimous agreement (silent auto-resolve) or an explicit field_overrides pick when they
// disagree; a real disagreement with no override 409s rather than guessing. Trade and
// Checklist are deliberately excluded from BOTH this list and WO_COMBINE_MERGE_FIELDS below —
// the survivor always keeps its own original Trade/Checklist, no picker, no comparison, no
// merge (Brett, explicit for Trade — every selected WO can have a different Trade and that's
// fine; Checklist follows the same logic because it's a trade-specific structured JSON blob
// that blending across different Trades would corrupt, not free text that's safe to
// concatenate). Money/identity fields (Vendor_ID, Customer_Charge, Deposit_Amount,
// Deposit_Vendor_ID, Scope_ID) are here rather than in WO_COMBINE_MERGE_FIELDS on purpose —
// an auto-pick could produce a real billing/assignment error, so they always force an
// explicit choice, never a silent default.
const WO_COMBINE_RECONCILE_FIELDS = [
  'Managed_By', 'Vendor_ID', 'Scheduled_Date', 'Scheduled_Window', 'Priority', 'Status',
  'WO_Contact_Name', 'WO_Contact_Phone', 'Customer_Charge', 'Deposit_Amount',
  'Deposit_Vendor_ID', 'Scope_ID', 'Tenant_Visible',
];

// Free-text fields that are NEVER a conflict — every selected WO's own value (if non-blank)
// is unconditionally concatenated onto the survivor's, same "nothing lost" treatment Notes
// already gets via woVoid's Combined path (see the Notes-merge block in woVoid above), rather
// than reducing N values down to one picked winner. Description is the direct fix for
// Brett's Sep 23 2026 bug report: 3 genuinely different tenant complaints (garbage disposal /
// door / shelving) were being collapsed to a single radio pick, silently discarding the other
// two. Room gets the same treatment for the same underlying reason — a room name is
// information the combine could easily be losing, not a setting with one objectively-correct
// value.
//
// Owner_WO_Ref is deliberately NOT here (Brett, Sep 23 2026, after reviewing the first draft
// of this PR which DID auto-merge it): the owner has their OWN reference numbers on their own
// side, and concatenating several onto one WO wouldn't match what the owner actually expects
// to see on any single surviving WO — unlike Description/Room, blending these together makes
// the field actively wrong, not just long. Owner_WO_Ref is excluded from BOTH this list and
// WO_COMBINE_RECONCILE_FIELDS entirely — same treatment as Trade/Checklist, survivor keeps its
// own value untouched, no picker, no merge. Instead, see the "owner ref notice" block in
// woCombine below: when a combine actually abandons a distinct owner reference (a combined
// WO's own Owner_WO_Ref is non-blank and differs from the survivor's), the owner gets a
// one-time notice naming which of their WO+ref pairs were folded into the surviving one, so
// they can update their own records — the notice replaces silently merging or silently
// dropping the ref.
const WO_COMBINE_MERGE_FIELDS = ['Description', 'Room'];

// Pure — no I/O. Same timestamped-prefix convention woVoid's Notes-merge already uses,
// reused here for every WO_COMBINE_MERGE_FIELDS field so Description/Room merges look and
// audit exactly like a Notes merge already does. Returns the survivor's value unchanged when
// the incoming WO's value for this field is blank — nothing to add.
function mergeWOTextField(survivorVal, sourceWoId, incomingVal) {
  const val = String(incomingVal == null ? '' : incomingVal).trim();
  if (!val) return survivorVal || '';
  const ts = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  const prefix = `[${ts} — combined from ${sourceWoId}] `;
  return survivorVal ? `${survivorVal}\n${prefix}${val}` : `${prefix}${val}`;
}

// Pure — no I/O — so it's directly unit-testable without mocking Sheets. `wos` is
// [survivor, ...combined], each a plain Work_Orders row object; `overrides` is the client's
// field_overrides object (or {}/null). A field only lands in `resolved` when every WO in
// `wos` agrees on it (even if that shared value differs from what the survivor itself
// originally had — silent auto-resolve either way), OR the caller supplied an override that
// matches one of the REAL candidate values already present on one of the selected WOs. An
// override that doesn't match any real candidate is refused, not trusted blindly — it still
// comes back as a conflict, same as no override at all.
function resolveCombineFields(wos, overrides, fields) {
  fields = fields || WO_COMBINE_RECONCILE_FIELDS;
  overrides = overrides && typeof overrides === 'object' ? overrides : {};
  const resolved = {}, conflicts = [];
  for (const f of fields) {
    const values = wos.map(w => (w && w[f] != null) ? String(w[f]) : '');
    const allAgree = values.every(v => v === values[0]);
    if (allAgree) { resolved[f] = values[0]; continue; }
    if (Object.prototype.hasOwnProperty.call(overrides, f)) {
      const chosen = String(overrides[f] == null ? '' : overrides[f]);
      if (values.includes(chosen)) { resolved[f] = chosen; continue; }
    }
    conflicts.push(f);
  }
  return { resolved, conflicts };
}

// POST /wo/combine {survivor_wo_id, combined_wo_ids:[...], field_overrides?:{...}, updated_by?,
// updated_by_role?} — extends the existing single-target woVoid(reason:'Combined') flow (the
// WO detail page's Void modal, left completely untouched) to N sources -> 1 survivor in one
// call. Brett always picks the survivor client-side — no auto-default here. Field
// reconciliation is recomputed here from the real rows, never trusted from the client; a real
// disagreement 409s with the conflicting field names so the UI can show the picker and retry
// with field_overrides. Each non-survivor WO is voided by calling the real woVoid() so its
// Notes-merge/WO_Audit behavior is byte-for-byte identical to a manual single Combine — this
// endpoint does not reimplement that logic.
//
// Rollback: Sheets has no transactions, so this is best-effort atomicity, same shape as
// /ops-queue/start-build's original-status rollback (see opsQueueStartBuild) — snapshot the
// survivor's reconciled fields before writing, and if any later step throws, unvoid whatever
// was already voided and restore the survivor's snapshot before reporting the failure, rather
// than leaving a half-combined state on the sheet.
async function woCombine(env, body) {
  const survivorId = body.survivor_wo_id;
  if (!survivorId) return json({ error: 'survivor_wo_id required' }, 400);
  const combinedIds = [...new Set((Array.isArray(body.combined_wo_ids) ? body.combined_wo_ids : []).map(x => String(x || '')).filter(Boolean))];
  if (!combinedIds.length) return json({ error: 'combined_wo_ids required (at least one)' }, 400);
  if (combinedIds.includes(String(survivorId))) return json({ error: 'survivor_wo_id cannot also appear in combined_wo_ids' }, 400);

  try { await ensureColumns(env, 'Work_Orders', WO_VOID_COLUMNS); } catch (_) {}
  const workorders = await fetchTab(env, 'Work_Orders');
  const survivor = findWO(workorders, survivorId);
  if (!survivor) return json({ error: `Survivor work order ${survivorId} not found` }, 404);
  if (String(survivor.Voided || '').toUpperCase() === 'TRUE') return json({ error: `Survivor work order ${survivorId} is voided — cannot combine into it` }, 400);
  if (String(survivor.Bid_Group_ID || '').trim()) return json({ error: `Work order ${survivorId} is in bid group ${survivor.Bid_Group_ID} — unlink it from the group first (WO detail > Bid group) before combining.` }, 400);
  const combinedWOs = [];
  for (const id of combinedIds) {
    const w = findWO(workorders, id);
    if (!w) return json({ error: `Work order ${id} not found` }, 404);
    if (String(w.Voided || '').toUpperCase() === 'TRUE') return json({ error: `Work order ${id} is already voided — cannot combine it again` }, 400);
    if (String(w.Bid_Group_ID || '').trim()) return json({ error: `Work order ${id} is in bid group ${w.Bid_Group_ID} — unlink it from the group first (WO detail > Bid group) before combining.` }, 400);
    combinedWOs.push(w);
  }
  // Same same-Property_ID/Unit_ID scoping the existing single-WO Combined picker already
  // enforces client-side (populateVoidCombineOptions) — re-enforced here server-side, never
  // trusted from the client.
  for (const w of combinedWOs) {
    if (String(w.Property_ID || '') !== String(survivor.Property_ID || '') || String(w.Unit_ID || '') !== String(survivor.Unit_ID || '')) {
      return json({ error: `Work order ${w.ID} is not the same property/unit as survivor ${survivorId}` }, 400);
    }
  }

  // Billing-state guard (Sep 23 2026, Brett — field audit gap #3; widened same day after
  // Brett's follow-up to also cover vendor-bill state). QBO_Invoice_Number is the
  // Work_Orders-level signal that a WO has actually been invoiced (customer-facing) in
  // QuickBooks (written by qbSendInvoice/qbSendFinalInvoice). Combining across that boundary
  // would fold a survivor's Description/Priority/etc (and any future combine-driven edits)
  // into a WO QuickBooks already has a final invoice number for, silently changing what's
  // already been billed. Separately, a WO can have vendor-bill-side billing state already
  // reviewed/sent to QuickBooks (Vendor_Bills/Invoice_Review — a BILL, the vendor-paid side,
  // distinct from the customer-facing INVOICE above) without necessarily having an invoice
  // number on the WO itself yet — findLockedVendorBillForWOs reuses the exact same
  // vendorBillReassignLock logic Split's reassignment guard already trusts for "is this bill
  // already committed". Either signal blocks the whole combine outright, no override possible
  // — there's no safe auto-reconciliation for already-billed state either way.
  const alreadyInvoiced = [survivor, ...combinedWOs].filter(w => String(w.QBO_Invoice_Number || '').trim());
  const lockedBill = await findLockedVendorBillForWOs(env, [survivor.ID, ...combinedWOs.map(w => w.ID)]);
  if (alreadyInvoiced.length || lockedBill) {
    const reasons = [];
    if (alreadyInvoiced.length) reasons.push(`${alreadyInvoiced.map(w => w.ID).join(', ')} already ${alreadyInvoiced.length > 1 ? 'have' : 'has'} a QuickBooks invoice number`);
    if (lockedBill) reasons.push(`WO ${lockedBill.WO_ID} has a vendor bill (${lockedBill.ID}) already reviewed/sent to QuickBooks`);
    return json({
      error: 'already_invoiced',
      wo_ids: alreadyInvoiced.map(w => w.ID),
      locked_bill_id: lockedBill ? lockedBill.ID : undefined,
      message: `Cannot combine — ${reasons.join('; ')}. Handle billing manually before combining.`,
    }, 400);
  }

  const { resolved, conflicts } = resolveCombineFields([survivor, ...combinedWOs], body.field_overrides);
  if (conflicts.length) {
    return json({ error: 'field_conflict', conflicts, message: `These fields disagree across the selected work orders — field_overrides required for: ${conflicts.join(', ')}` }, 409);
  }

  const changedBy = body.updated_by || 'admin', changedByRole = body.updated_by_role || 'admin';
  const survivorSnapshot = {};
  for (const f of WO_COMBINE_RECONCILE_FIELDS) survivorSnapshot[f] = survivor[f] ?? '';
  for (const f of WO_COMBINE_MERGE_FIELDS) survivorSnapshot[f] = survivor[f] ?? '';
  const fieldsToApply = {};
  for (const f of WO_COMBINE_RECONCILE_FIELDS) {
    if (String(resolved[f] ?? '') !== String(survivorSnapshot[f] ?? '')) fieldsToApply[f] = resolved[f];
  }
  // Merge fields (Description/Room/Owner_WO_Ref): unconditional, order-preserving
  // concatenation of every combined WO's own value onto the survivor's, regardless of
  // whether they agree or disagree — there is no "conflict" state for these at all.
  for (const f of WO_COMBINE_MERGE_FIELDS) {
    let merged = survivorSnapshot[f];
    for (const w of combinedWOs) merged = mergeWOTextField(merged, w.ID, w[f]);
    if (merged !== survivorSnapshot[f]) fieldsToApply[f] = merged;
  }

  const voidedSoFar = [];
  try {
    if (Object.keys(fieldsToApply).length) {
      await updateWOFields(env, survivorId, fieldsToApply);
      await logWOAuditMany(env, Object.entries(fieldsToApply).map(([field, newVal]) => ({
        woId: survivorId, changedBy, changedByRole, field,
        oldValue: survivorSnapshot[field], newValue: newVal,
        notes: WO_COMBINE_MERGE_FIELDS.includes(field)
          ? `Combine: merged from ${combinedIds.join(', ')}`
          : `Combine: reconciled from ${combinedIds.join(', ')}`,
      })));
    }
    for (const w of combinedWOs) {
      const res = await woVoid(env, { wo_id: w.ID, reason: 'Combined', combined_into_wo_id: survivorId, updated_by: changedBy, updated_by_role: changedByRole });
      const resBody = await res.json();
      if (!resBody || !resBody.success) throw new Error(`Failed to void ${w.ID}${resBody && resBody.error ? ': ' + resBody.error : ''}`);
      voidedSoFar.push(w.ID);
    }
  } catch (e) {
    for (const id of voidedSoFar) { try { await woUnvoid(env, { wo_id: id, updated_by: changedBy, updated_by_role: changedByRole }); } catch (_) {} }
    if (Object.keys(fieldsToApply).length) { try { await updateWOFields(env, survivorId, survivorSnapshot); } catch (_) {} }
    return json({ error: 'combine_failed', detail: e.message, rolled_back: true }, 500);
  }

  // Batched tenant SMS — ONE new notice about the merge, gated exactly like every other
  // tenant status SMS (isTenantNotifiable + the survivor's own Tenant_Notify_Updates toggle),
  // through the same smsGatedSend chokepoint (full Global/Property/Owner/Tenant gate
  // hierarchy) — no bypass. The survivor keeps getting its normal future notifications
  // unchanged; this is just the one extra notice about the combine itself. Best-effort —
  // the combine itself has already succeeded above regardless of this.
  try {
    const survivorFresh = findWO(await fetchTab(env, 'Work_Orders'), survivorId) || survivor;
    const units = await fetchTab(env, 'Units'), tenants = await fetchTab(env, 'Tenants');
    const properties = await fetchTab(env, 'Properties'), owners = await fetchTab(env, 'Owners');
    const unit = units.find(u => u.ID === survivorFresh.Unit_ID);
    const property = properties.find(p => p.ID === survivorFresh.Property_ID);
    const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
    // CAP-036 #21: every active tenant in the unit, not just one.
    if (survivorFresh.Tenant_Notify_Updates !== 'FALSE') for (const tenant of tenantsForDispatch(tenants, unit, survivorFresh)) {
      if (!isTenantNotifiable(tenant, survivorFresh)) continue;
      const idList = combinedIds.join(', ');
      const msg = `Hi ${tenant.First_Name}, work order${combinedIds.length > 1 ? 's' : ''} ${idList} (${woJobLabel(survivorFresh)}) ${combinedIds.length > 1 ? 'were' : 'was'} combined into ${survivorId}. We're continuing to track it there. Ref: ${survivorId}.`;
      await smsGatedSend(env, { wo_id: survivorId, message_type: 'tenant_wo_combined', recipient_type: 'tenant', tenant, owner, property, message_body: msg });
    }
  } catch (e) { /* non-fatal — combine already succeeded */ }

  // Owner ref notice (Sep 23 2026, Brett's follow-up) — Owner_WO_Ref is excluded from both
  // WO_COMBINE_RECONCILE_FIELDS and WO_COMBINE_MERGE_FIELDS (see the comment above
  // WO_COMBINE_MERGE_FIELDS): the survivor keeps its own ref completely untouched. When that
  // means a combine is actually abandoning a distinct owner reference — a combined WO's own
  // Owner_WO_Ref is non-blank AND differs from the survivor's — the owner gets a one-time
  // notice naming exactly which of their WO+ref pairs were folded into which surviving WO+ref,
  // so they can update their own records; matches the existing owner_job_scheduled/
  // owner_managed_by_changed pattern (smsGatedSend, recipient_type:'owner', same Global+
  // Property+Customer gate hierarchy — no bypass). Skipped entirely (with an explicit
  // WO_Audit note, same "log it either way" convention as the rest of this endpoint) when
  // nothing is actually being abandoned — every combined WO's ref is blank or already matches
  // the survivor's — so this never fires on the common case of one shared/absent ref.
  try {
    const survivorForRef = findWO(await fetchTab(env, 'Work_Orders'), survivorId) || survivor;
    const survivorRef = String(survivorForRef.Owner_WO_Ref || '').trim();
    const abandonedWOs = combinedWOs.filter(w => {
      const ref = String(w.Owner_WO_Ref || '').trim();
      return ref && ref !== survivorRef;
    });
    if (!abandonedWOs.length) {
      await logWOAudit(env, survivorId, changedBy, changedByRole, 'Owner_Ref_Notice', '', 'skipped', 'No distinct owner reference abandoned by this combine — nothing to notify the owner about');
    } else {
      const properties = await fetchTab(env, 'Properties'), owners = await fetchTab(env, 'Owners');
      const property = properties.find(p => p.ID === survivorForRef.Property_ID);
      const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
      const unitForRef = (await fetchTab(env, 'Units')).find(u => u.ID === survivorForRef.Unit_ID);
      if (owner && owner.Phone && property) {
        const pairs = abandonedWOs.map(w => `${w.ID} (owner ref ${String(w.Owner_WO_Ref).trim()})`);
        const pairList = pairs.length > 1 ? pairs.slice(0, -1).join(', ') + ' and ' + pairs[pairs.length - 1] : pairs[0];
        const survivorRefText = survivorRef ? `owner ref ${survivorRef}` : 'no owner ref on file';
        const msg = `Hi ${owner.First_Name}, at ${propUnitText(property, unitForRef)}, ${pairList} ${abandonedWOs.length > 1 ? 'were' : 'was'} combined into ${survivorId} (${survivorRefText}). Please update your records — future updates will only come on ${survivorId}. Thank you!`;
        await smsGatedSend(env, { wo_id: survivorId, message_type: 'owner_wo_combined_ref', recipient_type: 'owner', owner, property, message_body: msg });
      }
    }
  } catch (e) { /* non-fatal — combine already succeeded */ }

  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_combine', Skill_Or_Endpoint: '/wo/combine', Success: 'TRUE', Notes: `survivor=${survivorId} combined=${combinedIds.join(',')}` }); } catch (_) {}

  const mergedFieldsApplied = {};
  for (const f of WO_COMBINE_MERGE_FIELDS) if (Object.prototype.hasOwnProperty.call(fieldsToApply, f)) mergedFieldsApplied[f] = fieldsToApply[f];
  return json({ success: true, survivor_wo_id: survivorId, combined_wo_ids: combinedIds, resolved_fields: resolved, merged_fields: mergedFieldsApplied });
}

// Split (inverse of Combine, Sep 22 2026 build — WO detail "Split" action). Takes ONE existing
// work order and creates N new additional work orders from it, dividing the work between the
// original (which survives, trimmed down) and the new ones. New WOs inherit Property_ID/
// Unit_ID/Tenant_ID from the original (same job location/tenant) — never re-entered. Each new
// WO's Description arrives from the client already pre-filled from the original's own text and
// then edited/trimmed down there — the server does not re-derive it, whatever the client sends
// is what gets written, same as any other field.
const WO_SPLIT_ORIGINAL_FIELDS = ['Trade', 'Priority', 'Vendor_ID', 'Scheduled_Date', 'Managed_By', 'Description'];
const WO_SPLIT_MAX_NEW = 10;

// Pure — whether a Time_Entries row is safe to move to a different WO_ID. Already-billed hours
// (Bill_ID set, and that bill still live) are the labor a live vendor bill already accounts for —
// moving the hours without moving the bill would make the two disagree about which job they're
// for. A blank Bill_ID, or one pointing at a voided/inactive bill (voiding already frees the
// hours again — same convention listTimeEntries' Billed_Bill_ID already uses), is safe to move.
function timeEntryReassignLock(entry, vendorBills) {
  const billId = String(entry.Bill_ID || '').trim();
  if (!billId) return null;
  const bill = vendorBills.find(b => String(b.ID) === billId);
  if (!bill || bill.Active === 'FALSE') return null;
  return `Already linked to vendor bill ${billId} — reassign the bill instead, or unlink the entry first.`;
}

// Pure — whether a Vendor_Bills row is safe to move to a different WO_ID. 'reviewed' means
// Brett has already approved/markup-priced it (approveInvoiceReview) against the WO it names; a
// live Invoice_Review row carrying a QB_Invoice_ID means it has actually been sent to
// QuickBooks. Either way the WO on the bill is already baked into billed/booked numbers
// elsewhere — moving it after that point would make the Hub and QuickBooks disagree about which
// job it was for. Same care the existing bill-adjustment code (moveVendorBillToNewWO) takes with
// otherAactiveBills, applied here as a hard block rather than a "pause and look" preview, since
// Split's reassignment table has no separate preview/apply step of its own.
function vendorBillReassignLock(bill, invoiceReviewRows) {
  if (bill.Active === 'FALSE') return 'Bill is voided/inactive.';
  if (bill.Status === 'reviewed') return 'Already reviewed/approved for invoicing.';
  const sentReview = (invoiceReviewRows || []).find(ir => ir.Active !== 'FALSE' && String(ir.Bill_ID) === String(bill.ID) && String(ir.QB_Invoice_ID || '').trim());
  if (sentReview) return `Already sent to QuickBooks (invoice ${sentReview.QB_Invoice_ID}).`;
  return null;
}

// Billing-state guard helper shared by woCombine and woSplit (Sep 23 2026, Brett's follow-up
// to widen the invoice-only check both endpoints started with). Reuses vendorBillReassignLock
// above — the same "is this bill already committed" logic Split's own reassignment guard
// already trusts — against every LIVE Vendor_Bills row tied to any of the given WO ids.
// Voided/inactive bills are filtered out before the check (moot for a billing-state block,
// unlike for reassignment safety where vendorBillReassignLock's own Active==='FALSE' branch
// matters). Returns the first locked bill found, or null if none of the given WOs has one.
async function findLockedVendorBillForWOs(env, woIds) {
  const ids = new Set((woIds || []).map(String));
  if (!ids.size) return null;
  const vendorBills = await fetchTab(env, 'Vendor_Bills');
  const relevant = vendorBills.filter(b => ids.has(String(b.WO_ID)) && b.Active !== 'FALSE');
  if (!relevant.length) return null;
  let invoiceReview = [];
  try { invoiceReview = await fetchTab(env, 'Invoice_Review'); } catch (e) {}
  for (const bill of relevant) {
    if (vendorBillReassignLock(bill, invoiceReview)) return bill;
  }
  return null;
}

// POST /wo/split {original_wo_id, original_overrides?:{Trade,Priority,Vendor_ID,Scheduled_Date,
// Managed_By,Description}, new_work_orders:[{Trade,Priority,Vendor_ID?,Scheduled_Date?,
// Managed_By,Description}, ...], reassignments?:[{type:'time_entry'|'vendor_bill', id,
// target:'original'|<new-WO index>}]}. Property_ID/Unit_ID/Tenant_ID are always inherited from
// the original, never taken from the client. New WOs are created through the real
// createWorkOrder() so numbering/defaults/required-column handling stays exactly consistent with
// every other WO creation path; fields it doesn't accept on its own body (Vendor_ID,
// Scheduled_Date, Managed_By) are applied right after via updateWOFields, same two-step pattern
// moveVendorBillToNewWO already uses. Reassignments are validated (existence, ownership by the
// original, lock state) BEFORE anything is created, so a bad reassignment never leaves new WOs
// half-created. Rollback on any later failure: undo any already-applied reassignments, restore
// the original's overridden fields, and void (there is no hard-delete anywhere in this app —
// voiding is the standing "undo a creation" mechanism) whatever new WOs already got created.
async function woSplit(env, body) {
  const originalId = body.original_wo_id;
  if (!originalId) return json({ error: 'original_wo_id required' }, 400);
  const newSpecs = Array.isArray(body.new_work_orders) ? body.new_work_orders : [];
  if (!newSpecs.length) return json({ error: 'new_work_orders required (at least one)' }, 400);
  if (newSpecs.length > WO_SPLIT_MAX_NEW) return json({ error: `Cannot split into more than ${WO_SPLIT_MAX_NEW} new work orders at once` }, 400);

  const workorders = await fetchTab(env, 'Work_Orders');
  const original = findWO(workorders, originalId);
  if (!original) return json({ error: `Work order ${originalId} not found` }, 404);
  if (original.Voided === 'TRUE') return json({ error: `Work order ${originalId} is voided — cannot split it` }, 400);
  if (String(original.Bid_Group_ID || '').trim()) return json({ error: `Work order ${originalId} is in bid group ${original.Bid_Group_ID} — unlink it from the group first (WO detail > Bid group) before splitting.` }, 400);
  // Same billing-state guard as woCombine (Sep 23 2026 field audit, widened same day to also
  // cover vendor-bill state) — splitting a WO that QuickBooks already has a final invoice
  // number for would leave that invoice referring to a job that's now spread across N work
  // orders, with no way to tell which one(s) it actually covers; a vendor bill already
  // reviewed/sent to QuickBooks has the same problem on the vendor-paid side. Blocked outright
  // rather than offered a picker, same reasoning as Combine.
  {
    const alreadyInvoicedOriginal = !!String(original.QBO_Invoice_Number || '').trim();
    const lockedBillOriginal = await findLockedVendorBillForWOs(env, [originalId]);
    if (alreadyInvoicedOriginal || lockedBillOriginal) {
      const reasons = [];
      if (alreadyInvoicedOriginal) reasons.push(`${originalId} already has a QuickBooks invoice number`);
      if (lockedBillOriginal) reasons.push(`vendor bill ${lockedBillOriginal.ID} is already reviewed/sent to QuickBooks`);
      return json({
        error: 'already_invoiced',
        wo_ids: [originalId],
        locked_bill_id: lockedBillOriginal ? lockedBillOriginal.ID : undefined,
        message: `Cannot split ${originalId} — ${reasons.join('; ')}. Handle billing manually before splitting.`,
      }, 400);
    }
  }

  const changedBy = body.updated_by || 'admin', changedByRole = body.updated_by_role || 'admin';
  const overrides = body.original_overrides && typeof body.original_overrides === 'object' ? body.original_overrides : {};

  const reassignments = Array.isArray(body.reassignments) ? body.reassignments : [];
  for (const r of reassignments) {
    if (!r || (r.type !== 'time_entry' && r.type !== 'vendor_bill') || r.id === undefined || r.id === null || r.id === '') {
      return json({ error: 'Each reassignment needs a type (time_entry|vendor_bill) and id' }, 400);
    }
    const validTarget = r.target === 'original' || (Number.isInteger(r.target) && r.target >= 0 && r.target < newSpecs.length);
    if (!validTarget) return json({ error: `Invalid reassignment target for ${r.type} ${r.id}` }, 400);
  }

  // Load + lock-check every referenced Time_Entries/Vendor_Bills row up front. Vendor_Bills is
  // needed for BOTH types (a time entry's own lock check reads it too), so any reassignment at
  // all pulls it in.
  let timeEntries = [], vendorBills = [], invoiceReview = [];
  if (reassignments.some(r => r.type === 'time_entry')) timeEntries = await fetchTab(env, 'Time_Entries');
  if (reassignments.length) vendorBills = await fetchTab(env, 'Vendor_Bills');
  if (reassignments.some(r => r.type === 'vendor_bill')) { try { invoiceReview = await fetchTab(env, 'Invoice_Review'); } catch (e) {} }

  const resolvedReassignments = [];
  for (const r of reassignments) {
    if (r.type === 'time_entry') {
      const te = timeEntries.find(t => String(t.ID) === String(r.id));
      if (!te) return json({ error: `Time entry ${r.id} not found` }, 404);
      if (String(te.WO_ID) !== String(originalId)) return json({ error: `Time entry ${r.id} does not belong to ${originalId}` }, 400);
      const lockReason = timeEntryReassignLock(te, vendorBills);
      if (lockReason) return json({ error: 'reassign_locked', type: 'time_entry', id: r.id, reason: lockReason }, 409);
      resolvedReassignments.push({ type: 'time_entry', id: r.id, target: r.target });
    } else {
      const bill = vendorBills.find(b => String(b.ID) === String(r.id));
      if (!bill) return json({ error: `Vendor bill ${r.id} not found` }, 404);
      if (String(bill.WO_ID) !== String(originalId)) return json({ error: `Vendor bill ${r.id} does not belong to ${originalId}` }, 400);
      const lockReason = vendorBillReassignLock(bill, invoiceReview);
      if (lockReason) return json({ error: 'reassign_locked', type: 'vendor_bill', id: r.id, reason: lockReason }, 409);
      resolvedReassignments.push({ type: 'vendor_bill', id: r.id, target: r.target });
    }
  }

  const originalSnapshot = {};
  for (const f of WO_SPLIT_ORIGINAL_FIELDS) originalSnapshot[f] = original[f] ?? '';
  const originalFieldsToApply = {};
  for (const f of WO_SPLIT_ORIGINAL_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(overrides, f) && String(overrides[f] ?? '') !== String(originalSnapshot[f] ?? '')) {
      originalFieldsToApply[f] = overrides[f];
    }
  }

  const createdWoIds = [];
  const appliedReassignments = []; // {type, id, from} — for rollback
  try {
    // 1. Create each new WO via the real createWorkOrder() path — inherits Property/Unit/Tenant
    //    from the original, never from the client. A zero-width-space marker (stripped right
    //    back off below) makes each call's Description unique even when two new WOs still carry
    //    the identical pre-filled text — createWorkOrder's own accidental-double-tap duplicate
    //    guard (findRecentDuplicate) has no way to know this is 1-of-N intentional creates in
    //    one Split, not a resubmit, and would otherwise collapse them into the same WO id.
    // Fallback for a new WO spec that omits Trade/Priority entirely (the shipped index.html
    // Split UI always sends both, pre-filled from the original's own values — see
    // splitCardHtml — so this only matters for a direct/future API caller): Sep 23 2026 field
    // audit gap, structurally the same class of bug Brett hit in Combine — silently defaulting
    // to 'normal'/'' would downgrade an Urgent original's children to Normal, or leave a new
    // WO with no Trade at all, with no signal that happened. Falls back to the original's own
    // (post-override) value instead, same "inherit unless told otherwise" rule the rest of
    // Split already applies to Property/Unit/Tenant/Room.
    const effectiveOriginalTrade = Object.prototype.hasOwnProperty.call(originalFieldsToApply, 'Trade') ? originalFieldsToApply.Trade : originalSnapshot.Trade;
    const effectiveOriginalPriority = Object.prototype.hasOwnProperty.call(originalFieldsToApply, 'Priority') ? originalFieldsToApply.Priority : originalSnapshot.Priority;
    for (let i = 0; i < newSpecs.length; i++) {
      const spec = newSpecs[i] || {};
      const dupeGuardMarker = '​'.repeat(i + 1);
      const createRes = await createWorkOrder(env, {
        property_id: original.Property_ID || '', unit_id: original.Unit_ID || '', tenant_id: original.Tenant_ID || '',
        type: original.Type || 'manual', trade: spec.Trade || effectiveOriginalTrade || '', description: (spec.Description || '') + dupeGuardMarker,
        priority: spec.Priority || effectiveOriginalPriority || 'normal', room: original.Room || '',
        created_by: changedBy, notes: `Created via split from ${originalId}`,
      });
      const created = await createRes.clone().json();
      if (!created || !created.id) throw new Error('Failed to create a new work order during split');
      createdWoIds.push(created.id);
      const postCreateFields = { Description: spec.Description || '' }; // strip the dupe-guard marker back off
      if (spec.Vendor_ID) postCreateFields.Vendor_ID = spec.Vendor_ID;
      if (spec.Scheduled_Date) postCreateFields.Scheduled_Date = spec.Scheduled_Date;
      if (spec.Managed_By) postCreateFields.Managed_By = spec.Managed_By;
      await updateWOFields(env, created.id, postCreateFields);
    }

    // 2. Apply overrides to the original.
    if (Object.keys(originalFieldsToApply).length) {
      await updateWOFields(env, originalId, originalFieldsToApply);
      await logWOAuditMany(env, Object.entries(originalFieldsToApply).map(([field, newVal]) => ({
        woId: originalId, changedBy, changedByRole, field,
        oldValue: originalSnapshot[field], newValue: newVal,
        notes: `Split: original updated, new work orders ${createdWoIds.join(', ')}`,
      })));
    }

    // 3. Apply reassignments — after the new WOs exist, so a target index resolves to a real id.
    for (const r of resolvedReassignments) {
      const targetWoId = r.target === 'original' ? originalId : createdWoIds[r.target];
      const tab = r.type === 'time_entry' ? 'Time_Entries' : 'Vendor_Bills';
      await updateRow(env, tab, r.id, { WO_ID: targetWoId });
      appliedReassignments.push({ type: r.type, id: r.id, from: originalId });
    }

    // 4. Audit trail — original names every new WO it was split into; each new WO names the
    //    original it came from. Mirrors woCombine's logWOAuditMany convention.
    await logWOAudit(env, originalId, changedBy, changedByRole, 'Split', 'FALSE', 'TRUE', `Split into ${createdWoIds.join(', ')}`);
    await logWOAuditMany(env, createdWoIds.map(id => ({
      woId: id, changedBy, changedByRole, field: 'Created', oldValue: '', newValue: 'TRUE',
      notes: `Created via split from ${originalId}`,
    })));
  } catch (e) {
    for (const ar of appliedReassignments) {
      const tab = ar.type === 'time_entry' ? 'Time_Entries' : 'Vendor_Bills';
      try { await updateRow(env, tab, ar.id, { WO_ID: ar.from }); } catch (_) {}
    }
    if (Object.keys(originalFieldsToApply).length) { try { await updateWOFields(env, originalId, originalSnapshot); } catch (_) {} }
    for (const id of createdWoIds) {
      try { await woVoid(env, { wo_id: id, reason: 'Other', detail: `Split rolled back — ${originalId}'s split failed partway`, updated_by: changedBy, updated_by_role: changedByRole }); } catch (_) {}
    }
    return json({ error: 'split_failed', detail: e.message, rolled_back: true, created_then_rolled_back: createdWoIds }, 500);
  }

  // 5. Batched tenant SMS — gated on the ORIGINAL's own (post-override) Tenant_Notify_Updates,
  //    through the same full Global/Property/Owner/Tenant hierarchy as every other tenant SMS —
  //    no bypass. Best-effort — the split itself has already succeeded above regardless of this.
  try {
    const originalFresh = findWO(await fetchTab(env, 'Work_Orders'), originalId) || original;
    const units = await fetchTab(env, 'Units'), tenants = await fetchTab(env, 'Tenants');
    const properties = await fetchTab(env, 'Properties'), owners = await fetchTab(env, 'Owners');
    const unit = units.find(u => u.ID === originalFresh.Unit_ID);
    const property = properties.find(p => p.ID === originalFresh.Property_ID);
    const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
    // CAP-036 #21: every active tenant in the unit, not just one.
    if (originalFresh.Tenant_Notify_Updates !== 'FALSE') for (const tenant of tenantsForDispatch(tenants, unit, originalFresh)) {
      if (!isTenantNotifiable(tenant, originalFresh)) continue;
      const idList = createdWoIds.join(', ');
      const msg = `Hi ${tenant.First_Name}, work order ${originalId} (${woJobLabel(originalFresh)}) was split into ${createdWoIds.length > 1 ? 'work orders' : 'work order'} ${idList}. We're continuing to track your job across these. Ref: ${originalId}.`;
      await smsGatedSend(env, { wo_id: originalId, message_type: 'tenant_wo_split', recipient_type: 'tenant', tenant, owner, property, message_body: msg });
    }
  } catch (e) { /* non-fatal — split already succeeded */ }

  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_split', Skill_Or_Endpoint: '/wo/split', Success: 'TRUE', Notes: `original=${originalId} new=${createdWoIds.join(',')}` }); } catch (_) {}

  return json({ success: true, original_wo_id: originalId, new_wo_ids: createdWoIds });
}

// Voided WOs are excluded from the default list, and from ?include_closed=true, on every
// list endpoint below — they are not a "closed" status like Complete/Invoiced/Paid, they are
// removed from view entirely. The admin /workorders route below is the one place that can
// still see them, and only on request (?include_voided / ?voided_only), for the Hub's own
// dedicated Voided filter.
async function getWorkOrdersList(env, url) {
  const rows = await fetchTab(env, 'Work_Orders');
  const voidedOnly = url.searchParams.get('voided_only') === '1';
  const includeVoided = url.searchParams.get('include_voided') === '1';
  const filtered = voidedOnly ? rows.filter(r => r.Voided === 'TRUE')
    : includeVoided ? rows
    : rows.filter(r => r.Voided !== 'TRUE');
  return json(filtered.filter(r => String(r.Addon_Status || '') !== 'Draft'));   // additional-work drafts are never listed
}
// ════════════════════════════════════════════════════════════════════════════════════════════
// DUPLICATE WORK ORDER + BID GROUPS  (Oct 12 2026, Brett)
// Brett has vendors who don't keep promised schedules, so he wants a deliberate "shotgun": give
// the SAME job to several vendors at once and keep whichever comes back first/best. Normally a
// duplicate WO is exactly what rule 162 (findRecentDuplicate) exists to stop, so this is an
// explicit, admin-only, one-copy-per-tap feature with its own rules:
//   - POST /wo/duplicate {source_wo_id, vendor_id?}  one COPY per call, linked in a bid group
//     (Work_Orders.Bid_Group_ID 'BG-n'); Duplicated_From = the WO the button was tapped on.
//     Copies everything EXCEPT vendor, estimates, bills, time/labor, billing/QBO/deposit/scope
//     fields, schedule and Drive folder. SILENT to tenant and owner. The chosen vendor gets the
//     normal "new job" SMS right away and that one SMS bypasses quiet hours (this feature only).
//     The SMS outcome (sent/held/failed + reason) is ALWAYS returned and shown by the Hub.
//   - POST /wo/bid-group/unlink {wo_id}   makes a copy independent (clears Bid_Group_ID).
//   - POST /wo/bid-group/cancel {group_id|wo_id, mode:'all'|'duplicates'|'keep_one', keep_wo_id?,
//     dry_run?, confirm?}  cancels members through updateStatus (same semantics as /status
//     Cancelled: WO_Audit row + add-on orphan guard). Executes ONLY with confirm:true and
//     dry_run!==true; anything else is a preview. Members with bills/time/charges/QBO numbers
//     or a finished status are SKIPPED with a reason, never cancelled.
//   - GET /wo/bid-group?wo_id=  members for the Hub panel.
//   - Oct 13 2026 follow-up (Brett): "Keep this, cancel others" (mode keep_one) NEVER cancels the ORIGINAL
//     (the member with no Duplicated_From) — it cancels only the other duplicate copies. When the kept
//     member is a COPY it becomes tenant-visible (Tenant_Visible TRUE) and is marked Bid_Winner TRUE so the
//     owner portal (which hides still-linked copies) shows it too. Unlink leaves Tenant_Visible exactly as it is.
//   - Oct 13 2026 follow-up #2 (Brett: "tell the vendor." / "kept copy notifies according to that work order's settings."):
//     (1) When a cancel is EXECUTED (confirm:true, never a preview) the assigned vendor of every copy that really got
//         cancelled is texted that the job is cancelled / no longer needed (vendor_job_cancelled; bilingual by Vendor
//         Language; through smsGatedSend so every SMS gate, Test Mode and QUIET HOURS apply: a cancellation notice is not
//         urgent, so overnight it is HELD and the scheduler's `sweep` job releases it). One text per cancelled WO; an
//         already-Cancelled WO is never texted again (a retried confirm sends nothing); a vendor who also holds a job that
//         stays open is not texted (it would confuse them); no vendor = skipped. The per-vendor outcome (sent / held /
//         failed / skipped + reason) is returned and shown; a failed text is logged to Ops_Telemetry, returned in warnings
//         + needs_attention, and never blocks or undoes the cancel. Tenant and owner are never texted by a cancel.
//     (2) When a COPY is kept (keep_one) it starts notifying like any normal work order: Tenant_Visible / Tenant_Notify_Created /
//         Tenant_Notify_Updates are taken from the ORIGINAL work order of the group (a normal WO's own settings; defaults
//         TRUE when the original has none) and Owner_Notify_Override is cleared (or copied from the original), so the
//         owner's own notification setting applies. NO "new work order" text is sent at keep time: tenant and owner are
//         told about later status changes/updates only. Written first, read back, audited; if that fails nothing is cancelled.
// Why not createWorkOrder: its dupe guard (the point of rule 162) would block the copy, skipping
// the guard reopens the duplicate-ID race (WO-1192), and the row needs ~10 columns it never
// writes at create. So the copy is appended by woDupAppendCopy: serialized per isolate, one
// complete row in ONE append, then re-read to prove the ID is unique (and repaired if another
// isolate raced us). No notification code is reached at all, so "silent" is structural.
// NOTHING FAILS SILENTLY: every failure is logged to Ops_Telemetry (Success FALSE, WO ids) AND
// returned in `errors`/`warnings`; every write is re-read and verified.
// ════════════════════════════════════════════════════════════════════════════════════════════
const WO_DUP_ALLOWED_STATUSES = WOStatus.sets.FIELD_OPEN;
const BID_CANCEL_PROTECTED_STATUSES = WOStatus.sets.DONE_THROUGH_PAID;
const WO_BID_COLUMNS = ['Bid_Group_ID', 'Duplicated_From', 'Owner_Notify_Override'];
const WO_BID_WINNER_COLUMNS = ['Tenant_Visible', 'Tenant_Notify_Created', 'Tenant_Notify_Updates', 'Owner_Notify_Override', 'Bid_Winner'];   // ensured only when a COPY is chosen as the keep_one winner
const BID_CANCEL_SMS_TYPE = 'vendor_job_cancelled';
const WO_DUP_ENSURE_COLUMNS = WO_BID_COLUMNS.concat(['Checklist', 'Managed_By', 'Entry_Notes', 'Owner_Notes', 'Vendor_Admin_Notes', 'Admin_Notes']);
// Copied verbatim from the source. Deliberately NOT here: Vendor_ID, Status, Scheduled_*,
// Completed_Date, Invoice_*, QBO_*, Customer_Charge, Deposit_*, Scope_ID, Approval_Stage,
// Estimate_Revised, Current_Estimate, Hold_Reason, Drive_Folder_*, Void*, Parent_WO_ID,
// Turnover_*, Recurring_*, Source, Intake_Message_ID, Share_Rev.
const WO_DUP_COPY_FIELDS = ['Property_ID', 'Unit_ID', 'Tenant_ID', 'Type', 'Trade', 'Description', 'Priority', 'Owner_WO_Ref', 'WO_Contact_Name', 'WO_Contact_Phone', 'Notes', 'Room', 'Vendor_Needs_Access', 'Managed_By', 'Entry_Notes', 'Owner_Notes', 'Vendor_Admin_Notes', 'Admin_Notes'];
const WO_DUP_TAP_TTL_MS = 8000;
const __woDupTapCache = new Map();           // "source|vendor" -> { exp, newWoId }   (double-tap guard)
let __woDupChain = Promise.resolve();        // per-isolate mutex for everything that changes group membership / appends a WO

function woDupSerialize(fn) {
  const run = __woDupChain.then(fn);
  // The chain only needs to know the previous job FINISHED; the caller still gets the real result
  // or the real error from `run`. The rejection handler logs so a failure is never invisible.
  __woDupChain = run.then(function () {}, function (e) { console.error('[wo-dup] serialized job failed: ' + ((e && e.message) || e)); });
  return run;
}

function isCancelledWOStatus(s) { const v = String(s == null ? '' : s).trim(); return v === 'Cancelled' || v === 'Canceled'; }
// A still-linked copy (both stamps) is Brett's internal shotgun and is hidden from owners — UNLESS it was chosen
// as the winner (Bid_Winner TRUE, set by keep_one). Pure; unit-tested.
function isHiddenBidCopy(w) {
  return !!(w && String(w.Duplicated_From || '').trim() && String(w.Bid_Group_ID || '').trim() && String(w.Bid_Winner || '').trim().toUpperCase() !== 'TRUE');
}
function isBidGroupWO(wo) { return !!(wo && (String(wo.Bid_Group_ID || '').trim() || String(wo.Duplicated_From || '').trim())); }
function nextBidGroupId(workorders) {
  const nums = (workorders || [])
    .map(w => String(w.Bid_Group_ID || '').match(/^BG-(\d+)$/))
    .filter(Boolean)
    .map(m => parseInt(m[1], 10))
    .filter(n => Number.isFinite(n) && n > 0);
  return `BG-${nums.length ? Math.max(...nums) + 1 : 1001}`;
}

// Checklist = JSON string [{t,done,code,why}]. The copy starts with every item NOT done and no
// "why not" reason. An unparseable value is copied untouched and REPORTED (never dropped quietly).
function woDupResetChecklist(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return { value: '', count: 0, ok: true };
  let arr;
  try { arr = JSON.parse(s); } catch (e) { return { value: s, count: 0, ok: false, error: 'not valid JSON (' + String((e && e.message) || e) + ')' }; }
  if (!Array.isArray(arr)) return { value: s, count: 0, ok: false, error: 'not a list' };
  const out = arr.map(it => (it && typeof it === 'object') ? Object.assign({}, it, { done: false, code: '', why: '' }) : it);
  return { value: JSON.stringify(out), count: out.length, ok: true };
}

// Log a bid-group telemetry row. A failed telemetry write is itself surfaced in result.warnings.
async function bidLogTelemetry(env, result, jobType, endpoint, success, notes) {
  try {
    await logTelemetry(env, { Source: 'worker', Job_Type: jobType, Skill_Or_Endpoint: endpoint, Success: success ? 'TRUE' : 'FALSE', Notes: String(notes || '').slice(0, 900) });
  } catch (e) {
    console.error('[wo-dup] telemetry write failed: ' + ((e && e.message) || e));
    if (result && Array.isArray(result.warnings)) result.warnings.push('Could not write the Ops_Telemetry row for this action: ' + String((e && e.message) || e));
  }
}
// A step failed AFTER the copy existed: record it, surface it, keep going with the other steps.
async function bidStepFailed(env, result, jobType, endpoint, what, e, ids) {
  const msg = `${what}: ${String((e && e.message) || e)}`;
  result.errors.push(msg);
  await bidLogTelemetry(env, result, jobType, endpoint, false, `${ids || ''} ${msg}`);
}

// Append N objects to a tab in ONE request (columns mapped by header, ID = max+1 sequentially),
// returning the IDs it used. Throws on any Sheets error. Callers verify with bidCountRows.
async function bidAppendRows(env, tab, objs) {
  if (!objs || !objs.length) return { ids: [] };
  invalidateTabCache(tab);
  const data = await sheetsRequest(env, 'GET', `/values/${tab}`);
  const rows = data.values || [];
  if (!rows.length || !rows[0].length) throw new Error(`${tab} tab has no header row`);
  const headers = rows[0];
  const idc = idColIndex(headers);
  let next = 1;
  for (let i = 1; i < rows.length; i++) { const n = parseInt((rows[i] && rows[i][idc]) || '0', 10); if (Number.isFinite(n) && n >= next) next = n + 1; }
  const ids = [];
  const out = objs.map(o => headers.map(h => {
    if (h === 'ID') { const id = String(next++); ids.push(id); return id; }
    return o[h] !== undefined && o[h] !== null ? String(o[h]) : '';
  }));
  await sheetsRequest(env, 'POST', `/values/${tab}:append?valueInputOption=RAW`, { values: out });
  return { ids };
}
async function bidCountRows(env, tab, pred) {
  invalidateTabCache(tab);
  return (await fetchTab(env, tab)).filter(pred).length;
}
async function bidFreshWOs(env) { invalidateTabCache('Work_Orders'); return await fetchTab(env, 'Work_Orders'); }

// Write fields on one WO and PROVE they landed (updateWOFields no-ops silently when a row or a
// column is missing). Returns the fresh row. Throws with the mismatching fields named.
async function bidWriteWOFields(env, woId, fields) {
  await updateWOFields(env, woId, fields);
  const row = findWO(await bidFreshWOs(env), woId);
  if (!row) throw new Error(`${woId} not found when re-reading after the write`);
  const bad = Object.keys(fields).filter(k => String(row[k] == null ? '' : row[k]) !== String(fields[k] == null ? '' : fields[k]));
  if (bad.length) throw new Error(`${woId}: the write did not stick for ${bad.join(', ')} (column missing or write dropped)`);
  return row;
}

// Guard used by addEstimateVersion / addVendorBill / addTimeEntry / approveInvoiceReview: a
// Cancelled (or Voided) bid-group copy can never take new money-side records, so a customer can
// never be billed for a shotgun copy that lost. Returns null (fine) or {message, logged}.
async function bidGroupWriteBlock(env, woId, what, whatEs, endpoint) {
  const id = String(woId == null ? '' : woId).trim();
  if (!id) return null;
  const wo = findWO(await fetchTab(env, 'Work_Orders'), id);
  if (!wo || !isBidGroupWO(wo)) return null;
  const cancelled = isCancelledWOStatus(wo.Status), voided = String(wo.Voided || '').toUpperCase() === 'TRUE';
  if (!cancelled && !voided) return null;
  const word = cancelled ? 'cancelled' : 'voided', wordEs = cancelled ? 'cancelado' : 'anulado';
  const message = `${id} has been ${word} (the job went to another vendor), so it cannot take new ${what}. Contact Ridge Co if this is a mistake. / ${id} fue ${wordEs} (el trabajo se asignó a otro proveedor), por lo que no se pueden agregar ${whatEs}. Comuníquese con Ridge Co si es un error.`;
  let logged = true;
  try {
    await logTelemetry(env, { Source: 'worker', Job_Type: 'bid_group_write_blocked', Skill_Or_Endpoint: endpoint, Success: 'FALSE', Notes: `${id} (${word} bid-group copy) refused new ${what}` });
  } catch (e) {
    logged = false;
    console.error('[wo-dup] could not log a blocked write for ' + id + ': ' + ((e && e.message) || e));
  }
  return { message, logged };
}

// POST /wo/duplicate -------------------------------------------------------------------------
// The only part that must be serialized: pick the group id + WO number, append the one complete
// row, and prove the number is unique. Returns { woId, groupId, stampedSource, repairedId }.
async function woDupAppendCopy(env, srcId, opts) {
  await ensureColumns(env, 'Work_Orders', WO_DUP_ENSURE_COLUMNS);
  invalidateTabCache('Work_Orders');
  const data = await sheetsRequest(env, 'GET', `/values/Work_Orders`);
  const rows = data.values || [];
  if (!rows.length) throw new Error('Work_Orders tab has no headers');
  const headers = rows[0];
  const missing = WO_DUP_ENSURE_COLUMNS.filter(c => !headers.includes(c));
  if (missing.length) throw new Error('Work_Orders is missing columns after ensureColumns: ' + missing.join(', '));
  const idc = idColIndex(headers);
  if (!headers.includes('ID')) throw new Error('Work_Orders tab has no ID column');
  const objs = rows.slice(1).map(r => { const o = {}; headers.forEach((h, i) => { o[h] = (r && r[i]) || ''; }); return o; });
  const src = objs.find(w => w.ID === srcId);
  if (!src) throw new Error(`${srcId} not found`);
  const groupId = String(src.Bid_Group_ID || '').trim() || nextBidGroupId(objs);
  const stampedSource = !String(src.Bid_Group_ID || '').trim();
  if (stampedSource) {
    try { await bidWriteWOFields(env, srcId, { Bid_Group_ID: groupId }); }
    catch (e) { throw new Error(`could not put ${srcId} into bid group ${groupId}: ${e.message}`); }
    invalidateTabCache('Work_Orders');
  }
  // WO number: max+1 over the whole tab (same rule as createWorkOrder) from the FRESH read above.
  let maxNum = 1000;
  for (const w of objs) { const n = parseInt(String(w.ID || '').replace(/\D/g, ''), 10); if (Number.isFinite(n) && n > maxNum) maxNum = n; }
  const woId = `WO-${maxNum + 1}`, now = opts.now;
  const cl = woDupResetChecklist(src.Checklist);
  const f = {};
  for (const k of WO_DUP_COPY_FIELDS) f[k] = src[k] || '';
  f.Checklist = cl.value;
  Object.assign(f, {
    ID: woId, Vendor_ID: '', Status: 'New', Priority: src.Priority || 'normal',
    // SILENT to the tenant and owner: the copy is invisible in the tenant portal, never texts a
    // tenant on create/updates, and owner notifications are 'off' (NOTIFY_TIERS.off = no events).
    Tenant_Visible: 'FALSE', Tenant_Notify_Created: 'FALSE', Tenant_Notify_Updates: 'FALSE', Owner_Notify_Override: 'off',
    Vendor_SMS_Sent: 'FALSE', Tenant_SMS_Sent: 'FALSE', Owner_Notified: 'FALSE',
    Created_By: opts.changedBy || 'admin', Created_Date: now,
    Bid_Group_ID: groupId, Duplicated_From: srcId,
  });
  const newRow = headers.map(h => (f[h] !== undefined ? String(f[h]) : ''));
  try {
    await sheetsRequest(env, 'POST', `/values/Work_Orders:append?valueInputOption=RAW`, { values: [newRow] });
  } catch (e) {
    if (stampedSource) {
      try { await bidWriteWOFields(env, srcId, { Bid_Group_ID: '' }); }
      catch (e2) { throw new Error(`append failed (${e.message}) AND ${srcId} could not be taken back out of bid group ${groupId} (${e2.message}) — clear Bid_Group_ID on ${srcId} by hand`); }
    }
    throw new Error(`append failed: ${e.message}`);
  }
  // Prove the WO number is unique. Another isolate (a tenant submit, the Buildium intake) can
  // race the in-isolate mutex; if the number was taken, renumber OUR row (identified by the
  // Duplicated_From + Created_Date + group stamps) — never touch theirs.
  let finalId = woId, repaired = false;
  for (let attempt = 0; attempt < 3; attempt++) {
    invalidateTabCache('Work_Orders');
    const chk = (await sheetsRequest(env, 'GET', `/values/Work_Orders`)).values || [];
    const ch = chk[0] || headers;
    const cIdc = idColIndex(ch), cDup = ch.indexOf(WO_BID_COLUMNS[1]), cCreated = ch.indexOf('Created_Date'), cGroup = ch.indexOf(WO_BID_COLUMNS[0]);
    if (cDup < 0 || cCreated < 0 || cGroup < 0) throw new Error('Work_Orders lost a required column while verifying the new WO number');
    const same = [];
    for (let i = 1; i < chk.length; i++) if (String((chk[i] || [])[cIdc] || '') === finalId) same.push(i);
    if (same.length === 1) return { woId: finalId, groupId, stampedSource, repairedId: repaired };
    if (same.length === 0) throw new Error(`the new row ${finalId} could not be found after appending`);
    const mine = same.filter(i => String(chk[i][cDup] || '') === srcId && String(chk[i][cCreated] || '') === now && String(chk[i][cGroup] || '') === groupId);
    if (!mine.length) throw new Error(`WO number ${finalId} is shared by ${same.length} rows and none is identifiable as this copy`);
    let mx = 1000;
    for (let i = 1; i < chk.length; i++) { const n = parseInt(String((chk[i] || [])[cIdc] || '').replace(/\D/g, ''), 10); if (Number.isFinite(n) && n > mx) mx = n; }
    const renumbered = `WO-${mx + 1}`;
    await sheetsRequest(env, 'POST', `/values:batchUpdate`, { valueInputOption: 'RAW', data: [{ range: `Work_Orders!${col(cIdc)}${mine[mine.length - 1] + 1}`, values: [[renumbered]] }] });
    finalId = renumbered; repaired = true;
  }
  throw new Error(`could not settle on a unique WO number for the copy of ${srcId} after 3 attempts — check Work_Orders for a duplicate row`);
}

async function woDuplicate(env, body) {
  const _t0 = Date.now();
  body = body || {};
  const result = {
    ok: false, created: false, source_wo_id: String(body.source_wo_id || '').trim(), new_wo_id: '', bid_group_id: '',
    vendor_id: '', vendor_name: '',
    vendor_sms: { status: 'skipped', reason: 'No vendor chosen — the copy was created unassigned.' },
    copied: { attachments: 0, tenants: 0, checklist: false, checklist_items: 0 },
    warnings: [], errors: [],
  };
  let tapKey = '', ownsTap = false;       // the double-tap claim this call holds (released again if this call fails before creating)
  const fail = async (status, msg, extra) => {
    if (ownsTap && !result.created) __woDupTapCache.delete(tapKey);
    result.errors.push(msg); result.error = msg;
    if (extra) Object.assign(result, extra);
    await bidLogTelemetry(env, result, 'wo_duplicate', '/wo/duplicate', false, `source=${result.source_wo_id} ${msg}`);
    return json(result, status);
  };
  const srcId = result.source_wo_id, vendorId = String(body.vendor_id || '').trim();
  const changedBy = String(body.updated_by || 'admin');
  if (!srcId) return await fail(400, 'source_wo_id required');
  // One copy per tap: an identical request seconds later (double-tap, network retry) is refused,
  // and the claim is taken synchronously (no await between the check and the set) so two requests
  // arriving together cannot both pass. It is handed back if this call ends up creating nothing.
  tapKey = srcId + '|' + vendorId;
  const nowMs = Date.now();
  for (const [k, v] of __woDupTapCache) if (v.exp <= nowMs) __woDupTapCache.delete(k);
  const tap = __woDupTapCache.get(tapKey);
  if (tap) return await fail(409, `A copy of ${srcId}${vendorId ? ' for vendor ' + vendorId : ''} was just ${tap.newWoId ? 'created (' + tap.newWoId + ')' : 'started'} — this repeat tap was ignored so you don't get two copies.`, { previous_new_wo_id: tap.newWoId || '' });
  __woDupTapCache.set(tapKey, { exp: nowMs + WO_DUP_TAP_TTL_MS, newWoId: '' }); ownsTap = true;
  const workorders = await bidFreshWOs(env);
  const src = findWO(workorders, srcId);
  if (!src) return await fail(404, `Work order ${srcId} not found`);
  if (String(src.Voided || '').toUpperCase() === 'TRUE') return await fail(400, `${srcId} is voided — it cannot be duplicated.`);
  if (String(src.Type || '') === 'addon' || String(src.Parent_WO_ID || '').trim()) return await fail(400, `${srcId} is vendor-found additional work — it cannot be duplicated.`);
  const srcStatus = String(src.Status || 'New').trim() || 'New';
  if (!WO_DUP_ALLOWED_STATUSES.includes(srcStatus)) return await fail(400, `${srcId} is ${srcStatus} — only open jobs (${WO_DUP_ALLOWED_STATUSES.join(', ')}) can be duplicated.`);
  if (String(src.Turnover_Group_ID || '').trim()) result.warnings.push(`${srcId} is part of turnover group ${src.Turnover_Group_ID}; the copy is NOT linked to the turnover.`);
  let vendor = null;
  if (vendorId) {
    vendor = (await fetchTab(env, 'Vendors')).find(v => String(v.ID) === vendorId);
    if (!vendor) return await fail(404, `Vendor ${vendorId} not found`);
    if (String(vendor.Active || '').toUpperCase() === 'FALSE') return await fail(400, `${vendor.Name || 'Vendor ' + vendorId} is inactive — pick an active vendor.`);
    if (String(src.Managed_By || '') === 'Owner') return await fail(400, `${srcId} is being handled by the property owner (Managed_By = Owner), so a vendor cannot be assigned to a copy of it.`);
    // Same vendor twice in one bid group is almost certainly a mis-tap, not a strategy.
    const gid = String(src.Bid_Group_ID || '').trim();
    const sameVendor = workorders.filter(w => (w.ID === srcId || (gid && w.Bid_Group_ID === gid)) && String(w.Vendor_ID || '') === vendorId && !isCancelledWOStatus(w.Status) && String(w.Voided || '').toUpperCase() !== 'TRUE');
    if (sameVendor.length) return await fail(409, `${vendor.Name || 'This vendor'} already has ${sameVendor[0].ID} in this bid group — pick a different vendor or create the copy without a vendor.`);
    result.vendor_id = vendorId; result.vendor_name = vendor.Name || '';
  }

  // 1. Create + link the copy (serialized; one complete row; WO number proven unique).
  const now = new Date().toISOString();
  let created;
  try { created = await woDupSerialize(() => woDupAppendCopy(env, srcId, { now, changedBy })); }
  catch (e) { return await fail(500, `Could not create the copy: ${String((e && e.message) || e)}`); }
  const newId = created.woId;
  __woDupTapCache.set(tapKey, { exp: Date.now() + WO_DUP_TAP_TTL_MS, newWoId: newId });
  result.created = true; result.new_wo_id = newId; result.bid_group_id = created.groupId;
  if (created.repairedId) result.warnings.push(`Another record took the WO number first, so the copy was renumbered to ${newId}.`);
  const copyRow = findWO(await bidFreshWOs(env), newId);
  if (!copyRow) await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', 'The new row could not be re-read after creating it', new Error('row not found'), `${srcId}->${newId}`);
  else {
    const cl = woDupResetChecklist(src.Checklist);
    result.copied.checklist = !!cl.value; result.copied.checklist_items = cl.count;
    if (!cl.ok) result.warnings.push(`The checklist on ${srcId} is ${cl.error}; it was copied as-is (not reset).`);
    if (String(copyRow.Bid_Group_ID || '') !== created.groupId || String(copyRow.Duplicated_From || '') !== srcId) {
      await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', 'The copy row did not keep its bid group / Duplicated_From stamps', new Error(`got group=${copyRow.Bid_Group_ID || ''} from=${copyRow.Duplicated_From || ''}`), `${srcId}->${newId}`);
    }
  }

  // 2. Tenant links (WO_Tenants): same active tenants as the source. Silent: no message is sent.
  try {
    const wt = (await fetchTab(env, 'WO_Tenants')).filter(r => r.WO_ID === srcId && r.Active !== 'FALSE');
    const objs = wt.map(r => ({ WO_ID: newId, Tenant_ID: r.Tenant_ID, Tenant_Name: r.Tenant_Name, Tenant_Phone: r.Tenant_Phone, Added_By: 'duplicate-of-' + srcId, Added_Date: now, Active: 'TRUE' }));
    if (objs.length) {
      await bidAppendRows(env, 'WO_Tenants', objs);
      const n = await bidCountRows(env, 'WO_Tenants', r => r.WO_ID === newId && r.Active !== 'FALSE');
      if (n !== objs.length) throw new Error(`expected ${objs.length} tenant link(s) on ${newId}, found ${n}`);
    }
    result.copied.tenants = objs.length;
  } catch (e) { await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', `Tenant links were not copied to ${newId}`, e, `${srcId}->${newId}`); }

  // 3. Photos / videos (Attachments): the SAME Drive file re-pointed at the new WO (no Drive copy).
  // Vendor cost documents (receipt/bill/invoice) and anything tied to a receipt or invoice stay put.
  try {
    const atts = (await fetchTab(env, 'Attachments')).filter(a => a.WO_ID === srcId && a.Active !== 'FALSE'
      && !NON_SHARE_FILE_TYPES.includes(String(a.File_Type || '').toLowerCase())
      && !String(a.Receipt_ID || '').trim() && !String(a.Invoice_ID || '').trim());
    const today = now.split('T')[0];
    const objs = atts.map(a => ({ WO_ID: newId, File_Type: a.File_Type, Drive_File_ID: a.Drive_File_ID, Drive_URL: a.Drive_URL, File_Name: a.File_Name, Uploaded_By: a.Uploaded_By, Created_Date: today, Notes: a.Notes, Active: 'TRUE', Mime_Type: a.Mime_Type }));
    if (objs.length) {
      await bidAppendRows(env, 'Attachments', objs);
      const n = await bidCountRows(env, 'Attachments', r => r.WO_ID === newId && r.Active !== 'FALSE');
      if (n !== objs.length) throw new Error(`expected ${objs.length} attachment(s) on ${newId}, found ${n}`);
    }
    result.copied.attachments = objs.length;
  } catch (e) { await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', `Photos/videos were not copied to ${newId}`, e, `${srcId}->${newId}`); }

  // 4. WO_Audit trail on both WOs (so the history explains where the copy came from).
  try {
    const audit = [
      { WO_ID: newId, Changed_By: changedBy, Changed_By_Role: 'admin', Field: 'Duplicated', Old_Value: '', New_Value: srcId, Timestamp: now, Notes: `Copy of ${srcId} in bid group ${created.groupId} (silent to tenant/owner)` },
      { WO_ID: srcId, Changed_By: changedBy, Changed_By_Role: 'admin', Field: 'Duplicated', Old_Value: '', New_Value: newId, Timestamp: now, Notes: `Copy ${newId} created in bid group ${created.groupId}` },
    ];
    if (created.stampedSource) audit.push({ WO_ID: srcId, Changed_By: changedBy, Changed_By_Role: 'admin', Field: 'Bid_Group_ID', Old_Value: '', New_Value: created.groupId, Timestamp: now, Notes: 'Started a bid group' });
    await bidAppendRows(env, 'WO_Audit', audit);
    const n = await bidCountRows(env, 'WO_Audit', r => r.Field === 'Duplicated' && r.Timestamp === now && (r.WO_ID === newId || r.WO_ID === srcId));
    if (n < 2) throw new Error(`expected 2 audit rows, found ${n}`);
  } catch (e) { await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', 'The WO_Audit rows were not written', e, `${srcId}->${newId}`); }

  // 5. Assign the chosen vendor: the normal "new job" SMS, vendor only (notify_tenant:false),
  // bypassing quiet hours for THIS feature only. The outcome is returned verbatim.
  if (vendor) {
    try {
      const ares = await assignVendor(env, { wo_id: newId, vendor_id: vendorId, notify: true, notify_tenant: false }, { bypassQuietHours: true });
      let aj = null, parseErr = '';
      try { aj = await ares.json(); } catch (pe) { parseErr = String((pe && pe.message) || pe); }
      if (!aj) throw new Error(`assign returned an unreadable response (HTTP ${ares.status}) ${parseErr}`);
      if (ares.status !== 200 || !aj.success) throw new Error(aj.error || `assign failed (HTTP ${ares.status})`);
      result.vendor_sms = aj.vendor_sms_detail || { status: aj.vendor_sms ? 'sent' : 'failed', reason: aj.vendor_sms ? 'Sent' : 'The assign call did not report why the text was not sent.' };
      if (aj.tenant_sms) result.errors.push(`UNEXPECTED: the assign step reported a tenant text for ${newId}. Check the tenant's messages.`);
      const after = findWO(await bidFreshWOs(env), newId);
      if (!after || String(after.Vendor_ID || '') !== vendorId || String(after.Status || '') !== 'Assigned') {
        throw new Error(`after assigning, ${newId} reads back Vendor_ID=${after ? after.Vendor_ID : '(row missing)'} Status=${after ? after.Status : ''}`);
      }
    } catch (e) {
      result.vendor_sms = { status: 'failed', reason: `The vendor was NOT assigned and NOT texted: ${String((e && e.message) || e)}` };
      await bidStepFailed(env, result, 'wo_duplicate', '/wo/duplicate', `Vendor ${vendor.Name || vendorId} was not assigned to ${newId}`, e, `${srcId}->${newId}`);
    }
    if (result.vendor_sms.status !== 'sent') result.warnings.push(`Vendor text ${String(result.vendor_sms.status).toUpperCase()}: ${result.vendor_sms.reason}`);
  }

  result.ok = result.errors.length === 0;
  await bidLogTelemetry(env, result, 'wo_duplicate', '/wo/duplicate', result.ok, `source=${srcId} new=${newId} group=${created.groupId} vendor=${vendorId || 'none'} sms=${result.vendor_sms.status} attachments=${result.copied.attachments} tenants=${result.copied.tenants} errors=${result.errors.length} ms=${Date.now() - _t0}`);
  return json(result, 200);
}

// POST /wo/bid-group/unlink -------------------------------------------------------------------
async function woBidGroupUnlink(env, body) {
  body = body || {};
  const result = { ok: false, wo_id: String(body.wo_id || '').trim(), group_id: '', cleared: [], warnings: [], errors: [] };
  const fail = async (status, msg) => { result.errors.push(msg); result.error = msg; await bidLogTelemetry(env, result, 'wo_bid_unlink', '/wo/bid-group/unlink', false, `${result.wo_id} ${msg}`); return json(result, status); };
  if (!result.wo_id) return await fail(400, 'wo_id required');
  const changedBy = String(body.updated_by || 'admin');
  try {
    return await woDupSerialize(async () => {
      const all = await bidFreshWOs(env);
      const wo = findWO(all, result.wo_id);
      if (!wo) return await fail(404, `Work order ${result.wo_id} not found`);
      const gid = String(wo.Bid_Group_ID || '').trim();
      if (!gid) return await fail(400, `${result.wo_id} is not in a bid group, so there is nothing to unlink.`);
      result.group_id = gid;
      const others = all.filter(w => w.Bid_Group_ID === gid && w.ID !== wo.ID);
      const toClear = [wo].concat(others.length === 1 ? others : []);
      for (const w of toClear) {
        try { await bidWriteWOFields(env, w.ID, { Bid_Group_ID: '' }); result.cleared.push(w.ID); }
        catch (e) { await bidStepFailed(env, result, 'wo_bid_unlink', '/wo/bid-group/unlink', `Could not clear the bid group on ${w.ID}`, e, w.ID); }
      }
      if (others.length === 1) result.warnings.push(`${gid} had only ${others[0].ID} left, so it was released from the group too.`);
      try {
        const now = new Date().toISOString();
        await bidAppendRows(env, 'WO_Audit', result.cleared.map(id => ({ WO_ID: id, Changed_By: changedBy, Changed_By_Role: 'admin', Field: 'Bid_Group_ID', Old_Value: gid, New_Value: '', Timestamp: now, Notes: id === wo.ID ? `Unlinked from bid group ${gid}` : `Released from bid group ${gid} (last member)` })));
      } catch (e) { await bidStepFailed(env, result, 'wo_bid_unlink', '/wo/bid-group/unlink', 'The WO_Audit rows were not written', e, result.wo_id); }
      result.ok = result.errors.length === 0 && result.cleared.includes(wo.ID);
      await bidLogTelemetry(env, result, 'wo_bid_unlink', '/wo/bid-group/unlink', result.ok, `wo=${wo.ID} group=${gid} cleared=${result.cleared.join(',')}`);
      return json(result, result.ok ? 200 : 500);
    });
  } catch (e) { return await fail(500, `Unlink failed: ${String((e && e.message) || e)}`); }
}

// GET /wo/bid-group?wo_id=...|group_id=... -------------------------------------------------------
async function woBidGroupGet(env, url) {
  const woId = String(url.searchParams.get('wo_id') || '').trim(), groupParam = String(url.searchParams.get('group_id') || '').trim();
  if (!woId && !groupParam) return json({ error: 'wo_id or group_id required' }, 400);
  const [all, vendors, estimates] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Vendors'), fetchTab(env, 'Estimates')]);
  let wo = null, gid = groupParam;
  if (woId) { wo = findWO(all, woId); if (!wo) return json({ error: `Work order ${woId} not found` }, 404); gid = String(wo.Bid_Group_ID || '').trim(); }
  if (!gid) return json({ ok: true, group_id: '', members: [], duplicated_from: wo ? String(wo.Duplicated_From || '') : '', note: wo && wo.Duplicated_From ? `Independent copy of ${wo.Duplicated_From} (unlinked)` : 'Not in a bid group' });
  const members = all.filter(w => w.Bid_Group_ID === gid).map(w => {
    const v = w.Vendor_ID ? vendors.find(x => String(x.ID) === String(w.Vendor_ID)) : null;
    const est = estimates.filter(e => e.WO_ID === w.ID && String(e.Active || '').toUpperCase() !== 'FALSE').sort((a, b) => (parseInt(b.Version || '0', 10) || 0) - (parseInt(a.Version || '0', 10) || 0))[0];
    return {
      id: w.ID, status: w.Status || 'New', vendor_id: w.Vendor_ID || '', vendor_name: v ? (v.Name || '') : '',
      duplicated_from: w.Duplicated_From || '', is_original: !String(w.Duplicated_From || '').trim(),
      voided: String(w.Voided || '').toUpperCase() === 'TRUE', scheduled_date: w.Scheduled_Date || '', created_date: w.Created_Date || '',
      is_winner: String(w.Bid_Winner || '').trim().toUpperCase() === 'TRUE', tenant_visible: String(w.Tenant_Visible || '').trim().toUpperCase() !== 'FALSE',   // same predicate the tenant portal uses (only an explicit FALSE hides)
      latest_estimate: est ? { version: est.Version || '', subtotal: est.Subtotal || '', status: est.Status || '' } : null,
    };
  }).sort((a, b) => (a.is_original === b.is_original ? String(a.created_date).localeCompare(String(b.created_date)) : (a.is_original ? -1 : 1)));
  return json({ ok: true, group_id: gid, members, this_wo_id: woId });
}

// Pure classifier (unit-tested): may this bid-group member be cancelled, and what should Brett know?
function bidCancelClassify(wo, ctx) {
  const reasons = [], warnings = [];
  const id = wo.ID, st = String(wo.Status || 'New').trim() || 'New';
  const num = v => { const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
  let kind = 'cancel';
  if (isCancelledWOStatus(st)) { reasons.push('Already cancelled'); kind = 'already'; }
  if (String(wo.Voided || '').toUpperCase() === 'TRUE') { reasons.push('Voided'); kind = kind === 'already' ? kind : 'skip'; }
  if (BID_CANCEL_PROTECTED_STATUSES.includes(st)) { reasons.push(`Status is ${st} — finished work is never auto-cancelled`); kind = 'skip'; }
  const bills = (ctx.bills || []).filter(b => b.WO_ID === id && String(b.Active || '').toUpperCase() !== 'FALSE');
  if (bills.length) { reasons.push(`Has ${bills.length} vendor bill${bills.length > 1 ? 's' : ''}`); kind = 'skip'; }
  const times = (ctx.timeEntries || []).filter(t => t.WO_ID === id && String(t.Active || '').toUpperCase() !== 'FALSE');
  if (times.length) { reasons.push(`Has ${times.length} time entr${times.length > 1 ? 'ies' : 'y'}`); kind = 'skip'; }
  if (num(wo.Customer_Charge) > 0) { reasons.push(`Customer charge $${num(wo.Customer_Charge).toFixed(2)} is set`); kind = 'skip'; }
  if (String(wo.QBO_Invoice_Number || '').trim()) { reasons.push(`QuickBooks invoice ${wo.QBO_Invoice_Number}`); kind = 'skip'; }
  if (String(wo.QBO_Bill_Number || '').trim()) { reasons.push(`QuickBooks bill ${wo.QBO_Bill_Number}`); kind = 'skip'; }
  if (String(wo.Invoice_ID || '').trim()) { reasons.push(`Linked to invoice ${wo.Invoice_ID}`); kind = 'skip'; }
  if (num(wo.Deposit_Amount) > 0 || String(wo.Deposit_QB_Bill_Number || '').trim()) { reasons.push('Has a vendor deposit'); kind = 'skip'; }
  if (String(wo.Scope_ID || '').trim()) { reasons.push(`Linked to scope proposal ${wo.Scope_ID}`); kind = 'skip'; }
  const irs = (ctx.invoiceReview || []).filter(r => r.WO_ID === id && String(r.Active || '').toUpperCase() !== 'FALSE');
  if (irs.length) { reasons.push('Has an invoice review / approval row'); kind = 'skip'; }
  if (kind === 'cancel') {
    if (WOStatus.sets.VENDOR_STARTED.includes(st)) warnings.push(`Vendor has already ${st === 'Accepted' ? 'accepted' : 'started'} this job; they will be texted that it is cancelled`);
    if ((ctx.workorders || []).some(w => String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() === id)) warnings.push('Has additional-work children; the cancel is refused if any are still live');
  }
  return { kind, reasons, warnings };
}

// ── Vendor cancellation text (Oct 13 2026, Brett: "tell the vendor.") ────────────────────────────────
// Same vendor-text conventions as the "new job" text in assignVendor: bilingual by Vendor Language (hand-built, so
// already_localized), WO number first, trade + property address (with unit/room), nothing about the tenant or owner.
function bidWoAddress(wo, property, unit, isSpanish) {
  const room = String((wo && wo.Room) || '').trim();
  if (!property) return isSpanish ? 'la propiedad' : 'the property';
  return `${property.Address}${unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : ''}${room ? ' (' + room + ')' : ''}`;
}
function bidCancelVendorMessage(woId, trade, address, isSpanish) {
  const t = String(trade || '').trim();
  const en = `[${woId}] CANCELLED: the ${t ? t + ' ' : ''}job at ${address} is no longer needed. Please do not do this work. Thank you.`;
  const es = `[${woId}] CANCELADO: el trabajo${t ? ' de ' + t : ''} en ${address} ya no es necesario. Por favor no realice este trabajo. Gracias.`;
  return { en, es, text: isSpanish ? es : en, language: isSpanish ? 'es' : 'en' };
}
// Turns smsGatedSend's return value into the plain-words outcome the Hub shows (sent / held / failed / skipped + why).
// One copy of this mapping, used by assignVendor (new-job text) and the bid-group cancel text.
function vendorSmsDetailFromResult(env, r, lang, msg) {
  if (r.sent) return { status: 'sent', reason: r.test_mode ? 'TEST MODE IS ON: the text went to the Hub test number, NOT to the vendor' : 'Text sent to the vendor', test_mode: !!r.test_mode, language: lang, message_body: r.message_body || msg };
  if (r.held_for_quiet_hours) return { status: 'held', reason: `Held for quiet hours — it will send after ${r.send_after}`, language: lang, message_body: r.message_body || msg };
  if (r.send_ok === false) return { status: 'failed', reason: `Blocked, not sent: ${r.gate_snapshot}`, language: lang, message_body: r.message_body || msg };
  if (!r.recipient_phone) return { status: 'failed', reason: 'Vendor phone number is missing or invalid — no text was sent', language: lang, message_body: r.message_body || msg };
  if (env.__STAGING__ ?? isStaging(env)) return { status: 'skipped', reason: 'STAGING: texts are stubbed, so nothing was really sent (the message was only logged)', language: lang, message_body: r.message_body || msg };
  return { status: 'failed', reason: 'Twilio rejected or failed to send the text (see Message_Queue)', language: lang, message_body: r.message_body || msg };
}
// What WILL / WOULD happen for one cancelled copy's vendor. Pure (no I/O). Statuses: will_send | skipped | cannot_send.
// keptVendors: Map vendorId -> id of a job that stays open for that vendor (they are not texted about the cancelled one).
function bidCancelVendorPlan(row, vendor, wo, property, unit, keptVendors) {
  const vid = String((row && row.vendor_id) || '').trim();
  const base = { vendor_id: vid, vendor_name: (row && row.vendor_name) || '', wo_id: row.wo_id };
  if (!vid) return Object.assign(base, { status: 'skipped', reason: 'No vendor is assigned, so nobody is texted.' });
  if (!vendor) return Object.assign(base, { status: 'cannot_send', reason: `Vendor ${vid} was not found in the Vendors tab, so nobody could be texted. Call whoever was assigned.` });
  const name = vendor.Name || ('Vendor ' + vid);
  base.vendor_name = name;
  const keptWo = keptVendors && keptVendors.get(vid);
  if (keptWo) return Object.assign(base, { status: 'skipped', reason: `${name} also has ${keptWo}, which stays open, so they are not texted about ${row.wo_id} (it would be confusing).` });
  if (!normalizePhone(vendor.Phone)) return Object.assign(base, { status: 'cannot_send', reason: `${name} has no valid phone number on file, so they cannot be texted. Call them.` });
  const es = vendor.Language === 'es';
  const m = bidCancelVendorMessage(row.wo_id, wo && wo.Trade, bidWoAddress(wo, property, unit, es), es);
  return Object.assign(base, { status: 'will_send', reason: `${name} will be texted that ${row.wo_id} is cancelled.`, language: m.language, message_body: m.text, message_en: m.en });
}
// Sends (or declines to send) the cancellation text for ONE copy that was just cancelled. NEVER throws and never touches the
// cancel itself: every outcome is returned, counted in result.summary.vendor_texts, and a failure is also logged to
// Ops_Telemetry and put in result.warnings (+ needs_attention). At most one text per WO, ever (Message_Queue is checked).
async function bidCancelNotifyVendor(env, result, row, wo, vendor, property, unit, keptVendors) {
  const plan = bidCancelVendorPlan(row, vendor, wo, property, unit, keptVendors);
  const out = { wo_id: row.wo_id, vendor_id: plan.vendor_id, vendor_name: plan.vendor_name, status: plan.status, reason: plan.reason, language: plan.language || '', message_body: plan.message_body || '', message_en: plan.message_en || '' };
  try {
    if (plan.status === 'cannot_send') out.status = 'failed';
    else if (plan.status === 'will_send') {
      await ensureSmsInfra(env);
      invalidateTabCache(MSG_QUEUE_TAB);
      const prior = (await fetchTab(env, MSG_QUEUE_TAB)).filter(q => q.WO_ID === row.wo_id && q.Message_Type === BID_CANCEL_SMS_TYPE && q.Recipient_Type === 'vendor' && String(q.Active || '').toUpperCase() !== 'FALSE' && (q.Status === 'pending' || q.Status === 'sent'));
      if (prior.length) { out.status = 'skipped'; out.reason = `A cancellation text for ${row.wo_id} was already ${prior[0].Status === 'sent' ? 'sent' : 'queued'} (${prior[0].Created_Date || 'earlier'}), so no second one was sent.`; }
      else {
        const es = plan.language === 'es';
        const r = await smsGatedSend(env, { wo_id: row.wo_id, message_type: BID_CANCEL_SMS_TYPE, recipient_type: 'vendor', vendor, property, message_body: plan.message_body, already_localized: true, original_body: es ? plan.message_en : '', translated_to: es ? 'es' : '' });
        const d = vendorSmsDetailFromResult(env, r, plan.language, plan.message_body);
        out.status = d.status; out.reason = d.reason; out.message_body = d.message_body || out.message_body; out.queued_id = r.queued_id || '';
        if (d.test_mode) out.test_mode = true;
      }
    }
  } catch (e) {
    out.status = 'failed'; out.reason = `The cancellation text could not be queued or sent: ${String((e && e.message) || e)}`;
  }
  const c = result.summary.vendor_texts;
  c[out.status] = (c[out.status] || 0) + 1;
  result.vendor_texts.push(out);
  if (out.status === 'failed') {
    result.needs_attention = true;
    result.warnings.push(`Vendor text FAILED for ${out.wo_id}${out.vendor_name ? ' (' + out.vendor_name + ')' : ''}: ${out.reason} The job IS cancelled, but the vendor was not told: call them.`);
  }
  if (out.status === 'sent' || out.status === 'held' || out.status === 'failed') {
    await bidLogTelemetry(env, result, 'wo_bid_cancel_vendor_sms', '/wo/bid-group/cancel', out.status !== 'failed', `${out.wo_id} vendor=${out.vendor_id} status=${out.status} ${out.reason}`);
  }
  return out;
}

// ── Kept copy notifies like a normal work order (Oct 13 2026, Brett: "kept copy notifies according to that work order's settings.") ──
// A bid-group copy is created silent (Tenant_Visible/Notify FALSE, Owner_Notify_Override 'off'). When Brett KEEPS a copy it must behave
// like the work order it stands in for. A normal WO carries Tenant_Visible / Tenant_Notify_Created / Tenant_Notify_Updates (TRUE unless
// someone turned them off for that WO) and an optional Owner_Notify_Override ('' = the owner's own setting by priority, see shouldNotifyOwner).
// So the winner takes those four values from the ORIGINAL work order of its group (walking Duplicated_From up to the row with none);
// if the original cannot be found it gets the normal defaults (TRUE / TRUE / TRUE / ''). Pure; unit-tested.
function bidWinnerNotifyPlan(all, winner) {
  const byId = id => (all || []).find(w => String(w.ID) === String(id));
  let cur = winner, hops = 0, source = null;
  while (cur && String(cur.Duplicated_From || '').trim() && hops < 12) {
    const next = byId(String(cur.Duplicated_From).trim());
    if (!next || next.ID === winner.ID) { cur = null; break; }
    cur = next; hops++;
  }
  if (cur && cur !== winner && !String(cur.Duplicated_From || '').trim()) source = cur;
  const flag = v => (String(v == null ? '' : v).trim().toUpperCase() === 'FALSE' ? 'FALSE' : 'TRUE');
  let ov = source ? String(source.Owner_Notify_Override == null ? '' : source.Owner_Notify_Override).trim() : '';
  if (ov && !Object.prototype.hasOwnProperty.call(NOTIFY_TIERS, ov)) ov = '';
  const settings = {
    Tenant_Visible: source ? flag(source.Tenant_Visible) : 'TRUE',
    Tenant_Notify_Created: source ? flag(source.Tenant_Notify_Created) : 'TRUE',
    Tenant_Notify_Updates: source ? flag(source.Tenant_Notify_Updates) : 'TRUE',
    Owner_Notify_Override: ov,
  };
  const tenantPart = settings.Tenant_Visible !== 'TRUE' ? 'hidden from the tenant' : (settings.Tenant_Notify_Updates === 'TRUE' ? 'the tenant can see it and gets its status texts' : 'the tenant can see it but gets no status texts');
  const ownerPart = ov === '' ? "the owner is notified per the owner's own setting" : (ov === 'off' ? 'the owner gets no texts about it' : `the owner is notified at the "${ov}" level`);
  const src = source ? `the original ${source.ID}` : 'the normal defaults (the original could not be found)';
  return { settings, source_wo_id: source ? source.ID : '', from_original: !!source, note: `${winner.ID} now follows the normal work order rules (copied from ${src}): ${tenantPart}; ${ownerPart}. No text is sent right now; later status changes notify as usual.` };
}
function bidWinnerNotifyDiff(fresh, settings) {
  const want = {};
  const up = v => String(v == null ? '' : v).trim().toUpperCase();
  for (const k of ['Tenant_Visible', 'Tenant_Notify_Created', 'Tenant_Notify_Updates']) if (up(fresh[k]) !== settings[k]) want[k] = settings[k];
  if (String(fresh.Owner_Notify_Override == null ? '' : fresh.Owner_Notify_Override).trim() !== settings.Owner_Notify_Override) want.Owner_Notify_Override = settings.Owner_Notify_Override;
  return want;
}

// POST /wo/bid-group/cancel --------------------------------------------------------------------
async function woBidGroupCancel(env, body) {
  body = body || {};
  const mode = String(body.mode || '').trim();
  const confirmed = body.confirm === true && body.dry_run !== true;
  const result = {
    ok: false, dry_run: !confirmed, mode, group_id: '', keep_wo_id: String(body.keep_wo_id || '').trim(), results: [], winner: null,
    summary: { would_cancel: 0, would_skip: 0, cancelled: 0, skipped: 0, failed: 0, kept: 0, already_cancelled: 0, would_text: 0, vendor_texts: { sent: 0, held: 0, failed: 0, skipped: 0 } },
    vendor_texts: [], vendor_text_notices: [], quiet_hours_now: false, needs_attention: false,
    warnings: [], errors: [],
  };
  const fail = async (status, msg) => { result.errors.push(msg); result.error = msg; await bidLogTelemetry(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', false, `${body.group_id || body.wo_id || ''} ${msg}`); return json(result, status); };
  if (!['all', 'duplicates', 'keep_one'].includes(mode)) return await fail(400, "mode must be 'all', 'duplicates' or 'keep_one'");
  if (mode === 'keep_one' && !result.keep_wo_id) return await fail(400, 'keep_wo_id is required for mode keep_one');
  const changedBy = String(body.updated_by || 'admin');
  const run = async () => {
    const all = await bidFreshWOs(env);
    let gid = String(body.group_id || '').trim();
    if (!gid) {
      const w = findWO(all, String(body.wo_id || '').trim());
      if (!w) return await fail(404, `Work order ${body.wo_id || ''} not found`);
      gid = String(w.Bid_Group_ID || '').trim();
      if (!gid) return await fail(400, `${w.ID} is not in a bid group.`);
    }
    result.group_id = gid;
    const members = all.filter(w => w.Bid_Group_ID === gid);
    if (!members.length) return await fail(404, `Bid group ${gid} has no members`);
    if (mode === 'keep_one' && !members.some(m => m.ID === result.keep_wo_id)) return await fail(400, `${result.keep_wo_id} is not a member of ${gid}.`);
    // keep_one (Oct 13 2026): the kept member is the winner. Keeping a cancelled/voided job would leave nothing alive.
    const winnerWO = mode === 'keep_one' ? members.find(m => m.ID === result.keep_wo_id) : null;
    if (winnerWO && isCancelledWOStatus(winnerWO.Status)) return await fail(400, `${winnerWO.ID} is already cancelled, so it cannot be the one you keep. Pick a job that is still open.`);
    if (winnerWO && String(winnerWO.Voided || '').toUpperCase() === 'TRUE') return await fail(400, `${winnerWO.ID} is voided, so it cannot be the one you keep. Pick a job that is still open.`);
    let winnerPlan = null;
    if (winnerWO) {
      const winnerIsOriginal = !String(winnerWO.Duplicated_From || '').trim();
      const visBefore = String(winnerWO.Tenant_Visible == null ? '' : winnerWO.Tenant_Visible).trim();
      winnerPlan = winnerIsOriginal ? null : bidWinnerNotifyPlan(all, winnerWO);
      const willChange = winnerPlan ? Object.keys(bidWinnerNotifyDiff(winnerWO, winnerPlan.settings)) : [];
      result.winner = {
        wo_id: winnerWO.ID, is_original: winnerIsOriginal, tenant_visible_before: visBefore,
        already_visible: !winnerIsOriginal && visBefore.toUpperCase() === 'TRUE' && String(winnerWO.Bid_Winner || '').trim().toUpperCase() === 'TRUE',
        will_become_tenant_visible: !winnerIsOriginal && !!winnerPlan && winnerPlan.settings.Tenant_Visible === 'TRUE' && visBefore.toUpperCase() !== 'TRUE', became_tenant_visible: false,
        notify: winnerPlan ? { settings: winnerPlan.settings, source_wo_id: winnerPlan.source_wo_id, from_original: winnerPlan.from_original, will_change: willChange, changed: [], text_sent_now: false } : null,
        note: winnerIsOriginal ? 'The original is kept as it is; only the other copies are cancelled. Its notification settings are not touched.' : winnerPlan.note,
      };
    }
    const [vendors, bills, timeEntries, invoiceReview, properties, units] = await Promise.all([fetchTab(env, 'Vendors'), fetchTab(env, 'Vendor_Bills'), fetchTab(env, 'Time_Entries'), fetchTab(env, 'Invoice_Review'), fetchTab(env, 'Properties'), fetchTab(env, 'Units')]);
    const ctx = { bills, timeEntries, invoiceReview, workorders: all };
    const targets = [];
    for (const m of members) {
      const v = m.Vendor_ID ? vendors.find(x => String(x.ID) === String(m.Vendor_ID)) : null;
      const row = { wo_id: m.ID, status_before: m.Status || 'New', vendor_id: m.Vendor_ID || '', vendor_name: v ? (v.Name || '') : '', is_original: !String(m.Duplicated_From || '').trim(), reasons: [], warnings: [], result: '', vendor_sms: null };
      // keep_one (Oct 13 2026, Brett): cancel ONLY the duplicate copies that are not the winner. The original is never cancelled by "Keep this".
      const isTarget = mode === 'all' ? true : mode === 'duplicates' ? !row.is_original : (m.ID !== result.keep_wo_id && !row.is_original);
      if (!isTarget) {
        row.result = 'kept';
        row.reasons.push(mode === 'keep_one' ? (m.ID === result.keep_wo_id ? 'Kept (the one you chose)' : 'Kept (the original is never cancelled by "Keep this")') : 'Kept (the original)');
        result.summary.kept++; result.results.push(row); continue;
      }
      const c = bidCancelClassify(m, ctx);
      row.reasons = c.reasons; row.warnings = c.warnings;
      if (c.kind === 'already') { row.result = 'already_cancelled'; result.summary.already_cancelled++; }
      else if (c.kind === 'skip') { row.result = confirmed ? 'skipped' : 'would_skip'; result.summary[confirmed ? 'skipped' : 'would_skip']++; }
      else { row.result = confirmed ? 'pending' : 'would_cancel'; if (!confirmed) result.summary.would_cancel++; targets.push(row); }
      result.results.push(row);
    }
    // Vendors who still hold a job that STAYS open are not texted about a cancelled one (Oct 13 2026): kept / skipped / still-open members.
    const keptVendors = new Map();
    for (const r of result.results) {
      if (!['kept', 'would_skip', 'skipped'].includes(r.result)) continue;
      const m = members.find(x => x.ID === r.wo_id);
      if (m && m.Vendor_ID && !isCancelledWOStatus(m.Status) && String(m.Voided || '').toUpperCase() !== 'TRUE' && !keptVendors.has(String(m.Vendor_ID))) keptVendors.set(String(m.Vendor_ID), m.ID);
    }
    const woById = id => members.find(x => x.ID === id);
    const planFor = row => { const m = woById(row.wo_id); const prop = properties.find(p => p.ID === m.Property_ID); const unit = units.find(u => u.ID === m.Unit_ID); const vendor = m.Vendor_ID ? vendors.find(x => String(x.ID) === String(m.Vendor_ID)) : null; return { m, prop, unit, vendor }; };
    if (!confirmed) {
      // PREVIEW: say exactly who will be texted. Nothing is sent, queued or changed.
      result.quiet_hours_now = isQuietHoursNow(new Date());
      for (const row of result.results) {
        if (row.result === 'would_cancel') {
          const { m, prop, unit, vendor } = planFor(row);
          const p = bidCancelVendorPlan(row, vendor, m, prop, unit, keptVendors);
          row.vendor_sms = p;
          if (p.status === 'will_send') { result.summary.would_text++; result.vendor_text_notices.push({ wo_id: row.wo_id, level: 'ok', text: p.reason }); }
          else if (p.status === 'cannot_send') result.vendor_text_notices.push({ wo_id: row.wo_id, level: 'bad', text: p.reason });
          else if (p.vendor_id) result.vendor_text_notices.push({ wo_id: row.wo_id, level: 'info', text: p.reason });
        } else {
          row.vendor_sms = { wo_id: row.wo_id, vendor_id: row.vendor_id, vendor_name: row.vendor_name, status: 'skipped', reason: row.result === 'kept' ? 'Kept, so not texted.' : (row.result === 'already_cancelled' ? 'Already cancelled earlier, so no new text.' : 'Not cancelled, so not texted.') };
        }
      }
      if (result.summary.would_text && result.quiet_hours_now) result.warnings.push('It is quiet hours right now (7pm-9am ET): the vendor texts will be held and sent automatically after 9am ET by the scheduler.');
      result.ok = true;
      await bidLogTelemetry(env, result, 'wo_bid_cancel_preview', '/wo/bid-group/cancel', true, `group=${gid} mode=${mode} would_cancel=${result.summary.would_cancel} would_skip=${result.summary.would_skip} would_text=${result.summary.would_text}`);
      return json(result, 200);
    }
    if (!targets.length) result.warnings.push('Nothing to cancel — every targeted member was skipped, kept or already cancelled.');
    // Winner first: if it cannot be made visible / notifying, STOP before cancelling anything (no half-done shotgun).
    if (winnerWO && !result.winner.is_original) {
      try {
        await ensureColumns(env, 'Work_Orders', WO_BID_WINNER_COLUMNS);
        const fresh = findWO(await bidFreshWOs(env), winnerWO.ID);
        if (!fresh) throw new Error('the row could not be found');
        const want = bidWinnerNotifyDiff(fresh, winnerPlan.settings);
        if (String(fresh.Bid_Winner || '').trim().toUpperCase() !== 'TRUE') want.Bid_Winner = 'TRUE';
        if (Object.keys(want).length) {
          await bidWriteWOFields(env, winnerWO.ID, want);
          result.winner.became_tenant_visible = 'Tenant_Visible' in want && want.Tenant_Visible === 'TRUE';
          result.winner.notify.changed = Object.keys(want).filter(k => k !== 'Bid_Winner');
          const now = new Date().toISOString(), aud = [];
          for (const k of Object.keys(want)) {
            const nv = want[k];
            const notes = k === 'Bid_Winner' ? `Chosen to keep in bid group ${gid}`
              : k === 'Tenant_Visible' ? `Kept as the winner of bid group ${gid}; Tenant_Visible now ${nv}, as on the original (no text message sent)`
              : `Kept as the winner of bid group ${gid}; now follows ${winnerPlan.from_original ? 'the original ' + winnerPlan.source_wo_id : 'the normal defaults'} so tenant/owner are notified like any work order (no text message sent now)`;
            aud.push({ WO_ID: winnerWO.ID, Changed_By: changedBy, Changed_By_Role: 'admin', Field: k, Old_Value: String(fresh[k] == null ? '' : fresh[k]), New_Value: nv, Timestamp: now, Notes: notes });
          }
          try { await bidAppendRows(env, 'WO_Audit', aud); }
          catch (ae) { await bidStepFailed(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', `The WO_Audit rows for the winner ${winnerWO.ID} were not written`, ae, winnerWO.ID); }
        }
        // A previous winner in this group (Brett changed his mind) loses the marker; it is about to be cancelled.
        for (const prev of members.filter(m => m.ID !== winnerWO.ID && String(m.Bid_Winner || '').trim().toUpperCase() === 'TRUE')) {
          try { await bidWriteWOFields(env, prev.ID, { Bid_Winner: '' }); }
          catch (pe) { await bidStepFailed(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', `Could not clear the old winner marker on ${prev.ID}`, pe, prev.ID); }
        }
      } catch (e) {
        return await fail(500, `${winnerWO.ID} could not be made visible/notifying like a normal work order (${String((e && e.message) || e)}), so NOTHING was cancelled. Try again.`);
      }
    }
    for (const row of result.results) if (row.result !== 'pending') row.vendor_sms = { wo_id: row.wo_id, vendor_id: row.vendor_id, vendor_name: row.vendor_name, status: 'skipped', reason: row.result === 'kept' ? 'Kept, so not texted.' : (row.result === 'already_cancelled' ? 'Already cancelled earlier, so no new text.' : 'Not cancelled, so not texted.') };
    for (const row of targets) {
      // 1. The cancel itself (same path as a normal Cancelled status), verified by reading it back.
      try {
        const res = await updateStatus(env, { wo_id: row.wo_id, status: 'Cancelled', updated_by: changedBy, updated_by_role: 'admin' });
        let j = null, perr = '';
        try { j = await res.json(); } catch (pe) { perr = String((pe && pe.message) || pe); }
        if (!j) throw new Error(`status call returned an unreadable response (HTTP ${res.status}) ${perr}`);
        if (res.status !== 200 || !j.success) throw new Error(j.error || `status call failed (HTTP ${res.status})`);
        const after = findWO(await bidFreshWOs(env), row.wo_id);
        if (!after || !isCancelledWOStatus(after.Status)) throw new Error(`${row.wo_id} still reads Status=${after ? after.Status : '(row missing)'} after the cancel`);
        row.result = 'cancelled'; result.summary.cancelled++;
      } catch (e) {
        row.result = 'failed'; row.reasons.push(String((e && e.message) || e)); result.summary.failed++;
        row.vendor_sms = { wo_id: row.wo_id, vendor_id: row.vendor_id, vendor_name: row.vendor_name, status: 'skipped', reason: 'The cancel failed, so the vendor was not texted.' };
        result.errors.push(`${row.wo_id}: ${String((e && e.message) || e)}`);
        await bidLogTelemetry(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', false, `group=${gid} ${row.wo_id} ${String((e && e.message) || e)}`);
        continue;
      }
      // 2. Tell the vendor (only for a cancel THIS call just made; never throws; never undoes the cancel).
      const { m, prop, unit, vendor } = planFor(row);
      row.vendor_sms = await bidCancelNotifyVendor(env, result, row, m, vendor, prop, unit, keptVendors);
      // 3. Audit trail for the cancel (includes what happened to the vendor text).
      try {
        const audited = await bidCountRows(env, 'WO_Audit', r => r.WO_ID === row.wo_id && r.Field === 'Status' && isCancelledWOStatus(r.New_Value));
        if (!audited) row.warnings.push('Cancelled, but no WO_Audit row for the status change was found');
        await bidAppendRows(env, 'WO_Audit', [{ WO_ID: row.wo_id, Changed_By: changedBy, Changed_By_Role: 'admin', Field: 'Bid_Group_Cancel', Old_Value: row.status_before, New_Value: 'Cancelled', Timestamp: new Date().toISOString(), Notes: `Cancelled from bid group ${gid} (${mode}${mode === 'keep_one' ? ', kept ' + result.keep_wo_id : ''}). Vendor text: ${row.vendor_sms.status}${row.vendor_sms.reason ? ' (' + row.vendor_sms.reason + ')' : ''}` }]);
      } catch (ae) { await bidStepFailed(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', `${row.wo_id} was cancelled but its WO_Audit rows were not written`, ae, row.wo_id); }
    }
    result.ok = result.errors.length === 0;
    await bidLogTelemetry(env, result, 'wo_bid_cancel', '/wo/bid-group/cancel', result.ok, `group=${gid} mode=${mode} keep=${result.keep_wo_id} cancelled=${result.summary.cancelled} skipped=${result.summary.skipped} failed=${result.summary.failed} texts=${JSON.stringify(result.summary.vendor_texts)}`);
    return json(result, result.ok ? 200 : 500);
  };
  try { return await woDupSerialize(run); }
  catch (e) { return await fail(500, `Cancel failed: ${String((e && e.message) || e)}`); }
}

async function assignVendor(env, body, internal) {
  internal = internal || {};   // server-side options (NOT reachable from the HTTP body): { bypassQuietHours }
  const _t0 = Date.now();
  // notify defaults TRUE — preserves existing behavior for the Assign/Reassign Vendor modal
  // (which always says "Assign + Send SMS" and should keep meaning that). Pass notify:false
  // only from the New Work Order creation flow's "Notify vendor + tenant now" checkbox, for
  // cases like a WO created purely to record billing for work already done by phone weeks
  // ago — the vendor is assigned (Vendor_ID/Status still update normally) but no message is
  // composed or queued at all, since none was ever meant to exist for that case.
  const notify = body.notify !== false;
  // Sep 28 2026 (recurring WOs): notify_tenant:false = vendor-only dispatch, no tenant text.
  // Defaults TRUE so every existing caller behaves exactly as before.
  const notifyTenantOnAssign = body.notify_tenant !== false;
  const [workorders, vendors, tenants, units, properties, owners] = await fetchTabs(env, [
    'Work_Orders','Vendors','Tenants','Units','Properties','Owners',
  ]);
  const wo = findWO(workorders, body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  // Sep 16 2026 (Brett): an owner can claim a WO as their own (Managed_By='Owner', via
  // ownerUpdateWO) — once that's set, nobody should dispatch a Ridge Co vendor to it until the
  // owner hands it back. This is the actual enforcement point, not just a UI hint: it blocks
  // the assign call itself regardless of which screen it's triggered from.
  if (wo.Managed_By === 'Owner') return json({ error: 'This work order is being handled by the property owner, not Ridge Co — it cannot be assigned a vendor while marked that way.' }, 400);
  const vendor = vendors.find(v => v.ID === body.vendor_id); if (!vendor) return json({ error: 'Vendor not found' }, 404);
  const property = properties.find(p => p.ID === wo.Property_ID);
  const owner    = property ? owners.find(o => o.ID === property.Owner_ID) : null;
  const unit     = units.find(u => u.ID === wo.Unit_ID);
  // CAP-036 #21: notify every active tenant linked to this unit, not just one — see
  // tenantsForDispatch's comment for the real Lance/Emily (115 W 29th St) case this fixes.
  const woTenants = tenantsForDispatch(tenants, unit, wo);
  const room     = (wo.Room||'').trim();
  const address  = property ? `${property.Address}${unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : ''}${room ? ' ('+room+')' : ''}` : 'the property';
  // Access info (lockbox codes, master key status, etc.) is deliberately NOT built or sent
  // here — this initial dispatch text withholds it on purpose (see the Access-gate comment
  // below); it only unlocks in the vendor's own portal once they accept. Removed a dead
  // `accessInfo`/`getWOLockboxes` computation that used to run here and go nowhere (Aug 24,
  // 2026) — real access info flows through enrichWO's vendorView, gated on accessGated.
  let vendorSMSSent = false, tenantSMSSent = false;
  // Outcome of the vendor text in plain words (Oct 12 2026, Duplicate Work Order): sent / held /
  // failed / skipped + WHY, returned to the caller so a text that did not go out is never silent.
  let vendorSmsDetail = { status: 'skipped', reason: notify ? 'Vendor has no phone number on file' : 'Notifications were turned off for this assignment' };
  if (notify && !vendor.Phone) vendorSmsDetail = { status: 'failed', reason: 'Vendor has no phone number on file — no text was sent' };
  if (notify && vendor.Phone) {
    const isSpanish = vendor.Language === 'es';
    // Access-gate: the lockbox code + tenant contact are NOT sent on dispatch — they unlock
    // once the vendor accepts in the portal. Accepting moves the status, which is what lets
    // the tenant-notification automation fire. Message text deliberately does NOT tell the
    // vendor to reply YES/NO by text (Sep 14 2026, Brett's call) — handleInboundSMS's YES/NO
    // handling still exists in code but is currently unreachable: the Twilio number's inbound
    // webhook routes through a Twilio Studio Flow (Brett's own fix for the old-PM-autoresponder
    // issue) that never forwards to /sms-inbound, so a vendor texting YES today would hit that
    // generic Flow response, not this Hub. Telling them to text YES/NO would be actively
    // misleading until real reply/call handling replaces the Flow. Portal Accept/Decline
    // (Aug 13 build) is unaffected by this — it's a real, working button, not an SMS reply.
    const link = vendorPortalLink(body.wo_id);
    // English version always built (Oct 13 2026, Brett: the Message Queue showed only the Spanish that
    // was sent): for a Spanish vendor it rides along as the queue row's Original_Body so the review
    // screen can show what the text says in English.
    const msgEn = `[${body.wo_id}] New ${wo.Trade} job: ${wo.Description} (at ${address}). Log in to your vendor portal to accept or decline — the lockbox code & tenant contact unlock once you accept.\n${link}`;
    const msg = isSpanish
      ? `[${body.wo_id}] Nuevo trabajo: ${wo.Trade} — ${wo.Description} en ${address}. Inicie sesión en su portal de proveedor para aceptar o rechazar — el código de la caja y el contacto del inquilino se desbloquean al aceptar.\n${link}`
      : msgEn;
    // TWILIO_SMS_BUILD_BRIEF_v1.0 — vendor_job_assigned. Gated + queued via smsGatedSend;
    // the accept-gate withholding (lockbox/tenant contact) itself is unchanged, only the
    // SMS-reply instruction was removed per the comment above. Link added per Brett's ask
    // (Sep 14 2026) — deep-links into the portal (vendorPortalLink), not the no-login
    // shareable-link mechanism, specifically to avoid bypassing this same accept-gate.
    const r = await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'vendor_job_assigned', recipient_type: 'vendor', vendor, message_body: msg, allowEarlyMorning: body.allow_early_morning_sms === true, already_localized: true, original_body: isSpanish ? msgEn : '', translated_to: isSpanish ? 'es' : '', bypassQuietHours: internal.bypassQuietHours === true });
    vendorSMSSent = r.sent;
    const _lang = isSpanish ? 'es' : 'en';
    vendorSmsDetail = vendorSmsDetailFromResult(env, r, _lang, msg);
  }
  if (notify && notifyTenantOnAssign) {
    // TWILIO_SMS_BUILD_BRIEF_v1.0 — tenant_job_assigned. Now includes the assigned vendor's
    // name + phone (Brett confirmed this is already customer-facing and safe to surface),
    // and a short job label (woJobLabel) so two same-trade/same-address jobs never read
    // identically in a text — "your General job" alone was indistinguishable from any other
    // General job at the same address. CAP-036 #21: loops every tenant in the unit (was one).
    for (const tenant of woTenants) {
      if (!tenant?.Phone || !isTenantNotifiable(tenant, wo)) continue;
      const vendorPhoneDisplay = formatPhoneDisplay(vendor.Phone);
      const msg = `Hi ${tenant.First_Name}, your ${woJobLabel(wo)} has been assigned to ${vendor.Name || 'a technician'}${vendorPhoneDisplay ? ' (' + vendorPhoneDisplay + ')' : ''}. They will contact you to schedule. Ref: ${body.wo_id}.`;
      const r = await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'tenant_job_assigned', recipient_type: 'tenant', tenant, owner, property, message_body: msg });
      if (r.sent) tenantSMSSent = true;
    }
  }
  await updateWOFields(env, body.wo_id, { Vendor_ID: body.vendor_id, Status: 'Assigned', Vendor_SMS_Sent: vendorSMSSent ? 'TRUE' : 'FALSE', Tenant_SMS_Sent: tenantSMSSent ? 'TRUE' : 'FALSE' });
  // Vendor nudge clock (Sep 14 2026) — starts on every successful assignment, notify or
  // silent, since it tracks actual work progress rather than whether a text went out.
  await createVendorNudgeClock(env, body.wo_id, body.vendor_id);
  try { await logTelemetry(env, { Source:'worker', Job_Type:'wo_assign', Skill_Or_Endpoint:'/assign', Success:'TRUE', Latency_ms: Date.now()-_t0, Notes:`trade=${wo.Trade||''} vendor_sms=${vendorSMSSent} tenant_sms=${tenantSMSSent} notify=${notify}` }); } catch(_){}
  return json({ success: true, vendor_sms: vendorSMSSent, tenant_sms: tenantSMSSent, notified: notify, vendor_sms_detail: vendorSmsDetail });
}

async function updateStatus(env, body) {
  const _t0 = Date.now();
  // On Hold now REQUIRES a reason (Sep 14 2026, Brett) — checked before anything is written,
  // so a bad request never leaves a WO On Hold with no reason on record. hold_reason is the
  // real field name the client should send; notes is accepted as a fallback so an older/other
  // caller that only ever sent notes doesn't suddenly break.
  let holdReason = '';
  if (body.status === 'On Hold') {
    holdReason = String(body.hold_reason || body.notes || '').trim();
    if (!holdReason) return json({ error: 'A reason is required to put a work order On Hold.' }, 400);
  }
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, body.wo_id);
  if (!wo) return json({ error: 'WO not found' }, 404);
  // Orphan guard (additional work): cancelling a parent with live add-ons would strand them.
  if ((body.status === 'Cancelled' || body.status === 'Canceled') && workorders.some(w => String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() === String(body.wo_id))) {
    const _live = addonLiveChildren(workorders, await fetchTab(env, 'Estimates'), body.wo_id);
    if (_live.length) return json({ error: addonLiveChildrenMessage(_live, body.wo_id, 'cancel'), open_additional_work: _live }, 409);
  }
  const changedBy = body.updated_by || 'system', changedRole = body.updated_by_role || 'admin';
  const fields = { Status: body.status };
  if (body.notes) {
    let statusNote = body.notes;
    if (body.vendor_id) {
      const sVendors = await fetchTab(env, 'Vendors');
      const sVendor = sVendors.find(v => v.ID === body.vendor_id);
      if (sVendor?.Language === 'es') { const en = await translateToEnglish(env, statusNote); if (en && en !== statusNote) statusNote = `[ES] ${statusNote}\n[EN] ${en}`; }
    }
    fields.Notes = statusNote;
  }
  if (body.scheduled_date) fields.Scheduled_Date = body.scheduled_date;
  if (body.status === 'Complete' || body.status === 'Pending Invoice')
    fields.Completed_Date = wo.Completed_Date || new Date().toISOString();
  if (body.status === 'On Hold') {
    try { await ensureColumns(env, 'Work_Orders', ['Hold_Reason']); } catch (_) {}
    fields.Hold_Reason = holdReason;
  }
  await updateWOFields(env, body.wo_id, fields);
  await logWOAudit(env, body.wo_id, changedBy, changedRole, 'Status', wo.Status||'', body.status, body.notes||'');
  // Vendor nudge clock reset (Sep 14 2026) — real vendor activity (a status change or note
  // FROM the vendor, distinguished by updated_by_role) resets the clock; an admin changing
  // status on the vendor's behalf does not (that's not the vendor actually engaging).
  if (changedRole === 'vendor') { await resetVendorNudgeClock(env, body.wo_id, body.vendor_id || wo.Vendor_ID); }
  const config = await fetchConfig(env);
  const [units, tenants, properties, owners] = await fetchTabs(env, ['Units','Tenants','Properties','Owners']);
  const unit = units.find(u => u.ID === wo.Unit_ID), property = properties.find(p => p.ID === wo.Property_ID);
  const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
  const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'your unit';
  if (body.status === 'Complete') {
    // CAP-036 #21: every active tenant in the unit, not just the one Units.Tenant_ID happens
    // to name — see tenantsForDispatch's comment for the real Lance/Emily case this fixes.
    if (wo.Tenant_Notify_Updates !== 'FALSE') for (const tenant of tenantsForDispatch(tenants, unit, wo)) {
      if (!isTenantNotifiable(tenant, wo)) continue;
      // TWILIO_SMS_BUILD_BRIEF_v1.0 — tenant_job_completed. woJobLabel keeps two same-trade/
      // same-address jobs distinguishable in the text (see tenant_job_assigned's comment).
      // Sep 16 2026 (Brett): dropped the "reply or call us" line — inbound SMS from a tenant
      // number currently dead-ends into handleInboundSMS's vendor-only lookup ("Sorry, we
      // could not find your vendor record"), so this was promising a channel that doesn't
      // actually route anywhere yet. Revisit once a real tenant contact path exists.
      const msg = `Hi ${tenant.First_Name}, your ${woJobLabel(wo)} at ${address} is complete. Thank you! Ref: ${body.wo_id}.`;
      await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'tenant_job_completed', recipient_type: 'tenant', tenant, owner, property, message_body: msg });
    }
    if (config.admin_phone) await sendSMS(env, config.admin_phone, `✅ ${body.wo_id} marked Complete${body.updated_by ? ' (by '+body.updated_by+')' : ''}. ${woJobLabel(wo)} at ${address}. Pending invoice.`);
    await updateWOFields(env, body.wo_id, { Owner_Notified: 'PENDING' });
  }
  // Vendor accepted → notify the tenant that a technician has accepted and will reach out.
  // This is the automation the acceptance gate exists to enable: the status moving to
  // Accepted is the trigger, so a vendor who just starts the job no longer silently skips it.
  if (body.status === 'Accepted') {
    // CAP-036 #21: every active tenant in the unit, not just one.
    if (wo.Tenant_Notify_Updates !== 'FALSE') for (const tenant of tenantsForDispatch(tenants, unit, wo)) {
      if (!isTenantNotifiable(tenant, wo)) continue;
      const msg = `Hi ${tenant.First_Name}, a technician has accepted your ${woJobLabel(wo)} at ${address} and will contact you to schedule. Ref: ${body.wo_id}.`;
      await sendSMS(env, tenant.Phone, msg); await logSMS(env, body.wo_id, 'tenant_accepted', tenant.ID, tenant.Phone, msg);
    }
  }
  // Turnover dependency release (B-100). Repairs and Paint run in parallel with no gate on
  // each other, but Cleaning is created On Hold and must wait until BOTH finish (or the
  // date-fallback `daily_turnover` scheduler job releases it first). This only ever fires for a WO
  // that's actually part of a turnover group and just went Complete — everything else is a
  // no-op single extra field read.
  if (body.status === 'Complete' && wo.Turnover_Group_ID && wo.Turnover_Role && wo.Turnover_Role !== 'Cleaning') {
    try { await releaseTurnoverCleaningIfReady(env, wo.Turnover_Group_ID); } catch (e) { /* non-fatal */ }
  }
  // Owner notifications (Sep 14 2026 rebuild) — Received/Complete/On_Hold here; Scheduled
  // moved to scheduleWO itself (Sep 15 2026 — real gap found live-testing: nothing in this
  // codebase ever actually sets Status to the literal 'Scheduled', so the mapping that used to
  // live here could never fire; see scheduleWO's own comment). Deliberately NOT kept as a
  // dead/defensive entry here too — leaving it would risk a double-send if some future code
  // path ever did set status:'Scheduled' via this endpoint.
  // 'Assigned' and 'Invoiced' retired per Brett's own call (see NOTIFY_TIERS comment). Routed
  // through the real gated pipeline now (Global+Property+Customer, Test Mode, Message_Queue),
  // not the old raw sendSMS — the old path bypassed Test Mode entirely, so a real owner could
  // receive a live text about a WO created purely for testing. This closes that gap.
  const OWNER_STATUS_EVENTS = { Complete: 'Complete', 'On Hold': 'On_Hold' };
  const ownerEvent = OWNER_STATUS_EVENTS[body.status];
  if (ownerEvent && owner?.Phone) {
    const notify = await shouldNotifyOwner(env, wo, ownerEvent);
    if (notify) {
      const ownerMsgs = {
        Complete: `Hi ${owner.First_Name}, work order ${body.wo_id} — ${woJobLabel(wo)} at ${address} — is complete. Ref: ${body.wo_id}.`,
        On_Hold: `Hi ${owner.First_Name}, work order ${body.wo_id} — ${woJobLabel(wo)} at ${address} — is on hold: ${holdReason}. Ref: ${body.wo_id}.`,
      };
      const msg = ownerMsgs[ownerEvent];
      const msgType = ownerEvent === 'On_Hold' ? 'owner_job_on_hold' : `owner_job_${ownerEvent.toLowerCase()}`;
      const r = await smsGatedSend(env, { wo_id: body.wo_id, message_type: msgType, recipient_type: 'owner', owner, property, message_body: msg });
      if (r.sent) await updateWOFields(env, body.wo_id, { Owner_Notified: 'TRUE' });
    }
  }
  try { await logTelemetry(env, { Source:'worker', Job_Type:'wo_status', Skill_Or_Endpoint:'/status', Success:'TRUE', Latency_ms: Date.now()-_t0, Notes:`status=${body.status||''}` }); } catch(_){}
  return json({ success: true });
}

// Save a WO's itemized checklist state (admin defines items; vendor checks them off /
// marks not-done with a reason). Stored as JSON on Work_Orders.Checklist. Callable by the
// Hub (admin secret) and the vendor portal (scoped). ensureColumns self-provisions the
// column so the first write can't silently drop the field (FL rule 37).
async function saveChecklist(env, body) {
  if (!body.wo_id) return json({ error: 'Missing wo_id' }, 400);
  await ensureColumns(env, 'Work_Orders', ['Checklist']);
  const value = typeof body.checklist === 'string' ? body.checklist : JSON.stringify(body.checklist || []);
  await updateWOFields(env, body.wo_id, { Checklist: value });
  if (body.updated_by) {
    try { await logWOAudit(env, body.wo_id, body.updated_by, body.updated_by_role || 'vendor', 'Checklist', '', 'updated', body.note || ''); } catch(_){}
  }
  return json({ success: true });
}

// RETIRED Oct 14 2026 (Ops_Build_Queue #100, collapse 3 invoice/QB paths into one).
// "Log Invoice" wrote a typed amount to the sheet-only Invoices tab and flipped the WO to
// Invoiced WITHOUT creating a QuickBooks invoice or touching Invoice_Review, so a job could leave
// every needs-billing view with nothing billed. The ONE invoice path is Invoice Builder ->
// /invoice-review/approve -> /qb/send-invoice. A stale cached page that still posts here gets a
// loud 410 plus a telemetry failure row instead of a quiet sheet-only "invoice".
async function retiredLogInvoice(env, body, path, callerRole) {
  await logTelemetry(env, { Source: 'worker', Job_Type: 'legacy_invoice_blocked', Skill_Or_Endpoint: path, Success: 'FALSE',
    Notes: `wo=${(body && body.wo_id) || ''} amount=${(body && body.amount) || ''} role=${callerRole || 'admin'}` });
  return json({ error: 'Log Invoice has been retired because it never created a QuickBooks invoice. Open the job and use the Invoice Builder (or Review Bills) instead. Nothing was saved.', retired: true }, 410);
}

// Dollar amounts compare by whole cents, never by string ("150" and "150.00" are the same price).
// Anything that is not a number falls back to exact string equality so it can only ever read as
// "different", never as a false match.
function sameCents(a, b) {
  const x = Math.round(parseFloat(a) * 100), y = Math.round(parseFloat(b) * 100);
  return Number.isFinite(x) && Number.isFinite(y) ? x === y : String(a == null ? '' : a) === String(b == null ? '' : b);
}

// ── PORTAL VIEWS ─────────────────────────────────────────────

async function vendorWorkorders(env, url, callerRole, callerSessionId) {
  // A vendor session is always scoped to ITS OWN id from the signed token, never the query string.
  const vendorId = callerRole === 'vendor' ? String(callerSessionId || '') : url.searchParams.get('vendor_id');
  if (!vendorId) return json({ error: 'Missing vendor_id' }, 400);
  const includeClosed = url.searchParams.get('include_closed') === 'true';
  // ONE batchGet for everything (was 3 separate Sheets reads per call: tabs + Config + Master_Key_Holders).
  // Config comes back as raw rows from the same cache entry; if Master_Key_Holders doesn't exist yet the
  // batch fails with a missing-tab error and we fall back to the old three-read path (holders = []).
  let workorders, properties, units, tenants, keys, vendors, masterKeys, masterKeyHolders, config;
  try {
    [workorders, properties, units, tenants, keys, vendors, masterKeys, masterKeyHolders] = await fetchTabs(env, ['Work_Orders','Properties','Units','Tenants','Keys','Vendors','Master_Keys','Master_Key_Holders','Config'], { stale: true });
    const _cfgHit = __tabCache.get('Config');
    config = configFromValues(_cfgHit && _cfgHit.data && _cfgHit.data.values);
  } catch (e) {
    if (!isMissingTabError(e)) throw e;
    [[workorders, properties, units, tenants, keys, vendors, masterKeys], config, masterKeyHolders] = await Promise.all([
      fetchTabs(env, ['Work_Orders','Properties','Units','Tenants','Keys','Vendors','Master_Keys'], { stale: true }),
      fetchConfig(env),
      fetchMasterKeyHolders(env, { stale: true }),
    ]);
  }
  let tradeAccessDefaults = {};
  try { tradeAccessDefaults = JSON.parse(config.Access_Trade_Defaults || '{}'); } catch(e) {}
  // Voided is never shown to a vendor, regardless of include_closed — it isn't a closed
  // status a vendor should be able to page back to, it's a job that shouldn't have existed.
  const wos = workorders.filter(w => w.Vendor_ID === vendorId && w.Voided !== 'TRUE' && String(w.Addon_Status || '') !== 'Draft' && !(String(w.Type || '') === 'addon' && String(w.Parent_WO_ID || '').trim() && String(w.Approval_Stage || '') !== 'Approved') && (includeClosed || OPEN_WO_STATUSES.includes(w.Status)));
  // vendors passed through so enrichWO can tell whether THIS vendor is Brett's own
  // in-house record — that's what lets a "Brett Only" code still surface on a WO
  // that's actually assigned to him (see enrichWO's visibleLockboxes). viewingVendorId is
  // THIS vendor — enrichWO only ever tells a vendor about a master key when they're the one
  // the WO is actually assigned to (matches the `wos` filter above, but enforced again inside
  // enrichWO itself rather than trusted from the filter, since that's the one place a leak
  // to another vendor would matter).
  const enriched = wos.map(wo => enrichWO(wo, properties, units, tenants, keys, { tradeAccessDefaults, vendorView: true, vendors, viewingVendorId: vendorId }, masterKeys, masterKeyHolders));
  enriched.sort((a, b) => { const pa = PRIORITY_ORDER[a.Priority?.toLowerCase()] ?? 2, pb = PRIORITY_ORDER[b.Priority?.toLowerCase()] ?? 2; return pa !== pb ? pa - pb : (a.property_address||'').localeCompare(b.property_address||''); });
  return json(enriched);
}

async function tenantWorkorders(env, url, callerRole, callerSessionId) {
  // A tenant session is always scoped to ITS OWN id from the signed token, never the query string.
  const tenantId = callerRole === 'tenant' ? String(callerSessionId || '') : url.searchParams.get('tenant_id');
  if (!tenantId) return json({ error: 'Missing tenant_id' }, 400);
  const includeClosed = url.searchParams.get('include_closed') === 'true';
  const [workorders, properties, units, tenants, keys, vendors, owners] = await fetchTabs(env, ['Work_Orders','Properties','Units','Tenants','Keys','Vendors','Owners']);
  const tenant = tenants.find(t => t.ID === tenantId); if (!tenant) return json([]);
  // isBackgroundWO: don't show a WO opened before this tenant moved in — matches the rule
  // isTenantNotifiable already applies to SMS, so "won't text them about it" and "won't show
  // it in their portal" stay in sync instead of drifting apart (see isBackgroundWO comment).
  const wos = workorders.filter(w => { if (!includeClosed && !OPEN_WO_STATUSES.includes(w.Status)) return false; return tenantCanSeeWO(tenant, w); });
  // tenants get the assigned vendor's name/phone/trade so they can coordinate access —
  // enrichWO never resolved Vendor_ID -> a name/phone at all before this (tenant.html and
  // owner.html both had a "Technician: —" row wired up with nothing to fill it). No
  // Master_Keys/viewingVendorId passed — omitLockbox:true already zeroes lockboxes below, and
  // a tenant must never learn a master key exists at all, let alone who holds a copy.
  const enriched = wos.map(wo => enrichWO(wo, properties, units, tenants, keys, { omitLockbox: true, tenantView: true, vendors }));
  // Sep 16 2026 (Brett): a WO the owner has claimed as their own (Managed_By='Owner', see the
  // owner.html toggle) shows the OWNER's own contact info here instead of Ridge Co's — the
  // tenant should never be left thinking Ridge Co is quietly handling it. Held_Contact_Note is
  // free text Brett sets once per owner (e.g. "Check your Buildium portal for updates" for an
  // owner who runs their own tenant system, or just a phone number for one who doesn't) so this
  // covers any owner's actual setup rather than assuming a fixed phone/email shape. Falls back
  // to the owner's own name+phone on file if no custom note has been set yet. Resolved here
  // (not inside enrichWO) so every OTHER caller of enrichWO — vendor/owner/shared-link views —
  // is completely unaffected by this tenant-only concern.
  enriched.forEach(wo => {
    if (wo.Managed_By !== 'Owner') return;
    const property = properties.find(p => p.ID === wo.Property_ID);
    const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
    if (owner && owner.Held_Contact_Note) {
      wo.owner_managed_contact = owner.Held_Contact_Note;
    } else if (owner) {
      const ownerName = (`${owner.First_Name||''} ${owner.Last_Name||''}`.trim()) || owner.Company || 'your property manager';
      wo.owner_managed_contact = owner.Phone ? `Contact ${ownerName} at ${owner.Phone}` : `Contact ${ownerName} directly`;
    } else {
      wo.owner_managed_contact = 'Please contact your property manager directly.';
    }
  });
  enriched.sort((a, b) => new Date(b.Created_Date) - new Date(a.Created_Date));
  return json(enriched);
}

async function ownerWorkorders(env, url, callerRole, callerSessionId) {
  // An owner session is always scoped to ITS OWN id from the signed token, never the query string.
  const ownerId = callerRole === 'owner' ? String(callerSessionId || '') : url.searchParams.get('owner_id');
  if (!ownerId) return json({ error: 'Missing owner_id' }, 400);
  const includeClosed = url.searchParams.get('include_closed') === 'true';
  const [workorders, properties, units, tenants, keys, vendors] = await fetchTabs(env, ['Work_Orders','Properties','Units','Tenants','Keys','Vendors']);
  const ownerPropIds = new Set(properties.filter(p => p.Owner_ID === ownerId).map(p => p.ID));
  // Still-linked bid-group copies (Duplicated_From AND Bid_Group_ID both set) are Brett's internal shotgun
  // and would show the owner every competing vendor — hidden here (this endpoint ignores Tenant_Visible).
  // The copy Brett KEPT ("Keep this", Bid_Winner TRUE) is shown (isHiddenBidCopy, Oct 13 2026).
  const wos = workorders.filter(w => ownerPropIds.has(w.Property_ID) && w.Voided !== 'TRUE' && String(w.Type || '') !== 'addon' && !isHiddenBidCopy(w) && (includeClosed || OPEN_WO_STATUSES.includes(w.Status)));
  // Owner gets the vendor's name/trade (who's on the job), not their phone — keeps the
  // vendor relationship mediated through Brett rather than owners going around him. No
  // Master_Keys/viewingVendorId passed — omitLockbox:true already zeroes lockboxes below,
  // and master key info stays vendor-only regardless.
  const enriched = wos.map(wo => enrichWO(wo, properties, units, tenants, keys, { omitLockbox: true, omitTenantPhone: true, ownerView: true, vendors }));
  enriched.sort((a, b) => new Date(b.Created_Date) - new Date(a.Created_Date));
  return json(enriched);
}

function enrichWO(wo, properties, units, tenants, keys, opts={}, masterKeys=[], masterKeyHolders=[]) {
  const property = properties.find(p => p.ID === wo.Property_ID) || {};
  const unit     = units.find(u => u.ID === wo.Unit_ID) || {};
  let tenant = {};
  const tenantId = wo.Tenant_ID || unit.Tenant_ID;
  if (tenantId) tenant = tenants.find(t => t.ID === tenantId) || {};
  if (!tenant.ID && wo.Unit_ID)       tenant = tenants.find(t => t.Unit_ID === wo.Unit_ID && t.Active !== 'FALSE') || {};
  if (!tenant.ID && wo.Property_ID && !wo.Unit_ID) tenant = tenants.find(t => t.Property_ID === wo.Property_ID && !t.Unit_ID && t.Active !== 'FALSE') || {};

  // Work orders keep their original Tenant_ID forever — that IS the history, and clearing
  // it would destroy the record of who reported what. But a work order raised while
  // someone lived here does not entitle a vendor to their phone number today. The unit
  // pointer being cleaned on move-out cannot help here, because this reads wo.Tenant_ID
  // first. So the person's number is withheld once they've gone, while the name stays for
  // the Hub's own records.
  const tenantIsFormer = !!tenant.ID && !isTenantCurrent(tenant);
  const tradeDefaults = opts.tradeAccessDefaults || {};
  const woAccess = (wo.Vendor_Needs_Access || 'auto').trim();
  let vendorHasAccess;
  if (woAccess === 'TRUE')  vendorHasAccess = true;
  else if (woAccess === 'FALSE') vendorHasAccess = false;
  else {
    const trade = (wo.Trade || '').trim();
    // Check the raw spelling AND the resolved one. A default saved under "Electric" must
    // keep applying now that the trade resolves to "Electrical" — an unmatched lookup
    // yields undefined, and `undefined !== 'FALSE'` GRANTS access. A rename must never
    // quietly turn a no-access trade into an access-granted one.
    const resolvedName = resolveTrade(trade).name;
    let tradeDefault = tradeDefaults[trade];
    if (tradeDefault === undefined) tradeDefault = tradeDefaults[resolvedName];
    if (tradeDefault === undefined) {
      // Resolve the CONFIG KEYS too, not just the work order's trade. His access rules were
      // saved through a dropdown that only offered "Electric", so the keys are the old
      // spelling while new work orders say "Electrical" — and an unmatched lookup GRANTS
      // access. A rule he set to no-access must not be silently ignored because the
      // vocabulary moved underneath it.
      const key = Object.keys(tradeDefaults).find(kk => resolveTrade(kk).name === resolvedName);
      if (key !== undefined) tradeDefault = tradeDefaults[key];
    }
    vendorHasAccess = tradeDefault !== 'FALSE';
  }
  // Accept-gate (vendor portal only): the lockbox code + tenant contact are withheld until
  // the vendor has ACCEPTED the work order. Accepting is what unlocks them — and accepting
  // moves the status, which lets the tenant-notification automation fire. New/Assigned = gated.
  const ACCEPTED_OR_LATER = WOStatus.sets.ACCEPTED_OR_LATER;
  const accessGated = !!opts.vendorView && !ACCEPTED_OR_LATER.includes((wo.Status||'').trim());
  // Resolve the assigned vendor's name/phone/trade/in-house status when a vendor directory
  // was handed in. This never happened before — tenant.html and owner.html both had a
  // "Technician" / "Vendor" row template referencing wo.vendor_name, but nothing ever
  // populated it, so it always rendered blank/"—". Only callers that pass opts.vendors get
  // it resolved; callers that don't (generic admin reads) are unaffected. Resolved BEFORE
  // the lockboxes are filtered below, because a "Brett Only" code's one exception is a WO
  // whose assigned vendor IS Brett (In_House).
  let vendorName = '', vendorPhone = '', vendorTrade = '', vendorInHouse = false;
  if (opts.vendors && wo.Vendor_ID) {
    const v = opts.vendors.find(vv => vv.ID === wo.Vendor_ID);
    if (v) {
      vendorName = v.Name || `${v.First_Name||''} ${v.Last_Name||''}`.trim();
      vendorPhone = v.Phone || '';
      vendorTrade = v.Trade || '';
      vendorInHouse = String(v.In_House||'').toUpperCase() === 'TRUE';
    }
  }
  // Master key info is resolved ONLY when the caller tells us who's actually looking
  // (opts.viewingVendorId) AND that person is the vendor this WO is assigned to — never for
  // a tenant, never for an owner, never for some other vendor browsing/bidding. This is a
  // stricter, separate gate from the trade-access/accept-gate below (which still applies on
  // top of it via `lockboxes` further down) — "not shared with every vendor, period" per Brett.
  const masterKeyRow = (property && property.Master_Key_ID) ? masterKeys.find(mk => mk.ID === property.Master_Key_ID && mk.Active !== 'FALSE') : null;
  let masterKeyInfo = null;
  if (masterKeyRow && opts.viewingVendorId && String(opts.viewingVendorId) === String(wo.Vendor_ID)) {
    const holder = masterKeyHolders.find(h => h.Master_Key_ID === masterKeyRow.ID && String(h.Vendor_ID) === String(opts.viewingVendorId) && h.Active !== 'FALSE');
    masterKeyInfo = { name: masterKeyRow.Name || 'Unnamed', hasIt: !!holder && holder.Status === 'Have It', note: holder ? (holder.Notes||'') : '' };
  }
  const rawLockboxes = getWOLockboxes(keys, wo.Property_ID, wo.Unit_ID, unit.Unit_Label||'', masterKeyInfo);
  // Per-code visibility, independent of the per-WO/per-trade share toggle above: a code
  // marked "Brett Only" (see getWOLockboxes) is stripped out of every external render —
  // enrichWO is ONLY ever used to build vendor/tenant/owner/shared-link views, never the
  // admin Hub, which reads Keys directly and always sees everything — UNLESS the vendor
  // actually assigned to this WO is Brett's own in-house record, matching "viewable for me,
  // and on the work order assigned to me" (FEATURE_LOG access-visibility fix).
  const visibleLockboxes = vendorInHouse ? rawLockboxes : rawLockboxes.filter(lb => lb.visibility !== 'Brett Only');
  const lockboxes = (opts.omitLockbox || !vendorHasAccess || accessGated) ? [] : visibleLockboxes;
  const accessNotes = (!vendorHasAccess || accessGated) ? '' : (property.Access_Notes||'');
  const legacyLockbox = (!lockboxes.length && vendorHasAccess && !accessGated && property.Lockbox_Code) ? property.Lockbox_Code : '';
  const base = {
    ...wo,
    property_address: property.Address||'', property_city: property.City||'', unit_label: unit.Unit_Label||'',
    tenant_name:  wo.WO_Contact_Name || (tenant.First_Name ? `${tenant.First_Name} ${tenant.Last_Name||''}`.trim() : ''),
    // A named WO contact is a deliberate override and stands on its own; the TENANT's
    // number is what gets withheld once they've moved out.
    tenant_phone: (opts.omitTenantPhone || accessGated) ? '' : (wo.WO_Contact_Phone || (tenantIsFormer ? '' : (tenant.Phone||''))),
    tenant_former: tenantIsFormer,
    tenant_record_name:  tenant.First_Name ? `${tenant.First_Name} ${tenant.Last_Name||''}`.trim() : '',
    tenant_record_phone: (opts.omitTenantPhone || tenantIsFormer || accessGated) ? '' : (tenant.Phone||''),
    lockboxes,
    legacy_lockbox: legacyLockbox,
    access_notes: accessNotes,
    vendor_has_access: vendorHasAccess,
    access_gated: accessGated,
    vendor_name: vendorName, vendor_phone: vendorPhone, vendor_trade: vendorTrade,
  };
  // Tenants get the full technician contact (name+phone+trade) so they can coordinate
  // access directly once someone's assigned — that's the whole point of showing it.
  if (opts.tenantView) { delete base.access_notes; delete base.legacy_lockbox; base.lockboxes = []; }
  // Owners see WHO is on the job (name+trade) but not a direct line to the vendor — keeps
  // the vendor relationship mediated through Brett rather than owners going around him.
  if (opts.ownerView)  { delete base.Invoice_ID; base.Display_Status = base.Status === 'Pending Invoice' ? 'Complete' : base.Status; base.vendor_phone = ''; }
  return base;
}

async function getPropertyFull(env, url) {
  const id = url.searchParams.get('id');
  if (!id) return json({ error: 'Missing id' }, 400);
  const [props, units, tenants, keys] = await fetchTabs(env, ['Properties','Units','Tenants','Keys']);
  const property = props.find(p => p.ID === id);
  if (!property) return json({ error: 'Property not found' }, 404);
  const propUnits = units.filter(u => u.Property_ID === id).map(unit => ({ ...unit, tenant: tenants.find(t => t.ID === unit.Tenant_ID)||null, keys: keys.filter(k => k.Unit_ID === unit.ID && k.Active !== 'FALSE') }));
  return json({ ...property, units: propUnits, keys: keys.filter(k => k.Property_ID === id && !k.Unit_ID && k.Active !== 'FALSE') });
}

async function getBuildingInfo(env, url) {
  const propId = url.searchParams.get('property_id'), unitId = url.searchParams.get('unit_id') || '';
  if (!propId) return json({ error: 'Missing property_id' }, 400);
  const [properties, units] = await fetchTabs(env, ['Properties','Units']);
  const prop = properties.find(p => p.ID === propId);
  if (!prop) return json({ error: 'Property not found' }, 404);
  return json({ property: prop, unit: unitId ? (units.find(u => u.ID === unitId)||null) : null, units: units.filter(u => u.Property_ID === propId) });
}

async function saveBuildingInfo(env, body) {
  const { type, id, fields, bulk_unit_ids } = body; const results = [];
  if (type === 'property') { results.push({ id, result: await updateRow(env, 'Properties', id, fields) }); }
  else if (type === 'unit') { results.push({ id, result: await updateRow(env, 'Units', id, fields) }); for (const uid of (bulk_unit_ids||[])) { if (uid !== id) results.push({ id: uid, result: await updateRow(env, 'Units', uid, fields) }); } }
  return json({ success: true, results });
}

async function ownerProperties(env, url) {
  const ownerId = url.searchParams.get('owner_id');
  if (!ownerId) return json({ error: 'Missing owner_id' }, 400);
  const [properties, units] = await fetchTabs(env, ['Properties','Units']);
  return json(properties.filter(p => p.Owner_ID === ownerId && p.Active !== 'FALSE').map(p => ({ ...p, units: units.filter(u => u.Property_ID === p.ID) })));
}

async function saveCacheEntry(env, body) {
  const data = await sheetsRequest(env, 'GET', `/values/Troubleshooting_Cache`);
  const rows = data.values || []; if (!rows.length) throw new Error('Troubleshooting_Cache tab missing headers');
  const headers = rows[0], now = new Date().toISOString().split('T')[0];
  const existing = rows.slice(1).find(r => { const obj={}; headers.forEach((h,i) => obj[h]=r[i]||''); return obj.Trade === body.trade && obj.Keywords === body.keywords; });
  if (existing) return await updateRow(env, 'Troubleshooting_Cache', existing[0], { Response: body.response, Use_Count: String(parseInt(existing[headers.indexOf('Use_Count')]||'0') + 1), Last_Used: now, Flagged: 'FALSE' });
  const newRow = headers.map(h => ({ ID: String(nextSafeId(rows)), Trade: body.trade||'', Keywords: body.keywords||'', Season: body.season||'', Property_Type: body.property_type||'', Response: body.response||'', Use_Count: '1', Created_Date: now, Last_Used: now, Flagged: 'FALSE', Flag_Reason: '', Flag_Date: '', Last_Refreshed: '', Active: 'TRUE' }[h] ?? ''));
  await sheetsRequest(env, 'POST', `/values/Troubleshooting_Cache:append?valueInputOption=RAW`, { values: [newRow] });
  return json({ success: true });
}
async function flagCacheEntry(env, body) { return await updateRow(env, 'Troubleshooting_Cache', body.id, { Flagged: 'TRUE', Flag_Reason: body.reason||'', Flag_Date: new Date().toISOString().split('T')[0] }); }
async function refreshCacheEntry(env, body) { return await updateRow(env, 'Troubleshooting_Cache', body.id, { Response: '', Flagged: 'FALSE', Flag_Reason: '', Last_Refreshed: new Date().toISOString().split('T')[0] }); }
// ── PIN GENERATION & SEND ─────────────────────────────────────

const PORTAL_BASE = 'https://ridge-co.github.io/RidgeCo';

function generatePIN(phone) {
  const alpha = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const prefix = [0,1,2].map(() => alpha[Math.floor(Math.random() * alpha.length)]).join('');
  const digits = (phone || '').replace(/\D/g, '').slice(-5).padStart(5, '0');
  return prefix + digits;
}

async function regeneratePIN(env, body) {
  const { type, id, send } = body;
  if (!type || !id) return json({ error: 'Missing type or id' }, 400);
  let tab, phoneField;
  if (type === 'vendor') { tab = 'Vendors'; phoneField = 'Phone'; }
  else if (type === 'owner_user') { tab = 'Owner_Users'; phoneField = 'Phone'; }
  else if (type === 'tenant') { tab = 'Tenants'; phoneField = 'Phone'; }
  else return json({ error: 'type must be vendor, owner_user, or tenant' }, 400);
  const rows = await fetchTab(env, tab);
  const record = rows.find(r => r.ID === id);
  if (!record) return json({ error: `${type} not found` }, 404);
  if (!record[phoneField]) return json({ error: 'Phone number required to generate PIN' }, 400);
  const newPIN = generatePIN(record[phoneField]);
  await updateRow(env, tab, id, { PIN: newPIN });
  if (send) { const sendResult = await sendPinMessage(env, { type, id }); return json({ success: true, pin: newPIN, sms_sent: !!sendResult }); }
  return json({ success: true, pin: newPIN });
}

async function sendPinMessage(env, body) {
  const { type, id } = body;
  if (!type || !id) return json({ error: 'Missing type or id' }, 400);
  let firstName, phone, pin, owner = null, address = '', vendorRec = null;
  if (type === 'tenant') {
    const [tenants, units, properties, owners] = await fetchTabs(env, ['Tenants', 'Units', 'Properties', 'Owners']);
    const t = tenants.find(r => r.ID === id);
    if (!t) return json({ error: 'Tenant not found' }, 404);
    if (!t.Phone) return json({ error: 'No phone number on file', name: t.First_Name||'' }, 400);
    if (!t.PIN)   return json({ error: 'No PIN set — set a PIN first', name: t.First_Name||'' }, 400);
    firstName = t.First_Name||'Resident'; phone = t.Phone; pin = t.PIN;
    // Sep 16 2026: resolve the tenant's own property → owner so the intro text can say "on
    // behalf of {Owner}" instead of a generic "Ridge Co" — same join welcomeSend already does.
    const unit = units.find(u => u.ID === t.Unit_ID);
    const propId = t.Property_ID || (unit && unit.Property_ID) || '';
    const property = properties.find(p => p.ID === propId) || null;
    owner = property ? (owners.find(o => o.ID === property.Owner_ID) || null) : null;
    address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : '';
  } else if (type === 'vendor') {
    const vendors = await fetchTab(env, 'Vendors'); const v = vendors.find(r => r.ID === id);
    if (!v) return json({ error: 'Vendor not found' }, 404);
    if (!v.Phone) return json({ error: 'No phone number on file', name: v.Name||'' }, 400);
    if (!v.PIN)   return json({ error: 'No PIN set — set a PIN first', name: v.Name||'' }, 400);
    firstName = (v.Name||'').split(' ')[0]; phone = v.Phone; pin = v.PIN; vendorRec = v;
  } else if (type === 'owner') {
    const owners = await fetchTab(env, 'Owners'); const o = owners.find(r => r.ID === id);
    if (!o) return json({ error: 'Owner not found' }, 404);
    if (!o.Phone) return json({ error: 'No phone on file', name: o.First_Name||'' }, 400);
    if (!o.PIN)   return json({ error: 'No PIN set', name: o.First_Name||'' }, 400);
    firstName = o.First_Name||'Owner'; phone = o.Phone; pin = o.PIN;
  } else if (type === 'owner_user') {
    const ownerUsers = await fetchTab(env, 'Owner_Users'); const u = ownerUsers.find(r => r.ID === id);
    if (!u) return json({ error: 'Owner user not found' }, 404);
    if (!u.Phone) return json({ error: 'No phone on file', name: u.First_Name||'' }, 400);
    if (!u.PIN)   return json({ error: 'No PIN set', name: u.First_Name||'' }, 400);
    firstName = u.First_Name||'Owner'; phone = u.Phone; pin = u.PIN;
  } else { return json({ error: 'Invalid type. Use: tenant, vendor, owner, owner_user' }, 400); }
  const portalUrl = type === 'vendor' ? PORTAL_BASE+'/vendor.html' : type === 'tenant' ? PORTAL_BASE+'/tenant.html' : PORTAL_BASE+'/owner.html';
  // Sep 16 2026: pulled out of a hardcoded `messages` object into Message_Templates (editable
  // in the Messaging page without a redeploy). The literal strings below are ONLY a fallback
  // for the split second before the tab is first seeded — every real send after that reads the
  // live template. Assistant persona (not Brett's own name) + "on behalf of {Owner}" + the
  // never-marketing line are Brett's explicit Sep 16 requirements; ASSISTANT_NAME defaults to
  // 'Riley' but is a one-place Config edit, not hardcoded here.
  const cfg = await fetchConfig(env);
  const assistantName = cfg.ASSISTANT_NAME || 'Riley';
  const ownerLabel = (owner && (owner.Company || owner.First_Name)) || 'your property owner';
  const tokens = { FirstName: firstName, PortalUrl: portalUrl, PIN: pin, Owner: ownerLabel, Address: address, AssistantName: assistantName };
  const templateType = type === 'owner_user' ? 'pin_owner' : `pin_${type}`;
  const tpl = await getMessageTemplate(env, templateType, 'sms');
  const fallback = {
    tenant:     `Hi ${firstName}! This is ${assistantName} with Ridge Co Property Maintenance - we handle maintenance on behalf of ${ownerLabel}. New number, worth saving (it's outbound-only for now, so texting back won't reach us yet). Portal: ${portalUrl} PIN: ${pin}. Use it to check on repair requests or submit a new one. We'll only text you about maintenance at your property, never marketing.`,
    vendor:     `Hi ${firstName}, it's ${assistantName} with Ridge Co (new text line - outbound-only for now, so a reply won't reach anyone yet). Your vendor portal's ready: ${portalUrl} PIN: ${pin}. Log in to see your jobs, update status, and upload photos.`,
    owner:      `Hi ${firstName}! This is ${assistantName} with Ridge Co (outbound-only line for now - texting back won't reach us yet). Your owner portal's ready: ${portalUrl} PIN: ${pin}. Log in to check on your work orders, submit requests, and manage your notification settings.`,
    owner_user: `Hi ${firstName}! This is ${assistantName} with Ridge Co (outbound-only line for now - texting back won't reach us yet). Your owner portal's ready: ${portalUrl} PIN: ${pin}. Log in to check on your work orders, submit requests, and manage your notification settings.`,
  };
  const message = (m => type === 'tenant' ? withTenantStopNote(m) : m)(tpl ? renderTemplate(tpl.Body, tokens) : fallback[type]);
  if (body.preview_only) return json({ preview: message, phone, name: firstName, pin, will_translate_to: vendorRec && vendorWantsSpanish(vendorRec) ? 'es' : '' });
  // Vendor language (Sep 28 2026): the PIN text goes out in Spanish for a Spanish vendor. The
  // PIN, portal link and amounts are verified intact or the English original is sent.
  let outMessage = message, translatedTo = '';
  if (vendorRec) { const t = await translateForVendorDetailed(env, vendorRec, message); if (t.translated) { outMessage = t.text; translatedTo = 'es'; } }
  await sendSMS(env, phone, outMessage);
  await logSMS(env, '', `pin_send_${type}`, id, phone, `[PIN sent to ${firstName}]`);
  return json({ success: true, sent_to: phone, name: firstName, translated_to: translatedTo });
}

// POST /welcome/send { type: 'tenant'|'vendor', id, preview_only?, message? } — Sep 14 2026,
// Brett. Distinct from sendPinMessage above: that sends portal credentials; this is a warm
// intro ("this is Ridge Co, save this number") that never includes a PIN. Goes through the
// real gated pipeline (smsGatedSend), unlike sendPinMessage's direct sendSMS — a welcome text
// still respects Global/Test Mode/the person's own SMS_Enabled toggle, and lands in
// Message_Queue for review like every other gated message. The default text generated here is
// PERSONALIZED (real name/address) for the single-send preview; body.message, if provided,
// overrides it entirely — the Hub always lets Brett edit before sending (single: pre-filled
// textarea; bulk: one shared editable text for the whole batch, deliberately generic/unnamed).
async function welcomeSend(env, body) {
  const { type, id } = body;
  if (!type || !id) return json({ error: 'Missing type or id' }, 400);
  let recipient, firstName, phone, defaultMsg, property = null, owner = null;
  // Sep 17 2026 (Brett): a bulk welcome send lets Brett edit the shared text before sending —
  // that edited text (body.message) needs the SAME {FirstName}/{Owner}/{Address}/{AssistantName}
  // substitution the template default already gets, or a bulk batch would either send every
  // recipient the literal, un-personalized string, or (worse) the literal "{FirstName}" text if
  // Brett left the template's own tokens in place expecting them to fill in per person. `tokens`
  // is populated per type below and applied to body.message too, not just the template default.
  let tokens = {};
  if (type === 'tenant') {
    const [tenants, units, properties, owners] = await fetchTabs(env, ['Tenants','Units','Properties','Owners']);
    recipient = tenants.find(t => t.ID === id);
    if (!recipient) return json({ error: 'Tenant not found' }, 404);
    if (!recipient.Phone) return json({ error: 'No phone number on file', name: recipient.First_Name||'' }, 400);
    firstName = recipient.First_Name || 'there';
    phone = recipient.Phone;
    const unit = units.find(u => u.ID === recipient.Unit_ID);
    const propId = recipient.Property_ID || (unit && unit.Property_ID) || '';
    property = properties.find(p => p.ID === propId) || null;
    owner = property ? owners.find(o => o.ID === property.Owner_ID) || null : null;
    const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'your unit';
    // Sep 16 2026 (Brett): dropped the "text us anytime with a request" / "reply here" promise
    // — handleInboundSMS only recognizes vendor phone numbers today, so a tenant texting in
    // a new request or a question currently gets a nonsensical "could not find your vendor
    // record" auto-reply. Revisit once a real tenant intake path (form or inbound routing)
    // exists — this welcome text should only promise what actually works right now.
    // Sep 16 2026: now reads from the editable tenant_welcome/sms template (assistant persona,
    // "on behalf of {Owner}", never-marketing line) — same template pin_tenant shares the
    // tone with, so the two don't drift again the way the old hardcoded copies did.
    {
      const cfg = await fetchConfig(env);
      const assistantName = cfg.ASSISTANT_NAME || 'Riley';
      const ownerLabel = (owner && (owner.Company || owner.First_Name)) || 'your property owner';
      const tpl = await getMessageTemplate(env, 'tenant_welcome', 'sms');
      tokens = { FirstName: firstName, Address: address, Owner: ownerLabel, AssistantName: assistantName };
      defaultMsg = tpl ? renderTemplate(tpl.Body, tokens)
        : `Hi ${firstName}, this is ${assistantName} with Ridge Co Property Maintenance - we handle maintenance on behalf of ${ownerLabel} at ${address}. Save this number (outbound-only for now, so a text back won't reach anyone yet) - we'll only text about maintenance here, never marketing.`;
    }
  } else if (type === 'vendor') {
    const vendors = await fetchTab(env, 'Vendors');
    recipient = vendors.find(v => v.ID === id);
    if (!recipient) return json({ error: 'Vendor not found' }, 404);
    if (!recipient.Phone) return json({ error: 'No phone number on file', name: recipient.Name||'' }, 400);
    firstName = (recipient.Name || 'there').split(' ')[0];
    phone = recipient.Phone;
    {
      const cfg = await fetchConfig(env);
      const assistantName = cfg.ASSISTANT_NAME || 'Riley';
      const tpl = await getMessageTemplate(env, 'vendor_welcome', 'sms');
      tokens = { FirstName: firstName, PortalUrl: PORTAL_BASE + '/vendor.html', AssistantName: assistantName };
      defaultMsg = tpl ? renderTemplate(tpl.Body, tokens)
        : `Hi ${firstName}, it's ${assistantName} with Ridge Co. Save this number - you'll get job details by text whenever we assign you work, plus a link to your vendor portal (${PORTAL_BASE}/vendor.html) to accept jobs, log time, and submit invoices. (This line is outbound-only for now - a text back won't reach anyone yet.)`;
    }
  } else {
    return json({ error: 'Invalid type. Use: tenant or vendor' }, 400);
  }
  if (type === 'tenant') defaultMsg = withTenantStopNote(withWelcomeRatesNote(defaultMsg));
  if (body.preview_only) return json({ preview: defaultMsg, phone, name: firstName });
  // Apply the same token substitution to a custom/edited message as the template default gets
  // — a no-op for plain text with no {Token} in it, correct per-recipient fill-in for anything
  // that came from (or still contains) the live template's tokens, e.g. a bulk send.
  const finalMsg = (m => type === 'tenant' ? withTenantStopNote(withWelcomeRatesNote(m)) : m)(body.message ? renderTemplate(String(body.message), tokens) : defaultMsg);
  const sendOpts = type === 'tenant'
    ? { wo_id: '', message_type: 'tenant_welcome', recipient_type: 'tenant', tenant: recipient, property, owner, message_body: finalMsg, allowPendingConsent: true }
    : { wo_id: '', message_type: 'vendor_welcome', recipient_type: 'vendor', vendor: recipient, message_body: finalMsg };
  const r = await smsGatedSend(env, sendOpts);
  // Sep 15 2026 — same fix as createVendorRequest/processVendorNudges (found live-testing
  // both the same day): a quiet-hours hold returns sent:false from smsGatedSend even though
  // the message WILL go out once quiet hours end (it's correctly queued, not failed). Treating
  // that as an error here had two real consequences: (1) the caller got a false "Send failed"
  // 502 for a message that was actually working correctly, and (2) because the function
  // returned before reaching the Welcome_Sent write below, a person with a legitimately queued
  // welcome message would still show as "not yet welcomed" in the Hub's own filter.
  if (!r.sent && !r.held_for_quiet_hours) return json({ error: r.send_ok ? 'Send failed' : ('Blocked: ' + r.gate_snapshot), name: firstName }, r.send_ok ? 502 : 400);
  await ensureColumns(env, type === 'tenant' ? 'Tenants' : 'Vendors', ['Welcome_Sent','Welcome_Sent_Date']);
  const _wf = { Welcome_Sent: 'TRUE', Welcome_Sent_Date: new Date().toISOString() };
  // Oct 14 2026: Brett sending the welcome to a roster-added tenant (consent pending) IS the go-ahead: switch their texts on and
  // record it. The tenant can still reply STOP (SMS_OptOut, which this never touches).
  const _consentFlip = type === 'tenant' && String(recipient.SMS_Consent || '') === 'pending';
  if (_consentFlip) { await ensureColumns(env, 'Tenants', ['SMS_Consent', 'SMS_Enabled']); _wf.SMS_Consent = 'welcome_sent'; _wf.SMS_Enabled = 'TRUE'; }
  const _wr = await updateRow(env, type === 'tenant' ? 'Tenants' : 'Vendors', id, _wf);
  if (!_wr.ok) return json({ success: true, sent_to: phone, name: firstName, warning: 'The welcome text WAS sent/queued, but the "welcomed" mark could not be saved: ' + await respErrText(_wr) + ' - it will still show as not welcomed.' }, 200);
  return json({ success: true, sent_to: r.held_for_quiet_hours ? '(queued — held for quiet hours)' : (r.test_mode ? '(test mode)' : phone), held_for_quiet_hours: !!r.held_for_quiet_hours, name: firstName });
}

// POST /property/notice { property_id, message?, email_subject?, email_body?,
// channels: ['sms']|['sms','email'], preview_only } — Sep 16 2026, Brett. A property-wide
// broadcast: every active tenant at one property, one shot (water shutoffs, power outages,
// anything affecting the whole building). Deliberately its own function rather than a loop
// over welcomeSend/smsGatedSend call sites elsewhere: this is the one place that (a) bypasses
// the quiet-hours hold — an urgent notice can't wait for a 9am release the way a routine
// status update can — while (b) still honoring Global/Test Mode and each tenant's own
// SMS_OptOut. Urgent doesn't mean "ignore an explicit opt-out." Email is a separate channel,
// sent directly via gmailSendEmail (not gated by the SMS toggle system, since it isn't SMS).
async function sendPropertyNotice(env, body) {
  const propertyId = body.property_id;
  if (!propertyId) return json({ error: 'property_id required' }, 400);
  const channels = Array.isArray(body.channels) && body.channels.length ? body.channels : ['sms'];
  // unit_id (Sep 23 2026, additive): when passed, narrows the broadcast down to that one unit's
  // tenant(s) instead of every active tenant in the building, and adds a {Unit} token so a
  // template can reference it. No unit_id (the pre-existing default) still means the original
  // building-wide broadcast with no Unit token — unchanged for every existing caller.
  const unitId = body.unit_id || '';
  const [properties, owners, tenants, units] = await fetchTabs(env, ['Properties', 'Owners', 'Tenants', 'Units']);
  const property = properties.find(p => p.ID === propertyId);
  if (!property) return json({ error: 'Property not found' }, 404);
  const owner = property ? (owners.find(o => o.ID === property.Owner_ID) || null) : null;
  const unit = unitId ? units.find(u => u.ID === unitId) : null;
  if (unitId && !unit) return json({ error: 'Unit not found' }, 404);
  const activeTenants = tenants.filter(t => {
    // Oct 14 2026: isTenantCurrent also drops a tenant whose Move_Out_Date has passed (Active alone missed that).
    if (!isTenantCurrent(t)) return false;
    if (String(t.Property_ID) !== String(propertyId)) return false;
    if (unitId) return t.Unit_ID === unitId;
    return true;
  });

  const cfg = await fetchConfig(env);
  const assistantName = cfg.ASSISTANT_NAME || 'Riley';
  const ownerLabel = (owner && (owner.Company || owner.First_Name)) || 'your property owner';
  const unitToken = unit && unit.Unit_Label ? formatUnitLabel(unit.Unit_Label) : '';
  const tokens = { Address: property.Address || '', Owner: ownerLabel, AssistantName: assistantName, Unit: unitToken };

  const smsTpl = await getMessageTemplate(env, 'property_notice', 'sms');
  const emailTpl = await getMessageTemplate(env, 'property_notice', 'email');
  const smsBody = body.message ? String(body.message) : renderTemplate(smsTpl ? smsTpl.Body : '', tokens);
  const emailSubject = body.email_subject ? String(body.email_subject) : renderTemplate(emailTpl ? emailTpl.Subject : 'Maintenance update - {Address}', tokens);
  const emailBody = body.email_body ? String(body.email_body) : renderTemplate(emailTpl ? emailTpl.Body : '', tokens);

  const isOptedOut = t => String(t.SMS_OptOut || '').toUpperCase() === 'TRUE';
  const smsRecipients = channels.includes('sms') ? activeTenants.filter(t => t.Phone && !isOptedOut(t)) : [];
  const smsSkippedOptOut = channels.includes('sms') ? activeTenants.filter(t => t.Phone && isOptedOut(t)).length : 0;
  const emailRecipients = channels.includes('email') ? activeTenants.filter(t => t.Email) : [];

  if (body.preview_only) {
    return json({
      property_address: property.Address, owner: ownerLabel,
      sms_message: smsBody, email_subject: emailSubject, email_body: emailBody,
      total_active_tenants: activeTenants.length,
      sms_recipient_count: smsRecipients.length, sms_skipped_opted_out: smsSkippedOptOut,
      email_recipient_count: emailRecipients.length,
    });
  }

  const results = { sms_sent: 0, sms_failed: 0, sms_queued_quiet_hours: 0, email_sent: 0, email_failed: 0 };
  for (const tenant of smsRecipients) {
    try {
      const r = await smsGatedSend(env, { wo_id: body.wo_id || '', message_type: 'property_notice', recipient_type: 'tenant', tenant, owner, property, message_body: smsBody, bypassQuietHours: true });
      if (r.sent) results.sms_sent++; else if (r.held_for_quiet_hours) results.sms_queued_quiet_hours++; else results.sms_failed++;
    } catch (e) { results.sms_failed++; }
  }
  if (channels.includes('email')) {
    for (const tenant of emailRecipients) {
      try { await gmailSendEmail(env, { to: tenant.Email, subject: emailSubject, html: emailBody }); results.email_sent++; }
      catch (e) { results.email_failed++; }
    }
  }
  return json({ success: true, property_address: property.Address, ...results, skipped_opted_out: smsSkippedOptOut });
}

// ── VENDOR BILLING ───────────────────────────────────────────

// B-20260916-1930-k7: vendor invoice confirmation email — pure date/holiday helpers.
// See context/VENDOR_INVOICE_CONFIRMATION_EMAIL_BUILD_BRIEF_v1.0.md for the full design.
// Config.US_HOLIDAYS holds "YYYY-MM-DD:Name,YYYY-MM-DD:Name,..." — a small, Brett-maintained
// list (no floating-holiday date math to get subtly wrong), parsed into a Map here.
function parseHolidayMap(raw) {
  const map = new Map();
  String(raw || '').split(',').forEach(pair => {
    const idx = pair.indexOf(':');
    if (idx < 0) return;
    const date = pair.slice(0, idx).trim();
    const name = pair.slice(idx + 1).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(date) && name) map.set(date, name);
  });
  return map;
}

// The next BUSINESS day strictly after dateStr — skips Saturday, Sunday, and any date in
// holidayMap. Returns the date the clock starts on, plus which (if any) named holidays were
// skipped, so the caller can decide whether to explain the shift to the vendor. A skipped
// weekend with no named holiday is NOT reported — that's the ordinary, expected case and
// doesn't need explaining every time.
function nextBusinessDay(dateStr, holidayMap) {
  const hmap = holidayMap instanceof Map ? holidayMap : new Map();
  const d = new Date(String(dateStr || '') + 'T00:00:00Z');
  if (isNaN(d.getTime())) return { date: '', skippedHolidays: [] };
  const skippedHolidays = [];
  d.setUTCDate(d.getUTCDate() + 1);
  for (let guard = 0; guard < 30; guard++) {
    const iso = d.toISOString().split('T')[0];
    const dow = d.getUTCDay();
    const holidayName = hmap.get(iso);
    if (dow !== 0 && dow !== 6 && !holidayName) return { date: iso, skippedHolidays };
    if (holidayName) skippedHolidays.push({ date: iso, name: holidayName });
    d.setUTCDate(d.getUTCDate() + 1);
  }
  return { date: '', skippedHolidays }; // guard tripped — malformed/huge holiday list, fail safe rather than loop forever
}

// The vendor payment window: clock starts the next business day after submission, due 14
// calendar days after that (Brett's own rule — a calendar-day count from a business-day start,
// not 14 more business days).
function vendorPaymentWindow(submissionDateStr, holidayMap) {
  const start = nextBusinessDay(submissionDateStr, holidayMap);
  if (!start.date) return null;
  const due = new Date(start.date + 'T00:00:00Z');
  due.setUTCDate(due.getUTCDate() + 14);
  return { clock_start: start.date, due_date: due.toISOString().split('T')[0], skipped_holidays: start.skippedHolidays };
}

// B-20260916-1930-k7: the confirmation email itself. Best-effort — every caller wraps this in
// its own try/catch; a failure here must never fail or slow the vendor's Submit tap. Soft-
// launched behind Config.VENDOR_INVOICE_EMAIL_TEST_VENDOR_IDS (comma-separated Vendor IDs) so
// it can be proven on one real vendor (Alex Busey) before being widened to everyone. Attachments
// are sent as signed /vendor-file/view links (the same private-file proxy the portal already
// uses), NEVER as a raw drive.google.com share link — these files are deliberately never made
// "anyone with the link" shareable (privacy — FEATURE_LOG rule 13), and a bare Drive link would
// silently repeat the WO-1071 black-page bug.
async function sendVendorInvoiceConfirmationEmail(env, billRow) {
  const vendorId = billRow.Vendor_ID || billRow.vendor_id || '';
  const woId = billRow.WO_ID || billRow.wo_id || '';
  if (!vendorId || !woId) return;
  const config = await fetchConfig(env);
  const allowIds = String(config.VENDOR_INVOICE_EMAIL_TEST_VENDOR_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!allowIds.includes(String(vendorId))) return; // soft launch — not enabled for this vendor yet

  const [vendors, wos, properties] = await Promise.all([
    fetchTab(env, 'Vendors').catch(() => []),
    fetchTab(env, 'Work_Orders').catch(() => []),
    fetchTab(env, 'Properties').catch(() => []),
  ]);
  const vendor = vendors.find(v => String(v.ID) === String(vendorId));
  if (!vendor) return;

  if (!vendor.Email) {
    // Ask once, via SMS (subject to the standing Config.TWILIO_ENABLED switch, same as every
    // other SMS in this file) — never re-nudge on every future bill while Email stays blank.
    if (!vendor.Email_Request_Sent_Date) {
      try { await ensureColumns(env, 'Vendors', ['Email_Request_Sent_Date']); } catch (e) {}
      const vname = (vendor.First_Name || (vendor.Name || '').split(' ')[0] || '').trim();
      const msg = (vendor.Language === 'es')
        ? `Hola${vname ? ' ' + vname : ''}, no tenemos un correo electrónico registrado para usted. Agréguelo en su portal de proveedores de Ridge Co para recibir una copia de cada factura que envíe y la fecha de pago.`
        : `Hi${vname ? ' ' + vname : ''}, we don't have an email on file for you. Add one in your Ridge Co vendor portal so we can send you a copy of every invoice you submit and when payment is due.`;
      try {
        await sendSMS(env, vendor.Phone, msg);
        await updateRow(env, 'Vendors', vendor.ID, { Email_Request_Sent_Date: new Date().toISOString().split('T')[0] });
      } catch (e) {}
    }
    return;
  }

  const wo = findWO(wos, woId) || {};
  const prop = wo.Property_ID ? properties.find(p => String(p.ID) === String(wo.Property_ID)) : null;
  const address = prop ? (prop.Address || '') : '';
  const isEs = vendor.Language === 'es';
  let description = wo.Description || '';
  if (isEs && description) { try { const t = await translateText(env, description, 'English', 'Spanish'); if (t) description = t; } catch (e) {} }

  const holidayMap = parseHolidayMap(config.US_HOLIDAYS);
  const submissionDate = String(billRow.Submitted_At || new Date().toISOString()).split('T')[0];
  const win = vendorPaymentWindow(submissionDate, holidayMap);
  const submittedDisplay = billRow.Submitted_At
    ? new Date(billRow.Submitted_At).toLocaleString('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
    : '';
  const dueDisplay = win ? new Date(win.due_date + 'T00:00:00Z').toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' }) : '';
  const reasonEn = (win && win.skipped_holidays.length) ? ` (${win.skipped_holidays.map(h => h.name).join(', ')} falls in between, so the window starts a bit later than usual)` : '';
  const reasonEs = (win && win.skipped_holidays.length) ? ` (${win.skipped_holidays.map(h => h.name).join(', ')} cae en medio, así que la ventana comienza un poco más tarde de lo habitual)` : '';

  const base = String(env.WORKER_BASE_URL || 'https://maintenance-hub.brett-2f8.workers.dev').replace(/\/+$/, '');
  let fileToken = '';
  try { fileToken = await makeSessionToken({ role: 'vendor', id: vendor.ID }, env.WORKER_SECRET); } catch (e) {}
  const fileLink = (fileId) => `${base}/vendor-file/view?wo_id=${encodeURIComponent(woId)}&file_id=${encodeURIComponent(fileId)}&t=${encodeURIComponent(fileToken)}`;

  const linkRows = [];
  if (fileToken && billRow.Invoice_File_ID) {
    linkRows.push(`<li><a href="${_escHtml(fileLink(billRow.Invoice_File_ID))}">${isEs ? 'Su factura' : 'Your invoice file'}</a></li>`);
  }
  if (fileToken) {
    let receipts = [];
    try { receipts = JSON.parse(billRow.Receipts_JSON || '[]'); } catch (e) {}
    (Array.isArray(receipts) ? receipts : []).forEach((r, i) => {
      if (!r || r.pay === 'account' || !r.url) return;
      const fid = driveIdFromUrl(r.url);
      if (!fid) return;
      const label = r.desc ? _escHtml(String(r.desc)) : (isEs ? `Recibo ${i + 1}` : `Receipt ${i + 1}`);
      linkRows.push(`<li><a href="${_escHtml(fileLink(fid))}">${label}</a></li>`);
    });
  }

  const vname = (vendor.First_Name || (vendor.Name || '').split(' ')[0] || '').trim();
  const html = isEs ? [
    `<p>Hola${vname ? ' ' + vname : ''},</p>`,
    `<p>Hemos recibido su factura para <b>OT ${_escHtml(woId)}</b>${address ? ' — ' + _escHtml(address) : ''}${description ? '<br>' + _escHtml(description) : ''}.</p>`,
    `<ul>`,
    billRow.Vendor_Invoice_No ? `<li>Su número de factura: ${_escHtml(billRow.Vendor_Invoice_No)}</li>` : '',
    billRow.Vendor_Invoice_Date ? `<li>Fecha de la factura: ${_escHtml(billRow.Vendor_Invoice_Date)}</li>` : '',
    billRow.Total ? `<li>Monto: $${_escHtml(billRow.Total)}</li>` : '',
    submittedDisplay ? `<li>Enviado: ${_escHtml(submittedDisplay)}</li>` : '',
    `</ul>`,
    linkRows.length ? `<p>Archivos que envió:</p><ul>${linkRows.join('')}</ul>` : '',
    win ? `<p>Ventana de pago estándar: 14 días, comenzando el siguiente día hábil después del envío${reasonEs}. Fecha de pago prevista: <b>${_escHtml(dueDisplay)}</b>.</p>` : '',
    `<p style="color:#888;font-size:11px">Ridge Co — esta es una confirmación automática, no es necesario responder.</p>`,
  ] : [
    `<p>Hi${vname ? ' ' + vname : ''},</p>`,
    `<p>We've received your invoice for <b>WO ${_escHtml(woId)}</b>${address ? ' — ' + _escHtml(address) : ''}${description ? '<br>' + _escHtml(description) : ''}.</p>`,
    `<ul>`,
    billRow.Vendor_Invoice_No ? `<li>Your invoice #: ${_escHtml(billRow.Vendor_Invoice_No)}</li>` : '',
    billRow.Vendor_Invoice_Date ? `<li>Invoice date: ${_escHtml(billRow.Vendor_Invoice_Date)}</li>` : '',
    billRow.Total ? `<li>Amount: $${_escHtml(billRow.Total)}</li>` : '',
    submittedDisplay ? `<li>Submitted: ${_escHtml(submittedDisplay)}</li>` : '',
    `</ul>`,
    linkRows.length ? `<p>Files you submitted:</p><ul>${linkRows.join('')}</ul>` : '',
    win ? `<p>Standard payment window: 14 days, starting the next business day after submission${reasonEn}. Expected payment date: <b>${_escHtml(dueDisplay)}</b>.</p>` : '',
    `<p style="color:#888;font-size:11px">Ridge Co — this is an automated confirmation, no reply needed.</p>`,
  ];
  const subject = isEs ? `Hemos recibido su factura — OT ${woId}` : `We've received your invoice — WO ${woId}`;
  let emailOutcome = 'failed';
  try { await gmailSendEmail(env, { to: vendor.Email, subject, html: html.filter(Boolean).join('\n') }); emailOutcome = 'sent'; } catch (e) { emailOutcome = 'failed'; throw e; }
  finally {
    // Per-WO communication audit (Sep 20 2026) — same visibility as the SMS side (smsGatedSend).
    try { await logMessageAudit(env, { woId, channel: 'email', recipientName: vendor.Name || vendor.First_Name || '', recipientType: 'vendor', messageType: 'vendor_invoice_confirmation', messageBody: subject + '\n\n' + html.filter(Boolean).join('\n'), outcome: emailOutcome }); } catch (e) {}
  }
}

// ── Vendor Loan/Advance Ledger (CAP-036 #13, Sep 24 2026, Brett-confirmed) ──────────────────
// A GENERAL, reusable running-balance ledger on the Vendor record — any vendor, not
// hardcoded to Gina or Alex. One tab covers both use cases, distinguished by Entry_Type:
//   'manual'         — Gina (Venmo, bypasses the invoice-payment system on purpose): Brett
//                       adds an entry with an amount + direction + date; balance moves either
//                       way (a loan/advance increases it, a repayment decreases it).
//   'auto-deduction' — Alex (and any other vendor with a nonzero balance): automatically
//                       deducted from the LABOR portion of each invoice at bill-payment time
//                       (see applyVendorLoanDeduction, called from qbSendInvoice).
//   'seed'           — a one-time starting-balance entry (e.g. Alex's $210 placeholder).
// Amount is stored SIGNED (+ increases balance / a loan given, − decreases it / a repayment)
// so the running balance is always just a sum — Balance_After is a snapshot for fast display,
// recomputed from the full history so a stray edit can never leave it silently wrong.
// Self-provisions on first write, same pattern as ensureTrashTabs/ensureDeliveryTab/ensureInspTabs.
const LOAN_LEDGER_TAB = 'Vendor_Loan_Ledger';
const LOAN_LEDGER_HEADERS = ['ID','Vendor_ID','Vendor_Name','Entry_Type','Direction','Amount','Balance_After','Labor_Amount','Bill_ID','WO_ID','Date','Notes','Entered_By','Created_Date','Active'];

async function ensureLoanLedgerTab(env) {
  const meta = await sheetsRequest(env, 'GET', '?fields=sheets.properties.title');
  const titles = (meta.sheets || []).map(s => s.properties && s.properties.title).filter(Boolean);
  if (!titles.includes(LOAN_LEDGER_TAB)) {
    await sheetsRequest(env, 'POST', ':batchUpdate', { requests: [{ addSheet: { properties: { title: LOAN_LEDGER_TAB } } }] });
  }
  await ensureColumns(env, LOAN_LEDGER_TAB, LOAN_LEDGER_HEADERS);
}

// Sum of every active entry's signed Amount for one vendor = the current balance.
// Balance > 0 means the vendor owes Ridge Co (a loan/advance outstanding); 0 or less
// means paid off (a negative balance would mean Brett owes THEM, which the deduction
// logic below can never create — it stops exactly at 0, see computeLoanDeduction).
async function getVendorLoanBalance(env, vendorId) {
  let rows = [];
  try { rows = await fetchTab(env, LOAN_LEDGER_TAB); } catch (e) { return 0; } // tab doesn't exist yet → no loans
  return rows.filter(r => r.Active !== 'FALSE' && String(r.Vendor_ID) === String(vendorId))
    .reduce((sum, r) => sum + (parseFloat(r.Amount) || 0), 0);
}

// Appends one ledger entry and returns the new running balance. `direction` is 'loan' (balance
// goes up) or 'repayment' (balance goes down) — the caller passes a positive `amount` either
// way; the sign is applied here so a mistaken negative amount can never flip the meaning.
async function addVendorLoanEntry(env, opts) {
  await ensureLoanLedgerTab(env);
  const direction = opts.direction === 'loan' ? 'loan' : 'repayment';
  const signedAmount = direction === 'loan' ? Math.abs(Number(opts.amount) || 0) : -Math.abs(Number(opts.amount) || 0);
  const priorBalance = await getVendorLoanBalance(env, opts.vendorId);
  const balanceAfter = +(priorBalance + signedAmount).toFixed(2);
  const row = {
    Vendor_ID: String(opts.vendorId),
    Vendor_Name: opts.vendorName || '',
    Entry_Type: opts.entryType || 'manual',   // manual | auto-deduction | seed
    Direction: direction,
    Amount: signedAmount.toFixed(2),
    Balance_After: balanceAfter.toFixed(2),
    Labor_Amount: (opts.laborAmount != null && opts.laborAmount !== '') ? Number(opts.laborAmount).toFixed(2) : '',
    Bill_ID: opts.billId || '',
    WO_ID: opts.woId || '',
    Date: opts.date || new Date().toISOString().split('T')[0],
    Notes: opts.notes || '',
    Entered_By: opts.enteredBy || 'Brett',
  };
  await addRow(env, LOAN_LEDGER_TAB, row);
  return balanceAfter;
}

// GET /vendor-loan?vendor_id=X — running balance + full entry history for one vendor
// (admin UI: Vendor edit view + the manual-entry ledger modal).
async function vendorLoanGet(env, url) {
  const vendorId = (url.searchParams.get('vendor_id') || '').trim();
  if (!vendorId) return json({ error: 'vendor_id required' }, 400);
  let rows = [];
  try { rows = await fetchTab(env, LOAN_LEDGER_TAB); } catch (e) { rows = []; } // no tab yet = no history
  const entries = rows.filter(r => r.Active !== 'FALSE' && String(r.Vendor_ID) === String(vendorId))
    .sort((a, b) => (parseInt(a.ID) || 0) - (parseInt(b.ID) || 0));
  const balance = entries.reduce((sum, r) => sum + (parseFloat(r.Amount) || 0), 0);
  return json({ vendor_id: vendorId, balance: +balance.toFixed(2), entries });
}

// POST /vendor-loan/add { vendor_id, vendor_name?, amount, direction: 'loan'|'repayment',
// date?, notes?, entered_by? } — Gina's manual ledger (and anyone else's manual correction).
// Always Entry_Type 'manual'; the automatic path (applyVendorLoanDeduction) writes its own
// 'auto-deduction' rows directly and never goes through this endpoint.
async function vendorLoanAdd(env, body) {
  const vendorId = String(body.vendor_id || '').trim();
  const amount = Number(body.amount);
  const direction = body.direction === 'loan' ? 'loan' : (body.direction === 'repayment' ? 'repayment' : null);
  if (!vendorId) return json({ error: 'vendor_id required' }, 400);
  if (!(amount > 0)) return json({ error: 'amount must be a positive number' }, 400);
  if (!direction) return json({ error: "direction must be 'loan' or 'repayment'" }, 400);
  const balance = await addVendorLoanEntry(env, {
    vendorId, vendorName: body.vendor_name || '', entryType: 'manual', direction,
    amount, date: body.date || '', notes: body.notes || '', enteredBy: body.entered_by || 'Brett',
  });
  return json({ success: true, balance });
}

// PURE — the Alex/vendor-loan automatic-deduction formula (CAP-036 #13, Sep 24 2026,
// Brett-confirmed spec; edge cases pinned in test/vendor-loan-deduction.test.mjs).
//   laborAmount    — the LABOR-ONLY portion of the invoice being paid. Never materials or
//                    reimbursement — those pass through to the vendor untouched regardless
//                    of loan balance (Brett's stated rationale: materials spend isn't within
//                    the vendor's control, so it must not speed up repayment).
//   currentBalance — the vendor's loan balance BEFORE this invoice's deduction.
// Returns the dollar amount to deduct. $0 whenever there's no balance to repay or labor is
// under $100. Otherwise: 2.5% of labor at exactly $100, scaling linearly up to 5% at $500+
// labor, capped at $25/invoice, then rounded to the nearest $2.50 — DOWN when labor is under
// $350, UP at $351+ (exactly $350 rounds down, same side as "under"). The one exception: a
// deduction that would clear the balance is never rounded and never exceeds what's actually
// owed — it pays the exact remaining balance instead, whether that shortfall shows up before
// or only after rounding.
function computeLoanDeduction(laborAmount, currentBalance) {
  const labor = Number(laborAmount) || 0;
  const balance = Number(currentBalance) || 0;
  if (balance <= 0 || labor < 100) return 0;

  const pct = labor >= 500 ? 0.05 : 0.025 + (labor - 100) * (0.05 - 0.025) / (500 - 100);
  let deduction = Math.min(labor * pct, 25);

  // Payoff check #1: the raw (capped, unrounded) deduction already clears the balance.
  if (deduction >= balance) return +balance.toFixed(2);

  const roundUp = labor >= 351;
  deduction = roundUp ? Math.ceil(deduction / 2.5) * 2.5 : Math.floor(deduction / 2.5) * 2.5;

  // Payoff check #2: rounding (specifically rounding UP) can push it past the balance too.
  if (deduction >= balance) return +balance.toFixed(2);

  return +deduction.toFixed(2);
}

// STEP 1 (read-only) — figures out whether a loan deduction applies to this bill and how
// much, WITHOUT writing anything. Split from the ledger write (recordVendorLoanDeduction,
// below) on purpose: qbSendInvoice's bill POST can fail (a bad vendor ref, an Intuit hiccup)
// and get retried on the next send attempt, and this row's QB_Bill_ID only gets set on
// success — so writing the ledger entry here, before we know the bill actually posted, would
// double-deduct on every retry of a failed send. Compute the adjustment early (to size the
// bill payload correctly); record it only after billId comes back real.
async function computeVendorLoanAdjustment(env, { vendorId, vendorCost, billRow }) {
  const balance = await getVendorLoanBalance(env, vendorId);
  if (!(balance > 0)) return { deduction: 0, laborAmount: 0, balance: 0 };

  const isFlat = String((billRow && billRow.Bill_Type) || '').toLowerCase() === 'flat';
  const laborAmount = isFlat ? (parseFloat(billRow && billRow.Flat_Rate) || 0) : (parseFloat(billRow && billRow.Labor_Total) || 0);
  const deduction = computeLoanDeduction(laborAmount, balance);
  // Never deduct more than the vendor is actually being paid on this bill — the loan ledger
  // is repaid out of what they're owed, not created as a negative payable.
  const safeDeduction = Math.min(deduction, Math.max(0, vendorCost));
  return { deduction: safeDeduction > 0 ? safeDeduction : 0, laborAmount, balance };
}

// STEP 2 (writes) — call ONLY after the QuickBooks Bill has actually been created (a real
// billId came back). General on purpose — ANY vendor with a nonzero balance gets this, not
// just Alex.
async function recordVendorLoanDeduction(env, { vendorId, vendorName, deduction, laborAmount, billId, woId }) {
  return await addVendorLoanEntry(env, {
    vendorId, vendorName, entryType: 'auto-deduction', direction: 'repayment',
    amount: deduction, laborAmount, billId, woId,
    notes: `Auto-deducted from invoice payment (labor $${Number(laborAmount).toFixed(2)})`,
  });
}

async function addVendorBill(env, body) {
  { const _blk = await bidGroupWriteBlock(env, body.WO_ID || body.wo_id, 'vendor bills', 'facturas', '/vendor-bill/add'); if (_blk) return json({ error: _blk.message, code: 'bid_group_cancelled', refusal_logged: _blk.logged }, 409); }
  // Vendor_Bills stores Created_Date as a date only, so the finest duplicate window
  // available here is the same day: same job, same vendor, same total, same day, still
  // sitting unreviewed. That is a re-submit, not a second bill. Returned as success with
  // duplicate:true rather than an error — the vendor's bill IS recorded, and reporting a
  // failure is what drives the next re-tap in the first place.
  // Notes, Hours and the receipts subtotal are all in the signature, not just the total.
  // A same-day window is coarse — two genuine visits to one job in a day can carry the
  // same trip charge — so the rest of the bill has to match byte-for-byte before this
  // treats it as a re-submit. An already-reviewed bill never blocks a new one.
  const dupeKey = body.WO_ID || body.wo_id;
  if (dupeKey && body.Total) {
    const dupe = await findRecentDuplicate(env, 'Vendor_Bills', {
      WO_ID: dupeKey, Vendor_ID: String(body.Vendor_ID || ''), Total: String(body.Total),
      Status: 'submitted', Notes: String(body.Notes || ''), Hours: String(body.Hours || ''),
      Receipts_Total: String(body.Receipts_Total || ''),
      Invoice_Description: String(body.Invoice_Description || ''),
    }, 86400);
    if (dupe) {
      // A re-submit didn't create a second bill, but the hours it was built from still
      // belong to the bill that DID get created. Link them to that one rather than leaving
      // them loose and billable a second time.
      try { await linkTimeEntriesToBill(env, body.time_entry_ids, String(dupe.ID || ''), dupeKey); } catch (e) {}
      return json({ success: true, duplicate: true, id: String(dupe.ID || '') });
    }
  }
  // Vendor_Bills has no column for the vendor's own invoice number until something needs
  // one, and addRow maps by header — a write to a missing column stores nothing silently.
  if (body.Vendor_Invoice_No) { try { await ensureColumns(env, 'Vendor_Bills', ['Vendor_Invoice_No']); } catch (e) {} }
  // Same lazy pattern for the vendor's own invoice DATE (Aug 31 2026, invoice-OCR pre-fill —
  // Created_Date already means "the day this bill row was submitted," not the date printed on
  // the vendor's invoice, so this is a genuinely new fact, not a rename/reuse of an existing
  // column). Only touches the sheet when a caller actually sends one — neither the plain hourly/
  // flat bill flow nor the older vendor.html build ever did, so this is a no-op for them.
  if (body.Vendor_Invoice_Date) { try { await ensureColumns(env, 'Vendor_Bills', ['Vendor_Invoice_Date']); } catch (e) {} }
  // B-227 Phase 1/2: Payment_Method (reimburse_via_labor_bill default / separate_vendor_billpay /
  // credit_card_no_bill) — same lazy-ensureColumns pattern, only touches the sheet when a caller
  // actually sends one (the vendor portal doesn't send this field, so it stays untouched there).
  if (body.Payment_Method) { try { await ensureColumns(env, 'Vendor_Bills', ['Payment_Method']); } catch (e) {} }
  // Same pattern for the vendor's own invoice FILE (the actual document/photo, not just the
  // number) — B-fix Aug 17: vendors had no way to attach their invoice, only receipts had an
  // upload control. Drive_File_ID kept alongside the URL so the Hub can open it directly.
  if (body.Invoice_File_URL) { try { await ensureColumns(env, 'Vendor_Bills', ['Invoice_File_URL', 'Invoice_File_ID']); } catch (e) {} }
  // Invoice_Description — the customer-facing text (separate from Notes, which stays
  // private). Used directly on flat/no-time-entry bills, and as the lead-in when time
  // entries with their own Invoice_Description are also linked to this bill (buildInvoiceLines).
  if (body.Invoice_Description) { try { await ensureColumns(env, 'Vendor_Bills', ['Invoice_Description']); } catch (e) {} }

  // B-20260916-1930-k7: real time-of-day, for the vendor confirmation email + a genuine audit
  // trail — Created_Date is date-only (matches this tab's existing business-date convention),
  // Submitted_At captures the actual moment regardless of what the caller sends.
  if (!body.Submitted_At) body.Submitted_At = new Date().toISOString();
  try { await ensureColumns(env, 'Vendor_Bills', ['Submitted_At']); } catch (e) {}

  // Hours logged on the job can BE the bill — that is the whole point when Brett is the
  // vendor. The ids ride in on the body but are not a Vendor_Bills column, so they come
  // out before the row is written and get stamped onto the time rows afterwards instead.
  const timeIds = parseIdList(body.time_entry_ids);
  delete body.time_entry_ids;

  const res = await addRow(env, 'Vendor_Bills', body);
  if (timeIds.length) {
    // Link AFTER the bill exists. If this half fails the bill is still right — the hours
    // simply stay available, which is recoverable. The reverse (hours marked spent against
    // a bill that was never created) is not.
    try {
      const created = await res.clone().json();
      if (created && created.id) await linkTimeEntriesToBill(env, timeIds, String(created.id), body.WO_ID || body.wo_id);
    } catch (e) { /* the bill is saved; the link is not worth losing it over */ }
  }
  // Automation: entering a bill moves the WO to Complete (if still pre-complete).
  try {
    const woKey = body.WO_ID || body.wo_id;
    if (woKey) {
      const wos = await fetchTab(env, 'Work_Orders');
      const wo = findWO(wos, woKey);
      const preComplete = WOStatus.sets.FIELD_OPEN;
      if (wo && preComplete.includes(wo.Status)) {
        await updateWOFields(env, woKey, { Status: 'Complete', Completed_Date: wo.Completed_Date || new Date().toISOString().split('T')[0] });
      }
    }
  } catch(e) { /* non-fatal: bill is still saved */ }
  // B-20260916-1930-k7: vendor invoice confirmation email — best-effort, soft-launched via
  // Config.VENDOR_INVOICE_EMAIL_TEST_VENDOR_IDS. Never blocks or slows the bill itself.
  try { await autoMatchVendorToQbo(env, body.Vendor_ID || body.vendor_id, '/vendor-bill/add'); } catch (e) { /* never blocks the bill */ }
  try { await sendVendorInvoiceConfirmationEmail(env, body); } catch (e) { /* non-fatal: bill is still saved */ }
  return res;
}

// POST /vendor-bill/add-standalone { vendor_id, property_id, bill_to:'owner'|'ridgeco',
//   line_items:[{description,amount,pay:'reimburse'|'account',url}], notes?, invoice_description? }
// Vendor Standalone Billing (Sep 24 2026 build brief §3c) — lets a vendor with
// Vendors.Can_Bill_No_WO='TRUE' submit a bill with NO Work_Orders row at all (Sierra Taylor's
// tenant-treats/small-extras case). Writes a Vendor_Bills row with WO_ID left BLANK — already
// tolerated everywhere downstream (addVendorBill's WO-auto-complete step is a no-op on a blank
// WO_ID; addReceipt has supported a bare property_id with no wo_id since the one-tap-expense
// build) — plus three new columns (Property_ID, Bill_To, Standalone) that qbSendInvoice's new
// standalone branch (qbSendStandaloneInvoice) and Review Bills' renderIRCard use to resolve
// Owner/QuickBooks straight from Property_ID, the same shape scopeSigResolveParties() already
// uses for signed Scope Proposals. Every other field (Bill_Type/Hours/Truck_Stock/Receipts_JSON/
// Receipts_Total/Receipts_Reimburse_Total/Total) matches the existing hourly/flat bill shape
// EXACTLY, on purpose — Review Bills' irCalc()/renderIRCard money math and the QuickBooks send
// path never need to know a bill is standalone; only the owner-resolution step does.
async function addVendorBillStandalone(env, body) {
  const vendorId = String(body.vendor_id || '').trim();
  const propertyId = String(body.property_id || '').trim();
  const billTo = String(body.bill_to || '').trim().toLowerCase();
  const items = Array.isArray(body.line_items) ? body.line_items : [];
  if (!vendorId) return json({ error: 'vendor_id required' }, 400);
  if (!propertyId) return json({ error: 'property_id required' }, 400);
  if (!['owner', 'ridgeco'].includes(billTo)) return json({ error: "bill_to must be 'owner' or 'ridgeco'" }, 400);
  const validItems = items.filter(it => it && (+it.amount || 0) > 0);
  if (!validItems.length) return json({ error: 'At least one line item with an amount is required' }, 400);

  const [vendors, properties] = await fetchTabs(env, ['Vendors', 'Properties']);
  const vendor = vendors.find(v => String(v.ID) === vendorId);
  if (!vendor) return json({ error: 'Vendor not found' }, 404);
  // Never trust the client — re-check the permission and the property allow-list server-side,
  // same principle as the Sep 16 2026 tenant-submission hardening.
  if (String(vendor.Can_Bill_No_WO || '').toUpperCase() !== 'TRUE') {
    return json({ error: 'This vendor is not enabled for standalone billing' }, 403);
  }
  const prop = properties.find(p => String(p.ID) === propertyId);
  if (!prop) return json({ error: 'Property not found' }, 404);
  if (!vendorHasBillingPropertyAccess(vendor, propertyId)) {
    return json({ error: 'You do not have billing access to this property yet. Use "Request access to another property" first.' }, 403);
  }

  const receipts = validItems.map(it => ({
    amount: +(+it.amount || 0).toFixed(2),
    desc: String(it.description || it.desc || '').trim(),
    url: String(it.url || '').trim(),
    pay: it.pay === 'account' ? 'account' : 'reimburse',
  }));
  const totals = computeStandaloneBillTotals(receipts);
  if (totals.receipts_total <= 0) return json({ error: 'Total must be greater than $0' }, 400);

  await ensureColumns(env, 'Vendor_Bills', ['Property_ID', 'Bill_To', 'Standalone']);

  // Same duplicate-guard shape addVendorBill already uses (vendor+property+total+day), scoped
  // to Standalone rows only so it never collides with an ordinary WO-anchored bill.
  const dupe = await findRecentDuplicate(env, 'Vendor_Bills', {
    Vendor_ID: vendorId, Property_ID: propertyId, Total: totals.total.toFixed(2), Standalone: 'TRUE',
  }, 86400);
  if (dupe) return json({ success: true, duplicate: true, id: String(dupe.ID || '') });

  const vendorName = vendor.Company || vendor.Name || [vendor.First_Name, vendor.Last_Name].filter(Boolean).join(' ') || ('Vendor ' + vendorId);
  const now = new Date();
  const res = await addRow(env, 'Vendor_Bills', {
    WO_ID: '', Vendor_ID: vendorId, Vendor_Name: vendorName,
    Bill_Type: 'flat', Hours: '0', Rate: '0', Labor_Total: '0', Flat_Rate: '0',
    Truck_Stock: '0', Truck_Desc: '',
    Receipts_JSON: JSON.stringify(receipts),
    Receipts_Total: totals.receipts_total.toFixed(2),
    Receipts_Reimburse_Total: totals.receipts_reimburse_total.toFixed(2),
    Total: totals.total.toFixed(2),
    Notes: String(body.notes || ''),
    Invoice_Description: String(body.invoice_description || '').trim() || (vendorName + ' — standalone bill'),
    Property_ID: propertyId, Bill_To: billTo, Standalone: 'TRUE',
    Status: 'submitted', Submitted_At: now.toISOString(), Created_Date: now.toISOString().split('T')[0],
  });
  return res;
}

// POST /vendor/request-property-access { vendor_id, property_id, note? }
// Vendor Standalone Billing (§3b/§3d) — a vendor whose Billing_Property_Access allow-list
// doesn't yet cover a property they need to bill against can ask for it here instead of being
// stuck. Writes a Vendor_Access_Requests row (Brett approves/denies from Dev Log or the
// Dashboard badge — see vendorAccessRequestApprove) and fires the same admin-alert SMS every
// other "Brett, look at this" flow in this file uses (config.admin_phone + sendSMS).
async function vendorRequestPropertyAccess(env, body) {
  const vendorId = String(body.vendor_id || '').trim();
  const propertyId = String(body.property_id || '').trim();
  if (!vendorId) return json({ error: 'vendor_id required' }, 400);
  if (!propertyId) return json({ error: 'property_id required' }, 400);

  const [vendors, properties] = await fetchTabs(env, ['Vendors', 'Properties']);
  const vendor = vendors.find(v => String(v.ID) === vendorId);
  if (!vendor) return json({ error: 'Vendor not found' }, 404);
  const prop = properties.find(p => String(p.ID) === propertyId);
  if (!prop) return json({ error: 'Property not found' }, 404);

  await ensureColumns(env, 'Vendor_Access_Requests', [
    'ID', 'Vendor_ID', 'Vendor_Name', 'Requested_Property_ID', 'Note', 'Status',
    'Created_Date', 'Decided_Date', 'Active',
  ]);
  const vendorName = vendor.Company || vendor.Name || [vendor.First_Name, vendor.Last_Name].filter(Boolean).join(' ') || ('Vendor ' + vendorId);
  const res = await addRow(env, 'Vendor_Access_Requests', {
    Vendor_ID: vendorId, Vendor_Name: vendorName, Requested_Property_ID: propertyId,
    Note: String(body.note || ''), Status: 'pending', Created_Date: new Date().toISOString(),
  });
  try {
    const config = await getConfig(env);
    if (config.admin_phone) {
      await sendSMS(env, config.admin_phone,
        `🔑 ${vendorName} requested billing access to ${prop.Address || ('property ' + propertyId)}. Review in Hub → Dev Log → Vendor Access Requests.`);
    }
  } catch (e) { /* non-fatal — the request row is already saved */ }
  return res;
}

// GET /vendor-access-requests?status=pending  (or &count_only=1 for the dashboard/nav badges)
// Vendor Standalone Billing (§3d) — one query backs BOTH the Dev Log section and the
// Dashboard pending-count tile, deliberately, so the two badges can never drift apart.
async function listVendorAccessRequests(env, url) {
  const status = (url.searchParams.get('status') || '').trim().toLowerCase();
  const countOnly = url.searchParams.get('count_only') === '1';
  let rows = [];
  try { rows = await fetchTab(env, 'Vendor_Access_Requests'); } catch (e) { rows = []; }
  let results = rows.filter(r => r.Active !== 'FALSE');
  if (status) results = results.filter(r => String(r.Status || 'pending').toLowerCase() === status);
  if (countOnly) return json({ count: results.length });
  return json(results);
}

// POST /vendor-access-requests/approve { id, scope:'once'|'ongoing', decision:'approve'|'deny' }
// Vendor Standalone Billing (§3d). 'once' resolves the pending item without touching the
// vendor's standing Billing_Property_Access list; 'ongoing' also appends the requested
// property to it, so future bills against it clear the server-side allow-list check without
// another request. A deny just closes the row out — no Vendors write at all.
async function vendorAccessRequestApprove(env, body) {
  const id = String(body.id || '').trim();
  const decision = String(body.decision || '').trim().toLowerCase();
  const scope = String(body.scope || 'once').trim().toLowerCase();
  if (!id) return json({ error: 'id required' }, 400);
  if (!['approve', 'deny'].includes(decision)) return json({ error: "decision must be 'approve' or 'deny'" }, 400);

  const rows = await fetchTab(env, 'Vendor_Access_Requests');
  const reqRow = rows.find(r => String(r.ID) === id);
  if (!reqRow) return json({ error: 'Request not found' }, 404);

  const today = new Date().toISOString();
  if (decision === 'deny') {
    await updateRow(env, 'Vendor_Access_Requests', id, { Status: 'denied', Decided_Date: today });
    return json({ success: true, id, status: 'denied' });
  }

  const newStatus = scope === 'ongoing' ? 'approved_ongoing' : 'approved_once';
  await updateRow(env, 'Vendor_Access_Requests', id, { Status: newStatus, Decided_Date: today });

  if (scope === 'ongoing' && reqRow.Vendor_ID && reqRow.Requested_Property_ID) {
    try {
      const vendors = await fetchTab(env, 'Vendors');
      const vendor = vendors.find(v => String(v.ID) === String(reqRow.Vendor_ID));
      if (vendor) {
        const list = String(vendor.Billing_Property_Access || '').split(',').map(s => s.trim()).filter(Boolean);
        if (!list.includes(String(reqRow.Requested_Property_ID))) {
          list.push(String(reqRow.Requested_Property_ID));
          await ensureColumns(env, 'Vendors', ['Billing_Property_Access']);
          await updateRow(env, 'Vendors', reqRow.Vendor_ID, { Billing_Property_Access: list.join(',') });
        }
      }
    } catch (e) { /* the request itself is already resolved; the vendor list append is best-effort */ }
  }
  return json({ success: true, id, status: newStatus });
}

// POST /vendor-bill/edit-receipts { bill_id, receipts:[{amount,desc,pay,url}], edited_by? }
// Sep 23 2026, Brett's ask: a vendor's mistaken/duplicate receipt entry on a submitted bill
// (e.g. a blank-description receipt whose amount just re-states her own flat-rate/labor
// invoice) was inflating the customer-facing pass-through price, and the only existing fix
// was Void — which throws away the whole bill (labor, invoice file, notes) to drop one bad
// line. This replaces the bill's ENTIRE Receipts_JSON with the corrected array the caller
// sends (edit an amount/desc/pay-mode, delete a line, or add a missed one — all the same
// "send the corrected list back" shape) and recomputes every field that is derived from it,
// the same way doActualBillSubmit() in vendor.html originally computed them:
//   Receipts_Total            = sum of every receipt's amount (both pay modes)
//   Receipts_Reimburse_Total  = sum of receipts NOT marked 'account' (what's owed to the vendor)
//   Total                     = laborOrFlat + Truck_Stock + Receipts_Reimburse_Total
// Editable at ANY pre-QB stage — submitted OR already reviewed/markup-priced — per Brett's
// explicit answer (Sep 23 2026 session). The one hard stop is a bill that's actually been
// sent to QuickBooks: Invoice_Review is what /qb/send-invoice acts on and stamps QB_Invoice_ID
// onto, so a live Invoice_Review row carrying one means real QB records already exist off the
// old numbers — same convention the same-day Receipt Reconciler reassign/mark-refund build
// (FL rule, PR #44) already uses ("hasn't been emailed to QuickBooks yet"). Once sent, this
// refuses and points at QuickBooks directly, same as that build.
// If the bill was already reviewed (Status:'reviewed', a markup/Customer_Total was already
// computed and frozen onto Vendor_Bills + a live Invoice_Review row) but NOT yet sent to QB,
// editing receipts here invalidates that frozen pricing — so this resets Status back to
// 'submitted' and deactivates the stale Invoice_Review row, forcing a fresh Review Bills pass
// (with the corrected numbers) before it can go to QB. Never silently leaves a stale approved
// price sitting on a bill whose underlying cost just changed.
async function editVendorBillReceipts(env, body) {
  const billId = String((body && body.bill_id) || '').trim();
  if (!billId) return json({ error: 'bill_id required' }, 400);
  if (!Array.isArray(body.receipts)) return json({ error: 'receipts must be an array' }, 400);

  const bills = await fetchTab(env, 'Vendor_Bills');
  const bill = bills.find(b => String(b.ID) === billId);
  if (!bill) return json({ error: `No vendor bill ${billId}` }, 404);
  if (bill.Active === 'FALSE') return json({ error: `Bill ${billId} is voided — nothing to edit. Submit a new bill instead.` }, 409);

  // Hard stop: already sent to QuickBooks. Same check moveVendorBillToNewWO/vendorBillReassignLock
  // use — a live Invoice_Review row for this bill carrying a QB_Invoice_ID.
  let invoiceReviewRows = [];
  try { invoiceReviewRows = await fetchTab(env, 'Invoice_Review'); } catch (e) { invoiceReviewRows = []; }
  const liveIR = invoiceReviewRows.find(ir => ir.Active !== 'FALSE' && String(ir.Bill_ID) === billId);
  if (liveIR && String(liveIR.QB_Invoice_ID || '').trim()) {
    return json({ error: `Already sent to QuickBooks (invoice ${liveIR.QB_Invoice_ID}) — fix this in QuickBooks directly, or void this bill and have the vendor resubmit.` }, 409);
  }

  // Sanitize the incoming receipt list — same shape doActualBillSubmit() builds client-side.
  const receipts = body.receipts.map(r => ({
    amount: Math.round((parseFloat(r && r.amount) || 0) * 100) / 100,
    desc: String((r && r.desc) || '').trim(),
    pay: (r && r.pay === 'account') ? 'account' : 'reimburse',
    url: String((r && r.url) || ''),
  })).filter(r => r.amount > 0 || r.desc);

  const receiptsTotal = receipts.reduce((s, r) => s + r.amount, 0);
  const receiptsReimburse = receipts.reduce((s, r) => s + (r.pay === 'account' ? 0 : r.amount), 0);
  const laborOrFlat = bill.Bill_Type === 'flat' ? (parseFloat(bill.Flat_Rate) || 0) : (parseFloat(bill.Labor_Total) || 0);
  const truckStock = parseFloat(bill.Truck_Stock) || 0;
  const newTotal = laborOrFlat + truckStock + receiptsReimburse;
  const oldTotal = parseFloat(bill.Total) || 0;

  try { await ensureColumns(env, 'Vendor_Bills', ['Receipts_Reimburse_Total']); } catch (e) {}

  const fields = {
    Receipts_JSON: JSON.stringify(receipts),
    Receipts_Total: receiptsTotal.toFixed(2),
    Receipts_Reimburse_Total: receiptsReimburse.toFixed(2),
    Total: newTotal.toFixed(2),
  };

  let resetToSubmitted = false;
  if (bill.Status === 'reviewed') {
    fields.Status = 'submitted';
    resetToSubmitted = true;
    if (liveIR) {
      try { await updateRow(env, 'Invoice_Review', liveIR.ID, { Active: 'FALSE' }); } catch (e) { /* non-fatal — the stale row is now orphaned but harmless; Review Bills re-derives from Vendor_Bills */ }
    }
  }

  await updateRow(env, 'Vendor_Bills', billId, fields);

  try {
    await logWOAudit(env, bill.WO_ID || '', body.edited_by || 'Brett', 'admin', 'Vendor_Bill_Receipts',
      `$${oldTotal.toFixed(2)} (${(JSON.parse(bill.Receipts_JSON || '[]') || []).length} receipt line(s))`,
      `$${newTotal.toFixed(2)} (${receipts.length} receipt line(s))`,
      resetToSubmitted ? 'Receipts edited on bill ' + billId + ' — reset to submitted, needs re-review before QuickBooks.' : 'Receipts edited on bill ' + billId + '.');
  } catch (e) { /* audit is best-effort — the fix itself already landed */ }

  return json({
    success: true, bill_id: billId, total: newTotal.toFixed(2),
    receipts_total: receiptsTotal.toFixed(2), receipts_reimburse_total: receiptsReimburse.toFixed(2),
    reset_to_submitted: resetToSubmitted,
  });
}

async function listVendorBills(env, url) {
  const woId = url.searchParams.get('wo_id') || '', vendorId = url.searchParams.get('vendor_id') || '', statusFilter = url.searchParams.get('status') || '';
  try {
    const bills = await fetchTab(env, 'Vendor_Bills', { stale: !!vendorId });
    let results = bills.filter(b => b.Active !== 'FALSE');
    if (statusFilter && !woId) {
      // Admin view: Invoice Review screen — return all bills matching this status.
      // Oct 14 2026: this branch used to ignore vendor_id, so a vendor session calling
      // /vendor-bills?status=submitted got EVERY vendor's bills. A vendor session now always carries
      // its own vendor_id here (forced by the router), so the filter applies; admin calls send none.
      const byStatus = results.filter(b => (b.Status || '').toLowerCase() === statusFilter.toLowerCase());
      return json(vendorId ? byStatus.filter(b => b.Vendor_ID === vendorId) : byStatus);
    }
    if (woId)     results = results.filter(b => b.WO_ID     === woId);
    if (vendorId) results = results.filter(b => b.Vendor_ID === vendorId);
    return json(results);
  } catch(e) { return json([]); }
}

// GET /vendor-bills/truck-stock — Brett, Sep 2026: "I need to be able to review all truck
// material entries on the receipts page AND the vendor bills page." Truck stock lives as a
// single Truck_Stock/Truck_Desc pair directly on each Vendor_Bills row (a vendor's own
// inventory, always owed back to them — never a Ridge Co card purchase), not as its own list —
// this pulls every bill (any status, not just pending review) that has one, with WO/property/
// vendor context resolved, so both pages can render one simple table from a single call.
async function vendorBillsTruckStock(env) {
  try {
    const [bills, wos, vendors, properties] = await fetchTabs(env, ['Vendor_Bills', 'Work_Orders', 'Vendors', 'Properties']);
    const rows = bills.filter(b => b.Active !== 'FALSE' && Number(b.Truck_Stock) > 0).map(b => {
      const wo = wos.find(w => String(w.ID) === String(b.WO_ID)) || {};
      const vendor = vendors.find(v => String(v.ID) === String(b.Vendor_ID)) || {};
      const prop = wo.Property_ID ? properties.find(p => String(p.ID) === String(wo.Property_ID)) : null;
      return {
        bill_id: b.ID, wo_id: b.WO_ID || '', vendor_name: b.Vendor_Name || vendor.Name || '',
        truck_stock: Number(b.Truck_Stock) || 0, truck_desc: b.Truck_Desc || '',
        status: b.Status || '', created_date: (b.Created_Date || '').split('T')[0],
        property_address: prop ? (prop.Address || '') : (wo.Property_Address || ''),
      };
    }).sort((a, b) => (b.created_date || '').localeCompare(a.created_date || ''));
    const total = rows.reduce((s, r) => s + r.truck_stock, 0);
    return json({ ok: true, count: rows.length, total: +total.toFixed(2), rows });
  } catch (e) { return json({ ok: false, error: String(e && e.message || e), rows: [] }); }
}

// POST /vendor-bill/move-to-new-wo { bill_id, cutoff_date?, reason?, moved_by?, apply? }
// Splits a bill — and a date-filtered slice of its work order's photos — off onto a
// BRAND-NEW work order. Built for the recurring case where a vendor revisits a property
// he's already done a (billed, closed-out) job at, and the new bill lands on that same old
// WO instead of getting its own: the old WO's history gets contaminated with an unrelated
// bill, and there's no clean per-visit record. This creates a fresh WO instead of trying to
// untangle the old one.
//
// Preview-first, same shape as adminMergeOwner/adminMergeProperty: apply:false (default)
// reports exactly what WOULD move without writing anything; apply:true actually creates the
// WO and moves the rows. Everything on the old WO dated BEFORE the cutoff — its own bill
// history, notes, earlier photos — is untouched; only the bill and the on/after-cutoff
// photos move.
async function moveVendorBillToNewWO(env, body) {
  const billId = String(body.bill_id || '').trim();
  if (!billId) return json({ error: 'bill_id required' }, 400);
  const apply = body.apply === true || String(body.apply).toUpperCase() === 'TRUE';
  const movedBy = body.moved_by || 'Brett';
  const reason = body.reason || '';

  const bills = await fetchTab(env, 'Vendor_Bills');
  const bill = bills.find(b => String(b.ID) === billId);
  if (!bill) return json({ error: `No vendor bill ${billId}` }, 404);
  if (bill.Active === 'FALSE') return json({ error: `Bill ${billId} is inactive/voided — nothing to move.` }, 409);

  const oldWoId = bill.WO_ID;
  if (!oldWoId) return json({ error: `Bill ${billId} has no WO_ID to split from.` }, 400);

  const workorders = await fetchTab(env, 'Work_Orders');
  const oldWo = findWO(workorders, oldWoId);
  if (!oldWo) return json({ error: `Old work order ${oldWoId} not found.` }, 404);

  // Default cutoff = the bill's own submitted date — the day the vendor actually did this
  // job, which is exactly the day whose photos this bill is paying for.
  const cutoff = String(body.cutoff_date || bill.Created_Date || '').slice(0, 10);
  if (!cutoff) return json({ error: 'No cutoff_date given and the bill has no Created_Date to default to.' }, 400);

  // Attachments only carry a WO_ID, not a bill_id — there is no per-bill link in the
  // schema. On a WO with only one active bill (the normal case) a date cutoff is a safe
  // proxy for "this visit's photos." But if the OLD WO carries another still-open bill
  // (a second vendor, or a second unreviewed bill from this same vendor), a date-based
  // cutoff can't tell that bill's photos apart from this one's — moving by date alone
  // risks sweeping evidence for a job that isn't the one being split off. Surface it
  // rather than silently grabbing it; ridgeco-validate flagged this as the real gap.
  const otherActiveBills = bills.filter(b => b.WO_ID === oldWoId && b.Active !== 'FALSE' && String(b.ID) !== billId);

  const attachments = await fetchTab(env, 'Attachments');
  const woAttachments = attachments.filter(a => a.WO_ID === oldWoId && a.Active !== 'FALSE');
  const moving = woAttachments.filter(a => String(a.Created_Date || '').slice(0, 10) >= cutoff);
  const staying = woAttachments.filter(a => String(a.Created_Date || '').slice(0, 10) < cutoff);

  const preview = {
    success: true, applied: false,
    old_wo: { id: oldWoId, property_id: oldWo.Property_ID, trade: oldWo.Trade, status: oldWo.Status, description: oldWo.Description },
    bill: { id: billId, vendor_id: bill.Vendor_ID, vendor_name: bill.Vendor_Name, total: bill.Total, created_date: bill.Created_Date },
    cutoff_date: cutoff,
    attachments_to_move: moving.map(a => ({ id: a.ID, file_name: a.File_Name, file_type: a.File_Type, created_date: a.Created_Date })),
    attachments_staying: staying.map(a => ({ id: a.ID, file_name: a.File_Name, file_type: a.File_Type, created_date: a.Created_Date })),
    new_wo_preview: { property_id: oldWo.Property_ID, unit_id: oldWo.Unit_ID, tenant_id: oldWo.Tenant_ID, trade: oldWo.Trade, type: oldWo.Type, vendor_id: oldWo.Vendor_ID },
    // Non-empty means: pause and look before applying. The old WO has other money still
    // open on it, and a date cutoff can't distinguish whose photos are whose.
    other_active_bills: otherActiveBills.map(b => ({ id: b.ID, vendor_name: b.Vendor_Name, total: b.Total, status: b.Status })),
  };
  if (!apply) return json(preview);

  // ── APPLY ────────────────────────────────────────────────────
  // 1. Create the new WO — reuse createWorkOrder rather than re-deriving its ID-numbering
  //    and auto-tenant-linking logic. Description is deliberately left blank (Brett's call —
  //    a revisit gets its own fresh notes, not the old job's carried over).
  const createRes = await createWorkOrder(env, {
    property_id: oldWo.Property_ID, unit_id: oldWo.Unit_ID, tenant_id: oldWo.Tenant_ID,
    type: oldWo.Type || 'manual', trade: oldWo.Trade || '', description: '',
    priority: oldWo.Priority || 'normal', room: oldWo.Room || '',
    created_by: movedBy, notes: reason ? `Split from ${oldWoId}: ${reason}` : `Split from ${oldWoId}`,
  });
  const created = await createRes.clone().json();
  if (!created || !created.id) return json({ error: 'Failed to create the new work order', detail: created }, 500);
  const newWoId = created.id;

  // 2+3. Set the vendor/status on the new WO and move the bill onto it. These two are the
  // core of the split — a new WO with no vendor/bill on it is useless — so they're wrapped
  // together: if either throws, the new WO already exists (step 1 committed) but is
  // incomplete, and the caller needs to know that WO's id rather than getting a bare 500
  // and no way to find it. This never auto-retries (a retry after a partial failure would
  // create a SECOND stray WO, not resume this one) — it hands the id back for a human to
  // check the sheet and finish or clean up by hand.
  try {
    // The vendor already did this job — set them + Complete directly rather than going
    // through assignVendor (which SMS's the vendor to accept a dispatch). Mirrors exactly
    // what addVendorBill already does automatically for any WO a bill lands on.
    await updateWOFields(env, newWoId, {
      Vendor_ID: oldWo.Vendor_ID || '', Status: 'Complete',
      Completed_Date: new Date().toISOString().split('T')[0],
    });
    await updateRow(env, 'Vendor_Bills', billId, { WO_ID: newWoId });
  } catch (e) {
    return json({
      success: false, applied: true, partial: true, new_wo_id: newWoId, bill_id: billId,
      error: `Work order ${newWoId} was created, but moving the vendor/status/bill onto it failed (${e.message || e}). ` +
        `The bill is still on ${oldWoId}. Check ${newWoId} in the Hub before retrying — retrying this action now creates ANOTHER new WO, it does not resume this one.`,
    }, 500);
  }

  // 4. Move only the photos at/after the cutoff. Anything older stays on the old WO — it's
  //    that job's own history, not this visit's. Best-effort per row: the bill has already
  //    moved successfully by this point, so one photo failing to move is reported, not
  //    treated as fatal to the whole action.
  const movedAttachmentIds = [];
  for (const a of moving) {
    try { await updateRow(env, 'Attachments', a.ID, { WO_ID: newWoId }); movedAttachmentIds.push(a.ID); }
    catch (e) { /* best-effort — report what didn't move below rather than losing the whole apply over one row */ }
  }
  const failedAttachmentIds = moving.map(a => a.ID).filter(id => !movedAttachmentIds.includes(id));

  // 5. Audit trail on BOTH work orders — this is the whole reason a bill and its photos
  //    disappeared from the old WO and a new one appeared with no dispatch/assign step
  //    behind it.
  await logWOAuditMany(env, [
    { woId: oldWoId, changedBy: movedBy, changedByRole: 'admin', field: 'Bill_Moved_Out', oldValue: billId, newValue: newWoId,
      notes: `Bill ${billId} ($${bill.Total || '0'}) + ${movedAttachmentIds.length} photo(s) moved to new WO ${newWoId}.${reason ? ' Reason: ' + reason : ''}` },
    { woId: newWoId, changedBy: movedBy, changedByRole: 'admin', field: 'Split_From', oldValue: '', newValue: oldWoId,
      notes: `Created by splitting bill ${billId} + ${movedAttachmentIds.length} photo(s) off ${oldWoId}.${reason ? ' Reason: ' + reason : ''}` },
  ]);

  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'bill_split', Skill_Or_Endpoint: '/vendor-bill/move-to-new-wo', Success: 'TRUE', Notes: `old_wo=${oldWoId} new_wo=${newWoId} bill=${billId} attachments=${movedAttachmentIds.length}` }); } catch (_) {}

  return json({
    success: true, applied: true,
    new_wo_id: newWoId, old_wo_id: oldWoId, bill_id: billId,
    attachments_moved: movedAttachmentIds.length,
    attachments_failed: failedAttachmentIds,
    attachments_left_on_old_wo: staying.length,
  });
}

// POST /invoice-review/unapprove { id }
// Approving a bill locks the price in, and there was no way back — a second approve just
// handed back the existing row, so a bill approved at $185 stayed $185 no matter what
// happened to the number afterwards. Withdrawing puts the bill back in Review Bills to be
// priced again.
//
// Only ever before it reaches QuickBooks. Once an invoice or bill exists there, the Hub
// row is the record of what was actually sent, and quietly retiring it would leave the two
// systems disagreeing with nothing to reconcile against.
// POST /vendor-bill/set-pending-info { id, pending_info: true/false, note?, set_by? }
// CAP-036 #14 (Sep 24 2026, Brett): the "Invoiced — Pending Info" sub-status — a vendor has
// invoiced a job and it's complete, but Brett needs something more (photos, receipts, a better
// description) before he can pay it, and there was no way to flag that. Deliberately modeled as
// a FLAG layered on top of the existing Status enum, not a new Status value: Vendor_Bills.Status
// only ever means 'submitted' or 'reviewed' (see addVendorBill / approveInvoiceReview /
// unapproveInvoiceReview) — a bill can be either AND ALSO flagged Pending_Info at the same time,
// exactly as Brett described it. Setting the flag requires a note (what's missing); clearing it
// does not. This function only ever sets/clears the flag — see qbSendInvoice for the actual
// soft-block-with-override at the money-movement point, renderIRCard (index.html Review Bills)
// and loadVendorBillSummary (vendor.html) for where it surfaces.
async function setVendorBillPendingInfo(env, body) {
  const id = String(body.id || '').trim();
  if (!id) return json({ error: 'id required' }, 400);
  const pending = body.pending_info === true || String(body.pending_info).toUpperCase() === 'TRUE';
  const note = String(body.note || '').trim();
  if (pending && !note) return json({ error: 'A note is required when flagging Pending Info — say what\'s missing (photos, receipts, description, etc.).' }, 400);

  try {
    await ensureColumns(env, 'Vendor_Bills', ['Pending_Info', 'Pending_Info_Note', 'Pending_Info_Set_By', 'Pending_Info_Set_Date']);
  } catch (e) { return json({ error: 'Could not prepare Vendor_Bills columns: ' + String(e && e.message || e) }, 500); }

  const bills = await fetchTab(env, 'Vendor_Bills');
  const bill = bills.find(b => String(b.ID) === id);
  if (!bill) return json({ error: `No vendor bill ${id}` }, 404);

  const wasPending = String(bill.Pending_Info || '').toUpperCase() === 'TRUE';
  const fields = {
    Pending_Info: pending ? 'TRUE' : 'FALSE',
    Pending_Info_Note: pending ? note : '',
    Pending_Info_Set_By: pending ? (body.set_by || 'Brett') : '',
    Pending_Info_Set_Date: pending ? new Date().toISOString() : '',
  };
  await updateRow(env, 'Vendor_Bills', id, fields);
  try {
    await logWOAudit(env, bill.WO_ID || '', body.set_by || 'Brett', 'admin', 'Vendor_Bill_Pending_Info',
      wasPending ? ('Pending Info: ' + (bill.Pending_Info_Note || '')) : 'not flagged',
      pending ? ('Pending Info: ' + note) : 'cleared',
      pending ? ('Flagged bill ' + id + ' pending info: ' + note) : ('Cleared pending-info flag on bill ' + id + '.'));
  } catch (e) { /* audit is best-effort — the flag itself already landed */ }
  return json({ success: true, id, pending_info: pending, note: pending ? note : '' });
}

async function unapproveInvoiceReview(env, body) {
  const id = String(body.id || '').trim();
  if (!id) return json({ error: 'id required' }, 400);

  const irs = await fetchTab(env, 'Invoice_Review');
  const ir = irs.find(r => String(r.ID) === id);
  if (!ir) return json({ error: `No approval row ${id}` }, 404);
  if (ir.Active === 'FALSE') return json({ success: true, already_withdrawn: true });

  const sentInv  = (ir.QB_Invoice_ID || '').trim();
  const sentBill = (ir.QB_Bill_ID || '').trim();
  if (sentInv || sentBill) {
    return json({
      error: `This one is already in QuickBooks (${sentInv ? 'invoice ' + sentInv : ''}${sentInv && sentBill ? ', ' : ''}${sentBill ? 'bill ' + sentBill : ''}). Withdrawing the approval here would leave the Hub and QuickBooks disagreeing. Void or edit it in QuickBooks instead.`,
      qb_invoice_id: sentInv, qb_bill_id: sentBill,
    }, 409);
  }

  await updateRow(env, 'Invoice_Review', id, {
    Active: 'FALSE',
    QB_Invoice_Status: 'withdrawn',
  });

  // Put the bill back where it came from, or it won't reappear in Review Bills to be
  // priced again — which would leave the job stuck with no way to invoice it.
  let billRestored = false;
  if (ir.Bill_ID) {
    try {
      const res = await updateRow(env, 'Vendor_Bills', ir.Bill_ID, { Status: 'submitted' });
      const parsed = await res.clone().json();
      billRestored = !!(parsed && parsed.success);
    } catch (e) { billRestored = false; }
  }

  return json({
    success: true, id, wo_id: ir.WO_ID || '', bill_id: ir.Bill_ID || '',
    customer_total: ir.Customer_Total || '',
    bill_restored: billRestored,
    warning: billRestored ? '' : 'The approval is withdrawn, but the vendor bill could not be set back to submitted — it may not reappear in Review Bills. Check the Vendor_Bills row.',
  });
}

// POST /qb/undo-send { id, reason? }
// The other half of the fix started by /invoice-review/unapprove: that endpoint refuses the
// moment QB_Invoice_ID or QB_Bill_ID is set (on purpose — pulling the Hub row back without
// touching QuickBooks would leave the two systems disagreeing about a real invoice/bill that
// still exists there), and its error message has always just said "void it in QuickBooks
// directly." This endpoint IS that direct route, from the Hub: it actually voids the
// QuickBooks Invoice and/or Bill first (reusing qbDeleteInvoiceSafe/qbDeleteBillSafe, which
// already refuse — safely, writing nothing — if either transaction has a payment applied),
// and only once QuickBooks is clean does it do exactly what /invoice-review/unapprove does:
// flip the Invoice_Review row inactive and put the Vendor_Bills row back to 'submitted' so it
// reappears in Review Bills to be fixed (receipts re-attached, priced again, etc.) and resent.
//
// Real case this closes (Brett, Sep 28 2026): a bill sent to QuickBooks before the
// receipt-upload-during-billing bug was fixed, so the QB invoice/bill exist at the right
// total but with no receipt image attached (qbAttachReceipts silently skips any
// Receipts_JSON entry with no .url — there was never a URL to attach). There was no way
// back short of fixing it by hand in QuickBooks.
//
// Both sides are checked SAFE before either is deleted — never delete one half and then
// discover the other can't be undone, which would leave QuickBooks and the Hub each missing
// half of a real transaction.
async function qbUndoSend(env, body) {
  try {
    const id = String(body.id || '').trim();
    const billIdParam = String(body.bill_id || '').trim();
    if (!id && !billIdParam) return json({ error: 'id or bill_id required' }, 400);

    const irRows = await fetchTab(env, 'Invoice_Review');
    const ir = id
      ? irRows.find(r => String(r.ID) === id)
      : irRows.find(r => r.Active !== 'FALSE' && String(r.Bill_ID) === billIdParam);
    if (!ir) return json({ error: `No Invoice_Review row found${id ? ' for id ' + id : ' for bill ' + billIdParam}` }, 404);
    if (ir.Active === 'FALSE') return json({ error: 'This review row is already withdrawn.' }, 400);

    const invoiceId = (ir.QB_Invoice_ID || '').trim();
    const billId    = (ir.QB_Bill_ID || '').trim();
    if (!invoiceId && !billId) {
      // Nothing was ever sent — the ordinary unapprove path already handles this cleanly.
      return await unapproveInvoiceReview(env, { id: ir.ID });
    }

    const token = await qbAccessToken(env);

    // Dry-run both first (read + qbTxnSafeToDelete, no writes) before deleting either.
    if (invoiceId) {
      const got = await qbApi(env, `invoice/${encodeURIComponent(invoiceId)}?minorversion=73`, 'GET', null, token);
      const inv = got && got.Invoice;
      if (!inv) return json({ error: `Could not read QuickBooks invoice ${invoiceId}: ${qbFault(got) || 'not found'}` }, 502);
      const safe = qbTxnSafeToDelete('Invoice', invoiceId, inv.Balance, inv.TotalAmt);
      if (!safe.ok) return json({ error: safe.error, invoice_id: invoiceId, bill_id: billId }, 409);
    }
    if (billId) {
      const got = await qbApi(env, `bill/${encodeURIComponent(billId)}?minorversion=73`, 'GET', null, token);
      const bill = got && got.Bill;
      if (!bill) return json({ error: `Could not read QuickBooks bill ${billId}: ${qbFault(got) || 'not found'}` }, 502);
      const safe = qbTxnSafeToDelete('Bill', billId, bill.Balance, bill.TotalAmt);
      if (!safe.ok) return json({ error: safe.error, invoice_id: invoiceId, bill_id: billId }, 409);
    }

    // Both sides confirmed safe (or absent) — now actually delete.
    const invRes = await qbDeleteInvoiceSafe(env, invoiceId, token);
    if (!invRes.ok) return json({ error: 'Invoice: ' + invRes.error, invoice_id: invoiceId, bill_id: billId }, 502);
    const billRes = await qbDeleteBillSafe(env, billId, token);
    if (!billRes.ok) {
      // The invoice is already gone and there's no undoing THAT from here — say so plainly
      // rather than pretending nothing happened. The bill still needs clearing by hand or a
      // retry of this same call once the reason resolves.
      return json({
        ok: false, partial: true,
        error: 'QuickBooks invoice ' + invoiceId + ' was deleted, but the bill could not be: ' + billRes.error,
        invoice_id: invoiceId, bill_id: billId,
      }, 502);
    }

    // Undo any loan-ledger deduction this send applied — otherwise Brett would owe the
    // vendor money that was already docked against a bill that no longer exists.
    let loanReversed = 0;
    try {
      const ledger = await fetchTab(env, LOAN_LEDGER_TAB);
      const entry = ledger.find(r => r.Active !== 'FALSE' && r.Entry_Type === 'auto-deduction' && String(r.Bill_ID) === String(ir.Bill_ID));
      if (entry) {
        await updateRow(env, LOAN_LEDGER_TAB, entry.ID, { Active: 'FALSE' });
        loanReversed = Math.abs(parseFloat(entry.Amount) || 0);
      }
    } catch (e) { /* no ledger tab / nothing to reverse — not fatal */ }

    // A signed-proposal final billing: put its payments back to pending so they can be billed again
    // (otherwise the proposal would show as fully invoiced against a QuickBooks invoice that is gone).
    let proposalReverted = false, proposalRevertError = '';
    try { proposalReverted = (await qbProposalRevert(env, ir)).reverted; }
    catch (e) {
      proposalRevertError = 'QuickBooks was undone, but putting signed proposal Scope #' + (ir.Proposal_Scope_ID || '?') + ' back to unbilled failed: ' + String((e && e.message) || e) + ' — fix it on the Signed Proposals page.';
      try { await logTelemetry(env, { Source: 'worker', Job_Type: 'proposal_revert_failed', Skill_Or_Endpoint: '/qb/undo-send', Success: 'FALSE', Notes: ('ir=' + ir.ID + ' ' + proposalRevertError).slice(0, 480) }); } catch (_) {}
    }

    // Mirror /invoice-review/unapprove exactly from here.
    await updateRow(env, 'Invoice_Review', ir.ID, { Active: 'FALSE', QB_Invoice_Status: 'undone' });
    let billRestored = false;
    if (ir.Bill_ID) {
      try {
        const res = await updateRow(env, 'Vendor_Bills', ir.Bill_ID, { Status: 'submitted' });
        const parsed = await res.clone().json();
        billRestored = !!(parsed && parsed.success);
      } catch (e) { billRestored = false; }
    }

    // The send flipped the WO to Invoiced — undo that too, back to Complete (where
    // addVendorBill leaves a WO once its bill is submitted, which is where this is headed).
    let woReverted = false;
    if (ir.WO_ID) {
      try { await updateWOFields(env, ir.WO_ID, { Status: 'Complete', QBO_Invoice_Number: '' }); woReverted = true; }
      catch (e) { woReverted = false; }
    }

    try {
      await logWOAudit(env, ir.WO_ID || '', body.undone_by || 'Brett', 'admin', 'QB_Send_Undone',
        `Invoice ${invoiceId || '—'} / Bill ${billId || '—'}`, 'voided',
        `Undid the QuickBooks send for bill ${ir.Bill_ID || ir.ID} (invoice ${invoiceId || 'none'}, bill ${billId || 'none'} deleted in QuickBooks).` +
        (loanReversed ? ` Reversed a $${loanReversed.toFixed(2)} loan-ledger deduction.` : '') +
        (body.reason ? ` Reason: ${body.reason}` : ''));
    } catch (e) { /* audit is best-effort */ }

    return json({
      success: true, ok: true, id: ir.ID, wo_id: ir.WO_ID || '', bill_id: ir.Bill_ID || '',
      invoice_deleted: invRes.doc || invoiceId || '', bill_deleted: billRes.doc || billId || '',
      loan_reversed: loanReversed,
      bill_restored: billRestored, wo_reverted: woReverted, proposal_reverted: proposalReverted,
      warning: [billRestored ? '' : 'QuickBooks was undone, but the vendor bill could not be set back to submitted — check the Vendor_Bills row.', proposalRevertError].filter(Boolean).join(' '),
    });
  } catch (e) { return json({ ok: false, error: e.message }, 500); }
}

async function approveInvoiceReview(env, body) {
  const {
    bill_id, wo_id, vendor_id, vendor_name,
    job_type, vendor_cost, brett_time, brett_hrs, travel,
    markup, processing_fee, customer_total, brett_net, approved_by,
    own_wage, profit, own_materials, own_material_ids,
  } = body;
  // A materials/time-only invoice (Brett did the job, or the vendor's materials went on our
  // account with no labor bill) has NO vendor bill — so bill_id is optional, but we still need
  // a work order to anchor the review row to.
  if (!customer_total || (!bill_id && !wo_id)) return json({ error: 'customer_total and a bill_id or wo_id are required' }, 400);
  // A cancelled/voided bid-group copy can never be approved for customer billing (Oct 12 2026).
  {
    let _wid = wo_id;
    if (!_wid && bill_id) { const _b = (await fetchTab(env, 'Vendor_Bills')).find(b => String(b.ID) === String(bill_id)); _wid = _b ? _b.WO_ID : ''; }
    const _blk = await bidGroupWriteBlock(env, _wid, 'invoice approvals', 'aprobaciones de factura', '/invoice-review/approve');
    if (_blk) return json({ error: _blk.message, code: 'bid_group_cancelled', refusal_logged: _blk.logged }, 409);
  }
  // Server-side backstop for the Sep 22 2026 double-billing block: receipts on a signed scope
  // proposal's WO are already billed through its payment milestones. The picker disables them
  // (listBilledReceipts), but a stale page could still send them — refuse rather than bill twice.
  const _ownIds = String(own_material_ids || '').split(',').map(x => x.trim()).filter(Boolean);
  if (_ownIds.length && wo_id) {
    let covered = null;
    try { covered = await scopeCoveringSignatureForWO(env, wo_id); }
    catch (e) { return json({ error: 'Could not confirm whether this job is billed through a signed proposal, so its receipts were not billed — try again.' }, 503); }
    if (covered) return json({ error: `This job is billed through signed proposal Scope #${covered.scope_id} (its payment milestones already include materials) — its receipts can't be invoiced again here. Reload and untick them.`, scope_covered: covered }, 409);
  }
  const today = new Date().toISOString().split('T')[0];
  // Padded pricing (Oct 19 2026): the invoice builder folds the instant-pay pad into its cost basis and tells us the amount; we re-derive it from
  // the fee schedule and refuse a mismatch loudly, so the pad on the bill always equals the pad the customer's price was built on.
  const padRes = await resolveApprovalPad(env, body);
  if (padRes.error) return json({ error: padRes.error, code: 'instant_pad_mismatch' }, 409);

  // Approving twice must not create a second Invoice_Review row — the Hub can now approve
  // straight from the work order, so the same bill is reachable from two places. If this
  // bill already has a live review row, hand that one back instead of logging another.
  try {
    const existingIR = await fetchTab(env, 'Invoice_Review');
    const already = bill_id
      ? existingIR.find(r => r.Active !== 'FALSE' && String(r.Bill_ID) === String(bill_id))
      // No vendor bill on this job — the review is keyed to the work order instead, so a
      // second approve of the same job hands the first one back rather than logging twice.
      : existingIR.find(r => r.Active !== 'FALSE' && !String(r.Bill_ID || '') && String(r.WO_ID) === String(wo_id));
    if (already) {
      // Hand back the existing row rather than logging a second one — but say what it's
      // for. Approving again at a different number used to look like it worked while the
      // original amount quietly stood.
      return json({ success: true, already_approved: true, id: String(already.ID),
        approved_total: already.Customer_Total || '',
        differs: !sameCents(already.Customer_Total, customer_total),
        qb_status: already.QB_Invoice_Status || 'pending' });
    }
  } catch (e) { /* tab unreadable — fall through and let the append surface the real error */ }
  // Neither tab has these columns yet, and updateRow/addRow map by header — a write to a
  // column that isn't there reports success and stores nothing.
  try {
    await Promise.all([
      ensureColumns(env, 'Vendor_Bills',   ['Own_Wage', 'Profit', 'Own_Materials']),
      ensureColumns(env, 'Invoice_Review', ['Own_Wage', 'Profit', 'Own_Materials', 'Own_Material_IDs']),
    ]);
  } catch (e) { /* the money fields below still land; only the split is lost */ }
  if (padRes.pad > 0) { await ensureColumns(env, 'Invoice_Review', ['Instant_Pad']); }   // not in the try above: a pad that cannot be stored must stop the approval

  // 1. Update Vendor_Bills row: mark reviewed, save markup fields — only when there IS a
  //    vendor bill. A materials/time-only invoice has none to update.
  if (bill_id) await updateRow(env, 'Vendor_Bills', bill_id, {
    Status:         'reviewed',
    Job_Type:       job_type        || 'standard',
    Own_Materials:  own_materials   || '0',
    Brett_Time:     brett_time      || '0',
    Brett_Hrs:      brett_hrs       || '0',
    Travel:         travel          || '0',
    Markup:         markup          || '0',
    Processing_Fee: processing_fee  || '0',
    Customer_Total: customer_total,
    Brett_Net:      brett_net       || '0',
    Own_Wage:       own_wage        || '0',
    Profit:         profit          || '0',
    Approved_By:    approved_by     || 'Brett',
    Reviewed_Date:  today,
  });
  // 2. Append to Invoice_Review log — this row is what /qb/send-invoice acts on.
  // NOTE: the ID below is a placeholder. addRow overwrites the ID column with its own
  // auto-increment, so this 'IR-…' value never reaches the sheet. It used to be returned
  // to the caller anyway, handing back an id that matches no row — which meant the Hub
  // could not chain "approve" straight into "send to QuickBooks". The real id is read back
  // out of addRow's response below.
  const reviewRow = {
    ID:                 'IR-' + Date.now(),
    Bill_ID:            bill_id || '',
    WO_ID:              wo_id,
    Vendor_ID:          vendor_id || '',
    Vendor_Name:        vendor_name || '',
    Job_Type:           job_type,
    Vendor_Cost:        vendor_cost || '0',
    Brett_Time:         brett_time,
    // Which receipts from the Receipts tab the customer is paying for. Recorded by id so
    // the send builds exactly the lines that were approved, not whatever is on the job by
    // the time it goes out.
    Own_Materials:      own_materials || '0',
    Own_Material_IDs:   own_material_ids || '',
    Travel:             travel,
    Markup:             markup,
    Processing_Fee:     processing_fee,
    Customer_Total:     customer_total,
    Brett_Net:          brett_net,
    // Brett_Net is cash in minus cash OUT. Own_Wage is how much of it is his own hours
    // rather than what the business made — the two are different questions, and a job that
    // only covers his wage is not a job that works once he pays someone else to do it.
    Own_Wage:           own_wage || '0',
    Profit:             profit   || '0',
    ...(padRes.pad > 0 ? { Instant_Pad: String(padRes.pad) } : {}),
    QB_Invoice_Status:  'pending',
    QB_Invoice_ID:      '',
    QB_Bill_ID:         '',
    Approved_By:        approved_by,
    Approved_Date:      today,
    Active:             'TRUE',
  };
  const addRes = await addRow(env, 'Invoice_Review', reviewRow);
  let realId = '';
  try {
    const parsed = await addRes.clone().json();
    if (parsed && parsed.error) return addRes;      // missing tab / no header row — surface it
    realId = String(parsed && parsed.id || '');
  } catch (e) { /* fall through with an empty id rather than fail the whole approval */ }
  if (padRes.pad > 0 && realId) {
    // A pad that did not land would send the vendor a legacy deduction while the customer's price was built on a pad: say so, never go quiet.
    try {
      invalidateTabCache('Invoice_Review');
      const back = (await fetchTab(env, 'Invoice_Review')).find(r => String(r.ID) === realId);
      if (!back || Math.abs((+back.Instant_Pad || 0) - padRes.pad) > 0.005) throw new Error('Instant_Pad read back as "' + (back ? back.Instant_Pad : 'no row') + '"');
    } catch (e) {
      await logTelemetry(env, { Source: 'worker', Job_Type: 'approve_instant_pad_not_saved', Skill_Or_Endpoint: '/invoice-review/approve', Success: 'FALSE', Notes: ('ir=' + realId + ' wo=' + wo_id + ' ' + String((e && e.message) || e)).slice(0, 400) }).catch(() => {});
      return json({ success: false, id: realId, error: 'The invoice was approved, but its $' + padRes.pad.toFixed(2) + ' instant-pay pad did not save (' + String((e && e.message) || e).slice(0, 120) + '). Withdraw the approval and approve again before sending to QuickBooks.' }, 500);
    }
  }
  // Sep 15 2026 — a WO carrying an unapplied vendor deposit (POST /wo/deposit-approve) has
  // now had its final bill reviewed and folded into vendor_cost (per the deposit banner
  // renderIRCard shows). Flip Deposit_Applied so a SECOND bill/review on this same WO never
  // nets the same deposit out twice, and the banner stops showing once it's been accounted for.
  try {
    const wos = await fetchTab(env, 'Work_Orders');
    const wo = findWO(wos, wo_id);
    if (wo && wo.Deposit_Amount && parseFloat(wo.Deposit_Amount) > 0 && wo.Deposit_Applied !== 'TRUE') {
      await updateWOFields(env, wo_id, { Deposit_Applied: 'TRUE' });
    }
  } catch (e) { /* non-fatal — the review itself is already saved */ }
  return json({ success: true, id: realId, instant_pad: padRes.pad || 0 });
}

// POST /invoice-review/approve-bulk { approvals: [ {bill_id, wo_id, vendor_id, vendor_name,
// job_type, vendor_cost, brett_time, brett_hrs, travel, markup, processing_fee,
// customer_total, brett_net, own_wage, profit, own_materials, own_material_ids, approved_by},
// ... ] }
//
// Same business logic as approveInvoiceReview (dedup-by-bill/WO, mark the Vendor_Bills row
// reviewed, append an Invoice_Review row) applied to a WHOLE BATCH sharing ONE read of each
// tab and ONE write of each kind, instead of ~7 Sheets calls PER bill. Built for the Review
// Bills bulk-select UI: Brett was hitting Google's per-minute Sheets quota (the "not moving
// fast" error) partly because approving bills one at a time really did mean N × ~7 reads.
// This does NOT touch QuickBooks — it only moves bills from "submitted" to "approved,
// awaiting QuickBooks" (Invoice_Review, QB_Invoice_Status:'pending'), exactly like a single
// approve does. Sending to QuickBooks stays on the existing Send-to-QB screen, which already
// has its own preview-first, one-at-a-time-confirmed batch-sequential send — money leaving
// the building through QuickBooks keeps that explicit per-item gate; only the REVIEW step
// (which creates no QuickBooks record) is now bulk.
async function approveInvoiceReviewBulk(env, body) {
  const approvals = Array.isArray(body.approvals) ? body.approvals : [];
  if (!approvals.length) return json({ error: 'approvals array required' }, 400);
  if (approvals.length > 50) return json({ error: 'Max 50 approvals per batch' }, 400);
  const today = new Date().toISOString().split('T')[0];

  try {
    await Promise.all([
      ensureColumns(env, 'Vendor_Bills',   ['Own_Wage', 'Profit', 'Own_Materials']),
      ensureColumns(env, 'Invoice_Review', ['Own_Wage', 'Profit', 'Own_Materials', 'Own_Material_IDs']),
    ]);
  } catch (e) { /* the money fields below still land; only the split is lost */ }

  const [vendorBillsData, irData] = await Promise.all([
    sheetsRequest(env, 'GET', '/values/Vendor_Bills'),
    sheetsRequest(env, 'GET', '/values/Invoice_Review'),
  ]);
  const vbHeaders = (vendorBillsData.values || [])[0] || [];
  const vbBody = (vendorBillsData.values || []).slice(1);
  const irHeaders = (irData.values || [])[0] || [];
  const irRowsRaw = (irData.values || []).slice(1);
  const irBody = irRowsRaw.map(r => { const o = {}; irHeaders.forEach((h, i) => o[h] = r[i] || ''); return o; });

  const _idcVB = idColIndex(vbHeaders);
  let nextIRId = nextSafeId(irData.values || []);

  const results = [], billUpdates = [], newIRRows = [];
  // Same signed-scope-proposal receipt backstop as approveInvoiceReview (Sep 22 2026) — read
  // Scopes/Scope_Signatures at most once for the whole batch, and only if some approval carries
  // receipts. A failed read fails just the approvals that carry receipts, never silently passes them.
  let _cover = null, _coverErr = null, _coverLoaded = false;
  const coverFor = async woId => {
    if (!_coverLoaded) {
      _coverLoaded = true;
      try {
        const orEmpty = e => { if (isMissingTabError(e)) return []; throw e; };
        const [scopes, sigs] = await Promise.all([fetchTab(env, 'Scopes').catch(orEmpty), fetchTab(env, 'Scope_Signatures').catch(orEmpty)]);
        _cover = { scopes, sigs };
      } catch (e) { _coverErr = e; }
    }
    if (_coverErr) throw _coverErr;
    return scopeCoveringSignature(_cover.scopes, _cover.sigs, woId, null);
  };

  for (const a of approvals) {
    const bill_id = a.bill_id, wo_id = a.wo_id;
    if (!a.customer_total || (!bill_id && !wo_id)) {
      results.push({ bill_id, wo_id, success: false, error: 'customer_total and a bill_id or wo_id are required' });
      continue;
    }
    if (wo_id && String(a.own_material_ids || '').split(',').map(x => x.trim()).filter(Boolean).length) {
      let covered = null;
      try { covered = await coverFor(wo_id); }
      catch (e) { results.push({ bill_id, wo_id, success: false, error: 'Could not confirm whether this job is billed through a signed proposal — its receipts were not billed. Try again.' }); continue; }
      if (covered) { results.push({ bill_id, wo_id, success: false, error: `Billed through signed proposal Scope #${covered.scope_id} — its receipts can't be invoiced again here. Untick them and re-approve.`, scope_covered: covered }); continue; }
    }
    // Same dedup rule as the single-item approve: approving the same bill/job twice hands
    // back the existing row instead of logging a duplicate.
    const already = bill_id
      ? irBody.find(r => r.Active !== 'FALSE' && String(r.Bill_ID) === String(bill_id))
      : irBody.find(r => r.Active !== 'FALSE' && !String(r.Bill_ID || '') && String(r.WO_ID) === String(wo_id));
    if (already) {
      results.push({ bill_id, wo_id, success: true, already_approved: true, id: String(already.ID),
        approved_total: already.Customer_Total || '', differs: !sameCents(already.Customer_Total, a.customer_total) });
      continue;
    }

    if (bill_id) {
      const rowIndex = vbBody.findIndex(r => r[_idcVB] === String(bill_id));
      if (rowIndex === -1) { results.push({ bill_id, wo_id, success: false, error: 'Vendor bill not found' }); continue; }
      const sheetRow = rowIndex + 2;
      const fields = {
        Status: 'reviewed', Job_Type: a.job_type || 'standard', Own_Materials: a.own_materials || '0',
        Brett_Time: a.brett_time || '0', Brett_Hrs: a.brett_hrs || '0', Travel: a.travel || '0',
        Markup: a.markup || '0', Processing_Fee: a.processing_fee || '0', Customer_Total: a.customer_total,
        Brett_Net: a.brett_net || '0', Own_Wage: a.own_wage || '0', Profit: a.profit || '0',
        Approved_By: a.approved_by || 'Brett', Reviewed_Date: today,
      };
      for (const [field, value] of Object.entries(fields)) {
        const colIndex = vbHeaders.indexOf(field);
        if (colIndex !== -1) billUpdates.push({ range: `Vendor_Bills!${col(colIndex)}${sheetRow}`, values: [[value]] });
      }
    }

    const irId = nextIRId; nextIRId += 1;
    const reviewRowObj = {
      ID: String(irId), Bill_ID: bill_id || '', WO_ID: wo_id, Vendor_ID: a.vendor_id || '', Vendor_Name: a.vendor_name || '',
      Job_Type: a.job_type, Vendor_Cost: a.vendor_cost || '0', Brett_Time: a.brett_time,
      Own_Materials: a.own_materials || '0', Own_Material_IDs: a.own_material_ids || '',
      Travel: a.travel, Markup: a.markup, Processing_Fee: a.processing_fee, Customer_Total: a.customer_total,
      Brett_Net: a.brett_net, Own_Wage: a.own_wage || '0', Profit: a.profit || '0',
      QB_Invoice_Status: 'pending', QB_Invoice_ID: '', QB_Bill_ID: '', Approved_By: a.approved_by || 'Brett',
      Approved_Date: today, Active: 'TRUE',
    };
    newIRRows.push(irHeaders.map(h => reviewRowObj[h] !== undefined ? String(reviewRowObj[h]) : ''));
    results.push({ bill_id, wo_id, success: true, id: String(irId) });
  }

  // Exactly two writes total, however many bills are in the batch — versus 2N before.
  if (billUpdates.length) await sheetsRequest(env, 'POST', '/values:batchUpdate', { valueInputOption: 'RAW', data: billUpdates });
  if (newIRRows.length) await sheetsRequest(env, 'POST', '/values/Invoice_Review:append?valueInputOption=RAW', { values: newIRRows });

  return json({ success: true, results });
}

// ── ESTIMATES ────────────────────────────────────────────────

// Stored Line_Items JSON with the derived desc_en removed — what the vendor actually submitted.
function estimateLineItemsCanonical(json) {
  try { return JSON.stringify((JSON.parse(json || '[]') || []).map(li => { const c = Object.assign({}, li); delete c.desc_en; return c; })); } catch (_) { return String(json || ''); }
}

// POST /estimate/retranslate { estimate_id | wo_id + version } — ADMIN-ONLY (no ROLE_SCOPES entry).
// Re-runs the English translation of a stored estimate (every non-blank line + the change reason,
// no heuristic) and rewrites ONLY the derived English fields: per-line desc_en inside Line_Items and
// Change_Reason_EN. The vendor's original desc / Change_Reason / amounts are never touched.
async function retranslateEstimate(env, body) {
  const all = await fetchTab(env, 'Estimates');
  let est = null;
  if (body && body.estimate_id) est = all.find(e => String(e.ID) === String(body.estimate_id));
  else if (body && body.wo_id && body.version != null) est = all.find(e => e.WO_ID === String(body.wo_id) && String(e.Version) === String(body.version) && e.Active !== 'FALSE');
  else return json({ error: 'estimate_id, or wo_id + version, required' }, 400);
  if (!est) return json({ error: 'Estimate not found' }, 404);
  let lines = []; try { lines = JSON.parse(est.Line_Items || '[]'); } catch (_) {}
  if (!Array.isArray(lines) || !lines.length) return json({ error: 'Estimate has no line items' }, 400);
  const en = await estimateEnglishFields(env, lines, est.Change_Reason || '', { force: true });
  if (!en.ok) return json({ ok: false, success: false, error: 'Translation is unavailable right now (' + (en.error || 'unknown') + ') — nothing was changed. Try again in a minute.' }, 502);
  try { await ensureColumns(env, 'Estimates', ['Change_Reason_EN']); } catch (_) {}
  await updateRow(env, 'Estimates', est.ID, { Line_Items: JSON.stringify(en.line_items), Change_Reason_EN: en.change_reason_en || '' });
  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'estimate_retranslate', Skill_Or_Endpoint: '/estimate/retranslate', Success: 'TRUE', Notes: `estimate=${est.ID} wo=${est.WO_ID} v${est.Version}` }); } catch (_) {}
  return json({ success: true, ok: true, estimate_id: est.ID, wo_id: est.WO_ID, version: est.Version, line_items: en.line_items, change_reason_en: en.change_reason_en || '',
    changed: en.line_items.some(li => li.desc_en) || !!en.change_reason_en });
}

async function listEstimates(env, url) {
  const woId = url.searchParams.get('wo_id') || '';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  const all = await fetchTab(env, 'Estimates');
  const results = all.filter(e => e.WO_ID === woId && e.Active !== 'FALSE').sort((a, b) => parseInt(a.Version||'1') - parseInt(b.Version||'1')).map(e => { try { e.Line_Items = JSON.parse(e.Line_Items||'[]'); } catch { e.Line_Items = []; } return e; });
  return json(results);
}

// POST /estimate/unapprove { wo_id, reason? }
// An approved estimate is a commitment the vendor has been told to proceed on, so taking
// it back has to tell them — otherwise they carry on working to a number that no longer
// stands.
// ── ESTIMATE / PROPOSAL SMS (Sep 28 2026, FEATURE_LOG rule 201) ───────────────────────────────
// Everything goes through smsGatedSend, so the existing gates apply unchanged: Config
// TWILIO_ENABLED (global), TWILIO_TEST_MODE (redirects to the test recipient), Vendors.SMS_Enabled /
// SMS_OptOut for vendors, quiet hours (7pm-9am ET hold, except the 8am reminder). 'admin' is a new
// recipient kind = Brett himself: only the Global switch applies (his own number, Config
// ADMIN_SMS_PHONE, falling back to TWILIO_TEST_RECIPIENT). Bodies come from Message_Templates so
// Brett can reword them; vendor bodies never carry dollar amounts.
const HUB_URL = 'https://ridge-co.github.io/RidgeCo/index.html';
// Only estimates/signings created AFTER this instant ever trigger reminders or deposit texts, so the
// 14 old backfilled "Estimated" jobs can't text him. Override with Config estimate_sms_since.
const ESTIMATE_SMS_DEFAULT_SINCE = '2026-09-29T00:00:00.000Z';
const NEEDS_INFO_RESUME_DAYS = 3;
const REMINDER_MIN_AGE_HOURS = 12; // an estimate posted this morning already got its own text
async function getAdminSmsRecipient(env) {
  let cfg = {}; try { cfg = await fetchConfig(env); } catch (_) {}
  return { Name: 'Brett', Phone: cfg.ADMIN_SMS_PHONE || cfg.TWILIO_TEST_RECIPIENT || '+14439617927' };
}
// "20 E Eager St Apt 3" for a work order — property + unit (Brett Oct 19). Falls back to the property alone,
// and never throws (a text must not fail because a lookup did): an unresolved address is "" and logged.
async function woLocationText(env, woId, fallbackProperty, unitId) {
  try {
    if (!woId && !unitId) return propUnitText(fallbackProperty, null);
    const [wos, props, units] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Properties'), fetchTab(env, 'Units')]);
    const wo = woId ? findWO(wos, woId) : null;
    const property = (wo && props.find(p => String(p.ID) === String(wo.Property_ID))) || fallbackProperty || null;
    const uid = (wo && wo.Unit_ID) || unitId || '';
    const unit = uid ? units.find(u => String(u.ID) === String(uid)) : null;
    return propUnitText(property, unit) || (wo && wo.Address) || '';
  } catch (e) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'wo_location_lookup_failed', Skill_Or_Endpoint: 'woLocationText', Success: 'FALSE', Notes: ('wo=' + woId + ' ' + String((e && e.message) || e)).slice(0, 300) }); } catch (_) {}
    return propUnitText(fallbackProperty, null);
  }
}
async function sendTemplatedSms(env, o) {
  try {
    let tpl = null; try { tpl = await getMessageTemplate(env, o.type, 'sms'); } catch (_) {}
    const def = DEFAULT_MESSAGE_TEMPLATES.find(t => t.Message_Type === o.type && t.Channel === 'sms');
    const tk = Object.assign({ HubUrl: HUB_URL }, o.tokens || {});
    if (tk.Location == null || tk.Location === '') tk.Location = (await woLocationText(env, o.wo_id, o.property, o.unit_id)) || tk.Address || 'the property';
    const body = renderTemplate(tpl ? tpl.Body : (def ? def.Body : ''), tk).replace(/\s+/g, ' ').trim();
    if (!body) return { sent: false, reason: 'no template for ' + o.type };
    const opts = { wo_id: o.wo_id || '', message_type: o.type, recipient_type: o.kind, message_body: body, property: o.property, bypassQuietHours: !!o.bypassQuietHours };
    if (o.quietWindow) opts.quietWindow = o.quietWindow;
    if (o.skip_if_seen) opts.skip_if_seen = o.skip_if_seen;
    if (o.kind === 'admin') opts.admin = await getAdminSmsRecipient(env); else if (o.kind === 'owner') opts.owner = o.owner; else opts.vendor = o.vendor;
    return await smsGatedSend(env, opts);
  } catch (e) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'estimate_sms_failed', Skill_Or_Endpoint: o.type, Success: 'FALSE', Notes: 'wo=' + (o.wo_id || '') + ' err=' + String((e && e.message) || e).slice(0, 200) }); } catch (_) {}
    return { sent: false, error: String((e && e.message) || e) };
  }
}
const fmtMoney = n => (parseFloat(n) || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const vendorFirstName = v => (v && (v.First_Name || (v.Name || '').split(' ')[0])) || 'there';
async function estimateSmsContext(env, woId, vendorIdHint) {
  const [wos, props, vendors] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Properties'), fetchTab(env, 'Vendors')]);
  const wo = findWO(wos, woId) || null;
  const property = wo ? props.find(p => p.ID === wo.Property_ID) : null;
  const vendor = vendors.find(v => v.ID === (vendorIdHint || (wo && wo.Vendor_ID))) || null;
  return { wo, property, vendor, address: (property && property.Address) || (wo && wo.Address) || '' };
}
async function notifyVendorTemplated(env, type, woId, vendorIdHint, extraTokens, job) {
  const c = await estimateSmsContext(env, woId, vendorIdHint);
  if (!c.vendor || !c.vendor.Phone) return { sent: false, reason: 'no vendor phone' };
  return sendTemplatedSms(env, { type, kind: 'vendor', vendor: c.vendor, wo_id: woId, property: c.property,
    tokens: Object.assign({ FirstName: vendorFirstName(c.vendor), WO: woId, Job: job || ('work order ' + woId) }, extraTokens || {}) });
}
// PURE — which estimates are "awaiting Brett's decision" for the daily reminder. Latest active
// version per WO; Pending (or blank) counts; 'Needs Info' pauses and resumes NEEDS_INFO_RESUME_DAYS
// after it was flagged; Approved / Declined / Converted never count. Voided/closed WOs never count.
function estimatesAwaitingDecision(estimates, workorders, now, sinceISO) {
  const CLOSED = WOStatus.sets.RECEIPT_CLOSED;
  const latest = {};
  for (const e of estimates || []) {
    if (e.Active === 'FALSE' || !e.WO_ID) continue;
    const cur = latest[e.WO_ID];
    if (!cur || (parseInt(e.Version) || 0) > (parseInt(cur.Version) || 0)) latest[e.WO_ID] = e;
  }
  const since = Date.parse(sinceISO) || 0, nowMs = now.getTime(), out = [];
  for (const woId of Object.keys(latest)) {
    const e = latest[woId], st = String(e.Status || 'Pending');
    const created = Date.parse(e.Created_Date || '') || 0;
    if (created < since) continue;
    if (nowMs - created < REMINDER_MIN_AGE_HOURS * 3600000) continue;
    if (st === 'Needs Info') {
      const flagged = Date.parse(e.Needs_Info_Date || '') || 0;
      if (!flagged || nowMs - flagged < NEEDS_INFO_RESUME_DAYS * 86400000) continue;
    } else if (st !== 'Pending' && st !== '') continue;
    const wo = (workorders || []).find(w => w.ID === woId);
    if (!wo || wo.Voided === 'TRUE' || CLOSED.includes(String(wo.Status || ''))) continue;
    out.push({ wo_id: woId, estimate: e, wo });
  }
  return out.sort((a, b) => String(a.estimate.Created_Date).localeCompare(String(b.estimate.Created_Date)));
}
function etDateString(date) { return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(date); }
// Runs from the scheduler's `sweep_work` job (every ~15 min). Sends ONE digest text per day, from 8am ET until
// 6pm ET (so a scheduler outage at 8am still catches up that day, never after hours), only when something is
// awaiting a decision. Claims the day BEFORE sending, so two overlapping callers can never text twice.
async function processEstimateReminders(env, nowArg) {
  const now = nowArg || new Date();
  { const h = etHour(now); if (h < 8 || h >= 18) return { skipped: 'outside the 8am-6pm ET reminder window' }; }
  let cfg = {}; try { cfg = await fetchConfig(env); } catch (_) {}
  const today = etDateString(now);
  if (cfg.estimate_reminder_last_date === today) return { skipped: 'already sent today' };
  const [ests, wos, vendors] = await Promise.all([fetchTab(env, 'Estimates'), fetchTab(env, 'Work_Orders'), fetchTab(env, 'Vendors')]);
  const pending = estimatesAwaitingDecision(ests, wos, now, cfg.estimate_sms_since || ESTIMATE_SMS_DEFAULT_SINCE);
  if (!pending.length) return { count: 0 };
  try { await setConfigKey(env, { key: 'estimate_reminder_last_date', value: today }); } catch (_) { return { skipped: 'could not claim the day' }; }
  const [propsR, unitsR] = await Promise.all([fetchTab(env, 'Properties'), fetchTab(env, 'Units')]);
  const list = pending.slice(0, 5).map(p => {
    const v = vendors.find(x => x.ID === (p.estimate.Vendor_ID || p.wo.Vendor_ID));
    const loc = propUnitText(propsR.find(x => String(x.ID) === String(p.wo.Property_ID)), unitsR.find(x => String(x.ID) === String(p.wo.Unit_ID)));
    return p.wo_id + (loc ? ' (' + loc + ')' : '') + (v ? ' ' + (v.First_Name || v.Name || '') : '') + ' $' + fmtMoney(p.estimate.Subtotal);
  }).join(', ') + (pending.length > 5 ? ' +' + (pending.length - 5) + ' more' : '');
  const r = await sendTemplatedSms(env, { type: 'admin_estimate_reminder', kind: 'admin', bypassQuietHours: true, tokens: { Count: pending.length, List: list } });
  return { count: pending.length, sent: !!(r && r.sent), gate: r && r.gate_snapshot };
}
// Pure: a signature's FIRST milestone = its lowest-Sequence non-inactive milestone (the deposit milestone).
function firstMilestoneForSignature(sig, milestones) {
  if (!sig) return null;
  const ms = (milestones || []).filter(m => m.Signature_ID === String(sig.ID) && String(m.Active || '').toUpperCase() !== 'FALSE');
  ms.sort((a, b) => (parseInt(a.Sequence) || 0) - (parseInt(b.Sequence) || 0));
  return ms[0] || null;
}
// Pure: the deposit milestone = the first milestone, and ONLY if it carries a QuickBooks invoice. If milestone 1 has
// no invoice yet this returns null -- it never falls through to milestone 2 (that is not the deposit).
function depositMilestoneForSignature(sig, milestones) {
  const f = firstMilestoneForSignature(sig, milestones);
  return f && (f.QB_Invoice_ID || '').trim() ? f : null;
}
// Pure: deposit invoice for a scope given already-read Scope_Signatures + Payment_Milestones rows.
// source is 'signature' (legacy Scope_Signatures.QB_Invoice_ID), 'milestone' (first milestone) or ''.
// `first` is the first milestone even when it has no invoice (used to tell "awaiting" from "billed but missing").
function resolveScopeDepositInvoice(sigs, milestones, scopeId) {
  const live = (sigs || []).filter(x => x.Scope_ID === String(scopeId) && String(x.Active || '').toUpperCase() !== 'FALSE');
  if (!live.length) return { sig: null, invoiceId: '', source: '', milestone: null, first: null };
  const sig = live[live.length - 1];
  const first = firstMilestoneForSignature(sig, milestones);
  if ((sig.QB_Invoice_ID || '').trim()) return { sig, invoiceId: sig.QB_Invoice_ID.trim(), source: 'signature', milestone: null, first };
  const m = depositMilestoneForSignature(sig, milestones);
  return { sig, invoiceId: m ? m.QB_Invoice_ID.trim() : '', source: m ? 'milestone' : '', milestone: m, first };
}
// Pure: a Pre-approved scope with no resolvable deposit invoice. 'alarm' = tell Brett (SMS + telemetry + red banner):
// no signature at all, milestone 1 is Status 'billed' but has no invoice id, or the signature is 24h+ old (or its time
// is unreadable). Otherwise it is just awaiting the normal deposit invoice (muted banner line only).
function classifyMissingDeposit(sig, first, nowMs) {
  if (!sig) return { alarm: true, reason: 'Pre-approved but no active signature found' };
  if (first && String(first.Status || '').toLowerCase() === 'billed') return { alarm: true, reason: 'no deposit invoice id: milestone ' + first.ID + ' is marked billed but has no QuickBooks invoice' };
  const signed = Date.parse(sig.Signed_TS || sig.Signed_Date || '');
  if (!isNaN(signed) && nowMs - signed < 24 * 3600000) return { alarm: false, reason: 'awaiting deposit invoice (signed less than 24h ago)' };
  return { alarm: true, reason: 'no deposit invoice on the signature or its first milestone' + (first ? ' (milestone ' + first.ID + ')' : ' (no milestones)') + ', 24h+ after signing' };
}
// Deposit invoice for a signed scope: the legacy signature invoice, else the earliest billed milestone.
// A Payment_Milestones read failure now THROWS (it used to be swallowed into "no invoice", which made a
// milestone-billed deposit look un-invoiced); callers log it. `tabs` lets a loop read the tabs once.
async function scopeDepositInvoiceId(env, scopeId, tabs) {
  let sigs, milestones;
  if (tabs) { sigs = tabs.sigs; milestones = tabs.milestones; }
  else {
    sigs = await fetchTab(env, 'Scope_Signatures');
    try { await paymentMilestonesTab(env); } catch (_) {}
    milestones = await fetchTab(env, 'Payment_Milestones');
  }
  return resolveScopeDepositInvoice(sigs, milestones, scopeId);
}
// Pre-approved -> Approved + the two "deposit paid" texts. The stage check makes it idempotent, so
// the 15-minute sweep, the daily QuickBooks sync and the Who To Pay page-open sweep can all call it.
// Only the call that actually moves Pre-approved -> Approved sends texts. Texts are skipped for
// signings older than the SMS cut-over so backfilled history never fires.
// Claims Config `deposit_paid_text_<scopeId>` right before texting (cross-isolate guard: a second concurrent sweep
// finds it set and does not text again). Returns { changed, texted, text_errors:[...] } -- a text that did not go
// out (error / sent:false / gate-blocked) or a context failure is in text_errors (logged to Ops_Telemetry too), never silent.
const _depositTransitionInFlight = new Set();
async function claimDepositTextMarker(env, key) {
  const data = await sheetsRequest(env, 'GET', '/values/Config');
  if (((data && data.values) || []).some(r => (r[0] || '').trim() === key && (r[1] || '').trim())) return 'already';
  const w = await setConfigKey(env, { key, value: new Date().toISOString() });
  if (w && w.status && w.status >= 400) throw new Error('Config write refused (HTTP ' + w.status + ')');
  return 'claimed';
}
async function scopeDepositPaidTransition(env, scopeId, sinceISO) {
  const key = String(scopeId);
  if (_depositTransitionInFlight.has(key)) return { changed: false, in_flight: true };
  _depositTransitionInFlight.add(key);
  const errs = [];
  try {
    const scope = (await fetchTab(env, 'Scopes')).find(x => x.ID === key);
    if (!scope || String(scope.Approval_Stage || '') !== 'Pre-approved') return { changed: false };
    const { sig } = await scopeDepositInvoiceId(env, scopeId);
    // Re-read the stage immediately before the write (another sweep may have just moved it).
    invalidateTabCache('Scopes');
    const fresh = (await fetchTab(env, 'Scopes')).find(x => x.ID === key);
    if (!fresh || String(fresh.Approval_Stage || '') !== 'Pre-approved') return { changed: false };
    const staged = await setApprovalStage(env, { woId: scope.WO_ID || '', scopeId: scope.ID, stage: 'Approved' });
    // setApprovalStage swallows its own errors and returns false; verify the Scope row really moved so a failed
    // write can never look like success (and never text twice on the retry).
    invalidateTabCache('Scopes');
    const after = (await fetchTab(env, 'Scopes')).find(x => x.ID === key);
    if (!staged || !after || String(after.Approval_Stage || '') !== 'Approved') throw new Error('Approval_Stage did not move to Approved for scope ' + key + ' (write failed)');
    const recent = sig && (Date.parse(sig.Signed_TS || sig.Signed_Date || '') || 0) >= (Date.parse(sinceISO) || 0);
    if (!recent) return { changed: true, texted: false, text_errors: errs };
    const ref = 'scope=' + key + ' wo=' + (scope.WO_ID || '');
    // Claim the once-only text marker BEFORE texting. A read/write failure is surfaced; we still text once for this call.
    try { if ((await claimDepositTextMarker(env, 'deposit_paid_text_' + key)) === 'already') return { changed: true, texted: false, already_texted: true, text_errors: errs }; }
    catch (e) { await logAndCollectError(env, errs, 'deposit_paid_text_claim', 'scopeDepositPaidTransition', ref + ' (could not claim the once-only text marker; texting once for this call)', e); }
    let c;
    try { c = await estimateSmsContext(env, scope.WO_ID || '', scope.Vendor_ID); }
    catch (e) { await logAndCollectError(env, errs, 'deposit_paid_text_context', 'scopeDepositPaidTransition', ref + ' approved but texts not sent', e); return { changed: true, texted: false, text_errors: errs }; }
    const job = scope.WO_ID ? ('work order ' + scope.WO_ID) : ('proposal #' + scope.ID);
    const smsOk = r => !!r && !r.error && (r.sent === true || r.held_for_quiet_hours === true);
    const why = r => String((r && (r.error || r.reason)) || (r && r.gate_snapshot ? 'blocked by the SMS gate' : 'not sent'));
    const send = async (label, o) => {
      let r; try { r = await sendTemplatedSms(env, o); } catch (e) { r = { sent: false, error: String((e && e.message) || e) }; }
      if (!smsOk(r)) await logAndCollectError(env, errs, 'deposit_paid_text_failed', 'scopeDepositPaidTransition', ref + ' ' + label, new Error(label + ' text not sent: ' + why(r)));
    };
    await send('admin_deposit_paid', { type: 'admin_deposit_paid', kind: 'admin', wo_id: scope.WO_ID || '', unit_id: scope.Unit_ID || '', property: c.property, tokens: { Job: job, Address: c.address } });
    if (c.vendor && c.vendor.Phone) await send('vendor_deposit_paid', { type: 'vendor_deposit_paid', kind: 'vendor', vendor: c.vendor, wo_id: scope.WO_ID || '', unit_id: scope.Unit_ID || '', property: c.property, tokens: { FirstName: vendorFirstName(c.vendor), Job: job } });
    else if (scope.Vendor_ID) await logAndCollectError(env, errs, 'deposit_paid_text_failed', 'scopeDepositPaidTransition', ref + ' vendor_deposit_paid', new Error('vendor_deposit_paid text not sent: vendor ' + scope.Vendor_ID + ' not found or has no phone'));
    return { changed: true, texted: errs.length === 0, text_errors: errs };
  } finally { _depositTransitionInFlight.delete(key); }
}
// Nothing may fail silently (Brett, Oct 1 2026): log an error to Ops_Telemetry (Success=FALSE) AND push it onto
// `sink` so it is returned to the caller / shown in the UI. If telemetry itself fails that is added to the sink too.
async function logAndCollectError(env, sink, jobType, endpoint, ref, e) {
  const msg = String((e && e.message) || e).slice(0, 300);
  const entry = { stage: jobType, ref: ref || '', error: msg };
  sink.push(entry);
  try { await logTelemetry(env, { Source: 'worker', Job_Type: jobType, Skill_Or_Endpoint: endpoint, Success: 'FALSE', Notes: `${ref || ''} err=${msg}`.slice(0, 500) }); }
  catch (le) { sink.push({ stage: 'telemetry', ref: ref || '', error: 'could not write Ops_Telemetry: ' + String((le && le.message) || le).slice(0, 200) }); }
  return entry;
}
// Surfaces one sweep problem: pushes it on out.not_found / out.errors; writes Ops_Telemetry (not_found: once per scope
// per day via marker <key>_tel so a 15-min cron does not flood the sheet; errors: every time); and texts the admin phone
// once per scope per day. The SMS marker (deposit_sweep_alert_<kind>_<scope>) is set ONLY when a real send happened:
// a missing admin_phone, TWILIO_ENABLED off ({skipped}) or a send error is reported in out.errors (stage alert_sms) and
// does not start the 24h quiet period. The Who To Pay banner shows everything in out regardless of the markers.
async function depositSweepSurface(env, out, cfg, kind, entry) {
  (kind === 'not_found' ? out.not_found : out.errors).push(entry);
  const key = 'deposit_sweep_alert_' + kind + '_' + (entry.scope || 'sweep');
  const now = Date.now(), DAY = 24 * 3600000;
  const telDue = kind === 'error' || alertDebounceOk(cfg, key + '_tel', now, DAY);
  const smsDue = alertDebounceOk(cfg, key, now, DAY);
  const what = entry.reason || entry.error || '';
  const stamp = new Date(now).toISOString();
  let telemetryOk = true;
  if (telDue) {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'deposit_sweep_' + kind, Skill_Or_Endpoint: 'processDepositPaidSweep', Success: 'FALSE', Notes: `scope=${entry.scope || ''} wo=${entry.wo_id || ''} ${entry.stage ? 'stage=' + entry.stage + ' ' : ''}${what}`.slice(0, 500) }); }
    catch (le) { telemetryOk = false; out.errors.push({ scope: entry.scope || '', stage: 'telemetry', error: 'could not write Ops_Telemetry: ' + String((le && le.message) || le).slice(0, 200) }); }
    if (telemetryOk && kind !== 'error') {
      try { await setConfigKey(env, { key: key + '_tel', value: stamp }); cfg[key + '_tel'] = stamp; }
      catch (ce) { out.errors.push({ scope: entry.scope || '', stage: 'alert_marker', error: String((ce && ce.message) || ce).slice(0, 200) }); }
    }
  }
  if (!smsDue) return;
  let sent = false, failWhy = '';
  try {
    if (!cfg.admin_phone) throw new Error('Config admin_phone is not set');
    const r = await sendSMS(env, cfg.admin_phone, (kind === 'not_found' ? 'Deposit check: cannot find the deposit invoice for scope ' : 'Deposit check ERROR on scope ') + (entry.scope || '?') + (entry.wo_id ? ' (' + entry.wo_id + ')' : '') + ' - ' + String(what).slice(0, 120));
    if (r && r.error) throw new Error(String(r.error));
    if (r && r.skipped) throw new Error('SMS skipped: ' + (r.reason || 'sending is disabled'));
    sent = true;
  } catch (se) { failWhy = String((se && se.message) || se).slice(0, 200); }
  if (!sent) {
    out.errors.push({ scope: entry.scope || '', wo_id: entry.wo_id || '', stage: 'alert_sms', error: 'admin alert NOT sent: ' + failWhy });
    if (telDue) { try { await logTelemetry(env, { Source: 'worker', Job_Type: 'deposit_sweep_alert_not_sent', Skill_Or_Endpoint: 'processDepositPaidSweep', Success: 'FALSE', Notes: `scope=${entry.scope || ''} wo=${entry.wo_id || ''} ${failWhy}`.slice(0, 500) }); } catch (le) { out.errors.push({ scope: entry.scope || '', stage: 'telemetry', error: 'could not write Ops_Telemetry: ' + String((le && le.message) || le).slice(0, 200) }); } }
    return;
  }
  try { await setConfigKey(env, { key, value: stamp }); cfg[key] = stamp; }
  catch (ce) { out.errors.push({ scope: entry.scope || '', stage: 'alert_marker', error: String((ce && ce.message) || ce).slice(0, 200) }); }
}
// Fast sweep (the scheduler's sweep_work job every ~15 min, the daily_qb_sync job via qbSyncPayments, and POST /scope-deposit/sweep
// which the Who To Pay page fires when it opens). Only touches QuickBooks when a Pre-approved scope exists.
// Returns { ok, checked, transitioned:[{scope,wo_id,texted,text_errors?,invoice_id,source}], not_found:[{scope,wo_id,reason,invoice_id?}],
// awaiting_invoice:[{scope,wo_id,reason}] (fresh signing, normal wait, no alert), errors:[{scope?,wo_id?,stage,error}] }.
// NEVER throws and NEVER swallows: every failure is in `errors` AND in Ops_Telemetry.
// not_found = a Pre-approved scope whose deposit invoice cannot be resolved for real (no signature, milestone 1 billed with
// no invoice id, or signed 24h+ ago with none) or cannot be fetched from QuickBooks. ok is false when errors/not_found exist.
// Pure. Config DEPOSIT_SWEEP_SKIP_SCOPES = comma/space separated Scope IDs Brett has said to stop alarming on (Oct 14 2026:
// scopes 4 and 6 have no deposit invoice and never will). Only the "no deposit invoice" ALARM is muted for a listed scope:
// if an invoice shows up later the sweep still checks it and still marks the deposit paid. Every muted scope is reported in
// the sweep result under `skipped` (never dropped), so the skip is visible in /cron/status detail and on the Who To Pay page.
function depositSweepSkipSet(cfg) {
  const raw = String((cfg && cfg.DEPOSIT_SWEEP_SKIP_SCOPES) == null ? '' : cfg.DEPOSIT_SWEEP_SKIP_SCOPES);
  return new Set(raw.split(/[\s,;]+/).map(x => x.trim()).filter(Boolean));
}
async function processDepositPaidSweep(env) {
  const out = { ok: true, checked: 0, transitioned: [], not_found: [], awaiting_invoice: [], skipped: [], errors: [] };
  let cfg = {};
  try { cfg = await fetchConfig(env); } catch (e) { cfg = {}; await logAndCollectError(env, out.errors, 'deposit_sweep_config', 'processDepositPaidSweep', 'fetchConfig', e); }
  const skipScopes = depositSweepSkipSet(cfg);
  let scopes, tabs, token;
  try {
    scopes = (await fetchTab(env, 'Scopes')).filter(x => String(x.Approval_Stage || '') === 'Pre-approved' && x.Active !== 'FALSE');
    out.checked = scopes.length;
    if (!scopes.length) { out.ok = !out.errors.length; return out; }
    try { await paymentMilestonesTab(env); } catch (_) {}
    tabs = { sigs: await fetchTab(env, 'Scope_Signatures'), milestones: await fetchTab(env, 'Payment_Milestones') };
  } catch (e) {
    await logAndCollectError(env, out.errors, 'deposit_sweep_read', 'processDepositPaidSweep', 'scopes/signatures/milestones', e);
    out.ok = false; return out;
  }
  const since = cfg.estimate_sms_since || ESTIMATE_SMS_DEFAULT_SINCE;
  try { token = await qbAccessToken(env); }
  catch (e) {
    for (const sc of scopes) await depositSweepSurface(env, out, cfg, 'error', { scope: sc.ID, wo_id: sc.WO_ID || '', stage: 'qb_token', error: 'QuickBooks token failed: ' + String((e && e.message) || e).slice(0, 160) });
    out.ok = false; return out;
  }
  for (const sc of scopes) {
    const base = { scope: sc.ID, wo_id: sc.WO_ID || '' };
    try {
      const { sig, first, invoiceId, source } = await scopeDepositInvoiceId(env, sc.ID, tabs);
      if (!invoiceId) {
        const k = classifyMissingDeposit(sig, first, Date.now());
        if (k.alarm && skipScopes.has(String(sc.ID))) out.skipped.push(Object.assign({}, base, { reason: 'on the DEPOSIT_SWEEP_SKIP_SCOPES list: ' + k.reason }));
        else if (k.alarm) await depositSweepSurface(env, out, cfg, 'not_found', Object.assign({}, base, { reason: k.reason }));
        else out.awaiting_invoice.push(Object.assign({}, base, { reason: k.reason }));
        continue;
      }
      const r = await qbApi(env, 'invoice/' + encodeURIComponent(invoiceId) + '?minorversion=73', 'GET', null, token);
      const inv = r && r.Invoice;
      if (!inv) { await depositSweepSurface(env, out, cfg, 'not_found', Object.assign({}, base, { invoice_id: invoiceId, reason: 'QuickBooks returned no invoice ' + invoiceId })); continue; }
      if ((Number(inv.TotalAmt) || 0) > 0 && (Number(inv.Balance) || 0) <= 0.005) {
        const t = await scopeDepositPaidTransition(env, sc.ID, since);
        if (t && t.changed) {
          out.transitioned.push(Object.assign({}, base, { texted: !!t.texted, text_errors: t.text_errors || [], invoice_id: invoiceId, source }));
          if (t.text_errors && t.text_errors.length) out.errors.push(...t.text_errors.map(e => Object.assign({ scope: sc.ID, wo_id: sc.WO_ID || '' }, e)));
        }
      }
    } catch (e) {
      await depositSweepSurface(env, out, cfg, 'error', Object.assign({}, base, { stage: 'scope', error: String((e && e.message) || e).slice(0, 200) }));
    }
  }
  out.ok = !out.errors.length && !out.not_found.length;
  return out;
}
// POST /estimate/needs-info { wo_id } and POST /estimate/decline { wo_id, reason? } — admin-only.
async function flagEstimate(env, body, kind) {
  const woId = body && body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const [all, _woRows] = await fetchTabs(env, ['Estimates', 'Work_Orders']);
  const versions = all.filter(e => e.WO_ID === woId && e.Active !== 'FALSE');
  if (!versions.length) return json({ error: 'No estimate found for this WO' }, 404);
  const latest = versions.reduce((a, b) => (parseInt(a.Version) || 0) > (parseInt(b.Version) || 0) ? a : b);
  const _blockMsg = addonEstimateActionBlock(findWO(_woRows, woId), latest, kind);
  if (_blockMsg) return json({ error: _blockMsg }, 400);
  const st = String(latest.Status || 'Pending');
  if (!['Pending', 'Needs Info'].includes(st)) return json({ error: `That estimate is "${st}" — only a pending estimate can be flagged ${kind === 'decline' ? 'declined' : 'needs-info'}.` }, 409);
  try { await ensureColumns(env, 'Estimates', ['Needs_Info_Date', 'Declined_Date', 'Decline_Reason']); } catch (_) {}
  const now = new Date().toISOString();
  await updateRow(env, 'Estimates', latest.ID, kind === 'decline'
    ? { Status: 'Declined', Declined_Date: now, Decline_Reason: String(body.reason || '').slice(0, 300) }
    : { Status: 'Needs Info', Needs_Info_Date: now });
  if (kind === 'decline') await setApprovalStage(env, { woId, stage: '' });
  const r = await notifyVendorTemplated(env, kind === 'decline' ? 'vendor_estimate_declined' : 'vendor_estimate_needs_info', woId, latest.Vendor_ID);
  return json({ success: true, wo_id: woId, status: kind === 'decline' ? 'Declined' : 'Needs Info', vendor_notified: !!(r && r.sent), vendor_sms: r && (r.sent ? 'sent' : (r.gate_snapshot || r.reason || 'not sent')),
    resumes_reminders_after_days: kind === 'decline' ? null : NEEDS_INFO_RESUME_DAYS });
}
const estimateNeedsInfo = (env, body) => flagEstimate(env, body, 'needs-info');
const estimateDecline = (env, body) => flagEstimate(env, body, 'decline');

// ── APPROVAL STAGE (Sep 28 2026, FEATURE_LOG rule 200) ─────────────────────────────────────────
// One field — Approval_Stage — on Work_Orders AND Scopes, so Brett can filter jobs/proposals that
// still need an approval step without opening each one. Stages: Estimated (vendor submitted, waiting
// on Brett) → Approved (Brett approved on the WO, no owner involved) OR Proposed (pushed to the
// owner as a proposal) → Pre-approved (owner signed, deposit not yet paid) → Approved (deposit paid).
// Every transition goes through setApprovalStage so the labels live in exactly one place.
// Best-effort: a stage write must never fail the real action (approve / sign / push).
const APPROVAL_STAGES = ['Estimated', 'Proposed', 'Pre-approved', 'Approved'];
async function setApprovalStage(env, { woId, scopeId, stage, onlyFrom }) {
  if (stage !== '' && !APPROVAL_STAGES.includes(stage)) return false; // '' clears (declined)
  let ok = false;
  try {
    if (woId) {
      try { await ensureColumns(env, 'Work_Orders', ['Approval_Stage', 'Estimate_Revised']); } catch (_) {}
      if (onlyFrom) {
        const wo = findWO(await fetchTab(env, 'Work_Orders'), woId);
        if (!wo || !onlyFrom.includes(String(wo.Approval_Stage || ''))) return false;
      }
      await updateWOFields(env, woId, { Approval_Stage: stage, Estimate_Revised: '' }); ok = true;
    }
    if (scopeId) {
      try { await ensureColumns(env, 'Scopes', ['Approval_Stage']); } catch (_) {}
      await updateRow(env, 'Scopes', scopeId, { Approval_Stage: stage }); ok = true;
    }
  } catch (_) { /* best-effort */ }
  return ok;
}

// POST /admin/backfill-approval-stage { apply?: true } — idempotent one-time fill of Approval_Stage
// on existing Work_Orders and Scopes (rule 200). Preview by default. Derivation: signed scope →
// Pre-approved (the deposit-paid sweep in qbSyncPayments lifts it to Approved); scope-linked WO with a
// Converted estimate → Proposed; latest estimate Approved → Approved; any other estimate → Estimated.
// Never overwrites a stage that is already set.
async function backfillApprovalStage(env, body) {
  const apply = !!(body && body.apply === true);
  const [wos, ests, scopes] = await Promise.all([fetchTab(env, 'Work_Orders'), fetchTab(env, 'Estimates'), fetchTab(env, 'Scopes')]);
  const latestByWO = {};
  for (const e of ests) {
    if (e.Active === 'FALSE' || !e.WO_ID) continue;
    const cur = latestByWO[e.WO_ID];
    if (!cur || (parseInt(e.Version) || 0) > (parseInt(cur.Version) || 0)) latestByWO[e.WO_ID] = e;
  }
  const scopeStage = sc => (String(sc.Status || '').toLowerCase() === 'signed' ? 'Pre-approved' : '');
  const scopeByWO = {}; for (const sc of scopes) if (sc.WO_ID && sc.Active !== 'FALSE') scopeByWO[sc.WO_ID] = sc;
  const plan = [];
  for (const wo of wos) {
    if (String(wo.Approval_Stage || '')) continue;
    const e = latestByWO[wo.ID]; if (!e) continue;
    const sc = scopeByWO[wo.ID];
    let stage = '';
    if (sc && scopeStage(sc)) stage = scopeStage(sc);
    else if (String(e.Status) === 'Converted' || sc) stage = 'Proposed';
    else if (String(e.Status) === 'Approved') stage = 'Approved';
    else stage = 'Estimated';
    plan.push({ type: 'wo', id: wo.ID, stage });
  }
  for (const sc of scopes) {
    if (String(sc.Approval_Stage || '') || sc.Active === 'FALSE') continue;
    const wo = sc.WO_ID ? wos.find(w => w.ID === sc.WO_ID) : null;
    const stage = scopeStage(sc) || (wo && wo.Approval_Stage) || (sc.WO_ID && latestByWO[sc.WO_ID] ? 'Proposed' : '');
    if (stage) plan.push({ type: 'scope', id: sc.ID, stage });
  }
  let written = 0;
  if (apply && plan.length) {
    try { await ensureColumns(env, 'Work_Orders', ['Approval_Stage', 'Estimate_Revised']); } catch (_) {}
    try { await ensureColumns(env, 'Scopes', ['Approval_Stage']); } catch (_) {}
    for (const p of plan) {
      try {
        if (p.type === 'wo') await updateWOFields(env, p.id, { Approval_Stage: p.stage });
        else await updateRow(env, 'Scopes', p.id, { Approval_Stage: p.stage });
        written++;
      } catch (_) {}
    }
  }
  const counts = {}; plan.forEach(p => { const k = p.type + ':' + p.stage; counts[k] = (counts[k] || 0) + 1; });
  return json({ success: true, applied: apply, planned: plan.length, written, counts, sample: plan.slice(0, 15) });
}

async function unapproveEstimate(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const all = await fetchTab(env, 'Estimates');
  const versions = all.filter(e => e.WO_ID === woId && e.Active !== 'FALSE');
  if (!versions.length) return json({ error: 'No estimate found for this WO' }, 404);
  const latest = versions.reduce((a, b) => parseInt(a.Version) > parseInt(b.Version) ? a : b);
  if (String(latest.Status || '') !== 'Approved') {
    return json({ error: `That estimate is "${latest.Status || 'Pending'}", not approved — nothing to withdraw.` }, 409);
  }

  const data = await sheetsRequest(env, 'GET', '/values/Estimates');
  const rows = data.values || [], headers = rows[0] || [];
  const idCol = headers.indexOf('ID'), statusCol = headers.indexOf('Status');
  if (idCol === -1 || statusCol === -1) return json({ error: 'Estimates tab missing ID or Status column' }, 500);
  const rowIdx = rows.findIndex((r, i) => i > 0 && r[idCol] === latest.ID);
  if (rowIdx === -1) return json({ error: 'Could not locate estimate row' }, 404);
  const sheetRow = rowIdx + 1;

  const batch = [{ range: `Estimates!${col(statusCol)}${sheetRow}`, values: [['Pending']] }];
  const note = body.reason ? ('Approval withdrawn: ' + body.reason) : 'Approval withdrawn';
  const noteCol = headers.indexOf('Approval_Note');
  if (noteCol > -1) batch.push({ range: `Estimates!${col(noteCol)}${sheetRow}`, values: [[note]] });
  await sheetsRequest(env, 'POST', '/values:batchUpdate', { valueInputOption: 'RAW', data: batch });
  await setApprovalStage(env, { woId, stage: 'Estimated' });

  // Tell the vendor. They were told to proceed; they need to know that's paused.
  let vendorTold = false;
  if (latest.Vendor_ID) {
    try {
      const vendors = await fetchTab(env, 'Vendors');
      const vendor = vendors.find(v => v.ID === latest.Vendor_ID);
      if (vendor?.Phone) {
        const msgEn = `Hold on WO ${woId} — the approved estimate ($${latest.Subtotal}) has been put back on hold${body.reason ? ': ' + body.reason : ''}. Please don't proceed until we confirm the revised number.`;
        const tv = await translateForVendorDetailed(env, vendor, msgEn), msg = tv.text; // Spanish for a Spanish vendor (Sep 28 2026)
        await sendSMS(env, vendor.Phone, msg);
        await logSMS(env, woId, 'estimate_unapproved', vendor.ID, vendor.Phone, tv.translated ? msg + ' || EN: ' + msgEn : msg);
        vendorTold = true;
      }
    } catch (e) { /* status is already back to Pending; the SMS is best-effort */ }
  }
  return json({ success: true, wo_id: woId, version: latest.Version, subtotal: latest.Subtotal,
                vendor_notified: vendorTold,
                warning: (latest.Vendor_ID && !vendorTold) ? 'Estimate is back on hold, but the vendor could not be texted — tell them directly.' : '' });
}

// Additional-work guard for approve / needs-info / decline: a voided, withdrawn or draft add-on child can never be
// acted on, and (approve only) a Declined/Withdrawn latest estimate can't be approved. Returns '' (ok) or a message.
// Normal (non-addon) work orders are never affected.
function addonEstimateActionBlock(wo, latest, kind) {
  if (!wo || String(wo.Type || '') !== 'addon') return '';
  const as = String(wo.Addon_Status || '');
  if (String(wo.Voided || '').toUpperCase() === 'TRUE' || as === 'Withdrawn') return 'This additional work was withdrawn or voided — it cannot be ' + (kind === 'approve' ? 'approved' : 'changed') + '.';
  if (as === 'Draft') return 'This additional work has not been submitted yet — it cannot be ' + (kind === 'approve' ? 'approved' : 'changed') + '.';
  const st = String((latest && latest.Status) || '');
  if (kind === 'approve' && (st === 'Declined' || st === 'Withdrawn')) return 'This additional work estimate is ' + st + ' — it cannot be approved.';
  return '';
}
async function approveEstimate(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const [all, _woRows] = await fetchTabs(env, ['Estimates', 'Work_Orders']); const versions = all.filter(e => e.WO_ID === woId && e.Active !== 'FALSE');
  if (!versions.length) return json({ error: 'No estimate found for this WO' }, 404);
  const latest = versions.reduce((a, b) => parseInt(a.Version) > parseInt(b.Version) ? a : b);
  const _blockMsg = addonEstimateActionBlock(findWO(_woRows, woId), latest, 'approve');
  if (_blockMsg) return json({ error: _blockMsg }, 400);
  const data = await sheetsRequest(env, 'GET', '/values/Estimates'); const rows = data.values || [], headers = rows[0] || [];
  const idCol = headers.indexOf('ID'), statusCol = headers.indexOf('Status');
  if (idCol === -1 || statusCol === -1) return json({ error: 'Estimates tab missing ID or Status column' }, 500);
  const rowIdx = rows.findIndex((r, i) => i > 0 && r[idCol] === latest.ID);
  if (rowIdx === -1) return json({ error: 'Could not locate estimate row' }, 404);
  const sheetRow = rowIdx + 1;
  function colLetter(n) { return n < 26 ? String.fromCharCode(65+n) : 'A'+String.fromCharCode(65+n-26); }
  const approvedBy = body.approved_by || 'admin', requestDeposit = !!body.request_deposit;
  // Oct 19 2026: approving after the job is already done must be able to skip the "you're clear to proceed" text.
  const skipVendorSms = body.skip_vendor_sms === true || String(body.skip_vendor_sms).toLowerCase() === 'true';
  const approvalNote = body.approval_type || ((requestDeposit ? 'Deposit requested' : 'Approved — no deposit required') + (skipVendorSms ? ' (vendor not texted — approved after the fact)' : ''));
  const batch = [{ range: `Estimates!${colLetter(statusCol)}${sheetRow}`, values: [['Approved']] }];
  const optionalCols = { Approved_By: approvedBy, Approved_Date: new Date().toISOString(), Approval_Note: approvalNote };
  Object.entries(optionalCols).forEach(([colName, val]) => { const idx = headers.indexOf(colName); if (idx > -1) batch.push({ range: `Estimates!${colLetter(idx)}${sheetRow}`, values: [[val]] }); });
  await sheetsRequest(env, 'POST', '/values:batchUpdate', { valueInputOption: 'RAW', data: batch });
  await setApprovalStage(env, { woId, stage: 'Approved' });
  // Vendor text via the gated, editable template path (no dollar amounts — FEATURE_LOG rule 201).
  let vendorSms = null;
  let vendorSmsNote = '';
  if (skipVendorSms) vendorSmsNote = 'skipped (you chose not to text the vendor)';
  else if (latest.Vendor_ID) {
    try { vendorSms = await notifyVendorTemplated(env, requestDeposit ? 'vendor_estimate_approved_deposit' : 'vendor_estimate_approved', woId, latest.Vendor_ID); }
    catch (e) {
      // The approval is saved; a failed text must be visible, not swallowed.
      vendorSmsNote = 'text failed: ' + String((e && e.message) || e).slice(0, 120);
      try { await logTelemetry(env, { Source: 'worker', Job_Type: 'estimate_approve_vendor_sms_failed', Skill_Or_Endpoint: '/estimate/approve', Success: 'FALSE', Notes: ('wo=' + woId + ' ' + String((e && e.message) || e)).slice(0, 300) }); } catch (_) {}
    }
  }
  return json({ success: true, requestDeposit, vendor_sms_skipped: skipVendorSms,
    vendor_sms: vendorSmsNote || (vendorSms ? (vendorSms.sent ? 'sent' : (vendorSms.gate_snapshot || vendorSms.reason || 'not sent')) : 'no vendor') });
}

// POST /wo/deposit-approve { wo_id, vendor_id?, amount, notes? }
// Sep 15-16 2026 — Brett: regular (non-Scope-Proposal) work orders had no way to record a
// vendor deposit without either (a) using /vendor-bill/add, which auto-flips the WO to
// Complete — wrong mid-job — or (b) mentally subtracting it later, which is exactly the kind
// of after-the-fact catch this exists to prevent.
//
// CORRECTION (Sep 16): the first version of this only recorded the deposit as a Hub-side
// note and deliberately never touched QuickBooks. That was wrong — Brett pays the deposit
// himself via QuickBooks' own Instant Pay, which pays against a real Bill record, and there
// was none, so there was nothing for him to actually pay. This now creates a REAL QuickBooks
// Bill for the vendor (no customer Invoice — Brett bills the owner once, at job completion,
// for the whole job) and leaves it OPEN/unpaid for Brett to pay himself in QuickBooks — the
// Hub creates the obligation, Brett executes the actual payment, matching how a vendor bill
// half already gets created automatically elsewhere in this file (e.g. scopeProposalBook)
// while payment itself always stays a separate, human-triggered step.
// The Hub-side Work_Orders fields still exist so the FINAL bill's review card can show the
// net amount still owed (renderIRCard's deposit banner + the Deposit_Applied flip in
// approveInvoiceReview) — that part of the original design was right, just incomplete.
async function depositApprove(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const amount = parseFloat(body.amount);
  if (!Number.isFinite(amount) || amount <= 0) return json({ error: 'amount must be a positive number' }, 400);

  const wos = await fetchTab(env, 'Work_Orders');
  const wo = findWO(wos, woId);
  if (!wo) return json({ error: `No work order ${woId} found` }, 404);

  // Refuse a second deposit on top of one still outstanding (Applied !== TRUE) unless Brett
  // explicitly forces it — a duplicate-tap here is a real second QuickBooks bill, not a
  // cosmetic re-save.
  const hasOutstanding = wo.Deposit_Amount && parseFloat(wo.Deposit_Amount) > 0 && wo.Deposit_Applied !== 'TRUE';
  if (hasOutstanding && !body.force) {
    return json({
      error: `WO ${woId} already has an unapplied deposit of $${parseFloat(wo.Deposit_Amount).toFixed(2)} ` +
             `(approved ${wo.Deposit_Approved_Date || '?'}, QuickBooks bill ${wo.Deposit_QB_Bill_Number || wo.Deposit_QB_Bill_ID || '?'}). ` +
             `Clear it first (POST /wo/deposit-clear) or pass force:true to replace it.`,
      existing_amount: wo.Deposit_Amount, existing_date: wo.Deposit_Approved_Date,
    }, 409);
  }

  const vendorId = body.vendor_id || wo.Vendor_ID || '';
  if (!vendorId) return json({ error: 'No vendor on this WO and none passed — vendor_id required' }, 400);
  const vendors = await fetchTab(env, 'Vendors');
  const vendor = vendors.find(v => v.ID === vendorId);
  if (!vendor) return json({ error: `Vendor ${vendorId} not found` }, 404);

  const [properties, units] = await Promise.all([
    fetchTab(env, 'Properties').catch(() => []),
    fetchTab(env, 'Units').catch(() => []),
  ]);
  const prop = properties.find(p => String(p.ID) === String(wo.Property_ID));
  const unit = units.find(u => String(u.ID) === String(wo.Unit_ID));
  const addr = ((prop ? prop.Address : (wo.Property_Address || '')) + (unit && unit.Unit_Label ? ' ' + unit.Unit_Label : '')).trim();

  let token;
  try { token = await qbAccessToken(env); }
  catch (e) { return json({ error: 'QuickBooks auth failed, nothing was recorded: ' + e.message }, 502); }

  let vendorQbId;
  try { vendorQbId = await qbFindOrCreateVendor(env, vendor, vendor.Name || vendor.Company || vendor.First_Name || 'Vendor', token); }
  catch (e) { return json({ error: 'QuickBooks vendor lookup failed, nothing was recorded: ' + e.message }, 502); }

  const trade = QB_TRADE_MAP[(wo.Trade || '').trim()] || QB_TRADE_MAP.General;
  const desc = (`Deposit — ${addr || ('WO ' + woId)}${wo.Description ? ' — ' + wo.Description : ''}`).slice(0, 4000);
  const billPayload = {
    Line: [{ DetailType: 'AccountBasedExpenseLineDetail', Amount: +amount.toFixed(2), Description: desc,
      AccountBasedExpenseLineDetail: { AccountRef: { value: trade.expense } } }],
    VendorRef: { value: vendorQbId }, TxnDate: new Date().toISOString().slice(0, 10),
    PrivateNote: (`Deposit approved by Brett — WO ${woId} — pay via QuickBooks Instant Pay; nets against the final vendor bill at job completion.` +
                  (body.notes ? ' ' + body.notes : '')).slice(0, 1000),
  };
  const rb = await qbApi(env, 'bill?minorversion=73', 'POST', billPayload, token);
  const qbBillId = (rb && rb.Bill && rb.Bill.Id) || '';
  const qbBillNumber = (rb && rb.Bill && rb.Bill.DocNumber) || '';
  if (!qbBillId) return json({ error: 'QuickBooks bill was not created (' + (qbFault(rb) || 'unknown error') + ') — nothing was recorded, nothing to pay yet.' }, 502);

  await ensureColumns(env, 'Work_Orders', ['Deposit_Amount', 'Deposit_Vendor_ID', 'Deposit_Approved_Date', 'Deposit_Notes', 'Deposit_Applied', 'Deposit_QB_Bill_ID', 'Deposit_QB_Bill_Number']);
  await updateWOFields(env, woId, {
    Deposit_Amount: amount.toFixed(2),
    Deposit_Vendor_ID: vendorId,
    Deposit_Approved_Date: new Date().toISOString().split('T')[0],
    Deposit_Notes: body.notes || '',
    Deposit_Applied: 'FALSE',
    Deposit_QB_Bill_ID: qbBillId,
    Deposit_QB_Bill_Number: qbBillNumber,
  });
  return json({ success: true, wo_id: woId, amount: amount.toFixed(2), qb_bill_id: qbBillId, qb_bill_number: qbBillNumber });
}

// POST /wo/deposit-clear { wo_id, reason? } — undo a deposit entered in error. If a QuickBooks
// bill was already created for it, this also tries to delete that bill — but only when it's
// still unpaid (qbDeleteBillSafe refuses anything with a payment applied), so clearing the Hub
// record can never silently orphan a bill Brett already paid.
async function depositClear(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  const wos = await fetchTab(env, 'Work_Orders');
  const wo = findWO(wos, woId);
  if (!wo) return json({ error: `No work order ${woId} found` }, 404);
  if (!wo.Deposit_Amount) return json({ error: 'No deposit recorded on this WO' }, 404);

  let qbNote = '';
  if (wo.Deposit_QB_Bill_ID) {
    try {
      const token = await qbAccessToken(env);
      const del = await qbDeleteBillSafe(env, wo.Deposit_QB_Bill_ID, token);
      if (del.ok && !del.skipped) qbNote = `QuickBooks bill ${del.doc || wo.Deposit_QB_Bill_ID} deleted.`;
      else if (!del.ok) qbNote = `Hub record cleared, but the QuickBooks bill could NOT be deleted (${del.error}) — check QuickBooks directly, it may already be paid.`;
    } catch (e) { qbNote = `Hub record cleared, but clearing the QuickBooks bill failed: ${e.message} — check QuickBooks directly.`; }
  }

  await ensureColumns(env, 'Work_Orders', ['Deposit_Amount', 'Deposit_Vendor_ID', 'Deposit_Approved_Date', 'Deposit_Notes', 'Deposit_Applied', 'Deposit_QB_Bill_ID', 'Deposit_QB_Bill_Number']);
  await updateWOFields(env, woId, {
    Deposit_Amount: '', Deposit_Vendor_ID: '', Deposit_Approved_Date: '',
    Deposit_Notes: body.reason ? `Cleared: ${body.reason}` : 'Cleared', Deposit_Applied: 'FALSE',
    Deposit_QB_Bill_ID: '', Deposit_QB_Bill_Number: '',
  });
  return json({ success: true, wo_id: woId, qb_note: qbNote });
}

async function addEstimateVersion(env, body) {
  const woId = body.wo_id; if (!woId) return json({ error: 'wo_id required' }, 400);
  if (!Array.isArray(body.line_items) || !body.line_items.length) return json({ error: 'line_items required' }, 400);
  { const _blk = await bidGroupWriteBlock(env, woId, 'estimates', 'presupuestos', '/estimate'); if (_blk) return json({ error: _blk.message, code: 'bid_group_cancelled', refusal_logged: _blk.logged }, 409); }
  const existing = await fetchTab(env, 'Estimates'), priorVersions = existing.filter(e => e.WO_ID === woId);
  const nextVersion = priorVersions.length ? Math.max(...priorVersions.map(e => parseInt(e.Version||'0'))) + 1 : 1;
  const subtotal = body.line_items.reduce((sum, li) => sum + (parseFloat(li.amount)||0), 0);
  const lineItemsJson = JSON.stringify(body.line_items);

  // WO-1052, WO-1012 and WO-1062 each carry two byte-identical estimates written about a
  // second apart — a double-tap on the vendor's Submit button. Note the version counter
  // masked it: the second write read the first row and dutifully incremented 1→2, so the
  // twins look like a legitimate revision until you compare the line items. Re-submitting
  // the exact same numbers is never a real revision, so hand back the row that already
  // exists instead of appending a second one.
  // Sep 28 2026: stored Line_Items may now carry desc_en (English copy), so the stored JSON is
  // compared with desc_en stripped — the double-tap guard still matches a re-submit exactly.
  const dupe = await findRecentDuplicate(env, 'Estimates', {
    WO_ID: woId, Vendor_ID: body.vendor_id || '',
  }, 120, r => estimateLineItemsCanonical(r.Line_Items) === estimateLineItemsCanonical(lineItemsJson));
  if (dupe) return json({ success: true, duplicate: true, version: parseInt(dupe.Version || '1'), subtotal: dupe.Subtotal || subtotal.toFixed(2) });

  // Vendor text is kept exactly as written; an English copy is stored beside it (per-line desc_en
  // inside Line_Items + Change_Reason_EN) so the admin panel, owner proposal and invoice can read
  // English. Fails open — a translation miss just means no English copy (Re-translate can retry).
  const changeReason = nextVersion === 1 ? 'Initial estimate' : (body.change_reason||'Revised');
  let storedLineItems = body.line_items, changeReasonEn = '';
  try {
    const vendorRow = body.vendor_id ? (await fetchTab(env, 'Vendors').catch(() => [])).find(v => String(v.ID) === String(body.vendor_id)) : null;
    const en = await estimateEnglishFields(env, body.line_items, nextVersion === 1 ? '' : changeReason, { force: vendorWantsSpanish(vendorRow) });
    if (en.ok) { storedLineItems = en.line_items; changeReasonEn = en.change_reason_en; }
  } catch (_) {}
  const row = { WO_ID: woId, Vendor_ID: body.vendor_id||'', Version: String(nextVersion), Line_Items: JSON.stringify(storedLineItems), Subtotal: subtotal.toFixed(2), Change_Reason: changeReason, Created_By: body.created_by||'vendor', Created_Date: new Date().toISOString(), Status: body.status||'Pending' };
  if (changeReasonEn) { try { await ensureColumns(env, 'Estimates', ['Change_Reason_EN']); row.Change_Reason_EN = changeReasonEn; } catch (_) {} }
  await addRow(env, 'Estimates', row);
  try { await updateWOField(env, woId, 'Current_Estimate', subtotal.toFixed(2)); } catch(e) {}
  // Approval stage: a first/normal estimate puts the job in Estimated. A revision that arrives AFTER
  // the job was approved/proposed/signed means something changed — do NOT silently reset the stage
  // (that hides a signed job's change); flag it "revised" so Brett reviews it (change order vs
  // re-approval is his call, see FEATURE_LOG rule 200).
  try {
    const wo = findWO(await fetchTab(env, 'Work_Orders'), woId);
    const cur = String((wo && wo.Approval_Stage) || '');
    if (['Approved', 'Proposed', 'Pre-approved'].includes(cur) && nextVersion > 1) {
      try { await ensureColumns(env, 'Work_Orders', ['Approval_Stage', 'Estimate_Revised']); } catch (_) {}
      await updateWOFields(env, woId, { Estimate_Revised: 'v' + nextVersion + ' $' + subtotal.toFixed(2) + ' (' + new Date().toISOString().slice(0, 10) + ')' });
    } else {
      await setApprovalStage(env, { woId, stage: 'Estimated' });
    }
  } catch (_) {}
  // Text Brett about a vendor-posted estimate (not one he typed himself in the Hub). Best-effort.
  if (!/^(admin|hub|brett)$/i.test(String(body.created_by || ''))) {
    try {
      const c = await estimateSmsContext(env, woId, body.vendor_id);
      await sendTemplatedSms(env, { type: 'admin_estimate_new', kind: 'admin', wo_id: woId, property: c.property,
        tokens: { Kind: (c.wo && c.wo.Type === 'addon') ? (nextVersion > 1 ? 'Revised additional work' : 'Additional work') : (nextVersion > 1 ? 'Revised estimate' : 'New estimate'), WO: woId, Address: c.address, Vendor: (c.vendor && (c.vendor.Name || c.vendor.First_Name)) || body.created_by || 'a vendor', Amount: fmtMoney(subtotal) } });
    } catch (_) {}
  }
  return json({ success: true, version: nextVersion, subtotal: subtotal.toFixed(2) });
}

// Pricing constants (tier markups, admin fee, card-fee multiplier, itemized hourly/min,
// rounding) are CONFIDENTIAL and live ONLY in a private store — the Cloudflare secret
// `PRICING_CONFIG` (JSON) or the private Config-sheet row `pricing_config`. They are never
// in this public repo. Shape:
//   { "tiers": [[<maxCost>,<markupPct>,<minMarkupAmt?>], ..., [null,<markupPct>,<minMarkupAmt?>]],
//     // brackets low→high; null maxCost = "and above"; minMarkupAmt (optional, default 0) is a
//     // per-tier floor on the DOLLAR markup, e.g. 35% with a $50 minimum on small jobs.
//     "adminFee": <n>, "adminFeeThreshold": <n>,  // adminFee only applies when rawCost >= this (default 0 = always)
//     "cardFeeMult": <n>, "itemizedHourly": <n>, "itemizedMinFee": <n>,
//     "onsiteHourly": <n>, "onsiteMinFee": <n>, "passThroughFlat": <n>, "roundTo": <n> }
// Unset → null → pricing SUGGESTIONS/estimates are dormant; manual invoicing still works.
async function getPricingConfig(env) {
  try { if (env && env.PRICING_CONFIG) return JSON.parse(env.PRICING_CONFIG); } catch(_) {}
  try { const cfg = await fetchConfig(env); if (cfg && cfg.pricing_config) return JSON.parse(cfg.pricing_config); } catch(_) {}
  return null;
}
// Pure, config-driven — no constants baked in. Returns null if pricing isn't configured.
// Aug 18 2026: added per-tier minMarkupAmt (dollar floor on markup, e.g. Brett's "$50 minimum"
// on the up-to-$1000 tier) and adminFeeThreshold (admin fee only kicks in above a cost
// threshold, e.g. "$85 admin on $3000+" — previously adminFee applied unconditionally to
// every job, which nothing had actually shipped with yet since PRICING_CONFIG had never been
// set). Neither changes behavior for a tier/config that doesn't use them (minMarkupAmt/
// adminFeeThreshold both default to 0, i.e. "no floor" / "always applies", matching the old
// formula exactly) — this mirror MUST stay in sync with index.html's copy of this function.
function calcTieredEstimate(rawCost, pc) {
  if (!pc || !Array.isArray(pc.tiers) || !pc.tiers.length) return null;
  const cost = parseFloat(rawCost) || 0;
  let tier = pc.tiers[pc.tiers.length-1];
  for (const t of pc.tiers) { if (t[0] === null || cost <= t[0]) { tier = t; break; } }
  const pct = tier[1], minMarkup = tier[2] || 0;
  const markup = Math.max(cost * pct, minMarkup);
  const round = pc.roundTo || 5, fee = (pc.cardFeeMult != null ? pc.cardFeeMult : 1);
  const admin = (cost >= (pc.adminFeeThreshold || 0)) ? (pc.adminFee || 0) : 0;
  const stepA=cost+markup, stepB=stepA+admin, stepC=stepB*fee, finalPrice=Math.ceil(stepC/round)*round, deposit=finalPrice/2;
  return { rawCost:cost, markupPct:pct, markupAmt:+markup.toFixed(2), stepA:+stepA.toFixed(2), stepB:+stepB.toFixed(2), stepC:+stepC.toFixed(2), finalPrice:+finalPrice.toFixed(2), deposit:+deposit.toFixed(2) };
}

// ── LOCATION / CLUSTER ───────────────────────────────────────

async function listNearbyWOs(env, url) {
  const woId = url.searchParams.get('wo_id')||'', vendorId = url.searchParams.get('vendor_id')||'';
  if (!woId) return json({ error: 'wo_id required' }, 400);
  const [wos, props, tenants] = await fetchTabs(env, ['Work_Orders','Properties','Tenants']);
  const wo = wos.find(w => w.ID === woId); if (!wo) return json({ error: 'WO not found' }, 404);
  const prop = props.find(p => String(p.ID) === String(wo.Property_ID)); if (!prop) return json({ nearby: [], message: 'Property not found' });
  const primary = (prop.Location_Cluster||'').trim(), overlap = (prop.Location_Overlap||'').split(',').map(s=>s.trim()).filter(Boolean), allTags = [primary, ...overlap].filter(Boolean);
  if (!allTags.length) return json({ nearby: [], message: 'no_tags', primary_cluster: null });
  const nearbyPropIds = new Set();
  props.forEach(p => { if (String(p.ID) === String(wo.Property_ID)) return; const pTags = [(p.Location_Cluster||'').trim(), ...(p.Location_Overlap||'').split(',').map(s=>s.trim())].filter(Boolean); if (pTags.some(t => allTags.includes(t))) nearbyPropIds.add(String(p.ID)); });
  if (!nearbyPropIds.size) return json({ nearby: [], message: 'no_nearby', primary_cluster: primary });
  const OPEN = new Set(WOStatus.sets.FIELD_OPEN);
  const nearby = wos.filter(w => w.ID !== woId && w.Voided !== 'TRUE' && nearbyPropIds.has(String(w.Property_ID)) && OPEN.has(w.Status) && (!vendorId || w.Vendor_ID === vendorId)).map(w => { const wProp = props.find(p => String(p.ID) === String(w.Property_ID)), t = tenants.find(t => String(t.ID) === String(w.Tenant_ID)); return { id: w.ID, property_id: w.Property_ID, address: (wProp&&wProp.Address)||'', city: (wProp&&wProp.City)||'', description: w.Description, trade: w.Trade, priority: w.Priority, status: w.Status, vendor_id: w.Vendor_ID, tenant_name: t ? `${t.First_Name||''} ${t.Last_Name||''}`.trim() : '', tenant_phone: isTenantCurrent(t) ? (t.Phone||'') : '' }; });
  return json({ nearby, primary_cluster: primary, overlap_clusters: overlap });
}

async function geocodeProperty(env, body) {
  if (!env.GOOGLE_MAPS_KEY) return json({ error: 'GOOGLE_MAPS_KEY not set' }, 500);
  const address = (body.address||'').trim(); if (!address) return json({ error: 'address required' }, 400);
  const r = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${env.GOOGLE_MAPS_KEY}`);
  const d = await r.json(); if (d.status !== 'OK' || !d.results.length) return json({ error: 'Geocoding failed: '+d.status }, 400);
  const loc = d.results[0].geometry.location; return json({ success: true, lat: loc.lat, lng: loc.lng, formatted: d.results[0].formatted_address });
}

async function clusterSuggestions(env, url) {
  const lat = parseFloat(url.searchParams.get('lat')), lng = parseFloat(url.searchParams.get('lng')), maxKm = parseFloat(url.searchParams.get('max_km')||'2.5');
  if (isNaN(lat)||isNaN(lng)) return json({ error: 'lat and lng required' }, 400);
  const props = await fetchTab(env, 'Properties'), tagged = props.filter(p => p.Location_Cluster && p.Lat && p.Lng);
  if (!tagged.length) return json({ suggestions: { primary: null, overlap: [] }, nearby: [], message: 'No tagged properties with coordinates yet' });
  function haversineKm(lat1,lng1,lat2,lng2) { const R=6371,d2r=Math.PI/180,dLat=(lat2-lat1)*d2r,dLng=(lng2-lng1)*d2r,a=Math.sin(dLat/2)**2+Math.cos(lat1*d2r)*Math.cos(lat2*d2r)*Math.sin(dLng/2)**2; return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)); }
  const nearby = tagged.map(p => ({ id:p.ID, address:p.Address, cluster:p.Location_Cluster, overlap:p.Location_Overlap, dist_km:haversineKm(lat,lng,parseFloat(p.Lat),parseFloat(p.Lng)) })).filter(p => p.dist_km<=maxKm).sort((a,b)=>a.dist_km-b.dist_km);
  const counts={}; nearby.slice(0,5).forEach(p => { counts[p.cluster]=(counts[p.cluster]||0)+1; });
  const primary = Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||null;
  const overlapSet=new Set(); nearby.filter(p=>p.dist_km>0.4).forEach(p => { if(p.cluster!==primary) overlapSet.add(p.cluster); (p.overlap||'').split(',').forEach(o=>{ const t=o.trim(); if(t&&t!==primary) overlapSet.add(t); }); });
  return json({ suggestions: { primary, overlap: [...overlapSet].slice(0,4) }, nearby });
}

async function savePropertyClusters(env, body) {
  const { property_id, cluster, overlap, lat, lng } = body; if (!property_id) return json({ error: 'property_id required' }, 400);
  const data = await sheetsRequest(env, 'GET', '/values/Properties'); const rows = data.values||[]; if (rows.length<2) return json({ error: 'Properties tab empty' }, 500);
  const headers = rows[0], idCol = headers.indexOf('ID'), needed = ['Location_Cluster','Location_Overlap','Lat','Lng'], missing = needed.filter(n=>headers.indexOf(n)===-1);
  if (missing.length) return json({ error: `Add these columns to Properties tab: ${missing.join(', ')}`, missing }, 400);
  const rowIdx = rows.findIndex((r,i)=>i>0&&String(r[idCol])===String(property_id)); if (rowIdx===-1) return json({ error: 'Property not found: '+property_id }, 404);
  const sheetRow = rowIdx+1, colFn = n => n<26?String.fromCharCode(65+n):'A'+String.fromCharCode(65+n-26), updates=[];
  if (cluster!==undefined) updates.push({ range:`Properties!${colFn(headers.indexOf('Location_Cluster'))}${sheetRow}`, values:[[cluster||'']] });
  if (overlap!==undefined) updates.push({ range:`Properties!${colFn(headers.indexOf('Location_Overlap'))}${sheetRow}`, values:[[Array.isArray(overlap)?overlap.join(','):(overlap||'')]] });
  if (lat!==undefined) updates.push({ range:`Properties!${colFn(headers.indexOf('Lat'))}${sheetRow}`, values:[[String(lat)]] });
  if (lng!==undefined) updates.push({ range:`Properties!${colFn(headers.indexOf('Lng'))}${sheetRow}`, values:[[String(lng)]] });
  if (!updates.length) return json({ success:true, message:'Nothing to update' });
  await sheetsRequest(env, 'POST', '/values:batchUpdate', { valueInputOption:'RAW', data:updates }); return json({ success:true });
}

// ── KEY REGISTRY IMPORTER ────────────────────────────────────

async function importKeyRegistry(env, body) {
  const registryId = env.KEY_REGISTRY_SHEET_ID; if (!registryId) return json({ error: 'KEY_REGISTRY_SHEET_ID not set' }, 500);
  const token = await getAccessToken(env);
  const regResp = await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${registryId}/values/Sheet1`, { headers: { 'Authorization': `Bearer ${token}` } });
  const regData = await regResp.json(); if (regData.error) return json({ error: `Key Registry read error: ${regData.error.message}` }, 400);
  const regRows = regData.values||[]; if (regRows.length<2) return json({ error: 'Key Code Registry appears empty' }, 400);
  const rH = regRows[0];
  const iAddr=rH.findIndex(h=>h.toLowerCase().includes('property')), iUnit=rH.findIndex(h=>h.toLowerCase()==='unit'), iCode=rH.findIndex(h=>h.toLowerCase().includes('key code')||h.toLowerCase()==='key code');
  const iLoc=rH.findIndex(h=>h.toLowerCase().includes('lock box location')||h.toLowerCase().includes('location')), iDate=rH.findIndex(h=>h.toLowerCase().includes('as of')||h.toLowerCase().includes('date'));
  const iMailbox=rH.findIndex(h=>h.toLowerCase().includes('mail')), iNotes=rH.findIndex(h=>h.toLowerCase()==='notes');
  if (iAddr===-1||iUnit===-1) return json({ error: `Could not find address/unit columns. Found: ${rH.join(', ')}` }, 400);
  const [props,units,keysTabData] = await Promise.all([fetchTab(env,'Properties'), fetchTab(env,'Units'), sheetsRequest(env,'GET','/values/Keys')]);
  const keysHeaders = (keysTabData.values&&keysTabData.values[0])||['ID','Property_ID','Unit_ID','Key_Type','Key_Code','Lockbox_Code','Location','Notes','Possession_Status','Active'];
  let nextId = (keysTabData.values||[]).slice(1).reduce((max,r)=>{ const n=parseInt(r[keysHeaders.indexOf('ID')]||'0'); return n>max?n:max; },0)+1;
  function matchProp(addr) { if(!addr)return null; const a=addr.toLowerCase().trim().replace(/[.,]/g,''); return props.find(p=>{ const pa=(p.Address||'').toLowerCase().trim().replace(/[.,]/g,''); return pa===a||pa.startsWith(a.split(' ').slice(0,3).join(' '))||a.startsWith(pa.split(',')[0]); }); }
  function matchUnit(prop,unitLabel) { if(!prop||!unitLabel)return null; const ul=unitLabel.toLowerCase().trim().replace(/apt\.?\s*/i,'apt ').replace(/\s+/g,' '); return units.find(u=>{ if(String(u.Property_ID)!==String(prop.ID))return false; const hl=(u.Unit_Label||'').toLowerCase().trim().replace(/apt\.?\s*/i,'apt ').replace(/\s+/g,' '); return hl===ul||hl.replace(/\s/g,'')===ul.replace(/\s/g,''); }); }
  function inferKeyType(u) { const l=(u||'').toLowerCase().trim(); if(l==='fd'||l.includes('front door'))return 'Building-FrontDoorKey'; if(l.includes('ridge')&&l.includes('lock'))return 'Building-Lockbox'; if(l==='lock box'||l==='lockbox')return 'Building-Lockbox'; if(l.includes('mailbox')||l.includes('mail box'))return 'Unit-MailboxKey'; if(l.includes('gate'))return 'Building-GateCode'; if(l.match(/^apt|^unit/i))return 'Unit-Key'; return 'Building-CustomKey'; }
  function isUnitSpecific(u) { return !!(u||'').match(/^apt|^unit/i); }
  const preview=body.preview!==false, mapped=[], skipped=[];
  for (let i=1;i<regRows.length;i++) {
    const row=regRows[i], addr=(iAddr>=0?row[iAddr]:'')||'', unitCol=(iUnit>=0?row[iUnit]:'')||'', code=(iCode>=0?row[iCode]:'')||'';
    const loc=(iLoc>=0?row[iLoc]:'')||'', asOf=(iDate>=0?row[iDate]:'')||'', mailbox=(iMailbox>=0?row[iMailbox]:'')||'', notes=(iNotes>=0?row[iNotes]:'')||'';
    if (!addr&&!unitCol&&!code) continue;
    const prop=matchProp(addr); if (!prop) { skipped.push({ row:i+1,addr,unitCol,reason:'Property not found in hub' }); continue; }
    const keyType=inferKeyType(unitCol); let unitId='',unitLabel='';
    if (isUnitSpecific(unitCol)) { const unit=matchUnit(prop,unitCol); if(unit){unitId=unit.ID;unitLabel=unit.Unit_Label;}else{unitLabel=unitCol;} }
    mapped.push({ property_id:prop.ID,property_address:prop.Address,unit_id:unitId,unit_label:unitLabel||unitCol,key_type:keyType,key_code:code,location:loc,notes:[notes,mailbox?'Mailbox: '+mailbox:'',asOf?'As of: '+asOf:''].filter(Boolean).join(' | '),source_row:i+1 });
  }
  if (preview) return json({ preview:true,total:mapped.length,skipped:skipped.length,rows:mapped,skippedRows:skipped });
  const now=new Date().toISOString();
  const newRows=mapped.map(m=>{ const row=Array(keysHeaders.length).fill(''); function set(c,v){const i=keysHeaders.indexOf(c);if(i>=0)row[i]=v;} set('ID',String(nextId++));set('Property_ID',String(m.property_id));set('Unit_ID',String(m.unit_id));set('Key_Type',m.key_type);set('Key_Code',m.key_code);set('Lockbox_Code',m.key_code);set('Location',m.location);set('Lockbox_Location',m.location);set('Notes',m.notes);set('Possession_Status','Have It');set('Active','TRUE');set('Added_Date',now); return row; });
  await sheetsRequest(env,'POST','/values/Keys:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',{ values:newRows });
  return json({ success:true,imported:newRows.length,skipped:skipped.length });
}

// ── ESTIMATE TEXT GENERATION ─────────────────────────────────

async function generateEstimateText(env, body) {
  if (!env.ANTHROPIC_API_KEY) return json({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  const { property_address, issues, line_items, wo_id } = body;
  if (!property_address||!issues) return json({ error: 'property_address and issues required' }, 400);
  if (!Array.isArray(line_items)||!line_items.length) return json({ error: 'line_items required' }, 400);
  const rawCost = line_items.reduce((sum,li)=>sum+(parseFloat(li.amount)||0),0);
  const _pc = await getPricingConfig(env);
  if (!_pc) return json({ error: 'Pricing not configured — set PRICING_CONFIG (Cloudflare secret) or the Config sheet `pricing_config` row.' }, 400);
  const pricing = calcTieredEstimate(rawCost, _pc);
  let includeIntegrityClause=false;
  if (wo_id) { try { const all=await fetchTab(env,'Estimates'); const versions=all.filter(e=>e.WO_ID===wo_id).sort((a,b)=>parseInt(a.Version||'1')-parseInt(b.Version||'1')); if(versions.length){const firstItems=JSON.parse(versions[0].Line_Items||'[]'); if(firstItems.length>1&&line_items.length<firstItems.length) includeIntegrityClause=true;} } catch(e){} }
  const itemsList=line_items.map(li=>`- ${englishOnly(li.desc_en || li.desc)}`).join('\n');   // owner-facing text is English (Sep 28 2026): desc_en when the vendor wrote Spanish
  const integrityClauseText=includeIntegrityClause?'\n- Estimate Integrity Clause: This estimate is priced as a single, unified project based on current mobilization efficiencies. If individual line items are selectively removed or declined by the client, any remaining approved items are subject to a 15% price adjustment plus a $150 travel/mobilization fee.':'';
  // Standing policy (Aug 21 2026, Brett) — same boilerplate as scopeProposal()'s doc: standalone/
  // partial-scope pricing is best-efforts, not fixed, since the combined price absorbs unknowns a
  // lone item doesn't share. Distinct from the punitive Integrity Clause above (which only fires
  // when items are dropped from an already-multi-versioned estimate) — this applies universally.
  const partialScopeClauseText='\n- If only part of this scope is approved or completed instead of the full project, pricing for those individual items is a best-efforts estimate, not a fixed quote: the combined price is built to absorb the small unknowns of doing larger and smaller tasks together in one visit, and a standalone item doesn\'t get that same cushion — its actual final cost may run higher than estimated once that work is underway on its own.';
  const prompt=`You are a property maintenance estimate writer. Rewrite the following raw, messy scope-of-work items into a polished, professional, scannable bulleted list. Correct all typos, slang, and grammar. The output is for an English-speaking property owner: if any item or the issue description is in Spanish, write it in English. Group related items under bold category headers where it makes sense.\n\nProperty: ${property_address}\nRaw issue description: ${issues}\nRaw line items:\n${itemsList}\n\nReturn ONLY the rewritten "Scope of Work:" bulleted section — clean Markdown, no emojis, no preamble, no other sections. Do not include any dollar amounts or pricing.`;
  try {
    const { data }=await anthropicMessages(env,{ model:'claude-sonnet-4-6', max_tokens:800, messages:[{role:'user',content:prompt}] },{ source:'generateEstimateText' });
    const scopeText=data.content?.[0]?.text?.trim()||''; if (!scopeText) return json({ error:'Claude returned empty response',detail:data }, 500);
    const doc=`${property_address}\n\n${scopeText}\n\nFinancial Terms:\n\nTotal Estimated Cost: $${pricing.finalPrice.toFixed(2)}\nRequired 50% Deposit: $${pricing.deposit.toFixed(2)}\n\nPayment & Project Terms:\n\n- A 50% electronic deposit is required to approve this estimate and schedule the work.\n- All deposits and final invoices must be paid electronically. Physical checks are not accepted.`+partialScopeClauseText+integrityClauseText;
    return json({ success:true, text:doc, pricing:{ finalPrice:pricing.finalPrice, deposit:pricing.deposit } });
  } catch(e) { if (aiCreditIsPausedError(e)) return aiCreditPausedJson({ message: 'Automatic estimate wording is paused - type the scope text by hand.' }); return json({ error:e.message }, 500); }
}
// ── WO AUDIT ─────────────────────────────────────────────────

async function logWOAudit(env, woId, changedBy, changedByRole, field, oldValue, newValue, notes='') {
  return logWOAuditMany(env, [{ woId, changedBy, changedByRole, field, oldValue, newValue, notes }]);
}

// Batched version — one GET (to find the next ID) + one multi-row append covering ALL
// entries, instead of a GET+POST pair per field. adminUpdateWO/ownerUpdateWO/tenant-access
// updates were each calling logWOAudit once PER CHANGED FIELD in a loop, which used to mean
// N re-reads of the SAME WO_Audit tab for one save (each read racing the one the previous
// loop iteration had just written seconds — sometimes milliseconds — earlier). This is one of
// the concrete contributors to the "quota exceeded" error Brett hit after an ordinary WO edit.
// Message-audit columns (Sep 20 2026) — added to WO_Audit so every outbound SMS/email tied to a
// WO logs recipient/channel/full-text/outcome alongside the existing field-edit history, not
// just a 100-char truncated Notes string (see the old Tenant_Manual_SMS precedent). Additive
// only — self-provisioned lazily below, existing field-edit-only callers never touch these.
const WO_AUDIT_MSG_COLS = ['Channel', 'Recipient_Name', 'Recipient_Type', 'Message_Type', 'Message_Body', 'Outcome', 'Original_Body', 'Translated_To'];

async function logWOAuditMany(env, entries) {
  if (!entries || !entries.length) return;
  try {
    if (entries.some(e => e.channel || e.messageType || e.messageBody || e.originalBody)) {
      try { await ensureColumns(env, 'WO_Audit', WO_AUDIT_MSG_COLS); } catch (e) {}
    }
    const data = await sheetsRequest(env, 'GET', `/values/WO_Audit`);
    const rows = data.values||[]; if (!rows.length) return;
    const headers = rows[0], now = new Date().toISOString();
    let nextId = nextSafeId(rows);
    const newRows = entries.map(e => {
      const row = headers.map(h => ({
        ID:String(nextId), WO_ID:e.woId||'', Changed_By:e.changedBy||'unknown', Changed_By_Role:e.changedByRole||'unknown',
        Field:e.field||'', Old_Value:String(e.oldValue??''), New_Value:String(e.newValue??''), Timestamp:now, Notes:e.notes||'',
        Channel:e.channel||'', Recipient_Name:e.recipientName||'', Recipient_Type:e.recipientType||'',
        Message_Type:e.messageType||'', Message_Body:e.messageBody||'', Outcome:e.outcome||'',
        Original_Body:e.originalBody||'', Translated_To:e.translatedTo||'',
      }[h]??''));
      nextId += 1;
      return row;
    });
    await sheetsRequest(env, 'POST', `/values/WO_Audit:append?valueInputOption=RAW`, { values:newRows });
  } catch(e) { /* never break main operation */ }
}

// Thin wrapper matching logWOAudit's shape, for the message-send call sites (smsGatedSend,
// sendVendorInvoiceConfirmationEmail) instead of the field-edit shape.
async function logMessageAudit(env, { woId, changedBy, changedByRole, channel, recipientName, recipientType, messageType, messageBody, outcome, notes, originalBody, translatedTo }) {
  return logWOAuditMany(env, [{
    woId, changedBy: changedBy || 'System', changedByRole: changedByRole || 'system',
    field: channel === 'email' ? 'Email' : 'SMS', oldValue: '', newValue: '',
    notes: notes || '', channel, recipientName, recipientType, messageType, messageBody, outcome, originalBody, translatedTo,
  }]);
}

async function getWOAudit(env, url) {
  const woId = url.searchParams.get('wo_id'); if (!woId) return json({ error: 'Missing wo_id' }, 400);
  try {
    const audit = await fetchTab(env, 'WO_Audit');
    return json(audit.filter(a => a.WO_ID === woId).sort((a,b) => new Date(a.Timestamp)-new Date(b.Timestamp)));
  } catch(e) { return json([]); }
}

async function translateToEnglish(env, text) {
  if (!env.ANTHROPIC_API_KEY) return text;
  try {
    const { data } = await anthropicMessages(env, { model:'claude-sonnet-4-6', max_tokens:400, messages:[{role:'user',content:`Translate the following from Spanish to English. Return only the translation, nothing else:\n\n${text}`}] }, { source:'translateToEnglish' });
    return data.content?.[0]?.text?.trim() || text;
  } catch(e) { await aiFailOpenNote(env, 'translateToEnglish', e); return text; }
}

// Generic one-shot translation used by the Shareable WO (B-117) to show the vendor the job
// details in Spanish. Keeps proper nouns / addresses / codes intact; returns the source
// text unchanged on any miss so a translation outage never blanks the work order.
// opts (optional, Sep 28 2026): { preserve:true } appends the link/PIN/amount-preservation rules,
// { html:true } tells the model the input is HTML, { max_tokens } raises the default 600.
async function translateText(env, text, fromLabel, toLabel, opts) {
  if (!env.ANTHROPIC_API_KEY || !text || !String(text).trim()) return text;
  try {
    const extra = (opts && opts.preserve ? ' ' + VENDOR_TRANSLATE_PRESERVE : '') + (opts && opts.html ? ' The input is HTML: keep every tag, attribute and link exactly as-is and translate only the visible text.' : '');
    const { data } = await anthropicMessages(env, { model:'claude-sonnet-4-6', max_tokens:(opts && opts.max_tokens) || 600, messages:[{role:'user',content:`Translate the following from ${fromLabel} to ${toLabel}. Keep addresses, proper names, phone numbers and door/lock codes exactly as written.${extra} Return only the translation, nothing else:\n\n${text}`}] }, { source:'translateText' });
    return data.content?.[0]?.text?.trim() || text;
  } catch(e) { await aiFailOpenNote(env, 'translateText', e); return text; }
}

// ── VENDOR TRANSLATION (Sep 28 2026, feat/vendor-translation-send-to-vendor) ────────────────────
// Outbound: everything the Hub sends a vendor whose Vendors.Language is 'es' goes out in Spanish
// (English original kept in Message_Queue / WO_Audit). Inbound: vendor-written estimate text is
// kept as written and an English copy is stored beside it (desc_en / Change_Reason_EN), so Brett,
// the owner proposal and the invoice all read English. Every helper here FAILS OPEN — on any miss
// (no API key, timeout, bad model output, a link/PIN/amount that did not survive) the ORIGINAL
// text is used and the send/save is never blocked.
const VENDOR_TRANSLATE_PRESERVE = 'Keep every URL, link, phone number, PIN, door/lock code, work order id (like WO-1234, [1234] or 1234), "Ref:" reference, dollar amount, date, time, address and proper name EXACTLY as written — never translate, reformat, drop or add them. Keep line breaks. Add no commentary.';

function vendorWantsSpanish(vendor) { return !!vendor && String(vendor.Language || '').trim().toLowerCase() === 'es'; }

// Tokens that must appear, byte-for-byte, in a translation of `text` (links, $ amounts, 4+ digit
// runs such as phone numbers / PINs / ids). If the model dropped or altered one, the translation
// is discarded and the English original is sent instead.
function extractPreservedTokens(text) {
  const s = String(text || ''), toks = new Set();
  (s.match(/https?:\/\/[^\s<>"')\]]+/gi) || []).forEach(u => toks.add(u.replace(/[.,;:!?]+$/, '')));
  (s.match(/\$\s?\d[\d,]*(?:\.\d+)?/g) || []).forEach(d => toks.add(d.replace(/\s+/g, '')));
  (s.match(/\b\d{4,}\b/g) || []).forEach(n => toks.add(n));
  (s.match(/\bPIN:?\s*([A-Za-z0-9]{4,})/gi) || []).forEach(m => toks.add(m.replace(/^PIN:?\s*/i, '')));
  return Array.from(toks);
}
function preservedTokensIntact(original, translated) {
  const out = String(translated || ''), flat = out.replace(/\s+/g, '');
  return extractPreservedTokens(original).every(t => out.includes(t) || flat.includes(t.replace(/\s+/g, '')));
}
function htmlTagSkeleton(html) { return (String(html || '').match(/<\/?[a-zA-Z][^>]*>/g) || []).map(t => t.replace(/\s+/g, ' ')).join('|'); }

// Cheap "is this probably Spanish?" test so English-only estimates never cost a model call.
function plausiblyNonEnglish(text) {
  const s = String(text || '');
  if (!s.trim()) return false;
  if (/[áéíóúñüÁÉÍÓÚÑÜ¿¡]/.test(s)) return true;
  const stop = new Set(['el','la','los','las','de','del','para','con','por','una','un','y','se','que','en','es','hay','muy','pero','como','hacer','trabajo','materiales','instalacion','reparacion','cambiar','pintura','mano','obra','bano','cocina','puerta','ventana','tuberia','agua','luz','piso','pared','techo','lavabo','inodoro','llave','arreglar','limpieza','servicio','cotizacion','incluye','pintar','reemplazar','colocar','poner','quitar','tubo','fuga','falta']);
  const words = s.toLowerCase().match(/[a-z]+/g) || [];
  let hits = 0; for (const w of words) if (stop.has(w)) hits++;
  return hits >= 2 || (words.length <= 3 && hits >= 1);
}

// "[ES] original [EN] english" (the tag pattern vendor notes / bills / receipts are stored in) →
// the English part. Untagged text is returned unchanged. Used everywhere text is customer-facing.
function englishOnly(text) {
  const s = String(text == null ? '' : text);
  const m = s.match(/\[EN\]\s*([\s\S]*)$/);
  if (m && m[1].trim()) return m[1].trim();
  return s.replace(/^\[ES\]\s*/, '');
}

// Direct-Anthropic translation. Batch of short strings → same-length array; ok:false on any miss.
async function translateBatchToEnglish(env, strings) {
  const arr = (strings || []).map(s => String(s == null ? '' : s));
  const idx = arr.map((s, i) => s.trim() ? i : -1).filter(i => i >= 0);
  if (!idx.length) return { ok: true, out: arr, called: false };
  if (!env.ANTHROPIC_API_KEY) return { ok: false, out: arr, error: 'no_api_key' };
  let timer;
  try {
    const ctrl = new AbortController(); timer = setTimeout(() => ctrl.abort(), 20000);
    const prompt = 'Below is a JSON array of short texts a property-maintenance contractor wrote for an estimate. Translate every item that is in Spanish (or any non-English language) into natural, plain English; return items that are already English EXACTLY unchanged. Keep dollar amounts, numbers, addresses, names and units exactly as written. Return ONLY a JSON array of strings, same length and same order, no commentary.\n\n' + JSON.stringify(idx.map(i => arr[i]));
    const { data } = await anthropicMessages(env, { model: 'claude-sonnet-4-6', max_tokens: 1500, messages: [{ role: 'user', content: prompt }] }, { signal: ctrl.signal, source: 'translateBatchToEnglish' });
    const txt = (data && data.content && data.content[0] && data.content[0].text) || '';
    const m = txt.match(/\[[\s\S]*\]/);
    const parsed = m ? JSON.parse(m[0]) : null;
    if (!Array.isArray(parsed) || parsed.length !== idx.length) return { ok: false, out: arr, error: 'bad_response' };
    const out = arr.slice();
    idx.forEach((i, k) => { if (typeof parsed[k] === 'string' && parsed[k].trim()) out[i] = parsed[k].trim(); });
    return { ok: true, out, called: true };
  } catch (e) { return Object.assign({ ok: false, out: arr, error: String((e && e.message) || e) }, aiCreditIsPausedError(e) ? { paused: true, code: AI_CREDIT_CODE } : {}); }
  finally { if (timer) clearTimeout(timer); }
}

// Estimate → English. Each line keeps its original `desc`; `desc_en` is added only when the
// English differs. `force` (the Re-translate button) sends every non-blank text to the model;
// otherwise only text that looks non-English is sent (no cost for English estimates).
async function estimateEnglishFields(env, lineItems, changeReason, opts) {
  const force = !!(opts && opts.force);
  const items = (Array.isArray(lineItems) ? lineItems : []).map(li => Object.assign({}, li));
  const texts = items.map(li => String((li && li.desc) || '')).concat([String(changeReason || '')]);
  const pick = texts.map((t, i) => (t.trim() && (force || plausiblyNonEnglish(t))) ? i : -1).filter(i => i >= 0);
  if (!pick.length) return { line_items: items, change_reason_en: '', ok: true, called: false };
  const r = await translateBatchToEnglish(env, pick.map(i => texts[i]));
  const en = texts.slice(); pick.forEach((i, k) => { en[i] = r.out[k]; });
  const norm = s => String(s || '').trim().toLowerCase();
  items.forEach((li, i) => {
    if (pick.indexOf(i) === -1) return;
    if (r.ok && en[i] && norm(en[i]) !== norm(texts[i])) li.desc_en = en[i]; else if (force && r.ok) delete li.desc_en;
  });
  const last = texts.length - 1;
  const crEn = (pick.indexOf(last) !== -1 && r.ok && norm(en[last]) !== norm(texts[last])) ? en[last] : '';
  return { line_items: items, change_reason_en: crEn, ok: r.ok, called: true, error: r.error };
}

// Pure helper any downstream consumer (owner proposal, invoice, push-to-scope) calls to get the
// English view of an estimate's lines — desc_en when present, else desc (with any [ES]/[EN] tags
// resolved). `desc_orig` carries the vendor's own wording when it differs.
function estimateLinesEnglish(estimateOrLines) {
  let lines = estimateOrLines;
  if (estimateOrLines && !Array.isArray(estimateOrLines)) { try { lines = JSON.parse(estimateOrLines.Line_Items || '[]'); } catch (_) { lines = []; } }
  return (Array.isArray(lines) ? lines : []).map(li => {
    const orig = String((li && li.desc) || '');
    const en = englishOnly((li && li.desc_en) || orig);
    return Object.assign({}, li, { desc: en, desc_orig: en !== orig ? orig : undefined });
  });
}

// English → Spanish for a vendor recipient. Returns {text, original, translated, lang, skipped_reason}.
// Only vendors with Language==='es' are ever translated. opts: {already_localized, html, max_tokens}.
async function translateForVendorDetailed(env, vendor, text, opts) {
  const original = String(text == null ? '' : text);
  const wantsEs = vendorWantsSpanish(vendor);
  const lang = wantsEs ? 'es' : 'en';
  if (!wantsEs || !original.trim() || (opts && opts.already_localized)) return { text: original, original, translated: false, lang };
  try {
    const out = await translateText(env, original, 'English', 'Spanish', { preserve: true, html: !!(opts && opts.html), max_tokens: (opts && opts.max_tokens) || 1200 });
    if (!out || !String(out).trim() || out === original) return { text: original, original, translated: false, lang, skipped_reason: 'unchanged_or_unavailable' };
    if (!preservedTokensIntact(original, out)) return { text: original, original, translated: false, lang, skipped_reason: 'preservation_check_failed' };
    if (opts && opts.html && htmlTagSkeleton(original) !== htmlTagSkeleton(out)) return { text: original, original, translated: false, lang, skipped_reason: 'html_structure_changed' };
    return { text: String(out), original, translated: true, lang };
  } catch (e) { return { text: original, original, translated: false, lang, skipped_reason: 'error' }; }
}
async function translateForVendor(env, vendor, text, opts) { return (await translateForVendorDetailed(env, vendor, text, opts)).text; }

// Vendor EMAIL (subject + HTML body). Subject and body are translated separately; either falls back
// to English independently. Use at every gmailSendEmail call whose recipient is a vendor unless the
// body is already hand-built bilingual (pass already_localized:true).
async function translateVendorEmail(env, vendor, { subject, html, already_localized }) {
  if (already_localized || !vendorWantsSpanish(vendor)) return { subject, html, translated: false, original_subject: subject, original_html: html };
  const s = await translateForVendorDetailed(env, vendor, subject, { max_tokens: 200 });
  const h = await translateForVendorDetailed(env, vendor, html, { html: true, max_tokens: 3000 });
  return { subject: s.text, html: h.text, translated: s.translated || h.translated, original_subject: subject, original_html: html };
}

// ── WO NOTES ─────────────────────────────────────────────────

async function addWONote(env, body) {
  if (!body.wo_id || !body.note) return json({ error: 'Missing wo_id or note' }, 400);
  const workorders = await fetchTab(env, 'Work_Orders');
  const wo = findWO(workorders, body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  if (body.author_role === 'owner' && body.owner_id) {
    const properties = await fetchTab(env, 'Properties');
    const prop = properties.find(p => p.ID === wo.Property_ID);
    if (!prop || prop.Owner_ID !== body.owner_id) return json({ error: 'Unauthorized' }, 403);
  }
  let noteText = body.note;
  if (body.author_role === 'vendor' && body.vendor_id) {
    const allVendors = await fetchTab(env, 'Vendors'), noteVendor = allVendors.find(v => v.ID === body.vendor_id);
    if (noteVendor?.Language === 'es') { const en = await translateToEnglish(env, noteText); if (en && en !== noteText) noteText = `[ES] ${noteText}\n[EN] ${en}`; }
  }
  const ts = new Date().toLocaleString('en-US', { timeZone:'America/New_York', month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit' });
  const attribution = `[${ts} — ${body.author||'Unknown'} (${body.author_role||'unknown'})]`;
  const newNotes = wo.Notes ? `${wo.Notes}\n${attribution} ${noteText}` : `${attribution} ${noteText}`;
  await updateWOFields(env, body.wo_id, { Notes: newNotes });
  await logWOAudit(env, body.wo_id, body.author, body.author_role, 'Notes', wo.Notes||'', noteText.substring(0,100), 'Note appended');

  // Sep 16 2026 (Brett): the tenant portal's note box has said "Sent to your property manager"
  // since it shipped, but nothing ever actually notified anyone — same false-promise shape as
  // the SMS wording fixed earlier today. This makes that line true: a real-time admin ping,
  // matching every other "Brett gets pinged" pattern already in this file (handleInboundSMS's
  // vendor-reply relay, the vendor-nudge flagged-to-Brett alert) — plain sendSMS, not the gated
  // tenant/owner/vendor pipeline, since this is an internal alert to Brett's own number, not a
  // customer-facing message subject to Test Mode/toggles.
  if (body.author_role === 'tenant') {
    try {
      const config = await fetchConfig(env);
      if (config.admin_phone) {
        const noteProperties = await fetchTab(env, 'Properties');
        const noteWOProp = noteProperties.find(p => p.ID === wo.Property_ID);
        const noteAddr = noteWOProp ? noteWOProp.Address : wo.Property_ID;
        await sendSMS(env, config.admin_phone, `💬 ${body.author||'A tenant'} left a note on ${body.wo_id} (${noteAddr}): "${noteText}"`);
      }
    } catch (e) { /* non-fatal — note already saved */ }
  }

  if (body.notify_owner_status_note === true) {
    try {
      const [properties, owners] = await fetchTabs(env, ['Properties','Owners']);
      const noteProp = properties.find(p => p.ID === wo.Property_ID);
      const noteOwner = noteProp ? owners.find(o => o.ID === noteProp.Owner_ID) : null;
      if (noteOwner?.Phone) {
        // Sep 16 2026 (Brett): same "reply" gap as the tenant-completed text — owner numbers
        // aren't recognized by handleInboundSMS either, so dropped the reply promise here too.
        const ownerMsg = `Hi ${noteOwner.First_Name}, your work order ${body.wo_id} has been placed on hold. Note: ${noteText}.`;
        await sendSMS(env, noteOwner.Phone, ownerMsg);
        await logSMS(env, body.wo_id, 'owner_onhold_note', noteOwner.ID, noteOwner.Phone, ownerMsg);
      }
    } catch(e) { /* non-fatal — note already saved */ }
  }

  return json({ success: true });
}

const OWNER_EDITABLE_FIELDS = ['Owner_WO_Ref','Priority','Scheduled_Date','Managed_By'];

async function ownerUpdateWO(env, body) {
  const allowed = {}; for (const [k,v] of Object.entries(body.fields||{})) { if (OWNER_EDITABLE_FIELDS.includes(k)) allowed[k]=v; }
  if (!Object.keys(allowed).length) return json({ error: 'No owner-editable fields provided' }, 400);
  // Managed_By (Sep 16 2026, Brett): additive column, ensured here on first real write rather
  // than a central schema pass — same convention as Hold_Reason in updateStatus. Values are
  // 'RidgeCo' (default/blank) or 'Owner'; validated so a bad client value can't write junk into
  // a field several other code paths branch on (assignVendor's guard, the tenant portal's
  // grayed-out treatment).
  if ('Managed_By' in allowed) {
    if (!['RidgeCo','Owner'].includes(allowed.Managed_By)) return json({ error: "Managed_By must be 'RidgeCo' or 'Owner'" }, 400);
    try { await ensureColumns(env, 'Work_Orders', ['Managed_By']); } catch (_) {}
  }
  const [workorders, properties] = await fetchTabs(env, ['Work_Orders','Properties']);
  const wo = findWO(workorders, body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  const prop = properties.find(p => p.ID === wo.Property_ID);
  if (!prop || String(prop.Owner_ID) !== String(body.owner_id)) return json({ error: 'Unauthorized' }, 403);
  await updateRow(env, 'Work_Orders', body.wo_id, allowed);
  const _ownerEntries = Object.entries(allowed).filter(([field,newVal]) => String(wo[field]||'') !== String(newVal||'')).map(([field,newVal]) => ({ woId: body.wo_id, changedBy: body.owner_name, changedByRole: 'owner', field, oldValue: wo[field]||'', newValue: newVal, notes: 'Owner updated via portal' }));
  await logWOAuditMany(env, _ownerEntries);
  return json({ success: true });
}

async function adminUpdateWO(env, body) {
  const adminName = body.admin_name||'Admin'; if (!body.wo_id||!body.fields) return json({ error: 'Missing wo_id or fields' }, 400);
  const workorders = await fetchTab(env, 'Work_Orders'); const wo = workorders.find(w => w.ID === body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  // Managed_By (Sep 16 2026, TENANT_WO_SETTINGS_UI_AND_HARDENING_BUILD_BRIEF_v1.0 Part B):
  // adminUpdateWO takes arbitrary body.fields with no allow-list (unlike ownerUpdateWO's
  // OWNER_EDITABLE_FIELDS), so Managed_By gets the same validation + ensureColumns here that
  // ownerUpdateWO already has — several other code paths (assignVendor's guard, the tenant
  // portal's grayed-out treatment) branch on this being exactly one of two strings.
  if ('Managed_By' in body.fields) {
    if (!['RidgeCo','Owner'].includes(body.fields.Managed_By)) return json({ error: "Managed_By must be 'RidgeCo' or 'Owner'" }, 400);
    try { await ensureColumns(env, 'Work_Orders', ['Managed_By']); } catch (_) {}
  }
  await updateRow(env, 'Work_Orders', body.wo_id, body.fields);
  // One batched audit write covering every changed field, instead of a GET+POST pair per
  // field — a 3-field edit used to mean 3 extra re-reads of WO_Audit in one save.
  const _adminEntries = Object.entries(body.fields).filter(([field,newVal]) => String(wo[field]||'') !== String(newVal||'')).map(([field,newVal]) => ({ woId: body.wo_id, changedBy: adminName, changedByRole: 'admin', field, oldValue: wo[field]||'', newValue: newVal, notes: 'Admin updated via portal' }));
  await logWOAuditMany(env, _adminEntries);
  // Owner notify on Managed_By change (Brett's call, Part B): unlike owner.html's own
  // claim/release toggle — where the owner already knows, since they just did it — an admin
  // flipping this is news to the owner either direction, so it's sent unconditionally here
  // rather than gated by shouldNotifyOwner's routine-status tiers (same "always tell them"
  // treatment as the Owner Received message in createWorkOrder). Non-fatal: the WO field
  // update above already succeeded regardless of whether this notify goes through.
  if ('Managed_By' in body.fields && String(wo.Managed_By||'RidgeCo') !== String(body.fields.Managed_By)) {
    try {
      const [properties, owners, unitsMB] = await fetchTabs(env, ['Properties','Owners','Units']);
      const property = properties.find(p => p.ID === wo.Property_ID);
      const owner = property ? owners.find(o => o.ID === property.Owner_ID) : null;
      const mbLoc = propUnitText(property, unitsMB.find(u => u.ID === wo.Unit_ID));
      if (owner?.Phone && property) {
        const msg = body.fields.Managed_By === 'Owner'
          ? `Hi ${owner.First_Name}, we've marked ${body.wo_id} at ${mbLoc} as being handled by you rather than Ridge Co — we won't assign a vendor to it while it's set this way. Let us know if that's not right.`
          : `Hi ${owner.First_Name}, ${body.wo_id} at ${mbLoc} is back with Ridge Co to handle — we'll take it from here.`;
        await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'owner_managed_by_changed', recipient_type: 'owner', owner, property, message_body: msg });
      }
    } catch (e) { /* non-fatal */ }
  }
  return json({ success: true });
}

async function appendDescription(env, body) {
  if (!body.wo_id||!body.text) return json({ error: 'Missing wo_id or text' }, 400);
  const [workorders, properties] = await fetchTabs(env, ['Work_Orders','Properties']);
  const wo = findWO(workorders, body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  if (body.author_role === 'owner' && body.owner_id) { const prop = properties.find(p => p.ID === wo.Property_ID); if (!prop || String(prop.Owner_ID) !== String(body.owner_id)) return json({ error: 'Unauthorized' }, 403); }
  const ts = new Date().toLocaleString('en-US', { timeZone:'America/New_York', month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit' });
  const newDesc = (wo.Description||'') + `\n\n[${ts} — ${body.author||'Unknown'} (${body.author_role||'unknown'})] ${body.text.trim()}`;
  await updateWOFields(env, body.wo_id, { Description: newDesc });
  await logWOAudit(env, body.wo_id, body.author, body.author_role, 'Description', wo.Description||'', newDesc, 'Description update appended');
  return json({ success: true });
}

async function setTenantVisibility(env, body) {
  const ALLOWED = ['Tenant_Visible','Tenant_Notify_Created','Tenant_Notify_Updates'], updates = {};
  for (const [k,v] of Object.entries(body.fields||{})) { if (ALLOWED.includes(k)) updates[k]=v; }
  if (!Object.keys(updates).length) return json({ error: 'No valid fields' }, 400);
  const workorders = await fetchTab(env, 'Work_Orders'); const wo = workorders.find(w => w.ID === body.wo_id); if (!wo) return json({ error: 'WO not found' }, 404);
  await updateRow(env, 'Work_Orders', body.wo_id, updates);
  const _tvEntries = Object.entries(updates).filter(([field,newVal]) => String(wo[field]||'') !== String(newVal||'')).map(([field,newVal]) => ({ woId: body.wo_id, changedBy: body.changed_by||'admin', changedByRole: body.changed_by_role||'admin', field, oldValue: wo[field]||'', newValue: newVal, notes: 'Tenant visibility setting changed' }));
  await logWOAuditMany(env, _tvEntries);
  return json({ success: true });
}

// ── TURNOVER TRIGGER (B-100) ──────────────────────────────────
// One trigger, three connected work orders: Repairs + Paint run in parallel from day one
// (so Brett can line up vendors well ahead of a knee-jerk, last-minute turnover instead of
// scrambling once the unit is actually empty); Cleaning is created On Hold and only releases
// once BOTH finish, or the target move-in date arrives — whichever comes first. All three
// share one Turnover_Group_ID so the release check and the Hub UI can always find siblings.
// Two entry points funnel into the same createTurnoverWOs() core (PAT-001 — one place this
// logic lives): a manual "Start Turnover" button (startTurnoverManual) and setting a future
// move-out date on a still-active tenant (scheduleMoveOutWithTurnover) — the latter does NOT
// touch Tenants.Active/PIN/Unit pointer the way the existing destructive /tenant/move-out
// does; the tenant keeps living there and using their portal right up to the real date.
const TURNOVER_ROLES = ['Repairs', 'Paint', 'Cleaning'];
const TURNOVER_TRADE_BY_ROLE = { Repairs: 'General', Paint: 'Painting', Cleaning: 'Cleaning' };
const TURNOVER_DESC_BY_ROLE = {
  Repairs: 'Standard turnover — repairs (checklist TBD).',
  Paint: 'Standard turnover — paint (checklist TBD).',
  Cleaning: 'Standard turnover — cleaning (checklist TBD). Waits on Repairs + Paint, or the day before the target move-in date, whichever comes first.',
};
// "Done" for the purposes of unblocking Cleaning — Cancelled counts too, so one dead/void
// leg of a turnover can't permanently wedge the cleaner behind a job that will never finish.
const TURNOVER_RELEASE_DONE_STATUSES = WOStatus.sets.TURNOVER_DONE;

function dayBefore(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr + 'T12:00:00'); // noon avoids DST edge cases shifting the date
  if (isNaN(d)) return '';
  d.setDate(d.getDate() - 1);
  return d.toISOString().split('T')[0];
}

function nextTurnoverGroupId(workorders) {
  const nums = workorders
    .map(w => (w.Turnover_Group_ID || '').match(/^TO-(\d+)$/))
    .filter(Boolean)
    .map(m => parseInt(m[1], 10))
    .filter(n => Number.isFinite(n) && n > 0);
  return `TO-${nums.length ? Math.max(...nums) + 1 : 1001}`;
}

// Core: create the 3 connected WOs for one unit. Reuses createWorkOrder() for every field
// this shares with a normal WO (ID assignment, WO_Tenants linking, telemetry) instead of
// re-deriving that logic — the turnover-specific bits (Turnover_Group_ID/Role, Cleaning's
// On Hold start + release date) are stamped on afterward with their own ensureColumns call.
async function createTurnoverWOs(env, body) {
  const unitId = body.unit_id;
  if (!unitId) return json({ error: 'unit_id required' }, 400);
  const [units, workorders] = await fetchTabs(env, ['Units', 'Work_Orders']);
  const unit = units.find(u => u.ID === unitId);
  if (!unit) return json({ error: 'Unit not found' }, 404);

  // Idempotency guard — don't stack a second turnover on a unit that already has one running.
  // "Running" = any WO on this unit carrying a Turnover_Group_ID whose status isn't done yet.
  const existingGroup = workorders.find(w => w.Unit_ID === unitId && w.Turnover_Group_ID
    && !TURNOVER_RELEASE_DONE_STATUSES.includes(w.Status));
  if (existingGroup) {
    return json({ error: `A turnover is already active for this unit (${existingGroup.Turnover_Group_ID}).`, existing_group_id: existingGroup.Turnover_Group_ID }, 409);
  }

  const groupId = nextTurnoverGroupId(workorders);
  const releaseDate = dayBefore(body.target_move_in_date || '');

  const woIds = {};
  // Sequential, not Promise.all — each createWorkOrder() call re-reads the current max WO
  // number, so three concurrent calls could compute the same "next" number and collide.
  for (const role of TURNOVER_ROLES) {
    const resp = await createWorkOrder(env, {
      property_id: unit.Property_ID,
      unit_id: unitId,
      type: 'turnover',
      trade: TURNOVER_TRADE_BY_ROLE[role],
      description: TURNOVER_DESC_BY_ROLE[role],
      priority: body.priority || 'normal',
      created_by: body.created_by || 'admin',
      // No current tenant to show this to — the outgoing tenant is on the way out and there
      // may be no incoming tenant yet. Admin can flip visibility per-WO later if it's ever needed.
      tenant_visible: false,
      tenant_notify_created: false,
      tenant_notify_updates: false,
    });
    const respBody = await resp.json();
    if (respBody.error) return json({ error: `Failed creating ${role} WO: ${respBody.error}` }, 500);
    woIds[role] = respBody.id;
  }

  // Hold_Reason doesn't exist on Work_Orders yet (the B-127 notes model that would have
  // added it never merged) — ensure it here too, since Cleaning's initial On Hold write
  // below needs it, not just the three Turnover_* columns.
  await ensureColumns(env, 'Work_Orders', ['Turnover_Group_ID', 'Turnover_Role', 'Turnover_Release_Date', 'Hold_Reason']);
  await updateWOFields(env, woIds.Repairs, { Turnover_Group_ID: groupId, Turnover_Role: 'Repairs' });
  await updateWOFields(env, woIds.Paint, { Turnover_Group_ID: groupId, Turnover_Role: 'Paint' });
  await updateWOFields(env, woIds.Cleaning, {
    Turnover_Group_ID: groupId,
    Turnover_Role: 'Cleaning',
    Status: 'On Hold',
    Hold_Reason: 'Turnover — waiting on Repairs + Paint (or the day before move-in, whichever comes first).',
    Turnover_Release_Date: releaseDate,
  });

  try { await logTelemetry(env, { Source: 'worker', Job_Type: 'turnover_start', Skill_Or_Endpoint: '/turnover', Success: 'TRUE', Notes: `unit=${unitId} group=${groupId} source=${body.source || 'manual'}` }); } catch (_) {}

  return json({ success: true, group_id: groupId, wo_ids: woIds, release_date: releaseDate || null });
}

// Manual "Start Turnover" button — unit is already vacant, or Brett just wants the jobs
// queued now regardless of a tenant/move-out record.
async function startTurnoverManual(env, body) {
  return createTurnoverWOs(env, { unit_id: body.unit_id, target_move_in_date: body.target_move_in_date, priority: body.priority, created_by: body.created_by, source: 'manual' });
}

// Setting a FUTURE move-out date on a tenant who is still living there. Deliberately does
// NOT call processMoveOut()/deactivate the tenant — that stays a separate, immediate,
// destructive action for the actual day. This just books the date and gets the turnover
// vendors queued with lead time, which is the whole point Brett raised: last-minute
// turnovers are unschedulable, this gives Repairs/Paint a head start before the unit is even empty.
async function scheduleMoveOutWithTurnover(env, body) {
  const { tenant_id, move_out_date, target_move_in_date, created_by } = body;
  if (!tenant_id || !move_out_date) return json({ error: 'tenant_id and move_out_date required' }, 400);
  const tenants = await fetchTab(env, 'Tenants');
  const tenant = tenants.find(t => t.ID === tenant_id);
  if (!tenant) return json({ error: 'Tenant not found' }, 404);
  if (!tenant.Unit_ID) return json({ error: 'This tenant has no Unit_ID on file — turnover requires a unit-level tenant. Add the unit first, or use "Start Turnover" directly on the unit.' }, 400);

  await ensureColumns(env, 'Tenants', ['Scheduled_Move_Out_Date']);
  await updateRow(env, 'Tenants', tenant_id, { Scheduled_Move_Out_Date: move_out_date });

  const turnover = await createTurnoverWOs(env, {
    unit_id: tenant.Unit_ID,
    target_move_in_date,
    created_by,
    source: 'scheduled_move_out',
  });
  const turnoverBody = await turnover.json();
  // A 409 (turnover already running on this unit) is not a failure of THIS action — the
  // move-out date still got saved. Report both halves so the Hub can show "date saved,
  // turnover already in progress" instead of a bare error.
  return json({ success: true, move_out_date, turnover: turnoverBody, turnover_created: !turnoverBody.error });
}

// Repairs/Paint just went Complete — check whether Cleaning can release now.
async function releaseTurnoverCleaningIfReady(env, groupId) {
  const workorders = await fetchTab(env, 'Work_Orders');
  const siblings = workorders.filter(w => w.Turnover_Group_ID === groupId);
  const cleaning = siblings.find(w => w.Turnover_Role === 'Cleaning');
  if (!cleaning || cleaning.Status !== 'On Hold') return; // already released, or no cleaning leg
  const others = siblings.filter(w => w.Turnover_Role && w.Turnover_Role !== 'Cleaning');
  const allDone = others.length > 0 && others.every(w => TURNOVER_RELEASE_DONE_STATUSES.includes(w.Status));
  if (allDone) {
    await updateWOFields(env, cleaning.ID, { Status: 'New', Hold_Reason: '' });
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'turnover_release', Skill_Or_Endpoint: 'updateStatus', Success: 'TRUE', Notes: `group=${groupId} reason=repairs_paint_complete` }); } catch (_) {}
  }
}

// Daily cron sweep (B-100 date fallback) — release any Cleaning WO still On Hold whose
// Turnover_Release_Date has arrived, even if Repairs/Paint haven't finished.
async function releaseTurnoverByDate(env) {
  const workorders = await fetchTab(env, 'Work_Orders');
  const today = new Date().toISOString().split('T')[0];
  const due = workorders.filter(w => w.Turnover_Role === 'Cleaning' && w.Status === 'On Hold'
    && w.Turnover_Release_Date && w.Turnover_Release_Date <= today);
  for (const w of due) {
    await updateWOFields(env, w.ID, { Status: 'New', Hold_Reason: '' });
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'turnover_release', Skill_Or_Endpoint: 'scheduled/turnover-date', Success: 'TRUE', Notes: `wo=${w.ID} group=${w.Turnover_Group_ID} reason=date_fallback` }); } catch (_) {}
  }
}

// ── MASTER KEYS / TEMPLATES / MATERIALS ──────────────────────

async function bulkAssignMasterKey(env, body) {
  if (!body.master_key_id||!body.owner_id) return json({ error: 'Missing master_key_id or owner_id' }, 400);
  const propData = await sheetsRequest(env, 'GET', `/values/Properties`); const props = propData.values||[], headers = props[0]||[];
  const ownerIdx=headers.indexOf('Owner_ID'), mkIdx=headers.indexOf('Master_Key_ID');
  if (ownerIdx===-1||mkIdx===-1) return json({ error: 'Properties tab missing Owner_ID or Master_Key_ID column' }, 400);
  let updated=0; const requests=[];
  props.slice(1).forEach((row,i) => { if(row[ownerIdx]===body.owner_id){ requests.push({ range:`Properties!${col(mkIdx)}${i+2}`, values:[[body.master_key_id]] }); updated++; } });
  if (requests.length) await sheetsRequest(env, 'POST', `/values:batchUpdate`, { valueInputOption:'RAW', data:requests });
  return json({ success:true, updated });
}

// Master_Key_Holders (Aug 24, 2026): tracks which VENDOR currently physically holds a copy
// of a given master key — "this property is on a master key, and Eddy has a copy" is a fact
// about Eddy specifically, not about the property, and it changes over time (checked out,
// returned, promised-but-not-given-yet, per Brett's own "he doesn't have it right now, but
// I will give that to him shortly"). One row per (Master_Key_ID, Vendor_ID) pair; upserted
// here rather than ever appending a duplicate. Status vocabulary matches the existing Keys
// Possession_Status wording so the whole app speaks one language: 'Have It' / 'Need Copy' /
// "Don't Have It" / 'Unknown'. See getWOLockboxes/enrichWO for how this gates what a vendor
// is told — never surfaced to a vendor who ISN'T the one holding (or about to be handed) it,
// never surfaced to a tenant, ever (see enrichWO's opts.viewingVendorId gate).
async function fetchMasterKeyHolders(env, opts) {
  try { return await fetchTab(env, 'Master_Key_Holders', opts); }
  catch (e) { if (isMissingTabError(e)) return []; throw e; }
}

async function setMasterKeyHolder(env, body) {
  if (!body.master_key_id || !body.vendor_id) return json({ error: 'Missing master_key_id or vendor_id' }, 400);
  const rows = await fetchMasterKeyHolders(env);
  const now = new Date().toISOString().split('T')[0];
  const existing = rows.find(r => r.Master_Key_ID === String(body.master_key_id) && r.Vendor_ID === String(body.vendor_id));
  const fields = { Status: body.status || '', Notes: body.notes || '', Updated_Date: now, Active: 'TRUE' };
  if (existing) return await updateRow(env, 'Master_Key_Holders', existing.ID, fields);
  return await addRow(env, 'Master_Key_Holders', { Master_Key_ID: String(body.master_key_id), Vendor_ID: String(body.vendor_id), ...fields });
}

async function listWOTemplates(env, url) {
  const ownerId = url.searchParams.get('owner_id')||'';
  const templates = await fetchTab(env, 'WO_Templates');
  return json(templates.filter(t => t.Active!=='FALSE' && (!t.Owner_ID||t.Owner_ID===''||(ownerId&&t.Owner_ID===ownerId))));
}

async function listMaterials(env, url) {
  const woId=url.searchParams.get('wo_id')||'', vendorId=url.searchParams.get('vendor_id')||'', showAll=url.searchParams.get('all')==='true';
  const materials = await fetchTab(env, 'Materials'); let items = materials.filter(m => m.Active!=='FALSE');
  if (woId) { items=items.filter(m=>m.WO_ID===woId); }
  else if (vendorId&&!showAll) { const wos=await fetchTab(env,'Work_Orders'); const vids=new Set(wos.filter(w=>w.Vendor_ID===vendorId).map(w=>w.ID)); items=items.filter(m=>vids.has(m.WO_ID)); }
  if (showAll||(!woId&&!vendorId)) { const wos=await fetchTab(env,'Work_Orders'); const ps=await fetchTab(env,'Properties'); items=items.map(m=>{ const wo=wos.find(w=>w.ID===m.WO_ID)||{}; const prop=ps.find(p=>p.ID===wo.Property_ID)||{}; return {...m,wo_status:wo.Status||'',property_address:prop.Address||'',wo_trade:wo.Trade||''}; }); }
  return json(items);
}

// ── GOOGLE DRIVE ─────────────────────────────────────────────

async function findDriveFolder(token, name, parentId, sharedDriveId) {
  const q=`name=${JSON.stringify(name)} and mimeType='application/vnd.google-apps.folder' and '${parentId}' in parents and trashed=false`;
  const params=new URLSearchParams({ q, fields:'files(id,name,webViewLink)', supportsAllDrives:'true', includeItemsFromAllDrives:'true', ...(sharedDriveId?{driveId:sharedDriveId,corpora:'drive'}:{}) });
  const res=await fetch(`https://www.googleapis.com/drive/v3/files?${params}`,{headers:{Authorization:`Bearer ${token}`}});
  const data=await res.json(); return (data.files||[])[0]||null;
}

async function createDriveFolder(token, name, parentId) {
  const res=await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true&includeItemsFromAllDrives=true&fields=id,name,webViewLink',{ method:'POST', headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'}, body:JSON.stringify({name,mimeType:'application/vnd.google-apps.folder',parents:[parentId]}) });
  return await res.json();
}

async function findOrCreateFolder(token, name, parentId, sharedDriveId) {
  const existing = await findDriveFolder(token, name, parentId, sharedDriveId);
  return existing || await createDriveFolder(token, name, parentId);
}

async function uploadFileToDrive(token, arrayBuffer, filename, mimeType, folderId, sharedDriveId) {
  const metadata=JSON.stringify({name:filename,parents:[folderId]}), boundary='ridgeco_boundary_xyz', enc=new TextEncoder();
  const metaPart=enc.encode(`--${boundary}\nContent-Type: application/json\n\n${metadata}\n--${boundary}\nContent-Type: ${mimeType}\n\n`);
  const closePart=enc.encode(`\n--${boundary}--`), fileBytes=new Uint8Array(arrayBuffer);
  const combined=new Uint8Array(metaPart.length+fileBytes.length+closePart.length);
  combined.set(metaPart,0); combined.set(fileBytes,metaPart.length); combined.set(closePart,metaPart.length+fileBytes.length);
  const res=await fetch(`https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&includeItemsFromAllDrives=true&fields=id,name,webViewLink,mimeType,size${sharedDriveId?'&driveId='+sharedDriveId:''}`,{ method:'POST', headers:{Authorization:`Bearer ${token}`,'Content-Type':`multipart/related; boundary=${boundary}`}, body:combined });
  return await res.json();
}

async function updateWOField(env, woId, fieldName, value) {
  try {
    const data=await sheetsRequest(env,'GET','/values/Work_Orders'); const rows=data.values||[], headers=rows[0]||[];
    const colIdx=headers.indexOf(fieldName); if(colIdx===-1) return;
    const idCol=idColIndex(headers), rowIdx=rows.findIndex((r,i)=>i>0&&r[idCol]===woId); if(rowIdx===-1) return;
    const colLetter=colIdx<26?String.fromCharCode(65+colIdx):'A'+String.fromCharCode(65+colIdx-26);
    await sheetsRequest(env,'PUT',`/values/Work_Orders!${colLetter}${rowIdx+1}?valueInputOption=RAW`,{values:[[value]]});
  } catch(e) { /* non-fatal */ }
}

// Retired July 20, 2026 — the Make.com → QBO webhook path is dead (Make stopped
// firing in 2025). Invoicing now goes through the preview-first /qb/send-invoice
// flow against Intuit directly. The old /fire-make-webhook route is gone; the Hub
// button that called it now opens the QB preview modal.

async function updateOwnerBilling(env, body) {
  if (!body.owner_id) return json({error:'Missing owner_id'},400);
  const BILLING_FIELDS=['Billing_Name','Billing_Address','Billing_City','Billing_State','Billing_Zip','Billing_Phone','Billing_Email'];
  const fields={}; for(const f of BILLING_FIELDS){if(body[f]!==undefined)fields[f]=body[f];}
  if(!Object.keys(fields).length) return json({error:'No billing fields provided'},400);
  await updateRow(env,'Owners',body.owner_id,fields); return json({success:true});
}

async function getOwnerBilling(env, url) {
  const ownerId=url.searchParams.get('owner_id'); if(!ownerId) return json({error:'Missing owner_id'},400);
  const owners=await fetchTab(env,'Owners'); const owner=owners.find(o=>o.ID===ownerId); if(!owner) return json({error:'Owner not found'},404);
  return json({owner_id:owner.ID,name:owner.First_Name+' '+(owner.Last_Name||''),company:owner.Company||'',billing_name:owner.Billing_Name||'',billing_address:owner.Billing_Address||'',billing_city:owner.Billing_City||'',billing_state:owner.Billing_State||'',billing_zip:owner.Billing_Zip||'',billing_phone:owner.Billing_Phone||'',billing_email:owner.Billing_Email||'',qbo_customer_id:owner.QBO_Customer_ID||''});
}

// ── ADMIN TOOLS ──────────────────────────────────────────────

// POST /admin/fix-stale-tenants { apply?: true }
// Units still naming a tenant who has moved out. Move-out never cleared the pointer, so
// this backlog exists in the live sheet right now — and every one of them is a former
// tenant's phone number waiting to be texted to a vendor. Reports by default; only
// writes when explicitly told to.
// ── DUPLICATE PROPERTIES: INSPECT, THEN MERGE ────────────────
// The same building entered twice is not a cosmetic problem. Work orders, units, keys,
// tenants and receipts each attach to whichever ID they happened to be created against,
// so the history splits in two and neither half is complete. Deleting the wrong one
// silently orphans everything pointing at it.
//
// Nothing here deletes. The loser is deactivated, and every reference is repointed first.

// Every tab that stores a Property_ID, and what else needs repointing alongside it.
const PROPERTY_REFS = [
  { tab: 'Work_Orders',  col: 'Property_ID' },
  { tab: 'Units',        col: 'Property_ID' },
  { tab: 'Keys',         col: 'Property_ID' },
  { tab: 'Tenants',      col: 'Property_ID' },
  { tab: 'Attachments',  col: 'Property_ID' },
  { tab: 'Receipts',     col: 'Property_ID' },
  { tab: 'Estimates',    col: 'Property_ID' },
  { tab: 'Materials',    col: 'Property_ID' },
  // Not called Property_ID. A queued receipt auto-linked to the losing row would otherwise
  // stay pointed at a property that no longer exists as far as the Hub is concerned.
  { tab: 'Receipts_Queue', col: 'Suggested_Property_ID' },
];

// GET /admin/duplicate-properties
// Addresses appearing more than once, with a full reference count per ID so you can see
// which row the work actually lives on before touching anything.
// POST /admin/migrate-trades { apply?: true }
// One-time sweep bringing stored trade names onto the canonical list. The worker already
// aliases on read, so the MONEY was never wrong — but every client-side filter compares
// raw strings, so a Hub filter set to "Electrical" returns none of the history stored as
// "Electric". This closes that.
//
// Safe to run now in a way it wasn't before: every form writes the canonical list, so
// nothing is going to reintroduce the old spellings behind the sweep.
const TRADE_MIGRATION_TABS = [
  { tab: 'Work_Orders', cols: ['Trade'] },
  { tab: 'Vendors',     cols: ['Trade', 'Trades'] },
  { tab: 'Materials',   cols: ['Trade'] },
  { tab: 'WO_Templates',cols: ['Trade'] },
];

async function adminMigrateTrades(env, body) {
  const apply = body && (body.apply === true || String(body.apply).toUpperCase() === 'TRUE');
  const report = [];

  for (const spec of TRADE_MIGRATION_TABS) {
    let rows;
    try { rows = await fetchTab(env, spec.tab); }
    catch (e) { if (isMissingTabError(e)) continue; report.push({ tab: spec.tab, error: e.message }); continue; }

    for (const col of spec.cols) {
      const changes = [];
      for (const r of rows) {
        const raw = String(r[col] || '').trim();
        if (!raw) continue;
        // Trades is a comma list; Trade is a single value. Handle both by splitting.
        const parts = raw.split(',').map(x => x.trim()).filter(Boolean);
        const mapped = parts.map(x => { const res = resolveTrade(x); return res.matched ? res.name : x; });
        const next = mapped.join(', ');
        if (next !== raw) changes.push({ id: r.ID, from: raw, to: next });
      }
      if (!changes.length) continue;
      if (apply) {
        for (const c of changes) {
          try { await updateRow(env, spec.tab, c.id, { [col]: c.to }); c.done = true; }
          catch (e) { c.done = false; }
        }
      }
      report.push({ tab: spec.tab, col, count: changes.length,
                    applied: apply ? changes.filter(c => c.done).length : 0,
                    sample: changes.slice(0, 8) });
    }
  }

  const total = report.reduce((n, r) => n + (r.count || 0), 0);
  return json({ success: true, applied: apply, total, report });
}

// Owners duplicate the same way properties do — the same company entered twice, each row
// collecting its own properties and its own portal users. Same treatment: show what is
// attached to each, repoint everything onto the keeper, deactivate the loser, delete
// nothing.
const OWNER_REFS = [
  { tab: 'Properties',   col: 'Owner_ID' },
  { tab: 'Owner_Users',  col: 'Owner_ID' },
  { tab: 'WO_Templates', col: 'Owner_ID' },   // templates can be scoped to one owner
];

// GET /admin/duplicate-owners
// POST /admin/owner-to-user { from_id, to_id, apply? }
// Two people at one company should be ONE owner record with TWO logins — that's exactly
// what Owner_Users is for. Two Owners rows instead means the properties split, reporting
// sees two owners, and only one of them can hold the QuickBooks link.
//
// This converts the surplus Owners row into an Owner_User on the keeper, carrying the
// person's PIN across so their login keeps working, then moves anything attached and
// deactivates the old row. Nobody loses access, which is the whole difference between
// this and a merge.
async function adminOwnerToUser(env, body) {
  const fromId = String(body.from_id || '').trim();
  const toId   = String(body.to_id || '').trim();
  const apply  = body.apply === true || String(body.apply).toUpperCase() === 'TRUE';
  if (!fromId || !toId) return json({ error: 'from_id and to_id required' }, 400);
  if (fromId === toId) {
    return json({ error: 'Those two rows carry the SAME ID in the Owners tab. That is a data problem, not a duplicate — give one of them a unique ID in the sheet first, or every lookup will keep finding whichever comes first.' }, 400);
  }

  const [owners, ownerUsers] = await fetchTabs(env, ['Owners','Owner_Users']);
  const from = owners.find(o => String(o.ID) === fromId);
  const to   = owners.find(o => String(o.ID) === toId);
  if (!from) return json({ error: `No owner ${fromId}` }, 404);
  if (!to)   return json({ error: `No owner ${toId}` }, 404);

  const personName = ((from.First_Name || '') + ' ' + (from.Last_Name || '')).trim() || qbOwnerDisplayName(from);
  if (!personName) return json({ error: 'That row has no person name to carry across.' }, 400);

  // A PIN already in use would let two people log in as each other.
  const pin = String(from.PIN || '').trim();
  if (pin) {
    const pinClash = ownerUsers.find(u => String(u.PIN || '').trim().toLowerCase() === pin.toLowerCase() && u.Active !== 'FALSE');
    if (pinClash) return json({ error: `That PIN is already used by owner user "${pinClash.First_Name || pinClash.ID}". Change one of them first.` }, 409);
    // Check active OWNERS too. Login tries Owner_Users first and returns null outright on a
    // name mismatch — no fallthrough. So a PIN shared with another owner would send that
    // person's login into this new user, fail the name check, and lock them out completely.
    const ownerClash = owners.find(o => String(o.ID) !== fromId && String(o.PIN || '').trim().toLowerCase() === pin.toLowerCase() && o.Active !== 'FALSE');
    if (ownerClash) return json({ error: `That PIN is also on owner "${qbOwnerDisplayName(ownerClash)}". Converting would lock them out — change one PIN first.` }, 409);
  }

  const alreadyUser = ownerUsers.find(u => String(u.Owner_ID) === toId && u.Active !== 'FALSE' &&
    ((u.First_Name || '') + ' ' + (u.Last_Name || '')).trim().toLowerCase() === personName.toLowerCase());

  // What moves across with them.
  const plan = [];
  for (const ref of OWNER_REFS) {
    let rows;
    try { rows = await fetchTab(env, ref.tab); }
    catch (e) { if (isMissingTabError(e)) continue; return json({ error: `Could not read ${ref.tab} — stopping.` }, 500); }
    const hits = rows.filter(r => String(r[ref.col] || '') === fromId && r.Active !== 'FALSE');
    if (hits.length) plan.push({ tab: ref.tab, col: ref.col, ids: hits.map(r => r.ID), count: hits.length });
  }

  const loginFirstName = from.First_Name || personName.split(' ')[0] || '';
  if (!apply) {
    return json({ success: true, applied: false, from: fromId, to: toId,
      person: personName, keeper: qbOwnerDisplayName(to),
      has_pin: !!pin, already_user: !!alreadyUser,
      // Owner rows log in on PIN alone; owner USERS must also give a first name. That's a
      // real change to how this person signs in, and it should not be a surprise.
      login_first_name: loginFirstName,
      login_name_changes: !from.First_Name,
      plan, total: plan.reduce((n, p) => n + p.count, 0) });
  }

  // Create the login FIRST. If anything later fails, the person can already sign in and
  // the old row is still live — nobody is locked out at any point.
  let userId = alreadyUser ? alreadyUser.ID : '';
  if (!alreadyUser) {
    const res = await addRow(env, 'Owner_Users', {
      Owner_ID: toId,
      First_Name: loginFirstName,
      Last_Name:  from.Last_Name || '',
      Phone: from.Phone || '', Email: from.Billing_Email || from.Email || '',
      PIN: pin, Role: 'secondary', Active: 'TRUE',
      Created_Date: new Date().toISOString().split('T')[0],
    });
    try { const parsed = await res.clone().json(); userId = parsed && parsed.id ? String(parsed.id) : ''; } catch (e) {}
    if (!userId) return json({ error: 'Could not create the owner user — nothing else was changed.' }, 500);
  }

  const moved = [], failed = [];
  for (const step of plan) {
    for (const id of step.ids) {
      try { await updateRow(env, step.tab, id, { [step.col]: toId }); moved.push(step.tab + ':' + id); }
      catch (e) { failed.push(step.tab + ':' + id); }
    }
  }
  if (failed.length) {
    return json({ success: false, applied: true, owner_user_id: userId, moved: moved.length, failed,
      error: `${personName} can now sign in under ${qbOwnerDisplayName(to)}, but ${failed.length} reference(s) didn't move. Both owner rows are still active. Re-run to finish.` }, 500);
  }

  // Carry the QuickBooks link over if only the old row had one.
  const fq = (from.QBO_Customer_ID || '').trim(), tq = (to.QBO_Customer_ID || '').trim();
  if (fq && !tq) { try { await updateRow(env, 'Owners', toId, { QBO_Customer_ID: fq }); } catch (e) {} }

  // Clear the old PIN before deactivating, so one PIN never resolves to two records.
  // updateRow returns a 404 response rather than throwing, so its result has to be read —
  // otherwise a failed deactivation reports success while the old row stays live with a
  // working PIN.
  let deactivated = true;
  try {
    const dRes = await updateRow(env, 'Owners', fromId, { Active: 'FALSE', PIN: '' });
    const dBody = await dRes.clone().json();
    deactivated = !!(dBody && dBody.success);
  } catch (e) { deactivated = false; }

  return json({ success: true, applied: true, owner_user_id: userId, person: personName,
    keeper: qbOwnerDisplayName(to), moved: moved.length, qb_moved: !!(fq && !tq),
    deactivated,
    warning: deactivated ? '' : `${personName} can sign in under ${qbOwnerDisplayName(to)}, but the old owner row could not be deactivated — it is still active and still holds the PIN. Deactivate it by hand.`,
    login_name: loginFirstName,
    note: `${personName} now signs in as a secondary user on ${qbOwnerDisplayName(to)} with the same PIN, giving their first name "${loginFirstName}".` });
}

async function adminDuplicateOwners(env) {
  const owners = (await fetchTab(env, 'Owners')).filter(o => o.Active !== 'FALSE');
  const groups = {};
  for (const o of owners) {
    const key = qbNormName(qbOwnerDisplayName(o));
    if (!key) continue;
    (groups[key] = groups[key] || []).push(o);
  }
  const dupeKeys = Object.keys(groups).filter(k => groups[k].length > 1);
  if (!dupeKeys.length) return json({ success: true, duplicates: [] });

  const refData = {};
  for (const ref of OWNER_REFS) {
    if (refData[ref.tab] !== undefined) continue;
    try { refData[ref.tab] = await fetchTab(env, ref.tab); }
    catch (e) { refData[ref.tab] = isMissingTabError(e) ? [] : null; }
  }

  // Two rows sharing an ID is a different and worse problem than two rows for one company:
  // every lookup by id takes whichever comes first, so half the system sees one row and
  // half sees the other. Surface it rather than letting a merge fail with a confusing error.
  const idCounts = {};
  owners.forEach(o => { const k = String(o.ID || ''); idCounts[k] = (idCounts[k] || 0) + 1; });
  const sharedIds = Object.keys(idCounts).filter(k => k && idCounts[k] > 1);

  const duplicates = dupeKeys.map(key => ({
    name: qbOwnerDisplayName(groups[key][0]),
    shared_id: groups[key].length > 1 && new Set(groups[key].map(o => String(o.ID))).size === 1,
    rows: groups[key].map(o => {
      const counts = {}; let total = 0;
      for (const ref of OWNER_REFS) {
        const rows = refData[ref.tab];
        if (!rows) { counts[ref.tab] = null; continue; }
        const n = rows.filter(r => String(r[ref.col] || '') === String(o.ID) && r.Active !== 'FALSE').length;
        counts[ref.tab] = n; total += n;
      }
      return { id: o.ID, display: qbOwnerDisplayName(o),
               email: o.Billing_Email || o.Email || '', phone: o.Phone || '',
               // An Owners row with a PIN is somebody's portal login. Deactivating it on
               // merge takes their access away, so it has to be visible BEFORE the merge.
               has_login: !!String(o.PIN || '').trim(),
               qb_id: o.QBO_Customer_ID || '', refs: counts, total_refs: total };
    }),
  }));
  return json({ success: true, duplicates, shared_ids: sharedIds });
}

// POST /admin/merge-owner { from_id, to_id, apply? }
async function adminMergeOwner(env, body) {
  const fromId = String(body.from_id || '').trim();
  const toId   = String(body.to_id || '').trim();
  const apply  = body.apply === true || String(body.apply).toUpperCase() === 'TRUE';
  if (!fromId || !toId) return json({ error: 'from_id and to_id required' }, 400);
  if (fromId === toId) {
    return json({ error: 'Those two rows carry the SAME ID in the Owners tab. Give one of them a unique ID in the sheet first — with a shared ID, every lookup finds whichever comes first.' }, 400);
  }

  const owners = await fetchTab(env, 'Owners');
  const from = owners.find(o => String(o.ID) === fromId);
  const to   = owners.find(o => String(o.ID) === toId);
  if (!from) return json({ error: `No owner ${fromId}` }, 404);
  if (!to)   return json({ error: `No owner ${toId}` }, 404);

  // Merging two genuinely different owners would move properties onto the wrong ledger.
  if (qbNormName(qbOwnerDisplayName(from)) !== qbNormName(qbOwnerDisplayName(to))) {
    return json({ error: `"${qbOwnerDisplayName(from)}" and "${qbOwnerDisplayName(to)}" are not the same name. Refusing to merge.` }, 409);
  }
  // Two different QuickBooks customers means two real ledgers with real history.
  const fq = (from.QBO_Customer_ID || '').trim(), tq = (to.QBO_Customer_ID || '').trim();
  if (fq && tq && fq !== tq) {
    return json({ error: `These are linked to different QuickBooks customers (#${fq} and #${tq}). Sort that out first — merging would abandon one ledger.` }, 409);
  }

  const plan = [];
  for (const ref of OWNER_REFS) {
    let rows;
    try { rows = await fetchTab(env, ref.tab); }
    catch (e) { if (isMissingTabError(e)) continue; return json({ error: `Could not read ${ref.tab} — stopping rather than half-merging.` }, 500); }
    const hits = rows.filter(r => String(r[ref.col] || '') === fromId && r.Active !== 'FALSE');
    if (hits.length) plan.push({ tab: ref.tab, col: ref.col, ids: hits.map(r => r.ID), count: hits.length });
  }

  if (!apply) {
    return json({ success: true, applied: false, from: fromId, to: toId, name: qbOwnerDisplayName(from),
                  plan, total: plan.reduce((n, p) => n + p.count, 0),
                  // The system already models several people at one company: Owner_Users.
                  // Two Owners rows each with a login means the second person belongs
                  // there, not merged away.
                  loser_has_login: !!String(from.PIN || '').trim(),
                  loser_phone: from.Phone || '',
                  qb_note: (!tq && fq) ? `The keeper isn't linked to QuickBooks but #${fromId} is (#${fq}) — that link moves across.` : '' });
  }

  const moved = [], failed = [];
  for (const step of plan) {
    for (const id of step.ids) {
      try { await updateRow(env, step.tab, id, { [step.col]: toId }); moved.push(step.tab + ':' + id); }
      catch (e) { failed.push(step.tab + ':' + id); }
    }
  }
  if (failed.length) {
    return json({ success: false, applied: true, moved: moved.length, failed,
      error: `Moved ${moved.length} but ${failed.length} failed. Both owners are still active — nothing was hidden. Re-run to finish.` }, 500);
  }

  // Carry the QuickBooks link over if only the loser had one, so the keeper inherits the
  // ledger rather than looking unmapped and getting a new customer created for it.
  if (fq && !tq) { try { await updateRow(env, 'Owners', toId, { QBO_Customer_ID: fq }); } catch (e) {} }
  await updateRow(env, 'Owners', fromId, { Active: 'FALSE' });
  return json({ success: true, applied: true, from: fromId, to: toId, moved: moved.length,
                qb_moved: !!(fq && !tq),
                note: `Owner ${fromId} is deactivated, not deleted — the row is still in the sheet.` });
}

async function adminDuplicateProperties(env) {
  const properties = await fetchTab(env, 'Properties');
  const live = properties.filter(p => p.Active !== 'FALSE');

  // Group on address AND city. Same street number and name in two different towns is a
  // realistic shape in a Baltimore-area portfolio, and presenting those as duplicates with
  // a proposed keeper is how you'd merge two genuinely different buildings.
  const groups = {};
  for (const p of live) {
    const addr = qbNormAddress(p.Address || '');
    if (!addr) continue;
    const key = addr + '|' + qbNormAddress(p.City || '');
    (groups[key] = groups[key] || []).push(p);
  }
  const dupeKeys = Object.keys(groups).filter(k => groups[k].length > 1);
  if (!dupeKeys.length) return json({ success: true, duplicates: [] });

  // Only read the reference tabs when there's actually something to report on.
  const refData = {};
  for (const ref of PROPERTY_REFS) {
    if (refData[ref.tab] !== undefined) continue;
    // A tab that doesn't exist holds no references — that's an answer, not a failure.
    // Only a genuine read error is unknown, and that's what null means here.
    try { refData[ref.tab] = await fetchTab(env, ref.tab); }
    catch (e) { refData[ref.tab] = isMissingTabError(e) ? [] : null; }
  }

  const duplicates = dupeKeys.map(key => ({
    address: groups[key][0].Address,
    rows: groups[key].map(p => {
      const counts = {}; let total = 0;
      for (const ref of PROPERTY_REFS) {
        const rows = refData[ref.tab];
        if (!rows) { counts[ref.tab] = null; continue; }   // unreadable, not zero
        const n = rows.filter(r => String(r[ref.col] || '') === String(p.ID) && r.Active !== 'FALSE').length;
        counts[ref.tab] = n; total += n;
      }
      return {
        id: p.ID,
        unit_count_field: p.Unit_Count || '',
        owner_id: p.Owner_ID || '',
        lockbox: p.Lockbox_Code || '',
        qb_id: p.QBO_Customer_ID || '',
        refs: counts,
        total_refs: total,
      };
    }),
  }));
  return json({ success: true, duplicates });
}

// POST /admin/merge-property { from_id, to_id, apply? }
// Repoints every reference from the duplicate onto the keeper, then deactivates the
// duplicate. Reports what it WOULD do unless apply is explicitly true.
async function adminMergeProperty(env, body) {
  const fromId = String(body.from_id || '').trim();
  const toId   = String(body.to_id || '').trim();
  const apply  = body.apply === true || String(body.apply).toUpperCase() === 'TRUE';
  if (!fromId || !toId) return json({ error: 'from_id and to_id required' }, 400);
  if (fromId === toId)  return json({ error: 'from_id and to_id are the same row' }, 400);

  const properties = await fetchTab(env, 'Properties');
  const from = properties.find(p => String(p.ID) === fromId);
  const to   = properties.find(p => String(p.ID) === toId);
  if (!from) return json({ error: `No property ${fromId}` }, 404);
  if (!to)   return json({ error: `No property ${toId}` }, 404);

  // Merging two genuinely different buildings would be far worse than the duplicate.
  if (qbNormAddress(from.Address || '') !== qbNormAddress(to.Address || '')) {
    return json({ error: `"${from.Address}" and "${to.Address}" are not the same address. Refusing to merge.` }, 409);
  }
  if (qbNormAddress(from.City || '') !== qbNormAddress(to.City || '')) {
    return json({ error: `Same street address but different cities (${from.City || 'blank'} vs ${to.City || 'blank'}). Those are two different buildings.` }, 409);
  }
  if (String(from.Owner_ID || '') !== String(to.Owner_ID || '')) {
    return json({ error: `Those two rows have different owners (${from.Owner_ID || 'none'} vs ${to.Owner_ID || 'none'}). Fix the owner first — merging would move work onto the wrong ledger.` }, 409);
  }

  const plan = [];
  for (const ref of PROPERTY_REFS) {
    let rows;
    try { rows = await fetchTab(env, ref.tab); }
    catch (e) {
      // A tab this system has never created can't be holding references to anything.
      // Only a real read failure justifies stopping — that one could hide rows that
      // need moving, and a half-merge is worse than no merge.
      if (isMissingTabError(e)) continue;
      return json({ error: `Could not read ${ref.tab} — stopping rather than half-merging.` }, 500);
    }
    const hits = rows.filter(r => String(r[ref.col] || '') === fromId && r.Active !== 'FALSE');
    if (hits.length) plan.push({ tab: ref.tab, col: ref.col, ids: hits.map(r => r.ID), count: hits.length });
  }

  // Two units called "Apt 1" on one property will collide when they're linked to
  // QuickBooks: the second create hits a duplicate-name fault, resolves to the SAME
  // sub-customer, and both units end up billing to one ledger. Worth knowing before the
  // merge, not after.
  let labelClashes = [];
  try {
    const units = await fetchTab(env, 'Units');
    const labelOf = u => String(u.Unit_Label || '').trim().toLowerCase();
    const toLabels = new Set(units.filter(u => String(u.Property_ID) === toId && u.Active !== 'FALSE').map(labelOf).filter(Boolean));
    labelClashes = units.filter(u => String(u.Property_ID) === fromId && u.Active !== 'FALSE' && toLabels.has(labelOf(u)))
                        .map(u => u.Unit_Label);
  } catch (e) { /* advisory only */ }

  if (!apply) {
    return json({ success: true, applied: false, from: fromId, to: toId, address: from.Address,
                  plan, total: plan.reduce((n, p) => n + p.count, 0), label_clashes: labelClashes });
  }

  // Repoint everything BEFORE deactivating, so a failure part-way leaves both rows live
  // and the references still resolve. A half-merge that has already hidden the source
  // would strand whatever hadn't moved yet.
  const moved = [], failed = [];
  for (const step of plan) {
    for (const id of step.ids) {
      try { await updateRow(env, step.tab, id, { [step.col]: toId }); moved.push(step.tab + ':' + id); }
      catch (e) { failed.push(step.tab + ':' + id); }
    }
  }
  if (failed.length) {
    return json({ success: false, applied: true, moved: moved.length, failed,
      error: `Moved ${moved.length} reference(s) but ${failed.length} failed. Both properties are still active — nothing was hidden. Re-run to finish.` }, 500);
  }

  await updateRow(env, 'Properties', fromId, { Active: 'FALSE' });
  return json({ success: true, applied: true, from: fromId, to: toId, moved: moved.length,
                label_clashes: labelClashes,
                note: `Property ${fromId} is deactivated, not deleted — its row is still in the sheet if you need to look at it.` });
}

async function adminFixStaleTenants(env, body) {
  const apply = body && (body.apply === true || String(body.apply).toUpperCase() === 'TRUE');
  const [units, tenants] = await fetchTabs(env, ['Units','Tenants']);
  // A Tenants read that succeeds but returns nothing would classify EVERY linked unit as
  // an orphan, and one click would wipe the portfolio. Refuse before doing any work.
  if (apply && !tenants.length) {
    return json({ error: 'Refusing to clear: the Tenants tab came back empty, which is a read problem rather than a real backlog.' }, 409);
  }
  const now = new Date();
  const stale = [];

  for (const u of units) {
    const tid = String(u.Tenant_ID || '').trim();
    if (!tid) continue;
    const t = tenants.find(x => String(x.ID) === tid);
    if (!t) { stale.push({ unit: u.ID, label: u.Unit_Label || '', tenant: tid, why: 'tenant record no longer exists' }); continue; }
    const inactive = String(t.Active || '').toUpperCase() === 'FALSE';
    const movedOut = t.Move_Out_Date && !isNaN(new Date(t.Move_Out_Date + 'T23:59:59')) && new Date(t.Move_Out_Date + 'T23:59:59') < now;
    if (inactive || movedOut) {
      stale.push({ unit: u.ID, label: u.Unit_Label || '', tenant: tid,
                   name: ((t.First_Name || '') + ' ' + (t.Last_Name || '')).trim(),
                   why: movedOut ? ('moved out ' + t.Move_Out_Date) : 'marked inactive' });
    }
  }

  // A missing tenant ROW is a data anomaly that deserves a human look, not an automatic
  // clear — the link may be the only remaining evidence of who lived there.
  const clearable = stale.filter(r => r.why !== 'tenant record no longer exists');
  const needsReview = stale.filter(r => r.why === 'tenant record no longer exists');

  if (apply) {
    for (const row of clearable) { try { await updateRow(env, 'Units', row.unit, { Tenant_ID: '' }); row.cleared = true; } catch (e) { row.cleared = false; } }
  }
  // Clearing unit pointers doesn't end the exposure. Work orders keep their Tenant_ID by
  // design — that's the history — so count how many still name someone who has left. Those
  // are now phone-suppressed rather than cleared, and this is how you see the size of it.
  let woExposed = 0, contactExposed = 0;
  try {
    const wos = await fetchTab(env, 'Work_Orders');
    const gone = tenants.filter(t => !isTenantCurrent(t));
    const goneIds = new Set(gone.map(t => String(t.ID)));
    woExposed = wos.filter(w => w.Tenant_ID && goneIds.has(String(w.Tenant_ID))).length;

    // A WO_Contact_Phone typed by hand is a deliberate override and is never suppressed —
    // it's usually a super or a family member, which is the point of the field. But if
    // someone typed the TENANT's own number in there and that tenant has since left, it
    // stays reachable to vendors and no gate can tell. Detectable, so report it.
    // Compare on the last 10 digits. Tenants sits in PHONE_TABS so its numbers are stored
    // normalised as +1XXXXXXXXXX (11 digits), while WO_Contact_Phone is free text and is
    // usually typed as 10. Comparing the full strings would have matched nothing and
    // reported a reassuring zero on exactly the data this exists to find.
    const last10 = v => { const n = String(v || '').replace(/\D/g, ''); return n.length >= 10 ? n.slice(-10) : ''; };
    const goneNumbers = new Set(gone.map(t => last10(t.Phone)).filter(Boolean));
    contactExposed = wos.filter(w => { const n = last10(w.WO_Contact_Phone); return n && goneNumbers.has(n); }).length;
  } catch (e) { woExposed = -1; }

  return json({ success: true, applied: apply, count: stale.length,
                clearable: clearable.length, needs_review: needsReview.length,
                wos_naming_former_tenants: woExposed,
                wos_with_former_tenant_contact_phone: contactExposed, stale });
}

// Any PIN not matching this shape is either a pre-alphanumeric-scheme legacy value (plain
// digits, e.g. a tenant's raw phone suffix from before generatePIN existed) or otherwise
// malformed — regenerated the same way generatePIN produces a fresh one. Sep 16 2026: this
// replaced two hardcoded name-based special cases ("if name==='Adrian'/'Heather'") that were
// themselves a prior one-off patch for exactly this problem on two Owners rows — a real
// symptom that legacy PINs keep resurfacing and a name-keyed fix doesn't generalize. Also
// caught, live, while building this: two Tenants rows (James/Kelsey, same property) sharing
// the identical legacy PIN, with James's not even matching his own phone — a real collision,
// not just a cosmetic old-format issue. Regenerating off each row's own phone fixes both at
// once, since a fresh random 3-letter prefix collision is vanishingly unlikely.
const PIN_FORMAT_OK = p => /^[A-Z]{3}\d{5}$/.test(p || '');

async function adminFixPins(env, body) {
  const results=[], batchData=[];
  function colLetter(n){return n<26?String.fromCharCode(65+n):'A'+String.fromCharCode(65+n-26);}
  function queueCell(tab,sheetRowNum,colIdx,value){batchData.push({range:`${tab}!${colLetter(colIdx)}${sheetRowNum}`,values:[[value]]});}
  const vData=await sheetsRequest(env,'GET','/values/Vendors'); const vRows=vData.values||[],vH=vRows[0]||[];
  const [vPhone,vPin,vName]=[vH.indexOf('Phone'),vH.indexOf('PIN'),vH.indexOf('Name')];
  for(let i=1;i<vRows.length;i++){const row=vRows[i];if(!row[vPhone])continue;const norm=normalizePhone(row[vPhone]);if(norm&&norm!==row[vPhone]){queueCell('Vendors',i+1,vPhone,norm);results.push({tab:'Vendors',name:row[vName],field:'Phone',from:row[vPhone],to:norm});}const pin=row[vPin]||'';if(!PIN_FORMAT_OK(pin)){const np=generatePIN(norm||row[vPhone]);queueCell('Vendors',i+1,vPin,np);results.push({tab:'Vendors',name:row[vName],field:'PIN',from:pin,to:np});}}
  const oData=await sheetsRequest(env,'GET','/values/Owners');const oRows=oData.values||[],oH=oRows[0]||[];
  const [oPhone,oPin,oFirst]=[oH.indexOf('Phone'),oH.indexOf('PIN'),oH.indexOf('First_Name')];
  for(let i=1;i<oRows.length;i++){const row=oRows[i],name=row[oFirst]||'';if(row[oPhone]){const norm=normalizePhone(row[oPhone]);if(norm&&norm!==row[oPhone]){queueCell('Owners',i+1,oPhone,norm);results.push({tab:'Owners',name,field:'Phone',from:row[oPhone],to:norm});}const pin=row[oPin]||'';if(!PIN_FORMAT_OK(pin)){const np=generatePIN(norm||row[oPhone]);queueCell('Owners',i+1,oPin,np);results.push({tab:'Owners',name,field:'PIN',from:pin,to:np});}}}
  const ouData=await sheetsRequest(env,'GET','/values/Owner_Users');const ouRows=ouData.values||[],ouH=ouRows[0]||[],[ouPhone,ouPin,ouFirst]=[ouH.indexOf('Phone'),ouH.indexOf('PIN'),ouH.indexOf('First_Name')];
  let heatherInOwnUsers=false;
  for(let i=1;i<ouRows.length;i++){const row=ouRows[i];if((row[ouFirst]||'')==='Heather')heatherInOwnUsers=true;if(row[ouPhone]){const norm=normalizePhone(row[ouPhone]);if(norm&&norm!==row[ouPhone]){queueCell('Owner_Users',i+1,ouPhone,norm);results.push({tab:'Owner_Users',name:row[ouFirst],field:'Phone',from:row[ouPhone],to:norm});}if(ouPin>=0){const pin=row[ouPin]||'';if(!PIN_FORMAT_OK(pin)){const np=generatePIN(norm||row[ouPhone]);queueCell('Owner_Users',i+1,ouPin,np);results.push({tab:'Owner_Users',name:row[ouFirst],field:'PIN',from:pin,to:np});}}}}
  const tData=await sheetsRequest(env,'GET','/values/Tenants');const tRows=tData.values||[],tH=tRows[0]||[],[tPhone,tPin,tFirst]=[tH.indexOf('Phone'),tH.indexOf('PIN'),tH.indexOf('First_Name')];
  for(let i=1;i<tRows.length;i++){const row=tRows[i],rawPhone=row[tPhone]||'';if(!rawPhone)continue;const norm=normalizePhone(rawPhone);if(norm&&norm!==rawPhone){queueCell('Tenants',i+1,tPhone,norm);results.push({tab:'Tenants',name:row[tFirst],field:'Phone',from:rawPhone,to:norm});}const pin=row[tPin]||'';if(!PIN_FORMAT_OK(pin)){const np=generatePIN(norm||rawPhone);queueCell('Tenants',i+1,tPin,np);results.push({tab:'Tenants',name:row[tFirst],field:'PIN',from:pin,to:np});}}
  if(batchData.length) await sheetsRequest(env,'POST','/values:batchUpdate',{valueInputOption:'RAW',data:batchData});
  if(!heatherInOwnUsers){const heather=oRows.slice(1).map(r=>({row:r,name:r[oFirst]})).find(x=>x.name==='Heather');if(heather){const phone=normalizePhone(heather.row[oPhone]||''),pin=generatePIN(phone);await addRow(env,'Owner_Users',{Owner_ID:heather.row[oH.indexOf('ID')]||'5',First_Name:'Heather',Phone:phone,PIN:pin,Active:'TRUE'});results.push({tab:'Owner_Users',action:'created',name:'Heather',pin,phone});}}
  return json({success:true,changes:results.length,results});
}

async function adminReformatSheets(env) {
  const results=[],batch=[];
  function colLetter(n){return n<26?String.fromCharCode(65+n):'A'+String.fromCharCode(65+n-26);}
  function queueCell(tab,sheetRow,colIdx,value){batch.push({range:`${tab}!${colLetter(colIdx)}${sheetRow}`,values:[[value]]});}
  const TABS=['Properties','Units','Tenants','Owners','Owner_Users','Vendors','Work_Orders'];
  for(const tab of TABS){
    const data=await sheetsRequest(env,'GET',`/values/${tab}`);const rows=data.values||[];if(rows.length<2)continue;
    const h=rows[0],idCol=h.indexOf('ID'),phoneCol=h.indexOf('Phone'),activeCol=h.indexOf('Active'),pinCol=h.indexOf('PIN');
    let maxId=rows.slice(1).map(r=>parseInt(r[idCol]||'0')).filter(n=>Number.isFinite(n)&&n>0).reduce((a,b)=>Math.max(a,b),0);
    for(let i=1;i<rows.length;i++){const row=rows[i],sheetRow=i+1;if(row.every(cell=>!cell||cell===''))continue;
      if(idCol>=0&&(!row[idCol]||row[idCol].trim()==='')){maxId++;queueCell(tab,sheetRow,idCol,String(maxId));results.push({tab,row:sheetRow,fix:'Added ID',value:maxId});}
      if(phoneCol>=0&&row[phoneCol]){const norm=normalizePhone(row[phoneCol]);if(norm&&norm!==row[phoneCol]){queueCell(tab,sheetRow,phoneCol,norm);results.push({tab,row:sheetRow,fix:'Phone',from:row[phoneCol],to:norm});}}
      if(activeCol>=0&&row[activeCol]){const raw=String(row[activeCol]).toLowerCase().trim(),norm=(raw==='false'||raw==='0')?'FALSE':'TRUE';if(norm!==row[activeCol]){queueCell(tab,sheetRow,activeCol,norm);results.push({tab,row:sheetRow,fix:'Active',from:row[activeCol],to:norm});}}
      const PIN_TABS=['Vendors','Owner_Users','Tenants'];if(PIN_TABS.includes(tab)&&pinCol>=0&&!row[pinCol]&&row[phoneCol]){const pin=generatePIN(normalizePhone(row[phoneCol]));queueCell(tab,sheetRow,pinCol,pin);results.push({tab,row:sheetRow,fix:'Generated PIN',value:pin});}
    }
  }
  if(batch.length) await sheetsRequest(env,'POST','/values:batchUpdate',{valueInputOption:'RAW',data:batch});
  return json({success:true,fixes:results.length,results});
}

async function testDriveAccess(env) {
  const results={};
  try {
    results.propsRoot=env.DRIVE_PROPERTIES_ROOT||'NOT SET'; results.saEmail=env.GOOGLE_SA_EMAIL?env.GOOGLE_SA_EMAIL.substring(0,30)+'...':'NOT SET'; results.saKey=env.GOOGLE_SA_KEY?'SET ('+env.GOOGLE_SA_KEY.length+' chars)':'NOT SET';
    const token=await getAccessToken(env); results.token=token?'OK':'FAILED'; if(!token) return json({ok:false,results});
    const params=new URLSearchParams({q:`'${env.DRIVE_PROPERTIES_ROOT}' in parents and trashed=false`,fields:'files(id,name)',supportsAllDrives:'true',includeItemsFromAllDrives:'true',driveId:env.DRIVE_PROPERTIES_ROOT,corpora:'drive',pageSize:'3'});
    const listRes=await fetch(`https://www.googleapis.com/drive/v3/files?${params}`,{headers:{Authorization:`Bearer ${token}`}});const listData=await listRes.json();
    results.listStatus=listRes.status; results.listResult=listData.error?listData.error:`${(listData.files||[]).length} folders found`;
    const testName=`_test_${Date.now()}`;
    const createRes=await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true&fields=id,name',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({name:testName,mimeType:'application/vnd.google-apps.folder',parents:[env.DRIVE_PROPERTIES_ROOT]})});
    const createData=await createRes.json(); results.createStatus=createRes.status; results.createResult=createData.error?createData.error:`Created: ${createData.name}`;
    if(createData.id){const delRes=await fetch(`https://www.googleapis.com/drive/v3/files/${createData.id}?supportsAllDrives=true`,{method:'DELETE',headers:{Authorization:`Bearer ${token}`}});results.deleteStatus=delRes.status;}
    return json({ok:results.createStatus===200,results});
  } catch(e){return json({ok:false,error:e.message,results});}
}

// Read-only diagnostic (rule 179): a 404 from Drive's permissions/share API can mean the file
// is genuinely gone, OR that the service account has zero visibility into a file that still
// exists (Google returns 404 rather than 403 for files the caller can't see at all, to avoid
// leaking existence) — driveShareAnyone's failure alone can't tell those apart. This calls
// Drive's files.get directly per ID and reports what Drive itself says: found (+ whether it's
// merely trashed, which still counts as "gone" for sharing purposes) or the real error. Never
// writes anything — files.get is a plain read.
async function adminDriveFileCheck(env, body) {
  body = body || {};
  const ids = Array.isArray(body.file_ids) ? body.file_ids.filter(Boolean).slice(0, 50) : [];
  if (!ids.length) return json({ error: 'file_ids (array, max 50) required' }, 400);
  try {
    const token = await getAccessToken(env);
    if (!token) return json({ error: 'Failed to get Google access token' }, 500);
    const results = [];
    for (const id of ids) {
      try {
        const res = await fetch(`https://www.googleapis.com/drive/v3/files/${id}?fields=id,name,trashed,driveId,parents,mimeType,owners(emailAddress)&supportsAllDrives=true`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          results.push({
            id, found: true, trashed: !!data.trashed, name: data.name || null,
            drive_id: data.driveId || null, parents: data.parents || [],
            owners: (data.owners || []).map(o => o.emailAddress),
          });
        } else {
          let msg = `HTTP ${res.status}`;
          try { const eb = await res.json(); msg = (eb && eb.error && eb.error.message) || msg; } catch (_) {}
          results.push({ id, found: false, status: res.status, error: msg });
        }
      } catch (e) {
        results.push({ id, found: false, status: null, error: String((e && e.message) || e) });
      }
    }
    return json({ ok: true, checked: results.length, results });
  } catch (e) { return json({ error: e.message }, 500); }
}

async function createUploadSession(env, body) {
  const woId=(body.wo_id||'').trim(), propAddr=(body.property||'Unknown Property').trim()||'Unknown Property';
  const fileName=(body.file_name||`file_${Date.now()}`).trim(), mimeType=(body.mime_type||'application/octet-stream').trim();
  const fileType=(body.file_type||'other').toLowerCase(); // before | after | receipt | invoice | report | other
  try {
    const token=await getAccessToken(env), propsRoot=env.DRIVE_PROPERTIES_ROOT; if(!propsRoot) return json({error:'DRIVE_PROPERTIES_ROOT not configured'},500);
    const propFolder=await findOrCreateFolder(token,propAddr,propsRoot,propsRoot); if(!propFolder?.id) return json({error:'Cannot create property folder',addr:propAddr},500);

    // Vendor invoices/bills go to a separate internal folder — never inside the customer WO folder
    if (fileType === 'invoice' || fileType === 'bill') {
      const internalRoot = await findOrCreateFolder(token,'_Internal — Vendor Bills',propFolder.id);
      if(!internalRoot?.id) return json({error:'Cannot create internal bills folder'},500);
      const woLabel = woId||`upload_${Date.now()}`;
      const billsWOFolder = await findOrCreateFolder(token,woLabel,internalRoot.id);
      if(!billsWOFolder?.id) return json({error:'Cannot create WO bills folder'},500);
      const sessionResp=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&supportsAllDrives=true&fields=id,name,webViewLink',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Upload-Content-Type':mimeType,'Origin':body.origin||'https://ridge-co.github.io'},body:JSON.stringify({name:fileName,parents:[billsWOFolder.id]})});
      const uploadUrl=sessionResp.headers.get('Location'); if(!uploadUrl){const errBody=await sessionResp.text();return json({error:'Drive did not return upload URL',status:sessionResp.status,detail:errBody},500);}
      return json({success:true,upload_url:uploadUrl,wo_folder_id:billsWOFolder.id,wo_folder_url:billsWOFolder.webViewLink||'',file_name:fileName});
    }

    // All other file types go into the customer-facing WO folder with subfolders
    let woFolder; if(body.folder_id){woFolder={id:body.folder_id,webViewLink:body.folder_url||''};} else{const woLabel=woId||`upload_${Date.now()}`;woFolder=await findOrCreateFolder(token,woLabel,propFolder.id);if(!woFolder?.id)return json({error:'Cannot create WO folder',wo:woLabel},500);}

    // Route to subfolder by file type
    let targetFolderId = woFolder.id;
    if (fileType === 'before') {
      const sub = await findOrCreateFolder(token,'Before Photos',woFolder.id);
      if (sub?.id) targetFolderId = sub.id;
    } else if (fileType === 'after' || fileType === 'receipt') {
      const sub = await findOrCreateFolder(token,'After + Receipts',woFolder.id);
      if (sub?.id) targetFolderId = sub.id;
    }
    // report and other go flat in WO folder

    const sessionResp=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&supportsAllDrives=true&fields=id,name,webViewLink',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Upload-Content-Type':mimeType,'Origin':body.origin||'https://ridge-co.github.io'},body:JSON.stringify({name:fileName,parents:[targetFolderId]})});
    const uploadUrl=sessionResp.headers.get('Location'); if(!uploadUrl){const errBody=await sessionResp.text();return json({error:'Drive did not return upload URL',status:sessionResp.status,detail:errBody},500);}
    return json({success:true,upload_url:uploadUrl,wo_folder_id:woFolder.id,wo_folder_url:woFolder.webViewLink||'',file_name:fileName});
  } catch(e){return json({error:e.message,step:'create_upload_session'},500);}
}

// File types whose media stays PRIVATE — vendor cost docs never go anyone-with-link (FEATURE_LOG rule 13).
const NON_SHARE_FILE_TYPES = ['receipt','bill','invoice','tax_id_doc'];

async function logAttachment(env, body) {
  try {
    // Vendor Additional Work (Sep 30 2026): addon_item = the item index this photo belongs to. The row
    // below is a FIXED object, so the column must exist first and the value must be named here.
    const _addonItem = (body.addon_item === undefined || body.addon_item === null) ? '' : String(body.addon_item).trim();
    if (_addonItem !== '') { try { await ensureColumns(env, 'Attachments', ['Addon_Item']); } catch(_){} }
    await addRow(env,'Attachments',{WO_ID:body.wo_id||'',File_Name:body.file_name||'',File_Type:body.file_type||'photo',Drive_File_ID:body.file_id||'',Drive_URL:body.file_url||'',Mime_Type:body.mime_type||'',Created_Date:new Date().toISOString().split('T')[0],Active:'TRUE',Addon_Item:_addonItem});
    // Share the just-uploaded job media anyone-with-link so it opens in the portal without a Google
    // login. This is the resumable-upload path the vendor portal uses (createUploadSession → PUT → here).
    const ft=(body.file_type||'').toLowerCase();
    if(body.file_id && !NON_SHARE_FILE_TYPES.includes(ft)){ try{ const tok=await getAccessToken(env); await driveShareAnyone(tok, body.file_id); }catch(_){ /* non-fatal */ } }
    if(body.wo_folder_url){await updateWOField(env,body.wo_id,'Drive_Folder_URL',body.wo_folder_url);await updateWOField(env,body.wo_id,'Drive_Folder_ID',body.wo_folder_id||'');}
    return json({success:true});
  } catch(e){return json({error:e.message},500);}
}

// One-time backfill: share every existing job-media attachment anyone-with-link so photos/videos on
// past work orders open in the portal without a Google login. Skips vendor cost docs (receipt/bill/
// invoice — FEATURE_LOG rule 13). Idempotent: re-sharing an already-public file is harmless.
// Body: { dry_run?:true, limit?:N }. Secret-gated (admin).
// One-time repair + live diagnostic for rule 171: Payment_Source has never actually existed as
// a column on the live Receipts sheet (confirmed by reading real receipt rows back from prod —
// the key is absent, not blank, on every single row going back to August), so `addReceipt`'s
// swallowed ensureColumns call has been silently dropping every vendor's/hub's payment-source
// selection on write since the feature was added. This calls ensureColumns directly with NO
// swallowing catch, so if it fails again the real Sheets API error comes back in the response
// instead of vanishing. Schema-only — adds a header cell if missing, touches no row data.
async function adminEnsureReceiptsPaymentSource(env) {
  const before = await sheetsRequest(env, 'GET', `/values/Receipts`);
  const headersBefore = (before.values && before.values[0]) || [];
  if (headersBefore.includes('Payment_Source')) {
    return json({ success: true, already_present: true, headers: headersBefore });
  }
  await ensureColumns(env, 'Receipts', ['Payment_Source']);
  const after = await sheetsRequest(env, 'GET', `/values/Receipts`);
  const headersAfter = (after.values && after.values[0]) || [];
  return json({
    success: headersAfter.includes('Payment_Source'),
    headers_before: headersBefore,
    headers_after: headersAfter,
  });
}

async function adminShareAttachments(env, body) {
  const _t0 = Date.now();
  body = body || {};
  const dryRun = body.dry_run === true;
  const limit = Number.isInteger(body.limit) && body.limit > 0 ? body.limit : 0;
  // Rule 177: without an offset, every call — real or dry-run — always considered the SAME
  // first `limit` shareable rows in the table, from row 1, every time. Calling this again with
  // the same limit (exactly what the tool's own UI text told Brett to do — "run again if more
  // remain") never actually advanced past that first window; it just re-checked/re-shared the
  // same files. `offset` lets a caller say "skip the first N shareable files, I already handled
  // those" so consecutive batches genuinely walk the whole table instead of looping on batch 1.
  const offset = Number.isInteger(body.offset) && body.offset > 0 ? body.offset : 0;
  try {
    const rows = await fetchTab(env, 'Attachments');
    const token = await getAccessToken(env);
    if (!token) return json({ error: 'Failed to get Google access token' }, 500);
    // Rule 176: `limit` used to be checked only against `shared`, which dry-run never
    // increments (it always `continue`d before the share call) — so limit was silently a
    // no-op in dry-run mode and every dry-run response was identical regardless of the value
    // typed in. It's now checked against `considered` (files this batch actually looks at),
    // so it bounds real work in BOTH modes: real Drive share calls when not dry-run, and real
    // Drive permission-list lookups (see driveIsSharedAnyone below) when dry-run. Dry-run also
    // no longer reports a tautological `shared: 0` — it does a genuine read-only check per
    // considered file and reports `already_shared` / `needs_sharing`, so Brett can tell
    // whether the sweep would actually do anything before running it for real.
    let scanned = 0, shareable = 0, skippedInternal = 0, skippedNoId = 0, skippedKnownMissing = 0;
    let considered = 0, alreadyShared = 0, shared = 0, failed = 0;
    const failures = [];
    const failedByStatus = {};
    for (const r of rows) {
      scanned++;
      if (r.Active === 'FALSE') continue;
      const ft = (r.File_Type || '').toLowerCase();
      if (NON_SHARE_FILE_TYPES.includes(ft)) { skippedInternal++; continue; }
      const fileId = r.Drive_File_ID || '';
      if (!fileId) { skippedNoId++; continue; }
      // Ops_Build_Queue #23 (Sep 19 2026) — documented root cause of the ~20% failure rate:
      // real, permanently-unreachable Drive files (deleted, or moved somewhere this service
      // account can no longer see — /admin/drive-file-check tells the two apart), not a
      // transient auth/path bug. Without this, the same handful of files fail on every single
      // batch forever. A file gets marked here the first time a REAL (non-dry-run) share call
      // comes back 404 — one call already includes driveShareAnyoneVerbose's own 2-attempt
      // retry, so a 404 surviving that is a real signal, not noise (a judgment call, not a
      // Brett-specified threshold — easy to raise if a false-positive ever turns up). Once
      // marked, future batches skip it instead of re-failing on it — it stops counting toward
      // shareable/failed and shows up in its own skipped_known_missing count instead, so Brett
      // can see how many attachments genuinely need re-uploading vs. how many are still a real,
      // retryable failure.
      if (r.Drive_File_Missing === 'TRUE') { skippedKnownMissing++; continue; }
      shareable++;
      if (shareable <= offset) continue;         // already handled by an earlier batch
      if (limit && considered >= limit) continue; // this batch's window is full
      considered++;
      if (dryRun) {
        const isShared = await driveIsSharedAnyone(token, fileId);
        if (isShared) alreadyShared++;
        continue;
      }
      const shareResult = await driveShareAnyoneVerbose(token, fileId);
      if (shareResult.ok) { shared++; continue; }
      failed++;
      const statusKey = String(shareResult.status || 'unknown');
      failedByStatus[statusKey] = (failedByStatus[statusKey] || 0) + 1;
      if (failures.length < 25) failures.push({ wo: r.WO_ID || '', file: r.File_Name || '', id: fileId, status: shareResult.status, error: shareResult.error });
      if (shareResult.status === 404) {
        try {
          await ensureColumns(env, 'Attachments', ['Drive_File_Missing']);
          await updateRow(env, 'Attachments', r.ID, { Drive_File_Missing: 'TRUE' });
        } catch (_) { /* best-effort — a failed mark just means it's re-tried (and re-marked) next batch, not silently lost */ }
      }
    }
    const remainingAfterBatch = Math.max(0, shareable - offset - considered);
    const nextOffset = offset + considered;
    const statusBreakdown = Object.entries(failedByStatus).map(([s, c]) => `${s}:${c}`).join(',');
    try { await logTelemetry(env, { Source:'worker', Job_Type:'admin_share_attachments', Skill_Or_Endpoint:'/admin/share-attachments', Success: failed ? 'FALSE' : 'TRUE', Latency_ms: Date.now()-_t0, Notes:`dry_run=${dryRun} offset=${offset} shareable=${shareable} considered=${considered} shared=${shared} already_shared=${alreadyShared} failed=${failed}${statusBreakdown ? ' failed_by_status=' + statusBreakdown : ''} known_missing=${skippedKnownMissing}` }); } catch(_){}
    const out = {
      success: true,
      dry_run: dryRun,
      scanned,
      shareable,
      offset,
      limit: limit || null,
      considered_this_batch: considered,
      next_offset: nextOffset,
      remaining_after_this_batch: remainingAfterBatch,
      skipped_internal: skippedInternal,
      skipped_no_id: skippedNoId,
      skipped_known_missing: skippedKnownMissing,
      failed,
      failed_by_status: failedByStatus,
      failures,
    };
    if (dryRun) {
      out.already_shared = alreadyShared;
      out.needs_sharing = considered - alreadyShared;
    } else {
      out.shared = shared;
    }
    return json(out);
  } catch (e) { return json({ error: e.message }, 500); }
}

// ── SCHEDULING ───────────────────────────────────────────────

async function scheduleWO(env, body) {
  const _t0 = Date.now();
  const workorders=await fetchTab(env,'Work_Orders'); const wo=workorders.find(w=>w.ID===body.wo_id); if(!wo) return json({error:'WO not found'},404);
  const isWithinHour=body.window==='Within 1 hour', today=new Date().toISOString().split('T')[0], schedDate=body.date||today;
  const updates={Scheduled_Date:schedDate,Scheduled_Window:body.window||''};
  if(isWithinHour&&WOStatus.sets.PRE_START.includes(wo.Status)) updates.Status='In Progress';
  await updateWOFields(env,body.wo_id,updates);
  await logWOAudit(env,body.wo_id,body.updated_by||'admin',body.updated_by_role||'admin','Scheduled',wo.Scheduled_Date||'',schedDate+' '+(body.window||''),isWithinHour?'On my way notification':'Appointment scheduled');
  // Vendor nudge clock reset (Sep 14 2026) — a vendor setting a schedule is real activity.
  if (body.updated_by_role === 'vendor') { await resetVendorNudgeClock(env, body.wo_id, body.vendor_id || wo.Vendor_ID); }
  let tenantSMSSent=false, notifyQueued=false;
  const [units,tenants,properties,owners]=await fetchTabs(env, ['Units','Tenants','Properties','Owners']);
  const unit=units.find(u=>u.ID===wo.Unit_ID), property=properties.find(p=>p.ID===wo.Property_ID);
  const owner=property?owners.find(o=>o.ID===property.Owner_ID):null;
  if(body.notify_tenant&&wo.Tenant_Notify_Updates!=='FALSE'){
    // CAP-036 #21: every active tenant in the unit, not just the one Units.Tenant_ID names.
    const address=property?property.Address+(unit&&unit.Unit_Label?' '+formatUnitLabel(unit.Unit_Label):''):'your address';
    for (const tenant of tenantsForDispatch(tenants, unit, wo)) {
    if(isTenantNotifiable(tenant,wo)){
      const dateStr=new Date(schedDate+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});
      // woJobLabel keeps two same-trade/same-address jobs distinguishable in the text.
      const msg=isWithinHour?`Hi ${tenant.First_Name}, your technician is on the way and will arrive within 1 hour for your ${woJobLabel(wo)} at ${address}. Ref: ${body.wo_id}.`:`Hi ${tenant.First_Name}, your ${woJobLabel(wo)} at ${address} is scheduled for ${dateStr}, ${body.window}. Ref: ${body.wo_id}.`;
      const now=new Date(), tomorrow=new Date(now); tomorrow.setDate(tomorrow.getDate()+1); const tomorrowStr=tomorrow.toISOString().split('T')[0];
      // TWILIO_SMS_BUILD_BRIEF_v1.0 — tenant_job_scheduled. Same-day/within-hour sends
      // immediately through the gate; anything further out still uses the pre-existing
      // Notification_Queue defer-to-a-reasonable-hour mechanism (unrelated to and unchanged
      // by this build) — but the deferred fire (processPendingNotifications, below) now
      // re-evaluates the SAME gate at actual send time instead of sending raw, so a message
      // queued days ahead still honors whatever Global/Property/Customer/Tenant state is
      // true when it actually goes out, not what was true when it was scheduled.
      if(schedDate===today||isWithinHour){
        const r = await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'tenant_job_scheduled', recipient_type: 'tenant', tenant, owner, property, message_body: msg });
        if (r.sent) tenantSMSSent = true;
      } else {
        let sendAfter;if(schedDate===tomorrowStr){sendAfter=new Date(now.getTime()+3600000).toISOString();}else{const fivePM=new Date(now);fivePM.setUTCHours(21,0,0,0);if(now<fivePM){sendAfter=fivePM.toISOString();}else{const eightAM=new Date(tomorrow);eightAM.setUTCHours(13,0,0,0);sendAfter=eightAM.toISOString();}}
        await queueNotification(env,body.wo_id,'tenant_schedule',tenant.Phone,msg,sendAfter,{ message_type: 'tenant_job_scheduled', recipient_type: 'tenant', recipient_id: tenant.ID, property_id: property ? property.ID : '' });
        notifyQueued=true;
      }
    }
    }
  }
  // Owner Scheduled (Sep 15 2026 — real gap found live-testing rule 168): the owner-scheduled
  // message was wired into updateStatus, gated on body.status==='Scheduled' — but nothing in
  // this codebase ever actually sets Status to that literal value (scheduling only ever
  // touches Scheduled_Date/Scheduled_Window here in scheduleWO, independent of Status). That
  // made the notification permanently unreachable, not just for this rebuild but for however
  // long it existed before. Fixed by triggering it from the actual code path that handles
  // scheduling, independent of notify_tenant (an owner's own preference, not tied to whether
  // the tenant toggle happens to be on) and independent of isWithinHour (Brett's own event set
  // — Received/Scheduled/Complete/On_Hold — doesn't have a distinct "technician en route" tier).
  let ownerSMSSent=false;
  if (property && owner?.Phone) {
    const notify = await shouldNotifyOwner(env, wo, 'Scheduled');
    if (notify) {
      const dateStr = new Date(schedDate+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});
      const ownerMsg = `Hi ${owner.First_Name}, work order ${body.wo_id} — ${woJobLabel(wo)} at ${propUnitText(property, unit)} — is scheduled for ${dateStr}, ${body.window}, subject to change. Ref: ${body.wo_id}.`;
      const r = await smsGatedSend(env, { wo_id: body.wo_id, message_type: 'owner_job_scheduled', recipient_type: 'owner', owner, property, message_body: ownerMsg });
      ownerSMSSent = r.sent;
      if (r.sent) await updateWOFields(env, body.wo_id, { Owner_Notified: 'TRUE' });
    }
  }
  try { await logTelemetry(env, { Source:'worker', Job_Type:'wo_schedule', Skill_Or_Endpoint:'/schedule', Success:'TRUE', Latency_ms: Date.now()-_t0, Notes:`window=${body.window||''} new_status=${updates.Status||wo.Status||''}` }); } catch(_){}
  return json({success:true,tenant_sms:tenantSMSSent,notify_queued:notifyQueued,owner_sms:ownerSMSSent,new_status:updates.Status||wo.Status});
}

// Notification_Queue — a send-TIMING defer (day-before-5pm / day-of-8am cutoff so a schedule
// text doesn't land at an odd hour days in advance), separate from and unrelated to the new
// Message_Queue gate/review system above. Extended (additive columns) to carry enough context
// (Message_Type/Recipient_Type/Recipient_ID/Property_ID) for processPendingNotifications to
// re-run the FULL gate at actual fire time rather than sending raw. Self-provisions via
// ensureTab/ensureColumns (FL rule 37/78) — previously this silently no-op'd if the tab didn't
// exist yet (`if(!rows.length)return` on a GET that would have thrown first), so nothing queued
// here had ever actually been confirmed to write.
const NOTIF_QUEUE_TAB = 'Notification_Queue';
const NOTIF_QUEUE_COLS = ['ID','WO_ID','Type','Phone','Message','Send_After','Sent','Created_At','Message_Type','Recipient_Type','Recipient_ID','Property_ID'];
let _notifQueueReady = false;

async function queueNotification(env, woId, type, phone, message, sendAfter, ctx) {
  ctx = ctx || {};
  try {
    if (!_notifQueueReady) { await ensureTab(env, NOTIF_QUEUE_TAB, NOTIF_QUEUE_COLS); _notifQueueReady = true; }
    await ensureColumns(env, NOTIF_QUEUE_TAB, NOTIF_QUEUE_COLS);
    const data=await sheetsRequest(env,'GET',`/values/${NOTIF_QUEUE_TAB}`);const rows=data.values||[];
    const headers=rows[0]&&rows[0].length?rows[0]:NOTIF_QUEUE_COLS,now=new Date().toISOString();
    const rowObj={ID:String(nextSafeId(rows)),WO_ID:woId,Type:type,Phone:phone,Message:message,Send_After:sendAfter,Sent:'FALSE',Created_At:now,
      Message_Type:ctx.message_type||'',Recipient_Type:ctx.recipient_type||'',Recipient_ID:ctx.recipient_id||'',Property_ID:ctx.property_id||''};
    const newRow=headers.map(h=>rowObj[h]??'');
    await sheetsRequest(env,'POST',`/values/${NOTIF_QUEUE_TAB}:append?valueInputOption=RAW`,{values:[newRow]});
  } catch(e){/* non-fatal */}
}

let __pendingNotifAt = 0; // last time GET /notifications/pending actually ran (per isolate)
async function processPendingNotifications(env) {
  try {
    const data=await sheetsRequest(env,'GET',`/values/${NOTIF_QUEUE_TAB}`); if(!data.values||data.values.length<2) return json({processed:0});
    const [headers,...rows]=data.values;
    const iPhone=headers.indexOf('Phone'),iMsg=headers.indexOf('Message'),iAfter=headers.indexOf('Send_After'),iSent=headers.indexOf('Sent'),iWO=headers.indexOf('WO_ID'),
      iMType=headers.indexOf('Message_Type'),iRType=headers.indexOf('Recipient_Type'),iRId=headers.indexOf('Recipient_ID'),iPId=headers.indexOf('Property_ID');
    const now=new Date(); let processed=0;
    let tenants=null, owners=null, properties=null, vendors=null, workorders=null; // lazy-loaded once, only if a gated row is actually due
    for(const row of rows){
      if((row[iSent]||'')==='TRUE') continue;
      const sendAfter=row[iAfter]?new Date(row[iAfter]):null; if(sendAfter&&sendAfter>now) continue;
      const phone=row[iPhone],msg=row[iMsg]; if(!phone||!msg) continue;
      const messageType = iMType>=0 ? row[iMType] : '';
      if (messageType) {
        // New-style row (TWILIO_SMS_BUILD_BRIEF_v1.0) — re-evaluate the full gate NOW, at
        // actual fire time, not at the time it was originally queued.
        const recipientType = row[iRType], recipientId = row[iRId], propertyId = row[iPId];
        if (!tenants) { [tenants,owners,properties,vendors] = await fetchTabs(env, ['Tenants','Owners','Properties','Vendors']); }
        // tenant_job_received (Sep 14 2026): queued 8h out specifically so the tenant_job_
        // assigned message can supersede/"bump" it if the WO gets assigned before the 8h is
        // up — a tenant doesn't need "we got your request" AND "we assigned someone" back to
        // back. Checked at actual fire time (not queue time) since assignment could happen
        // any time in that 8h window. workorders is lazy-loaded here too, only when an actual
        // tenant_job_received row is due, so every other message type pays zero extra cost.
        if (messageType === 'tenant_job_received') {
          if (!workorders) { workorders = await fetchTab(env, 'Work_Orders'); }
          const liveWO = workorders.find(w => w.ID === (row[iWO] || ''));
          if (liveWO && liveWO.Vendor_ID) {
            const rowIndex2 = rows.indexOf(row);
            await sheetsRequest(env,'POST',`/values:batchUpdate`,{valueInputOption:'RAW',data:[{range:`${NOTIF_QUEUE_TAB}!${col(iSent)}${rowIndex2+2}`,values:[['TRUE']]}]});
            continue; // superseded — already assigned, no separate "we received it" needed
          }
        }
        const property = properties.find(p=>p.ID===propertyId);
        const owner = property ? owners.find(o=>o.ID===property.Owner_ID) : null;
        const tenant = recipientType==='tenant' ? tenants.find(t=>t.ID===recipientId) : null;
        const vendor = recipientType==='vendor' ? vendors.find(v=>v.ID===recipientId) : null;
        await smsGatedSend(env, { wo_id: row[iWO]||'', message_type: messageType, recipient_type: recipientType, tenant, owner, property, vendor, message_body: msg });
      } else {
        // Legacy row shape (pre-dates this build) — fall back to the old raw send so nothing
        // already queued is silently dropped. Still honors sendSMS's own Global kill switch.
        await sendSMS(env,phone,msg);await logSMS(env,row[iWO]||'','queued_notification','',phone,msg);
      }
      const rowIndex=rows.indexOf(row);await sheetsRequest(env,'POST',`/values:batchUpdate`,{valueInputOption:'RAW',data:[{range:`${NOTIF_QUEUE_TAB}!${col(iSent)}${rowIndex+2}`,values:[['TRUE']]}]});processed++;
    }
    return json({processed});
  } catch(e){return json({processed:0,error:e.message});}
}

// ── Vendor nudge/request system (Sep 14 2026, Brett) ───────────────────────────────────────
// Automatic status-update clock (created on assignment, resets on real vendor activity, quiets
// while a future Scheduled_Date is pending, caps at 5 nudges then flags Brett instead of a
// 6th) plus manual "Request photos"/"Request invoice" buttons. One shared tab, one shared
// sweep, one shared 5-nudge safety cap across all three request types.
const VENDOR_REQ_TAB = 'Vendor_Requests';
const VENDOR_REQ_COLS = ['ID','WO_ID','Vendor_ID','Request_Type','Status','Nudge_Count','First_Nudge_At','Next_Nudge_At','Last_Activity_At','Satisfied_Date','Created_Date','Active'];
const VENDOR_NUDGE_MAX = 5;           // after this many sends with no resolution, flag Brett instead of nudging again
const VENDOR_NUDGE_REPEAT_HOURS = 24; // status_update: daily, per Brett
const VENDOR_MANUAL_REPEAT_HOURS = 48; // photos/invoice: Brett didn't specify a cadence for
  // these two — 2 days is a reasonable middle ground between the daily auto-clock (which
  // exists specifically to chase a QUIET vendor) and a full week; easy to tune if wrong.
// Satisfied-condition status sets (Sep 16 2026, Brett — replaces the earlier Vendor_Bills-row
// check, which stalled indefinitely once a WO moved past 'Complete' to 'Invoiced': the status
// nudge is answered the moment the WO reaches Complete or later; the invoice nudge is a
// separate, later-starting ask that isn't answered until the WO actually reaches Invoiced or
// later. Cancelled/Declined already short-circuit BOTH types earlier in the sweep, unchanged.
const WO_STATUS_COMPLETE_OR_LATER = WOStatus.sets.COMPLETE_OR_LATER;
const WO_STATUS_INVOICED_OR_LATER = WOStatus.sets.INVOICED_OR_LATER;
let _vendorReqReady = false;
async function ensureVendorReqTab(env) {
  if (!_vendorReqReady) { await ensureTab(env, VENDOR_REQ_TAB, VENDOR_REQ_COLS); _vendorReqReady = true; }
  await ensureColumns(env, VENDOR_REQ_TAB, VENDOR_REQ_COLS);
}
async function vendorBillExistsForWO(env, woId) {
  const bills = await fetchTab(env, 'Vendor_Bills');
  return bills.some(b => b.WO_ID === woId && b.Active !== 'FALSE');
}

// Called from assignVendor on every successful assignment (notify or silent — the clock
// tracks actual work progress, not whether a text went out). Any existing OPEN status_update
// row for this WO (any vendor — e.g. a prior assignee before a reassignment) is closed first,
// since chasing an old assignee for a job they're no longer on doesn't make sense.
async function createVendorNudgeClock(env, woId, vendorId) {
  try {
    await ensureVendorReqTab(env);
    const rows = await fetchTab(env, VENDOR_REQ_TAB);
    for (const r of rows) {
      if (r.WO_ID === woId && r.Request_Type === 'status_update' && r.Status === 'open') {
        await updateRow(env, VENDOR_REQ_TAB, r.ID, { Status: 'cancelled' });
      }
    }
    const now = new Date();
    const firstNudge = new Date(Math.max(next9amET(now).getTime(), now.getTime() + 16*3600000));
    await addRow(env, VENDOR_REQ_TAB, {
      WO_ID: woId, Vendor_ID: vendorId, Request_Type: 'status_update', Status: 'open',
      Nudge_Count: '0', First_Nudge_At: firstNudge.toISOString(), Next_Nudge_At: firstNudge.toISOString(),
      Last_Activity_At: now.toISOString(), Satisfied_Date: '', Created_Date: now.toISOString(), Active: 'TRUE',
    });
  } catch (e) { /* non-fatal — assignment itself already succeeded */ }
}

// Called from updateStatus/scheduleWO when updated_by_role==='vendor' — real vendor activity
// resets the clock back to a fresh start (count back to 0, same first-nudge formula as a new
// assignment) rather than just pushing the next check out a day. A vendor actively engaging is
// exactly the case the nudge system exists to NOT bother.
async function resetVendorNudgeClock(env, woId, vendorId) {
  try {
    await ensureVendorReqTab(env);
    const rows = await fetchTab(env, VENDOR_REQ_TAB);
    const row = rows.find(r => r.WO_ID === woId && r.Request_Type === 'status_update' && r.Status === 'open' && (!vendorId || r.Vendor_ID === vendorId));
    if (!row) return;
    const now = new Date();
    const nextNudge = new Date(Math.max(next9amET(now).getTime(), now.getTime() + 16*3600000));
    await updateRow(env, VENDOR_REQ_TAB, row.ID, { Nudge_Count: '0', Next_Nudge_At: nextNudge.toISOString(), Last_Activity_At: now.toISOString() });
  } catch (e) { /* non-fatal */ }
}

// POST /vendor-request/create { wo_id, vendor_id, request_type: 'photos'|'invoice' } — the
// manual buttons. If a matching open request already exists, this just resends immediately
// rather than creating a duplicate row (one outstanding ask per WO+vendor+type at a time).
async function createVendorRequest(env, body) {
  const woId = body.wo_id, vendorId = body.vendor_id, reqType = body.request_type;
  if (!woId || !vendorId || !['photos','invoice'].includes(reqType)) return json({ error: 'wo_id, vendor_id, and request_type (photos|invoice) are required' }, 400);
  await ensureVendorReqTab(env);
  const [workorders, vendors, properties, units, rows] = await Promise.all([
    fetchTab(env, 'Work_Orders'), fetchTab(env, 'Vendors'), fetchTab(env, 'Properties'), fetchTab(env, 'Units'), fetchTab(env, VENDOR_REQ_TAB),
  ]);
  const wo = findWO(workorders, woId); if (!wo) return json({ error: 'WO not found' }, 404);
  const vendor = vendors.find(v => v.ID === vendorId); if (!vendor) return json({ error: 'Vendor not found' }, 404);
  if (!vendor.Phone) return json({ error: 'Vendor has no phone number on file' }, 400);
  const property = properties.find(p => p.ID === wo.Property_ID);
  const unit = units.find(u => u.ID === wo.Unit_ID);
  const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'the property';
  const vname = (vendor.First_Name || (vendor.Name||'').split(' ')[0] || 'there');
  const msg = reqType === 'photos'
    ? `Hi ${vname}, could you upload before/after photos for ${woId} at ${address} when you get a chance? You can add them from your vendor portal. ${vendorPortalLink(woId)}`
    : `Hi ${vname}, please submit your invoice for ${woId} at ${address} when you get a chance — you can do this from your vendor portal. ${vendorPortalLink(woId)}`;
  const r = await smsGatedSend(env, { wo_id: woId, message_type: `vendor_request_${reqType}`, recipient_type: 'vendor', vendor, message_body: msg });
  // "Dispatched" means the message actually entered the pipeline — either sent outright, or
  // held for quiet hours (which WILL send once quiet hours end, per rule 166's own release
  // sweep). Only a genuine gate block or send failure should NOT count toward the nudge
  // budget/timer — a quiet-hours hold isn't that, and treating it as "didn't happen" would let
  // the automatic sweep fire ANOTHER nudge on top of the one already queued for 9am release.
  const dispatched = r.sent || r.held_for_quiet_hours;
  const now = new Date();
  const existing = rows.find(x => x.WO_ID === woId && x.Vendor_ID === vendorId && x.Request_Type === reqType && x.Status === 'open');
  const nextNudge = new Date(now.getTime() + VENDOR_MANUAL_REPEAT_HOURS*3600000).toISOString();
  if (existing) {
    await updateRow(env, VENDOR_REQ_TAB, existing.ID, { Nudge_Count: String((parseInt(existing.Nudge_Count,10)||0) + (dispatched?1:0)), Next_Nudge_At: nextNudge, Last_Activity_At: now.toISOString() });
  } else {
    await addRow(env, VENDOR_REQ_TAB, {
      WO_ID: woId, Vendor_ID: vendorId, Request_Type: reqType, Status: 'open',
      Nudge_Count: dispatched ? '1' : '0', First_Nudge_At: now.toISOString(), Next_Nudge_At: nextNudge,
      Last_Activity_At: now.toISOString(), Satisfied_Date: '', Created_Date: now.toISOString(), Active: 'TRUE',
    });
  }
  return json({ success: true, sent: r.sent, held_for_quiet_hours: !!r.held_for_quiet_hours, test_mode: r.test_mode, gate_snapshot: r.gate_snapshot });
}

// PURE — true while an add-on child has not been approved (no vendor nudges yet).
function addonNudgeHold(wo) { return !!wo && String(wo.Type || '') === 'addon' && String(wo.Approval_Stage || '') !== 'Approved'; }

// Called from the scheduler's `sweep` job (POST /cron/run; also manual POST /cron/sweep). Handles all 3 request types
// through one loop: satisfied-checks first (so a row that's already resolved never nudges
// again even if it's technically "due"), then the type-specific quiet/nudge/cap logic.
async function processVendorNudges(env) {
  await ensureVendorReqTab(env);
  const now = new Date();
  const [rows, workorders, vendors, properties, units, config] = await Promise.all([
    fetchTab(env, VENDOR_REQ_TAB), fetchTab(env, 'Work_Orders'), fetchTab(env, 'Vendors'), fetchTab(env, 'Properties'), fetchTab(env, 'Units'), fetchConfig(env),
  ]);
  const due = rows.filter(r => r.Status === 'open' && r.Next_Nudge_At && new Date(r.Next_Nudge_At) <= now);
  const results = [];
  for (const row of due) {
    const wo = findWO(workorders, row.WO_ID);
    const vendor = vendors.find(v => v.ID === row.Vendor_ID);
    // WO gone, voided, or vendor gone — nothing left to chase.
    if (!wo || wo.Voided === 'TRUE' || !vendor) { await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'cancelled' }); results.push({ id: row.ID, action: 'cancelled_missing' }); continue; }
    // Cancelled/Declined stop ALL open request types for this WO outright — nothing left worth
    // chasing a vendor for on a job that isn't happening (per Brett, Sep 16 2026).
    if (WOStatus.sets.DEAD.includes(wo.Status)) { await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'cancelled' }); results.push({ id: row.ID, action: 'cancelled_wo_status' }); continue; }
    // Additional work (Sep 30 2026): an add-on child is not a real job until Brett approves it. assignVendor(notify:false)
    // at /start opened the status clock, so: a declined add-on (stage cleared) closes its clock, a pending / needs-info
    // one is skipped (no nudge, nothing written) and starts nudging only once Approval_Stage is 'Approved'.
    if (addonNudgeHold(wo)) {
      if (String(wo.Approval_Stage || '') === '') { await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'cancelled' }); results.push({ id: row.ID, action: 'cancelled_addon_declined' }); }
      else results.push({ id: row.ID, action: 'skipped_addon_unapproved' });
      continue;
    }
    // status_update is answered the moment the WO reaches Complete or later — the vendor told
    // us what we needed to know, regardless of billing. If invoicing isn't done yet, hand off
    // to a fresh 'invoice' request (below) rather than going silent — that's the ask that
    // should now persist until the WO is actually Invoiced.
    if (row.Request_Type === 'status_update' && WO_STATUS_COMPLETE_OR_LATER.includes(wo.Status)) {
      await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'satisfied', Satisfied_Date: now.toISOString() });
      results.push({ id: row.ID, action: 'satisfied_complete' });
      if (!WO_STATUS_INVOICED_OR_LATER.includes(wo.Status)) {
        const hasOpenInvoiceReq = rows.some(x => x.WO_ID === row.WO_ID && x.Vendor_ID === row.Vendor_ID && x.Request_Type === 'invoice' && x.Status === 'open');
        if (!hasOpenInvoiceReq) {
          await addRow(env, VENDOR_REQ_TAB, {
            WO_ID: row.WO_ID, Vendor_ID: row.Vendor_ID, Request_Type: 'invoice', Status: 'open',
            Nudge_Count: '0', First_Nudge_At: now.toISOString(), Next_Nudge_At: now.toISOString(),
            Last_Activity_At: now.toISOString(), Satisfied_Date: '', Created_Date: now.toISOString(), Active: 'TRUE',
          });
          results.push({ id: row.ID, action: 'invoice_chase_started' });
        }
      }
      continue;
    }
    // invoice persists specifically until the WO is Invoiced or later — a Vendor_Bills row
    // existing isn't the same as the WO actually being invoiced (see WO-1200/1201, Sep 16),
    // so the status field is the authoritative signal here, not the bill's mere presence.
    if (row.Request_Type === 'invoice' && WO_STATUS_INVOICED_OR_LATER.includes(wo.Status)) {
      await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'satisfied', Satisfied_Date: now.toISOString() });
      results.push({ id: row.ID, action: 'satisfied_invoiced' }); continue;
    }
    if (row.Request_Type === 'photos') {
      const attachments = await fetchTab(env, 'Attachments'); // only fetched for an actually-due photos row
      const hasNewPhoto = attachments.some(a => a.WO_ID === row.WO_ID && a.Active !== 'FALSE' && ['before','after','photo'].includes((a.File_Type||'').toLowerCase()) && a.Created_Date && new Date(a.Created_Date) >= new Date(row.Created_Date));
      if (hasNewPhoto) { await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'satisfied', Satisfied_Date: now.toISOString() }); results.push({ id: row.ID, action: 'satisfied_photos' }); continue; }
    }
    // status_update quiet period: a future Scheduled_Date pauses nudging until that date
    // arrives — pushed forward rather than re-checked every sweep in the meantime.
    if (row.Request_Type === 'status_update' && wo.Scheduled_Date) {
      const sched = new Date(wo.Scheduled_Date + 'T12:00:00Z');
      if (sched > now) { await updateRow(env, VENDOR_REQ_TAB, row.ID, { Next_Nudge_At: sched.toISOString() }); results.push({ id: row.ID, action: 'quieted_for_schedule' }); continue; }
    }
    const nudgeCount = parseInt(row.Nudge_Count, 10) || 0;
    if (nudgeCount >= VENDOR_NUDGE_MAX) {
      await updateRow(env, VENDOR_REQ_TAB, row.ID, { Status: 'flagged' });
      const property = properties.find(p => p.ID === wo.Property_ID);
      const flagMsg = `⚠️ ${vendor.Name||vendor.First_Name||'Vendor'} hasn't responded after ${VENDOR_NUDGE_MAX} reminders on ${row.WO_ID}${property?' at '+property.Address:''} (${row.Request_Type}). May need a personal follow-up.`;
      if (config.admin_phone) await sendSMS(env, config.admin_phone, flagMsg);
      results.push({ id: row.ID, action: 'flagged_to_brett' }); continue;
    }
    const property = properties.find(p => p.ID === wo.Property_ID);
    const unit = units.find(u => u.ID === wo.Unit_ID);
    const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'the property';
    const vname = vendor.First_Name || (vendor.Name||'').split(' ')[0] || 'there';
    let msg, msgType, repeatHours;
    if (row.Request_Type === 'status_update') {
      // By the time this fires, the WO is confirmed still pre-Complete (the satisfied-check
      // above already peeled off anything Complete-or-later into an invoice chase instead).
      // Coaching language per Brett (Sep 16 2026): walk the vendor through the actual portal
      // steps we're waiting on, not just a bare "any update?" ask.
      msg = `Hi ${vname}, checking in on ${row.WO_ID} — ${woJobLabel(wo)} at ${address}. Remember to add the schedule for the job in your portal, and mark it Complete once the work's done — then you'll just need to submit your invoice. ${vendorPortalLink(row.WO_ID)}`;
      msgType = 'vendor_nudge_status'; repeatHours = VENDOR_NUDGE_REPEAT_HOURS;
    } else if (row.Request_Type === 'photos') {
      msg = `Hi ${vname}, following up — could you upload before/after photos for ${row.WO_ID} at ${address}? ${vendorPortalLink(row.WO_ID)}`;
      msgType = 'vendor_nudge_photos'; repeatHours = VENDOR_MANUAL_REPEAT_HOURS;
    } else {
      msg = `Hi ${vname}, following up — please submit your invoice for ${row.WO_ID} at ${address} when you get a chance. ${vendorPortalLink(row.WO_ID)}`;
      msgType = 'vendor_nudge_invoice'; repeatHours = VENDOR_MANUAL_REPEAT_HOURS;
    }
    const r = await smsGatedSend(env, { wo_id: row.WO_ID, message_type: msgType, recipient_type: 'vendor', vendor, message_body: msg });
    // Same dispatched-vs-sent distinction as createVendorRequest above — a quiet-hours hold
    // still counts and still advances the timer, since the message IS queued to go out.
    const dispatched = r.sent || r.held_for_quiet_hours;
    await updateRow(env, VENDOR_REQ_TAB, row.ID, {
      Nudge_Count: String(nudgeCount + (dispatched ? 1 : 0)),
      Next_Nudge_At: new Date(now.getTime() + repeatHours*3600000).toISOString(),
    });
    results.push({ id: row.ID, action: dispatched ? 'nudged' : 'nudge_blocked', gate_snapshot: r.gate_snapshot });
  }
  return { checked: due.length, results };
}
// ── Vendor Task Requests (CAP-036 #12, Sep 24 2026) ─────────────────────────────────────────
// A DIFFERENT system from Vendor_Requests/processVendorNudges above: that one is an automatic
// clock that CHASES a quiet vendor (status/photos/invoice nudges, auto-satisfied, escalates to
// Brett after 5 tries). This one is Brett EXPLICITLY flagging a specific vendor issue that
// needs the vendor's attention — three canned request types (Request Photos, Request
// Description Update/Clarification, Other free-typed), always scoped to either the vendor's
// estimate or their invoice on a WO (both already tied to the WO — no separate attachment
// model needed). Triggered from the WO detail view or the bill-review section. Surfaces in a
// dedicated section of the vendor portal. The vendor can mark it done, but that does NOT
// auto-resolve it — per Brett, he doesn't trust a vendor's own "I did it" click without his own
// manual glance, so it lands in a "needs your review" queue (Status: vendor_marked_done) and
// only Brett's own /vendor-task-request/mark-reviewed call retires it.
const VENDOR_TASK_TAB = 'Vendor_Task_Requests';
const VENDOR_TASK_COLS = ['ID','WO_ID','Vendor_ID','Request_Type','Scope','Message','Status','Created_Date','Created_By','Vendor_Marked_Done_Date','Reviewed_Date','Active'];
const VENDOR_TASK_TYPES = ['photos','description','other'];
const VENDOR_TASK_SCOPES = ['estimate','invoice'];
let _vendorTaskReady = false;
async function ensureVendorTaskTab(env) {
  if (!_vendorTaskReady) { await ensureTab(env, VENDOR_TASK_TAB, VENDOR_TASK_COLS); _vendorTaskReady = true; }
  await ensureColumns(env, VENDOR_TASK_TAB, VENDOR_TASK_COLS);
}

// POST /vendor-task-request/create { wo_id, vendor_id, request_type: 'photos'|'description'|'other',
// scope: 'estimate'|'invoice', message?, created_by? } — the WO-detail / bill-review trigger.
// 'other' requires a free-typed message; the two canned types build their own message (an
// optional caller-supplied `message` is appended as extra context, never replaces the ask).
// Sends the vendor an SMS through the same smsGatedSend chokepoint every other vendor text
// uses (quiet hours / opt-out / test-mode all apply identically) so this doesn't need its own
// notification path — but the row (and the portal surface) is the requirement Brett actually
// asked for; the SMS is a best-effort convenience on top of it.
async function createVendorTaskRequest(env, body) {
  const woId = body.wo_id, vendorId = body.vendor_id, reqType = body.request_type, scope = body.scope;
  if (!woId || !vendorId) return json({ error: 'wo_id and vendor_id are required' }, 400);
  if (!VENDOR_TASK_TYPES.includes(reqType)) return json({ error: "request_type must be one of: " + VENDOR_TASK_TYPES.join(', ') }, 400);
  if (!VENDOR_TASK_SCOPES.includes(scope)) return json({ error: "scope must be 'estimate' or 'invoice'" }, 400);
  const customMsg = (body.message || '').trim();
  if (reqType === 'other' && !customMsg) return json({ error: "message is required when request_type is 'other'" }, 400);
  await ensureVendorTaskTab(env);
  const [workorders, vendors, properties, units] = await Promise.all([
    fetchTab(env, 'Work_Orders'), fetchTab(env, 'Vendors'), fetchTab(env, 'Properties'), fetchTab(env, 'Units'),
  ]);
  const wo = findWO(workorders, woId); if (!wo) return json({ error: 'WO not found' }, 404);
  const vendor = vendors.find(v => v.ID === vendorId); if (!vendor) return json({ error: 'Vendor not found' }, 404);
  const property = properties.find(p => p.ID === wo.Property_ID);
  const unit = units.find(u => u.ID === wo.Unit_ID);
  const address = property ? property.Address + (unit && unit.Unit_Label ? ' ' + formatUnitLabel(unit.Unit_Label) : '') : 'the property';
  const vname = (vendor.First_Name || (vendor.Name||'').split(' ')[0] || 'there');
  const scopeLabel = scope === 'estimate' ? 'estimate' : 'invoice';
  let msg;
  if (reqType === 'photos') {
    msg = `Hi ${vname}, could you upload updated photos to go with your ${scopeLabel} for ${woId} at ${address}? You can add them from your vendor portal.`;
  } else if (reqType === 'description') {
    msg = `Hi ${vname}, could you update or clarify the description on your ${scopeLabel} for ${woId} at ${address}? Please take a look in your vendor portal.`;
  } else {
    msg = customMsg;
  }
  if (customMsg && reqType !== 'other') msg += ' ' + customMsg;
  msg += ' ' + vendorPortalLink(woId);
  let sent = false, heldForQuietHours = false, testMode = false, gateSnapshot = '';
  if (vendor.Phone) {
    const r = await smsGatedSend(env, { wo_id: woId, message_type: `vendor_task_${reqType}`, recipient_type: 'vendor', vendor, message_body: msg });
    sent = !!r.sent; heldForQuietHours = !!r.held_for_quiet_hours; testMode = !!r.test_mode; gateSnapshot = r.gate_snapshot || '';
  }
  const now = new Date().toISOString();
  const res = await addRow(env, VENDOR_TASK_TAB, {
    WO_ID: woId, Vendor_ID: vendorId, Request_Type: reqType, Scope: scope, Message: msg,
    Status: 'open', Created_Date: now, Created_By: body.created_by || 'brett',
    Vendor_Marked_Done_Date: '', Reviewed_Date: '',
  });
  return json({ success: true, id: res.id, sent, held_for_quiet_hours: heldForQuietHours, test_mode: testMode, gate_snapshot: gateSnapshot, no_phone: !vendor.Phone });
}

// GET /vendor-task-requests?vendor_id=&wo_id=&status= — reads for BOTH the vendor portal
// (its own open items) and the admin Hub (WO-scoped or all-open view). A vendor-role session
// can only ever see its OWN rows: vendor_id is forced from the verified session, never a
// caller-supplied query param, so one vendor cannot page through another's flagged issues by
// changing the query string. Admin (full secret, callerRole null) can pass any filter.
async function listVendorTaskRequests(env, url, callerRole, callerSessionId) {
  await ensureVendorTaskTab(env);
  const rows = await fetchTab(env, VENDOR_TASK_TAB);
  let vendorId = url.searchParams.get('vendor_id') || '';
  const woId = url.searchParams.get('wo_id') || '';
  const status = url.searchParams.get('status') || '';
  if (callerRole === 'vendor') vendorId = callerSessionId;
  const out = rows.filter(r => {
    if (r.Active === 'FALSE') return false;
    if (vendorId && r.Vendor_ID !== vendorId) return false;
    if (woId && r.WO_ID !== woId) return false;
    if (status && r.Status !== status) return false;
    return true;
  });
  return json(out);
}

// POST /vendor-task-request/mark-done { id, vendor_id? } — the vendor-portal "Mark Done"
// button. Does NOT resolve the request — per Brett, a vendor's own "done" click is never
// auto-trusted. It only flips Status to 'vendor_marked_done', which is exactly what makes it
// show up in Brett's own /vendor-task-requests/pending-review queue for a manual check.
async function markVendorTaskDone(env, body, callerRole, callerSessionId) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  await ensureVendorTaskTab(env);
  const rows = await fetchTab(env, VENDOR_TASK_TAB);
  const row = rows.find(r => r.ID === String(id));
  if (!row || row.Active === 'FALSE') return json({ error: 'Request not found' }, 404);
  const vendorId = callerRole === 'vendor' ? callerSessionId : (body.vendor_id || row.Vendor_ID);
  if (row.Vendor_ID !== vendorId) return json({ error: 'This request does not belong to this vendor' }, 403);
  if (row.Status !== 'open') return json({ error: `Request is already ${row.Status}` }, 400);
  await updateRow(env, VENDOR_TASK_TAB, row.ID, { Status: 'vendor_marked_done', Vendor_Marked_Done_Date: new Date().toISOString() });
  return json({ success: true, id: row.ID, status: 'vendor_marked_done' });
}

// GET /vendor-task-requests/pending-review — Brett's "needs your review" queue: every
// vendor-marked-done request he hasn't personally cleared yet. Admin-gated only (not in
// ROLE_SCOPES.vendor) — a vendor has no reason to see this list.
async function listVendorTaskPendingReview(env) {
  await ensureVendorTaskTab(env);
  const rows = await fetchTab(env, VENDOR_TASK_TAB);
  return json(rows.filter(r => r.Active !== 'FALSE' && r.Status === 'vendor_marked_done'));
}

// POST /vendor-task-request/mark-reviewed { id } — Brett's own manual check, the only thing
// that actually retires a request. Admin-gated only.
async function markVendorTaskReviewed(env, body) {
  const id = body.id; if (!id) return json({ error: 'id required' }, 400);
  await ensureVendorTaskTab(env);
  const rows = await fetchTab(env, VENDOR_TASK_TAB);
  const row = rows.find(r => r.ID === String(id));
  if (!row || row.Active === 'FALSE') return json({ error: 'Request not found' }, 404);
  if (row.Status !== 'vendor_marked_done') return json({ error: `Request is ${row.Status}, not awaiting review` }, 400);
  await updateRow(env, VENDOR_TASK_TAB, row.ID, { Status: 'reviewed_resolved', Reviewed_Date: new Date().toISOString() });
  return json({ success: true, id: row.ID, status: 'reviewed_resolved' });
}

const OWNER_NOTIFY_DEFAULTS={urgent:'always',normal:'key',low:'completion'};
// Sep 14 2026 — trimmed to the 4 owner message types that actually exist now (Received/
// Scheduled/Complete/On_Hold). 'Assigned' and 'Invoiced' are retired per Brett's own call
// (owners don't need an Assigned text; Invoiced is dropped — the invoice email already covers
// it). On_Hold included in every tier except 'off': a delay is something any owner receiving
// SOME notifications would want to know, not just the high-priority "always" tier.
const NOTIFY_TIERS={always:['Received','Scheduled','Complete','On_Hold'],key:['Received','Scheduled','Complete','On_Hold'],completion:['Complete','On_Hold'],off:[]};

async function getOwnerNotifications(env, url) {
  const ownerId=url.searchParams.get('owner_id'); if(!ownerId) return json({error:'Missing owner_id'},400);
  const owners=await fetchTab(env,'Owners'); const owner=owners.find(o=>o.ID===ownerId); if(!owner) return json({error:'Owner not found'},404);
  return json({method:owner.Notify_Method||'sms',urgent:owner.Notify_Urgent||OWNER_NOTIFY_DEFAULTS.urgent,normal:owner.Notify_Normal||OWNER_NOTIFY_DEFAULTS.normal,low:owner.Notify_Low||OWNER_NOTIFY_DEFAULTS.low});
}

async function saveOwnerNotifications(env, body) {
  if(!body.owner_id) return json({error:'Missing owner_id'},400);
  const fields={}; if(body.method!==undefined) fields.Notify_Method=body.method; if(body.urgent!==undefined) fields.Notify_Urgent=body.urgent; if(body.normal!==undefined) fields.Notify_Normal=body.normal; if(body.low!==undefined) fields.Notify_Low=body.low;
  if(!Object.keys(fields).length) return json({error:'No fields to update'},400);
  await updateRow(env,'Owners',body.owner_id,fields); return json({success:true});
}

async function shouldNotifyOwner(env, wo, statusEvent) {
  const [properties,owners]=await fetchTabs(env, ['Properties','Owners']);
  const prop=properties.find(p=>p.ID===wo.Property_ID); if(!prop) return false;
  const owner=owners.find(o=>o.ID===prop.Owner_ID); if(!owner||!owner.Phone) return false;
  if((owner.Notify_Method||'sms')==='none') return false;
  if(wo.Owner_Notify_Override&&wo.Owner_Notify_Override!=='') return (NOTIFY_TIERS[wo.Owner_Notify_Override]||[]).includes(statusEvent);
  const priority=(wo.Priority||'normal').toLowerCase();
  const tier=(priority==='urgent'?owner.Notify_Urgent:priority==='low'?owner.Notify_Low:owner.Notify_Normal)||OWNER_NOTIFY_DEFAULTS[priority==='urgent'?'urgent':priority==='low'?'low':'normal'];
  return (NOTIFY_TIERS[tier]||[]).includes(statusEvent);
}

async function addWishlistItem(env, body) {
  // Ensure the Status column exists so new items are born 'Active' and the Dev Log status
  // buttons have somewhere to write (rule 37: never write a column that isn't there).
  try { await ensureColumns(env, 'Wishlist', ['Status']); } catch (e) { /* non-fatal — add still works */ }
  const data=await sheetsRequest(env,'GET',`/values/Wishlist`); const rows=data.values||[['ID','Text','Created','Active','Status']], headers=rows[0];
  const now=new Date().toISOString().replace('T',' ').split('.')[0];
  const newRow=headers.map(h=>({ID:String(nextSafeId(rows)),Text:body.text||'',Created:now,Active:'TRUE',Status:'Active'}[h]??''));
  await sheetsRequest(env,'POST',`/values/Wishlist:append?valueInputOption=RAW`,{values:[newRow]}); return json({success:true});
}

// POST /wishlist/status { id, status } — set an item's lifecycle status so the Dev Log
// wishlist reflects reality: Active / In progress / Done / Not applicable. Ensures the Status
// column first (rule 37) — otherwise updateRow silently no-ops on a missing column and returns
// a false success. Internal improvement list — no money/PII/auth surface.
async function setWishlistStatus(env, body) {
  const id = body && body.id;
  const status = String((body && body.status) || '').trim();
  const ALLOWED = ['Active','In progress','Done','Not applicable'];
  if (id === undefined || id === null || id === '') return json({ error: 'id required' }, 400);
  if (!ALLOWED.includes(status)) return json({ error: 'invalid status' }, 400);
  try { await ensureColumns(env, 'Wishlist', ['Status']); } catch (e) { /* if it already exists, updateRow proceeds */ }
  return await updateRow(env, 'Wishlist', id, { Status: status });
}

// ── SMS ──────────────────────────────────────────────────────

async function handleInboundSMS(env, request) {
  const params=new URLSearchParams(await request.text()), from=params.get('From')||'', body=(params.get('Body')||'').trim().toUpperCase();
  const vendors=await fetchTab(env,'Vendors'); const vendor=vendors.find(v=>v.Phone&&normalizePhone(v.Phone)===normalizePhone(from));
  if(!vendor) return twilioResponse('Sorry, we could not find your vendor record. Please contact your coordinator.');
  const workorders=await fetchTab(env,'Work_Orders');
  const recentWO=workorders.filter(w=>w.Vendor_ID===vendor.ID&&w.Status==='Assigned').sort((a,b)=>new Date(b.Created_Date)-new Date(a.Created_Date))[0];
  if(!recentWO) return twilioResponse('No open assignments found for your number.');
  const config=await fetchConfig(env); const vendorName=vendor.Name||`${vendor.First_Name||''} ${vendor.Last_Name||''}`.trim();
  if(body==='YES'||body==='Y'){
    // Route through updateStatus so accepting via SMS fires the same tenant-notification
    // automation (and audit/telemetry) as accepting in the portal.
    await updateStatus(env,{wo_id:recentWO.ID,status:'Accepted',updated_by:vendorName,updated_by_role:'vendor',vendor_id:vendor.ID});
    await logSMS(env,recentWO.ID,'vendor_reply',vendor.ID,from,body);
    if(config.admin_phone) await sendSMS(env,config.admin_phone,`✅ ${vendorName} accepted ${recentWO.ID} (${recentWO.Trade} @ property ${recentWO.Property_ID}).`);
    return twilioResponse(vendor.Language==='es'?`Entendido. Confirmado para ${recentWO.ID}. El código de la caja y el contacto del inquilino ya están en su portal.`:`Got it! You're confirmed for ${recentWO.ID}. The lockbox code & tenant contact are now unlocked in your portal.`);
  }
  if(body==='NO'||body==='N'){
    await updateWOFields(env,recentWO.ID,{Status:'Declined',Vendor_ID:''});await logSMS(env,recentWO.ID,'vendor_reply',vendor.ID,from,body);
    await logWOAudit(env,recentWO.ID,vendorName,'vendor','Status',recentWO.Status,'Declined','Declined via SMS reply');
    if(config.admin_phone) await sendSMS(env,config.admin_phone,`❌ ${vendorName} declined ${recentWO.ID}. Needs reassignment.`);
    return twilioResponse(vendor.Language==='es'?`Entendido. Su coordinador ha sido notificado.`:`Understood. Your coordinator has been notified.`);
  }
  await logSMS(env,recentWO.ID,'vendor_reply',vendor.ID,from,body);
  if(config.admin_phone) await sendSMS(env,config.admin_phone,`💬 ${vendorName} replied to ${recentWO.ID}: "${body}"`);
  return twilioResponse(`Message received. Your coordinator will follow up.`);
}

// Raw Twilio transport — no gating, sends if credentials are present. Only ever called by
// (a) sendSMS below, once the global kill switch has already been checked, and (b)
// smsGatedSend, which has already run the full four/two-layer gate + Test Mode redirect.
// Never call this directly from a new call site — call sendSMS (legacy/ungated sites) or
// smsGatedSend (the 6 TWILIO_SMS_BUILD_BRIEF_v1.0 message types) instead.
// Auth: Twilio accepts Basic auth with EITHER (Account SID : Auth Token) OR (API Key SID :
// API Key Secret) — Brett's Cloudflare secrets are the API-Key pair (TWILIO_API_SID /
// TWILIO_API_KEY), not a classic Auth Token (no TWILIO_AUTH var exists), so this uses that
// pair. The URL path always uses the Account SID (TWILIO_SID) regardless of which credential
// authenticates the request — that part is unchanged.
async function sendSMSRaw(env, to, message) {
  to = normalizePhone(to);
  if (!to) return { error: 'No phone number' };
  if (env.__STAGING__ ?? isStaging(env)) {
    console.log(`🧪 STAGING — SMS stubbed (not sent via Twilio) → ${to}: ${message}`);
    return { staged: true, would_have: { to, message }, note: '🧪 STAGING MODE — logged only, no real SMS sent.' };
  }
  if (!env.TWILIO_SID || !env.TWILIO_API_SID || !env.TWILIO_API_KEY || !env.TWILIO_FROM)
    return { error: 'Twilio not configured (missing TWILIO_SID/TWILIO_API_SID/TWILIO_API_KEY/TWILIO_FROM)' };
  const resp = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${env.TWILIO_SID}/Messages.json`, {
    method: 'POST',
    headers: { 'Authorization': 'Basic ' + btoa(`${env.TWILIO_API_SID}:${env.TWILIO_API_KEY}`), 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ From: env.TWILIO_FROM, To: to, Body: message }).toString(),
  });
  return resp.json();
}

// sendSMS — the long-standing chokepoint every pre-existing call site in this file already
// calls (owner status pings, admin-phone alerts, the vendor-accept SMS reply flow, the daily
// digest). None of those are part of TWILIO_SMS_BUILD_BRIEF_v1.0's 6 gated message types, so
// they don't get the full Property/Customer/Tenant/Vendor gate or Test Mode redirect — but
// EVERY one of them, old and new, now honors the one Global kill switch (Config.TWILIO_ENABLED)
// checked here. This matters because fixing the auth above (previously TWILIO_SID:TWILIO_AUTH,
// which 401'd since TWILIO_AUTH was never set) would otherwise make all of those pre-existing,
// never-actually-working call sites start sending real messages the moment real Twilio
// credentials landed — with no Test Mode, no review queue, no gating at all. Matches Brett's
// own stated intent (kept off until he's run live tests) at the one place that can enforce it
// for every SMS in the codebase, not just the 6 new ones. TWILIO_ENABLED defaults OFF (missing
// Config key reads as '', which is !== 'TRUE'), so nothing sends anywhere until Brett flips it.
async function sendSMS(env, to, message) {
  let cfg;
  try { cfg = await fetchConfig(env); } catch (e) { cfg = {}; }
  if (String(cfg.TWILIO_ENABLED || '').toUpperCase() !== 'TRUE') return { skipped: true, reason: 'TWILIO_ENABLED not TRUE' };
  return sendSMSRaw(env, to, message);
}

// ── POST /admin-notify (Oct 12 2026) — narrow server-to-server "text Brett" endpoint ─────────────
// Lets an external automation (str-automation) push ONE alert SMS to Brett. Designed to be
// un-abusable even if its token leaks:
//   • Auth: header X-Auth-Token must equal the NEW narrow secret env.ALERT_PUSH_TOKEN, accepted
//     ONLY for POST /admin-notify (alertPushTokenOk, wired into the auth cascade above). Unset or
//     blank secret => the token path is closed entirely (fail closed); an empty header never matches.
//   • Recipient is ALWAYS Config `admin_phone` — nothing in the request body can set or override
//     it (the body is only read for `text` and `source`).
//   • Per-day cap: ADMIN_NOTIFY_DAILY_CAP sends/day (UTC date) tracked in ONE Config row
//     (`admin_notify_daily_count` = "YYYY-MM-DD:N"). The slot is RESERVED (written + re-read to
//     verify) BEFORE the SMS goes out, so a Config write failure fails closed — no unmetered send.
//     Attempts count whether or not Twilio is enabled. Concurrent calls can overshoot by a few at
//     most (read-modify-write on a sheet cell, same as every other Config marker here).
//   • Honest result: {ok:true,sent:true} ONLY when a real send happened (Twilio message sid, or
//     the staging stub with staged:true); {ok:true,sent:false,skipped:true,reason} when sendSMS
//     skipped (TWILIO_ENABLED not TRUE); anything else is non-200 {ok:false,error}. Every outcome is
//     logged to Ops_Telemetry (Job_Type admin_notify) — never the token, phone number or message
//     text (length only); a telemetry-write failure is surfaced as telemetry_error in the response.
const ADMIN_NOTIFY_MAX_TEXT = 1500;
const ADMIN_NOTIFY_MAX_SOURCE = 40;
const ADMIN_NOTIFY_DAILY_CAP = 30;
const ADMIN_NOTIFY_COUNT_KEY = 'admin_notify_daily_count';

// Pure: is this request authorised by the narrow ALERT_PUSH_TOKEN? Constant-time compare; false
// for an unset/blank secret, an empty header, any method but POST, or any path but /admin-notify.
function alertPushTokenOk(secret, tok, method, path) {
  if (typeof secret !== 'string' || !secret.trim()) return false;
  if (typeof tok !== 'string' || !tok) return false;
  if (method !== 'POST' || path !== '/admin-notify') return false;
  if (tok.length !== secret.length) return false;
  let diff = 0;
  for (let i = 0; i < secret.length; i++) diff |= tok.charCodeAt(i) ^ secret.charCodeAt(i);
  return diff === 0;
}

// Pure: validate + normalise the JSON body. Only `text` and `source` are ever read.
function validateAdminNotifyBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return { ok: false, error: 'JSON object body required: {text, source?}' };
  if (typeof body.text !== 'string') return { ok: false, error: 'text (string) required' };
  const text = body.text.trim();
  if (!text) return { ok: false, error: 'text must not be empty' };
  if (text.length > ADMIN_NOTIFY_MAX_TEXT) return { ok: false, error: `text too long (${text.length} > ${ADMIN_NOTIFY_MAX_TEXT} chars)` };
  let source = '';
  if (body.source !== undefined && body.source !== null) {
    if (typeof body.source !== 'string') return { ok: false, error: 'source must be a string' };
    source = body.source.trim();
    if (source.length > ADMIN_NOTIFY_MAX_SOURCE) return { ok: false, error: `source too long (${source.length} > ${ADMIN_NOTIFY_MAX_SOURCE} chars)` };
    source = source.replace(/[\u0000-\u001f\u007f]/g, ' ');
  }
  return { ok: true, text, source };
}

// Pure: parse the "YYYY-MM-DD:N" cap row => how many sends already counted for `today`.
function adminNotifyCountToday(raw, today) {
  const m = /^(\d{4}-\d{2}-\d{2}):(\d+)$/.exec(String(raw || '').trim());
  return (m && m[1] === today) ? parseInt(m[2], 10) : 0;
}

// Pure: strip anything phone-number-shaped from an error string before it is logged or returned.
function scrubPhones(s) {
  return String(s == null ? '' : s).replace(/\+?\d[\d\s().-]{6,}\d/g, '[number]');
}

async function adminNotify(env, body) {
  const t0 = Date.now();
  let telemetryError = null;
  const tel = async (ok, notes) => {
    try { await logTelemetry(env, { Source: 'worker', Job_Type: 'admin_notify', Skill_Or_Endpoint: '/admin-notify', Success: ok ? 'TRUE' : 'FALSE', Latency_ms: Date.now() - t0, Notes: String(notes).slice(0, 500) }); }
    catch (e) { telemetryError = scrubPhones((e && e.message) || e).slice(0, 200); console.error('admin-notify: Ops_Telemetry write failed:', telemetryError); }
  };
  const done = async (status, ok, payload, notes) => {
    await tel(ok, notes);
    const out = Object.assign({}, payload);
    if (telemetryError) out.telemetry_error = telemetryError;
    return json(out, status);
  };

  const v = validateAdminNotifyBody(body);
  if (!v.ok) return done(400, false, { ok: false, error: v.error }, `rejected 400: ${v.error} source=${(body && typeof body.source === 'string') ? body.source.trim().slice(0, 40) : ''}`);
  const meta = `source=${v.source || '-'} len=${v.text.length}`;

  // Config (admin_phone + cap row). Read directly (not fetchConfig, which swallows errors) so an
  // unreadable Config is reported as such rather than masquerading as "admin_phone missing".
  let cfg;
  try { const data = await sheetsRequest(env, 'GET', '/values/Config'); cfg = configFromValues(data && data.values); }
  catch (e) { const m = scrubPhones((e && e.message) || e).slice(0, 200); return done(500, false, { ok: false, error: 'could not read Config: ' + m }, `FAILED config_read ${meta}: ${m}`); }
  const phone = String(cfg.admin_phone || '').trim();
  if (!phone) return done(500, false, { ok: false, error: 'Config admin_phone is not set' }, `FAILED admin_phone_missing ${meta}`);

  // Reserve a daily slot BEFORE sending; verify the write landed; fail closed on any problem.
  const today = new Date().toISOString().slice(0, 10);
  const used = adminNotifyCountToday(cfg[ADMIN_NOTIFY_COUNT_KEY], today);
  if (used >= ADMIN_NOTIFY_DAILY_CAP) return done(429, false, { ok: false, error: `daily cap reached (${ADMIN_NOTIFY_DAILY_CAP}/day)` }, `FAILED daily_cap_reached ${used}/${ADMIN_NOTIFY_DAILY_CAP} ${meta}`);
  const want = `${today}:${used + 1}`;
  try {
    const wr = await setConfigKey(env, { key: ADMIN_NOTIFY_COUNT_KEY, value: want });
    if (!wr || wr.status !== 200) throw new Error('Config write returned HTTP ' + (wr && wr.status));
    const back = configFromValues((await sheetsRequest(env, 'GET', '/values/Config')).values);
    if (String(back[ADMIN_NOTIFY_COUNT_KEY] || '').trim() !== want) throw new Error('cap counter did not persist (read-back mismatch)');
  } catch (e) { const m = scrubPhones((e && e.message) || e).slice(0, 200); return done(500, false, { ok: false, error: 'could not record daily cap counter, NOT sent: ' + m }, `FAILED cap_write ${meta}: ${m}`); }

  let r;
  try { r = await sendSMS(env, phone, v.text); }
  catch (e) { const m = scrubPhones((e && e.message) || e).slice(0, 200); return done(502, false, { ok: false, error: 'SMS send threw: ' + m }, `FAILED send_threw ${meta} cap=${used + 1}/${ADMIN_NOTIFY_DAILY_CAP}: ${m}`); }
  if (r && r.skipped) return done(200, true, { ok: true, sent: false, skipped: true, reason: String(r.reason || 'sending is disabled') }, `skipped (${scrubPhones(r.reason)}) ${meta} cap=${used + 1}/${ADMIN_NOTIFY_DAILY_CAP}`);
  if (r && r.staged) return done(200, true, { ok: true, sent: true, staged: true, note: 'staging stub - logged only, no real SMS' }, `sent (STAGING stub) ${meta} cap=${used + 1}/${ADMIN_NOTIFY_DAILY_CAP}`);
  if (r && r.sid && !r.error && !r.code) return done(200, true, { ok: true, sent: true, sid: r.sid }, `sent ${meta} sid=${r.sid} cap=${used + 1}/${ADMIN_NOTIFY_DAILY_CAP}`);
  const why = scrubPhones((r && (r.error || r.message)) || 'unexpected Twilio response (no message sid)').slice(0, 200);
  return done(502, false, { ok: false, error: 'SMS not sent: ' + why + ((r && r.code) ? ' (twilio code ' + r.code + ')' : '') }, `FAILED sms ${meta} cap=${used + 1}/${ADMIN_NOTIFY_DAILY_CAP}: ${why}`);
}

// ── Door-code system watchdog (Oct 12 2026) ──────────────────────────────────────────────────────────
// An independent check, run by the scheduler's `door_watchdog` job (Apps Script clock, ~every 15 min - NO cron), that GETs the public
// /health of the str-automation Worker (guest door codes + alerts) and texts Brett when it looks broken:
// fetch throws/times out (8s) / non-200 / non-JSON; ok !== true; any secrets_set value not true;
// last_tick null/invalid/older than 75 min (normally refreshes every ~25-30 min); problems[] non-empty.
//   * A MISSING last_tick key means "not deployed yet" and is tolerated for 24h (tracked in state as
//     absent_since), after which it becomes its own problem - so the check can never stay silently off.
//   * Missing `problems` is [].
//   * Dedupe: at most ONE text per distinct reason-set per 6h, plus ONE "RECOVERED" text when a
//     previously alerted problem clears. State = ONE Config row (`door_watchdog_state`, small JSON:
//     {active, sent:{<reason-key>:<ISO>}, absent_since}) written + read back to verify, the same
//     Config-row pattern as admin_notify_daily_count / failure_alert_last_sent_*. No new tab/binding.
//   * Fail-loud (Brett, non-negotiable): every failure path (health fetch itself, Config/state read,
//     corrupt state, state write, SMS, email fallback, telemetry write, an unexpected throw) is logged
//     (console + Ops_Telemetry Job_Type `door_watchdog`, Success=FALSE) and returned in `errors`. If the
//     SMS cannot be delivered (Twilio off/failing, admin_phone missing) an email goes to the same
//     address inspAlert uses; if NEITHER channel delivers the alert is NOT marked sent, so the next
//     15-min pass retries it. If the state store is unavailable a per-isolate in-memory copy limits
//     repeats until it recovers. The scheduler's `door_watchdog` job wraps the whole pass so it can never break
//     the other jobs.
//   * Testable without waiting for cron: pure evaluateDoorHealth / doorWdDecide / doorWdNextState /
//     doorWdComposeAlert (unit tests), runDoorWatchdogPass with injectable io (fetch, Config read,
//     state write, SMS, email, telemetry), GET /watchdog/door-system (read-only live status) and the
//     STAGING-ONLY POST /watchdog/door-system/test that runs one real pass with an injected health
//     payload / simulated failure and returns the SMS text it would send (SMS is the staging stub).
// NOTE (found in staging, Oct 12 2026): a plain fetch() from one Worker to another Worker on the SAME Cloudflare
// zone/account workers.dev subdomain fails with Cloudflare error 1042 (returned as an HTTP 404 page) unless the
// `global_fetch_strictly_public` compatibility flag is set - wrangler.toml now sets it. Without it this watchdog
// would see a permanent http_404 and cry wolf.
const DOOR_WD_URL = 'https://str-automation.brett-2f8.workers.dev/health';
const DOOR_WD_TIMEOUT_MS = 8000;
const DOOR_WD_STALE_MS = 75 * 60000;
const DOOR_WD_DEDUPE_MS = 6 * 3600000;
const DOOR_WD_ABSENT_GRACE_MS = 24 * 3600000;
const DOOR_WD_STATE_KEY = 'door_watchdog_state';
const DOOR_WD_JOB = 'door_watchdog';
const DOOR_WD_MAX_LIST = 6;
// Per-isolate fallback copy of the state when the Config row cannot be read/written. BEST-EFFORT ONLY:
// a new isolate starts empty, so while Config stays unreadable a repeat alert is possible (it errs toward
// texting again, never toward silence). The read/write failure itself is logged to Ops_Telemetry each time.
let __doorWdMem = null;

// Pure: a key name taken from the (untrusted) health JSON, made safe for an SMS / state key.
function doorWdName(v) {
  const s = String(v == null ? '' : v);
  return /^[A-Za-z0-9_.:-]{1,48}$/.test(s) ? s : '(invalid)';
}
function doorWdList(arr) {
  const a = arr.slice(0, DOOR_WD_MAX_LIST).join(', ');
  return arr.length > DOOR_WD_MAX_LIST ? a + ' +' + (arr.length - DOOR_WD_MAX_LIST) + ' more' : a;
}
function doorWdAge(ms) {
  const m = Math.max(0, Math.round(ms / 60000));
  return m < 120 ? m + 'm' : Math.round(m / 60) + 'h';
}

// Pure. `fr` is the fetch result: {error, timeout} | {status, json, bad_json}. Returns
// {healthy, reasons:[{code,text}], key, lastTickAbsent}. `key` is the sorted, joined reason codes: it
// identifies the reason-SET for dedupe and never contains volatile data (ages, error text).
function evaluateDoorHealth(fr, nowMs, opts) {
  opts = opts || {};
  const reasons = [];
  const add = (code, text) => reasons.push({ code, text });
  let lastTickAbsent = false;
  const finish = () => {
    const seen = new Set();
    const uniq = reasons.filter(r => !seen.has(r.code) && seen.add(r.code));
    return { healthy: uniq.length === 0, reasons: uniq, key: uniq.map(r => r.code).sort().join('|'), lastTickAbsent };
  };
  if (!fr || typeof fr !== 'object') { add('unreachable', 'health check returned nothing'); return finish(); }
  if (fr.error) { add('unreachable', fr.timeout ? 'health check timed out' : 'health check unreachable'); return finish(); }
  if (fr.status !== 200) {
    const st = Number.isInteger(fr.status) ? String(fr.status) : 'unknown';
    add('http_' + st, 'health returned HTTP ' + st);
    return finish();
  }
  if (fr.bad_json || !fr.json || typeof fr.json !== 'object' || Array.isArray(fr.json)) { add('bad_json', 'health response is not valid JSON'); return finish(); }
  const j = fr.json;
  if (j.ok !== true) add('not_ok', 'health reports ok is not true');

  const s = j.secrets_set;
  if (!s || typeof s !== 'object' || Array.isArray(s)) add('secrets_field', 'secrets_set missing from health');
  else Object.keys(s).filter(k => s[k] !== true).sort().forEach(k => add('secret:' + doorWdName(k), 'secret ' + doorWdName(k) + ' not set'));

  if (!Object.prototype.hasOwnProperty.call(j, 'last_tick')) {
    lastTickAbsent = true; // "not deployed yet" - tolerated only for DOOR_WD_ABSENT_GRACE_MS (tracked by the caller)
    if (opts.absentSinceMs != null && isFinite(opts.absentSinceMs) && nowMs - opts.absentSinceMs > DOOR_WD_ABSENT_GRACE_MS) {
      add('tick_field_missing', 'health has no last_tick field (tick check never went live)');
    }
  } else if (j.last_tick === null) {
    add('tick_null', 'no tick recorded (last_tick null)');
  } else {
    const t = typeof j.last_tick === 'string' ? Date.parse(j.last_tick) : NaN;
    if (!isFinite(t)) add('tick_invalid', 'last_tick is not a valid time');
    else if (nowMs - t > DOOR_WD_STALE_MS) add('tick_stale', 'last tick ' + doorWdAge(nowMs - t) + ' ago (expected under 75m)');
  }

  if (j.problems != null) {
    if (!Array.isArray(j.problems)) add('problems_field', 'problems field malformed');
    else Array.from(new Set(j.problems.map(p => doorWdName(p && typeof p === 'object' ? p.key : p)))).sort().forEach(k => add('problem:' + k, 'problem ' + k));
  }
  return finish();
}

// Pure: the exact SMS text. Reasons are summarised short; secrets and problems are grouped.
function doorWdComposeAlert(reasons) {
  const parts = [], secrets = [], probs = [];
  for (const r of reasons) {
    if (r.code.startsWith('secret:')) secrets.push(r.code.slice(7));
    else if (r.code.startsWith('problem:')) probs.push(r.code.slice(8));
    else parts.push(r.text);
  }
  if (secrets.length) parts.push('secrets not set: ' + doorWdList(secrets));
  if (probs.length) parts.push('problems: ' + doorWdList(probs));
  return 'ALERT: door-code system (str-automation): ' + parts.join('; ').slice(0, 240) + '. Guests may not get codes or alerts. Health: ' + DOOR_WD_URL;
}
function doorWdComposeRecovered() {
  return 'RECOVERED: door-code system (str-automation) is healthy again. Health: ' + DOOR_WD_URL;
}

// Pure: parse the stored state cell. Never throws; `corrupt` is true when a non-empty cell is unusable
// (the caller reports that loudly and carries on with a clean state).
function doorWdParseState(raw) {
  const clean = { active: false, sent: {}, absent_since: null };
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return { state: clean, corrupt: false };
  let o;
  try { o = JSON.parse(s); } catch (e) { return { state: clean, corrupt: true }; }
  if (!o || typeof o !== 'object' || Array.isArray(o)) return { state: clean, corrupt: true };
  const sent = {};
  if (o.sent && typeof o.sent === 'object' && !Array.isArray(o.sent)) {
    for (const k of Object.keys(o.sent)) if (typeof o.sent[k] === 'string' && isFinite(Date.parse(o.sent[k]))) sent[k] = o.sent[k];
  }
  const abs = typeof o.absent_since === 'string' && isFinite(Date.parse(o.absent_since)) ? o.absent_since : null;
  return { state: { active: o.active === true, sent, absent_since: abs }, corrupt: false };
}
function doorWdPrune(state, nowMs) {
  const sent = {};
  for (const k of Object.keys(state.sent || {})) {
    const t = Date.parse(state.sent[k]);
    if (isFinite(t) && nowMs - t < DOOR_WD_DEDUPE_MS) sent[k] = state.sent[k];
  }
  return { active: !!state.active, sent, absent_since: state.absent_since || null };
}

// Pure: what to do this pass. 'alert' | 'suppressed' (same reason-set already texted <6h ago) |
// 'recovered' (healthy now but an alert was delivered earlier) | 'none'.
function doorWdDecide(ev, state, nowMs) {
  const st = doorWdPrune(state, nowMs);
  if (!ev.healthy) {
    const last = Date.parse(st.sent[ev.key]);
    return (isFinite(last) && nowMs - last < DOOR_WD_DEDUPE_MS) ? 'suppressed' : 'alert';
  }
  return st.active ? 'recovered' : 'none';
}

// Pure: the state to persist after this pass. An alert/recovery only counts once it was DELIVERED.
function doorWdNextState(state, ev, decision, delivered, nowMs) {
  const st = doorWdPrune(state, nowMs);
  const iso = new Date(nowMs).toISOString();
  if (decision === 'alert' && delivered) { st.active = true; st.sent[ev.key] = iso; }
  if (decision === 'recovered' && delivered) { st.active = false; st.sent = {}; }
  st.absent_since = ev.lastTickAbsent ? (state.absent_since || iso) : null;
  return st;
}

// One attempt at the health GET. Never throws: {error, timeout} or {status, json, bad_json}.
async function doorWdAttempt(fetchImpl, timeoutMs) {
  const ctl = new AbortController();
  let timer;
  const timeoutP = new Promise((_, rej) => { timer = setTimeout(() => { try { ctl.abort(); } catch (e) { console.error('door-watchdog: abort failed:', e && e.message); } rej(Object.assign(new Error('timeout after ' + timeoutMs + 'ms'), { timeout: true })); }, timeoutMs); });
  const work = (async () => {
    const resp = await fetchImpl(DOOR_WD_URL, { signal: ctl.signal, headers: { Accept: 'application/json' } });
    const status = resp.status;
    const text = await resp.text();
    let parsed, bad = false;
    try { parsed = JSON.parse(text); } catch (e) { bad = true; }
    // keep a short body excerpt for diagnosis (telemetry / status only, never the SMS) when the reply is not healthy JSON
    const snippet = (bad || status !== 200) ? String(text).replace(/\s+/g, ' ').slice(0, 160) : undefined;
    return { status, json: bad ? undefined : parsed, bad_json: bad, snippet };
  })();
  work.catch((e) => { console.error('door-watchdog: health attempt rejected:', e && e.message); });
  try { return await Promise.race([work, timeoutP]); }
  catch (e) { return { error: String((e && e.message) || e).slice(0, 200), timeout: !!(e && e.timeout) }; }
  finally { clearTimeout(timer); }
}
// Up to 2 attempts (a transient network error / 5xx is retried once) so a single blip does not text Brett.
async function fetchDoorHealth(fetchImpl, o) {
  o = o || {};
  const timeoutMs = o.timeoutMs || DOOR_WD_TIMEOUT_MS;
  let last = null, attempts = 0;
  for (let i = 0; i < 2; i++) {
    attempts++;
    last = await doorWdAttempt(fetchImpl, timeoutMs);
    const transient = !!last.error || (typeof last.status === 'number' && last.status >= 500);
    if (!transient) break;
    if (i === 0) await new Promise(r => setTimeout(r, o.retryDelayMs == null ? 1500 : o.retryDelayMs));
  }
  last.attempts = attempts;
  return last;
}

async function doorWdReadConfig(env) {
  const data = await sheetsRequest(env, 'GET', '/values/Config');
  return configFromValues(data && data.values);
}
// Write the state cell and READ IT BACK (a write that returned 200 but did not land is a failure).
async function doorWdWriteState(env, value) {
  const wr = await setConfigKey(env, { key: DOOR_WD_STATE_KEY, value });
  if (!wr || wr.status !== 200) throw new Error('Config write returned HTTP ' + (wr && wr.status));
  const back = configFromValues((await sheetsRequest(env, 'GET', '/values/Config')).values);
  if (String(back[DOOR_WD_STATE_KEY] || '').trim() !== String(value || '').trim()) throw new Error('state did not persist (read-back mismatch)');
}

// One watchdog pass. `opts`: {nowMs, test, timeoutMs, retryDelayMs, io:{fetch, readConfig, writeState,
// sendSms(phone,text), sendEmail({to,subject,html}), logTelemetry(env,rec)}}. Never throws for an expected
// failure: everything is logged + returned in `errors` (res.ok=false). No phone number is ever returned.
async function runDoorWatchdogPass(env, opts) {
  opts = opts || {};
  const io = opts.io || {};
  const t0 = Date.now();
  const nowMs = opts.nowMs != null ? opts.nowMs : Date.now();
  const res = { ok: true, action: 'none', healthy: null, reason_key: '', reasons: [], sms_text: null, delivered: null, delivery: { sms: null, email: null }, fetch: null, state_before: null, state_after: null, state_saved: null, errors: [] };
  const fail = (stage, e) => { const m = scrubPhones((e && e.message) || e).slice(0, 200); res.ok = false; res.errors.push(stage + ': ' + m); console.error('door-watchdog:', stage, m); return m; };
  const tel = async (success, stage, notes) => {
    try {
      await (io.logTelemetry || logTelemetry)(env, { Source: 'worker', Job_Type: DOOR_WD_JOB, Skill_Or_Endpoint: opts.test ? 'test/door-watchdog' : 'scheduled/door-watchdog', Success: success ? 'TRUE' : 'FALSE', Latency_ms: Date.now() - t0, Notes: ((opts.test ? '[test] ' : '') + stage + ': ' + notes).slice(0, 480) });
    } catch (e) { fail('telemetry_write(' + stage + ')', e); }
  };

  // 1. health
  let fr;
  try { fr = await fetchDoorHealth(io.fetch || fetch, { timeoutMs: opts.timeoutMs, retryDelayMs: opts.retryDelayMs }); }
  catch (e) { fr = { error: 'watchdog fetch wrapper threw', attempts: 0 }; fail('fetch_wrapper', e); }
  res.fetch = { status: fr.status == null ? null : fr.status, attempts: fr.attempts || 0, error: fr.error ? scrubPhones(fr.error).slice(0, 200) : null, snippet: fr.snippet || null };

  // 2. state (read Config directly: fetchConfig swallows errors, which would hide an unreadable store)
  let cfg = null, stateRaw = '';
  try { cfg = await (io.readConfig ? io.readConfig() : doorWdReadConfig(env)); stateRaw = cfg[DOOR_WD_STATE_KEY] || ''; }
  catch (e) { const m = fail('state_read', e); await tel(false, 'state_read', m + ' (using in-memory state if any)'); }
  let parsed = doorWdParseState(stateRaw);
  if (parsed.corrupt) { fail('state_corrupt', 'stored door_watchdog_state is not valid JSON; starting clean'); await tel(false, 'state_corrupt', 'stored state unparseable; reset to clean'); }
  let state = parsed.state;
  if (__doorWdMem && (cfg === null || __doorWdMem.dirty)) state = __doorWdMem.state; // store unreadable, or our last write to it failed
  res.state_before = doorWdPrune(state, nowMs);

  // 3. decide
  const absentMs = state.absent_since ? Date.parse(state.absent_since) : null;
  const ev = evaluateDoorHealth(fr, nowMs, { absentSinceMs: absentMs });
  const decision = doorWdDecide(ev, state, nowMs);
  res.healthy = ev.healthy; res.reason_key = ev.key; res.reasons = ev.reasons; res.action = decision;

  // 4. deliver
  let delivered = null;
  if (decision === 'alert' || decision === 'recovered') {
    const text = decision === 'alert' ? doorWdComposeAlert(ev.reasons) : doorWdComposeRecovered();
    res.sms_text = text;
    const phone = cfg ? String(cfg.admin_phone || '').trim() : '';
    let smsOk = false, smsOutcome = 'failed', smsDetail = '';
    if (!cfg) smsDetail = 'Config unreadable, admin_phone unknown';
    else if (!phone) smsDetail = 'Config admin_phone not set';
    else {
      try {
        const r = await (io.sendSms ? io.sendSms(phone, text) : sendSMS(env, phone, text));
        if (r && r.skipped) smsDetail = 'skipped: ' + scrubPhones(r.reason || 'sending disabled');
        else if (r && r.staged) { smsOk = true; smsOutcome = 'staged'; }
        else if (r && r.sid && !r.error && !r.code) { smsOk = true; smsOutcome = 'sent'; }
        else smsDetail = scrubPhones((r && (r.error || r.message)) || 'unexpected response (no message sid)').slice(0, 200);
      } catch (e) { smsDetail = 'threw: ' + scrubPhones((e && e.message) || e).slice(0, 200); }
    }
    res.delivery.sms = { ok: smsOk, outcome: smsOutcome, detail: smsDetail || null };
    let emailOk = false;
    if (!smsOk) {
      fail('sms', smsDetail);
      await tel(false, 'sms_' + decision, smsDetail);
      const to = (cfg && cfg.INSP_NOTIFY_EMAIL) || 'brett@bmoremanagement.com'; // same fallback address inspAlert uses
      const subject = decision === 'alert' ? 'ALERT: door-code system (str-automation)' : 'RECOVERED: door-code system (str-automation)';
      const html = '<p>' + String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</p><p>(Sent by email because the text message could not be delivered: ' + String(smsDetail).replace(/&/g, '&amp;').replace(/</g, '&lt;') + ')</p>';
      let emailDetail = '';
      try {
        const r = await (io.sendEmail ? io.sendEmail({ to, subject, html }) : gmailSendEmail(env, { to, subject, html }));
        if (r && (r.sent || r.staged)) { emailOk = true; res.delivery.email = { ok: true, outcome: r.staged ? 'staged' : 'sent', detail: null }; }
        else emailDetail = scrubPhones((r && (r.error || r.message)) || 'unexpected response (not sent)').slice(0, 200);
      } catch (e) { emailDetail = 'threw: ' + scrubPhones((e && e.message) || e).slice(0, 200); }
      if (!emailOk) { res.delivery.email = { ok: false, outcome: 'failed', detail: emailDetail }; fail('email_fallback', emailDetail); await tel(false, 'email_fallback_' + decision, emailDetail); }
    }
    delivered = smsOk || emailOk;
    res.delivered = delivered;
    if (!delivered) {
      fail('delivery', 'neither SMS nor email delivered the ' + decision + '; it will be retried next pass');
      await tel(false, 'delivery_failed_' + decision, 'key=' + ev.key + ' - no channel delivered; retrying next pass');
    } else if (decision === 'alert') {
      await tel(false, 'problem_alerted', 'key=' + ev.key + ' via=' + (smsOk ? 'sms' : 'email') + (res.fetch && res.fetch.snippet ? ' body=' + res.fetch.snippet : '') + (res.fetch && res.fetch.error ? ' err=' + res.fetch.error : ''));
    } else {
      await tel(true, 'recovered', 'door-code system healthy again via=' + (smsOk ? 'sms' : 'email'));
    }
  }

  // 5. persist state if it changed (verified write)
  const next = doorWdNextState(state, ev, decision, delivered === true, nowMs);
  res.state_after = next;
  const baseline = { active: !!state.active, sent: state.sent || {}, absent_since: state.absent_since || null };
  if (JSON.stringify(next) !== JSON.stringify(baseline) || parsed.corrupt || (__doorWdMem && __doorWdMem.dirty)) {
    try {
      await (io.writeState ? io.writeState(JSON.stringify(next)) : doorWdWriteState(env, JSON.stringify(next)));
      res.state_saved = true;
      __doorWdMem = { state: next, dirty: false };
    } catch (e) {
      res.state_saved = false;
      __doorWdMem = { state: next, dirty: true };
      const m = fail('state_write', e);
      await tel(false, 'state_write', m + ' (dedupe/recovery state not persisted; in-memory copy used until it recovers)');
    }
  }
  return res;
}

// The scheduler entry point for the watchdog (job `door_watchdog`). It NEVER throws, so it cannot break the
// other jobs. Every failure inside runDoorWatchdogPass is already
// logged + alerted there; the catch here is for a genuinely unexpected throw.
async function doorWatchdogCron(env) {
  try {
    const wd = await runDoorWatchdogPass(env);
    if (!wd.ok) console.error('door-watchdog: pass finished with errors:', JSON.stringify(wd.errors));
    return wd;
  } catch (e) {
    const m = String((e && e.message) || e).slice(0, 300);
    console.error('door-watchdog: pass threw:', m);
    try { await logTelemetry(env, { Source: 'worker', Job_Type: DOOR_WD_JOB, Skill_Or_Endpoint: 'scheduled/door-watchdog', Success: 'FALSE', Notes: ('unexpected throw: ' + m).slice(0, 480) }); } catch (e2) { console.error('door-watchdog: telemetry write failed after throw:', e2 && e2.message); }
    try { await alertAdminOnFailure(env, 'door_watchdog', m); } catch (e3) { console.error('door-watchdog: admin alert failed after throw:', e3 && e3.message); }
    return { ok: false, errors: ['pass threw: ' + m] };
  }
}
// GET /watchdog/door-system - read-only: live health evaluation + stored state. Sends nothing, writes nothing.
async function doorWatchdogStatus(env) {
  const nowMs = Date.now();
  const out = { ok: true, errors: [], url: DOOR_WD_URL };
  const fr = await fetchDoorHealth(fetch, {});
  let st = { active: false, sent: {}, absent_since: null };
  try {
    const cfg = await doorWdReadConfig(env);
    const p = doorWdParseState(cfg[DOOR_WD_STATE_KEY]);
    st = p.state;
    if (p.corrupt) out.errors.push('stored door_watchdog_state is not valid JSON');
  } catch (e) { out.errors.push('could not read state: ' + scrubPhones((e && e.message) || e).slice(0, 200)); }
  const ev = evaluateDoorHealth(fr, nowMs, { absentSinceMs: st.absent_since ? Date.parse(st.absent_since) : null });
  out.healthy = ev.healthy; out.reason_key = ev.key; out.reasons = ev.reasons;
  out.would_send = ev.healthy ? null : doorWdComposeAlert(ev.reasons);
  out.would_do = doorWdDecide(ev, st, nowMs);
  out.fetch = { status: fr.status == null ? null : fr.status, attempts: fr.attempts, error: fr.error || null, snippet: fr.snippet || null };
  out.state = doorWdPrune(st, nowMs);
  if (out.errors.length) out.ok = false;
  return json(out, out.ok ? 200 : 500);
}

// POST /watchdog/door-system/test - STAGING ONLY (404 elsewhere); reachable with HUB_TEST_TOKEN / an open
// ui-test window / WORKER_SECRET. Runs ONE real pass (same code as the cron) with injected inputs and
// returns what it did, including the exact SMS text. SMS defaults to the staging stub (sendSMSRaw only logs
// on staging) so the Twilio kill-switch does not hide the text; sim.sms='gated' goes through the real sendSMS
// gate. The only things it writes are the one door_watchdog_state Config row and Ops_Telemetry rows tagged [test].
// body: {reset, seed_state, corrupt_state, now(ISO), health(obj), sim_fetch:{throw,hang,status,body,fail_first},
//        timeout_ms, sim:{sms:'stub'|'gated'|'fail'|'throw', email:'fail', state_read_fail, state_write_fail,
//        telemetry_fail, no_admin_phone}}
async function doorWatchdogTest(env, url, body) {
  if (!isStaging(env, url)) return json({ error: 'Not found' }, 404);
  const b = body && typeof body === 'object' && !Array.isArray(body) ? body : {};
  const sim = b.sim && typeof b.sim === 'object' ? b.sim : {};
  try {
    if (b.reset) { await doorWdWriteState(env, ''); __doorWdMem = null; }
    if (b.seed_state && typeof b.seed_state === 'object') await doorWdWriteState(env, JSON.stringify(b.seed_state));
    if (b.corrupt_state) await doorWdWriteState(env, '{not json');
  } catch (e) { return json({ ok: false, error: 'test setup failed: ' + scrubPhones((e && e.message) || e).slice(0, 200) }, 500); }
  let nowMs = Date.now();
  if (b.now !== undefined) { nowMs = Date.parse(b.now); if (!isFinite(nowMs)) return json({ ok: false, error: 'now must be an ISO time' }, 400); }
  const io = {};
  if (b.health !== undefined) io.fetch = async () => new Response(JSON.stringify(b.health), { status: 200, headers: { 'Content-Type': 'application/json' } });
  if (b.sim_fetch && typeof b.sim_fetch === 'object') {
    const f = b.sim_fetch; let calls = 0;
    const fallback = io.fetch;
    io.fetch = async (u, init) => {
      calls++;
      if (f.fail_first && calls <= Number(f.fail_first)) throw new Error('simulated network failure');
      if (f.throw) throw new Error(String(f.throw));
      if (f.hang) return new Promise(() => {});
      if (f.status === undefined && f.body === undefined && fallback) return fallback(u, init);
      return new Response(f.body === undefined ? '' : (typeof f.body === 'string' ? f.body : JSON.stringify(f.body)), { status: f.status || 200 });
    };
  }
  if (sim.state_read_fail || sim.no_admin_phone) {
    io.readConfig = async () => {
      if (sim.state_read_fail) throw new Error('simulated Config read failure');
      const c = await doorWdReadConfig(env); c.admin_phone = ''; return c;
    };
  }
  if (sim.state_write_fail) io.writeState = async () => { throw new Error('simulated Config write failure'); };
  if (sim.telemetry_fail) io.logTelemetry = async () => { throw new Error('simulated Ops_Telemetry failure'); };
  const smsMode = String(sim.sms || 'stub');
  if (smsMode === 'gated') io.sendSms = (phone, text) => sendSMS(env, phone, text);
  else if (smsMode === 'fail') io.sendSms = async () => ({ error: 'simulated Twilio failure' });
  else if (smsMode === 'throw') io.sendSms = async () => { throw new Error('simulated SMS exception'); };
  else io.sendSms = async (phone, text) => { const r = await sendSMSRaw(env, phone, text); return r && r.staged ? { staged: true } : r; };
  if (sim.email === 'fail') io.sendEmail = async () => { throw new Error('simulated email failure'); };
  const res = await runDoorWatchdogPass(env, { nowMs, test: true, timeoutMs: Number(b.timeout_ms) > 0 ? Number(b.timeout_ms) : undefined, retryDelayMs: b.sim_fetch ? 50 : undefined, io });
  res.build_version = BUILD_VERSION;
  return json(res);
}

// ── Gated tenant/vendor messaging (TWILIO_SMS_BUILD_BRIEF_v1.0) ──────────────
// Message_Queue: every message that WOULD be sent gets a row here first, unconditionally —
// the durable review trail, not just a "while Global is off" log. Self-provisions like
// Ops_Telemetry (ensureTab once per isolate + ensureColumns on every write, FL rule 37).
const MSG_QUEUE_TAB = 'Message_Queue';
const MSG_QUEUE_COLS = ['ID','WO_ID','Message_Type','Recipient_Type','Recipient_Name','Recipient_Phone','Property_ID','Property_Address','Message_Body','Status','Delivered_To','Gate_Snapshot','Created_Date','Sent_Date','Twilio_Message_SID','Active','Send_After','Original_Body','Translated_To','Skip_If_Seen'];
const SMS_TOGGLE_TABS = ['Properties','Owners','Tenants','Vendors'];
let _msgQueueTabReady = false, _smsTogglesReady = false;

async function ensureSmsInfra(env) {
  if (!_msgQueueTabReady) { await ensureTab(env, MSG_QUEUE_TAB, MSG_QUEUE_COLS); _msgQueueTabReady = true; }
  await ensureColumns(env, MSG_QUEUE_TAB, MSG_QUEUE_COLS);
  if (!_smsTogglesReady) {
    await Promise.all(SMS_TOGGLE_TABS.map(t => ensureColumns(env, t, ['SMS_Enabled'])));
    // Sep 16 2026: SMS_OptOut already existed as a column on Tenants/Vendors but nothing in
    // this file actually checked it — a real gap for a bulk-broadcast feature that needs to
    // honor an explicit opt-out regardless of how urgent the message is. Wired into
    // smsGateDecision below; this just guarantees the column exists everywhere it's read.
    await Promise.all(['Tenants', 'Vendors'].map(t => ensureColumns(env, t, ['SMS_OptOut'])));
    _smsTogglesReady = true;
  }
}

