// ── 6. TOKENS ────────────────────────────────────────────────────────────────────────────────────
async function fuSha256(s) { const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(s))); return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join(''); }
