  return `${label || 'The cabin'} checkout ${c.date} 11 AM${c.guests ? ' (' + c.guests + ')' : ''}: ` + (c.covered ? 'cleaner ' + c.covered_by.join(', ') : (c.reason === 'brett' ? 'only "Brett cleaning" is scheduled' : 'NO cleaner on the cleaning calendar') + ' ' + span);
