      const effSrc = (sets.STR_GUARD_BOOKING_SOURCES != null ? sets.STR_GUARD_BOOKING_SOURCES : String(curCfg.STR_GUARD_BOOKING_SOURCES || '')).split(/[\s,]+/).filter(Boolean);
