    invalidateTabCache('Config');
    const cfg = await fetchConfig(env);
    for (const [k, v] of Object.entries(sets)) if (String(cfg[k] || '') !== v) throw strErr('config_not_landed', `${k} did not save (it reads back as "${cfg[k] || ''}")`);
