function inspB64Wrapped(s) { const t = _utf8B64url(s).replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (_utf8B64url(s).length % 4)) % 4); return t.replace(/(.{76})/g, '$1\r\n'); }
